\title{Effective anisotropic interaction potentials \\
for pairs of ultracold molecules shielded by a static electric field}
\author{Bijit Mukherjee}
\email{bijit.9791@gmail.com}
\affiliation{Faculty of Physics, University of Warsaw, Pasteura 5, 02-093 Warsaw, Poland}
