\subsection{Motivic Cartan formula}\label{ssect:Cartan}

Classically, the Cartan formula describes how the power operations interact with the cup product in mod-$p$ cohomology. Here, we describe the Cartan formula in motivic cohomology as an equivalence between maps from $H \Fb^{\Ab^1}_\ell \otimes H\Fb^{\Ab^1}_\ell$ to $H\Fb^{\Ab^1}_\ell$, and interpret it in terms of the spectrum-level coproduct of the motivic Steenrod algebra. The advantage of this spectrum-level description is that it makes it apparent that the motivic Cartan formula is stable under pullbacks. Throughout this subsection, we work with field $k$ and $\ell$ a prime invertible in $k$.



We denote by $\Ac$ the internal mapping object $\underline{\maps}(H\Fb^{\Ab^1}_\ell, H\Fb^{\Ab^1}_\ell)$ in $\SH_k$ whose bigraded homotopy groups form the motivic Steenrod algebra \cite[Theorem~1.1(2)]{HKO}. We consider it as a left $H\Fb^{\Ab^1}_\ell$-module with the module structure given by the target $H\Fb^{\Ab^1}_\ell$. Composing tensor product with the multiplication $\mu \colon H\Fb^{\Ab^1}_\ell \otimes H\Fb^{\Ab^1}_\ell \to H\Fb^{\Ab^1}_\ell$ defines the \textit{external product}
\begin{equation}\label{eq:externalProdEquiv}
\times \colon \Ac \otimes_{H\Fb^{\Ab^1}_\ell} \Ac \xto{\sim} \underline{\maps}(H\Fb^{\Ab^1}_\ell \otimes H\Fb^{\Ab^1}_\ell, H\Fb^{\Ab^1}_\ell)
\end{equation}
which is an equivalence by the results of \cite[\S 5.1]{HKO}. 

\begin{rem}\label{rem:sum} In fact, more is true. Let $\Psi$ be the map~\eqref{eq:psi} from the introduction, classifying admissible monomials in the dual mod-$\ell$ motivic Steenrod algebra
\[
\Psi: \bigoplus_{\alpha} \Tb^{\otimes q_{\alpha}} \otimes H\Fb^{\Ab^1}_{\ell}[p_{\alpha}-q_{\alpha}] \xrightarrow{\simeq} H\Fb^{\Ab^1}_{\ell} \otimes H\Fb^{\Ab^1}_{\ell};
\]
as stated there, this map is an equivalence when $\ell$ is invertible in $k$. Thus, the motivic spectrum $\Ac \otimes_{H\Fb^{\Ab^1}_\ell} \Ac$, and therefore the motivic spectrum $\underline{\maps}(H\Fb^{\Ab^1}_\ell \otimes H\Fb^{\Ab^1}_\ell, H\Fb^{\Ab^1}_\ell)$, can be written as a sum of shifts and twists of $H\Fb^{\Ab^1}_\ell$.
\end{rem}

\begin{rem}[Characterization of the external product]\label{rem:external}
If $x,y \in \Ac^{\star, \star}$ are $H\Fb^{\Ab^1}_\ell$-cohomology operations in $\SH_k$ (in other words, maps of the form $H\Fb_{\ell}^{\Ab^1} \rightarrow \Tb^{\otimes j} \otimes H\Fb_{\ell}^{\Ab^1}[i]$), then $x \times y$ induces the cohomology operation that is uniquely characterized by the property that the composition
\[
\left(H\Fb^{\Ab^1}_\ell \right)^{\star,\star}(X) \otimes \left(H\Fb^{\Ab^1}_\ell \right)^{\star,\star}(Y) \to
\left( H\Fb^{\Ab^1}_\ell \otimes H\Fb^{\Ab^1}_\ell \right)^{\star, \star}(X \times Y) \xto{x \times y} \left(H\Fb^{\Ab^1}_\ell \right)^{\star,\star}(X \times Y)
\]
sends $\alpha \otimes \beta$ to $x(\alpha) \times y(\beta)$ where $X, Y $ are smooth $k$-schemes. Above, the first map is the structure map given by the Day convolution of presheaves, on which the symmetric monoidal structure of $\SH_k$ is based upon. 
\end{rem}


Using this identification, we next enhance the coproduct $\psi^* \colon \Ac^{\star,\star} \to \Ac^{\star,\star} \otimes_{(H\Fb^{\Ab^1}_\ell)^{\star,\star}} \Ac^{\star,\star}$ that was defined in \cite[Lemma~11.6]{voevodsky:2003a} to a spectrum-level coproduct map. Subsequently, we will interpret the Cartan formula in terms of this map.

\begin{lem}\label{lem:coprod-psi}
The coproduct map $\psi^*$ is the map induced on the bigraded homotopy groups by precomposition by the multiplication map $\mu$:
\[
\mu^*\colon \underline{\maps}(H\Fb^{\Ab^1}_\ell, H\Fb^{\Ab^1}_\ell) \to \underline{\maps}(H\Fb^{\Ab^1}_\ell \otimes H\Fb^{\Ab^1}_\ell, H\Fb^{\Ab^1}_\ell) \xto{\times^{-1}, \simeq}  \Ac \otimes_{H\Fb^{\Ab^1}_\ell} \Ac.
\]
\end{lem}
\begin{proof}
Indeed, if $\mu^*(x) = \sum_i x'_i \times x''_i$, then $\sum_i x'_i \times x''_i \in \Ac^{\star\star} \otimes_{H\Fb_\ell^{\star\star}} \Ac^{\star\star}$ is the unique element satisfying the condition of \cite[Lemma~11.6]{voevodsky:2003a}. This then defines the spectrum-level map after the characterization of the external product in Remark~\ref{rem:external}.
\end{proof}

From now on, we will denote the coproduct on $\Ac$ by $\mu^*$ to highlight its relationship with the product structure on $H\Fb^{\Ab^1}_\ell$. Combining Lemma~\ref{lem:coprod-psi} with \cite[Lemma~11.6]{voevodsky:2003a}, motivic Cartan formula \cite[Proposition~9.7]{voevodsky:2003a} may be understood as the computation of the action of $\mu^*$ on the motivic power operations (natural on a motivic space $\Xfr$ over $k$) 
\[
\P^i \colon H^{\star}_{\Ab^1}(\Xfr; \Fb_{\ell}(\star)) \to H^{\star + 2i(p-1)}_{\Ab^1}(\Xfr; \Fb_{\ell}(\star + i(p-1)))
\]
and
\[
\B^i \colon H^{\star}_{\Ab^1}(\Xfr; \Fb_{\ell}(\star)) \to H^{\star + 2i(p-1) + 1}_{\Ab^1}(\Xfr; \Fb_{\ell}(\star + i(p-1));
\]
here  $\B^i = \beta \P^i$ and we refer the reader to \cite[Page 33]{voevodsky:2003a} or \cite[\S 2.4]{HKO} for details on the construction of these operations. We state the motivic Cartan formula here for the convenience of the reader.



\begin{thm}[Motivic Cartan formula]\label{thm:MotivicCartanSH}
Let $k$ be a field of characteristic $p \not = \ell$. Then, the following homotopies exist between maps to $\underline{\maps}(H\Fb^{\Ab^1}_\ell \otimes H\Fb^{\Ab^1}_\ell, H\Fb^{\Ab^1}_\ell) \in \SH_k$:
\begin{enumerate}
\item if $\ell \not = 2$, then
\begin{align*}
\mu^*(\P^i) \simeq& \sum_{r = 0}^i \P^r \times \P^{i-r} \\
\mu^*(\B^i) \simeq& \sum_{r = 0}^i \B^r \times \P^{i-r} + \P^r \times \B^{i-r} 
\end{align*}

\item if $\ell = 2$, then
\begin{align*}
\mu^*(\Sq^{2i}) \simeq& \sum_{r = 0}^i \Sq^{2r} \times \Sq^{2i-2r} + \tau \sum_{s = 0}^{i-1} \Sq^{2s + 1} \times \Sq^{2i-2s - 1} \\
\mu^*(\Sq^{2i  + 1}) \simeq& \sum_{r = 0}^i (\Sq^{2r + 1} \times \Sq^{2i-2r} + \Sq^{2r} \times \Sq^{2i-2r+1}) \\
& + \rho \sum_{s=0}^{i-1} \Sq^{2s+1} \times \Sq^{2i-2s-1},
\end{align*}
where $\tau$ is the non-zero element of $H_{\Ab^1}^0(k; \Fb_2(1)) = \mu_2(k)$, and $\rho$ is the image of $-1$ in $H_{\Ab^1}^{1}(k; \Fb_2(1)) = k^\times / (k^\times)^2$.
\end{enumerate}
\end{thm}



\begin{rem}[Spectrum-level Cartan formula]\label{rem:spectrumCartan} We further clarify the formulas of Theorem~\ref{thm:MotivicCartanSH}. Let $x: H\Fb_{\ell}^{\Ab^1} \rightarrow \Tb^{\otimes j} \otimes H\Fb_{\ell}^{\Ab^1}[i]$ be one of the power operations $\P^i, B^i$ or $\Sq^i$. Then the theorem asserts that we have the following commutative diagram in $\SH_k$:
\begin{equation}\label{eq:spectrumCartan}
\begin{tikzcd}
 H\Fb_{\ell}^{\Ab^1} \ar{r}{x} & \Tb^{\otimes n} \otimes H\Fb_{\ell}^{\Ab^1}[m]\\
  H\Fb_{\ell}^{\Ab^1} \otimes  H\Fb_{\ell}^{\Ab^1} \ar{u}{\mu} \ar{r}{\Psi^{-1},\simeq} & \bigoplus_{\alpha} \Tb^{\otimes q_{\alpha}} \otimes H\Fb^{\Ab^1}_{\ell}[p_{\alpha}-q_{\alpha}] \ar[swap]{u}{\sum x_n \otimes x_m},\\
\end{tikzcd}
\end{equation}
where the sum of the right vertical map classifies the expression on right hand side of the formulas in Theorem~\ref{thm:MotivicCartanSH}. In other words, these are lifts of the motivic Cartan formulas to a spectrum level-statement. That we can do this ultimately rests on the very deep fact that $\Psi$ is an equivalence. 
\end{rem}



\section{Mod-$p$ motivic power operations of $\Fb_p$-schemes}\label{sect:Pops}


We now construct the motivic power operations acting on the mod-$p$ motivic cohomology of $\Fb_p$-schemes. We begin by constructing the operations on smooth $\Fb_p$-varieties in Section~\ref{subsect:smoothPops}.

%\textcolor{red}{, after which we extend them to all derived $\Fb_p$-schemes in Section~\ref{subsect:allPops} using the left Kan extension procedures described in Appendix~\ref{app:procdhLKE}.}

\subsection{A motivic Nizio{\l} theorem}\label{subsect:smoothPops}

To construct the motivic mod-$p$ power operations on smooth $\Fb_p$-varieties, we study motivic cohomology over $\Oc = \Zb_p[p^{1/p^\infty}]$, the infinitely ramified extension of $\Zb_p$ obtained by adjoining all the $p$th power roots of $p$. The idea is to use Theorem~\ref{thm:DetroitPurity} to show that the motivic cohomology of smooth $\Oc$-schemes is completely determined by the generic fibre. Our argument is similar to the one that used in \cite[Section~3]{AMM:2022} in order to obtain a similar result for algebraic $K$-theory. In turn, \cite{AMM:2022} was inspired by a phenomenon first observed by Nizio{\l}  in her proof of the crystalline comparison theorems \cite{niziol-crys}.

We denote by 
\[
j \colon \Spec(\Kb) \hook \Spec(\Oc)
\]
the open embedding obtained by inverting $p$. In particular $\Kb = \Oc[p^{-1}]$. The precise result we are going to prove is the following.

\begin{thm}\label{thm:Detroit}
Let $E$ be an absolute oriented motivic spectrum with absolute purity for pairs $(X, X_p)$, where $X$ is smooth over a discrete valuation ring $A$ of mixed characteristic $(0,p)$, and $X_p \hook X$ is the special fibre. Then, pulling back along the natural transformation $j_! j^* \to \Id$ induces an equivalence for all $m \geq 1$:
\[
\maps_{\SH_{\Oc}}(\Xfr, E/p^m) \rightarrow \maps_{\SH_{\Oc}}(j_! j^*(\Xfr), E/p^m).
\]
for all $\Xfr \in \SH_{\Oc}$. In particular, the unit map $E \to j_* E$ induces equivalences
\[
E/p^m \xrightarrow{\simeq} j_* E/p^m \qquad \forall m \geq 1,
\]
and
\[
(E)^\comp_p \xrightarrow{\simeq} ( j_* E)^\comp_p.
\]
\end{thm}

We will postpone this proof until after the key Lemma~\ref{lem:root-canal}. The following Corollary is the key point of our construction of motivic power operations. 

\begin{cor}\label{cor:main}
The pullback along the natural transformation $j_! j^* \to \Id$ induces an equivalence 
\[
\maps_{\SH_{\Oc}}(\Xfr, H\Fb_p^{\Ab^1}) \rightarrow \maps_{\SH_{\Oc}}(j_! j^*(\Xfr), H\Fb_p^{\Ab^1}).
\]
In particular, the unit map $H\Fb^{\Ab^1}_p \to j_* H\Fb^{\Ab^1}_p$ is an equivalence.
\end{cor}

\begin{proof} Motivic cohomology has the desired absolute purity by Theorem~\ref{thm:abs-pur}. The ``in particular'' part is a consequence of the first claim because it implies that mapping to the unit map induces an equivalence for all $\Xfr \in \SH_{\Oc}$.
\end{proof}


