\begin{cor}\label{cor:ModPSteenrod}%ALL YOU NEED 2 COMPOOT
Let $S$ be a smooth $\Fb_p$-scheme. Then the endomorphisms $\P^i$ and $B^i$ of Theorem~\ref{thm:ModPSteenrodSpectrumLevel} induce mod-$p$ motivic power operations 
\[
\P^i \colon H^{\star}_{\Ab^1}(\Xfr; \Fb_p(\star)) \to H^{\star + 2i(p-1)}_{\Ab^1}(\Xfr; \Fb_p(\star + i(p-1)))
\]
and
\[
B^i \colon H^{\star}_{\Ab^1}(\Xfr; \Fb_p(\star)) \to H^{\star + 2i(p-1) + 1}_{\Ab^1}(\Xfr; \Fb_p(\star + i(p-1))
\]
acting on the $\Ab^1$-local motivic cohomology of motivic spaces $\Xfr \in \Pc_{\Nis,\Ab^1}(\Sm_S)$. We have that $\P^0 = \Id$ and $\B^i = \beta \P^i$. Moreover, these operations satisfy the expected properties, namely:
\begin{enumerate}
\item the operations $\P^i$ and  $B^i$ commute with pullbacks;
\item the motivic Adem relations hold;
\item the motivic Cartan formulas hold;
\item if $x \in H_{\Ab^1}^{2i}(\Xfr; \Fb_p(i))$, then $\P^i(x) = x^p$;
\item if $y \in H^{j}_{\Ab^1}(\Xfr; \Fb_p(k))$ is such that $j-k<i$ and $k \leq i$, then $\P^i(y) = 0$;
\item the Bockstein $\beta$ is a graded derivation with respect to the first grading.
\end{enumerate}
\end{cor}
\begin{proof}
The first four claims are immediate from Theorem~\ref{thm:ModPSteenrodSpectrumLevel}. Claim 5 follows from claim 4 (see \cite[Lemma~9.9]{voevodsky:2003a}). Claim 6 is formal.
\end{proof}

Furthermore, the following result is proven similarly to \cite[Proposition~11.4]{voevodsky:2003a} which only uses the action of motivic power operations on the mod-$p$ motivic cohomology of products of $\rm{B}\mu_p$, which in turn may be computed using Corollary~\ref{cor:ModPSteenrod}.

\begin{cor}\label{cor:admiss}
Admissible monomials are $H_{\Ab^1}^{\star}(\Fb_p; \Fb_p(\star))$-linearly independent in 
\[
\Ext_{\SH_{\Fb_p}}^{\star,\star}(H\Fb^{\Ab^1}_p,H\Fb^{\Ab^1}_p).
\] In other words, there is an inclusion 
\[
\Ac_{\Fb_p}^{\star,\star} \hook \Ext_{\SH_{\Fb_p}}^{\star,\star}(H\Fb^{\Ab^1}_p,H\Fb^{\Ab^1}_p),
\]
where $\Ac_{\Fb_p}^{\star,\star}$ is the $H\Fb_p^{\star,\star}$-algebra generated by the Bockstein $\beta$ and the motivic power operations $\P^i$, modulo the motivic Adem relations.
\end{cor}


\subsection{Power operations on $\Fb_p$-schemes}\label{subsect:allPops} We now construct power operations on the $\Ab^1$-invariant motivic cohomology of (quasicompact, quasiseprated) $\Fb_p$-schemes. Given $X \in \Sch_{\Fb_p}$ with structure map $\pi: X \rightarrow \Spec(\Fb_p)$, we have that $H\Zb^{\Ab^1}_X \simeq \pi^*H\Zb^{\Ab^1}_{\Fb_p}$ (as $\Eb_{\infty}$-algebras in $\SH_{\Fb_p}$) thanks to \cite[Theorem 8.19]{bem}.  Therefore we have a maps of $\Eb_1$-algebras (and $\Eb_{\infty}$-coalgebras):
\[
\mathrm{end}_{\SH_{\Fb_p}}(H\Fb_p^{\Ab^1}) \rightarrow \mathrm{end}_{\SH_{X}}(H\Fb_p^{\Ab^1}).
\]
On the level of homotopy groups, we then obtain a map (in the notation of Corollary~\ref{cor:admiss}
\[
\Ac_{\Fb_p}^{\star,\star} \rightarrow \Ext_{\SH_{\Fb_p}}^{\star,\star}(H\Fb^{\Ab^1}_p,H\Fb^{\Ab^1}_p) \rightarrow \Ext_{\SH_{X}}^{\star,\star}(H\Fb^{\Ab^1}_p,H\Fb^{\Ab^1}_p);
\]
which we base change along the $\Ab^1$-invariant motivic cohomology ring of $X$ to get a map
\[
\Ac_{X}^{\star,\star}:=\Ac_{\Fb_p}^{\star,\star} \otimes_{H_{\Ab^1}^{\star}(\Fb_p; \Fb_p(\star))} H_{\Ab^1}^{\star}(X; \Fb_p(\star)) \rightarrow \Ext_{\SH_{X}}^{\star,\star}(H\Fb^{\Ab^1}_p,H\Fb^{\Ab^1}_p).
\]
In this way, $\Ac_{X}^{\star,\star}$ acts naturally on the $\Ab^1$-invariant motivic cohomology of smooth $X$-schemes (more generally, on motivic spaces over $X$).

\begin{cor}\label{cor:extension-a1}
Let $X \in \Sch_{\Fb_p}$. There exist reduced mod-$p$ power operation endomorphisms acting on $H\Fb^{\Ab^1}_p \in \SH_X$ that satisfy all the properties stated in Theorem~\ref{thm:ModPSteenrodSpectrumLevel}.
\end{cor}

\begin{proof}
Indeed, the first properties follow from functoriality and symmetric monoidality of $\pi^*$, respectively. The third property follows from Theorem~\ref{thm:ModPSteenrodSpectrumLevel}(3) using the fact $\Zb(j)^{\Ab^1}$ on $\Sm_X$ is calculated via pullback of $\Ab^1$-invariant cdh-sheaves using  \cite[Theorem 8.1]{bem} again. 
\end{proof}


In Remark~\ref{rem:nona1-inv} we discuss the extension of the mod-$p$ power operations to non-$\Ab^1$-invariant motivic cohomology. 

