%\end{rem}


\begin{ex}[Non liftable cycles on $\mathrm{B} \mu_p$] \label{ex:CohOfBmup}
Let $k$ be a characteristic $p > 0$ field and let $\mathrm{B} \mu_p$ be the classifying stack of $\mu_p$-torsors in the fppf-topology on $\Sm_{k}$, and $\Xfr \in \SH_k$. Recall that \cite[Theorem 6.10]{voevodsky:2003a} records a calculation mod-$p$ motivic cohomology of $\Xfr \times \mathrm{B}\mu_p$ at any characteristic. In our case the answer is as follows:
\[
H^{\star}_{\mot}(\Xfr \times \mathrm{B} \mu_p; \Fb_p(\star)) \cong H_{\mot}^{\star}(\Xfr; \Fb_p(\star))[[u, v]]/(u^2 = 0, \beta(u)= v) \qquad |u| = (1,1), |v| = (2,1).
\]
Here, $\beta$ is the Bockstein operator. We remark that $v$ is the pullback of the first Chern class of the universal line bundle along the map $\mathrm{B}\mu_p \to \mathrm{B}\Gb_m$ and $u$ is the unique class such that $\beta(u) = v$.

Let $\Xfr = \mathrm{B} \mu_p$ and let $u_i$ and $v_i$ be element in its motivic cohomology given by the pullbacks of $u$ and $v$ from the respective factors. By the basic properties of motivic cohomology operations Theorem~\ref{cor:ModPSteenrod} (in particular, Lemmas~\ref{lem:milnor} and~\ref{lem:Q_n-bmup}), we see that
\begin{align*}
\Q_1(u_1 \cdot u_2) &= (\P^1 \beta - \beta \P^1)(u_1 \cdot u_2) \\
&= v_1^p \cdot u_2 - u_1 \cdot v_2^p \\
&\not = 0.
\end{align*}
Thus, $u_1 \cdot u_2$ does not lift to an $\MGL$-cohomology class.

We note that the calculation \cite[Proposition~6.4]{AHI} shows that the answer for syntomic cohomology (an oriented theory with elementary blowup excision, the $\Pb^1$-bundle formula and the additive formal group law) is similar: for any scheme/stack $\Xfr$ we have
\begin{equation}\label{eq:syn}
H^{\star}_{\syn}(\Xfr \times \mathrm{B} \mu_p; \Fb_p(\star)) \cong H_{\syn}^{\star}(\Xfr; \Fb_p(\star))[[u, v]]/(u^2 = 0, \beta(u)= v) \qquad |u| = (1,1), |v| = (2,1).
\end{equation}
We will use this calculation in what follows.
