We now apply Theorem~\ref{thm:RRInMS} to the total power operations. Let $S = \Fb_p$ and consider the following object in $\MS_{\Fb_p}$
\[
H\Fb_p^{\mathrm{tot}} := \prod_{n \in \Zb} (\Tb^{\otimes n(p-1)} \otimes H\Fb_p) \oplus (\Tb^{\otimes n(p-1)} \otimes H\Fb_p[1]).
\]
This product is in fact a direct sum by \cite[Lemma~5.2]{HKO}. Thus, we can use the direct sum decomposition on the source to define a symmetric bilinear map $\mu^\tot \colon H\Fb_p^{\mathrm{tot}} \otimes H\Fb_p^{\mathrm{tot}} \to H\Fb_p^{\mathrm{tot}}$ degree-wisely by positing that
\[
(\Tb^{\otimes n(p-1)} \otimes H\Fb_p) \otimes (\Tb^{\otimes m(p-1)} \otimes H\Fb_p) \to \Tb^{\otimes (m+n)(p-1)} \otimes H\Fb_p
\]
and
\[
(\Tb^{\otimes n(p-1)} \otimes H\Fb_p) \otimes (\Tb^{\otimes m(p-1)} \otimes H\Fb_p [1]) \to \Tb^{\otimes (m+n)(p-1)} \otimes H\Fb_p[1]
\]
coincide with the usual multiplication on $H\Fb_p$, and that $\mu^\tot$ is null-homotopic on summands of form
\[
(\Tb^{\otimes n(p-1)} \otimes H\Fb_p[1]) \otimes (\Tb^{\otimes m(p-1)} \otimes H\Fb_p [1]). 
\]
The bilinear pairing $\mu^\tot$ equips $H\Fb_p^{\mathrm{tot}}$ with structure of a commutative algebra in ${\h}\SH_S$.


\begin{cons} The \textit{total power operation} is the map in $\SH_{\Fb_p}$
\begin{equation}\label{eq:total-p}
\P: H\Fb_p \rightarrow H\Fb_p^{\mathrm{tot}}
\end{equation}
given degree-wise by
\[
\P^n: H\Fb_p \rightarrow \Tb^{\otimes n(p-1)} \otimes H\Fb_p
\]
and
\[
\B^n: H\Fb_p \rightarrow \Tb^{\otimes n(p-1)} \otimes H\Fb_p[1].
\]
By the Cartan formula (Theorem~\ref{cor:ModPSteenrod}(2)), $P$ is a map in $\CAlg(\h\SH_{\Fb_p})$.


Applying \'etale sheafification on Eq.~\eqref{eq:total-p} in $\MS_{\Fb_p}$ yields a map
\begin{equation}\label{eq:total-p-syn}
\P: H\Fb_p^{\syn} \rightarrow (H\Fb^{\syn}_p)^{\mathrm{tot}}
\end{equation}
of commutative algebras in $\h\MS_{\Fb_p}$. We call this the \emph{total syntomic power operation}.
\end{cons}

Now let $S$ be an $\Fb_p$-scheme. Either by pullback in $\SH$ or by pullback in $\MS$ and \'etale sheafification we obtain the total power operations in
\[
\P:(H\Fb_p^{\Ab^1})_S \rightarrow (H\Fb_p^{\Ab^1})_S^\mathrm{tot},
\]
or
\[
\P: (H\Fb_p^{\syn})_S \rightarrow (H\Fb^{\syn}_p)_S^{\mathrm{tot}}
\]

\begin{cor} \label{cor:total-power-ops} Let $X \rightarrow Y$ be projective, quasi-smooth morphism over $S$. the formula
\[
\P(f_!(x)) = f_!(\Td_P(\Lbf_{X/Y}) \cdot \P(x)).
\]
holds in both mod-$p$ syntomic and $\Ab^1$-motivic cohomology. 
\end{cor}

\begin{rem}\label{rem:todd-vs-wu} Let $\Ec$ be a vector bundle on $\Sm_S^?$. Following definitions from topology, the \emph{$j$-th Stiefel-Whtiney class} of $\Ec$ is the class in motivic or syntomic cohomology given by
\[
w_j(\Ec) := t(\Ec)^{-1}(\P^j(t(\Ec)).
\]
The \emph{total Stiefel-Whitney class} of $\Ec$ is then defined by
\[
w(\Ec) := \sum_{j \geq 0} w_j(\Ec).
\]
By taking alternating sums, these classes are extended to any perfect complex on $X$. Applying Lemma~\ref{lem:ThomClassFormula} then the formula from Corollary~\ref{cor:total-power-ops} reads as
\begin{equation}\label{eq:sw}
\P(f_!(x)) = f_!(w(\Lbf_{X/Y}) \cdot \P(x)).
\end{equation}
\end{rem}



