\end{remark}


\subsubsection{Portfolio theory}

In the case of portfolio theory, more results may be obtained. First, if we consider variance as the risk measure, there is a special case that allows us to obtain more analytical results, as discussed in  \cite{colini2018variance}.
    Consider a portfolio $X_1+\dots+X_m$, where $\sigma_i^2$ is the variance of $X_i$ and $\rho_{i,j}$ is the correlation between $X_i$ and $X_j$. Then BShap yields that
$
        \text{BS}_i^R = \sigma_i^2 +  \sum_{j \neq i}  \rho_{i,j} \sigma_i \sigma_j.
$


For more general cases, we consider the principle of diversification, which suggests that owning a variety of financial assets is less risky than owning only one. This is reflected in the following Sub-additivity property for risk measures \citep{artzner1999coherent,rockafellar2002conditional}. 

% \begin{example}
%     In portfolio theory, there is a special case that allows us to obtain more analytical results \cite{colini2018variance}.
%     Consider a portfolio $X_1+\dots+X_m$, where $\sigma_i^2$ is the variance of $X_i$ and $\rho_{i,j}$ is the correlation between $X_i$ and $X_j$. Then BShap yields that
% $
%         \text{BS}_i^R = \sigma_i^2 +  \sum_{j \neq i}  \rho_{i,j} \sigma_i \sigma_j.
% $
% \end{example}

\begin{definition}[Sub-additivity]
    By the diversification principle, when two portfolios are combined, the risk cannot be greater than when they are combined separately. We say $\varrho$ preserves Sub-additivity if $Y_1, Y_2 \in \mathcal{L}$, 
$
    \varrho(Y_1+Y_2) \leq \varrho(Y_1) + \varrho(Y_2). 
$
\end{definition}

Therefore, we should expect to observe the impact of diversification when we calculate risk attributions. In the following proposition, we demonstrate how BShap preserves sub-additivity with proof in Appendix~\ref{sec:proof}. 

\begin{proposition} \label{prop:Sh_sub_addivitiy}
    For $f(\*X) = X_1 + \dots + X_m$, if $\varrho$ preserves Sub-additivity, then
    $\text{BS}^R_i \leq \varrho(X_i)$. As a result of sub-additivity, BShap (RAM) could reflect the principle of diversification, which reduces each individual risk attribution when assets are added to the portfolio. 
\end{proposition}


\subsection{Fundamental axioms}

We present fundamental axioms for RAMs that are analogous to Section~\ref{sec:BAM} and are expected to hold in general.  A similar idea can be applied to SRAMs. \textbf{We mainly use RAMs for demonstration of analytical examples and SRAMs in practice.} 

\begin{definition}
\textbf{Fundamental axioms for RAMs}. 

$\bullet$ \textbf{Completeness (RAM):} 
    $\sum_{i=1}^m A_i = \varrho(f(\*X)) - \varrho(f(\*X'))$.

$\bullet$ \textbf{Dummy (RAM):}
    If $\frac{\partial f(\*x)}{\partial x_i} = 0$, then $A_i = 0$.

$\bullet$ \textbf{Symmetry (RAM):}
    Define $\*x^*$ by swapping $x_i$ and $x_j$ and the probability density function of $f(\*X)$ by $g(\*x)$.  
    Suppose $g(\*x) = g(\*x^*)$, $\forall \*x$. Then if $x_i' = x_j'$, then $A_i = A_j$.
    % Suppose the distribution of $f(\*X)$ is symmetric about $X_i$ and $X_j$, then $A_i = A_j$.
\end{definition}


\begin{theorem} \label{thm:BShap_RAM_basic_axioms}
    BShap (RAM) preserves Completeness (RAM), Dummy (RAM), and Symmetry (RAM). 
\end{theorem}





\section{Comparisons of BAMs and RAMs}

RAMs and BAMs differ primarily in that the former focuses on the mean attributions whereas the latter focuses on the risk attributions. Consider the following portfolio $f(X_1,X_2) = X_1 + X_2$, in which $X_1$ follows a normal distribution with $\mathcal{N}(\mu,\sigma^2)$ and $X_2$ is a constant $r$, which can be considered coming from the risk-free interest rate. Assume that the standard deviation is used to measure risk. By RAMs, we expect that there is no risk associated with $X_2$ and therefore $A_2=0$. By BAMs, there is an attribution from $X_2$ with $\mathcal{A}_2 = r$. The focus of BAMs and RAMs, therefore, differs significantly. Following this, we illustrate some differences between BAMs and RAMs in terms of axioms. 


\subsection{Linearity}


As for BAMs, the Linearity (BAMs) implies the Linearity (SH). This is no longer true for RAMs due to the nonlinearity of risk measures. Consider an example 
$        f(X_1,X_2) = X_1, \ g(X_1,X_2) = X_2
$
    where the variance of $X_1$ and $X_2$ are $\sigma_1^2$ and $\sigma_2^2$ and the correlation between them is $\rho$. Suppose $\varrho(\cdot) = \text{STD}(\cdot)$. Then by Completeness (RAM) and Dummy (RAM), we have
    \begin{align*}
        A_1(f) = \sigma_1, A_2(f) = 0, A_1(g) = 0, A_2(g) = \sigma_2.
    \end{align*}
    If Linearity (BAM) holds, then we have
$
        A_i(f+g) = A_i(f) + A_i(g).
$
    However, if this were true,
    \begin{align*}
        A_1(f+g) + A_2(f+g) 
        = A_1(f) + A_1(g) + A_2(f) + A_2(g) = \sigma_1 + \sigma_2 \neq \sqrt{\sigma_1^2 + \sigma_2^2 + 2 \rho \sigma_1 \sigma_2} = \varrho(f+g),
    \end{align*}
    which is in contrast to the Completeness (RAM). \textbf{Therefore, Linearity is incompatible with Completeness (RAM) and Dummy (RAM).} Incompatible means that these axioms cannot be held simultaneously. \textbf{In view of this, there is no corresponding Linearity axiom for RAMs as there is for BAMs.}

While Linearity is not required for RAMs, BShap (RAM) does require Linearity (SH) for characteristic functions. It should be noted that this may not be a strict requirement for RAMs. As for Example~\ref{eg:eg_var}, by Euler's decomposition \cite{meucci2005risk}, we can decompose the STD of a portfolio
\begin{align*}
    \text{STD}(f(X_1,X_2)) = \frac{ \sigma_1^2 +  \rho \sigma_1 \sigma_2}{\sqrt{\sigma_1^2+\sigma_2^2+2\rho \sigma_1 \sigma_2}} 
    + \frac{ \sigma_2^2 +  \rho \sigma_1 \sigma_2}{\sqrt{\sigma_1^2+\sigma_2^2+2\rho \sigma_1 \sigma_2}}.
\end{align*}
It can be easily observed that Completeness (RAM), Dummy (RAM), and Symmetry (RAM) are preserved by this formula. Consequently, Euler's decomposition also provides a fair allocation of risk. 
In terms of characteristic functions, it can be rewritten as
\begin{align*}
    \text{STD}(f(X_1,X_2)) = \frac{v_R^2(\{1,2\})+v_R^2(\{1\})-v_R^2(\{2\})}{2v_R(\{1,2\})} 
    + \frac{v_R^2(\{1,2\})+v_R^2(\{2\})-v_R^2(\{1\})}{2v_R(\{1,2\})}.
\end{align*}
It is clear that this formula is not linear in the sense of Linearity (SH). Although it's still easy to interpret a linear function by Euler's decomposition, for a general complex $f$, a nonlinear interpretation might be too complicated. \textbf{Therefore, Linearity (SH) for BShap mainly helps make the explanation formula more transparent in the context of RAMs.} 

\begin{remark}
    Euler's decomposition is only applicable to homogeneous functions of degree one. Thus, it cannot be directly generalized to a general complex nonlinear function $f$. 
\end{remark}

\subsection{Symmetry}

The concept of symmetry is generally concerned with the fairness of allocation. Two features that behave the same should receive the same attribution. Different from BAM, symmetry (RAM) further requires that $X_i$ and $X_j$ are also symmetric in $\*X$ since the distribution of features matters. By directly applying BShap (BAM), the symmetry of features may be overlooked, resulting in unfair allocations, as illustrated in the following example. 

\begin{example}

    As a simple example, consider a portfolio $Y_t = f(X_{1,t},X_{2,t}) = X_{1,t} + X_{2,t}$ as the daily return of the portfolio with two assets. Suppose we use the Value-at-Risk (VaR) as the risk measure that $\widehat{\varrho}(\cdot) = \widehat{\text{VaR}}_{\alpha}(\cdot)$, and we find $y_{\tau} = -\widehat{\text{VaR}}_{\alpha} (Y_t)$ at date $\tau$. Suppose we apply BShap (BAM) to $y_{\tau}$ and have $\text{BS}_i(v_B) = x_{i,\tau}$. This calculation focus only on $x_{1,\tau}$ and $x_{2,\tau}$ and neglects the distribution of $X_{1,t}$ and $X_{2,t}$. Suppose $\{x_{1,t}+x_{2,t}\}_{i=1}^n$ is symmetric about $\{x_{1,t}\}_{i=1}^n$ and $\{x_{2,t}\}_{i=1}^n$. By Symmetry (RAM), we would expect to have $A_1 = A_2$. It may be the case, however, that $x_{1,\tau}$ contributes most to $y_{\tau}$ such that $\text{BS}_1(v_B)$ is much greater than $\text{BS}_2(v_B)$ when $x_{1,\tau}$ is much less than $x_{2,\tau}$. Thus, the Symmetry (RAM) is violated and the explanation is unfair. 
\end{example}




\subsection{Monotonicity axioms}

There have been extensive studies of domain knowledge-inspired monotonicity on attribution methods, \citep{friedman1999three,lundstrom2023four,chen2023address,chen2022monotonic,young1985producer}. The monotonicity axiom enables us to ensure the sign of attributions and to compare the relative importance of features. It is often possible to infer monotonicity from the derivatives of functions for BAMs. Therefore, the following monotonicity axioms for BAMs are often considered \citep{lundstrom2023four}. 


\begin{definition}\label{def:mono_axiom_BAM} 
\textbf{Monotonic axioms for BAMs}. 
\begin{itemize}
\item \textbf{Individual Monotonicity (BAM):}
    Suppose $\frac{\partial f(\*x)}{\partial x_{i}} \geq 0$, then
$
        \mathcal{A}_{i} \geq 0.
$
\item \textbf{Pairwise Monotonicity (BAM):}
If $ \frac{\partial f(\*x)}{\partial x_i} \leq \frac{\partial f(\*x)}{\partial x_j}$ and $x_i \leq x_j$, then 
$
\mathcal{A}_i \leq \mathcal{A}_j.
$
\item \textbf{Symmetric Monotonicity (BAM):}
    If $\frac{\partial f(\*x)}{\partial x_i} \leq \frac{\partial g(\*x)}{\partial x_j}$ and $x_i \leq x_j$, then
$
\mathcal{A}_i(f) \leq \mathcal{A}_j(g).
$
\end{itemize}
\end{definition}        

\begin{example} \label{eg:mono_BAMs}
We provide the following examples in credit scoring to demonstrate monotonicity.
\begin{itemize}
\item The probability of default increases with the number of past-due payments. Due to this, the corresponding attribution should also be positive. 
\item Suppose we use $x_i$ and $x_j$ to count the number of past dues less than and more than three months, then for each additional past due, $x_j$ should have a greater impact on the probability of default. Accordingly, if $x_j \geq x_i$, we should expect a larger attribution for $x_j$. 
\item Suppose that we compare two different credit scoring models for $x_i$ and $x_j$, we expect to compare their attributions if there exists clear monotonicity. 
\end{itemize}
\end{example}

As demonstrated in the following example, we can also expect some monotonicity for RAMs. 

\begin{example}
Consider nonlinear factor models 
$
    Y_t^1 = f(X_{1,t},X_{2,t}), Y_t^2 = g(X_{1,t},X_{2,t}),
$
where at $t$-th day, $Y_t^1$ and $Y_t^2$ are daily returns of Google and Capital One, and $X_{1,t}$ and $X_{2,t}$ are daily returns of the entire Finance sector and Technology sector. 
\begin{itemize}
\item Google is expected to have positive exposure to risk of the Technology sector. 
\item Google is more exposed to the risk of the Technology factor than to the Financial factor.
\item Google has a larger exposure to the risk of the Technology sector than Capital One. 
\end{itemize}
\end{example}

For BAMs, monotonicity is studied from the standpoint of the derivative of the function, e.g., $\frac{\partial f}{\partial x_i}(\*x) \geq 0$. This condition, however, may not be directly applicable to RAM content. 
Consider a simple example of $f(X_1) = X_1$,
where $X_1$ follows the standard normal distribution. While $f$ and $-f$ has the opposite signs, the distributions of $f(X_1)$ and $-f(X_1)$ are the same and we have $\varrho(f) = \varrho(-f)$. Therefore, Monotonicity on the function $f$ is irrelevant. For RAMs, we instead focus on characteristic functions as in Section~\ref{sec:Shap}. However, as demonstrated below, in contrast to BAMs \citep{lundstrom2023four}, Symmetryic Monotonicity (SH) for RAMs when $i \neq j$ is not expected. 

% \begin{proposition} \label{prop:SM_fail}
%     Symmetric Monotonicity (RAM) for $i \neq j$ is incompatible with Dummy (RAM) and Completeness (RAM). Incompatible means that these axioms cannot be held simultaneously.  
% \end{proposition}

\begin{example} \label{eg:SM_incompatible}
Symmetric Monotonicity (RAM) for $i \neq j$ is incompatible with Dummy (RAM) and Completeness (RAM). 
% Incompatible means that these axioms cannot be held simultaneously.  
Consider 
\begin{align*}
    f(X_1,X_2) = X_1 + X_2, \ g(X_1,X_2) = X_2, \ h(X_1,X_2) = X_1. 
\end{align*}
 By Dummy (RAM) and Completeness (RAM), we have $A_2(g) = \varrho(X_2)$ and $A_1(h) = \varrho(X_1)$. By Symmetric Monotonicity (RAM) for $i \neq j$, we  have $A_1(f)=A_2(g)$ and $A_2(f) = A_1(h)$. Then we no longer have Completeness (RAM). The relative importance of risk attributions for different features in different models cannot, therefore, be directly compared. 

 For a specific example of BShap (RAM), suppose $\text{Var}(X_1) = \text{Var}(X_2)= \sigma^2$ and $\rho>0$. By Symmetry (RAM), we know that to $f$, $X_1$ and $X_2$ bring the same amount of risk. Furthermore, by Theorem~\ref{thm:BShap_mono_global}, $X_2$ brings more risk to $f$ than to $g$. However, we cannot conclude that $X_1$ brings the same amount of risk to $f$ as the $X_2$ to $g$ even though they have the same distribution. By BShap (RAM),  we have
    \begin{align*}
        \textbf{BS}^R(f) = \left[ \begin{matrix} \sigma^2 + \rho \sigma^2 \\
        \sigma^2 + \rho \sigma^2 \end{matrix} \right], \
        \textbf{BS}^R(g) = \left[ \begin{matrix} 0 \\ \sigma^2 \end{matrix} \right].
    \end{align*}

\end{example}










\section{Empirical examples}
In this section, we demonstrate how BShap allocates risk attributions using a variety of examples. To the best of our knowledge, no other methods have been applied to allocate risk for general models in the past. 

