\begin{proof}[Proof of Theorem~\ref{thm:BShap_RAM_basic_axioms}]
    The Completeness (RAM) directly follows from the Completeness (SH) with the choice of characteristic function $v_R$. Under assumptions of Dummy (RAM) and Symmetry (RAM), the assumptions of the characteristic functions for Dummy (SH) and Symmetry (SH) are satisfied, and therefore the conclusions hold. 
\end{proof}




\begin{proof}[Proof of Proposition~\ref{prop:Sh_sub_addivitiy}]
    We calculate that 
    \begin{align*}
        \text{BS}_i &= \sum_{S \subseteq M \backslash i} \frac{|S|! (|M|-|S|-1)!}{|M|!} (v_R(S \cup i) - v_R(S)) \\
        &= \sum_{S \subseteq M \backslash i} \frac{|S|! (|M|-|S|-1)!}{|M|!} \left( \varrho \left( \sum_{j \in S} X_j + X_i \right) - \varrho \left( \sum_{j \in S} X_j \right) \right) \\
        &\leq \sum_{S \subseteq M \backslash i} \frac{|S|! (|M|-|S|-1)!}{|M|!} \varrho(X_i) = \varrho(X_i).
    \end{align*}

\end{proof}


