\title[Boundedness on weighted flag and product Hardy spaces]{The complete boundedness of singular integrals on weighted flag and product Hardy spaces}

\author[J. Tan]{Jian Tan}
\address{School of Science\\ Nanjing University of Posts and Telecommunications\\
    Nanjing 210023, People's Republic of China}
\email{tj@njupt.edu.cn}



\date{}


\begin{abstract}
It is known that 
product singular integrals are bounded on product Hardy spaces and that
flag singular integrals are bounded on flag Hardy spaces. The purpose of this paper is to obtain the complete boundedness of singular integrals on weighted flag and product Hardy spaces. In particular, we prove the boundedness of one-parameter singular integrals on both weighted flag and product Hardy spaces, as well as the boundedness of flag singular integrals on weighted product Hardy spaces.


%including the boundedness of one-parameter singular integrals on weighted flag and product Hardy spaces and the boundedness of flag singular integrals on weighted product Hardy spaces.
\end{abstract}

\subjclass[2020]{Primary 42B30, 42B25; Secondary 46E30}

\keywords{Weighted product Hardy spaces, weighted flag Hardy spaces, singular integrals, Littlewood--Paley theory, almost orthogonal estimates}

\maketitle



\section{Introduction and statement of main results}

It is well known that the classical singular integral operators
are bounded on the classical Hardy spaces.
On the other hand, the product singular integral operators, which are invariant under the following dilations:
$$
\delta x=(\delta_1x_1,\delta_2x_2,\cdots,\delta_nx_n),
$$
with $\delta_j>0$ and $1\le j\le n$,
are also bounded on corresponding product Hardy spaces.
For more details, see for example \cite{CF,F,FS,GS,HLLL} and the references therein.
A new extension of product theory came to light with the proof by
M\"uller et al. of the $L^p$ boundedness when $p\in(1,\infty)$
of Marcinkiewicz multipliers on the Heisenberg group in \cite{MRS}.
Then Han et al. introduced the multi-parameter flag Hardy spaces and gave the boundedness of flag singular integrals on these multi-parameter flag Hardy spaces in \cite{HLLW,HL,HLS}, which can be viewed as an ``intermediate'' between the classical Hardy spaces and the product Hardy spaces.
A natural question arises: is it possible that the one-parameter singular integrals are bounded on the flag Hardy spaces?

One of the main goals of this paper is to address this question, focusing on the two cases of $\mathbb R^n\times \mathbb R^m$ and $\mathbb R^n\times \mathbb R^m
\times \mathbb R^d$ with the flag structures, which also demonstrates that our methods are suitable for cases involving arbitrary multi-parameter flag structures.
In this paper, first we will consider the following one-parameter singular integral operators on $\mathbb R^n\times \mathbb R^m$.

\begin{definition}\label{1-2}
${K} \in C^2(\mathbb{R}^{n+m} \setminus \{0\})$ is said to be a {\it one-parameter singular integral kernel} on $\mathbb R^n\times \mathbb R^m$ if there are constants $C$ such that
\[
|\partial_z^\alpha {K}(z)| \leq \frac{C}{|z|^{n+m+|\alpha|}}
\]
for $0 \leq |\alpha| \leq 2$ and $z \in \mathbb{R}^{n+m} \setminus \{0\}$, and
\[
\int_{\epsilon < |z| < N} {K}(z) \, dz \leq C,
\]
whenever $0 < \epsilon < N < \infty$.
We say that an operator $T$ is a {\it one-parameter singular integral operator} if $Tf(z) = p. v. K\ast f(z)$ for a singular integral kernel ${K}$.
\end{definition}

For convenience, we defer the definitions of multi-parameter weighted flag and product Hardy spaces to Section \ref{pre}, along with Muckenhoupt weights in the multi-parameter settings.
Hereafter denote $\tau=\frac{2n}{2n+1}\vee\frac{2m}{2m+1},$ where $a\vee b$ means $\max\{a,b\}$. The first result in our paper is as follows. 
\begin{theorem}\label{1f}
Suppose that $w\in A_{p/\tau}(\mathbb R^n\times \mathbb R^m)$. If $T$ is a one-parameter singular integral operator on $\mathbb R^n\times \mathbb R^m$, then $T$ is bounded on multi-parameter weighted flag Hardy spaces $H^p_{flag,w}(\mathbb R^n\times \mathbb R^m)$ for $\tau<p\le1$.
\end{theorem}


In \cite{Tanc}, C. Tan proved that one-parameter singular integral operators
are also bounded on the product Hardy spaces. In the following theorem we extend the result to
the weighted case. Denote $\tilde\tau=\frac{n}{n+1}\vee\frac{m}{m+1}.$

\begin{theorem}\label{1p}
Suppose that $w\in A_{p/{\tilde\tau}}(\mathbb R^n\times \mathbb R^m)$. If $T$ is a one-parameter singular integral operator on $\mathbb R^n\times \mathbb R^m$, then $T$ is bounded on weighted product Hardy spaces $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m)$ for $\tilde\tau<p\le1$.
\end{theorem}

\begin{remark}\label{r1}
If the smoothness conditions of $K$ are replaced by ${K} \in C^\infty(\mathbb{R}^{n+m} \setminus \{0\})$, 
\[
|\partial_z^\alpha {K}(z)| \leq \frac{C}{|z|^{n+m+|\alpha|}}
\]
for any $0 \leq |\alpha| <\infty$ and
$
\int_{\epsilon < |z| < N} \partial_z^\beta{K}(z) \, dz \leq C
$
for any $0 \leq |\beta| <\infty$ and $0 < \epsilon < N < \infty$,
then by using the extrapolation we can get that for any $w\in A_{\infty}(\mathbb R^n\times \mathbb R^m)$, the one-parameter singular integral operator $\mathcal T$ is bounded on $H^p_{flag,w}(\mathbb R^n\times \mathbb R^m)$ and $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m)$ for $0<p<\infty$.
\end{remark}


We recall the definition of flag singular integrals in \cite{MRS}.

\begin{definition}\label{flag}
A \emph{flag kernel} on $\mathbb{R}^n \times \mathbb{R}^m$ is a distribution on $\mathbb{R}^{n+m}$ which coincides with a $C^{\infty}$ function away from the coordinate subspace $\{(0, y)\} \subset \mathbb{R}^{n+m}$, where $0 \in \mathbb{R}^n$ and $y \in \mathbb{R}^m$, and satisfies the following conditions:

\begin{itemize}
    \item[(1)] (Differential Inequalities) For any multi-indices $\alpha = (\alpha_1, \cdots, \alpha_n)$ and $\beta = (\beta_1, \cdots, \beta_m)$, we have
    \[
    |\partial_x^{\alpha} \partial_y^{\beta} K(x, y)| \leq C_{\alpha, \beta} |x|^{-n - |\alpha|} \cdot (|x| + |y|)^{-m - |\beta|}
    \]
    for all $(x, y) \in \mathbb{R}^n \times \mathbb{R}^m$ with $|x| \neq 0$.

    \item[(2)] (Cancellation Condition)
    \[
    \left| \int_{\mathbb{R}^m} \partial_x^{\alpha} K(x, y) \phi_1(\delta y) \, dy \right| \leq C_{\alpha} |x|^{-n - |\alpha|}
    \]
    for every multi-index $\alpha$, every normalized bump function $\phi_1$ on $\mathbb{R}^m$, and every $\delta > 0$;

    \[
    \left| \int_{\mathbb{R}^n} \partial_y^{\beta} K(x, y) \phi_2(\delta x) \, dx \right| \leq C_{\beta} |y|^{-m - |\beta|}
    \]
    for every multi-index $\beta$, every normalized bump function $\phi_2$ on $\mathbb{R}^n$, and every $\delta > 0$;

    \[
    \left| \int_{\mathbb{R}^{n+m}} K(x, y) \phi_3(\delta_1 x, \delta_2 y) \, dx \, dy \right| \leq C
    \]
    for every normalized bump function $\phi_3$ on $\mathbb{R}^{n+m}$, and every $\delta_1 > 0$ and $\delta_2 > 0$.
\end{itemize}

Then $T_{flag}(f)(x, y)=K\ast f(x, y)$ is said to be a {\it flag singular integral} on $\mathbb R^n\times \mathbb R^m$.
\end{definition}

In \cite{HL}, Han and Lu obtained the flag singular integrals $T_{flag}$ are bounded on the 
flag Hardy spaces $H^p_{flag}(\mathbb R^n\times \mathbb R^m).$  
Thus, a natural question arises: are the flag singular integrals bounded on weighted product Hardy spaces on $\mathbb R^n\times \mathbb R^m$?
The another purpose of this paper is to answer in the affirmative by obtaining the boundedness of such operators on these spaces as follows.


\begin{theorem}\label{fp}
Suppose that $w\in A_{\infty}(\mathbb R^n\times \mathbb R^m)$. If $T_{flag}$ is a a flag singular integral on $\mathbb R^n\times \mathbb R^m$, then $T_{flag}$ is bounded on weighted product Hardy spaces $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m)$ for $0<p\le1$.
\end{theorem}

We next study the weighted flag and product Hardy spaces boundedness of one-parameter singular integral operators on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$ which is nearly identical to Definition \ref{1-2}. For completeness, we give the definition of one-parameter singular integral operators on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$.

\begin{definition}\label{1-3}
${K} \in C^3(\mathbb{R}^{n+m+d} \setminus \{0\})$ is said to be a {\it one-parameter singular integral kernel} on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$ if there are constants $C$ such that
\[
|\partial_z^\alpha {K}(z)| \leq \frac{C}{|z|^{n+m+d+|\alpha|}}
\]
for $0 \leq |\alpha| \leq 3$ and $z \in \mathbb{R}^{n+m+d} \setminus \{0\}$, and
\[
\int_{\epsilon < |z| < N} {K}(z) \, dz \leq C,
\]
whenever $0 < \epsilon < N < \infty$.
We say that an operator $T$ is a {\it one-parameter singular integral operator} if $Tf(z) = p.v.{K}\ast f(z)$ for a singular integral kernel ${K}$.
\end{definition}


Hereafter denote $\gamma=\frac{3n}{3n+1}\vee\frac{3m}{3m+1}\vee \frac{3d}{3d+1}$. 
Now we state the following theorem.
\begin{theorem}\label{1f-3}
Suppose that $w\in A_{p/\gamma}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$. If $T$ is a one-parameter singular integral operator on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$, then $T$ is bounded on multi-parameter weighted flag Hardy spaces $H^p_{flag,w}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ for $\gamma<p\le1$.
\end{theorem}

The boundedness of one-parameter singular integral operator is also established on
weighted product Hardy spaces $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ as follows. Denote $\tilde \gamma=\frac{n}{n+1}\vee\frac{m}{m+1}\vee \frac{d}{d+1}$.

\begin{theorem}\label{1p-3}
Suppose that $w\in A_{p/\tilde\gamma}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$. If $T$ is a one-parameter singular integral operator on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$, then $T$ is bounded on weighted product Hardy spaces $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ for $\tilde\gamma<p\le1$.
\end{theorem}


\begin{remark}\label{r2}
If we impose stronger smoothness conditions of $K$ as in Remark \ref{r1},
then we can similarly conclude that for any $w\in A_{\infty}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$, the operator $\mathcal T$ is bounded on $H^p_{flag,w}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ and $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ for $0<p<\infty$.
\end{remark}

Next we will consider the singular integrals with the following flag
kernels which can be found in \cite{HLW}.

\begin{definition}
A {\it flag kernel} is a distribution $\mathcal{K}$ on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$ which coincides with a $C^\infty$ function away from the coordinate subspace $x_1 = 0$ and satisfies the following:

\begin{itemize}
    \item[(i)] ({differential inequalities}) For each $\alpha = (\alpha_1, \alpha_2, \alpha_3) \in \mathbb{Z}^3$,
    \[
    \left|\partial_{x_1}^{\alpha_1} \partial_{x_2}^{\alpha_2} \partial_{x_3}^{\alpha_3} \mathcal{K}(x)\right| \lesssim |x_1|^{-n_1 - |\alpha_1|} (|x_1| + |x_2|)^{-n_2 - |\alpha_2|} (|x_1| + |x_2| + |x_3|)^{-n_3 - |\alpha_3|}
    \]
    for $x_1 \neq 0$.

    \item[(ii)] ({cancellation conditions})
    \begin{itemize}
        \item[(a)] Given normalized bump functions $\psi_i$, $i = 1, 2, 3$, on $\mathbb{R}^{n_i}$ and any scaling parameter $r > 0$, define a distribution $\mathcal{K}_{\psi_i, r}$ by setting
        \begin{equation} \label{1-3}
        \langle \mathcal{K}_{\psi_i, r}, \varphi \rangle = \langle \mathcal{K}, (\psi_i)_r \otimes \varphi \rangle
        \end{equation}
        for any test function $\varphi \in \mathcal{S}(\mathbb{R}^{N - n_i})$. Then the distributions $\mathcal{K}_{\psi_i, r}$ satisfy the differential inequalities
        \[
        \left|\partial_{x_2}^{\alpha_2} \partial_{x_3}^{\alpha_3} \mathcal{K}_{\psi_1, r}(x_2, x_3)\right| \lesssim |x_2|^{-n_2 - |\alpha_2|} (|x_2| + |x_3|)^{-n_3 - |\alpha_3|},
        \]
        \[
        \left|\partial_{x_1}^{\alpha_1} \partial_{x_3}^{\alpha_3} \mathcal{K}_{\psi_2, r}(x_1, x_3)\right| \lesssim |x_1|^{-n_1 - |\alpha_1|} (|x_1| + |x_3|)^{-n_3 - |\alpha_3|},
        \]
        \[
        \left|\partial_{x_1}^{\alpha_1} \partial_{x_2}^{\alpha_2} \mathcal{K}_{\psi_3, r}(x_1, x_2)\right| \lesssim |x_1|^{-n_1 - |\alpha_1|} (|x_1| + |x_2|)^{-n_2 - |\alpha_2|}.
        \]
    \item[(b)] For any bump functions $\psi_i$ on $\mathbb{R}^{N - n_i}$ and any parameters $r = (r_1, r_2)$, we define the distributions $\mathcal{K}_{\psi_i, r}$ by \eqref{1-3}. Then the distributions $\mathcal{K}_{\psi_i, r}$, $i = 1, 2, 3$, are one-parameter kernels and satisfy
    \[
    \left|\partial_{x_i}^{\alpha_i} \mathcal{K}_{\psi_i, r}(x_i)\right| \lesssim |x_i|^{-n_i - |\alpha_i|}.
    \]

    \item[(c)] For any bump function $\psi$ on $\mathbb{R}^N$ and $r_1, r_2, r_3 > 0$, we have
    \[
    |\langle \mathcal{K}, \psi(r_1 \cdot, r_2 \cdot, r_3 \cdot) \rangle| \lesssim 1.
    \]
        \end{itemize}
\end{itemize}

Moreover, the corresponding constants that appear in these differential inequalities are independent of $r$, $r_1$, $r_2$.
Then we say that $T_{flag}=\mathcal{K} \ast f$ is a \textit{flag singular integral} $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$.

\end{definition}


In \cite{HLW}, Han et al. obtained the boundedness of the flag singular integrals on 
weighted flag Hardy spaces. Inspired by this result, we prove that the flag singular integrals are also bounded on the weighted product Hardy spaces $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ as follows. 

\begin{theorem}\label{fp-3}
Suppose that $w\in A_{\infty}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$. If $T_{flag}$ is a a flag singular integral on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$, then $T_{flag}$ is bounded on weighted product Hardy spaces $H^p_{prod,w}(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ for $0<p\le1$.
\end{theorem}

This paper is organized as follows. In Section \ref{pre}, we give some known results on weighted flag and product Hardy spaces along with the Fefferman--Stein vector valued maximal inequality
on product domain. Then we prove the boundedness of one-parameter singular integrals in the two cases of $\mathbb R^n\times \mathbb R^m$ and $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$ on the corresponding weighted flag Hardy spaces in Section 3. In Section 4, we focus on the boundedness of  
one-parameter singular integrals in the two cases of $\mathbb R^n\times \mathbb R^m$ and $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$ on the corresponding weighted product Hardy spaces.
In Section 5, we show that the flag singular integrals on $\mathbb R^n\times \mathbb R^m$ and $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$ are bounded on the corresponding weighted product Hardy spaces by using the weighted product Hardy spaces boundedness of the three-parameter singular integrals. In this last section, we will conclude by briefly considering the extension of the main results in this paper to Hardy spaces for ball quasi-Banach function spaces.

Throughout the paper, the letter
$C$ denotes a positive constant that may vary at each occurrence
but is independent to the main parameter, $A\lesssim B$ means that there are a constant
$C>0$ independent of the the main parameter such that $A\leq CB$ and $A\sim B$ denotes that $A\lesssim B$ and $B\lesssim A$.

\section{Preliminaries}\label{pre}
In this section, we recall some definitions and the basic results on weighted flag and product Hardy spaces. 
\subsection{Strong Hardy--Littlewood maximal operators on weighted Lebesgue spaces}\quad

For convenience, $\mathbb R^\mathcal X$ can represent either
$\mathbb R^n\times \mathbb R^m$ or $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$.
Denote by $L_{{\rm loc}}^{1}\left(\mathbb{R}^\mathcal X \right)$ the set of all locally integrable functions on $\mathbb{R}^\mathcal X$. 
In the multi-parameter case, it is natural to replace the classical Hardy--Littlewood maximal operator $M$ by the {\it strong Hardy--Littlewood maximal operators} $M_s$, which is defined by setting, for all $f\in L_{{\rm loc}}^{1}\left(\mathbb{R}^\mathcal X\right)$ and $x\in \mathbb{R}^\mathcal X$,
\begin{align*}\label{eq:second7}
	M_sf\left(x\right):= \sup\limits_{x\in R} \frac{1}{|R|} \int_{R} \left|f\left(y\right)\right|\,dy,
\end{align*}
where the supremum of $R$ are taken over all rectangles $R\in \mathbb R^\mathcal X$.
First we recall the definitions of product weights in the multi-parameter setting. For $1<p<\infty$, a nonnegative locally integrable function $w \in A_p\left(\mathbb{R}^\mathcal X\right)$ if there exists a constant $C>0$ such that
$$
\left(\frac{1}{|R|} \int_R w(x) d x\right)\left(\frac{1}{|R|} \int_R w(x)^{-1 /(p-1)} d x\right)^{p-1} \leqslant C.
$$
We say $w \in A_1\left(\mathbb{R}^\mathcal X\right)$ if there exists a constant $C>0$ such that
$$
M_s w(x) \leqslant C w(x) 
$$
for almost every $x \in \mathbb{R}^\mathcal X$.
We define $w \in A_{\infty}\left(\mathbb{R}^\mathcal X\right)$ by
$$
A_{\infty}\left(\mathbb{R}^\mathcal X\right)=\bigcup_{1 \leqslant p<\infty} A_p\left(\mathbb{R}^\mathcal X\right)
$$
%Observe that if $w \in A_{\infty}\left(\mathbb{R}^\mathcal X\right)$, then $w \in A_{q_w}\left(\mathbb{R}^\mathcal X\right)$, where $q_w=\inf \left\{q: w \in A_q\left(\mathbb{R}^\mathcal X\right)\right\}$.

Next, we recall 
the well-known weighted boundedness of the strong maximal operators
$\mathcal M_s$ as follows.

\begin{proposition}\label{FS}\cite{gr85}\label{max}\quad Let $1<p<\infty$ and $w\in A_{p}(\mathbb R^\mathcal X).$ Then $\mathcal M_s$ is of type
$(L^p_w(\mathbb R^\mathcal X),L^p_w(\mathbb R^\mathcal X))$.
Moreover, for any $1<s<\infty$, 
\begin{align*}
		\left\|\left\{\sum_{j=1}^{\infty}\left[M_s\left(f_{j}\right)\right]^{s}\right\}^{1 / s}\right\|_{L^p_w(\mathbb R^\mathcal X)} 
		\le C\left\|\left\{\sum_{j=1}^{\infty}\left|f_{j}\right|^{s}\right\}^{1 / s}\right\|_{L^p_w(\mathbb R^\mathcal X)}
	\end{align*}
\end{proposition}

\subsection{Weighted product Hardy spaces}\quad

In the subsection, we recall the Littlewood--Paley characterization for the three-parameter weighted Hardy spaces on $\mathbb R^n\times \mathbb R^m\times \mathbb R^d$. For more details, we refer the readers
to \cite{Ru}. 
For conveniences,  hereafter $Q\in \mathcal R^{j,k,\ell}$ means that $Q=I\times J\times K\subset \mathbb R^n\times\mathbb R^m\times \mathbb R^d$
with side-length \(\ell(I) = 2^{j}, \ell(J) = 2^{k} \) and \( \ell(K) = 2^{\ell} \), \( x_Q \) denotes the left lower corner
of $Q$. Similarly, $Q\in \mathcal R^{j,k}$ means that $Q=I\times J\subset \mathbb R^n\times\mathbb R^m$
with side-length \(\ell(I) = 2^{j}\) and  \( \ell(J) = 2^{k} \).
The definition of weighted product Hardy spaces on $\mathbb R^n\times \mathbb R^m$ is nearly identical but easier, so we omit it.
Let \(\mathcal S(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)\) denote the set of Schwartz functions in \(\mathbb R^n\times \mathbb R^m\times \mathbb R^d\)
and $x=(x_1,x_2,x_3)\in\mathbb R^n\times \mathbb R^m\times \mathbb R^d$. We denote \( f \in \mathcal{S}_0(\mathbb{R}^3)\),
if $f\in \mathcal S(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ and
\text{for\, all} indices $\alpha, \beta, \gamma$ of nonnegative integers,
\[\int_{\mathbb{R}} f(x_1,x_2,x_3)x_1^{\alpha} dx_1 = \int_{\mathbb{R}} f(x_1,x_2,x_3)x_2^{\beta} dx_2 = \int_{\mathbb{R}} f(x_1,x_2,x_3)x_3^{\gamma} dx_3 = 0.\]
The semi-norms of $f\in \mathcal{S}_0(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$ are the Schwartz semi-norms.
The dual space of \( \mathcal{S}_0(\mathbb R^n\times \mathbb R^m\times \mathbb R^d) \) is denoted by \( \mathcal{S}_0'(\mathbb R^n\times \mathbb R^m\times \mathbb R^d) \). 

Let \( \psi^{(1)} \in \mathcal{S}(\mathbb{R}^n), \psi^{(2)} \in \mathcal{S}(\mathbb{R}^m), \psi^{(3)} \in \mathcal{S}(\mathbb{R}^d) \) and satisfy
\begin{equation}\label{1.1}
\sum_{j \in \mathbb{Z}} |\widehat{\psi^{(1)}}(2^{-j} \xi_1)|^2 = 1 \quad \text{for all } \xi_1 \in \mathbb{R}^n \setminus \{0\},
\end{equation}
\begin{equation}\label{1.2}
\sum_{k \in \mathbb{Z}} |\widehat{\psi^{(2)}}(2^{-k} \xi_2)|^2 = 1 \quad \text{for all } \xi_2 \in \mathbb{R}^m \setminus \{0\},
\end{equation}
\begin{equation}\label{1.3}
\sum_{\ell \in \mathbb{Z}} |\widehat{\psi^{(3)}}(2^{-\ell} \xi_3)|^2 = 1 \quad \text{for all } \xi_3 \in \mathbb{R}^d \setminus \{0\},
\end{equation}
and the support conditions
\begin{equation}\label{1.4}
\mbox{supp}\;\widehat{\psi^{(i)}}(\xi_i)\subset \{\xi_i: \frac{1}{2}< |\xi_i|\le 2\},
\end{equation}\
for $i=1,2,3$. Denote
\[
\psi_{j,k,\ell}(x_1,x_2,x_3) = 2^{-j-k-\ell} \psi^{(1)}(2^{-j} x_1) \psi^{(2)}(2^{-k}x_2)  \psi^{(3)}(2^{-\ell} x_3),
\]
where
\[
\psi_j^{(1)}(x_1) = 2^{-j} \psi^{(1)}(2^{-j} x_1), \quad \psi_k^{(2)}(x_2) = 2^{-k} \psi^{(2)}(2^{-k} x_2), \quad \psi_{\ell}^{(3)}(x_3) = 2^{-\ell} \psi^{(3)}(2^{-\ell} x_3).
\]

By the Fourier transform, we can obtain the continuous version of the Calder\'on identity on \( L^2(\mathbb R^n\times \mathbb R^m\times \mathbb R^d) \), that is, for any \( f \in L^2(\mathbb R^n\times \mathbb R^m\times \mathbb R^d) \)
and $u:=(x,y,z)\in \mathbb R^n\times \mathbb R^m\times \mathbb R^d$,
\[
f(x,y,z) = \sum_{j,k,\ell \in \mathbb{Z}} \psi_{j,k,\ell} \ast \psi_{j,k,\ell} \ast f(x,y,z). 
\]

We also need the following discrete Calder\'on identity in $\mathcal{S}_0'(\mathbb R^n\times \mathbb R^m\times \mathbb R^d)$, whose proof is nearly identical to that of Theorem 1.1 in \cite{HLLTW}.
Also see \cite{FJ,FHLL} for more details on the Calder\'on  reproducing formula.

\begin{proposition}\label{disc} Let \( \psi_{j,k,\ell} \) be the same as in (\ref{1.1})-(\ref{1.4}). Then
\begin{align}\label{dsc}
f(u) = \sum_{j,k,\ell} \sum_{Q\in \mathcal R^{j,k,\ell}} | Q | {\psi}_{j,k,\ell}(u-u_Q) \ast \psi_{j,k,\ell} \ast f (u_Q),
\end{align}
where the series in (\ref{dsc}) converges in the norm of \(L^2(\mathbb R^n\times\mathbb R^m\times \mathbb R^d)\), in the norm of \( \mathcal{S}_0(\mathbb R^n\times\mathbb R^m\times \mathbb R^d) \) and in the dual space \( \mathcal{S}_0'(\mathbb R^n\times\mathbb R^m\times \mathbb R^d) \).
\end{proposition}


For \( f \in \mathcal{S}_0'(\mathbb R^n\times\mathbb R^m\times \mathbb R^d) \) and $x\in \mathbb R^n\times\mathbb R^m\times \mathbb R^d$, we define the {\it discrete Littlewood--Paley square function} on \(\mathbb R^n\times\mathbb R^m\times \mathbb R^d\) by
\[
\mathcal{G}^d(f)(u) := \left(  \sum_{j,k,\ell} \sum_{Q\in \mathcal R^{j,k,\ell}} |\psi_{j,k,\ell} \ast f (u_Q) |^2 \chi_{Q}(u_Q) \right)^{\frac{1}{2}},
\]
where \( \psi_{j,k,\ell} \) satisfies the same conditions as (\ref{1.1})-(\ref{1.4}). 
When \( 1 < p < \infty \), by the iteration argument, vector-valued Littlewood--Paley--Stein estimates and the duality argument, we can get \[ \| f \|_{L^{p}(\mathbb R^n\times\mathbb R^m\times \mathbb R^d)} \sim \| \mathcal{G}^d(f) \|_{L^{p}(\mathbb R^n\times\mathbb R^m\times \mathbb R^d)}. \]

\begin{definition}
For $0<p<\infty$ and $w\in A_\infty(\mathbb R^n\times\mathbb R^m\times \mathbb R^d)$, we define the {\it weighted product Hardy space}
$$H^p_w(\mathbb R^n\times\mathbb R^m\times \mathbb R^d)
=\{f\in \mathcal{S}_0'(\mathbb R^n\times\mathbb R^m\times \mathbb R^d):\mathcal{G}_d(f)\in L^p_w (\mathbb R^n\times\mathbb R^m\times \mathbb R^d)\}$$
with the norm
$$\|f\|_{H^p_w(\mathbb R^n\times\mathbb R^m\times \mathbb R^d)}
=\|\mathcal{G}^d(f)\|_{L^p_w(\mathbb R^n\times\mathbb R^m\times \mathbb R^d)}.$$
\end{definition}

%Then by using the Min--Max type inequality together with the above discrete Calder\'on identity, one can get the discrete Littlewood–Paley–Stein characterization for the three-parameter weighted Hardy spaces. Therefore, the definition of these weighted Hardy spaces is independent of the choice of functions \( \psi_{j,k,\ell} \) and thus ensure that the weighted Hardy space is well defined.



