\section{Preliminaries}\label{Prel}

Let $\bk$ be an arbitrary field, unless further specified, and let $\mN$ denote the set of non-negative integers.

\subsection{The infinite symmetric group}



\subsubsection{} Denote by $S_n$, with $n\in\mZ_{>0}$, the permutation group of the set $\{1,2, \ldots,n\}$. This gives a canonical inclusion $S_n\subset S_{n+1}$.
We consider the infinite symmetric group and its group algebra
$$S_\infty:=\bigcup_n S_n\;=\;\varinjlim_n S_n\quad\mbox{and}\quad\bk S_\infty\;\simeq\;\varinjlim_n \bk S_n.$$

For the Young subgroup $S_m\times S_n$ of $S_{m+n}$ we use the algebra isomorphism to introduce the notation $-\bullet-$:
$$\bk S_m\otimes \bk S_n\;\xrightarrow{\sim}\; \bk S_{m+n},\quad f\otimes g\mapsto f\bullet g.$$
We will use the same notation $f\bullet g\in \bk S_\infty$ for $f\in \bk S_m\subset \bk S_\infty$ and $g\in \bk S_\infty$. If it is unclear in which $\bk S_m\subset \bk S_\infty$ we consider $f$, we will write more specifically $f\stackrel{m}{\bullet}g$.


\subsubsection{}
All ideals we consider are two-sided unless mentioned otherwise. An ideal $I<\bk S_\infty$ is determined by the ideals $I_n:=I\cap \bk S_n$ for all $n\in\mZ_{>0}$. Any system of ideals $I_n<\bk S_n$ with $I_{n}=I_{n+1}\cap \bk S_n$ determines uniquely a corresponding ideal $I=\cup_nI_n$. We let $\Spec \bk S_\infty$ be the topological space of prime ideals in $\bk S_\infty$, for the Jacobson topology.

For a ring $R$ and an $R$-module $M$, we denote by $\Ann_RM$, or simply $\Ann M$, its annihilator ideal in $R$.
Recall that for a subring $R\subset S$, with $S$ free as a right $R$-module, and a left $R$-module~$N$, we have
\begin{equation}\label{EqInd}
\Ann_S(S\otimes_RN)\;=\;\Ann_S(S/S\Ann_R(N)).
\end{equation}
so that the left-hand side only depends on $\Ann_R(N)$.

For two $\bk$-algebras $A,B$ with modules $M,N$, we have
\begin{equation}\label{AnnTensor}
\Ann_{A\otimes B}(M\boxtimes N)\;=\; \Ann_A(M)\otimes B+ A\otimes \Ann_B(N).
\end{equation}


\subsubsection{} The simple $\bk S_n$-modules are denoted by $D^\lambda$. Here $\lambda$ runs over all partitions of $n$ if $\mathrm{char}(\bk)=0$ (and $D^\lambda$ is the Specht module corresponding to $\lambda$) and over all $p$-regular partitions of $n$ if $\mathrm{char}(\bk)=p>0$.

For an appropriate partition $\lambda\vdash n$, we will use the symbol $e_\lambda$ to denote an arbitrary primitive idempotent in $\bk S_n$ corresponding to $D^\lambda$.

For a module $M$ over a finite dimensional associative $\bk$-algebra, we write $\Irr(M)$ for the set of simple modules that appear as simple constituents.

\subsubsection{}There are two notions of inductive systems relating to $ S_\infty$. 

By an {\bf inductive system}, we refer to an inductive system of~$S_\infty$ as in \cite[Definition~1.1]{Za}. This is a collection $\Phi^n$ of (isomorphism classes of) simple $\bk S_n$-modules for each $n\in\mZ_{>0}$, such that $V\in \Phi^n$ if and only if there is some $U\in \Phi^{n+1}$ so that $V$ is a composition factor of $\Res^{S_{n+1}}_{S_n}U$.


We use the term {\bf lifted inductive system} for an inductive system as in \cite[Definition~2.1.1]{PolyFun}. This is a collection $\bB^n$ of indecomposable $\bk S_n$-modules for each $n\in\mZ_{>0}$, such that $V\in \bB^n$ if and only if there is some $U\in \bB^{n+1}$ so that $V$ is a direct summand of $\Res^{S_{n+1}}_{S_n}U$.



If $\mathrm{char}(\bk)=0$, the two notions clearly coincide and we simply say `inductive system' for both. In general, for a lifted inductive system $\bB$ we can define the inductive system $K_0(\bB)$ such that $K_0(\bB)^n$ contains all simple modules that are constituents of the modules in $\bB^n$, so that we may view $\bB$ as a `lift' of $K_0(\bB)$.

An inductive system $\Phi$ is {\bf indecomposable} if we cannot write it as $\Phi_1\cup\Phi_2$ for proper subsystems $\Phi_i\subset\Phi$.


\subsubsection{}\label{SecPhiI} Consider an ideal $I<\bk S_\infty$. Then the following conditions are equivalent on a simple $\bk S_n$-module $D^\lambda$:
\begin{enumerate}
\item[(i)] $D^\lambda\in \Irr(\bk S_n/I_n)$;
\item[(ii)] $D^\lambda\in \Irr(\bk S_\infty/ I)$;
\item[(iii)] $e_\lambda\not\in I$.
\end{enumerate}
We can thus define an inductive system $\Phi(I)$, where
$\Phi(I)^n$ comprises those $D^\lambda$ that satisfy the conditions (i)-(iii).

Conversely, for an inductive system $\Phi$, we define  ideals
$$\hat{I}(\Phi)_n:=\bigcap_{V\in \Phi^n}\Ann_{\bk S_n}V\;<\; \bk S_n.$$
If $\mathrm{char}(\bk)=0$, or more generally if $\Phi$ is semisimple (meaning every $V\in \Phi^n$ restricts to a semisimple $S_m$-representation for any $m<n$), it follows that the collection $\{\hat{I}(\Phi)_n\mid n\}$ defines an ideal in $\bk S_\infty$, which we denote by $I(\Phi)$, so $I(\Phi)_n=\hat{I}(\Phi)_n$. In general, we define $I(\Phi)$ to be the maximal ideal $J$ in $\bk S_\infty$ that satisfies the following equivalent conditions:
\begin{enumerate}
\item[(i)] $J_n\subset\hat{I}(\Phi)_n$ for all $n$;
\item[(ii)] $e_\lambda\not\in J$ whenever $D^\lambda\in \Phi^n$;
\item[(iii)]  $\Phi\subset\Phi(J)$.
\end{enumerate} 
It is also easy to give a direct description of $I(\Phi)$, namely
\begin{equation}\label{IPhi}I(\Phi)_n:=\bigcap_{m\ge n,V\in \Phi^m}\Ann_{\bk S_n}\Res^{S_m}_{S_n}V\;<\; \bk S_n.
\end{equation}


The following theorem is due to Zalesskii \cite{Za}, see also \cite{BK, Br, FL}.
Recall that an ideal is {\bf semiprimitive} if it is an intersection of primitive ideals. If the characteristic of $\bk$ is zero, then every ideal in $\bk S_\infty$ is semiprimitive. This follows for instance from the general principle that in a locally finite dimensional $\bk$-algebra (for any field $\bk$), the Jacobson radical is the maximal locally nilpotent ideal (as follows from the characterisation of the Jacobson radical via quasi-regular elements).


%Proposition~3.3, Theorem~1.25, Lemma~8.1 and Proposition~8.5 of \cite{Za}

\begin{theorem}\label{ThmZal}
The assignments
$I\mapsto \Phi(I)$ and $\Phi\mapsto I(\Phi)$ are (mutually inverse) inclusion reversing bijections between the set of semiprimitive ideals in $\bk S_\infty$ and the set of inductive systems.

In both cases the bijection restricts to a bijection between the set of indecomposable inductive systems and $\Spec \bk S_\infty$.
\end{theorem}
\begin{proof}
For fields of characteristic zero, this is \cite[Propositions~3.3 and~3.11]{Za}. For positive characteristic, in \cite[Theorem~1.25]{Za} it is proved that $I\mapsto \Phi(I)$ is bijections between the set of semiprimitive ideals in $\bk S_\infty$ and the set of inductive systems. The inverse $\Phi\mapsto I(\Phi)$ as provided {\it loc. cit.} is defined as the maximal ideal $J<\bk S_\infty$ under the restriction $\Phi(J)=\Phi$. That this is actually the same as the maximal ideal $J<\bk S_\infty$ under the restriction $\Phi(J)\supset\Phi$ follows from \cite[Proposition~2.6(i)]{BK}.


Finally, \cite[Proposition~8.5]{Za} states that $I(\Phi)$ is prime if and only if $\Phi$ is indecomposable. The last conclusion thus follows from the observation that a prime ideal $P$ in $\bk S_\infty$ must be semiprimitive, for instance by observing via the discussion before the theorem that the Jacobson radical of $\bk S_\infty/P$ is locally nilpotent and hence zero.
\end{proof}


\begin{remark}
Every prime ideal in $\bk S_\infty$ is primitive. Indeed, a prime ideal $I(\Phi)$ is an intersection of primitive ideals $I(\Phi_\alpha)$, but this implies $\Phi=\cup_\alpha\Phi_\alpha$, so by indecomposability of $\Phi$, we find $\Phi=\Phi_\alpha$ for some~$\alpha$.
\end{remark}


