\subsection{Operations}
We introduce two binary operations on ideals in $\bk S_\infty$.


\begin{definition}
For ideals $I,J$ in $\bk S_\infty$, the ideal $I\Join J$ is defined as the preimage of $$I\otimes \bk S_\infty \;+\; \bk S_\infty\otimes J$$
under the comultiplication algebra morphism
$\Delta:\bk S_\infty\to\bk S_\infty \otimes \bk S_\infty$.
\end{definition}
By cocommutativity, we have $I\Join J=J\Join I$, and similarly coassociativity implies associativity of $\Join$. We also have
$$(I\Join J)_n\,= \,\Ann_{\bk S_n}\left(\bk S_n/I_n\otimes \bk S_n/J_n\right)\,=\, \Ann_{\bk S_n}\left(V\otimes W\right),$$
for any $\bk S_n$-modules $V,W$ with annihilator ideals $I_n,J_n$.



\begin{example}\label{ExPlus}
\begin{enumerate}
\item The augmentation ideal $J_+$ is the identity element for the operation $\Join$, meaning that for every ideal $I$ in $\bk S_\infty$,
$$I\Join J_+\;=\; I\;=\; J_+\Join I.$$
\item The identity ideal is the zero element for the operation $\Join$, meaning 
$$I\Join \bk S_\infty\;=\; \bk S_\infty\;=\; \bk S_\infty\Join I.$$
\item For two $\bk S_\infty$-modules, we have
$$\Ann (M\otimes N)\;=\; \Ann(M)\Join \Ann(N),$$
for example $J_-\Join J_-=J_+$.
\end{enumerate}
\end{example}


%\begin{remark}
%For two inductive systems $\Phi$ and $\Psi$, write $\Phi\otimes \Psi$ for the inductive system for which $(\Phi\otimes \Psi)^n$ contains all simple constituents that occur in tensor products $D_1\otimes D_2$ with $D_1\in\Phi$ and $D_2\in \Psi$. Then
%$$\Phi(I\Join J)\;=\; \Phi(I)\otimes \Phi(J).$$
%These observations are also made in \cite[\S 3]{Za}.
%\end{remark}

\begin{definition}
For ideals $I,J$ in $\bk S_\infty$, the ideal $I\dagger J$ is such that
\begin{eqnarray*}
(I\dagger J)_n&=& \bigcap_{i=0}^n \Ann_{\bk S_n} (\bk S_{n}/\bk S_n(I_i\otimes \bk S_{n-i}\,+\, \bk S_i\otimes J_{n-i}))\\
&=& \bigcap_{i=0}^n \Ann_{\bk S_n} \Ind^{S_n}_{S_i\times S_{n-i}}(\bk S_i/I_i\boxtimes \bk S_{n-i}/J_{n-i})\\
&=& \bigcap_{i=0}^n \Ann_{\bk S_n} \Ind^{S_n}_{S_i\times S_{n-i}}(V_i\boxtimes W_{n-i}),
\end{eqnarray*}
for any $\bk S_i$-module $V_i$ with annihilator $I_i$ and any $\bk S_{n-i}$-module $W_{n-i}$ with annihilator $J_{n-i}$.
\end{definition}
That this chain of ideals actually defines an ideal in $\bk S_\infty$ follows from Mackey's formula. By definition $I\dagger J=J\dagger I$, and also $\dagger$ is associative.
%$$\Res_{S_n}^{S_{n+1}}\Ind^{S_{n+1}}_{S_a\times S_b}(M\boxtimes N)\;\simeq\;\Ind^{S_n}_{S_a\times S_{b-1}}(M\boxtimes N)\oplus \Ind^{S_n}_{S_{a-1}\times S_{b}}(M\boxtimes N),$$
%for $a+b=n+1$.
\begin{example}\label{ExDagger}
\begin{enumerate}
\item The identity ideal $\bk S_\infty$ is the identity element for the operation  $\dagger$, meaning
$$I\dagger \bk S_\infty\;=\; I\;=\; \bk S_\infty \dagger I.$$
\item For $m,n\in\mN$, we define the ideal 
$$\mP_{m,n}\,:= \,J_+^{\dagger m}\dagger J_-^{\dagger n},$$
so $\mP_{0,0}=\bk S_\infty$ by convention. Then $(\mP_{m,n})_i$ is the kernel of the permutation action
$$\bk S_i\;\to\; \End(V^{\otimes i}),$$
for $V$ a supervector space of dimension $m|n$. This follows directly, or from Example~\ref{ExsVec} below. We take the convention that for $\mathrm{char}(\bk)=2$, we have $\mP_{m,n}=J^{\dagger (m+n)}_+$.
\end{enumerate}

\end{example}

\begin{lemma}
For all ideals $I,J<\bk S_\infty$ and $P\in \TSpec \bk S_\infty$, we have
$$(I\dagger J)\Join P\;=\; (I\Join P)\dagger (J\Join P).$$
\end{lemma}
\begin{proof}
We can rewrite $((I\dagger J)\Join P)_n$ as
$$\bigcap_{i=0}^n\Ann\left(\Ind^{S_n}_{S_i\times S_{n-i}}\left((\bk S_{i}/I_i\boxtimes S_{n-i}/I_{n-i}) \otimes \Res^{S_n}_{S_i\times S_{n-i}}\bk S_n/P_n\right)\right),$$
whereas $((I\Join P)\dagger (J\Join P))_n$ becomes
$$\bigcap_{i=0}^n\Ann\left(\Ind^{S_n}_{S_i\times S_{n-i}}\left((\bk S_i/I_i\otimes \bk S_i/P_i)\boxtimes (\bk S_{n-i}/J_{n-i}\otimes \bk S_{n-i}/P_{n-i})\right)\right).$$
The conclusion thus follows from condition (5) in Proposition~\ref{LemDefT}.
\end{proof}



\begin{theorem}
The set $\TSpec \bk S_\infty$ equipped with addition $\dagger$ and multiplication $\Join$ is a commutative semiring.
\end{theorem}
\begin{proof}
The only things that remains to be proved is that $\dagger$ and $\Join$ restrict to operations
$$\TSpec\bk S_\infty\;\times\;\TSpec \bk S_\infty\;\to\; \TSpec \bk S_\infty.$$

The fact that $\Join$ preserves T-prime ideals can, via Proposition~\ref{LemDefT}, be reduced to the observation that the annihilator ideal in $\bk S_m\otimes \bk S_n$ of
$$\bk S_{m+n}/I_{m+n}\;\otimes\; \bk S_{m+n}/J_{m+n}$$
coincides with that of
$$ (\bk S_{m}/I_{m}\;\otimes\; \bk S_{m}/J_{m})\;\boxtimes\; (\bk S_{n}/I_{n}\;\otimes\; \bk S_{n}/J_{n}),$$
assuming that $I,J$ are T-prime.

The case $\dagger$ follows similarly, by also applying Mackey's formula.
\end{proof}

\begin{remark}
Already for $\mathrm{char}(\bk)=0$, the semiring $\TSpec \bk S_\infty$ is not topological for the Jacobson topology, as follows from the explicit description in the Section~\ref{Sec0}.
\end{remark}
\subsection{Growth rates of ideals}
\label{SecGrowth}

\subsubsection{} As a rough estimate of the size of a non-zero ideal $I<\bk S_\infty$, we set
$$\ddd(I)\;:=\; \max\{n\in\mZ_{>0}\mid I_n=0\}\;\in\;\mN,$$
with the understanding that the maximum of an empty set is $0$. Hence $\ddd(I)=0$ if and only if $I=\bk S_\infty$.
The following lemma is immediate.
\begin{lemma}\label{LemdAdd}
For non-zero ideals $I,J$ in $\bk S_\infty$, we have
$$\ddd(I\dagger J)\;\ge\; \ddd(I)+\ddd(J).$$
\end{lemma}


\begin{corollary}
For a non-zero proper ideal $I<\bk S_\infty$ and $m,n\in \mN$, we have $I^{\dagger m}=I^{\dagger n}$ if and only if $m=n$.
\end{corollary}

\subsubsection{} For T-prime ideals, we can define a more refined measure of the size. By Poposition~\ref{LemDefT}, for $I\in \TSpec \bk S_\infty$, the canonical morphism
$$\bk S_m/I_m\otimes \bk S_n/I_n\;\to\; \bk S_{m+n}/I_{m+n}$$
is an inclusion, so
$$\dim_{\bk}(\bk S_m/I_m)\dim_{\bk}(\bk S_m/I_m)\;\le\; \dim_{\bk}(\bk S_{m+n}/I_{m+n}).$$
Hence, setting $g_n(I)=\dim (\bk S_n/I_n)$, by Fekete's lemma in~\cite[Lemma~1.6.3]{Be}, there is a well-defined limit
$$\gggr(I)\;=\; \lim_{n\to\infty}\sqrt[2n]{g_n(I)}\;=\; \sup\{\sqrt[2n]{g_n(I)}\mid n>0\}\;\,\in\;\mR_{\ge 0}\cup\{\infty\}.$$
As with $\ddd(I)$, higher $\gggr(I)$ implies smaller $I$. For example $\gggr(\bk S_\infty)=0$ and $\gggr(I)\ge 1$ otherwise.

It will follow from closer analysis that, if we exclude the case $I=0$, we have $\gggr(I)\in\mR_{\ge0}$ for all $I\in\TSpec\bk S_\infty$, see Corollary~\ref{Cor0} and Lemma~\ref{lemfin}.

\begin{lemma}\label{Lemgdagger}
For $I,J\in \TSpec\bk S_\infty$, we have
\begin{enumerate}
\item $\max\{\gggr(I),\gggr(J)\}\;\le\; \gggr(I\dagger J)\;\le\; \gggr(I)+\gggr(J)$;
\item $\gggr(I\Join J)\;\le\; \gggr(I)\gggr(J)$.
\end{enumerate}
\end{lemma}
\begin{proof}
The first inequality in (1) follows since $I\dagger J\subset I$. For the second inequality, by definition, we have an exact sequence
$$0\to (I\dagger J)_{n}\to \bk S_n\to \bigoplus_{i=0}^n \End_{\bk}\left(\Ind^{S_n}_{S_i\times S_{n-i}} (\bk S_i/I_i\boxtimes \bk S_{n-i}/J_{n-i})\right),$$
where the right arrow represents the action of $\bk S_n$. This action commutes with the obvious right $\bk S_i\otimes \bk S_{n-i}$-action on the induced module, so that the exact sequence can be adjusted to get the estimate
$$g_n(I\dagger J)\;\le\;\sum_{i=0}^n\binom{n}{i}^2 g_i(I)g_{n-i}(J)$$
and hence
$$\sqrt{g_n(I\dagger J)}\;\le\;\sum_{i=0}^n\binom{n}{i} \sqrt{g_i(I)}\sqrt{g_{n-i}(J)}.$$
The result then follows from a standard argument, see for instance the proof of \cite[Lemma~4.9(2)]{CEO}.

Part (2) follows more directly from the exact sequence
$$0\to (I\Join J)_n\to \bk S_n\to \bk S_n/I_n\otimes \bk S_n/J_n$$
where the right arrow is comultiplication followed by quotient map. 
\end{proof}

At least in some cases, the subadditivity of Lemma~\ref{Lemgdagger}(1) is actually additivity:


\begin{lemma}\label{Lemmag}
\begin{enumerate}
\item We have $\gggr(\mP_{m,0})=\gggr(J_+^{m\dagger})=m$.
\item If $\mathrm{char}(\bk)=0$, then $\gggr(\mP_{m,n})=m+n$.
\end{enumerate}
\end{lemma}
\begin{proof}
We start with part (2). By Schur-Weyl duality, see for instance \cite{Berele}, and Example~\ref{ExDagger}(2), we have
$$\gggr(\mP_{m,n})\;=\;\lim_{i\to\infty}\sqrt[2i]{\dim_{\bk}\End_{GL(V)}(V^{\otimes i})},$$
for $V$ a supervector space of dimension $m|n$.
Now by \cite{Berele}, the $GL(V)$-representation $V^{\otimes i}$ is semisimple and the number of isomorphism classes of simple modules that can appear as direct summand in $V^{\otimes i}$ grows only polynomially in $i$, as it is bounded by $(i)^{m+n}$. On the other hand, with $d_i$ the length of $V^{\otimes i}$, we have 
$$\lim_{i\to\infty}\sqrt[i]{d_i}\;=\; m+n,$$
see for instance \cite[Proposition~3.1]{COT}. There must be a simple module that occurs at least $d_i/i^{m+n}$ times as direct summand in $V^{\otimes i}$, giving a lower bound for the dimension of $\End_{GL(V)}(V^{\otimes i})$. Combining all the above observations, we find that
$$m+n\;=\;\lim_{i\to\infty}\sqrt[2i]{(d_i/i^{m+n})^2}\;\le\;\gggr(\mP_{m,n}),$$
so the conclusion follows from Lemma~\ref{Lemgdagger}(1).

Part (1) follows from part (2), Schur-Weyl duality in positive characteristic and independence of $\dim_{\bk}\End_{GL(V)}(V^{\otimes i})$ on the characteristic (a well-known consequence of the fact that $V^{\otimes i}$ is a tilting module in a highest weight category with standard modules that have the same character in every characteristic).
\end{proof}

\begin{remark}
As observed in \cite{CEKO}, for $I=\mP_{m,n}$, the dimension of $\bk S_i/I_i$ s lower in positive characteristic than in characteristic zero, so a priori the inequality $\gggr(\mP_{m,n})\le m+n$ from Lemma~\ref{Lemgdagger} might be strict. Note however that $\gggr(\mP_{1,1})=2$ by \cite[Theorem~3.3.1]{CEKO}.
\end{remark}




\subsection{Tensor categories}
Let $\cC$ be a tensor category over $\bk$ and $X\in \cC$.

\subsubsection{} Following \cite[\S 6]{PolyFun}, to $X$ we associate the ideal
$$\TAnn(X)\;<\; \bk S_\infty.$$ Concretely, $\TAnn(X)$ is the kernel of the algebra morphism 
$$\bk S_\infty\;\to\; \varinjlim_{n}\End(X^{\otimes n})$$
coming from the braiding on $\cC$. Equivalently, $\TAnn(X)_n$ is the kernel of
$\bk S_n\to \End(X^{\otimes n}),$
which is the common kernel of all modules in $\mathbf{B}_X^n$, for $\mathbf{B}_X$ the lifted inductive system associated to $X$ in \cite[\S 3]{PolyFun}. By construction $\TAnn(FX)=\TAnn(X)$ for any tensor functor $F$.

As proved in \cite[4.11 and 4.12]{CEO}, the category $\cC$ is `of moderate growth' if and only if $\TAnn(X)\not=0$ for all $X\in\cC$.


\subsubsection{} For a tensor category, we consider the split Grothendieck monoid $M^{\oplus}(\cC)$, which is isomorphic to the free monoid generated by the set of isomorphism classes of indecomposable objects in $\cC$. This is a commutative semiring, with product induced from the tensor product.

\begin{prop}\label{Lem:Tens} Let $\cC$ be a tensor category of moderate growth.
The association $X\mapsto \TAnn(X)$ induces a semiring morphism
$$\TAnn_{\cC}:\;M^{\oplus}(\cC)\;\to\; \TSpec\bk S_\infty.$$
\end{prop}


\begin{proof}
Firstly, $\TAnn(X)$ is T-prime, since in a tensor category $\cC$, the morphism $f\otimes g$, for morphisms $f,g$ in $\cC$, can only be zero if both $f$ and $g$ are zero. It thus suffices to observe the identities
\begin{eqnarray*}
\TAnn(X\oplus Y)&=& \TAnn(X)\dagger \TAnn(Y),\\
\TAnn(X\otimes Y)&=&\TAnn(X)\Join \TAnn(Y),\\
\TAnn(0)&=& \bk S_\infty,\qquad \mbox{and}\quad \TAnn(\unit)\;=\; J_+,
\end{eqnarray*}
which follow by direct verification.
\end{proof}

\begin{example}\label{ExsVec}
If $\cC=\sVec$ and $V\in\cC$ a supervector space of dimension $m|n$, then $\TAnn(V)=\mP_{m,n}$, as now follows from the definition in Example~\ref{ExDagger}(2).
\end{example}

\begin{prop}
The inductive system $\Phi(\TAnn(X))$ is equal to $K_0(\mathbf{B}_X)$.
\end{prop}
\begin{proof}
This follows from the observations in \ref{SecPhiI}.
\end{proof}


\begin{remark}\label{ggd}
We have
$$g_n(\Ann(X))\;\le\; \dim_{\bk}\End(X^{\otimes n})\;\le\; \ell(X^{\otimes n})^2$$
and therefore
$$\gggr(\Ann(X))\;\le\; \mathtt{gd}(X).$$

\end{remark}


