\section{The complex numbers}\label{SecComp}

When the base field is the field $\mC$ of complex numbers, there are interesting classes of simple unitary $S_\infty \times S_\infty$-representations. Prime ideals in $\bk(S_\infty\times S_\infty)$ restrict to prime ideals in $\bk S_\infty$, say for the left factor $S_\infty<S_\infty^{\times 2}$). Hence the left annihilator $\LAnn(V)<\bk S_\infty$ of such a representation~$V$ must be a prime ideal in the list in Theorem~\ref{Prop:0}(1), and similarly for the right annihilator. In this section we identify these ideals.


\subsection{Spherical representations}



Consider the {\bf Thoma simplex}
$$\Omega\;\subset\;[0,1]^{\mZ_{>0}}\times [0,1]^{\mZ_{>0}}$$
of pairs $\omega=(\alpha,\beta)$
satisfying
$$\alpha_1\ge\alpha_2\ge \alpha_3\ge\cdots, \quad \beta_1\ge \beta_2\ge \beta_3\ge\cdots,\quad\gamma(\alpha,\beta):=\sum_{i=1}^\infty (\alpha_i+\beta_i)\le 1.$$

By \cite[Theorem~7.20]{BO} there is a bijection
$\omega\mapsto  T^\omega,$
between $\Omega$ and the set of isomorphism classes of simple unitary {\bf spherical} $S_\infty\times S_\infty$-representations. Here `spherical' means there exists a spherical vector in the representation, which is a vector $v$ such that $gv=vg$ for all $g\in S_\infty$. Here, and below, we write the action of $g\in S_\infty=S_\infty\times \{e\}$ on the left, and denote the action of $h\in S_\infty= \{e\}\times S_\infty$ by writing $h^{-1}$ on the right. 



\begin{theorem}\label{ThmSph}
Consider $\omega=(\alpha,\beta)\in \Omega$. If either $\gamma(\alpha,\beta)<1$ or $\alpha_i>0$ for all $i$ or $\beta_j>0$ for all $j$, then
$$\LAnn T^\omega\;=\;\RAnn T^\omega\;=\; 0.$$
In the remaining cases, set
$$m:=\max\{i\in\mN\mid \alpha_i\not=0\}\quad\mbox{and}\quad n:=\max\{i\in\mN\mid\beta_i\not=0\}.$$
Then we have
$$\LAnn T^\omega\;=\;\RAnn T^\omega\;=\; \mathfrak{P}_{m,n}.$$
\end{theorem}

\begin{remark}
Theorem~\ref{ThmSph} gives a negative answer to Zalesskii's question in \cite[Problem~5.12]{Za}, for the alternating group $A_\infty$. In fact, `$J_\chi=0$' (as defined in the proof of \ref{ThmSph} or \cite[Definition~5.8]{Za}) will be the case for `most' choices of extremal characters $\chi:A_\infty\to\mC$.
\end{remark}

Before we can give the proof of the theorem, we need to recall some definitions and results.




\subsubsection{} We follow the notion from \cite[Definition~1.7]{BO} of (extreme) characters $\chi: G\to\mC$ of groups $G$. For a finite group $G$ `extreme characters' are precisely the normalisation (such that $\chi(e)=1$) of usual (irreducible) characters, while `characters' now refer to positive linear combinations of usual (irreducible) characters that send the identity to $1$. We write $\chi^\lambda: S_n\to \mC$ for the function (extremal character) $\sigma\mapsto \chi(\sigma)/\chi(e)$, with $\chi$ the usual character of $D^\lambda$.

The set of characters $S_\infty\to\mC$ is in canonical bijection with the set of coherent systems of distributions on $\bY$, see \cite[Definition~3.4 and Proposition~3.5]{BO}, with an exchange of the `extremal' elements.

By Thoma's Theorem, see \cite[Theorems~3.12 and 3.15]{BO}, extreme characters of $S_\infty$ (or equivalently extreme coherent systems) are in bijection with elements of $\Omega$. We write the bijection as $\omega\mapsto \chi^\omega$. The representation $T^\omega$ is then characterised as follows: For a normalised spherical vector $v\in T^\omega$
\begin{equation}\label{eqsph}\chi^\omega(g)\;=\; (gv,v),\quad\mbox{ for all }\quad g\in S_\infty, \end{equation}
with $(\cdot,\cdot)$ the inner product of the Hilbert space $T^\omega$.




\subsubsection{}\label{limits} We will use an indirect description of the bijection $\omega\mapsto \chi^{\omega}$ mentioned above. Consider a path $\p$ in $\bY$. Although they are in general not well-defined, we can consider the pointwise limit function
\begin{equation}
\label{eqchi}\chi:=\lim_{n\to\infty} \chi^{\p(n)}\;:\; S_\infty\to\mC,
\end{equation}
and the limits
\begin{equation}\label{eqab}
\alpha_i\;:=\; \lim_{n\to\infty} \p(n)_i/n,\quad \beta_i\;:=\; \lim_{n\to\infty} (\p(n)^t)_i/n,\qquad i\in\mZ_{>0}.
\end{equation}
Vershik and Kerov proved in \cite[\S 5]{VK} that, for a given $\p$, the limit~\eqref{eqchi} exists if and only if limit~\eqref{eqab} exists. Moreover, we then have $\chi=\chi^\omega$, for $\omega:=(\alpha,\beta)\in \Omega$.

Moreover, as proved in \cite[Theorem~1]{VK}, every extremal character $\chi$ can be written as a limit \eqref{eqchi}, meaning the above completely describes the bijection. For our purposes, we need a slightly sharper statement, which can also be distilled from the work of Vershik and Kerov. To state it, we define the {\bf support} of a Thoma sequence $\omega\in \Omega$ as
the subset $\supp(\omega)\subset \bY$ of those $\lambda\vdash n$, for all $n$, such that $\chi^\lambda$ appears with non-zero coefficient in the expansion of $\chi^\omega|_{S_n}$ into (extremal) characters of $S_n$. The support corresponds to an inductive system, see \cite[Proposition~5.16]{Za}.

\begin{lemma}\label{Lem0}
Given $\omega\in \Omega$, there exists a path $\p$ in $\bY$ which is entirely contained in $\supp(\omega)$, so that $\omega$ is the limit obtained from $\p(n)$ as in \eqref{eqab}.
\end{lemma}
\begin{proof}
Following for instance \cite{VK}, the set $\cT(\bY)$ of paths on $\bY$ is a topological space by its inverse limit interpretation. Concretely, the open subsets are given by (finite) unions of cylinder subsets. A cyclinder subset of level $n$ is a subset comprising all paths that share a common initial segment of length~$n$.

Then there is a bijection between the set of coherent systems of distributions on $\bY$ and the set of Gibbs measures (called central Borel measures in \cite{VK}) on $\cT(\bY)$, see \cite[Proposition~7.11]{BO}. We describe one direction of the bijection. We start from a coherent system $\{P^{(n)}\}$, where $P^{(n)}$ is thus a probability measure on the finite set $\bY_n$. By definition of Borel measures, it is sufficient to determine the value of a Borel measure on the cylindrical sets. The Gibbs measure of the set corresponding to an initial segment
$$(\nu,\kappa,\ldots, \lambda\vdash n)$$ is given by $P^{(n)}(\lambda)$. 

Now, fix $\omega\in \Omega$, with corresponding $\chi^\omega$, coherent system $\{P^{(n)}\}$ and Gibbs measure $\mu^\omega$. By construction of $P^{(n)}$, we have $P^{(n)}(\lambda)\not=0$ if and only if $\lambda$ is in $\supp\omega$. It follows from the Vershik–Kerov ergodic theorem from \cite{VK}, see \cite[Corollary~7.19]{BO}, that $\mu^\omega$-almost every path $\p$ admits the limit \eqref{eqab}, producing $\omega$.

Now assume that the statement in the lemma is false. Then the set of paths with limit $\omega$ is contained in the union of cylinders corresponding to initial segments that end outside the support. By the above, this union has measure zero, contradicting the previous paragraph.
\end{proof}

\begin{remark}
The condition on $\p$ in Lemma~\ref{Lem0} is not automatic. For example $\p(n)=(n-1,1)$ is a path leading to the trivial character $\chi(\sigma)=1$ for all $\sigma\in S_\infty$. The lemma thus predicts that this $\chi$ can also be obtained as a limit from another path, and we can indeed take the path $\q(n)=(n)$.
\end{remark}

\begin{corollary}\label{CorSupp}
Consider $\omega=(\alpha,\beta)\in \Omega$. If either $\gamma(\alpha,\beta)<1$ or $\alpha_i>0$ for all $i$ or $\beta_j>0$ for all $j$, then
$\supp(\omega)=\bY$.
In the remaining cases, 
$$\supp(\omega)\;=\; \Phi^{(\infty^m,n^\infty)}$$
with $m,n$ as in Theorem~\ref{ThmSph}.
\end{corollary}
\begin{proof}
Assume first that the support of $\omega$ is not all of $\bY$. There there are $s,t\in\mN$ so that $\mu_{s+1}\le t$ for all $\mu\in \supp(\omega)$. Let $\p$ be any path as in Lemma~\ref{Lem0}. It follows that
$$\sum_{i=1}^s\alpha_i+\sum_{j=1}^t\beta_j\;=\;\lim_{n\to\infty} \frac{\sum_{i=1}^s \p(n)_i+\sum_{j=1}^t (\p(n)^t)_j}{n}\;=\;1,$$
which proves the first claim. 

Now assume that $\gamma(\alpha,\beta)=1$ and $\alpha_i=0$ iff $i>m$ and $\beta_j=0$ iff $j>n$. By considering the obvious requirements for a path to lead to limit~ $\omega$ via~\eqref{eqab}, we can use Lemma~\ref{Lem0} to show that
$$\Phi^{(\infty^m,n^\infty)}\;\subset\; \supp(\omega).$$
To show equality, we can consider a path which, for $r\gg$
is given by
$$\p(r)\;=\;(f(r),\lfloor r\alpha_2\rfloor,\ldots, \lfloor r\alpha_m\rfloor,\q(r)^t)$$
with
$$\q(r)\;=\;(\lfloor r\beta_1\rfloor-m,\ldots, \lfloor r\beta_n\rfloor -m),$$
and $f(r)\in\mN$ such that $\p(r)\vdash r$.
This path has limit $\omega$ under \eqref{eqab}, whence
$$\supp(\omega)\;\subset\; \Phi^{\p(\infty)}\;=\;\Phi^{(\infty^m,n^\infty)}.$$
This concludes the proof.
\end{proof}


\begin{proof}[Proof of Theorem~\ref{ThmSph}]
We can extend an extremal character $\chi$ to a $\mC$-linear function $\mC S_\infty\to\mC$ and set
$$J_\chi\;:=\;\{x\in \mC S_\infty\mid \chi(xg)=0,\; \forall g\in S_\infty\}.$$
Then, with $v$ the normalised spherical vector of $T^\omega$, and using \eqref{eqsph},
\begin{eqnarray*}
\LAnn T^\omega&=& \{x\in \mC S_\infty\mid (xgv, hv)=0,\;\;\forall g,h\in S_\infty\}\\
&=& \{x\in \mC S_\infty\mid (xgh^{-1}v,v)=0,\;\;\forall g,h\in S_\infty\}\;=\; J_{\chi^\omega}
\end{eqnarray*}
and similarly for the right annihilator.

Next we can observe that 
$J_{\chi^\omega}= I(\supp(\omega)), $
so that the conclusion follows from Corollary~\ref{CorSupp}.
\end{proof}



\subsection{Olshanski – Okounkov admissible representations}

Spherical representations belong to a broader class of `admissible' representations for $S_\infty\times S_\infty$. The classification of these representations was initiated by Olshanski and concluded by Okounkov in \cite{Ok}. Here, we determine their annihilator ideals, bu we crucially use as input a result announced in \cite{VN} by Vershik and Nessonov without proof in the literature.

\subsubsection{}\label{SecTrOl} By a `Young distribution' of size $d\in\mN$, we refer to a function from $[-1,1]$ to $\bY$ such that the sum of all sizes of partitions in the image is $d$. In particular, for all but finitely many points in $[-1,1]$, the value is $\varnothing$.

By \cite[Theorem~3]{Ok}, the (isomorphism classes) of irreducible admissible representations are 
$V(\omega,\Lambda,M),$
where $\omega\in \Omega$, and $\Lambda$ and $M$ are two Young distributions of the same size $d$, called the depth of $V(\omega,\Lambda,M)$, such that
$$\begin{cases}\ell(\Lambda(x))+\ell(M(x))\;\le\; \sharp\{i\in\mZ_{>0}\mid \alpha_i=x\},&\; x>0,\\
\ell(\Lambda(x)^t)+\ell(M(x)^t)\;\le\; \sharp\{j\in\mZ_{>0}\mid \beta_j=-x\},&\; x<0.
\end{cases}$$


\subsubsection{}\label{ClaimVN} It was announced in \cite{VN} that the unitary representations of $\mC S_\infty$ given by (restriction to the left copy of $S_\infty$)
$$V(\omega,\Lambda,M)\quad\mbox{and}\quad\Ind^{S_\infty}_{S_r\times S_\infty[r]} (D^\lambda\boxtimes T^\omega)$$
are quasi-equivalent,
where $\lambda=\Lambda(0)$ and $r=|\lambda|$. Our proof of the following theorem is contingent on this claim for the case $\omega=(\alpha,\beta)$ with $\sum_{i\le m}\alpha_i+\sum_{j\le n}\beta_j=1$ for finite $m,n$.



\begin{theorem}\label{ThmAdm} Consider an irreducible admissible representation $V(\omega,\Lambda,M)$ with $\omega=(\alpha,\beta)$.
If either $\gamma(\alpha,\beta)<1$ or $\alpha_i>0$ for all $i$ or $\beta_i>0$ for all $i$, then
$$\LAnn_{\bk S_\infty}V(\omega,\Lambda,M)\;=\;0\;=\;\RAnn_{\bk S_\infty}V(\omega,\Lambda,M).$$
In the remaining cases, set
$$m:=\max\{i\in\mN\mid \alpha_i\not=0\},\qquad n:=\max\{i\in\mN\mid\beta_i\not=0\},$$
$\lambda=\Lambda(0)$ and $\mu=M(0)$. Then
$$\LAnn_{\bk S_\infty} V(\omega,\Lambda,M)\;=\; I_{(\infty^m,n+\lambda_1,n+\lambda_2,\ldots)}\quad\mbox{and}$$
$$\RAnn_{\bk S_\infty} V(\omega,\Lambda,M)\;=\; I_{(\infty^m,n+\mu_1,n+\mu_2,\ldots)}.$$
\end{theorem}


\begin{remark}
Since there is no restriction on $\Lambda(0)$, Theorem~\ref{ThmAdm} implies that, contrary to spherical representations, the (left) annihilator ideals of admissible representations range over all prime ideals.
\end{remark}

We start the preparation for the proof. For $m\in\mZ_{>0}$, we denote by $S_\infty[m]<S_\infty$ the copy of $S_\infty$ that fixes every element of the set $\{1,2,\ldots, m\}$.


\begin{lemma}\label{Lem:LR}
For a partition $\nu\vdash j$ satisfying $\nu_{s+1}\le t$, for some $s,t\in\mN$, and partitions $\lambda\vdash r$ and $\kappa\vdash r+j$, the condition
$$[\Ind^{S_{r+j}}_{S_r\times S_j} D^\lambda\boxtimes D^\nu: D^\kappa]\;\not=\;0$$
implies that $\kappa_{s+i}\le t+\lambda_i $ for all $i>0$.
\end{lemma}
\begin{proof}
Immediate from the Littlewood-Richardson rule.
\end{proof}
For the remainder of the section, fix a triple $(\omega, \Lambda,M)$ as in \ref{SecTrOl}.

\begin{lemma}\label{LemSub}
We have 
$$\LAnn V(\omega,\Lambda,M)\;\subset\;\LAnn T^\omega\;\supset\; \RAnn V(\omega,\Lambda,M).$$
\end{lemma}
\begin{proof}
By construction of  $V(\omega,\Lambda,M)$, see for instance \cite[\S 1.2]{Ok}, its restriction to $S_\infty[d]\times S_\infty[d]$ has a direct summand isomorphic to $T^\omega$ (using the canonical identification $S_\infty[d]\simeq S_\infty$). Hence
$$\LAnn V(\omega,\Lambda,M)\cap \bk S_\infty[d]\;\subset\; I,$$
with $I$ the ideal $\LAnn T^\omega$ interpreted in $\bk S_\infty[d]$. The claim then follows by conjugation.
\end{proof}




\begin{proof}[Proof of Theorem~\ref{ThmAdm}]
By Lemma~\ref{LemSub} and Theorem~\ref{ThmSph}, we can focus on the final case. By \ref{ClaimVN}, the left annihilator of $ V(\omega,\Lambda,M)$ equals the annihilator of $\Ind^{S_\infty}_{S_r\times S_\infty[r]} (D^\lambda\boxtimes T^\omega)$.
By equation~\eqref{EqInd} and Theorem~\ref{ThmSph}, we then find
that 
$$\LAnn V(\omega,\Lambda,M)\;=\; \Ann \Ind^{S_\infty}_{S_r\times S_\infty[r]}(D^\lambda\boxtimes\varinjlim_i D^{\p(i)})$$
for any path $\p$ with $\p(\infty)=(\infty^m,n^\infty)$.
Moreover
$$\Ind^{S_\infty}_{S_r\times S_\infty[r]}(D^\lambda\boxtimes\varinjlim_i D^{\p(i)})\;\simeq\; \varinjlim_i \Ind^{S_{r+i}}_{S_r\times S_i}(D^\lambda\boxtimes D^{\p(i)}).$$
Hence, the inductive system corresponding to $\LAnn V(\omega,\Lambda,M)$ consists of all simple modules that appear in restrictions (to arbitrary $S_j<S_{r+m}$) of modules $\Ind^{S_{r+m}}_{S_r\times S_m}(D^\lambda\boxtimes D^{\mu})$ for $\mu\vdash m$ with $\mu_{m+1}\le n$. It follows quickly from Lemma~\ref{Lem:LR} that this system is precisely $\Phi_{(\infty^m,n+\lambda_1,n+\lambda_2,\ldots)}$, with notation as in Corollary~\ref{Cor:Lem}.
\end{proof}






