\section{Positive characteristic}\label{SecTC}

In this section we consider an algebraically closed field $\bk$ of characteristic $p>0$. We investigate the annihilator map
$$\TAnn_{\cC}:\;M^{\oplus}(\cC)\;\to\;\TSpec\bk S_\infty$$
for tensor categories $\cC$ over $\bk$. We assume throughout that $\cC$ is a tensor category of moderate growth.

\subsection{Injectivity of the annihilator map}



\begin{prop}\label{PropInj}
\begin{enumerate}
\item If $\cC$ is Frobenius exact, then $\TAnn_{\cC}$ factors via $M^{\oplus}(\cC)\tto M(\cC)$.
\item If $\TAnn_{\cC}$ is injective, then for any non-split inclusion $\xi:\unit\to X$ in $\cC$, there  is $n\in\mZ_{>0}$ for which $\xi^n:\unit\to\Sym^n X$ is zero.
\end{enumerate}
\end{prop}
\begin{proof}
Property (1) follows from the characterisation of Frobenius exactness in \cite[Theorem~C(iv)]{Tann}. Indeed, the latter states that any short exact sequence becomes split after applying a faithful symmetric monoidal functor.

For part (2), consider the short exact sequence
$$0\to\unit\xrightarrow{\xi} X\to Y\to 0$$
defined by $\xi$. By assumption, the inclusion
$$\TAnn(X)\;\subset\; \TAnn(\unit\oplus Y)$$
is strict, and the conclusion follows from \cite[Corollary~3.2.6]{Tann}. 
\end{proof}


In characteristic zero, Theorem~\ref{ThmsVec}(3) shows that $\TAnn_{\cC}$ is injective if and only if $\cC$ is incompressible. By Proposition~\ref{PropInj}(2), a necessary condition for injectivity is a condition that is conjectured to be true for all known incompressible tensor categories ($\Ver_{p^\infty}$ and its tensor subcategories), and verified for $\Ver_{2^\infty}$ in \cite[Theorem~9.2.1]{Incomp}. This leads us to the following conjecture, in analogy with Theorem~\ref{ThmsVec}(3) and (4).
\begin{conjecture}\label{ConjVer}
The annihilator map
$$\TAnn_{\cC}:\;M^{\oplus}(\cC)\to\TSpec\bk S_\infty$$
is injective if and only if $\cC$ is incompressible, and a semiring isomorphism if and only if $\cC=\Ver_{p^\infty}$.
\end{conjecture}

\begin{remark}
\begin{enumerate}
\item A consequence of the conjecture would be that classifying (T-)prime ideals in $\bk S_\infty$ is a wild problem.
\item Conjecture~\ref{ConjVer} is a stronger version of \cite[Conjecture~1.4]{BEO}. Indeed, assume that Conjecture~\ref{ConjVer} is true and let $\cC$ be an arbitrary incompressible tensor category. By \cite[Corollary~5.2.8]{Incomp}, there exists an incompressible tensor category $\cD$ containing both $\Ver_{p^\infty}$ and $\cC$ as tensor subcategories. Then $\TAnn_{\Ver_{p^\infty}}$ factors via $\TAnn_{\cD}$. However, under Conjecture~\ref{ConjVer}, the former is an isomorphism, while the latter is injective, implying that $M^{\oplus}(\Ver_{p^\infty})\hookrightarrow M^{\oplus}(\cD)$ is an isomorphism, forcing $\cD=\Ver_{p^\infty}$ and hence $\cC\subset \Ver_{p^\infty}$. The conclusion follows from \cite[Theorem~A]{Incomp}.
\end{enumerate} 
\end{remark}


While Conjecture~\ref{ConjVer} seems currently out of reach, the following special case is more tractable. It is an analogue of Theorem~\ref{ThmsVec}(3), but the proof of the latter fails for $p>3$. By \cite{CEO} it suffices to show that for a semisimple tensor category $\cC$ of moderate growth, the unique tensor functor $\cC\to\Ver_p$ is the inclusion of a subcategory if $K_0(\cC)\to K_0(\Ver_p)$ is injective.
\begin{conjecture}\label{ConjVer}
Let $\cC$ be Frobenius exact.
If the annihilator map
$$\TAnn_{\cC}:\;M^{\oplus}(\cC)\to\TSpec\bk S_\infty$$
is injective, then $\cC$ is a tensor subcategory of $\Ver_p$ (and thus incompressible).
\end{conjecture}



\subsection{Symmetrisers in ideals}
To establish the first steps towards Conjecture~\ref{ConjVer}, we introduce invariant of ideals, complementary to the ones in Subsection~\ref{SecGrowth}.

\subsubsection{}\label{as} Denote the symmetriser and skew symmetriser in $\bk S_n$ by $s_n$ and $a_n$. Let $I<\bk S_\infty$ be a non-zero ideal. It follows from \cite[Proposition~A.1]{CEO}, see also the proof of \cite[Lemma~4.10]{CEO}, that $s_n\in I$ for some $n$. We can thus define
$$\sss(I)\;:=\;\max\{n\in\mZ_{>0}\mid s_n\not\in I\}$$
and similarly
$$\aaa(I)\;:=\;\max\{n\in\mZ_{>0}\mid a_n\not\in I\}.$$
By convention, $\sss(\bk S_\infty)=0= \aaa(\bk S_\infty).$

\begin{example}
For the augmentation ideal $J_+$ we have
$$\aaa(J_+)=1\quad\mbox{and}\quad\sss(J_+)=p-1.$$
\end{example}



\begin{lemma}
For non-zero ideals $I,J$ in $\bk S_\infty$, we have
$$\sss(I\dagger J)\;=\; \sss(I)+\sss(J)\quad\mbox{and}\quad \aaa(I\dagger J)\;=\;\aaa(I)+\aaa(J).$$
\end{lemma}
\begin{proof}
We write the proof for symmetrisers. We can observe that, for $r,t\in\mZ_{>0}$, we have $s_{r+t}=s'(s_r\bullet s_t)$, for $s'$ a sum of shortest coset representatives of $S_{r+t}/(S_r\times S_t)$. Hence, if $s_m\not\in I$ and $s_n\not\in J$, it follows that $s_{m+n}$ does not act trivially on the generator $1\otimes 1\otimes 1$ of $\Ind^{S_{m+n}}_{S_m\times S_n}(\bk S_m/I_m\boxtimes \bk S_n/J_n)$. Hence we find
$$\sss(I\dagger J)\;\ge\; \sss(I)+\sss(J).$$
To get the inequality in the other direction, we can use additionally that the symmetriser is in the centre of the group algebra. We can observe that $s_{m+1}\in I$ and $s_{n+1}\in J$ imply that $s_{m+n+1}$ acts trivially on 
$$\Ind^{S_{m+n+1}}_{S_i\times S_j}(\bk S_i/I_i\boxtimes \bk S_j/J_j)$$ for $i+j=m+n+1$, since either $i\ge m+1$ or $j\ge n+1$.
\end{proof}


\begin{lemma}\label{lemfin}
For any $I\in \TSpec\bk S_\infty$, we have $\gggr(I)\in\mR_{\ge 0}$.
\end{lemma}
\begin{proof}
As recalled above, we have $s_n\in I$, for some $n$. Hence $ \TAnn(V)\subset I$, for a vector space $V$ of dimension $n$, by classical invariant theory. Thus
$$\gggr(I)\;\le\; \gggr(\TAnn(V))\;=\, n,$$
see Lemma~\ref{Lemmag}(1).
\end{proof}

\subsection{The annihilator map for Verlinde categories}
Conjecture~\ref{ConjVer} predicts that $\TAnn_{\Ver_{p^n}}$ is injective. Here we verify some small cases.
\begin{theorem}\label{ThmVer}
\begin{enumerate}
\item The annihilator map $\TAnn_{\Ver_4}$
is injective.
\item For every prime $p$, the annihilator map
$\TAnn_{\Ver_p}$
is injective.
\end{enumerate}
\end{theorem}
\begin{proof}
First we prove part (1). There are three indecomposable objects in $\Ver_4$, see \cite{BE}, the unit $\unit$, a simple projective $V$ and the projective cover $P$ of $\unit$. We will use
$$V^{\otimes 2}\simeq P\quad\mbox{and}\quad V\otimes P\simeq V^2.$$ We associate three invariants to the annihilator of an object $X$ in $\Ver_4$. With $K:=\TAnn(V)$, set $x_1(X):=\sss(\TAnn(X))$ and
$$x_2(X):=\sss(K\Join\TAnn(X))\quad\mbox{and}\quad x_3(X):=\sss(K\Join K\Join \TAnn(X)).$$ 
In practice, we can use $K\Join\TAnn(X)=\TAnn(V\otimes X)$.

If
$X$ is $\unit^l\oplus V^m\oplus P^n,$
then by \cite[Example~4.6]{CEO} and the above tensor products
$$x_1(X)= l+2m+4n,\quad x_2(X)=2l+4m+4n,\quad x_3(X)=4l+4m+8n.$$
It now follows from the observation
$$\det\left(\begin{array}{ccc}
1&2&4\\
2&4&4\\
4&4&8
\end{array}\right)\;=\;-16\;\not=\; 0$$
that $\TAnn_{\Ver_4}$ is injective.

For part (2), we consider $\Ver_p$ as the semisimplification of $\mathrm{Rep} C_p$, so that the simple $L_i\in \Ver_p$, for $0<i<p$, is the image of the indecomposable $C_p$-representation of dimension $i$, see \cite{Os}. As in part (1), for $X\in\Ver_p$ we define $x_i(X):=\aaa(\TAnn(L_2^{\otimes i-1}\otimes X))$, for $i\in\mZ_{>0}$, which only depend on $\TAnn(X)$. For $W\in\mathrm{Rep} C_p$, with image $\overline{W}\in\Ver_p$, the value $\aaa(\TAnn(\overline{W}))$ is the (vector space) dimension of $W$ minus the dimension of the maximal projective summand.
For $i+j\le p$, we thus have
$x_i(L_j)=2^{i-1}j$ and for $i+j=p+1$, we have
$x_i(L_j)=2^{i-1}j-p$. Again it suffices to show that the determinant of the $(p-1)\times(p-1)$-matrix $(x_i(L_j))_{1\le i,j\le p-1}$ is non-zero. After subtracting the first row $2^{i-1}$ times from the $i$-th row, we obtain a matrix $A$ with 
$A_{ij}=0$ if $i+j<p$ and $i>1$, and $A_{ij}=-p$ if $i+j=p+1$, hence
$$\det((x_i(L_j))_{ij})\;=\; \det(A)\;=\; (-1)^{\frac{(p+1)(p-2)}{2}}p^{p-2}\;\not=\; 0,$$
as desired.
\end{proof}


\begin{remark}
The method in the proof of Theorem~\ref{ThmVer} would extend to the essential image of the defining monoidal functor
$$F:\mathrm{Tilt} SL_2\to\Ver_{p^n},$$
see \cite{BEO, AbEnv}, if it remains true that 
$$\aaa(\TAnn_{\Ver_{p^n}}(FT_i))=\dim_{\bk}T_i,\quad\mbox{ for }\quad0\le i\le p^n-2,$$ where $T_i$ is the $SL_2$-tilting module of highest weight $i$. The cases dealt with in Theorem~\ref{ThmVer} are precisely those for which $F$ is essentially surjective.
\end{remark}


We conclude with an observation regarding the growth rate of ideals corresponding to $\Ver_p$.

\begin{prop}\label{Propgdg}Let $p$ be an odd prime and let $J_1,J_2,\ldots, J_{p-1}$ be the exhaustive list of maximal ideals in $\bk S_\infty$ from \cite{BK}. Then
$$\gggr(J_j)\;=\; \sin\left(\frac{\pi j }{p}\right)/\sin \left(\frac{\pi}{p}\right),\quad\mbox{for}\quad 1\le j<p.$$
Equivalently, for any simple object $V$ in $\Ver_p$, we have
$$\gggr(\TAnn(V))\;=\;\mathtt{gd}(V)$$
for the growth dimension $\mathtt{gd}$ from \cite{CEO}.
\end{prop}
\begin{proof}
Firstly, by \cite[Lemma~8.3]{CEO}, the growth dimension of $V$ equals its Frobenius-Perron dimension, so $\mathtt{gd}(L_j)=\sin\left(\frac{\pi j }{p}\right)/\sin \left(\frac{\pi}{p}\right)$, see for instance \cite{BEO}, and it suffices to prove the second claim. 
For that claim, we already know that $\gggr(\TAnn(V)) \le \mathtt{gd}(V)$, by Remark~\ref{ggd}.

By \cite[Lemma~8.5]{CEO}, it is sufficient to prove $\gggr(\TAnn(L_j))\ge\mathtt{gd}(L_j)$ for $L_j$ regarded as an object in the fusion category $\Ver_p(SL_j)$, as done in the proof of \cite[Theorem~4.1.1]{PolyFun}. The advantage there is that, as observed {\it loc. cit.}, the braiding homomorphism in $\Ver_p(SL_j)$
$$\bk S_n\;\to\; \End(L_j^{\otimes n})$$
is surjective. Now, let $d$ be the number of isomorphism classes of simple objects in $\Ver_p(SL_j)$. We then find
$$\ell(L_j^{\otimes n})^2\;\le\; d\,\dim\End(L_j^{\otimes n})\;=\;d\,\dim (\bk S_n/\TAnn(L_j)_n).$$
Taking the limit of the $2n$-th roots shows $\mathtt{gd}(L_j)\le \gggr(\TAnn(L_j))$.
\end{proof}

\begin{question}
Does the second equality in Proposition~\ref{Propgdg} remain valid for all objects in  $\Ver_p$? Equivalently, is $\gggr$ additive on the submonoid of $(\TSpec\bk S_\infty,\dagger)$ generated by the maximal ideals. 
\end{question}





