  \beta_{i,2}{:=}{\underline{\mu}_i-r\over (1-p)\overline{\sigma}^2_i},\qquad\qquad
  \beta_{i,3}{:=}{\overline{\mu}_i-r\over (1-p)\overline{\sigma}^2_i},\hspace{1.7cm}
  \\[2mm]
  K^1_{i,1}:=\frac{p-1}{2}\overline\pi^2\overline\sigma_i^2
  +(\underline\mu_i-R)\overline\pi+R,\qquad
  K^1_{i,2}:={(\underline{\mu}_i-R)^2\over 2(1-p)\overline{\sigma}_i^2}+R,\qquad
  K^1_{i,3}:=\frac{p-1}{2}\overline\sigma_i^2+\underline{\mu}_i,\;\,
  \\[2mm]
  \quad K^1_{i,4}:={(\underline{\mu}_i-r)^2\over 2(1-p)\overline{\sigma}_i^2}+r,\quad
  K^1_{i,5}:=r,\quad
  K^1_{i,6}:={(\overline{\mu}_i-r)^2\over 2(1-p)\overline{\sigma}_i^2}+r,\quad
  K^1_{i,7}:=\frac{p-1}{2}\underline\pi^2\overline\sigma_i^2
  +(\overline\mu_i-r)\underline\pi+r.
\eee



