\begin{remark}
The above Theorem implies that not all data assets hold value, only those of sufficient quality are valuable. For instance, if the estimation based on a particular data asset results in
$\underline{\mu}_2\leq r\leq \overline{\mu}_2$, then we have $\beta_{i,2}\leq 0\leq \beta_{i,3},  K(\mathbb{B}_i)=r, i=1,2$, which means  that the investor would fully invest in a risk-free asset regardless of the presence or absence of this data asset, which means this data asset is devoid of value and its purchase price would be zero.
\end{remark}

In the following, we suppose that  the ambiguities about drift and volatility are correlated, a higher return is associated with a larger risk.

\begin{assumption}\label{correlation}
Assume that $n=1$, and $R=r,\mathbb{A}=\mathbb{R}\times[\,\underline{c},\overline{c}\,]$ and
$\mathbb{B}_i=\{(\mu,\sigma):\mu=\underline{\mu}_i+\alpha,
\sigma=\underline{\sigma}_i^2+k\alpha^q,\alpha\in[\,0,\overline{\alpha}_i\,]\,\}$,
where $\underline{c},\overline{c},\underline{\mu}_i,\underline{\sigma}_i,k,q,\overline{\alpha}_i$ are constants satisfying $\underline{c}\leq \overline{c}$, and $\underline{\mu}_1\leq\underline{\mu}_2$ and
$$
\underline{\sigma}_2\geq\underline{\sigma}_1\geq0,\quad
k>0,\quad 0<q<1,\quad \overline{\alpha}_2\geq0,\quad
\overline{\alpha}_1\geq\max\left[\overline{\alpha}_2
+(\underline{\mu}_2-\underline{\mu}_1),\,
\left(\overline{\alpha}_2^q+\frac{\underline{\sigma}_2^2-
\underline{\sigma}_1^2}{k}\right)^{\frac{1}{q}}\right].
$$
\end{assumption}


 The limiting case $q=1$ means that the relationship
between the ambiguity about drift and the ambiguity about the
volatility square is linear, which is just Example 2.4 in
\cite{Epstein}. The other spectrum $q=0$ means no ambiguity about
volatility. Finally, $0<q<1$ means that the relationship between the ambiguity about drift and the ambiguity about the volatility
square is sub-linear, which is just example 4.3 in \cite{YLZ}.

\begin{theorem}\label{th-ex2}
Under Assumption \ref{correlation}, the constant  $K(\mathbb{B}_i)=(\mu_i^*-r)^2/(2(1-p)(\sigma^{*}_i)^2)+r$, where
$$
 \mu^*_i=\underline{\mu}_i+\alpha^*_i,\;\;
 \sigma^*_i=\sqrt{\underline{\sigma_i}^2+k(\alpha^*_i)^q},\;\;
 \alpha^*_i=\left\{
 \begin{array}{ll}
 r-\underline{\mu}_i,\;\; &-\overline{\alpha}_i<\underline{\mu}_i-r\leq 0;
 \\[2mm]
 \widehat{\alpha}_i, &0<\underline{\mu}_i-r
 <[\,2\underline{\sigma}_i^2\overline{\alpha}_i^{1-q}
 +{k(2-q)\overline{\alpha}_i\,]/(kq)};
 \\[2mm]
 \overline{\alpha}_i,&\mbox{otherwise},
 \end{array}
 \right.
$$
where $\widehat{\alpha}_i$ is the unique solution of the following algebra equations (for the case $\underline{\mu}_i-r>0$),
\bee
 2\underline{\sigma}_i^2+{k(2-q)\alpha^q-k q(\underline{\mu}_i-r)\alpha^{q-1}}=0.
\eee
\end{theorem}

The proof can be refer to Theorem 4.4 in \cite{YLZ}.



\begin{assumption}\label{BP}{\bf(Assumption in \cite{BP} and \cite{PWZ})}
Assume $R=r,\mathbb{A}=\mathbb{R}^n\times[\,\underline{c},\overline{c}\,]$, where $\underline{c},\overline{c}$ are constants satisfying $\underline{c}\leq \overline{c}$, and
$\mathbb{B}_i=\{(\mu,\Sigma):(\mu-\widehat{\mu})^{\rm T}\Sigma^{-1}(\mu-\widehat{\mu})\leq \epsilon_i^2, \Sigma\in\mathbb{B}^\Sigma_i\}$,
where $\widehat{\mu}$ is a constant vector, $\epsilon_i$ are  positive constants satisfying $\epsilon_1\geq \epsilon_2$, and $\mathbb{B}^\Sigma_i$ are non-empty compact subset of ${\cal S}^n_+$ satisfying that there exist constants $\delta>0$ such that
$$
 \xi^{\rm T}\Sigma\xi\geq\delta|\xi|^2,\;\;\forall\;\;
 \xi\in\mathbb{R}^n,\Sigma\in\mathbb{B}^\Sigma_1,\qquad
 \mathbb{B}^\Sigma_1\supset\mathbb{B}^\Sigma_2.
$$
\end{assumption}

\begin{theorem}\label{th-BP}
Under Assumption \ref{BP}, the constant
\be\label{eq-H}
 K(\mathbb{B}_i)=
 \frac{\left[\max\left(\min\limits_{x_\Sigma\in \mathbb{B}^\Sigma_i}H(x_\Sigma)-\epsilon_i,0\right)\right]^2}
 {2(1-p)}+r,\qquad
 H(x_\Sigma):=\sqrt{\left(\widehat{\mu}-r{\bf 1}_n\right)^{\rm T}
 (x_\Sigma)^{-1}\left(\widehat{\mu}-r{\bf 1}_n\right)}.
\ee
\end{theorem}

The proof can be found in \cite{BP}. For the convenience of reading, we provide a simplified proof based on our results.

\begin{proof}
From \eqref{eq-K,eq-f} and repeating the similar argument in Remark \ref{re-saddle point}, we know that
$$
 K(\mathbb{B}_i)=\min\limits_{x_\Sigma\in \mathbb{B}^\Sigma_i}\widehat{K}_1(x_\Sigma),\;\;
 \widehat{K}_1(x_\Sigma):=
 \max\limits_{x_\pi\in \mathbb{R}^n}\widehat{K}_2(x_\Sigma,x_\pi),\;\;
 \widehat{K}_2(x_\Sigma,x_\pi):=
 \min\limits_{x_\mu\in\{x_\mu:(x_\mu,x_\Sigma)\in \mathbb{B}_i\}}F^1(x_\pi;x_\mu,x_\Sigma).
$$

In the first, we calculate $\widehat{K}_2(x_\Sigma,x_\pi)$. According to Karush-Kuhn-Tucker Condition, we know that $x_\mu^*$ and the Lagrange multiplier $\Lambda^*$ satisfy $\Lambda^*\geq0$, and
$$
 x_\pi+2\Lambda^*(x_\Sigma)^{-1}(x_\mu^*-\widehat{\mu})=0,\;\;
 \Lambda^*\left[(x_\mu^*-\widehat{\mu})^{\rm T}(x_\Sigma)^{-1}(x_\mu^*-\widehat{\mu})-\epsilon_i^2\right]=0,\;\; (x_\mu^*-\widehat{\mu})^{\rm T}(x_\Sigma)^{-1}(x_\mu^*-\widehat{\mu})-\epsilon_i^2\leq0.
$$
So we deduce that
$$
  x_\pi^{\rm T}x_\Sigma x_\pi=\left(2\Lambda^*(x_\Sigma)^{-1}(x_\mu^*-\widehat{\mu})\right)^{\rm T}x_\Sigma \left(2\Lambda^*(x_\Sigma)^{-1}(x_\mu^*-\widehat{\mu})\right)=4(\Lambda^*)^2(x_\mu^*-\widehat{\mu})^{\rm T}(x_\Sigma)^{-1}(x_\mu^*-\widehat{\mu})=4(\epsilon_i\Lambda^*)^2,
$$
and
$$
 \Lambda^*= \frac{\sqrt{x_\pi^{\rm T}x_\Sigma x_\pi}}{2\epsilon_i},\;\;
 x_\mu^*=\widehat{\mu}- \frac{\epsilon_i x_\Sigma x_\pi}{\sqrt{x_\pi^{\rm T}x_\Sigma x_\pi}},\;\;
 \widehat{K}_2(x_\Sigma,x_\pi)={p-1\over 2}\,x_\pi^{\rm T}x_\Sigma x_\pi-\epsilon_i\sqrt{x_\pi^{\rm T}x_\Sigma x_\pi}+\left(\widehat{\mu}-r{\bf 1}_n\right)^{\rm T}x_\pi+r
$$
provided $x_\pi\neq0$. Note that $\widehat{K}_2(x_\Sigma,x_\pi)$ still takes the above form even if $x_\pi=0$.

In order to obtain $\widehat{K}_1(x_\Sigma)$, we denote $z=\sqrt{x_\pi^{\rm T}x_\Sigma x_\pi}$, then we know that
$$
 \widehat{K}_1(x_\Sigma)
 =\max\limits_{z\geq0}\widehat{K}_{3}(z,x_\Sigma),\quad
 \widehat{K}_{3}(z,x_\Sigma):=
 \max\left\{\widehat{K}_2(x_\Sigma,x_\pi):x_\pi^{\rm T}x_\Sigma x_\pi=z^2\right\}.
$$

According to Karush-Kuhn-Tucker Condition, we know that $x_\pi^*$ and the Lagrange multiplier $\Lambda^*$ satisfy $\Lambda^*\leq0$, and
$$
 \widehat{\mu}-r{\bf 1}_n+2\Lambda^* x_\Sigma x_\pi^*=0,\qquad
 (x_\pi^*)^{\rm T}x_\Sigma x_\pi^*=z^2.
$$

As above, we deduce that
$$
  \Lambda^*=\frac{-H(x_\Sigma)}{2z},\qquad
  x_\pi^*=\frac{z(x_\Sigma)^{-1}\left(\widehat{\mu}-r{\bf 1}_n\right)}{H(x_\Sigma)},\qquad
  \widehat{K}_{3}(z,x_\Sigma)={p-1\over 2}\,z^2+[H(x_\Sigma)-\epsilon_i]z+r
$$
provided $\widehat{\mu}-r{\bf 1}_n\neq0$, where $H(x_\Sigma)$ is defined in \eqref{eq-H}. Note that $\widehat{K}_3(z,x_\Sigma)$ still takes the above form even if $\widehat{\mu}-r{\bf 1}_n=0$.

Since
$$
 \partial_z\widehat{K}_3=
 (p-1)\left[z-\frac{H(x_\Sigma)-\epsilon_i}{1-p}\right]\;\;
 \left\{
 \begin{array}{ll}
 >0,&z<[H(x_\Sigma)-\epsilon_i]/(1-p),
 \\[2mm]
 <0,&z>[H(x_\Sigma)-\epsilon_i]/(1-p),
 \end{array}
 \right.
$$
we deduce that
$$
 \widehat{K}_1(x_\Sigma)
 =\frac{\left[\max\left(H(x_\Sigma)-\epsilon_i,0\right)\right]^2}
 {2(1-p)}+r.
$$
From the above expression of $\widehat{K}_1(x_\Sigma)$, it is not difficult to obtain the conclusion.
\end{proof}



\begin{assumption} \label{as-sample sizes} Assume $R=r, n=1,\mathbb{A}=\mathbb{R}\times[\,0,+\infty\,]$, and
$$
 \mathbb{B}_i=\left[\,\widehat{\mu}-{t_{1-\alpha/2}(N_i-1)s\over \sqrt{N_i}},\,\widehat{\mu}+{t_{1-\alpha/2}(N_i-1)s\over \sqrt{N_i}}\,\right]\times\left[\,{(N_i-1)s^2\over \chi^2_{1-\alpha/2}(N_i-1)},\,{(N_i-1)s^2\over \chi^2_{\alpha/2}(N_i-1)}\,\right],
$$
where $\widehat{\mu}$ is the sample mean, and $s^2$ is the sample variance, and $N_i$ are the sample sizes satisfying $N_2>N_1$, and $1-\alpha$ is the confidence level.
\end{assumption}

\begin{theorem}\label{th-sample sizes}
Under Assumption \ref{as-sample sizes}, the constant
$$
 K(B_i)={\max\left[|\widehat{\mu}-r|
 -\frac{t_{1-\alpha/2}(N_i-1)s}{\sqrt{N_i}},\,0\right]^2\over 2(1-p)}
 {\chi^2_{\alpha/2}(N_i-1)\over(N_i-1)s^2}+r.
$$
\end{theorem}


The proof follows from Theorem \ref{th-ex1}.


\section{Numerical Illustrations}
Based on the above theoretical discussions, now we describe how to apply our data asset pricing method based on numerical illustrations. For the sake of simplicity, we use the simplest data asset: a dataset to study the nature of data asset price. The basic idea is as follows. The buyer has an existing dataset $\mathcal{X}$ and plans to purchase a new dataset $\mathcal{Y}$. The dataset seller has knowledge about both $\mathcal{X}$ and $\mathcal{Y}$, and calculates the maximum price $P$ that the buyer is willing to pay for $\mathcal{Y}$. Following \cite{GI}, we quantify the ambiguity set as confidence intervals.

The set $\mathbb{B}$ is derived using the following procedures. First, we get the confidence intervals of $\mu$ and $\sigma$ from $\mathcal{X}$ and $\mathcal{Y}$ as $\mathcal{I}^{j}_{\mu}$ and $\mathcal{I}^{j}_{\sigma}$, where $j\in\{\mathcal{X},\mathcal{Y}\}$. Then,
$$
\mathbb{B}_1:= \left(\mathcal{I}^{\mathcal{X}}_{\mu}\lor \mathcal{I}^{\mathcal{Y}}_{\mu}\right)\times \left(\mathcal{I}^{\mathcal{X}}_{\sigma}\lor \mathcal{I}^{\mathcal{Y}}_{\sigma}\right),\qquad
\mathbb{B}_2:= \mathcal{I}^{\mathcal{Y}}_{\mu}\times \mathcal{I}^{\mathcal{Y}}_{\sigma},
$$
where for two intervals $I_1$ and $I_2$, $I_1\lor I_2$ means the smallest interval containing $I_1$ and $I_2$.
It is straightforward that $\mathbb{B}_1 \supset \mathbb{B}_2$, so that our assumption for \eqref{indifference equality} is satisfied.

For $i\in\{\mathcal{X},\mathcal{Y}\}$, denote $\mathbb{B}_i = [\underline{\mu}^i,\bar{\mu}^i]\times [\underline{\sigma}^i,\bar{\sigma}^i]$ and $\hat{\mu}_i=\frac{\underline{\mu}^i+\bar{\mu}^i}{2}, \hat{t}_i=\frac{\bar{\mu}^i-\underline{\mu}^i}{2}$, we have
$$
	K(\mathbb{B}_i)=\frac{\max\left[|\hat{\mu}_i-r|-\hat{t}_i,0\right]^2}{2(1-p)}\frac{1}{\overline{\sigma}_i}+r,\quad i=1,2.
$$

To illustrate, we assume the return has a normal distribution $\mathcal{N}(\mu,\sigma^2)$ with true values $\mu=0.1$ and $\sigma=0.2$. However, we only observe two sample datasets $\mathcal{X}$ and $\mathcal{Y}$ simulated from this true distribution, with sample sizes $N_1$ and $N_2$, respectively. We fix the size of the small dataset $\mathcal{X}$ as $N_1=1000$, and vary the size of the larger dataset $\mathcal{Y}$ as $N_2=2000,4000,\ldots,20000$. For each pair of simulated dataset $(\mathcal{X},\mathcal{Y})$, we fit a normal distribution for both and define $(\underline{\mu}^i,\bar{\mu}^i)$ as the 95\% confidence interval for the estimation of mean and $\underline{\sigma}^i,\bar{\sigma}^i$ as the 95\% confidence interval for the estimation of the standard deviation, for $i\in\{\mathcal{X},\mathcal{Y}\}$, define $(\mathbb{B}_1,\mathbb{B}_2)$ correspondingly, and obtain the price $P$. We repeat the above procedure for $M=10000$ times, i.e., by generating $M$ pairs of the simulated dataset $\{(\mathcal{X}^j,\mathcal{Y}^j)\}_{j=1}^M$ and obtaining $M$ values of the prices $\{P_j\}_{j=1}^M$.We then report the average of these $M$ prices as the data asset price $P$.

The results are shown in Figure \ref{fig:priceSample}. Consistent with our intuition, the price of the new larger dataset over the smaller dataset increases in its sample size.

\begin{figure}[htbp!]
\centering
	\includegraphics[width=0.7\textwidth]{dataset.jpg}
	\caption{Dataset price $P$ with respect to new data size. Parameters: $x=1$, $\rho = 0.1$, $r = 0.04$, $p = 0.5$, and $\lambda = 0.2$.}\label{fig:priceSample}
\end{figure}

Next, we study the impact of the true values of $\mu$ and $\sigma$ on the price of the new dataset. To this end, we fix $N_1=1000$ and $N_2=5000$, and vary the true values of $\mu\in[0.04,0.3]$ and $\sigma\in[0.1,0.5]$. For each pair of true values $(\mu,\sigma)$, we generate $M=10000$ pairs of simulated datasets $\{(\mathcal{X}^j,\mathcal{Y}^j)\}_{j=1}^M$ and obtain the price $P$ using the same procedure as above. The result in Figure \ref{fig:priceSample2} shows that the price of the new dataset is increasing in $\mu$ and decreasing $\sigma$. In other words, the new dataset is more valuable if the stock has a higher return and lower volatility, or in general, in an overall more profitable and less risky market environment.


\begin{figure}[htbp!]
\centering
  \includegraphics[width=0.7\textwidth]{fig2}
    \caption{Dataset price $P$ with respect to various $\mu$ and $\sigma$, for $\mu\in[0.04,0.3]$ and $\sigma\in[0.1,0.5]$. Parameters: $x=1$, $\rho = 0.1$, $r = 0.04$, $p = 0.5$, and $\lambda = 0.2$.}\label{fig:priceSample2}
\end{figure}

Finally, we study the impact of the risk aversion $1-p$ and the weight on the intertemporal consumption $\lambda$  on the dataset price, by varying $p\in[0.1,0.9]$ and $\lambda\in[0.1,1]$. The result in Figure \ref{fig:priceSample3} shows that the price is lower for investors with higher risk aversion and lower weight on the intertemporal consumption. Indeed, they tend to allocate more in the risky asset and hence assign a higher value for the price of the data asset.

\begin{figure}[htbp!]
  \centering
    \includegraphics[width=0.7\textwidth]{fig3}
    \caption{Dataset price $P$ with respect to various $p$ and $\lambda$, for $p\in[0.1,0.9]$ and $\lambda\in[0.2,2]$. Parameters: $\sigma=0.2$, $\mu=0.1$, $x=1$, $\rho = 0.1$, and $r = 0.04$. }\label{fig:priceSample3}
  \end{figure}


\newpage
\section{Conclusions}
In this paper, we developed a pricing model based on the informational value of data assets from the buyer's perspective through the indifference pricing principle, using the magnitude of parameter ambiguity regions to quantify information value of the data assets in the dynamic portfolio selection problems. Without consumption, the price of data assets in the optimal investment problem is strikingly simple, and the consumption will complicate the price. Moreover, we analyze the time-dependent monotonicity of data asset prices, when the utility discount rate is low, prices exhibit monotonic decay over time; conversely, with sufficiently high discount rates, prices first increase and subsequently decrease.



