%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\paragraph{Small charge regime: $\alpha \sim O(1)$.} The ionic and voltage solutions are given at the influx location by
\begin{subequations}\label{eq:alpha_small}
\begin{align}
c_1(\x_1) =& \, C_1 + \frac{I}{z_1\FF D_1 \pi A_2}\left(\frac{A_2}{A_1} - \frac{H(\x_1)}{4}A_2\log\left(\frac{A_1}{R}\right) \right. \nonumber \\
& \left. + \left(1 - \frac{z_1^2C_1}{\sum_{k=1}z_k^2C_k}\right)\left(\frac{\pi}{4} - \frac{H(\x_2)}{4}A_2\log\left(\frac{A_2}{R}\right)\right) + O\left( \frac{A_2}{R} \right) \right) \,, \label{eq:alpha_small_c1} \\
c_i(\x_1) =& \, C_i - z_iC_i\left(\frac{I}{\left(\sum_{k=1}^nz_k^2C_k\right) \FF D_1 \pi A_2 } \left( \frac{\pi}{4} - \frac{H(\x_2)}{4}A_2\log\left(\frac{A_2}{R}\right) + O\left(\frac{A_2}{R}\right)\right)\right), \quad i \neq 1 \,, \label{eq:alpha_small_ci} \\
v(\x_1) =& \, \frac{k_B\TT}{e}\left(\frac{I}{\left(\sum_{k=1}^nz_k^2C_k\right) \FF D_1\pi A_2 }\left( \frac{\pi}{4} - \frac{H(\x_2)}{4}A_2\log\left(\frac{A_2}{R}\right) + O\left(\frac{A_2}{R}\right)\right)\right)\,, \label{eq:alpha_small_v}
\end{align}
\end{subequations}
where we have the Faraday constant $\FF$, thermal voltage $\frac{k_B\TT}{e}$, valence $z_i$ and fixed ionic densities $C_i$ on the exit. Note that $H(\x_1)$ and $H(\x_2)$ are the mean boundary curvature at the center of the narrow windows $\p\Omega_{A_1}$, $\p\Omega_{A_2}$ (Fig.~\ref{fig:fig0}) and that we impose the local electro-neutrality condition
\beq
\sum_{i=1}^n z_iC_i = 0.
\eeq
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\paragraph{Large charge regime: $\alpha \gg 1$.} The solutions Eq.~\eqref{eq:alpha_small} become
\begin{subequations}\label{eq:alpha_large}
\begin{align}
c_1(\x_1) &= C_1 + \frac{I F(A_1,A_2,R)}{z_1 \FF D_1 \pi A_2 }\,, \label{eq:alpha_large_c1} \\
c_i(\x_1) &= C_i - z_iC_i\left(\frac{I F(A_1,A_2,R)}{\left(\sum_{k=1}^nz_k^2C_k\right)\FF D_1 \pi A_2}\right), \quad i \neq 1 \,, \label{eq:alpha_large_ci} \\
v(\x_1) &= \frac{k_B\TT}{e}\left(\frac{IF(A_1,A_2,R)}{\left(\sum_{k = 1}^n z_k^2 C_k\right) \FF D_1 \pi A_2} \right)\,, \label{eq:alpha_large_v}
\end{align}
\end{subequations}
where
\beq
F(A_1, A_2, R) = \frac{A_2}{A_1} + \frac{\pi}{4} - \frac{A_2}{4} \left(H(\x_1)\log\left(\frac{A_1}{R}\right) + H(\x_2)\log\left(\frac{A_2}{R}\right)\right) + O\left(\frac{A_2}{R}\right)\,.
\eeq
For two-charge models with monovalent ionic species, or more generally if $z_2 = -1$, the voltage is given by
\beq
v(\x_1) = \frac{k_B\TT}{e}\log\left(1 + \frac{IF(A_1,A_2,R)}{\left(\sum_{k = 1}^n z_k^2 C_k\right) \FF D_1 \pi A_2} \right)\,.
\eeq
