\section{Computing boundary integrals with the Neumann Green's function}\label{sec:app}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The Neumann Green's function}\label{sec:green}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We start with the domain $\tilde{\Omega}$, of $O(1)$ characteristic length-scale, on which we can introduce the Neumann Green's function $\ggreen$ solution of
\begin{equation}
\Delta \ggreen = \frac{1}{\abs{\tilde{\Omega}}}, \quad \tx \in \tilde{\Omega}, \quad \frac{\p \ggreen}{\partial \n} = \delta(\tx - \ty), \quad \tx \in \p \tilde{\Omega}, \quad \int_{\tilde{\Omega}} \ggreen d\tx = 0, \quad \ty \in \p \tilde{\Omega}\,,
\end{equation}
that behaves near the singular diagonal $\tx = \ty$ as
\begin{equation}
\ggreen \approx \frac{1}{2\pi \norm{\tx - \ty}} - \frac{\tilde{H}(\ty)}{4 \pi} \log(\norm{\tx - \ty}) + \tilde{R}_s(\tx;\ty)\,, \quad \text{with} \quad 0 < \norm{\tx-\ty} \ll 1\,,
\end{equation}
with mean boundary curvature function $\tilde{H}(\ty)$ and where $\tilde{R}_s(\tx;\ty)$ is the regular part, which can be further approximated as
\begin{equation}
\tilde{R}_s(\tx;\ty) \approx \tilde{R}_s(\ty;\ty) + O(\norm{\tx - \ty})\,.
\end{equation}
However on the stretched domain $\Omega_{\bxi}$ with $\bxi = \alpha\tx$ and $\bta = \alpha\ty$, we can work with
\beq
\GGREEN = \frac{1}{\alpha}\tilde{G}_s\left(\frac{\bxi}{\alpha};\frac{\bta}{\alpha}\right)\,,
\eeq
which satisfies
\begin{equation}\label{eq:green_bxi}
\Delta \GGREEN = \frac{1}{\abs{\Omega_{\bxi}}}, \quad \bxi \in \Omega_{\bxi}, \quad \frac{\p \GGREEN}{\p \n} = \delta(\bxi - \bta), \quad \bxi \in \p \Omega_{\bxi}, \quad \int_{\Omega_{\bxi}}\GGREEN d\bxi = 0, \quad \bta \in \p \Omega_{\bxi}\,,
\end{equation}
and behaves near the singular diagonal $\bxi = \bta$ as
\begin{equation}
\GGREEN \approx \frac{1}{2 \pi \norm{\bxi - \bta}} - \frac{\HH(\bta)}{4 \pi} \log\left(\norm{\bxi - \bta}\right) + \RR_s(\bxi;\bta), \quad 0 < \norm{\bxi - \bta} \ll \alpha\,,
\end{equation}
where $\HH(\bta)$ and $\RR_s(\bxi;\bta)$ are defined as
\beq
\HH(\bta) = \frac{1}{\alpha}\tilde{H}\left(\frac{\bta}{\alpha}\right), \quad \RR_s(\bxi;\bta) = \frac{1}{\alpha}\tilde{R}_s\left(\frac{\bxi}{\alpha};\frac{\bta}{\alpha}\right) + \frac{1}{4\pi\alpha}\tilde{H}\left(\frac{\bta}{\alpha}\right)\log(\alpha)\,,
\eeq
with $\RR_s(\bxi;\bta)$ that can be approximated as
\beq
\RR_s(\bxi;\bta) \approx \RR_s(\bta;\bta) + O\left(\frac{\norm{\bxi - \bta}}{\alpha}\right)\,.
\eeq
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Weber solution from electrostatics}\label{sec:weber}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Here we provide a justification for why the exit flux can be approximated by the classical Weber solution \cite{crank1975}. We consider
\beq\label{eq:outer}
\Delta \PP(\bxi) - \PP(\bxi) = 0, \quad \bxi \in \Omxi \,,
\eeq
along with absorbing boundary $\PP(\bxi) = 0$ for $\bxi\in\p\oxio$. Following \cite{gomez2015} we can use the small radius $a_2\alpha$ to introduce a set of local cartesian coordinates $(\eta,s_1,s_2)$ with which we can map the neighborhood near $\p\oxio$ to the infinite half-space in 3-D. This mapping relies on the expansion of the Laplacian as
\begin{equation}
\Delta_{\bxi} = \frac{1}{\left(\alpha a_2\right)^2} \Delta_{(\eta,s_1,s_2)} + O\left(\frac{1}{\alpha a_2}\right) = \frac{1}{\left(\alpha a_2\right)^2}\left(\frac{\p^2}{\p\eta^2} + \frac{\p^2}{\p s_1^2} + \frac{\p^2}{\p s_2^2}\right) + O\left(\frac{1}{\alpha a_2}\right) \,,
\end{equation}
where $\Delta_{(\eta,s_1,s_2)}$ is the Laplacian expressed in Cartesian coordinates. By redefining $\PP(\bxi)$ as $P(\eta,s_1,s_2)$ Eq.~\eqref{eq:outer} gets transformed as
\beq
\left(\frac{1}{\left(\alpha a_2\right)^2} \Delta_{(\eta,s_1,s_2)} + O\left(\frac{1}{\alpha a_2}\right)\right) P(\eta,s_1,s_2) - P(\eta,s_1,s_2) = 0,
\eeq
and thus at leading-order we obtain
\beq\label{eq:inner}
\Delta_{(\eta,s_1,s_2)} P(\eta,s_1,s_2) = 0, \quad \left. P\right|_{\eta = 0} = 0, \quad \sqrt{s_1^2 + s_2^2} < 1, \quad \left. \frac{\p P}{\p \eta}\right|_{\eta = 0} = 0, \quad \sqrt{s_1^2 + s_2^2} > 1\,,
\eeq
$P(\eta,s_1,s_2) \to P_0$ as far-field condition $\sqrt{\eta^2 + s_1^2 + s_2^2} \to \infty$. The solution to Eq.~\eqref{eq:inner} is given by
\beq
P(\eta,s_1,s_2) = P_0\left(1 - \frac{2}{\pi}\int_0^\infty e^{-\eta m}J_0\left(m\sqrt{s_1^2 + s_2^2}\right)\sin(m)\frac{dm}{m}\right)\,,
\eeq
where $J_0$ is the usual regular Bessel function of order 0. By then computing the flux we get
\beq
\left.\frac{\p P}{\p\eta}\right|_{\eta = 0} = \frac{2P_0}{\pi} \frac{1}{\sqrt{1 - (s_1^2+s_2^2)}}, \quad \sqrt{s_1^2 + s_2^2} < 1\,,
\eeq
and then when transformed back to the coordinates $\bxi$ this becomes
\beq
\frac{\p \PP(\bxi)}{\p \bxi} \sim \frac{1}{\sqrt{\left(\alpha a_2\right)^2 - \|\bxi-\bxi_2\|^2}}, \quad \bxi \in \p\oxio\,.
\eeq
We can treat similarly the equations for $\SS_{ij}$ and $\VV$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Computing boundary flux integrals}\label{sec:integrals}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We now derive approximation for the singular integrals from Section \S \ref{sec:asym} which involve the Neumann Green's function. We first calculate the boundary integrals
\beq
\int_{\p\Omega_{\bxi_1}} \GG_s(\bxi;\bxi_1) d\bxi \quad \text{and} \quad \int_{\p\Omega_{\bxi_2}} \frac{\GG_s(\bxi;\bxi_2)}{\sqrt{\alpha a_2^2 - \|\bxi-\bxi_2\|^2}} d\bxi\,,
\eeq
by defining $\rho = \|\bxi-\bxi_i\|$ and using polar coordinates. We obtain that
\begin{align}
\int_{\p\Omega_{\bxi_1}} \GG_s(\bxi;\bxi_1) d\bxi &= 2\pi\int_0^{a_1\alpha} \left( \frac{1}{2\pi \rho} - \frac{\HH(\bxi_1)}{4\pi}\log\left(\rho\right) + \RR_s(\bxi_1;\bxi_1) + O\left(\frac{\rho}{\alpha}\right) \right) \rho d\rho\,, \nonumber \\
&= \alpha a_1 - \frac{\HH(\bxi_1)}{2}\alpha^2 a_1^2\left(\frac{1}{2}\log(\alpha a_1) - \frac{1}{4}\right) + \pi \alpha^2 a_1^2\RR_s(\bxi_1;\bxi_1) + O\left(\alpha a_1^3\right)\,, \nonumber \\
&= \alpha a_1 f(a_1)\,, \nonumber
\end{align}
with $f(a_1)$ defined as
\begin{equation}
f(a_1) = 1 - \alpha\frac{\HH(\bxi_1)}{4}a_1\log(a_1) + \alpha a_1\left( \pi\RR_s(\bxi_1;\bxi_1) + \frac{\HH(\bxi_1)}{4}\left(\frac{1}{2} - \log(\alpha)\right)\right) + O(a_1^2)\,,
\end{equation}
but then on the domain $\tilde{\Omega}$ with $O(1)$ length-scale this yields,
\beq
f(a_1) = 1 - \frac{\tilde{H}(\tx_1)}{4}a_1\log(a_1) + a_1\left(\pi \tilde{R}_s(\tx_1;\tx_1) + \frac{\tilde{H}(\tx_1)}{8}\right) + O(a_1^2)\,.
\eeq
We then proceed similarly with the integral involving the classical Weber solution, and evaluate
\begin{align*}
\int_{\p\Omega_{\bxi_2}} \frac{\GG_s(\bxi;\bxi_2)}{\sqrt{\alpha a_2^2 - \|\bxi-\bxi_2\|^2}} d\bxi &= 2\pi \int_0^{\alpha a_2} \left(\frac{1}{2\pi \rho} - \frac{\HH(\bxi_2)}{4\pi}\log\left(\rho\right) + \RR_s(\bxi_2;\bxi_2) + O\left(\frac{\rho}{\alpha}\right) \right) \frac{\rho d\rho}{\sqrt{\left(\alpha a_2\right)^2 - \rho^2}}\,, \\
&= \frac{\pi}{2} - \alpha\frac{\HH(\bxi_2)}{2} a_2\left( \log(\alpha a_2) + \log(2) - 1 \right) + 2\pi a_2\alpha \RR_s(\bxi_2;\bxi_2) + O\left(a_2^2\right)\,, \\
&= \frac{\pi}{2}g(a_2)\,,
\end{align*}
where $g(a_2)$ is defined as
\begin{equation}
g(a_2) = 1 - \alpha \frac{\HH(\bxi_2)}{\pi}a_2\log(a_2) + \alpha a_2 \left(4\RR_s(\bxi_2;\bxi_2) + \frac{\HH(\bxi_2)}{\pi}\left(1-\log(2) - \log(\alpha)\right) \right) + O(a_2^2)\,,
\end{equation}
but then on the domain $\tilde{\Omega}$ with $O(1)$ length-scale this yields
\begin{equation}
g(a_2) = 1 - \frac{\tilde{H}(\tx_2)}{\pi}a_2\log(a_2) + a_2 \left(4\tilde{R}_s(\tx_2;\tx_2) +  \frac{\tilde{H}(\tx_2)}{\pi}(1-\log(2))\right) + O(a_2^2)\,.
\end{equation}
By then assuming that the narrow windows are well-spaced we get the approximation below for the mixed integral terms
\begin{align}
&\int_{\p\Omega_{\bxi_1}} \GG_s(\bxi;\bxi_2) d\bxi \approx \pi \left(a_1\alpha\right)^2 \GG_s(\bxi_1;\bxi_2), \\
&\int_{\p\Omega_{\bxi_2}} \frac{\GG_s(\bxi;\bxi_1)}{\sqrt{\alpha a_2^2 - \|\bxi-\bxi_2\|^2}} d\bxi \approx 2\pi a_2\alpha \GG_s(\bxi_2;\bxi_1)\,.
\end{align}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
To calculate the last integral in Eq.~\eqref{eq:greenid_sub_pp_1}-\eqref{eq:greenid_sub_pp_2} we proceed by splitting the domain into three subregions,
\begin{equation*}\label{eq:int_3D}
\int_{\Omxi} \GG_s(\bxi;\bxi_j)\PP(\bxi) d\bxi = \left(\int_{B\left(\bxi_1,\alpha a_1\right)} + \int_{B\left(\bxi_2,\alpha a_2\right)} + \int_{\Omxi\backslash\left\{B\left(\bxi_1,\alpha a_1\right) \cup B\left(\bxi_2,\alpha a_2\right) \right\}} \right)\GG_s(\bxi;\bxi_j)\PP(\bxi)d\bxi, \quad j=1,2\,,
\end{equation*}
where $B\left(\bxi_j,\alpha a_j\right)$ for $j=1,2$ are half-spheres of radius $\alpha a_j$ centered in $\bxi_j$. Outside of these subregions the sum $\PP(\bxi)$ is constant, yielding
\begin{equation*}
\int_{\Omxi\backslash\left\{B\left(\bxi_1,\alpha a_1\right) \cup B\left(\bxi_2,\alpha a_2\right) \right\}} \GG_s(\bxi;\bxi_j)\PP(\bxi)d\bxi \approx \overline{\PP}\int_{\Omxi\backslash\left\{B\left(\bxi_1,\alpha a_1\right) \cup B\left(\bxi_2,\alpha a_2\right) \right\}} \GG_s(\bxi;\bxi_j) d\bxi \approx \PP \left[ O(1) \right]\,,
\end{equation*}
with its contribution that can be neglected, while for the two subregions we get
\begin{align*}
\int_{\Omega_{\bxi}} \GG_s(\bxi;\bxi_j)\PP(\bxi) d\bxi &\approx \left( \int_{B\left(\bxi_1,\alpha a_1\right)} + \int_{B\left(\bxi_2,\alpha a_2\right)} \right) \GG_s(\bxi;\bxi_j)\PP(\bxi) d\bxi\,, \\
&\approx \PP(\bxi_1)\int_{B\left(\bxi_1,\alpha a_1\right)} \GG_s(\bxi;\bxi_j) d\bxi + \PP(\bxi_2)\int_{B\left(\bxi_2,\alpha a_2\right)} \GG_s(\bxi;\bxi_j) d\bxi \\
&\approx \PP(\bxi_1)\int_{B\left(\bxi_1,\alpha a_1\right)} \GG_s(\bxi;\bxi_j) d\bxi
\end{align*}
due to the absorbing boundary condition $\PP(\bxi_2) = 0$. Here the windows are well-spaced, thus we calculate
\beq
\int_{B\left(\bxi_1,\alpha a_1\right)} \GG_s(\bxi;\bxi_2) d\bxi \approx \GG_s(\bxi_1;\bxi_2) \left| B\left(\bxi_1,\alpha a_1\right) \right| = \GG_s(\bxi_1;\bxi_2) \frac{2\pi}{3}\alpha^3 a_1^3\,,
\eeq
while around the singularity we get
\begin{align*}
\int_{B\left(\bxi_1,\alpha a_1\right)} \GG_s(\bxi;\bxi_1) d\bxi &= \int_{\frac{\pi}{2}}^\pi \int_0^{2\pi} \int_0^{\alpha a_1} \left( \frac{1}{2\pi\rho} - \frac{\HH(\bxi_1)}{4\pi}\log\left(\rho\right) + \RR_s(\bxi_1;\bxi_1) + O\left(\frac{\rho}{\alpha}\right) \right) \rho^2 \sin(\theta) d\rho d\phi d\theta\,, \\
&= \frac{\left(\alpha a_1\right)^2}{2} - \frac{\HH(\bxi_1)}{2}\alpha^3 a_1^3\left(\frac{1}{3}\log(\alpha a_1)  - \frac{1}{9}\right) + 2\pi\RR_s(\bxi_1;\bxi_1)\frac{\alpha^3 a_1^3}{3} + O\left(\alpha a_1^4\right)\,, \\
&= \frac{\left(\alpha a_1\right)^2}{2}m(a_1)\,,
\end{align*}
where $m(a_1)$ is an expansion given by
\begin{equation}
m(a_1) = 1 - \alpha\frac{\HH(\bxi_1)}{3}a_1\log(a_1) + \alpha a_1\left( \frac{4\pi}{3}\RR_s(\bxi_1;\bxi_1) + \frac{\HH(\bxi_1)}{3} \left(\frac{1}{3} -\log(\alpha)\right)\right) + O\left(a_1^2\right)\,.
\end{equation}
On the domain $\tilde{\Omega}$ with $O(1)$ length-scale this yields
\begin{equation}
m(a_1) = 1 - \frac{\tilde{H}(\tx_1)}{3}a_1\log(a_1) + a_1\left( \frac{4\pi}{3}\tilde{R}_s(\tx_1;\tx_1) + \frac{\tilde{H}(\tx_1)}{9}\right) + O\left(a_1^2\right)\,,
\end{equation}
and our final approximate integral solutions are
\begin{subequations}
\begin{align}
\int_{\Omega_{\bxi}} \GG_s(\bxi;\bxi_1)\PP(\bxi) d\bxi &\approx \PP(\bxi_1) \frac{\left(\alpha a_1\right)^2}{2}m(a_1)\,, \\
\int_{\Omega_{\bxi}} \GG_s(\bxi;\bxi_2)\PP(\bxi) d\bxi &\approx \PP(\bxi_1) \frac{2\pi}{3}a_1^3\alpha^3 \GG_s(\bxi_1;\bxi_2)\,.
\end{align}
\end{subequations}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Reduced ionic and voltage asymptotic formulas}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Small interior charge}\label{sec:small_alpha_app}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
When $\alpha \sim O(1)$, we can expand the ratio $\AA$ assuming $a_1,\, a_2 \ll 1$ as
\begin{align*}
\AA &\approx
\frac{\left(\frac{f(a_1)}{a_1}-\pi\alpha\GG_s(\bxi_2;\bxi_1)\right)\left(1+\frac{g(a_2)}{4\alpha a_2}\left|\Omega_{\bxi}\right|\right) + \left(\frac{\pi g(a_2)}{4a_2} - \pi\alpha\GG_s(\bxi_2;\bxi_1)\right)\left(1 + \left|\Omega_{\bxi}\right|\GG_s(\bxi_2;\bxi_1)\right)}{\left(1+\frac{1}{2}\left(\alpha a_1\right)^2m(a_1) \right)\left(1+\frac{g(a_2)}{4\alpha a_2}\volOmxi\right)} \,, \\
&\approx \frac{f(a_1)}{a_1}-\pi\alpha\GG_s(\bxi_2;\bxi_1) + \frac{ \left(\frac{\pi g(a_2)}{4a_2} - \pi\alpha\GG_s(\bxi_2;\bxi_1)\right)\left(1 + \left|\Omega_{\bxi}\right|\GG_s(\bxi_2;\bxi_1)\right)}{\left(1+\frac{1}{2}\left(\alpha a_1\right)^2m(a_1) \right)\left(1+\frac{g(a_2)}{4\alpha a_2}\left|\Omega_{\bxi}\right|\right)} \,, \\
&\approx \frac{f(a_1)}{a_1}-\pi\alpha\GG_s(\bxi_2;\bxi_1) + \frac{ \left(\frac{\pi \alpha}{\volOmxi} - \frac{4a_2\pi\alpha\GG_s\left(\bxi_2;\bxi_1\right)}{g(a_2)\volOmxi}\right)\left(1 + \left|\Omega_{\bxi}\right|\GG_s(\bxi_2;\bxi_1)\right)}{1 + \frac{4\alpha a_2}{g(a_2)\left|\Omega_{\bxi}\right|}} \,, \\
&\approx \frac{f(a_1)}{a_1} - \pi\alpha\GG_s(\bxi_2;\bxi_1) + \frac{\pi \alpha}{\volOmxi} + \pi\alpha\GG_s(\bxi_2;\bxi_1) + O(a_2)\,, \\
&\approx \frac{f(a_1)}{a_1} + \frac{\pi \alpha}{\volOmxi} + O(a_2) \,,
\end{align*}
and similarly for $\BB$, which becomes
\begin{align*}
\BB &\approx
\frac{\frac{\pi g(a_2)}{4a_2} - \pi\alpha\GG_s(\bxi_2;\bxi_1)}
{1+\frac{g(a_2)}{4\alpha a_2}\volOmxi}
+
\frac{\left(\frac{f(a_1)}{a_1}-\pi\alpha\GG_s(\bxi_2;\bxi_1)\right)\frac{2\pi}{3}a_1^3\alpha^3 \GG_s(\bxi_1;\bxi_2)}
{\left(1+\frac{1}{2}\left(\alpha a_1\right)^2m(a_1) \right)\left(1+\frac{g(a_2)}{4\alpha a_2}\volOmxi\right)} \,, \\
&\approx \frac{\frac{\pi \alpha}{\volOmxi} - \frac{4a_2 \pi \alpha \GG_s\left(\bxi_2;\bxi_1\right)}{g(a_2)\volOmxi}}
{1+\frac{4\alpha a_2}{g(a_2)\volOmxi}}\,, \\
&\approx \frac{\pi \alpha}{\volOmxi} + O(a_2)\,.
\end{align*}
Starting from the general voltage formulas Eq.~\eqref{eq:VV_gen}, we obtain the current-voltage relation when $\alpha \sim O(1)$ by performing the asymptotic reduction below
\begin{align*}
\VV(\bxi_1) &= Ja_1^2\left( \left( m(a_1) - \frac{4\pi}{3}a_1\alpha\GGREENEVAL\right)\frac{1}{2}(\alpha a_1)^2\AA + \left(\frac{g(a_2)}{4 a_2} - \alpha\GG_s(\bxi_2;\bxi_1) \right) \frac{\volOmxi}{\alpha}\BB \right) + O\left(\left(\frac{J}{\alpha}\right)^2 \right)\,, \\
&\approx Ja_1^2\left(O(a_1) + \left(\frac{1}{4a_2} - \alpha\frac{\HH(\bxi_2)}{4\pi} \log(a_2) + O(1) \right)\pi\right) + O\left(\left(\frac{J}{\alpha}\right)^2 \right) \,, \\
&\approx Ja_1^2\left(\frac{\pi}{4a_2} - \alpha\frac{\HH(\bxi_2)}{4} \log(a_2) + O(1) \right) + O\left(\left(\frac{J}{\alpha}\right)^2 \right)\,,
\end{align*}
as well as, for the spatial average
\begin{align*}
\overline{\VV} &= Ja_1^2\left(\volOmxi\frac{g(a_2)}{4\alpha a_2}\BB - \frac{2\pi}{3}a_1^3\alpha^3\GGREENEVAL\AA\right) + O\left(\left(\frac{J}{\alpha}\right)^2 \right) \,, \\
&\approx Ja_1^2\left(\volOmxi\frac{g(a_2)}{4\alpha a_2} \left(\frac{\frac{\pi g(a_2)}{4 a_2} - \pi\alpha\GG_s(\bxi_2;\bxi_1) + O(a_1^3)}{1 + \frac{g(a_2)}{4\alpha a_2}\volOmxi + O(a_1^3)} \right) + O(a_1^2)\right) + O\left(\left(\frac{J}{\alpha}\right)^2 \right) \,, \\
&\approx Ja_1^2 \left( \frac{\frac{\pi g(a_2)}{4 a_2} - \pi\alpha\GG_s(\bxi_2;\bxi_1)}{1 + O(a_2)} + O(a_1^2) \right) + O\left(\left(\frac{J}{\alpha}\right)^2 \right) \,, \\
&\approx Ja_1^2 \left( \frac{\pi}{4a_2} - \alpha\frac{\HH(\bxi_2)}{4} \log(a_2) + O(1) \right) + O\left(\left(\frac{J}{\alpha}\right)^2 \right) \,,
\end{align*}
and thus we get the same expression for both $\VV(\x_1)$ and $\overline{\VV}$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Large interior charge}\label{sec:big_alpha_app}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Alternatively if $\alpha \gg 1$, we first remark that
\begin{equation}
\volOmxi = \alpha^3 \atOmega\,, \quad \GGREENEVAL = \alpha \ggreeneval\,,
\end{equation}
and thus we obtain that
\begin{align*}
\AA &=
\frac{1}{\alpha^2}\frac{\left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\left(\frac{1}{\alpha^2} + \frac{g(a_2)}{4a_2}\atOmega\right) + \left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right)\left(\frac{1}{\alpha^2} + \atOmega \tilde{G}_s\left(\tx_2;\tx_1\right)\right)}
{\left(\frac{1}{\alpha^2}+\frac{a_1^2}{2}m(a_1) \right)\left(\frac{1}{\alpha^2}+\frac{g(a_2)}{4a_2}\atOmega\right) - \left(\frac{1}{\alpha^2} + \atOmega \tilde{G}_s(\tx_2;\tx_1)\right)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)} \,.
\end{align*}
Taking first the limit of $\alpha$ big, we find
\begin{align*}
\AA &\approx \frac{1}{\alpha^2}\frac{\left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right) \frac{g(a_2)}{4a_2} + \left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right)\tilde{G}_s\left(\tx_2;\tx_1\right)}
{\frac{a_1^2}{8a_2}m(a_1)g(a_2) - \tilde{G}_s(\tx_2;\tx_1) \frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)} \,,
\end{align*}
after which we can expand assuming $a_1 \ll 1$ and $a_2 \ll 1$, leading to
\begin{align*}
\AA &\approx \frac{2}{\alpha^2 a_1^3}\left(\frac{f(a_1) - 4 \pi \frac{a_1 a_2}{g(a_2)} \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}
{m(a_1) - \frac{16\pi}{3}\frac{a_1a_2}{g(a_2)}\left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}\right) \approx \frac{2}{\alpha^2 a_1^3}\left(1 + O(a_1\log(a_1)) \right) \,,
\end{align*}
and then if $a_1^3 \gg \frac{1}{\alpha^2}$ we can neglect the ratio $\AA$. We proceed similarly for $\BB$,
\begin{align*}
\BB &=
\frac{1}{\alpha^2}\frac{\left(\frac{1}{\alpha^2} + \frac{a_1^2}{2}m(a_1) \right)\left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right) + \left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)}
{\left(\frac{1}{\alpha^2}+\frac{a_1^2}{2}m(a_1) \right)\left(\frac{1}{\alpha^2}+\frac{g(a_2)}{4a_2}\atOmega\right) - \left(\frac{1}{\alpha^2} + \atOmega \tilde{G}_s(\tx_2;\tx_1)\right)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)} \,,
\end{align*}
and then expanding in $\alpha \gg 1$ yields
\begin{align*}
\BB &\approx \frac{1}{\alpha^2\atOmega}\frac{\frac{a_1^2}{2}m(a_1) \left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right) + \left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)}
{\frac{a_1^2}{8a_2}m(a_1)g(a_2) - \tilde{G}_s(\tx_2;\tx_1)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)} \,,
\end{align*}
and after some simplifications and keeping only leading-order terms in $a_1 \ll 1$ and $a_2 \ll 1$, we get
\begin{align*}
\BB &\approx
\frac{\pi}{\alpha^2 \atOmega} \left(\frac{g(a_2) - 4a_2\tilde{G}_s(\tx_2;\tx_1) + \frac{16a_2}{3m(a_1)}\left(f(a_1) - \pi a_1 \tilde{G}_s(\tx_2;\tx_1)\right) \tilde{G}_s(\tx_1;\tx_2)}
{g(a_2) - \frac{16\pi a_1a_2}{3m(a_1)}\left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}\right)\,, \\
&\approx \frac{\pi}{\alpha^2 \atOmega}\left(1 + O(a_2\log(a_2)) \right) \,,
\end{align*}
since $\alpha \gg 1$. Concerning the voltage formula Eq.~\eqref{eq:VV_gen_influx}, we consider first the contribution from,
\begin{align*}
& \left( m(a_1) - \frac{4\pi}{3}a_1\ggreeneval\right)\frac{1}{2}(\alpha a_1)^2\AA\,,
\end{align*}
on which we can take the limit $\alpha \gg 1$, leading to
\begin{align*}
& \left( m(a_1) - \frac{4\pi}{3}a_1\ggreeneval\right)\left(
\frac{\left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\frac{g(a_2)}{4a_2} + \left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right) \tilde{G}_s\left(\tx_2;\tx_1\right)}
{m(a_1) \frac{g(a_2)}{4a_2} - \frac{4\pi}{3}a_1 \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}\right)\,,
\end{align*}
which is equivalent to
\begin{align*}
& \left( m(a_1) - \frac{4\pi}{3}a_1\ggreeneval\right)\left(
\frac{\left(\frac{f(a_1)}{a_1}\right)\frac{g(a_2)}{4a_2}  - \pi \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}
{m(a_1) \frac{g(a_2)}{4a_2} - \frac{4\pi}{3}a_1 \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}\right) \approx \\
& \left(1 - \frac{4\pi a_1}{3m(a_1)}\ggreeneval\right)\left(
\frac{\frac{f(a_1)}{a_1}  - \frac{4\pi a_2}{g(a_2)} \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}
{1 - \frac{16\pi a_1a_2}{3m(a_1)g(a_2)}\left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}\right)
\,,
\end{align*}
and then neglecting terms of $O(1)$ and beyond in terms of the narrow radii $a_1$ and $a_2$ we get,
\begin{align*}
\left( m(a_1) - \frac{4\pi}{3}a_1\ggreeneval\right)\frac{1}{2}(\alpha a_1)^2\AA \approx \frac{1}{a_1} - \frac{\tilde{H}(\tx_1)}{4}\log(a_1) + O(1)\,.
\end{align*}
Similarly for the contribution from
\begin{align*}
\left(\frac{g(a_2)}{4 a_2} - \ggreeneval \right) \alpha^2 \atOmega \BB\,,
\end{align*}
we get after taking the limit $\alpha \gg 1$,
\begin{align*}
\left(\frac{g(a_2)}{4 a_2} - \ggreeneval \right) \left( \frac{\frac{a_1^2}{2}m(a_1)\left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right) + \left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)}
{\frac{a_1^2}{2}m(a_1)\frac{g(a_2)}{4a_2} - \frac{2\pi}{3}a_1^3 \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}\right) \,,
\end{align*}
and then further simplifications yield
\begin{align*}
\left(g(a_2) - 4a_2\ggreeneval \right) \left( \frac{\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1) + \left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\frac{4\pi a_1}{3m(a_1)} \tilde{G}_s(\tx_1;\tx_2)}
{g(a_2) - \frac{16\pi a_1a_2}{3m(a_1)} \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}\right) \,,
\end{align*}
and upon neglecting terms of order $O(1)$ and beyond we get
\begin{align*}
\left(\frac{g(a_2)}{4 a_2} - \ggreeneval \right) \alpha^2 \atOmega \BB \approx \frac{\pi}{4a_2} - \frac{\tilde{H}(\tx_2)}{4}\log(a_2) + O(1)\,.
\end{align*}
Upon adding the two contributions we obtain
\begin{equation}
\tv(\tx_1) \approx Ja_1^2 \left(\frac{1}{a_1} + \frac{\pi}{4a_2} - \frac{\tilde{H}(\tx_1)}{4}\log(a_1) - \frac{\tilde{H}(\tx_2)}{4}\log(a_2) + O(1) \right)\,.
\end{equation}
Similarly for the average voltage with formula given by Eq.~\eqref{eq:VV_gen_bar}, we first calculate
\begin{align*}
\frac{g(a_2)}{4a_2}\alpha^2\atOmega \BB \approx \frac{g(a_2)}{4a_2}\left(\frac{\frac{a_1^2}{2}m(a_1) \left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right) + \left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)}
{\frac{a_1^2m(a_1)}{2}\frac{g(a_2)}{4a_2} - \tilde{G}_s(\tx_2;\tx_1)\frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)}\right)\,,
\end{align*}
and then further simplifications yield
\begin{align*}
\frac{g(a_2)}{4a_2}\alpha^2\atOmega \BB \approx \frac{\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1) + \left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right)\frac{4\pi a_1}{3m(a_1)}\tilde{G}_s(\tx_1;\tx_2)}{1 + \frac{16\pi a_1a_2}{3m(a_1)g(a_2)}\left(\ggreeneval\right)^2}
\end{align*}
and then neglecting terms of order $O(1)$ and beyond, we are left with
\begin{align*}
\frac{g(a_2)}{4a_2}\alpha^2\atOmega \BB \approx \frac{\pi}{4a_2} - \frac{\tilde{H}(\tx_2)}{4}\log(a_2) + O(1)\,.
\end{align*}
Similarly for the term
\begin{align*}
-\frac{2\pi}{3}a_1^3\alpha^2 \tilde{G}_s(\tx_1;\tx_2)\AA &\approx -\frac{2\pi}{3}a_1^3\tilde{G}_s(\tx_1;\tx_2) \left(\frac{\left(\frac{f(a_1)}{a_1}-\pi \tilde{G}_s(\tx_2;\tx_1)\right) \frac{g(a_2)}{4a_2} + \left(\frac{\pi g(a_2)}{4a_2} - \pi \tilde{G}_s(\tx_2;\tx_1)\right)\tilde{G}_s\left(\tx_2;\tx_1\right)}
{\frac{a_1^2}{2}m(a_1)\frac{g(a_2)}{4a_2} - \tilde{G}_s(\tx_2;\tx_1) \frac{2\pi}{3}a_1^3 \tilde{G}_s(\tx_1;\tx_2)}\right) \,, \\
&\approx -\frac{4\pi}{3}a_1\tilde{G}_s(\tx_1;\tx_2) \left(\frac{\frac{f(a_1)}{a_1} - \frac{4\pi a_2}{g(a_2)} \left(\tilde{G}_s(\tx_2;\tx_1)\right)^2}
{m(a_1) - \frac{16\pi a_1a_2}{3g(a_2)} \left(\tilde{G}_s(\tx_1;\tx_2)\right)^2}\right)\,, \\
&\approx - \frac{4\pi}{3}\tilde{G}_s(\tx_1;\tx_2) \sim O(1) \,.
\end{align*}
Thus for the average voltage we are left with
\begin{equation}
\overline{\tv} = Ja_1^2 \left( \frac{\pi}{4a_2} - \frac{\tilde{H}(\tx_2)}{4}\log(a_2) + O(1) \right)\,.
\end{equation}
