\title{Knot complements decomposing into prisms}





\date{\today}

\begin{document}

\begin{abstract} We describe four hyperbolic knot complements in $\mathbb{S}^3$, each of which covers a \emph{prism orbifold}: the quotient of $\mathbb{H}^3$ by the action of a discrete group generated by reflections in the faces of a polyhedron that has the combinatorial type of a triangular prism. The prism orbifolds are rigid-cusped and contain compact, totally geodesic hyperbolic triangle sub-orbifolds; as a result, the knot complements covering them have hidden symmetries and contain closed, embedded, totally geodesic surfaces.
\end{abstract}

\subjclass[2020]{57K32 , 57K10}


