\begin{lemma}\label{itsapermrep}
    For $i=2$ or $3$, let $\doh^{333}_i = \mathbb{H}^3/\dprgr^{333}_i$ be the orientable prism orbifold double-covering $O^{333}_i$ from Table \ref{table333}. Specializing the presentation for $\dprgr^{333}_i$ from (\ref{able}) to:\begin{align*}
    \dprgr^{333}_2\ & \cong\ \langle x, y,z, w\, |\, x^{3}, y^{3}, z^{3}, w^{2}, 
        (y^{-1}x)^{2}, (z^{-1}x)^{3}, (z^{-1}y)^{4}, (y^{-1}w)^{3}, (z^{-1}w)^{2} \rangle,\mbox{ and}\\
    \dprgr^{333}_3\ & \cong\ \langle x, y,z, w\, |\, x^{3}, y^{3}, z^{3}, w^{2}, 
        (y^{-1}x)^{2}, (z^{-1}x)^{3}, (z^{-1}y)^{4}, (y^{-1}w)^{2}, (z^{-1}w)^{3} \rangle,%\\
%    \dprgr(\be)\ & \cong\ \langle x, y,z, w\, |\, x^{a_1}, y^{a_4}, z^{a_5}, w^{a_7}, 
%        (y^{-1}x)^{a_3}, (z^{-1}x)^{a_2}, (z^{-1}y)^{a_6}, (y^{-1}w)^{a_9}, (z^{-1}w)^{a_8} \rangle
    \end{align*}
    each map $\sigma_{i,j}\co \{x,y,z,w\}\to S_{24}$ recorded in \Cref{table_pr} extends to a right-permutation representation of $\dprgr^{333}_i$ with image acting transitively on $\{0,1,\hdots,23\}$. The stabilizer $G_{i,j}$ of $0$ therefore has index $24$ in $\dprgr^{333}_i$, and $\sigma_{i,j}$ records the generators' action by right-multiplication on right cosets of $G_{i,j}$.
\end{lemma}

\begin{definition}\label{first manifold covers}
    For each $i\in\{2,3\}$ and $j\in\{1,2\}$, taking $G_{i,j}<\dprgr^{333}_i$ as in \Cref{itsapermrep}, let $M_{i,j} = \mathbb{H}^3/G_{i,j}$ be the corresponding cover of $\doh^{333}_i$.
\end{definition}

\begin{proof} We define the right-representation extending $\sigma_{i,j}$ as follows. For a word $g = \chi_1^{\alpha_1}\cdots \chi_k^{\alpha_k}$ in the generators $\{x,y,z,w\}$, with each ${\alpha_i}\in\mathbb{Z}$, and $n\in\{0,1,\hdots,23\}$, let
\[ \sigma_{i,j}(g)(n) = \left(\sigma_{i,j}(\chi_k)^{\alpha_k} \circ \hdots \circ \sigma_{i,j}(\chi_1)^{\alpha_1}\right)(n).\]
(Note that the composition here is in the opposite order from the usual product in $S_{24}$.) Well-definedness of this map on $\dprgr^{333}_i$ is equivalent to it sending each relator to the identity, which can be checked directly. See eg.~\Cref{M21 permreps} below for the case of $\sigma_{2,1}$. There, writing each relation from the presentation for $\dprgr^{333}_2$ given above in the form $g_j^{a_{i_j}}$ for $j\in\{1,\hdots,9\}$, cycle decompositions for the images of the $g_j$ are given. Each consists of $a_{i_j}$-cycles, verifying the $(i,j) = (2,1)$-case.

Another straightforward check establishes that each $\sigma_{i,j}$ determines a transitive action on $\{0,1,\hdots,23\}$. Therefore for any $i,j$, the stabilizer $G_{i,j}$ of $0$ in $\dprgr^{333}_i$ has index $24$. In particular, elements $g, h\in\dprgr^{333}_i$ determine the same right coset of $G_{i,j}$ if and only if $gh^{-1}\in G_{i,j}$; ie.~if and only if $0.g = 0.h$. For a complete set $\{g_0,\hdots,g_{23}\}$ of right coset representatives, where $0.g_n = n$ for each $n$, we then have $0.(g_nx) = n.x$, so $g_{n.x}$ represents the right coset $\left(G_{i,j}g_n\right)x$, and likewise for the other generators.\end{proof}

We now describe polyhedral decompositions of arbitrary covers of orbifolds $\doh(\be)$ determined by permutation representations of their orbifold fundamental groups $\dprgr(\be)$.

\begin{lemma}\label{cell decomp} Suppose $\dprgr(\be)$ is an orientable prism group, presented as in (\ref{able}), for a nine-tuple $\be$ from Table \ref{table236} or \ref{table333}. Label the faces of the doubled prism $\dpr(\be)$ on which the generators $x,y,z,w$ of $\dprgr(\be)$ act as face-pairings according to Figure \ref{numberings} (right), i.e.~as $0$, $1$, $2$, $3$ and $0_-$, $1_-$, $2_-$, $3_-$ so that $x$ takes $0_-$ to $0$, $y$ takes $1_-$ to $1$, $z$ takes $2_-$ to $2$, and $w$ takes $3_-$ to $3$.

Further suppose that \( H \) is an index-\( n \) subgroup of \( \dprgr(\be) \), and for a complete set $\mathcal{S} = \{g_0,\hdots,g_{n-1}\}$ of right coset representatives for $H$, let \( \sigma_x, \sigma_y, \sigma_z, \sigma_w \) be the values of the associated right-permutation representation $\sigma$ from \Cref{permrep}, on the generators. Then \( \mathbb{H}^3 / H \) is isometric to the orbifold obtained from distinct copies \( \dpr_0, \dots, \dpr_{n-1} \) of $\dpr(\be)$ by the equivalence relation generated by the face-pairing below. For every $i \in \{0, 1,\hdots, n-1\}$:

\begin{itemize}   
    \item Identify face \( 0_+ \) of \( \dpr_i \) to face \( 0_- \) of \( \dpr_j \), where \( j = \sigma_x(i) \).
    \item Identify face \( 1_+ \) of \( \dpr_i \) to face \( 1_- \) of \( \dpr_j \), where \( j = \sigma_y(i) \).
    \item Identify face \( 2_+ \) of \( \dpr_i \) to face \( 2_- \) of \( \dpr_j \), where \( j = \sigma_z(i) \).
    \item Identify face \( 3_+ \) of \( \dpr_i \) to face \( 3_- \) of \( \dpr_j \), where \( j = \sigma_w(i) \).
\end{itemize}

These identifications use the appropriate generator, pre- and post-composed by the appropriate marking. For example, the first identification map is \( g_j x g_i^{-1} \), where \( g_i: \dpr(\be) \rightarrow \dpr_i \) and \( g_j: \dpr(\be) \rightarrow \dpr_j \) are the markings. In particular, for each $f\in\{0,1,2,3\}$ they take the edge $f_+\cap f_-$ of $\dpr_i$ to the corresponding edge of $\dpr_j$.
\end{lemma}


