Each shaded circle in the figure represents a totally geodesic planar hexagon in $\Sigma_0\times[0,\infty)$, meeting $\Sigma_0\times\{0\}$ at right angles, that is the union of twelve copies of the triangle $T$ from \Cref{corandreev}. More precisely, each hexagon is six copies of $T\cup\overline{T}$, where $\overline{T}$ is the mirror image of $T$ in $\dpr^{333}_2$. Each hexagon has an angle of $2\pi/3$ at its vertices lying in edges labeled $a_i$ and $\pi/2$ at its vertices lying in edges labeled $b_j$. These polygons' edges are identified to each other under the pairings of hexagons of $\Sigma_0\times\{0\}$ that recover $M_{2,1}$, and an Euler characteristic or area computation shows that the polygons' union is a genus-two surface.
\end{example}

\begin{prop}\label{M_21plus} Let $\Sigma^+$ be the smallest subcomplex of the spine $\Sigma$ for $M_{2,1}$ from \Cref{M_21 spine} containing all $2$-cells that are unions of faces labeled $3_-$. For the surface $S_{2,1}\subset M_{2,1}$ of \Cref{ex: tot geod from cusp}, the compact component $M_{2,1}^+$ that results from cutting $M_{2,1}$ along $S_{2,1}$ deformation retracts to $\Sigma^+$ along geodesic arcs perpendicular to $S_{2,1}$. We thus have\begin{align*}
    \pi_1 M^+_{2,1} & \cong \langle\,C_1,C_3,C_4,C_6,C_6,C_7\,|\\
        & \ \qquad C_1^{-1}C_7^{-1}C_4C_6^{-1},\ C_1C_3^{-1}C_5C_3^{-1}C_4^{-1},\ C_3C_6^{-1}C_7C_6^{-1},\ C_5^{-1}C_1C_5^{-1}C_7C_4^{-1}\,\rangle
 \end{align*}
The fundamental group of $S_{2,1}$, presented as follows:
\[ \pi_1 S_{2,1} \cong \langle E_3, E_5, E_7, E_8\,|\, E_5E_3E_5^{-1}E_8E_3^{-1}E_7^{-1}E_8^{-1}E_7 \rangle \]
includes in $\pi_1 M^+_{2,1}$ via
\[ E_3 \mapsto C_3C_1,\ E_5\mapsto C_3C_5^{-1}C_1C_4C_6^{-1},\ E_7\mapsto C_4^{-1}C_5C_1^{-1}C_5C_3^{-1},\ E_8\mapsto C_3C_5^{-1}C_1C_6 \]
\end{prop}

\begin{remark}\label{basis change} Substituting $D = E_5^{-1}E_8$ for $E_5$ as a generator of $\pi_1 S_{2,1}$, we can replace its presentation given above by $\langle E_3,D,E_7,E_8\,|\,D^{-1}E_3DE_3^{-1}E_7^{-1}E_8^{-1}E_7E_8\rangle$; and $D\mapsto C_6C_4^{-1}C_6$.\end{remark}

