\[ E_9 = E_8^{-1},\ E_{10} = E_5E_3^{-1},\ E_{21}=E_{11}=E_{8}^{-1}E_5E_3^{-1},\ E_{13} = E_3^{-1}E_7^{-1}E_8^{-1},\ E_{23}=E_7^{-1}E_8^{-1}. \]
