\end{center}

\medskip\noindent
Proposition~\ref{p:c+d>a+b} covers all the points above the line. When $b-a$ decreases, the $c+d=a+b$ line gets closer to being tangent to the $cd=ab$ curve. When $a=b$, the region $\{cd\ge ab\}$ is contained inside $\{c+d\ge a+b\}$, and thus the conjecture is fully settled.

The boundary of the region covered by Proposition~\ref{p:all-cond} is an approximation of the curve $cd=ab$ using only vertical segments, horizontal segments, and segments of slope $-1$. The quality of the approximation depends on the number and the sizes of the divisors of $b$.
\end{note}

\section{The structure constants of the \texorpdfstring{$k$}{k}-fold map}\label{sec:matrix}
Fix $k\in\mathbb{N}$. In this section we study the (infinite) matrix of the $k$-fold map
$\Lambda[\mathbf{x}_\infty] \ni f(\mathbf{x}_\infty) \mapsto f[k\mathbf{y}_\infty]$
with respect to selected bases of the $\C$-algebra of symmetric functions. The matrices exhibit rich structure and properties that may be of independent interest; for numerical examples see
Examples~\ref{eg:D(2)} and~\ref{eg:B(2)}.

\subsection{The Schur basis matrix}
\begin{de}
    For each $\lambda, \mu \in \Par$, define
    $d_\lambda^\mu(k)$ via $s_\lambda[k \mathbf{y}_\infty] = \sum_\mu d_\lambda^\mu(k) s_\mu(\mathbf{y}_\infty)$.
\end{de}

We study $D(k) = \big( d_\lambda^\mu(k)\big)_{\lambda,\mu\in\Par}$.
Observe first that the matrix is block-diagonal.
\begin{lem}
    If $|\lambda|\ne|\mu|$ then $d_\lambda^\mu(k) = 0$.
\end{lem}
\begin{proof}
    The $k$-fold map preserves the total degree of monomials.
\end{proof}
In fact, since $p_\lambda[k\mathbf{y}_\infty] = k^{\ell(\lambda)}p_\lambda(\mathbf{y}_\infty)$, the matrix $D(k)$ is diagonalised by the matrix $X = (\chi^\lambda(\mu))_{\lambda,\mu\in\Par}$ of character values of the symmetric groups. More precisely, $X^{-1}\cdot D(k)\cdot X = \mathrm{diag}(1,k,k,k^2,\ldots) = \mathrm{diag}(k^{\ell(\lambda)})_{\lambda\in\Par}$.\medskip

Our first formula expresses $d_\lambda^\mu(k)$ in terms of $k$-multi-Littlewood--Richardson coefficients, defined by
$c_{\bm{\nu}}^\lambda = \langle s_{\nu^{(1)}}\cdots s_{\nu^{(k)}}, s_\lambda\rangle$, where $\bm{\nu}=(\nu^{(1)},\ldots,\nu^{(k)})\in\Par^k$.
\begin{p}\label{p:coefs}
    For all $\lambda, \mu\in\Par$, we have \(
    d_\lambda^\mu(k) = \sum_{\bm{\nu} \in \Par^k} c_{\bm{\nu}}^\lambda c_{\bm{\nu}}^\mu
    \).
\end{p}
\begin{proof}
    By the plethystic addition formula \eqref{eq:plet addition},
    \begin{align*}
        \textstyle
        s_\lambda\big[k \mathbf{y}_\infty\big] =
        s_\lambda\big[\mathbf{y}_\infty+\stackrel{k}{\cdots}+\mathbf{y}_\infty\big]  &= \sum_{\theta^{(1)}\subseteq\theta^{(2)}\subseteq\cdots\subseteq\theta^{(k)}=\lambda} s_{\theta^{(1)}}s_{\theta^{(2)}/\theta^{(1)}}\cdots s_{\lambda/\theta^{(k-1)}} (\mathbf{y}_\infty). 
    \end{align*}
    By definition, $s_{\theta^{(i+1)}/\theta^{(i)}} = \sum_{\nu} c^{\theta^{(i+1)}}_{\theta^{(i)}\nu} s_\nu$, and hence
    \begin{align*}
        \textstyle
        s_\lambda\big[k \mathbf{y}_\infty\big]  &= \sum_{\substack{\theta^{(1)}\subseteq\theta^{(2)}\subseteq\cdots\subseteq\theta^{(k)}=\lambda\\\nu^{(2)},\ldots,\nu^{(k)}}} 
        c_{\theta^{(1)}\nu^{(2)}}^{\theta^{(2)}}
        c_{\theta^{(2)}\nu^{(3)}}^{\theta^{(3)}} \cdots 
        c_{\theta^{(k-1)}\nu^{(k)}}^{\lambda}
        s_{\nu^{(1)}}s_{\nu^{(2)}}\cdots s_{\nu^{(k)}} (\mathbf{y}_\infty). 
    \end{align*}
    Using associativity, and renaming $\theta^{(1)}$ to $\nu^{(1)}$, we get
    \begin{align*}
        \textstyle
        s_\lambda\big[k \mathbf{y}_\infty\big]  &= \sum_{\nu^{(1)},\nu^{(2)},\ldots,\nu^{(k)}} 
        c_{\bm{\nu}}^{\lambda}
        s_{\nu^{(1)}}s_{\nu^{(2)}}\cdots s_{\nu^{(k)}} (\mathbf{y}_\infty).
    \end{align*}
    Comparing the coefficients at $s_\mu$ on both sides gives the desired expression.
\end{proof}

\vspace{-.5em}
\begin{note}
To interpret $d_\lambda^\mu(k)$ combinatorially, we make the following observation. In the same way that $\smash{c_{\mu,\nu}^\lambda}$ counts the number of lattice tableaux of shape $\lambda/\mu$ and content $\nu$, the $k$-multi-Littlewood--Richardson coefficient $c_{\bm\nu}^\lambda$ counts the number of lattice $k$-multi-tableaux of multi-shape $\bm{\nu}$ and content $\lambda$ \cite[\S3 and Lem.~6.1]{SXP}.
\end{note}\medskip

Next, we explore the symmetries of $D(k)$.
\begin{lem}\label{lem:symmetries}
    The coefficients $d_\lambda^\mu(k)$ exhibit the following symmetries:
    \begin{enumerate}
        \item $d_\lambda^\mu(k) = d_\mu^\lambda(k)$,
        \item $d_\lambda^\mu(k) = d_{\lambda'}^{\mu'}(k)$,
        \item $d_\lambda^\mu(k) = d_{\lambda^\square}^{\mu^\square}(k)$, where the box-complement of $\lambda$ (resp.~$\mu$) is taken inside $L(b,a)$ (resp.~$L(d,c)$), for all choices of $a, b, c, d$ such that $c/a = b/d = k$.
    \end{enumerate}
\end{lem}
\begin{proof}~
    \begin{enumerate}
        \item This follows by the symmetry of $\lambda$ and $\mu$ in Proposition~\ref{p:coefs}.
        \item This follows from the equality $c^{\lambda}_{\mu,\nu} = c^{\lambda'}_{\mu',\nu'}$ of Littlewood--Richardson coefficients (obtained by taking the $\omega$ involution on the expansion of $s_\mu s_\nu$), and Proposition~\ref{p:coefs}. 
        \item This follows from the duality $c^{\lambda}_{\mu,\nu} = c^{\lambda^\square}_{\mu^\square,\nu^\square}$ of Littlewood--Richardson coefficients (see \cite{BriandRosas}) and Proposition~\ref{p:coefs}. \qedhere
    \end{enumerate}
\end{proof}
Note that part (1) states that the matrix $D(k)$ is symmetric, and (2) says that the blocks of $D(k)$ are anti-symmetric (invariant under transpositions across their anti-diagonal). The symmetry given by (3) is more subtle. 
Together, these symmetries endow $D(k)$ with a rich combinatorial structure.\medskip

Cauchy identity gives another formula for $d_\lambda^\mu(k)$.
\begin{p}
    For all $\lambda, \mu\in\Par$, we have
    $$d_\lambda^\mu(k) = \Big\langle
    s_\lambda(\mathbf{y}_\infty)s_\mu(\mathbf{z}_\infty), ~  \prod_{i,j} (1-y_jz_i)^{-k} \Big\rangle.$$
\end{p}
\begin{proof}
    Consider the following computation in $\Lambda[\mathbf{x}_\infty]$,
\begin{align*}
    \Bigg\langle
    s_\lambda, ~  \Big(\sum_{\nu \in \Par} s_\nu\Big)^k \Bigg\rangle
    &= \Big\langle
    s_\lambda, ~ \sum_{\bm{\nu} \in (\Par)^k} s_{\nu^{(1)}}\cdots s_{\nu^{(k)}}  \Big\rangle\\
    &=  \Big\langle s_\lambda,~ \sum_\mu \sum_{\bm{\nu} \in (\Par)^k} c_{\bm{\nu}}^\mu s_\mu  \Big\rangle = \sum_{\bm{\nu} \in (\Par)^k} c_{\bm{\nu}}^\lambda.
\end{align*}
Hence, applying Cauchy identity in $\Lambda[\mathbf{y}_\infty]\otimes\Lambda[\mathbf{z}_\infty]$, we obtain, by Proposition~\ref{p:coefs}:
\begin{align*}
    d_\lambda^\mu(k) = \sum_{\bm{\nu} \in (\Par)^k} c_{\bm{\nu}}^\lambda c_{\bm{\nu}}^\mu &=
    \Bigg\langle
    s_\lambda(\mathbf{y}_\infty)s_\mu(\mathbf{z}_\infty), ~  \Big(\sum_{\nu \in \Par} s_\nu(\mathbf{y}_\infty)s_\nu(\mathbf{z}_\infty)\Big)^k \Bigg\rangle
    \\ &= 
    \Big\langle
    s_\lambda(\mathbf{y}_\infty)s_\mu(\mathbf{z}_\infty), ~  \prod_{i,j} (1-y_jz_i)^{-k} \Big\rangle. \qedhere
\end{align*}
\end{proof}

The third formula for $d_\lambda^\mu(k)$ involves Kronecker products.
\begin{p}\label{p:Kronecker1}
    For all $\lambda,\mu\in\Par$, we have $d_\lambda^\mu(k) = (s_\lambda * s_\mu)(1, \stackrel{k}{\ldots}, 1)$.
\end{p}
\begin{proof}
    Note that $k\mathbf{y} = \mathbf{z}_k\mathbf{y}_{|z_i\mapsto 1}$.
    The generalised Cauchy identity gives
    \[
    s_\lambda[k\mathbf{y}_\infty] = s_\lambda[\mathbf{z}_k\mathbf{y}_\infty]_{|z_i\mapsto 1} =
    \sum_{\mu} (s_\lambda * s_\mu)(\mathbf{z}_k) \cdot s_\mu(\mathbf{y}_\infty)_{|z_i\mapsto 1}.
    \qedhere
    \]
\end{proof}
\begin{cor}\label{cor:d-expresion-ssyt}
    For all $\lambda,\mu\in\Par$, we have $d_\lambda^\mu(k) = \sum_{\nu} g_{\lambda\mu\nu} ~\#\mathrm{SSYT}_k(\nu)$.
\end{cor}
\begin{proof}
    If $|\lambda| \ne |\mu|$ the statement holds trivially. Suppose $|\lambda| = |\mu|$ and expand the Kronecker product to obtain
    \[
    s_\lambda * s_\mu(1, \stackrel{k}{\ldots}, 1) = \sum_\nu g_{\lambda\mu\nu} ~ s_{\nu}(1, \stackrel{k}{\ldots}, 1) 
         = 
        \sum_\nu g_{\lambda\mu\nu} ~\#\mathrm{SSYT}_k(\nu). \qedhere
    \]
\end{proof}

By the hook-content formula, $d_\lambda^\mu(k)$ is therefore a polynomial in $k$:
    \[
    d_\lambda^\mu(k) 
    = \sum_\nu g_{\lambda\mu\nu} \prod_{u\in Y(\nu)}\frac{k + c(u)}{ h(u)}.
    \]

We can now deduce necessary conditions for some entries of $D(k)$ to be zero or non-zero.
\begin{cor}
    If $k<\max\left(\frac{\ell(\lambda)}{\ell(\mu)}, \frac{\ell(\mu)}{\ell(\lambda)}\right)$ then $d_\lambda^\mu(k)=0$.
\end{cor}

\begin{proof}
    By the symmetry of $d_\lambda^\mu(k)$ established in Lemma~\ref{lem:symmetries}(1), we may assume $\ell(\lambda)\geq\ell(\mu)$ without loss of generality.

    Suppose $k<\ell(\lambda)/\ell(\mu)$ and let $\nu\in\Par$. If $k<\ell(\nu)$, then $\#\text{SSYT}_k(\nu)=0$. If $\ell(\nu)\leq k$, then by the hypothesis, $\ell(\nu)<{\ell(\lambda)}/{\ell(\mu)}$. Recall from \S\ref{sec:preliminaries} that  $g_{\lambda\mu\nu}\neq0$ implies $\ell(\nu)\leq\ell(\lambda)\ell(\mu)$ or, by symmetry of $g_{\lambda\mu\nu}$ in $\lambda,\mu,\nu$, also $\ell(\lambda)\leq\ell(\mu)\ell(\nu)$, which is not satisfied. Hence $g_{\lambda\mu\nu}=0$.

    We have shown that if $k<\ell(\lambda)/\ell(\mu)$ then for every $\nu\in\Par$ the expression $g_{\lambda\mu\nu}\cdot\#\text{SSYT}_k(\nu)$ is zero, and hence so is $d_\lambda^\mu(k)$, by Corollary~\ref{cor:d-expresion-ssyt}.
\end{proof}


\begin{cor}
    If $k>|\lambda\cap\mu'|$ then $d_\lambda^\mu(k)\neq0$.
\end{cor}

\begin{proof}
    Recall from \S\ref{sec:preliminaries} that $\max\{\ell(\nu): g_{\lambda\mu\nu}\neq 0\}=|\lambda\cap\mu'|$. Therefore, there exists $\nu_0\in\Par$ such that both $g_{\lambda\mu\nu_0}\neq 0$ and $\ell(\nu_0)=|\lambda\cap\mu'|<k$, and consequently $\#\text{SSYT}_k(\nu_0)>0$.
    Thus, by Corollary~\ref{cor:d-expresion-ssyt},
    \[
    d_\lambda^\mu(k)=\sum_\nu g_{\lambda\mu\nu}\cdot\#\text{SSYT}_k(\nu)\geq g_{\lambda\mu\nu_0}\cdot \#\text{SSYT}_k(\nu_0)>0. \qedhere
    \]
\end{proof}

