\subsection{The monomial basis matrix}
We now turn to the study of the coefficients of the $k$-fold map in the monomial basis. In matrix notation, let $K_{\lambda,\mu} = \langle s_\lambda, m_\mu\rangle$ be a \emph{Kostka coefficient} and let $K = (K_{\lambda,\mu})_{\lambda,\mu\in\Par}$ be the \emph{Kostka matrix}. We study the block-diagonal matrix $B(k) = K^{-1} \cdot D(k) \cdot K$.
\begin{de}
    For each $\lambda, \mu \in \Par$, define
    $b_\lambda^\mu(k)$ via $m_\lambda[k \mathbf{y}_\infty] = \sum_\mu b_\lambda^\mu(k) m_\mu(\mathbf{y}_\infty)$.
\end{de}
\begin{de}
    Given a multiset $A = \{\!\{a_1, a_2,\ldots,a_n\}\!\}$, 
    a \emph{multiset partition} of $A$ is a collection of multisets (\emph{parts}) $A^{(1)}, A^{(2)}, \ldots, A^{(\ell)}$ such that the union (with multiplicity) of the parts is $A$.

    We define the \emph{weight} of a multiset partition $A^{(1)}, A^{(2)}, \ldots, A^{(\ell)}$ as the tuple $w=(w_1, w_2, \ldots, w_\ell)$, where $w_i$ is the sum of elements of $A^{(i)}$ (with multiplicity). 
    When $k \mid n$, let $\mathcal{P}_{k}(A,w)$ be the set of
    multiset partitions of $A$ of weight $w$, and in which each part has $k$ elements (with multiplicity).
\end{de}
\begin{p}
    Let $|\lambda|=|\mu|$ and $A = \{\!\{\lambda_i  : i = 1, \ldots, k\ell(\mu)\}\!\}$. Then
    \[
    b_{\lambda}^\mu(k) =
    \sum_{\mathcal{P}_{k}(A,\mu)}~
    \prod_{i=1}^{\ell(\mu)}
    \frac{k!}{m_0(A^{(i)})!~m_1(A^{(i)})!\cdots},
    \]
    where $m_j(A^{(i)})$ is the multiplicity of $j$ in $A^{(i)}$.
\end{p}
\begin{proof}
    Let $\ell=\ell(\mu)$. The monomial $y_1^{\mu_1}y_2^{\mu_2}\cdots y_\ell^{\mu_\ell}$ appears in $m_\lambda[k\mathbf{y}_\infty]$ if and only if there is a monomial in $m_\lambda(\mathbf{x}_\infty)$ of the form
    \[
    \Big(x_1^{a_1} x_2^{a_2} \cdots x_{k}^{a_k}\Big)
    \Big(x_{k+1}^{a_{k+1}} \cdots x_{2k}^{a_{2k}}\Big)
    \cdots 
    \Big(x_{(\ell-1)k+1}^{a_{(\ell-1)k+1}} \cdots x_{k\ell}^{a_{k\ell}}\Big)
    \]
    with $a_{(i-1)k+1}+\cdots+a_{ik} = \mu_i$ for all $i$. Hence $A^{(i)} = \{\!\{a_{(i-1)k+1},\ldots,a_{ik}\}\!\}$ defines a multiset partition of $A$ of weight $\mu$ and with $k$ elements in each part.

    For the $i$th parenthesis of the above expression, there are
    \[
    \frac{k!}{m_0(A^{(i)})!~m_1(A^{(i)})!\cdots}
    \]
    ways of reordering the exponents $a_{(i-1)k+1}, \ldots, a_{ik}$.
\end{proof}
In particular, we show shortly that $B(k)$ is lower-triangular. The diagonal is thus $\mathrm{diag}(k^{\ell(\lambda)})_{\lambda\in\Par}$, since $B(k)$ is conjugate to the matrix $X^{-1}D(k)X$ of the $k$-fold map in the power sum basis.
\begin{cor}
    If $b_\lambda^\mu(k) \ne 0$ then $\mu \ge \lambda$ in the lexicographic order.
\end{cor}
\begin{proof}
    If there exists a multiset partition of $\{\!\{\lambda_i  : i = 1, \ldots, k\ell(\mu)\}\!\}$ of weight $\mu$, then clearly $\mu \ge \lambda$.
\end{proof}

Again, we can obtain a formula in terms of Kronecker products.
\begin{p}\label{p:b-expresion-Kronecker}
    For all $\lambda,\mu\in\Par$, we have $b_\lambda^\mu(k) = (m_\lambda*h_\mu)(1,\stackrel{k}{\ldots},1)$.
\end{p}
\begin{proof}
It follows from Proposition \ref{p:Kronecker1} and bilinearity,
    \begin{align*}
        b_\lambda^\mu(k) &= \langle m_\lambda[k \mathbf{y}_\infty], h_\mu(\mathbf{y}_\infty) \rangle\\
        &= \sum_{\rho,\nu} K^{-1}_{\rho,\lambda} K_{\nu,\mu} \langle s_\rho[k \mathbf{y}_\infty], s_\nu(\mathbf{y}_\infty) \rangle\\
              &= \sum_{\rho,\nu}K^{-1}_{\rho,\lambda} K_{\nu,\mu} ~(s_\rho*s_\nu)(1, \stackrel{k}{\ldots}, 1)
              = m_\lambda*h_\mu(1, \stackrel{k}{\ldots}, 1). \qedhere
    \end{align*}
\end{proof}

