% --- Algorithm 1: Standard DDIM Sampling -

\begin{figure}[H]
\tiny % Reduce font size for this algorithm
\begin{algorithm}[H] % The [H] attempts to place the algorithm "here"
\caption{Standard DDIM Sampling}
\label{alg:standard_ddim}
\begin{algorithmic}[1] % Number lines
\Require
    Model $\bm{\epsilon}_\theta$, condition: $\cbm$, Schedule $\bar{\alpha}_t$
\State $\zbm_T \sim \mathcal{N}(0, \mathbf{I})$ \Comment{Init noise}
\For{$t = T, \dots, 1$}
    \State $\bm{\epsilon}_{\theta, t} \leftarrow \bm{\epsilon}_\theta(\zbm_t, t, \cbm)$ \Comment{Predict noise}
    \State $\hat{\zbm}_{0|t} \leftarrow (\zbm_t - \sqrt{1-\bar{\alpha}_t} \bm{\epsilon}_{\theta, t}) / \sqrt{\bar{\alpha}_t}$ \Comment{Predict $\zbm_0$}
    \State $\bm{\epsilon}'_{t} \leftarrow (\zbm_t - \sqrt{\bar{\alpha}_t} \hat{\zbm}_{0|t}) / \sqrt{1 - \bar{\alpha}_t}$ \Comment{Update direction based on $\hat{\zbm}_{0|t}$}
    \State $\zbm_{t-1} \leftarrow \sqrt{\bar{\alpha}_{t-1}} \hat{\zbm}_{0|t} + \sqrt{1 - \bar{\alpha}_{t-1}} \bm{\epsilon}'_{t}$ \Comment{DDIM step}
\EndFor
\State \Return $\zbm_0$
\end{algorithmic}
\end{algorithm}
\end{figure}



% --- Algorithm 2: DDIM + KDS  ---
\begin{figure}[H]
\scriptsize % Slightly larger font than \tiny
\begin{algorithm}[H]
\caption{DDIM + KDS}
\label{alg:guided_ddim_direct_ms_vector}
\begin{algorithmic}[1] % Number lines
\Require
    Model $\bm{\epsilon}_\theta$, Schedule $\bar{\alpha}_t$, condition: $\cbm$, Number of particles: $N$, bandwidth: $h$, steering strength: $\delta_t$, $\text{PatchSize}$
\State $\Zbm_T \sim \mathcal{N}(0, \mathbf{I})$ (ensemble of $N$ samples) \Comment{Init noise ensemble}
\For{$t = T, \dots, 1$}
    \State $\mathbf{E}_{\theta, t} \leftarrow \bm{\epsilon}_\theta(\Zbm_t, t, \cbm)$ \Comment{Predict ensemble noise}
    \State $\hat{\Zbm}_{0|t}^{\text{pred}} \leftarrow (\Zbm_t - \sqrt{1-\bar{\alpha}_t} \mathbf{E}_{\theta, t}) / \sqrt{\bar{\alpha}_t}$ \Comment{Predict $\mathbf{x}_0$ ensemble}

    % --- KDS Patch-wise Mechanism Start ---
    \State $\textbf{Patches} \leftarrow \text{Patchify}(\hat{\Zbm}_{0|t}^{\text{pred}})$ 
        \Comment{Extract all non-overlapped patches: $\textbf{Patches}[k,loc]$.}
    \For{each patch location $j$} \Comment{This loop over patch locations,  can be executed \textbf{in parallel}.}
        \State $\Pbm_j \leftarrow \textbf{Patches}[:, j]$ 
            \Comment{Ensemble of $N$ original patches at location $j$.}
        \For{$i=1, \dots, N$} \Comment{For particle $i$'s patch at location $j$, can be computed \textbf{in parallel}.}
            \State $\pbm_j^{(i)} \leftarrow \Pbm_j[i]$ \Comment{Patch from particle $i$ at location $j$.}
            \State $\mathbf{m}(\pbm_j^{(i)}) \leftarrow \frac{\sum_{k=1}^N G\left(\frac{\|\pbm_j^{(i)} - \Pbm_j^{(k)}\|^2}{h^2}\right) \Pbm_j^{(k)}}{\sum_{k=1}^N G\left(\frac{\|\pbm_j^{(i)} - \Pbm_j^{(k)}\|^2}{h^2}\right)} - \pbm_j^{(i)}$ 
                \Comment{Mean shift vector (Eq.~\ref{eq:patch_mean_shift_vector_revised}).}
            \State $\hat{\pbm}_{j}^{(i),\text{KDS}} \leftarrow \pbm_j^{(i)} + \delta_t \mathbf{m}(\pbm_j^{(i)})$ \Comment{Apply steering (Eq.~\ref{eq:pkdg_update_with_m_vector})}
            \State $\textbf{Patches}[i,j] \leftarrow \hat{\pbm}_{j}^{(i),\text{KDS}}$ 
                \Comment{Update the patch set with the guided patch.}
        \EndFor
    \EndFor
    \State $\hat{\Zbm}_{0|t}^{\text{KDS}} \leftarrow \text{Unpatchify}(\textbf{Patches})$ \Comment{Reconstruct guided latent prediction.}
    % --- KDS Patch-wise Mechanism End ---

    \State $\mathbf{E}'_{t} \leftarrow (\Zbm_t - \sqrt{\bar{\alpha}_t} \hat{\Zbm}_{0|t}^{\text{KDS}}) / \sqrt{1 - \bar{\alpha}_t}$ \Comment{Update direction}
    \State $\Zbm_{t-1} \leftarrow \sqrt{\bar{\alpha}_{t-1}} \hat{\Zbm}_{0|t}^{\text{KDS}} + \sqrt{1 - \bar{\alpha}_{t-1}} \mathbf{E}'_{t}$ \Comment{DDIM step}
\EndFor
\State \Return $\hat{\Zbm}_0^{\text{KDS}}$ \Comment{Return KDS-guided result}
\end{algorithmic}
\end{algorithm}
\end{figure}

% --- Algorithm 2: DDIM + KDS (Direct Mean Shift Vector Calculation) ---
\begin{figure}[H]
\scriptsize % Slightly larger font than \tiny
\begin{algorithm}[H]
\caption{DDIM + CFG + KDS}
\label{alg:guided_cfg_ddim_direct_ms_vector}
\begin{algorithmic}[1] % Number lines
\Require
    Model $\bm{\epsilon}_\theta$, Schedule $\bar{\alpha}_t$, condition: $\cbm$, Number of particles: $N$, bandwidth: $h$, steering strength: $\delta_t$, CFG strength: $w$, $\text{PatchSize}$
\State $\Zbm_T \sim \mathcal{N}(0, \mathbf{I})$ (ensemble of $N$ samples) \Comment{Init noise ensemble}
\For{$t = T, \dots, 1$}
    \State $\mathbf{E}_{\theta, t} \leftarrow \epsilonbm_\theta(\Zbm_t, t, \varnothing) + w (\epsilonbm_\theta(\Zbm_t, t, \cbm) - \epsilonbm_\theta(\Zbm_t, t, \varnothing)) $ \Comment{Predict ensemble noise with CFG}
    \State $\hat{\Zbm}_{0|t}^{\text{pred}} \leftarrow (\Zbm_t - \sqrt{1-\bar{\alpha}_t} \mathbf{E}_{\theta, t}) / \sqrt{\bar{\alpha}_t}$ \Comment{Predict $\mathbf{x}_0$ ensemble}
    \State $\hat{\Zbm}_{0|t}^{\text{KDS}} \leftarrow \textbf{Patch-wise KDS}(\hat{\Zbm}_{0|t}^{\text{pred}})$ \Comment{Same as Step 5-15 in Algorithm~\ref{alg:guided_ddim_direct_ms_vector}}
    % --- KDS Patch-wise Mechanism End ---

    \State $\mathbf{E}'_{t} \leftarrow (\Zbm_t - \sqrt{\bar{\alpha}_t} \hat{\Zbm}_{0|t}^{\text{KDS}}) / \sqrt{1 - \bar{\alpha}_t}$ \Comment{Update direction based on KDS-guided $\mathbf{x}_0$}
    \State $\Zbm_{t-1} \leftarrow \sqrt{\bar{\alpha}_{t-1}} \hat{\Zbm}_{0|t}^{\text{KDS}} + \sqrt{1 - \bar{\alpha}_{t-1}} \mathbf{E}'_{t}$ \Comment{DDIM step with KDS-guided $\mathbf{x}_0$}
\EndFor
\State \Return $\hat{\Zbm}_0^{\text{KDS}}$ \Comment{Return KDS-guided result}
\end{algorithmic}
\end{algorithm}
\end{figure}

\begin{algorithm}[H]
    \centering
    \caption{DPM-Solver++.}\label{alg:dpm-solver++}
    \begin{algorithmic}[1]
    \Require initial value $\Zbm_T$, time steps $\{t_i\}_{i=0}^M$ and $\{s_i\}_{i=1}^{M}$, data prediction model $\Zbm_\theta$.
        \State $\Zbm_T \sim \mathcal{N}(0, \mathbf{I})$ (ensemble of $N$ samples) \Comment{Init noise ensemble}
        \State $\tilde\Zbm_{t_0}\gets\Zbm_T$.
        \For{$i\gets 1$ to $M$}
        \State $h_i \gets \lambda_{t_{i}} - \lambda_{t_{i-1}}$
        \State $r_i \gets \frac{\lambda_{s_{i}} - \lambda_{t_{i-1}}}{h_i}$
        \State $\hat{\Zbm}_{0|t}^{\text{pred}} \leftarrow \Zbm_\theta(\tilde\Zbm_{t_{i-1}}, t_{i-1})$
        \State $\Ubm_{i} \gets \frac{\sigma_{s_{i}}}{\sigma_{t_{i-1}}}\tilde\Zbm_{t_{i-1}} - \alpha_{s_{i}}\left(e^{-r_i h_i} - 1\right)\hat{\Zbm}_{0|t}^{\text{pred}}$

        \State $\hat{\Ubm}_{0|s}^{\text{pred}} \leftarrow \Zbm_\theta(\Ubm_{i}, s_{i})$
        \State $\Dbm_i \gets
            (1-\frac{1}{2r_i})\hat{\Zbm}_{0|t}^{\text{pred}} + \frac{1}{2r_i}\hat{\Ubm}_{0|s}^{\text{pred}}$
        \State $\tilde\Zbm_{t_{i}} \gets \frac{\sigma_{t_i}}{\sigma_{t_{i-1}}}\tilde\Zbm_{t_{i-1}} - \alpha_{t_{i}}\left(e^{-h_i} - 1\right)\Dbm_i$
        \EndFor
        \State \Return $\tilde\Zbm_{t_M}$
    \end{algorithmic}
\end{algorithm}



\begin{algorithm}[H]
    \centering
    \caption{DPM-Solver++ with KDS.}\label{alg:dpm-solver++s}
    \begin{algorithmic}[1]
    \Require initial value $\Zbm_T$, time steps $\{t_i\}_{i=0}^M$ and $\{s_i\}_{i=1}^{M}$, data prediction model $\Zbm_\theta$.
        \State $\Zbm_T \sim \mathcal{N}(0, \mathbf{I})$ (ensemble of $N$ samples) \Comment{Init noise ensemble}
        \State $\tilde\Zbm_{t_0}\gets\Zbm_T$.
        \For{$i\gets 1$ to $M$}
        \State $h_i \gets \lambda_{t_{i}} - \lambda_{t_{i-1}}$
        \State $r_i \gets \frac{\lambda_{s_{i}} - \lambda_{t_{i-1}}}{h_i}$
        \State $\hat{\Zbm}_{0|t}^{\text{pred}} \leftarrow \Zbm_\theta(\tilde\Zbm_{t_{i-1}}, t_{i-1})$
        \State $\hat{\Zbm}_{0|t}^{\text{KDS}} \leftarrow \textbf{Patch-wise KDS}(\hat{\Zbm}_{0|t}^{\text{pred}})$ \Comment{Same as Step 5-15 in Algorithm~\ref{alg:guided_ddim_direct_ms_vector}}

        \State $\Ubm_{i} \gets \frac{\sigma_{s_{i}}}{\sigma_{t_{i-1}}}\tilde\Zbm_{t_{i-1}} - \alpha_{s_{i}}\left(e^{-r_i h_i} - 1\right)\hat{\Zbm}_{0|t}^{\text{KDS}}$

        \State $\hat{\Ubm}_{0|s}^{\text{pred}} \leftarrow \Zbm_\theta(\Ubm_{i}, s_{i})$
        \State $\hat{\Ubm}_{0|s}^{\text{KDS}} \leftarrow \textbf{Patch-wise KDS}(\hat{\Ubm}_{0|s}^{\text{pred}})$ \Comment{Same as Step 5-15 in Algorithm~\ref{alg:guided_ddim_direct_ms_vector}}

        \State $\Dbm_i \gets
            (1-\frac{1}{2r_i})\hat{\Zbm}_{0|t}^{\text{KDS}} + \frac{1}{2r_i}\hat{\Ubm}_{0|s}^{\text{KDS}}$
        \State $\tilde\Zbm_{t_{i}} \gets \frac{\sigma_{t_i}}{\sigma_{t_{i-1}}}\tilde\Zbm_{t_{i-1}} - \alpha_{t_{i}}\left(e^{-h_i} - 1\right)\Dbm_i$
        \EndFor
        \State \Return $\tilde\Zbm_{t_M}$
    \end{algorithmic}
\end{algorithm}



