\section{Proof of continuum model} \label{appendix:continuum_model}
When the amplifier $c \longrightarrow 0$, the replacement rate $r$ of an individual to become another individual, let's say for a resident $u$ on node $n_i$ to be replaced by a mutant $v$ whose parent is on $n_j$, is defined as \cite{EGTMarkovContinuous}
\begin{equation} \label{eq:replacement_rate}
\begin{split}
r & = r(u,v,n_i,n_j) \\
r(u,v,n_i,n_j) & = s \left( \beta_{u} w_{n_i,n_j} \frac{\delta_{v} + \gamma_{v,u}}{\delta_{v} + \gamma_{v,u} + \delta_u + \gamma_{u,v}} \right) + \delta_{v} \left( \frac{\beta_{u} w_{n_i,n_j}}{\sum_{0}^{k \setminus \{j\}} \beta_{k} w_{n_k,n_j}} \right)  \\
r(u,v,n_i,n_j)& = A \times \frac{B}{C} + \text{D} \times \frac{\text{E}}{F}  
\end{split}
\end{equation}
where 
\begin{itemize}
    \item A is the birth rate for $u$ on node $n_i$ with offspring to be placed and surviving on $n_j$ 
    %if the number of individuals on the node $n_j$ is 1 (the offspring survives) - not sure if this is making sense to me anymore 
    \item B is the death rate of $v$
    \item C is the total death rate of $u$ and $v$
    \item D is the natural death rate of an individual of $v$
    \item E is product of fitness of $v$ and the graph weight edge between $n_i$ and $n_j$
    \item F is sum of product of birth rates and graph rates excluding $u_j$ 
\end{itemize}
In EGT we require replacement probability rather than rates. To get the probability of replacement of individual $u$ by individual $v$ we would need to divide by the sum of all possible replacements rates, hence the probability of replacement is defined as \cite{EGTMarkovContinuous} 
\begin{equation} \label{eq:def_replacement_probability}
    R(u,v) = \frac{r(u,v,n_i,n_j)}{\sum_{f \in S} \sum_{k \in S}  r(f,k,n_f,n_k)}
\end{equation}
where $S$ is the set of all the individuals' traits.\cite{EGTMarkovContinuous} 
\newline \newline 
If $\delta_i=\delta_j = \delta$ and $\gamma_{i,j} = \gamma_{j,i} = \gamma$, then
\begin{equation}
\begin{split}
&  \frac{\delta_j + \gamma_{j,i}}{\delta_j + \gamma_{j,i} + \delta_i + \gamma_{i,j}} \\
& = \frac{\delta + \gamma}{\delta + \gamma + \delta + \gamma} \\
& =  \frac{1(\delta+ \gamma)}{2(\delta+ \gamma)} \\
& = \frac{1}{2}
\end{split}
\end{equation}
Then 
\begin{equation} \label{eq:replacement_rate_sim}
    r(i,j,n_i,n_j) = s \beta_i w_{n_i,n_j} \frac{1}{2} + \frac{\delta_j \beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}}
\end{equation}
Taking the replacement rate \ref{eq:replacement_rate_sim} and substituting it into \ref{eq:def_replacement_probability} gives \cite{EGTMarkovContinuous} 
\begin{equation} \label{eq:replacement_probability_not_simplified}
\begin{split}
    R(i,j)& = \frac{ r(i,j,n_i,n_j)}{\sum_l \sum_m r(l,m,n_l,n_m)} \\
    R(i,j)& = \frac{ s \beta_i w_{n_i,n_j} \frac{1}{2} + \frac{\delta_j \beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}} }
    {\sum_l \sum_m  s \beta_l w_{n_l,n_m} \frac{1}{2} + \frac{\delta_m \beta_l w_{n_l,n_m}}{\sum_{k \neq m}  \beta_k w_{n_k,n_m}}}
\end{split}   
\end{equation}
The denominator can be rewritten as 
\begin{align*}
\begin{split}
& \sum_l \sum_m  s \beta_l w_{n_l,n_m} \frac{1}{2} + \frac{\delta_m \beta_l w_{n_l,n_m}}{\sum_{k \neq m}  \beta_k w_{n_k,n_m}} \\
& = \sum_l \sum_m \beta_l w_{n_l,n_m} s \frac{1}{2}
+ \sum_l \sum_m \delta_m \frac{\beta_l w_{n_l,n_m}}{\sum_{k \neq m}  \beta_k w_{n_k,n_m}}
\end{split}
\end{align*}
We note that an individual who has died, cannot then produce the offspring, so for the second sum of the second term we impose an extra condition on the sum \cite{EGTMarkovContinuous}
\begin{align*}
 = \sum_l \sum_m \beta_l w_{n_l,n_m} s \frac{1}{2}
+ \sum_l \sum_{m \neq n} \delta_m \frac{\beta_l w_{n_l,n_m}}{\sum_{k \neq m}  \beta_k w_{n_k,n_m}}
\end{align*}
We note that $r(l,m,n_l,n_m) = r(m,l,n_m,n_l)$\cite{EGTMarkovContinuous}, which means
\begin{align*}
\delta_m \frac{\beta_l w_{n_l,n_m}}{\sum_{k \neq m}  \beta_k w_{k,m}} = 
\delta_l \frac{\beta_m w_{n_m,n_l}}{\sum_{k \neq l} \beta_k w_{k,l}}
\end{align*}
So the denominator can be rewritten as
\begin{align*}
\sum_l \sum_m \beta_l w_{n_l,n_m} s \frac{1}{2}
+ \sum_l \sum_{m \neq l} \delta_l \frac{\beta_m w_{n_m,n_l}}{\sum_{k \neq l} \beta_k w_{n_k,n_l}}
\end{align*}
We note that in the first term $s \frac{1}{2}$ are independent of $l$ and $m$ and $\beta_l$ is independent of $m$. For the second term, $\delta_l$ and $\sum_{k \neq l} \beta_k w_{k,l}$ is independent of $m$. This means that the denominator can be rearranged as 
\begin{align*}
s \frac{1}{2} \sum_l \beta_l \sum_m  w_{n_l,n_m} 
+ \sum_l \delta_l \frac{ \sum_{m \neq l} \beta_m w_{n_m,n_l}}{\sum_{k \neq l} \beta_k w_{n_k,n_l}}
\end{align*}
As $k=m$, then $\frac{ \sum_{m \neq l} \beta_m w_{n_m,n_l}}{\sum_{k \neq l} \beta_k w_{n_k,n_l}} = 1$, so then the denominator is equal to  
\begin{align} \label{eq:replacement_probability_denominator_simplifier}
s \frac{1}{2} \sum_l \beta_l \sum_m  w_{n_l,n_m} + \sum_l \delta_l
\end{align}
If $l=N$ and $\delta_l$ is the same for all individuals then 
\begin{align} \label{eq:replacement_probability_denominator_simplifier_v2}
s \frac{1}{2} \sum_l \beta_l \sum_m  w_{n_l,n_m} + N\delta
\end{align}
Substituting \ref{eq:replacement_probability_denominator_simplifier_v2} back into \ref{eq:replacement_probability_not_simplified} gives 
\begin{align} \label{eq:replacement_probability_simplified}
    R(i,j) =  \frac{s \frac{1}{2} \beta_i w_{n_i,n_j} + \delta_j \frac{\beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}}}
{s \frac{1}{2} \sum_l \beta_l \sum_m  w_{n_l,n_m} + N\delta}
\end{align}
We note that the replacement probability of Bd is \cite{EGTMarkovContinuous,pattni2015evolutionary}
\begin{equation} \label{eq:replacement_probability_Bd}
    R(i,j)_{Bd} = \frac{\beta_i w_{i,j}}{\sum_n \beta_n w_{i,n}}
\end{equation}
The replacement probability of dB is \cite{EGTMarkovContinuous,pattni2015evolutionary}
\begin{equation} \label{eq:replacement_probability_dB}
    R(i,j)_{dB} = \frac{1}{N}\frac{\beta_i w_{i,j}}{\sum_n \beta_n w_{n,j}}
\end{equation}
\cite{EGTMarkovContinuous} proved that taking $s=1$ and $\delta=0$ gives Bd replacement probability (\ref{eq:replacement_probability_Bd}) and taking take $s=0$ and $\delta=1$ gives dB replacement probability (\ref{eq:replacement_probability_dB}). 
%\newline \newline 
%We note that no matter what the value of $\delta$ is, if $s=0$, the dynamics are always dB.
\newline \newline 
Now let's consider the scenario where neither $s$ or $\delta$ are zero. Assuming that $\delta$ is the same value for all individuals in a population of size $N$, and $s=1$, this gives the replacement probability 
\begin{align*}
R(i,j) = \frac{\frac{1}{2} \beta_i w_{n_i,n_j} + \delta \frac{\beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}}}
{ s \frac{1}{2} \sum_l \beta_l \sum_m  w_{n_l,n_m} + N\delta}
\end{align*}
Factorizing by $\delta$ gives
\begin{align*}
\begin{split}
R(i,j) & = \frac{\delta}{\delta} \frac{\frac{1}{2} \beta_i w_{n_i,n_j} \frac{1}{\delta} + \frac{\beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}}}
{\frac{1}{2} \sum_l \beta_l \sum_m  w_{n_l,n_m} \frac{1}{\delta} +  N }\\
& = \frac{\frac{1}{2} \beta_i w_{n_i,n_j} \frac{1}{\delta} + \frac{\beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}}}
{\frac{1}{2} \frac{1}{\delta} \sum_l \beta_l \sum_m  w_{n_l,n_m}  +  N }
\end{split}
\end{align*}
Taking $\delta \longrightarrow \infty$ so $\frac{1}{\delta} \approx 0$ gives 
\begin{align}
\begin{split}
R(i,j) & \approx \frac{ \frac{\beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}}}
{  N }\\ 
& \approx \frac{1}{N} \frac{\beta_i w_{n_i,n_j}}{\sum_{k \neq j}  \beta_k w_{n_k,n_j}}
\end{split}
\end{align}
which is the same as replacement rate for dB dynamics, \ref{eq:replacement_probability_dB}.
Hence for large value of $\delta$ the system would be in dB dynamics. 

