\section{Full derivation of the fixation probability difference and finding the upper bound critical value $\delta_c$} \label{appendix:upper_bound_critical}
Here we show the full derivation of the difference between star graph fixation probability and complete graph fixation probability. 
\newline \newline 
The fixation probability for the \textbf{complete} graph is given by \cite{EGTMarkovContinuous}
\begin{equation} \label{eq:complete_fp}
    \rho_{\text{complete}} = \frac{1}{1 + \sum^{N-1}_{j=1} \Pi^{j}_{k=1} r_k}
\end{equation}
where,
\begin{equation} \label{eq:r_unsimplified}
    r_k = \frac{s \beta_0 w \frac{\delta_1 + \gamma_{1,0}}{\delta_0 + \delta_1 + \gamma_{0,1} + \gamma_{1,0}} + \delta_1 \beta_0 \frac{1}{(N-k)\beta_0 + (k-1)\beta_1}} {s \beta_1 w \frac{\delta_0 + \gamma_{0,1}}{\delta_0 + \delta_1 + \gamma_{0,1} + \gamma_{1,0}} + \delta_0 \beta_1 \frac{1}{(N-k-1)\beta_0 + k \beta_1}}
\end{equation}
If $\delta=\delta_0=\delta_1$ and $\gamma=\gamma_{0,1}=\gamma_{1,0}$, then 
\begin{equation} \label{eq:r_halfsimplified}
    r_k = \frac{s \beta_0 w \frac{1}{2} + \delta \beta_0 \frac{1}{(N-k)\beta_0 + (k-1)\beta_1}} {s \beta_1 w \frac{1}{2} + \delta \beta_1 \frac{1}{(N-k-1)\beta_0 + k \beta_1}}
\end{equation}
Note that when this is the case, the competition coefficients disappear. 
For complete graphs with self-loops, $w=\frac{1}{N}$. 
\newline \newline 
The fixation probability for the \textbf{star} graph is given by \cite{EGTMarkovContinuous}
\begin{equation} \label{eq:star_fp}
    \rho_{\text{star}} = \frac{a + b}{1 + \sum^{N-2}_{j=1} c(j) \Pi^{j}_{k=1} d(j)}
\end{equation}
\begin{equation} \label{eq:a_unsimplified}
    a = \frac{1}{N} \frac{ \frac{s}{2} w_c \beta_1 + \delta}{ \frac{s}{2} (w_c \beta_1 + w_l \beta_0) + \delta \frac{N}{N-1}}
\end{equation}
\begin{equation}  \label{eq:b_unsimplified}
    b = \frac{N}{N-1} \frac{\frac{s}{2} w_l \beta_1 + \delta \beta_1 \frac{1}{(N-2)\beta_0 + \beta_1}}{ \frac{s}{2} (w_l \beta_1 + w_c \beta_0) + \delta \frac{(N-2)\beta_0 + 2 \beta_1}{(N-2)\beta_0 + \beta_1} }
\end{equation}
\begin{equation}  \label{eq:c_unsimplified}
    c(j) = \frac{\frac{s}{2} w_l \beta_0 + \delta \beta_0 \frac{1}{(N-1-j)\beta_0 + j\beta_1}}{\frac{s}{2} (w_l \beta_0 + w_c \beta_1) + \delta \frac{(N-j)\beta_0 + j \beta_1}{(N-1-j) \beta_0 + j\beta_1}}
\end{equation}
\begin{equation}  \label{eq:d_unsimplified}
    d(k) = \frac{\frac{s}{2} w_c \beta_0 + \delta}{ \frac{s}{2} w_c \beta_1 + \delta} \frac{\frac{s}{2} (w_c \beta_1 + w_l \beta_0) + \delta \frac{(N-k)\beta_0 + k\beta_1}{(N-1-k)\beta_0 + k\beta_1}}{\frac{s}{2} (w_c \beta_0 + w_l \beta_1) + \delta \frac{(N-1-k)\beta_0 + (k+1)\beta_1}{(N-1-k)\beta_0 + k\beta_1}}
\end{equation}
We assume that $\delta = \delta_0 = \delta_1$ and $\gamma = \gamma_{0,1} = \gamma_{1,0}$.
From definition of star, $w_l = \frac{1}{2}$ and $w_c = \frac{1}{N}$. \cite{EGTMarkovContinuous} 
\newline \newline 
Taking the difference of the fixation probability (equations \ref{eq:star_fp} and \ref{eq:complete_fp}) gives 
\begin{equation} \label{eq:star_complete_difference}
\begin{aligned} 
    \rho_{\text{star}} - \rho_{\text{complete}} = \\ \frac{ (a+b - 1) + (a+b)\sum^{N-1}_{j=1} \Pi^{j}_{k=1} r_k - \sum^{N-2}_{j=1} c(j) \Pi^{j}_{k=1} d(k)}{1 + \sum^{N-2}_{j=1} c(j) \Pi^{j}_{k=1} d(k) + \sum^{N-1}_{j=1} \Pi^{j}_{k=1} r_k + (\sum^{N-2}_{j=1} c(j) \Pi^{j}_{k=1} d(k))(\sum^{N-1}_{j=1} \Pi^{j}_{k=1} r_k)}
\end{aligned}
\end{equation}
To simplify equation \ref{eq:star_complete_difference}, let's take a large value of $N$, i.e. limit of $N$ to infinity, $N \longrightarrow \infty$.
\newline \newline 
Using this, the expressions \ref{eq:r_halfsimplified},\ref{eq:a_unsimplified},  \ref{eq:b_unsimplified},\ref{eq:c_unsimplified},\ref{eq:d_unsimplified} become  
\begin{equation} \label{eq:a_simplified}
    a = 0
\end{equation}
\begin{equation} \label{eq:b_simplified}
    b = \frac{s w_l \beta_1}{ s w_l \beta_1 + s w_c \beta_0 +  2\delta }
\end{equation}
\begin{equation} \label{eq:c_simplified}
    c(j) = \frac{s w_l \beta_0}{s w_l \beta_0 + s w_c \beta_1 + 2\delta}
\end{equation}
\begin{equation} \label{eq:d_simplified}
    d(k) = \left( \frac{s w_c \beta_0 + 2\delta}{ s w_c \beta_1 + 2\delta} \right) \left( \frac{s w_c \beta_1 + s w_l \beta_0 + 2\delta}{s w_c \beta_0 + s w_l \beta_1 + 2\delta} \right)
\end{equation}
\begin{equation} \label{eq:r_simplified}
    r_k = \frac{\beta_0}{\beta_1}
\end{equation}
Note that now $c$ is independent of $j$ and $d$ is independent of $k$. Therefore
\begin{equation*}
    \sum^{\infty}_{j=1} c(j) \Pi^{j}_{k=1} d(k) =  \sum^{\infty}_{j=1} c d^j  = \frac{cd}{1-d}
\end{equation*}
using the rules for geometric series, $\sum^{\infty}_{k=m} a r^k = \frac{a r^m}{1-r}$, with $|r| < 1$. \\
Similarly,
\begin{equation*}
    \sum^{\infty}_{j=1} \Pi^{j}_{k=1} r_k = \sum^{\infty}_{j=1} r_k^j = \frac{r_k}{1-r_k}
\end{equation*}
So the equation \ref{eq:star_complete_difference} becomes 
\begin{equation} \label{eq:star_complete_difference_simplified}
    \rho_{\text{star}} - \rho_{\text{complete}} = \frac{ (b - 1) + b \frac{r_k}{1-r_k} - \frac{cd}{1-d}}{1 +  \frac{cd}{1-d} +  \frac{r_k}{1-r_k} + ( \frac{cd}{1-d})( \frac{r_k}{1-r_k})}
\end{equation}
It can be noted that equation \ref{eq:d_simplified} has a $\delta$ and $\delta^2$ if the fractions are expanded and combined. 
\begin{equation*}
    d =  \frac{s w_c \beta_0 s w_c \beta_1 + s w_c \beta_0 s w_l \beta_0 + 2\delta(s w_c \beta_0 + s w_c \beta_1 + s w_l \beta_0) + 4\delta^2}{ s w_c \beta_1 s w_c \beta_0 +s w_c \beta_1 s w_l \beta_1 + 2\delta (s w_c \beta_1 +  s w_c \beta_0 + s w_l \beta_1) + 4\delta^2} 
\end{equation*}
The assumption is that $N$ is very large, so $\frac{1}{N} \approx 0$. Therefore we must assume all other variables are sufficiently larger than $\frac{1}{N}$. Since $\frac{1}{N} < 1$, a sufficient condition for $\delta$ and $\delta^2$ to be larger enough is $\delta^2 \gg \frac{1}{N}$. Hence the limiting factor is that 
\begin{equation} \label{eq:true_hold}
  \delta > \frac{1}{\sqrt{N}}
\end{equation}
\newline \newline 
As working in the framework of the continuum model, so setting $s=1$. We assume that $\beta_0=1$ and $\beta_1=r$ \cite{ReviewGraphGameTheoryApplication}. $w_c=w=\frac{1}{N}$, $w_l = \frac{1}{2}$ from graph properties \cite{EGTMarkovContinuous}. This gives
\begin{equation}
    b = \frac{r}{ r+  4\delta }
\end{equation}
\begin{equation}
    c = \frac{1}{1 + 4\delta}
\end{equation}
\begin{equation}
    d = \frac{1 + 4\delta}{r + 4\delta}
\end{equation}
\begin{equation}
    r_k = \frac{1}{r}
\end{equation}
Inputting these into equation \ref{eq:star_complete_difference_simplified} gives 
\begin{equation*}
    \rho_{\text{star}} - \rho_{\text{complete}} = \frac{ (\frac{r}{ r+  4\delta } - 1) + \frac{r}{ r+  4\delta } \frac{1}{r-1} - \frac{1}{r-1}}{1 +  2\frac{1}{r-1} +  ( \frac{1}{r-1})^2}
\end{equation*}
which simplifies to
\begin{equation} \label{eq:final_difference_expression}
   \rho_{\text{star}} - \rho_{\text{complete}} = -\frac{4\delta(r-1)}{r(r+4\delta)}
\end{equation}
which holds for $\delta  \gg  \frac{1}{\sqrt{N}}$. Since $\rho_{\text{star}} - \rho_{\text{complete}} < 0 $ for all $\delta  \gg  \frac{1}{\sqrt{N}}$, the star is a suppressor. Therefore $\delta_c = \frac{1}{\sqrt{N}}$. 

\section{Calculating fixation probability numerically}
Gillespie algorithm is used to run the simulations following the method described in \cite{EGTMarkovContinuous}. 
\newline \newline 
To calculate fixation probability numerically, we note the total number of simulations run (reruns) $M_{\text{total}}$ and the number of those simulations that the mutant succeeded in, $M_\text{{mutant}}$. The fixation probability is then 
\begin{equation}
    \rho_{\text{numerical}} = \frac{M_\text{{mutant}}}{M_{\text{total}}}
\end{equation}
The more simulations are run, the closer the results gets to the analytical value. 

\section{Uncertainty in the simulation results seen in the Figures} \label{appendix:uncertainty_graphs}

The scatter points seen in most figures, ($M_{\text{total}}=10^4$ (\figurename\text{ }\ref{fig:contiuumBddB}, \figurename\text{ }\ref{fig:contiuumBddB_zoomzerotoone}, \figurename\text{ }\ref{fig:fixation_prob_difference_theory_sim}, \figurename\text{ }\ref{fig:fixation_prob_difference_theory_sim_error}, \figurename\text{ }\ref{fig:fixation_prob_difference_theory_sim_error_mean},\figurename\textbf{ }\ref{fig:contiuumBddB_zoomzerotoon_mean_error}) are the mean of five points of fixation probability calculated from 2000 simulations ($M_{\text{total}}=2 \times 10^3$). Hence the total number of simulations is $M_{\text{total}}=10^4$.  For \figurename\text{ }\ref{fig:discrete_star_complete_BddBupdate} $M_{\text{total}}=10^5$. This is is due to computational constraints. 
\newline \newline 
The error bars seen in \figurename\text{ }\ref{fig:contiuumBddB}, \figurename\text{ }\ref{fig:contiuumBddB_zoomzerotoone}, \figurename\text{ }\ref{fig:fixation_prob_difference_theory_sim_error} is the standard deviation of the five points used to estimate the mean, and is calculated by \cite{cumming2007error}
\begin{equation} \label{eq:standard_equation}
    s = \sqrt{\frac{1}{n}\sum_{i=1}^{n}(x_i - \bar{x})^2}
\end{equation}
where $x_i$ is the fixation probability calculated from 200 simulations (the measurement), $\bar{x}$ is the mean found from analytical equations (for star graph equation \ref{eq:star_fp_maintext} and for complete graph \ref{eq:complete_fp_maintext} found in section \ref{sec:continuous_time_model}), $n$ is the number of points used to estimate the mean (in this case 5).  
\newline \newline 
Using the standard deviation can calculate the standard error of the mean by \cite{cumming2007error}
\begin{equation} \label{eq:mean_error}
    s_n = \frac{s}{\sqrt{n}}
\end{equation}

