\subsection{Gaussian-Process Model Specifications}\label{sec::priors}

\subsubsection{Simulations}
Let units $i=1,\dots,N$ and times $t=1,\dots,T$.  Denote the latent process $f_{it}$ and observed outcome $Y_{it}$. We fit three different covariance kernels, each with both a Normal and a Poisson-count likelihood.

\bigskip
\noindent\textbf{GP prior:}
$$
\mathbf{f} \sim \mathcal{GP}\bigl(0,\;k\bigl((i,t),(i',t')\bigr)\bigr).
$$
\newline
\noindent\textbf{1. Nonseparable (Gneiting) kernel}
Define
$$
\psi(u) = \left(\frac{1}{l_t}\,u^\alpha + 1\right)^{\eta}, 
\quad
\phi(z) = \exp\left(-\frac{1}{t_s}\,z^\gamma\right),
$$
with variance $\tau^2>0$, length-scales $l_t,l_s>0$, smoothness $\alpha,\gamma\in(0,1]$, and space-time interaction $\eta\in[0,1]$.  Then
$$
k^{\mathrm{G}}\bigl((i,t),(i',t')\bigr)
= \tau^2\,
\psi\bigl(|t-t'|^2\bigr)\,
\phi\!\Bigl(\tfrac{\lVert s_i - s_{i'}\rVert^2}
                     {\psi\bigl(|t-t'|^2\bigr)}\Bigr).
$$


\noindent\textbf{2. Separable RBF-RBF kernel}
\[
k^{\mathrm{RBF-RBF}}\bigl((i,t),(i',t')\bigr)
= \tau^2\,
\exp\!\Bigl(-\tfrac{\lVert s_i - s_{i'}\rVert^2}{2l_s^2}\Bigr)\,
\exp\!\Bigl(-\tfrac{|t - t'|^2}{2l_t^2}\Bigr).
\]


\noindent\textbf{3. Separable ICM-RBF kernel}
Let \(\Phi\in\mathbb R^{N\times J}\) have rows \(\phi_i\).  Then
\[
k^{\mathrm{ICM-RBF}}\bigl((i,t),(i',t')\bigr)
= (\phi_i^{\!\top}\!\phi_{i'})\;
\exp\!\Bigl(-\tfrac{|t - t'|^2}{2l_t^2}\Bigr).
\]

\bigskip
\noindent\textbf{Outcome models:}
\[
\text{(a) Normal:}
\quad Y_{it}\mid f_{it}\;\sim\;\mathcal{N}\bigl(\mu_0 + f_{it},\,\sigma^2\bigr),
\qquad
\text{(b) Poisson:}
\quad Y_{it}\mid f_{it}\;\sim\;\mathrm{Poisson}\!\bigl(\exp(\mu_0 + f_{it})\bigr).
\]

\bigskip
\noindent\textbf{Priors (all models):}
$$
\tau^2,\;\sigma^2,\;l_t,\;l_s
\;\sim\;\mathrm{Inv\!-\!Gamma}(5,5),
\quad
\alpha,\;\gamma\;\sim\;\mathrm{Unif}(0,1),\\
\quad
\eta \sim \mathcal{N}(0.5,0.1)
\quad
\mu_0\;\sim\;\mathrm{Unif}\bigl(-\infty,\infty\bigr).
$$

\subsubsection{Application}
Let units $i=1,\dots,N$ and times $t=1,\dots,T$.  Denote the latent process $f_{it}$ and observed outcome $Y_{it}$. We fit three different covariance kernels on the Katrina mortality data with a Poisson-count likelihood. Here, we adjust the priors based on the county-distances and mortality counts of our data.

\bigskip
\noindent\textbf{GP prior:}
$$
\mathbf{f} \sim \mathcal{GP}\bigl(0,\;k\bigl((i,t),(i',t')\bigr)\bigr).
$$

\noindent\textbf{1. Nonseparable (Gneiting) kernel}
Define
$$
\psi(u) = \left(\frac{1}{l_t}\,u^\alpha + 1\right)^{\eta}, 
\quad
\phi(z) = \exp\left(-\frac{1}{t_s}\,z^\gamma\right),
$$
with variance $\tau^2>0$, length-scales $l_t,l_s>0$, smoothness $\alpha,\gamma\in(0,1]$, and space-time interaction $\eta\in[0,1]$.  Then
$$
k^{\mathrm{G}}\bigl((i,t),(i',t')\bigr)
= \tau^2\,
\psi\bigl(|t-t'|^2\bigr)\,
\phi\!\Bigl(\tfrac{\lVert s_i - s_{i'}\rVert^2}
                     {\psi\bigl(|t-t'|^2\bigr)}\Bigr).
$$


\noindent\textbf{2. Separable RBF-RBF kernel}
\[
k^{\mathrm{RBF-RBF}}\bigl((i,t),(i',t')\bigr)
= \tau^2\,
\exp\!\Bigl(-\tfrac{\lVert s_i - s_{i'}\rVert^2}{2l_s^2}\Bigr)\,
\exp\!\Bigl(-\tfrac{|t - t'|^2}{2l_t^2}\Bigr).
\]


\noindent\textbf{3. Separable ICM-RBF kernel}
Let \(\Phi\in\mathbb R^{N\times J}\) have rows \(\phi_i\).  Then
\[
k^{\mathrm{ICM-RBF}}\bigl((i,t),(i',t')\bigr)
= (\phi_i^{\!\top}\!\phi_{i'})\;
\exp\!\Bigl(-\tfrac{|t - t'|^2}{2l_t^2}\Bigr).
\]

\bigskip
\noindent\textbf{Outcome model:}

\[
\text{Poisson:}
\quad Y_{it}\mid f_{it}\;\sim\;\mathrm{Poisson}\!\bigl(\exp(\mu_0 + \delta_{i} + f_{it} +\mathrm{log}(\theta_{it}))\bigr).
\]

\bigskip
\noindent\textbf{Priors (Nonseparable):}
$$
\tau^2,\;\mu_0
\;\sim\;\mathcal{N}(0,1), 
\quad
\;l_t, \sim \mathcal{N}(10, 5), 
\quad
\;l_s \sim \mathcal{N}(300, 100),
\quad
\alpha,\;\gamma,\;\eta\sim\;\mathrm{Beta}(1,1),\\
\quad
\delta_i\;\sim\;\mathrm{Unif}\bigl(-\infty,\infty\bigr)
$$

\noindent\textbf{Priors (Separable RBF-RBF):}
$$
\tau^2 
\;\sim\;\mathcal{N}(0,1), 
\quad
\;l_t, \sim N(10, 5), 
\quad
\;l_s \sim N(300, 100),
\quad
\mu_0,\;\delta_i\;\sim\;\mathrm{Unif}\bigl(-\infty,\infty\bigr)
$$

\noindent\textbf{Priors (Separable ICM-RBF):}
$$
\tau^2 
\;\sim\;\mathrm{Inv\!-\!Gamma}(5,5), 
\quad
\;l_t, \sim N(10, 5), 
\quad
\;l_s \sim N(300, 100),
\quad
\mu_0,\;\sim\;\mathrm{Unif}\bigl(-\infty,\infty\bigr),
\quad
\delta_i\sim\mathcal{N}(0,1)
$$

