\author[Ramadas]{Rohini Ramadas}
\author[Silversmith]{Rob Silversmith}
\author[Vogtmann]{Karen Vogtmann}
\author[Winarski]{Rebecca R. Winarski}



\begin{document}
\begin{abstract}
    The moduli space of graphs $\M_{g,n}^{\trop}$ is a polyhedral object that mimics the behavior of the moduli spaces $\M_{g,n}$, $\Mbar_{g,n}$ of (stable) Riemann surfaces; this relationship has been made precise in several different ways, which collectively identify $\M_{g,n}^{\trop}$ as the ``tropicalization'' of $\M_{g,n}$. We describe how this relationship lifts to some objects that live over $\M_{g,n}$ (like Teichm\"uller space) and that live over $\M_{g,n}^{\trop}$ (like the Culler-Vogtmann space $\CV_{g,n}^*$). We introduce the notion of a stable complex handlebody, and show that $\CV_{g,n}^*$ can be viewed as the tropicalization of a certain complex manifold $\Mgnmh$ that parametrizes complex handlebodies. An important ingredient is our construction of a partial compactification $\Mbargnmh\supset\Mgnmh$, which we prove is a complex manifold with simple normal crossings boundary. When $n=0$, $\Mgnmh$ coincides with the moduli space of Schottky groups, $\Mbargnmh$ coincides with Gerritzen-Herrlich's extended Schottky space, and $\CV_{g,0}^*$ is the simplicial completion of the original Outer space. The resulting picture fits together many familiar objects from geometric group theory and surface topology, including Harvey?s curve complex, mapping class groups of surfaces and handlebodies, and augmented Teichm\"uller space. Many of the relationships between the objects that we see in this picture already exist in the literature, but we add some new ones, and generalize several existing relationships to include a number $n>0$ of punctures/leaves.
\end{abstract}

\maketitle

\section{Introduction}
    The purpose of this paper is to tell a story relating some well-studied objects in:
    \begin{itemize}
        \item Geometric group theory (automorphisms of free groups, Culler-Vogtmann spaces),
        \item Low-dimensional topology (surfaces and handlebodies, the structure of their loops and disks, and their associated mapping class groups),
        \item Complex geometry (Teichm\"uller space, Schottky space, and adjacent constructions),
        \item Algebraic geometry
        (Moduli spaces of stable curves), and
        \item Tropical/non-Archimedean geometry (Moduli spaces of tropical curves, and their non-Archimedean counterparts).
    \end{itemize}
    In the following sections, we outline the main characters in the story, and their relationships, which fit together to form the diagram in Figure \ref{fig:MainDiagram}. Many of the parts of this story already appear scattered in the literature around automorphisms of free groups, mapping class groups, handlebodies, Teichm\"uller space, Kleinian groups, and even phylogenetic trees. Our goal in this paper is to present what we hope is a  clean,  self-contained version of the story. Along the way, we will prove some new results, generalize some existing results, and give substantively new interpretations to some previously-studied objects. (See Section \ref{sec:IntroResults}.)

    \subsection{Boundary complexes and the meaning of ``tropicalization''}\label{sec:IntroTrop} Over the last decade or so, there has been a lot of research on tropical moduli spaces and the precise senses in which they are tropicalizations of algebraic moduli spaces. The classic example of this is $\M_{g,n}^{\trop}$, a generalized cone complex of dimension $3g-3+n$ parametrizing tropical curves/metric graphs. This is the tropicalization of the algebraic moduli space $\M_{g,n}$, a quasiprojective variety of (complex) dimension $3g-3+n$ parametrizing Riemann surfaces (i.e. smooth projective irreducible algebraic curves) of genus $g$ with $n$ labeled points, in the following senses:
        \begin{itemize}
        \item In the genus-zero case, $\M_{0,n}$ embeds as a closed subvariety of the algebraic torus $(\C^*)^{\binom{n}{2}-n}$, and Speyer-Sturmfels \cite{SpeyerSturmfels2004} used this fact to construct a tropicalization $\M_{0,n}^{\trop}$, a simplicial cone complex with a natural embedding in $\R^{\binom{n}{2}-n}$. As Speyer and Sturmfels noted, $\M_{0,n}^{\trop}$ is isomorphic to the space of phylogenetic trees studied in \cite{BilleraHolmesVogtmann2001}.
        \item Deligne and Mumford \cite{DeligneMumford1969} defined a normal crossings compactification $\Mbar_{g,n}$ of $\M_{g,n}$. As is standard in algebraic geometry, the complement $\Mbar_{g,n}\setminus\M_{g,n}$ is referred to as the \newword{boundary} of $\Mbar_{g,n}$ despite not being a topological boundary. The associated \newword{boundary complex} is a symmetric $\Delta$-complex\footnote{A $\Delta$-complex is a cell complex whose cells are homeomorphic to simplices.  A symmetric $\Delta$-complex is similar, but a ``cell" may be the quotient of a simplex by a finite group action.} that encodes the pattern of intersections of the strata of $\Mbar_{g,n}\setminus\M_{g,n}$. (See Section \ref{sec:BoundaryComplexes}.) The boundary complex is canonically identified with the \newword{link} $\Link(\M_{g,n}^{\trop})$, the moduli space of tropical curves with total edge length 1. (See e.g. \cite{Caporaso2012}.)
        \item Abramovich-Caporaso-Payne \cite{AbramovichCaporasoPayne2012} approached tropicalization via non-Archimedean geometry, using techniques of Thuillier on toroidal embeddings \cite{Thuillier2007} to show that the compactification $\Mbar_{g,n}$ of $\M_{g,n}$ determines a skeleton of the Berkovich analytification of $\M_{g,n}$, which is canonically identified with $\M_{g,n}^{\trop}$. (A complex variety of dimension $N$ has an associated Berkovich analytification, a topological space that can be obtained by taking an inverse limit of dimension-$N$ cone complexes, and a skeleton is a strong deformation retract of this topological space.) Cavalieri-Chan-Ulirsch-Wise \cite{CavalieriChanUlirschWise2020} later built the necessary tools for realizing this skeleton as a ``tropical moduli stack''.
        \item More recently, Chan-Galatius-Payne \cite{ChanGalatiusPayne2021} defined a surjective proper continuous map $\lambda_{g,n}:\M_{g,n}\to\M_{g,n}^{\trop}$, canonically defined up to homotopy, which induces an isomorphism from the compactly supported rational cohomology of $\M_{g,n}^{\trop}$ to the weight-zero compactly supported rational cohomology of $\M_{g,n}$.
    \end{itemize}
    Outer space and its variations, introduced in the following section, look a lot like tropical moduli spaces.  This was pointed out by Mikhalkin \cite[Sec. 3.1]{Mikhalkin2007}, and has been further explored and developed by several authors (\cite{ ChanMeloViviani2013,  PoineauTurchetti2020, ulirsch2021non}, summarized just below in Sections \ref{sec:IntroTeichmuller} and \ref{intro:Schottky}). In this paper, we use the above relationships between $\M_{g,n}$ and $\M_{g,n}^{\trop}$ as a ``wish list'' with which to explore the relationship between Outer space and tropical geometry. This requires leaving the realm of algebraic geometry --- it has generally been challenging to talk about tropicalization outside of algebraic geometry, but some of the above points have compelling analogues.

    \subsection{Outer space and its relationship to \texorpdfstring{$\M_{g,n}^{\trop}$}{Mgntrop}}\label{sec:IntroOuterSpace} In the early 1980s, M. Culler and the third author introduced  \newword{Outer space} $\CV_g$, a $(3g-3)$-dimensional contractible space on which the group $\Out(F_g)$ of outer automorphisms of a finitely-generated free group acts with finite stabilizers \cite{CullerVogtmann1986}. Outer space $\CV_g$ parametrizes metric graphs together with a \newword{marking} which identifies the fundamental group of the graph with $F_g$, and $\Out(F_g)$ acts by changing the marking. The space $\CV_g$
    decomposes into a disjoint union of open simplices, and can  be completed to a simplicial complex $\CV_g^*$, called the \newword{simplicial completion} of Outer space. The action of $\Out(F_g)$ on $\CV_g$ extends to a simplicial action on $\CV_g^*$. For $n\geq 1$, Hatcher introduced generalizations $\CV_{g,n}$ and $\CV_{g,n}^*$ of Outer space and its simplicial completion, which both have natural actions of $A_{g,n}:=\Aut(F_g)\rtimes F_g^{n-1}$. To unify later statements we set $\CV_g=\CV_{g,0}$ and $A_{g,0}=\Out(F_g)$. 




    The quotient $\CV_g/\Out(F_g)$ is the \newword{moduli space $\mathcal{MG}_g$ of metric graphs} of genus $g$ (i.e. connected with Betti number $g$) whose edge lengths sum to $1$. The quotient $\MG_{g,n}:=\CV_{g,n}/A_{g,n}$ is the moduli space of metric graphs whose edge lengths sum to 1, with $n$ labeled leaves. The quotients $\CV_g^{*}/\Out(F_g)$ and $\CV_{g,n}^*/A_{g,n}$ are naturally identified with $\Link(\M_{g}^{\trop})$ and $\Link(\M_{g,n}^{\trop})$ respectively. Under these identifications, $\mathcal{MG}_g$ and $\MG_{g,n}$ are realized as open subsets of $\Link(\M_{g}^{\trop})$ and $\Link(\M_{g,n}^{\trop})$ respectively.


    The above spaces have been used extensively to study the group $\Out(F_g)$ and its cohomology. We define them rigorously in Section \ref{sec:IntroOuterSpace}. In Appendix \ref{app:SimplicialCompletion} we give two alternate descriptions of $\CV_g^*$ and $\CV_{g,n}^*$.


    \begin{rem}
        $\Link(\M_{g,n}^{\trop})$ is a \emph{finite} cell complex. In contrast, $\CV_{g,n}^*$ is an \emph{infinite} simplicial complex. Therefore $\CV_{g,n}^*$ cannot be the boundary complex of a normal crossings compactification of an algebraic variety --- our first hint that we must leave the realm of algebraic geometry in order to interpret $\CV_{g,n}^*$ as a tropical moduli space.     \end{rem}

     \subsection{Teichm\"uller space \texorpdfstring{$\T(S_{g,n})$}{T(Sgn)}: its relationship to \texorpdfstring{$\M_{g,n}$}{Mgn}, and the tropical perspective}\label{sec:IntroTeichmuller}
     Fix an $n$-pointed genus-$g$ oriented surface $S_{g,n}$; its Teichm\"uller space $\T(S_{g,n})$ is a complex manifold parametrizing $n$-pointed genus-$g$ \emph{Riemann} surfaces together with a marking given by a homeomorphism from $S_{g,n}$ (See Section \ref{sec:ModuliTeichmuller}). The mapping class group  $\MCG(S_{g,n})$, i.e.  the group of isotopy classes of orientation-preserving homeomorphisms of $S_{g,n}$,  acts on $\T(S_{g,n})$ by changing the marking, and $\M_{g,n}$ is the quotient of $\T_{g,n}$ by this action.  
     Since the action has finite stabilizers, $\M_{g,n}$ is an orbifold, $\T_{g,n}$ is its orbifold universal cover, and $\MCG(S_{g,n})$ is the orbifold fundamental group of $\M_{g,n}.$  

    Outer space, with its action by $\Out(F_g),$ was originally introduced by Culler and Vogtmann as an analogue of Teichm\"uller space $\T_g$ with its action of $\MCG(\Sg)$. In particular, $\M_{g}$ parametrizes Riemann surfaces while $\T(S_{g})$ parametrizes Riemann surfaces with a topological marking; $\Link(\M_g^{\trop})$ parametrizes metric graphs while $\CV_{g}^*$ parametrizes metric graphs with a topological marking. Chan-Melo-Viviani \cite{ChanMeloViviani2013} developed this analogy further, constructing (under certain conditions) a ``tropical Siegel space'' $\mathbb{H}^{\trop}$ and a ``tropical period map'' from the cone over $\CV_g^*$ to $\mathbb{H}^{\trop}$. (Note: In \cite{ChanMeloViviani2013}, the cone over $\CV_g^*$ is referred to as ``tropical Teichm\"uller space'', which is at odds with the terminology introduced just below.)

     Bers introduced a partial compactification $\Tbar(S_{g,n})$ of $\T(S_{g,n})$, called augmented Teichm\"uller space \cite{Bers1974}. The action of $\MCG(S_{g,n})$ extends to $\Tbar(S_{g,n})$, and the quotient is naturally identified with $\Mbar_{g,n}$. The space $\Tbar(S_{g,n})$ is not a complex manifold, but the boundary $\Tbar(S_{g,n})\setminus\T(S_{g,n})$ has a natural stratification by locally closed subsets, each of which is a connected complex manifold. The boundary complex of $\Tbar(S_{g,n})$ (appropriately defined) is the \newword{curve complex} $\mathcal{C}(S_{g,n})$, an infinite simplicial complex  indexing multicurves on $S_{g,n}$ (see Section \ref{sec:Complexes}). The quotient of the cone $\Cone(\mathcal{C}(S_{g,n}))$ over $\mathcal{C}(S_{g,n})$ by $\MCG(S_{g,n})$ can be identified with $\M_{g,n}^{\trop}$. For these reasons, the first author \cite[Sec. 3.4]{ramadas2024thurston} proposed $\Cone(\mathcal{C}(S_{g,n}))$ as an alternate candidate for ``tropical Teichm\"uller space'', suggesting that the relationship between $\mathcal{C}(S_{g,n})$ and $\T(S_{g,n})$ is more in line with properties of tropicalizations listed in Section \ref{sec:IntroTrop} than the relationship between $\CV_{g,n}^*$ and $\T(S_{g,n})$, and noting in support of this that the Chan-Galatius-Payne map $\lambda_{g,n}:\M_{g,n}\to\M_{g,n}^{\trop}$ naturally lifts to an $\MCG(S_{g,n})$-equivariant continuous map $\widetilde{\lambda}_{g,n}:\T(S_{g,n})\to\Cone(\mathcal{C}(S_{g,n}))$. (See Section \ref{sec:CGP}.)


    \subsection{Schottky space and its relationship with \texorpdfstring{$\CV_g^*$}{CVg*}}\label{intro:Schottky}
    Despite the \emph{analogy} discussed above between $\T(S_g)$ and $\CV_g$, the \emph{relationship} between $\T(S_g)$ and $\CV_g$ does not fit into any of the frameworks of ``tropicalization'' listed in Section \ref{sec:IntroTrop}. However, there is a space, called (marked) Schottky space $\Sch_g$, which lives in between $\T(S_{g})$ and $\M_{g}$, for which $\CV_g^*$ does act in some sense as a tropicalization. $\Sch_g$ is a complex manifold that parametrizes Schottky groups (a special class of free subgroups of $\PSL_2(\C)$) together with a choice of free generators. It can be obtained as the quotient of $\T(\Sg)$ by a certain infinite-index subgroup of $\MCG(S_g)$; it admits an infinite-degree covering map from $\T(\Sg)$ and an infinite-degree covering map to $\M_g$. $\Sch_g$ is known to be related to $\CV_{g}^{*}$ in two ways:
    \begin{enumerate}
        \item \textbf{Via a partial compactification.} There is a partial compactification $\Sch_g\subseteq\bar{\Sch}_g$ whose boundary complex is $\CV_g^*$. The space $\bar{\Sch}_g$, a   complex manifold (but not an algebraic variety), was constructed by Gerritzen and Herrlich \cite{GerritzenHerrlich1988} and is called \newword{extended Schottky space}. This is the avenue that we explore further in this article.
        \item \textbf{Via non-Archimedean geometry.} Gerritzen and Herrlich \cite{Gerritzen1983, Herrlich2006} also constructed a non-Archimedean analog $\Sch_g^{\na}$ of Schottky space and noted that $\Sch_g^{\na}$ admits a natural ``tropicalization'' map to the cone over $\CV_g$. Ulirsch introduced a variant/enlargement  $\Sch_g^{\na,*}$ of $\Sch_g^{\na}$ and showed that it contains the cone over $\CV_g^*$ as a skeleton (strong deformation retract) \cite{ulirsch2021non}. $\Sch_g^{\na, *}$ parametrizes genus-$g$ \textit{non-Archimedean curves} together with a topological marking by a genus-$g$ graph, and therefore Ulirsch refers to $\Sch_g^{\na, *}$ as ``non-Archimedean Teichm\"uller space'', continuing the analogy of Chan-Melo-Viviani. However, Ulirsch also mentions the connection to Schottky space, speculating that there must be meaningful sense in which $\Sch_g^{\na}$ is related to the classical Schottky space $\Sch_g$. A precise connection between $\Sch_g^{\na}$ and $\Sch_g$ was established by Poineau-Turchetti \cite{PoineauTurchetti2020}, who constructed a ``universal" analytic Schottky space $\Sch_g^{\an,\univ}$, defined over the integers, of which both the non-Archimedean $\Sch_g^{\na}$ and the classical $\Sch_g$ can be realized as specializations\footnote{More precisely, there is a topological space $M(\Z)$ (with additional structure) that parametrizes multiplicative seminorms on the ring $\Z$ that are bounded from above by the standard Archimedean norm on $\Z$. The universal Schottky space $\Sch_g^{\an,\univ}$ admits a map $\pi$ to $M(\Z)$; this can be thought of as a ``universal family" of Schottky spaces. The inclusion $\Z\into \C$ can be realized in multiple ways as an inclusion of normed rings; two of these in particular are obtained by (1) the Archimedean norm on both rings and (2) the trivial norm on both rings. Each of these inclusions of normed rings induces a map from a one-point space into $M(\Z)$. One can pull back the universal family $\pi:\Sch_g^{\an,\univ}\to M(\Z)$ along both of these maps; along (1) we obtain the classical Schottky space $\Sch_g$, while along (2) we obtain the non-Archimedean Schottky space $\Sch_g^{\na}$. This can be recast slightly more concretely as follows: the construction in \cite{PoineauTurchetti2020} can be used to construct a bundle of Schottky spaces over an open disk, most fibers of which are isomorphic to classical Schottky space, but whose fiber over the origin is isomorphic to non-Archimedean Schottky space. In this sense we can think of classical Schottky space as ``degenerating" to non-Archimedean Schottky space. The construction in \cite{PoineauTurchetti2020} was used by Dang and Mehmeti  \cite{DangMehmeti2024} to relate the dynamics of non-Archimedean Schottky groups to those of classical Schottky groups.}.
 \end{enumerate}
It is well-known that a Schottky group determines a hyperbolic \emph{handlebody}, and that therefore $\Sch_g$ can be thought of as a space of handlebodies --- see just below.


    \subsection{Main results}\label{sec:IntroResults}
    In this paper, we aim to explore and connect the above points, to reframe them slightly, and to generalize them to allow labeled points (i.e. the case $n>0$). Schematically, from Sections \ref{sec:IntroTrop} and \ref{sec:IntroTeichmuller} we have a diagram:
    \begin{align}\label{eq:OriginalTropicalizationDiagram}
\begin{tikzcd}[ampersand replacement=\&]
    \boxed{\T(\Sgn)\subset\Tbar(\Sgn)}\arrow[d,"\MCG(\Sgn)",swap]\arrow[rr,bend left=5,rightsquigarrow,"\trop"]\&\&\mathcal{C}(\Sgn)\arrow[d,"\MCG(\Sgn)"]\\
    \boxed{\M_{g,n}\subset\Mbar_{g,n}}\arrow[rr,bend left=5,rightsquigarrow,"\trop"]\&\&\Link\M_{g,n}^{\trop}
\end{tikzcd}
\end{align}
    We fit this diagram into the larger diagram shown in Figure \ref{fig:MainDiagram}, whose pieces we now explain. A genus-$g$ \newword{handlebody} is an oriented 3-manifold with boundary that is obtained by gluing $2g$ disks on the boundary of a 3-ball to each other in pairs (via orientation-reversing homeomorphisms). Let $\Xgn$ be an $n$-pointed genus-$g$ handlebody, that is, a genus-$g$ handlebody together with $n$ distinct labeled points on its boundary. The boundary $S_{g,n}:=\partial\Xgn$ of $\Xgn$ is an oriented $n$-pointed genus-$g$ surface. 

    Associated to $\Xgn$ there is an infinite simplicial complex $\mathcal{D}(\Xgn)$ called the \emph{disk complex}, which lives naturally as a sub-complex of the curve complex $\mathcal{C}(S_{g,n})$. The mapping class group $\MCG(\Xgn)$ acts on $\mathcal{D}(\Xgn)$, and we are especially interested in the restriction of this action to the twist subgroup $\Tw(\Xgn)\subseteq\MCG(\Xgn)$, which is generated by Dehn twists around simple disks   (see Sections \ref{sec:HandlebodiesBackground} and \ref{sec:MappingClassGroups}).
    By a classical result of Luft \cite{Luft1978}, when $n=0$ there is an exact sequence of groups, with natural maps:
    \begin{equation}
        \begin{tikzcd}
            1\arrow[r]&\Tw(\Xg)\arrow[r]&\MCG(\Xg)\arrow[r]&\Out(\pi_1(\Xg))\arrow[r]&1.
        \end{tikzcd}
    \end{equation}
    Note that $\Out(\pi_1(\Xg))\cong\Out(F_g)$. Our first result is that this sequence (appropriately modified) remains exact for arbitrary $n$:

    \medskip

    \noindent\textbf{Theorem A.} (Theorem \ref{thm:LuftMarkedPoints})  \textit{There is a natural exact sequence:
        \begin{equation}
        \begin{tikzcd}[ampersand replacement = \&]
            1\arrow[r]\&\Tw(\Xgn)\arrow[r]\&\MCG(\Xgn)\arrow[r]\&A_{g,n}\arrow[r]\&1.
        \end{tikzcd}
    \end{equation}
    (Precisely, for the third map to be canonical we should choose an identification of $A_{g,n}$ with the homotopy mapping class group of $\Xgn$, see Section \ref{sec:MappingClassGroups}).}

    \medskip

    We next introduce the following spaces:
    \begin{itemize}
        \item $\T(\Xgn)$ is the Teichm\"uller space of $\Xgn$ (defined in Section \ref{sec:T(Vgn)}), a complex manifold of dimension $3g-3+n$. It parametrizes ``complex handlebodies'' with a topological marking, i.e. a homeomorphism from the reference handlebody $\Xgn$. $\T(\Xgn)$ is naturally isomorphic to $\T(S_{g,n})$. 
        \item $\Tbar(\Xgn)$ is the augmented Teichm\"uller space of $\Xgn$ (defined in Section \ref{sec:Tbar(Vgn)}), a partial compactification of $\T(\Xgn)$. It parametrizes \textit{stable} complex handlebodies with a topological marking, i.e. a sufficiently well-behaved \emph{surjection} from the reference handlebody $\Xgn$. $\Tbar(\Xgn)$ is \emph{not} isomorphic to $\Tbar(\Sgn)$, but rather is naturally isomorphic to an open subset of $\Tbar(\Sgn)$. Like $\Tbar(\Sgn)$, $\Tbar(\Xgn)$ is not a complex manifold, but the boundary $\Tbar(\Xgn)\setminus\T(\Xgn)$ is stratified by locally closed subsets, each of which is a connected complex manifold. The boundary complex of $\Tbar(\Xgn)$ (appropriately defined) is $\mathcal{D}(\Xgn)$. 
           \item   $\Mgnmh$ is the space of $n$-pointed genus-$g$ complex handlebodies marked by a \emph{homotopy equivalence} from $\Xgn$ (defined in Section \ref{sec:Mgmhbar}). It is a complex manifold of dimension $3g-3+n$, which is isomorphic to (marked) Schottky space $\Sch_g$ when $n=0$. Here ``$h\mathcal{T}$'' is short for ``homotopy Teichm\"uller space''.
        \item $\Mbargnmh$  is the space of $n$-pointed genus-$g$ stable complex handlebodies marked by a homotopy equivalence from $\Xgn$ (defined in Section \ref{sec:Mgmhbar}). This is a partial compactification of $\Mgnmh$. It is isomorphic to extended Schottky space $\bar{\Sch}_g$ when $n=0$ \cite{GerritzenHerrlich1988,Herrlich2006}.
             \item  $\Mgnh$ is the moduli space of (unmarked) $n$-pointed genus-$g$ complex handlebodies (defined in Section \ref{sec:Mghbar}). It is a complex orbifold  of dimension $3g-3+n$. In the case $n=0$, we have a natural isomorphism $\M(V_{g,0})\cong\Sch_g/\Out(F_g)$. (The latter quotient is called ``unmarked Schottky space''.) Here ``$\mathcal{MH}$'' is short for ``moduli space of handlebodies.''
        \item $\Mbargnh$ is the moduli space of (unmarked) $n$-pointed genus-$g$ stable complex handlebodies (defined in Section \ref{sec:Mghbar}), a partial compactification of $\Mgnh$. In the case $n=0$, there is a natural isomorphism $\Mbar(V_{g,0})\cong\overline{\Sch}_g/\Out(F_g)$ \cite{GerritzenHerrlich1988,Herrlich2006}.

    \end{itemize}
