    \begin{rem}\label{rem:GenusZero}
    In the case that $g=0$, the three groups $\MCG(S_{0,n})$, $\MCG(\X_{0,n})$, and $\Tw(\X_{0,n})$ all coincide, as do the three spaces $\M_{0,n}$, $h\T(V_{0,n})$ and $\mathcal{MH}_{0,n}$, and the three spaces $\Mbar_{0,n}$, $\overline{h\T}(V_{0,n})$ and $\overline{\mathcal{MH}}_{0,n}$.
\end{rem}
    Our results are summarized below, and depicted schematically in Figure \ref{fig:MainDiagram}:

    %Among the spaces and arrows in Figure \ref{fig:MainDiagram}, several of them correspond to nontrivial new results:

    \medskip

    \noindent\textbf{Theorem B (Complex structures).}
    \begin{enumerate}
        \item (Theorem \ref{thm:MarkedHandlebodiesComplexManifold}) \textit{$\Mbargnmh$ has the natural structure of a complex manifold of dimension $3g-3+n$, with respect to which the boundary $\Mbargnmh\setminus\Mgnmh$ is a countable union of complex submanifolds meeting at simple normal crossings.}
        \item (Theorem \ref{thm:UnmarkedHandlebodiesComplexOrbifold}) \textit{$\Mbargnh$ has the natural structure of a complex orbifold of dimension $3g-3+n$, with respect to which the boundary $\Mbargnh\setminus\Mgnh$ is a countable union of complex suborbifolds meeting at normal crossings.}
        \item (Theorems \ref{thm:MarkedHandlebodiesComplexManifold}(\ref{it:MgmhMghCovering},\ref{it:OutFgActionBiholomorphisms}), and \ref{thm:UnmarkedHandlebodiesComplexOrbifold}\eqref{it:MghMgEtale}) \textit{All maps in Figure \ref{fig:MainDiagram} between complex manifolds/orbifolds are holomorphic and \'etale, and all group actions on complex manifolds/orbifolds in Figure \ref{fig:MainDiagram} are actions by biholomorphisms.}
    \end{enumerate}
    \begin{rem}
        When $n=0$, Theorem B is \cite[Prop. 9]{GerritzenHerrlich1988}.
    \end{rem}
    We caution that $\Tbar(\Xgn)$ does not have a complex structure at the boundary, so its maps to $\Mbargnmh$, $\Mbargnh$ and $\Mbar_{g,n}$ are not holomorphic at the boundary. The map from $\Mbargnmh$ to $\Mbargnh$ is an orbifold covering map. The maps from $\Mbargnmh$ to $\Mbar_{g,n}$ and from $\Mbargnh$ to $\Mbar_{g,n}$ are local biholomorphisms (in the orbifold sense), but are not orbifold covering maps over the boundary of $\Mbar_{g,n}$. (The reader should have in mind the exponential map $\C\to\C$, which is a local biholomorphism but cannot be extended to a covering map.)

    \medskip

    \noindent\textbf{Proposition C.}
    \begin{enumerate}
        \item (Proposition \ref{prop:UnmarkedBijection}) \textit{The (holomorphic) map $\T(\Xgn)\to\Mgnh$ and the (continuous) map $\Tbar(\Xgn)\to\Mbargnh$ are canonically identified with the quotient maps by the mapping class group $\MCG(\Xgn)$.}
        \item (Proposition \ref{prop:MarkedBijection}) \textit{The (holomorphic) map $\T(\Xgn)\to\Mgnmh$ and the (continuous) map $\Tbar(\Xgn)\to\Mbargnmh$ are canonically identified with the quotient maps by the twist subgroup $\Tw(\Xgn)$.}
    \end{enumerate}

    \medskip

    \noindent\textbf{Theorem D.} (Theorem \ref{thm:QuotientOfDiskComplex}) \textit{The quotient $\mathcal{D}(\Xgn)/\Tw(\Xgn)$ is canonically identified with $\CV_{g,n}^*$.}

    \medskip

    \noindent\textbf{Corollary E.}
    \begin{enumerate}
        \item (Corollary \ref{cor:BoundaryMghLinkMgTrop}) \textit{The boundary complex of $\Mgnh\subseteq\Mbargnh$ is canonically identified with $\Link(\M_{g,n}^{\trop})$.}
        \item (Corollary \ref{cor:MgmhBoundaryComplexCV}) \textit{The boundary complex of $\Mgnmh\subseteq\Mbargnmh$ is canonically identified with $\CV_{g,n}^*$.}
    \end{enumerate}

    \begin{rem}
        Surprisingly, the map $\Mbargnh\to\Mbar_{g,n}$ induces an isomorphism on boundary complexes, even though it is infinite-to-1.
    \end{rem}

    \medskip

    In analogy with the Chan-Galatius-Payne map $\tilde\lambda_{\Sgn}:\T(\Sgn)\to\Cone(\mathcal{C}(\Sgn))$ (see Section \ref{sec:IntroTeichmuller}), we have:

    \medskip

    \noindent\textbf{Theorem F.} (Proposition \ref{prop:CGPAnalogy}) \textit{There is a continuous $\MCG(\Xgn)$-equivariant surjection $$\tilde\lambda_{\Xgn}:\T(\Xgn)\to\Cone(\mathcal{D}(\Xgn))$$ which descends to an $A_{g,n}$-equivariant continuous surjection $$\lambda_{g,n}^{h\mathcal{T}}:\Mgnmh\to\Cone(\CV_{g,n}^*).$$ In turn, $\lambda_{g,n}^{h\mathcal{T}}$ descends to a continuous surjection $$\lambda_{g,n}^{\mathcal{MH}}:\Mgnh\to\M_{g,n}^{\trop}.$$}

    \medskip

    By work of Hatcher \cite{Hatcher1995}, $\CV_{g,n}^*$ also has an interpretation in terms of the sphere complex $\Sph(W_{g,n})$ of a closed 3-manifold $W_{g,n}$ called a \emph{doubled handlebody}, see Appendix \ref{app:SimplicialCompletion}. There is a natural ``doubling map'' from the disk complex $\D(\Xgn)$ to the sphere complex $\Sph(W_{g,n})$. As a consequence of Theorem D and some results from 3-manifold theory, we have:

    \medskip

    \noindent\textbf{Proposition G.} (Proposition \ref{prop:DiskComplexSphereComplex}) \textit{The doubling map $\D(\Xgn)\to\Sph(W_{g,n})$ is precisely the quotient by the twist subgroup $\Tw(\Xgn)$.}

    \medskip

    \subsection{Revisiting the term ``tropicalization"}\label{sec:Revisit} In Figure \ref{fig:MainDiagram}, we have five squiggly arrows labeled by ``trop". Each of these five arrows admits the interpretation ``boundary complex of (partial) compactification". However, working from the bottom to the top of the diagram, the use of the term ``tropicalization" fits into three decreasing levels of niceness:
\begin{enumerate}
    \item Nicest: $(\M_{g,n}\subset\Mbar_{g,n})\leadsto \Link\M_{g,n}^{\trop}$. 
    \begin{enumerate}
        \item $\M_{g,n}$ and $\Mbar_{g,n}$ are both \emph{algebraic stacks} as well as complex orbifolds.
        \item Since $\M_{g,n}$ is algebraic and is not compact, there are holomorphic maps from punctured disks to $\M_{g,n}$ that do not extend across the puncture.
        \item $\Mbar_{g,n}$ is algebraic and compact, and its algebraic/complex structure extends that of the open subset $\M_{g,n}$. Therefore, every holomorphic map from a punctured disk to $\M_{g,n}$ extends across the puncture to a map to $\Mbar_{g,n}$.
        \item $\M_{g,n}$, being algebraic, has an associated non-Archimedean space, its Berkovich analytification $\M_{g,n}^{\na}$. Roughly speaking, a point of $\M_{g,n}^{\na}$ represents an ``infinitesimal one-parameter family" of points in $\M_{g,n}$\footnote{More precisely, a point of $\M_{g,n}^{\na}$ represents a field extension $K$ of $\C$ with a non-Archimedean valuation, together with a morphism of $\C$-schemes from $\Spec(K)$ to $\M_{g,n}$.}. In particular, a holomorphic map from a punctured disk to $\M_{g,n}$ determines a point of $\M_{g,n}^{\na}$\footnote{Not all points arise this way.}. $\M_{g,n}^{\trop}$ lives inside $\M_{g,n}^{\na}$ as a skeleton, i.e. strong deformation retract. This means that a holomorphic map $\alpha$ from a punctured disk to $\M_{g,n}$ determines a point $\alpha^{\trop}$ of $\M_{g,n}^{\trop}$\footnote{Again, not all points arise this way, but the points with integer cone coordinates do arise this way.}. The cone of $\M_{g,n}^{\trop}$ that $\alpha^{\trop}$ lies in corresponds to the boundary stratum of $\Mbar_{g,n}$ to which $\alpha$ sends the puncture.  
        \item There is the Chan-Galatius-Payne map $\lambda_{g,n}:\M_{g,n}\to\M_{g,n}^{\trop}$.
    \end{enumerate}

    \item Less nice, still pretty good: $(\Mgnh\subset\Mbargnh)\leadsto \Link\M_{g,n}^{\trop}$ and $(\Mgnmh\subset\Mbargnmh)\leadsto \CV_{g,n}^{*}$.
    \begin{enumerate}
        \item $\Mgnmh$ and $\Mbargnmh$ are complex manifolds, and $\Mgnh$ and $\Mbargnh$ are complex orbifolds. None of the four spaces is algebraic.
        \item $\Mgnmh$ and $\Mgnh$ are not compact. Since they are nonalgebraic, it is not immediate that there exist holomorphic maps from punctured disks to $\Mgnmh$ and $\Mgnh$ that do not extend across the puncture. However:
        \item The complex structures on $\Mbargnmh$ and $\Mbargnh$ extend those, respectively, on $\Mgnmh$ and $\Mgnh$. From this, we conclude that there do exist holomorphic maps from punctured disks to $\Mgnmh$ and $\Mgnh$ that do not extend across the puncture --- they extend instead to maps from the disk to $\Mbargnmh$ and $\Mbargnh$. 
        \item $\Mbargnmh$ and $\Mbargnh$ are also not compact. However, we \emph{speculate} that perhaps every holomorphic map from a punctured disk to $\Mgnmh$ (resp. $\Mgnh$) extends across the puncture to a map to $\Mbargnmh$ (resp. $\Mbargnh$).
        \item Given that $\Mgnmh$ and $\Mgnh$ are nonalgebraic, they do not admit Berkovich analytifications the way that $\M_{g,n}$ does (as far as we are aware). However, in the case $n=0$, $h\T(V_{g,0})$ does admit a non-Archimedean \emph{analogue} $h\T(V_{g,0})^{\na}:=\Sch_{g}^{\na,*}$ \cite{Gerritzen1983, Herrlich2006, ulirsch2021non}. By \cite{ulirsch2021non}, $\Cone(\CV_g^{*})$ does live inside $h\T(V_{g,0})^{\na}$ as a skeleton. By \cite{PoineauTurchetti2020} there is an explicit relationship between  $\Sch_g^{\na}$ (which is a subset of $\Sch_{g}^{\na,*}=h\T(V_{g,0})^{\na}$) and $h\T(V_{g,0})$, but this relationship is not ``is the Berkovich analytification of". As such, we are not aware of any interpretation of the form ``points of $h\T(V_{g,0})^{\na}$ correspond to one-parameter degenerations in $\Mgnmh$", but we would not be surprised if such an interpretation could be made meaningful/precise. In particular, it is quite possible that implicit in the combination of \cite{ulirsch2021non} and \cite{PoineauTurchetti2020} is a meaningful recipe for going from a holomorphic map from a punctured disk to $h\T(V_{g,0})$ to a point of $\Cone(\CV_g^{*})$\footnote{We also wonder whether there is a universal enlargement $\Sch_g^{\an,\univ,*}$ of $\Sch_g^{\an,\univ}$ over $M(\Z)$ whose Archimedean fiber is unchanged but whose non-Archimedean fiber over the trivial norm is $\Sch_{g}^{\na,*}$, rather than $\Sch_{g}^{\na}$.}. If our speculation that every holomorphic map from a punctured disk to $\Mgnmh$ extends across the puncture to a map to $\Mbargnmh$ is true, then one could define such a recipe directly, without going via non-Archimedean geometry, including when $n>0$.

        Ulirsch \cite{ulirsch2021non} points out a way to add labeled points to the construction of $\Sch_g^{\na,*}$. However we are not certain whether the resulting space bears the correct relationship to $\Mgnmh$ in the above senses, e.g. it is not clear whether it contains $\CV_{g,n}^*$ as a skeleton. Nor has the construction in \cite{PoineauTurchetti2020} been carried out when labeled points are allowed. However, we would not be surprised if there is a well-behaved version of the story in this generality. 
        \item There are Chan-Galatius-Payne-style maps $\lambda_{g,n}^{h\mathcal{T}}:\Mgnmh\to \Cone(\CV_{g,n}^{*})$ and $\lambda_{g,n}^{\mathcal{MH}}:\Mgnh\to \M_{g,n}^{\trop}$.
    \end{enumerate}

    \item Least satisfying: $(\T(\Xgn)\subset\Tbar(\Xgn))\leadsto \mathcal{D}(\Xgn)$ and $(\T(S_{g,n})\subset\Tbar(S_{g,n}))\leadsto \mathcal{C}(S_{g,n})$. 

    \begin{enumerate}
        \item $\T(\Xgn)$ and $\T(S_{g,n})$ are complex manifolds. Neither $\Tbar(\Xgn)$ nor $\Tbar(S_{g,n})$ admits a globally defined complex structure, but both are stratified by locally closed subsets, each of which is a complex manifold. None of the four spaces is algebraic.
        \item $\T(\Xgn)$ and $\T(\Sgn)$ are not compact. However, every holomorphic map from a punctured disk to $\T(\Xgn)$ or $\T(\Sgn)$ extends across the puncture. (To see this, recall that $\T(\Xgn)$ and $\T(S_{g,n})$ are both biholomorphic to the unit ball, and that a bounded holomorphic function on a punctured disk extends across the puncture.)
        \item The complex structures on $\T(\Xgn)$ and $\T(S_{g,n})$ do not extend to complex structures on $\Tbar(\Xgn)$ and $\Tbar(S_{g,n})$ respectively. Indeed, if they did, then there would necessarily exist a holomorphic map from a punctured disk to $\T(\Xgn)$ or $\T(S_{g,n})$ that did not extend across the puncture.
        \item $\Tbar(\Xgn)$ and $\Tbar(S_{g,n})$ are also not compact.
        \item Given that $\T(S_{g,n})$ and $\T(\Xgn)$ are non-algebraic, they do not admit Berkovich analytifications. Nor are there non-Archimedean counterparts known to us -- the spaces that have been termed ``tropical Teichm\"uller spaces" in the literature have precise relationships to Schottky rather than to Teichm\"uller spaces. Given that every holomorphic map from a punctured disk to $\T(\Xgn)$ or to $\T(S_{g,n})$ extends across the puncture, from the perspective of one-parameter complex degenerations, we would expect the tropicalizations of both $\T(\Xgn)$ and of $\T(S_{g,n})$ to be one-point sets. 
        \item There are Chan-Galatius-Payne-style maps $\tilde\lambda_{g,n}:\T(S_{g,n})\to\Cone(\mathcal{C}(S_{g,n}))$ and $\tilde\lambda_{\Xgn}:\T(\Xgn)\to\Cone(\mathcal{D}(\Xgn))$. 

    \end{enumerate}
\end{enumerate}

\begin{question}
    What is the topology of $\Mbargnmh$? Is it simply-connected? Contractible?
\end{question}

\begin{question}
    In the setting $n>0,$ is there a useful Schottky-group-like interpretation for $\Mgnh$, perhaps parametrizing Schottky groups together with $n$ distinct marked orbits on $\P^1\setminus(\text{limit set}).$
\end{question}





