\subsubsection{The moduli space of stable curves}\label{sec:StableCurves} Deligne and Mumford showed that the \newword{moduli space $\Mbar_{g,n}$ of stable $n$-pointed genus-$g$ curves} is a smooth irreducible Deligne-Mumford stack. In particular it is a complex orbifold that contains $\M_{g,n}$ as a dense open suborbifold. The boundary $\Mbar_{g,n}\setminus\M_{g,n}$ has a stratification by closed suborbifolds indexed by stable $n$-leafed genus-$g$ weighted graphs, i.e. for any such graph $\tau,$ we have a ``locally closed \newword{boundary stratum}'' 
$$\M_\tau=\{(C,x_1,\ldots,x_n)\in\Mbar_{g,n}:(C,x_1,\ldots,x_n)\text{ has dual graph }\tau\}.$$ 
The stratum $\M_\tau$ has a recursive structure, given by a natural isomorphism 
$$\M_\tau\cong\left(\prod_{\substack{\text{$v$ internal vertex of}\\ \tau_{(C,x_1,\ldots,x_n)}}}\M_{g_v,n_v}\right)\bigg/\Aut(\tau_{(C,x_1,\ldots,x_n)}),$$ 
where $g_v$ is the geometric genus of the irreducible component $v$, and $n_v$ is the number of special points on $v$. The closure $\Mbar_\tau$ of $\M_\tau$ in $\Mbar_{g,n}$ is characterized by 
$$\Mbar_\tau=\bigsqcup_{\tau'}\M_{\tau'},$$
 where $\tau'$ runs over all stable $n$-leafed genus-$g$ weighted graphs such that $\tau$ can be obtained from $\tau'$ by internal edge contractions. We refer to $\Mbar_\tau$ as a ``closed boundary stratum''. The isomorphism above extends to give $$\Mbar_\tau\cong\left(\prod_{\substack{\text{$v$ a vertex of}\\ \tau_{(C,x_1,\ldots,x_n)}}}\Mbar_{g_v,n_v}\right)\bigg/\Aut(\tau_{(C,x_1,\ldots,x_n)}),$$ so in particular each closed boundary stratum is a closed suborbifold of $\Mbar_{g,n}.$



\subsubsection{Augmented Teichm\"uller space} \label{sec:AugmentedTeichmullerSpace} Bers \cite{Bers1974} introduced a partial compactification of $\T(\Sgn)$, as follows. The \newword{augmented Teichm\"uller space} $$\Tbar(\Sgn)=\{(C,\phi)\}/\sim$$ of $\Sgn$ is the set of pairs $(C,\phi)$ where $C=(C,p_1,\ldots,p_n)$ is an $n$-pointed genus-$g$ stable curve, and $\phi:\Sgn\to C$ is a surjective $n$-pointed map satisfying:
\begin{itemize}
    \item $\phi$ is a homeomorphism on the complement of some multicurve $\Gamma$ in $\Sgn$, and
    \item $\phi$ contracts each component of $\Gamma$ to a node of $C$,
\end{itemize}
modulo the same equivalence relation as for $\T(\Sgn)$. $\Tbar(S_{g,n})$ is contractible, see \cite{Wolpert2009} --- this follows from the fact that $\Tbar(S_{g,n})$ has a $CAT(0)$ metric. The action of $\MCG(\Sgn)$ on $\T(\Sgn)$ extends to $\Tbar(\Sgn)$. However, unlike $\T(\Sgn)$, $\Tbar(\Sgn)$ is not a complex manifold, as shown in the following example:
\begin{ex}[{{See e.g. \cite[Ex. 2.3]{HubbardKoch2014}}}]\label{ex:V111}
    For a 1-pointed genus-1 surface $S_{1,1}$, the augmented Teichm\"uller space $\Tbar(S_{1,1})$ is homeomorphic to $\mathbb{H}\cup\Q\cup\{\infty\}$, where $\mathbb{H}$ is the (open) upper half-plane in $\C$. (Under this identification, $\T(S_{1,1})$ is identified with $\mathbb{H}$, which is indeed a complex manifold.) As in Example \ref{ex:V110}, we have $\MCG(S_{1,1})\cong\SL_2(\Z)$, which acts on $\mathbb{H}\cup\Q\cup\{\infty\}$ via the usual (right) action: $$z\cdot\begin{pmatrix}
        a&b\\
        c&d
    \end{pmatrix}=\frac{az+c}{bz+d}.$$
    Note that the action is not quite free; it has a kernel of order two. Note also that the points of $\Q\cup\{\infty\}$ have infinite stabilizers. For example, the stabilizer of $\infty$ consists of all elements of $\SL_2(\Z)$ with $b=0.$
\end{ex}
\medskip

Although $\Tbar(S_{g,n})$ is not a complex manifold (as we see in the above example), it has the structure of a countable disjoint union of complex manifolds, with a recursive stratification analogous to that of $\Mbar_{g,n}$ just above, as follows. Any element $(C,\phi)\in\Tbar(\Sgn)$ has an associated (possibly empty, contracted) multicurve $\Gamma$. Consider the locally closed \newword{boundary stratum} $$\T_\Gamma(\Sgn)=\{(C,\phi)\in\Tbar(\Sgn):(C,\phi)\text{ has associated multicurve }\Gamma\}.$$ We have an isomorphism
\begin{align}\label{eq:TSBoundaryRecursion}
    \T_\Gamma(\Sgn)\cong\prod_{\text{$v$ a vertex of $\tau_\Gamma$}}\T(\Sgn\langle v\rangle),
\end{align} where for each connected component $v$ of $\Sgn\setminus\Gamma$, $\Sgn\langle v\rangle$ is the pointed surface contracting each boundary component of (the closure in $\Sgn$ of) $v$ to a point, and labeling that point. In particular, $\T_\Gamma(\Sgn)$ has the natural structure of a complex manifold, of dimension $3g-3+n-\abs{\Gamma}$, where $\abs{\Gamma}$ is the number of simple closed curves in $\Gamma$.

A stratum $\T_{\Gamma'}(\Sgn)$ is contained in the closure of $\T_\Gamma(\Sgn)$ if and only if $\Gamma\subseteq\Gamma'.$ In particular, the closure $\Tbar_\Gamma(\Sgn)$ of $\T_\Gamma(\Sgn)$ in $\Tbar(\Sgn)$ can be characterized by:
$$\Tbar_\Gamma(\Sgn)=\bigsqcup_{\Gamma'\supseteq\Gamma}\T_{\Gamma'}(\Sgn).$$

We refer to $\Tbar_\Gamma(\Sgn)$ as a ``closed boundary stratum''. The recursive structure of $\T_\Gamma(\Sgn)$ extends: \begin{align}\label{eq:TbarSBoundaryRecursion}
    \Tbar_\Gamma(\Sgn)\cong\prod_{\text{$v$ a vertex of $\tau_\Gamma$}}\Tbar(\Sgn\langle v\rangle).
\end{align}

\begin{rem}\label{rem:HInverseMulticurve}
    The action of $\MCG(\Sgn)$ on $\T(\Sgn)$ extends naturally to $\Tbar(\Sgn)$. Note that if $(C,\phi)\in\Tbar(\Sgn)$ has contracted multicurve $\Gamma,$ then the multicurve contracted by $(C,\phi)\cdot h$ is $h^{-1}(\Gamma)$. 
\end{rem}
\begin{rem}
    Unlike the action of $\MCG(\Sgn)$ on $\T(\Sgn),$ the action of $\MCG(\Sgn)$ on $\Tbar(\Sgn)$ is not properly discontinuous. Indeed,  if $(C,\phi)\in\Tbar(\Sgn)\setminus \T(\Sgn)$ has contracted multicurve $\Gamma,$ then powers of the Dehn twist around any simple closed curve $\gamma\in\Gamma$ stabilize $(C,\phi),$ so the stabilizer of $(C,\phi)$ is infinite.
\end{rem}


We will need the following basic properties of this action.
\begin{lem}[{\cite[Prop. 2.5]{HubbardKoch2014}}]
    Let $\Gamma$ be a multicurve in $\Sgn$, and let $\Tw(\Gamma)\subseteq\MCG(\Sgn)$ be the subgroup generated by Dehn twists around simple closed curves in $\Gamma$, let $\MCG(\Sgn,\Gamma)\subseteq\MCG(\Sgn)$ denote the subgroup of mapping classes whose induced action on $\tau_\Gamma$ is trivial. (That is, $\MCG(\Sgn,\Gamma)$ consists of elements that preserve each curve in $\Gamma$ and that do not permute the components of $\Sg\setminus\Gamma$.) Then we have an exact sequence $$1\to \Tw(\Gamma)\to\MCG(\Sgn,\Gamma)\to\prod_{\text{$v$ internal vertex of $\tau_\Gamma$}}\MCG(\Sgn\langle v\rangle)\to1.$$
\end{lem}
\begin{lem}[Adapted from {\cite[Prop. 2.6]{HubbardKoch2014}}]\label{lem:StabilizerOfPointInTbarExactSequence}
    Let $\Gamma$ be a multicurve in $\Sgn$, and let $(C,\phi)\in\T_\Gamma(\Sgn).$ Let $\Stab(C,\phi)\subseteq\MCG(\Sgn)$ denote the stabilizer. Then we have an exact sequence $$1\to \Tw(\Gamma)\to\Stab(C,\phi)\to\Aut(C)\to1.$$
\end{lem}



As noted above, the action of $\MCG(\Sgn)$ on $\Tbar(\Sgn)$ is not properly discontinuous. However, the action is otherwise well-behaved in several ways:
\begin{itemize}
    \item The orbits are discrete.
    \item The action is compatible with the boundary stratification, in the sense that an element of $\MCG(\Sgn)$ sends each boundary stratum in $\Tbar(\Sgn)$ biholomorphically to a boundary stratum.
    \item Furthermore, the stabilizer of a stratum $\T_\Gamma(\Sgn)$ acts on $\T_\Gamma(\Sgn)$ with infinite kernel $\Tw(\Gamma)$, but the induced action of the quotient on $\Tbar_\Gamma(\Sgn)$ is properly discontinuous.
\end{itemize}
The above properties imply that the quotient $\Tbar(\Sgn)/\MCG(\Sgn)$ inherits a boundary stratification from $\Tbar(\Sgn)$, whose strata are locally closed connected subsets, indexed by the set of orbits of the $\MCG(\Sgn)$-action on the set of boundary strata of $\Tbar(\Sgn)$. Since each stratum of $\Tbar(\Sgn)$ has the structure of a complex manifold, the above properties imply that each boundary stratum in $\Tbar(\Sgn)/\MCG(\Sgn)$ inherits the structure of a complex orbifold.

This does not prove that $\Tbar(\Sgn)/\MCG(\Sgn)$ is itself a complex orbifold. However, this turns out to be the case --- it is a nontrivial theorem:
\begin{thm}[\cite{Harvey1974,Braungardt2001,HinichVaintrob2010,HubbardKoch2014}]\label{thm:MgnComplexOrbifold}
    $\Tbar(\Sgn)/\MCG(\Sgn)$ is naturally endowed with the structure of a complex orbifold, and this orbifold is canonically isomorphic to $\Mbar_{g,n}$. With respect to this structure,
    \begin{itemize}
        \item The restriction of the quotient map to each complex manifold $T_\Gamma(\Sgn)\subseteq\Tbar(\Sgn)$ is a holomorphic covering map over its image.
        \item The preimage of a locally closed (resp. closed) boundary stratum $\M_\tau\subseteq\Mbar_{g,n}$ (resp. $\Mbar_\tau$) under the quotient map is the union $\bigsqcup_{\Gamma}\T_\Gamma(\Sgn)$ (resp. $\bigsqcup_{\Gamma}\Tbar_\Gamma(\Sgn)$) where $\Gamma$ runs over all multicurves in $\Sgn$ with dual graph isomorphic to $\tau.$
    \end{itemize}
\end{thm}

\begin{ex}\label{ex:V111.5}
    Using the identifications in Examples \ref{ex:V110} and \ref{ex:V111}, the quotient $(\mathbb{H}\cup\Q\cup\{\infty\})/\SL_2(\Z)$ can be identified with $\Mbar_{1,1},$ by Theorem \ref{thm:MgnComplexOrbifold}. This special case is precisely the classical construction of the compactified modular curve, see e.g. \cite[Sec. 1.5]{Shimura1971}.
\end{ex}

\begin{rem}\label{rem:InheritedStratification}
    In Section \ref{sec:ComplexStructures}, we will consider certain pairs $(U,G),$ where $G\subseteq\MCG(\Sgn)$ is a subgroup, and $U\subseteq\Tbar(\Sgn)$ is a nonempty $G$-invariant open set that is a union of locally closed boundary strata. The same properties of the $\MCG(\Sgn)$-action above show that the quotient $U/G$ inherits a boundary stratification by locally closed connected strata, indexed by the $G$-orbits on the set of boundary strata of $\Tbar(\Sgn)$ that lie in $U$. Each stratum inherits the structure of a complex orbifold.
\end{rem}





\subsection{Simplicial complexes}\hfill\label{sec:Complexes}


\subsubsection{The curve complex} Associated to an $n$-pointed genus-$g$ surface $\Sgn$ is an infinite simplicial complex $\mathcal{C}(\Sgn)$ of dimension $3g-3+n$, called the \newword{curve complex}, whose vertices are isotopy classes of essential simple closed curves in $\Sgn$, and whose simplices are multicurves. In barycentric coordinates, a \emph{point} of $\mathcal{C}(\Sgn)$ can be interpreted as a multicurve $\Gamma$ in $\Sgn$, with positive real numbers that sum to 1 labeling the simple closed curves in $\Gamma$. Note that $\MCG(\Sgn)$ acts naturally on the right on $\mathcal{C}(\Sgn)$ by $\Gamma\cdot h=h^{-1}(\Gamma)$, see Remark \ref{rem:HInverseMulticurve}. This is an action by simplicial automorphisms.


\subsubsection{The disk complex}\label{sec:DiskComplex} Associated to an $n$-pointed genus $g$ handlebody $\Xgn$ is an infinite simplicial complex $\mathcal{D}(\Xgn)$ of dimension $3g-3+n$, called the \newword{disk complex}, whose vertices are $n$-pointed isotopy classes of essential disks, and whose simplices are multidisks. In barycentric coordinates, a \emph{point} of $\mathcal{D}(\Xgn)$ can be interpreted as a multidisk $\Delta$ in $\Xgn$, with positive real numbers that sum to 1 assigned to the disks in $\Delta$. The \newword{pure locus} is $\mathcal{D}^{\pure}(\Xgn)\subseteq\mathcal{D}(\Xgn)$ is the dense open set consisting of all simplices corresponding to pure multidisks $\Delta$ --- that is, multidisks $\Delta$ such that every component of $\Xg\setminus\Delta$ is simply connected. $\D^{\pure}(\Xgn)$ is not a subcomplex of $\D(\Xgn)$ --- rather it is the complement of a subcomplex.
\begin{prop}[\cite{McCullough1991,Giansiracusa2011}]\label{prop:SimpleDisksContractible}
    $\mathcal{D}(\Xgn)$ and $\mathcal{D}^{\pure}(\Xgn)$ are contractible.
\end{prop}

\begin{prop}\label{prop:DiskComplexInjectsIntoCurveComplex}
    The natural map $\mathcal{D}(\Xgn)\to\mathcal{C}(\partial\Xgn)$, which sends a multidisk to its boundary multicurve, is an embedding of simplicial complexes.
\end{prop}
\begin{proof}
    Since the map is clearly compatible with face inclusions, the statement is immediate from the fact that a simple closed curve in $\partial\Xgn$ bounds at most one disk in $\Xgn$ up to homotopy \cite[Lem. 2.3]{Hensel2020}.
\end{proof}
\begin{rem}
    The image of the above embedding is a full subcomplex of $\mathcal{C}(\partial\Xgn)$ --- this follows from the fact that two disjoint meridians can be made to bound disjoint disks, which follows from an innermost-circles argument.
\end{rem}

\begin{rem}
    $\MCG(\Xgn)$ acts naturally on the right on $\mathcal{D}(\Xgn)$ by $\Delta\cdot h=h^{-1}(\Delta)$, see Remark \ref{rem:HInverseMulticurve}. This is an action by simplicial automorphisms, and the embedding from Proposition \ref{prop:DiskComplexInjectsIntoCurveComplex} is equivariant with respect to the inclusion $\MCG(\Xgn)\into\MCG(\partial\Xgn)$ from Proposition \ref{prop:MCGInjection}. (In other words, if we view $\mathcal{D}(\Xgn)$ as a subset of $\mathcal{C}(\partial\Xgn)$ via Proposition \ref{prop:DiskComplexInjectsIntoCurveComplex}, then this subset is invariant under the $\MCG(\Xgn)$-action on $\mathcal{C}(\partial\Xgn)$.)
\end{rem}

\subsubsection{Outer Space}\label{sec:OuterSpaceBackground}
Outer space $\CV_g$ is the moduli space of marked stable metric graphs of genus $g$ without leaves whose edge lengths sum to one \cite{CullerVogtmann1986}. These graphs are not weighted, so  the word ``stable" amounts to saying that every vertex has valence at least three. Culler and Vogtmann proved that $\CV_g$ is contractible, and the group $\Out(F_n),$ realized as the group $\pi_0(HE(R_n))$ of homotopy classes of self-homotopy equivalences of the $n$-petaled rose $R_n$, acts with finite stabilizers.  This picture was extended by Hatcher \cite{Hatcher1995}  to include graphs with leaves.  Specifically, we define  $\CV_{g,n}$ to be the space of marked stable metric graphs of genus $g$ with $n$  labeled leaves, where a marking is an $n$-pointed homotopy equivalence from the $n$-thorned rose  $R_{g,n}$. Hatcher proved the space $\CV_{g,n}$ is contractible, and the group $A_{g,n}:=\pi_0(HE(R_{g,n}))$  acts on $\CV_{g,n}$ on the right by the formula $(\tau,r)\cdot\alpha=(\tau,r\circ\alpha)$ \cite{CullerVogtmann1986,Hatcher1995}. In particular, the stabilizer of a point is the group of automorphisms of the graph that preserve edge-lengths and leaves.

% up to isomorphism, where $(\tau_1,r_1)$ is isomorphic to $(\tau_2,r_2)$ if there is an $n$-pointed isometry $u:\tau_1\to \tau_2$ such that $u\circ r_1$ is $n$-pointed-homotopic to $r_2$. 



%There is a well-defined notion of \newword{edge contraction} for marked graphs. Let $(\tau,r)$ be a marked stable $n$-leafed genus-$g$ weightless graph $(\tau,r)$, and let $e$ be an internal edge of $\tau$ that is not a loop. Let $\tau'$ be the stable genus-$g$ weightless graph obtained by contracting $e$, and let $\contr_e:\tau\to\tau'$ be the contraction map, which is a homotopy equivalence. Then $(\tau',\contr_e\circ r)$ is the marked stable $n$-leafed genus-$g$ weightless graph obtained by contracting $e$.

$\CV_{g,n}$ is an infinite union of open simplices; the barycentric coordinates on each simplex correspond to all possible assignments of lengths that sum to 1 on the edges of a given marked graph $(\tau,r)$.  It is not a simplicial complex, since some faces are missing, but Culler-Vogtmann and Hatcher \cite{CullerVogtmann1986,Hatcher1995} observed that there is a simplicial complex $\CV_{g,n}^*$ of dimension $3g-3+n$ into which $\CV_{g,n}$ naturally embeds as the complement of a codimension-1 subcomplex \cite{Hatcher1995}. The simplicial complex $\CV_{g,n}^*$ is called the \newword{simplicial completion} of $\CV_{g,n}$. The action of $A_{g,n}$ on $\CV_{g,n}$ extends to a simplicial  action on $\CV^*_{g,n},$ but is no longer properly discontinuous since the stabilizer of any point in $\CV_{g,n}^*\setminus \CV_{g,n}$ is infinite.

For the purposes of this paper, our definition of the $\CV_{g,n}^*$ is the following. $\CV_{g,n}^*$ is the space of equivalence classes of marked stable graphs of genus $g$ with $n$ leaves, with edge lengths allowed to be zero. (Again, these graphs are not weighted.) The equivalence relation is generated by setting:
\begin{enumerate}
    \item $(\tau_1,r_1)$ is equivalent to $(\tau_2,r_2)$ if there is an $n$-pointed, edge-length-preserving isomorphism $\Phi:\tau_1\to\tau_2$ such that $\Phi\circ r_1$ is $n$-pointed homotopic to $r_2$, and
    \item $(\tau_1,r_1)$ is equivalent to $(\tau_2,r_2)$ if $(\tau_1,r_1)$ is obtained from $(\tau_2,r_2)$ by contracting a length-zero edge in $\tau_2$ which is not a loop. (The marking $r_1$ is the composition of $r_2:R_{g,n}\to\tau_2$ and the edge contraction map $\tau_2\to\tau_1$.)
\end{enumerate}
\begin{rem}
    The above characterization of $\CV_{g,n}^*$ does not appear explicitly in the literature as far as we know --- see Proposition \ref{prop:PointsOfSimplicialCompletion} in Appendix \ref{app:SimplicialCompletion}, where we also discuss Hatcher's original definition of $\CV_{g,n}^*$ in terms of spheres in a doubled handlebody.   
\end{rem}



\subsubsection{The moduli space of tropical curves}\label{sec:ModuliOfGraphs}




A \newword{tropical curve} is a stable weighted metric graph, as defined in Section \ref{sec:GraphConventions}. The \newword{moduli space of tropical curves} $\M_{g,n}^{\trop}$ is the space of   tropical curves of genus $g$ with $n$ leaves, up to isomorphism preserving the metric and each of the labeled leaves. The \newword{link} $\Link\M_{g,n}^{\trop}\subseteq\M_{g,n}^{\trop}$ is the locus of metric graphs whose edge lengths sum to 1.

There are canonical isomorphisms, as noted in \cite{ChanGalatiusPayne2021}:
\begin{itemize}
    \item $\mathcal{C}(S_{g,n})/\MCG(S_{g,n})\xrightarrow{\cong}{}\Link\M_{g,n}^{\trop}$, sending a multicurve $\Gamma$ to its dual graph $\tau_\Gamma$. The barycentric coordinates on $\mathcal{C}(S_{g,n})$ determine an assignment of a positive real length to each edge of $\tau_\Gamma$, so that the edge lengths sum to 1.
    \item $\D(\Xgn)/\MCG(\Xgn)\xrightarrow{\cong}{}\Link\M_{g,n}^{\trop}$, sending a multidisk $\Delta$ to its dual graph $\tau_\Delta$.
    \item $\CV_{g,n}^*/A_{g,n}\xrightarrow{\cong}{}\Link\M_{g,n}^{\trop}$, forgetting the marking, contracting all length-zero edges, and adding appropriate vertex weights.
\end{itemize}

Since the action of $A_{g,n}$ on $\CV_{g,n}^*$ is simplicial, $\M_{g,n}^{\trop}$ has the structure of a generalized cone complex, or a cone stack over polyhedral complexes, of dimension $3g-3+n$, see \cite{AbramovichCaporasoPayne2012,CavalieriChanUlirschWise2020}. (A generalized cone complex is to a cone complex what an orbifold is to a manifold.) For each isomorphism class $\tau$ of stable $n$-leafed genus-$g$ weighted graphs, the space $\M_{g,n}^{\trop}$ has a ``folded cone'' isomorphic to $\R_{\ge0}^{\abs{E(\tau)}}/\Aut(\tau)$ (recording the possible vectors of internal edge length assignments), and the cones are glued together by identifying a graph with internal edge $e$ having length zero with the graph obtained by contracting that edge.

The \newword{pure locus} $\M_{g,n}^{\trop,\pure}\subset\M_{g,n}^{\trop}$ is the locus of graphs where all vertex weights are zero. The complement of $\M_{g,n}^{\trop,\pure},$ i.e. the set of graphs with at least one positive weight vertex, is a subcomplex of $\M_{g,n}^{\trop}$. We also define the pure locus $\Link\M_{g,n}^{\trop,\pure}=\M_{g,n}^{\trop,\pure}\cap\Link\M_{g,n}^{\trop}$; this is the quotient of $\CV_{g,n}$ by $A_{g,n}.$

%The \newword{link} $\Link(M_{g,n}^{\trop})$ is the space of genus-$g$ weighted stable graphs whose edge lengths sum to 1, up to isomorphism.

\subsection{Boundary complexes} 
\label{sec:BoundaryComplexes}
The space $\Mbar_{g,n}\setminus\M_{g,n}$ is the topological boundary of $\M_{g,n}$ as a subset of $\Mbar_{g,n}$ It is a \newword{normal crossings hypersurface}, and  the \newword{boundary complex} of the compactification $\Mbar_{g,n}\supseteq\M_{g,n}$ is obtained by taking a vertex for each irreducible boundary hypersurface and a $k$-simplex for each irreducible component of each $(k+1)$-fold intersection of irreducible boundary hypersurfaces, glued in the natural way \cite{AbramovichCaporasoPayne2012}. (The resulting object is a symmetric $\Delta$-complex.) The boundary complex of $\Mbar_{g,n}\supseteq\M_{g,n}$ is naturally identified with $\Link(\M_{g,n}^{\trop})$.

For $\Sgn$ an $n$-pointed genus-$g$ surface, recall that, like $\Mbar_{g,n}$, $\Tbar(\Sgn)$ has a natural boundary stratification whose locally closed strata are complex manifolds (Section \ref{sec:AugmentedTeichmullerSpace}). Unlike the compactification $\M_{g,n}\subseteq\Mbar_{g,n}$, the boundary of the partial compactification $\T(\Sgn)\subseteq\Tbar(\Sgn)$ is not a normal crossings hypersurface, since, unlike $\Mbar_{g,n},$ $\Tbar(\Sgn)$ is not even an orbifold. However, there is still a reasonable notion of boundary complex:
\begin{Def}\label{Def:BoundaryComplex}
The \emph{boundary complex} of the compactification $\T(\Sgn)\subseteq\Tbar(\Sgn)$ is the simplicial complex whose vertex set is the set of codimension-1 locally closed strata in $\Tbar(\Sgn)$, and whose $k$-simplices are collections of $k$ codimension-1 strata whose closures have nonempty intersection. The boundary complex of $\T(\Sgn)\subseteq\Tbar(\Sgn)$ is naturally identified with the curve complex $\mathcal{C}(\Sgn)$.
\end{Def}


\begin{rem}\label{rem:InheritedBoundaryComplex}
    Let $(U,G)$ be as in Remark \ref{rem:InheritedStratification}. Since $U$ is an open union of locally closed strata $\T_\Gamma(\Sgn),$ it naturally defines a $G$-invariant closed subcomplex $\mathcal{C}_U(\Sgn)\subseteq\mathcal{C}(\Sgn).$ The quotient $U/G$ possesses a boundary complex analogously to Definition \ref{Def:BoundaryComplex}, which is again a symmetric $\Delta$-complex. The quotient $\mathcal{C}_U(\Sgn)/G$ also has the natural structure of a symmetric $\Delta$-complex, and these two complexes are canonically isomorphic.
\end{rem}







\section{The mapping class group exact sequence of an \texorpdfstring{$n$}{n}-pointed handlebody}\label{sec:LuftMarkedPoints}
Let $\Xgn$ be an $n$-pointed genus-$g$ handlebody, and let $S_{g,n}=\partial\Xgn$. Recall the three groups $\MCG(\Xgn)$, $\hMCG(\Xgn)$ and $\Tw(\Xgn)$ associated to $\Xgn$, from Section \ref{sec:MappingClassGroups}. Luft proved that the following sequence is  exact  when $n=0$:
\begin{prop}[\cite{Luft1978}]\label{prop:Luft}
    There is a natural exact sequence \begin{align}
        1\to\Tw(\Xg)\to\MCG(\Xg)\to\hMCG(\Xg)\to1.
    \end{align}
\end{prop}
In this section, we prove that this sequence remains exact in the presence of labeled points:
\begin{thm}\label{thm:LuftMarkedPoints}
    There is a natural exact sequence 
    \begin{align}\label{eq:HandlebodyGroupExactSequence}
        1\to\Tw(\Xgn)\to\MCG(\Xgn)\to\hMCG(\Xgn)\to1.
    \end{align}
\end{thm}
We will prove Theorem \ref{thm:LuftMarkedPoints} by induction on $n$, using Proposition \ref{prop:Luft} as the base case $n=0.$ We set up the induction in several steps. In what follows, assume $n>0$.

\begin{lemma}\label{lem:conjugate}
The subgroup of $\pi_1(\Sg\setminus\{x_1,\ldots,x_{n-1}\},x_n)$ generated by simple loops that bound an embedded disk is a normal subgroup.
\end{lemma}
