\begin{proof}[Proof of Theorem \ref{thm:LuftMarkedPoints}]
    We proceed by induction on $n$, with base case $n=0$ established in \cite[Cor. 2.5]{Luft1978}.

    Let $n>0.$ We have the following diagram:
    $$\begin{tikzcd}
        &&\MCG(\Xgn)\arrow[r,"\zeta"]\arrow[d,"\xi_1"]&\hMCG(\Xgn)\arrow[d,"\xi_2"]\\
        1\arrow[r]&\Tw(\X_{g,n-1})\arrow[r]&\MCG(\X_{g,n-1})\arrow[r]&\hMCG(\X_{g,n-1})\arrow[r]&1
    \end{tikzcd}$$
    The bottom row is exact by the inductive hypothesis, and it is easy to check that $\xi_1$ and $\xi_2$ are surjective. A straightforward diagram chase therefore gives the following diagram, where rows and columns are exact:
    $$\begin{tikzcd}
        &1\arrow[d]&1\arrow[d]&1\arrow[d]&\\
        1\arrow[r]&K\arrow[r]\arrow[d]&\ker(\xi_1)\arrow[r]\arrow[d]&\ker(\xi_2)\arrow[d]&\\
        1\arrow[r]&\ker(\zeta)\arrow[r]\arrow[d]&\MCG(\Xgn)\arrow[r,"\zeta"]\arrow[d,"\xi_1"]&\hMCG(\Xgn)\arrow[d,"\xi_2"]&\\
        1\arrow[r]&\Tw(\X_{g,n-1})\arrow[r]\arrow[d]&\MCG(\X_{g,n-1})\arrow[r]\arrow[d]&\hMCG(\X_{g,n-1})\arrow[r]\arrow[d]&1\\
        &1&1&1&
    \end{tikzcd}$$
    We first check that $\zeta$ is surjective. By Proposition \ref{prop:hMCGAddPoint}, we have canonical isomorphisms \begin{align*}
        \ker(\xi_2)&\cong\pi_1(\Xg\setminus\{x_1,\ldots,x_{n-1}\},x_n)
    \end{align*}
    and
    \begin{align*}    \ker(\xi_1)&\cong\pi_1(\Sg\setminus\{x_1,\ldots,x_{n-1}\},x_n),
    \end{align*}
    and the map $\ker(\xi_1)\to\ker(\xi_2)$ is identified with the natural map $$\pi_1(\Sg\setminus\{x_1,\ldots,x_{n-1}\},x_n)\to\pi_1(\Xg\setminus\{x_1,\ldots,x_{n-1}\},x_n)$$ induced by inclusion. It is well-known that this map is surjective, from which a straightforward diagram chase implies that $\zeta$ is surjective. We now have the diagram:
    $$\begin{tikzcd}
        &1\arrow[d]&1\arrow[d]&1\arrow[d]&\\
        1\arrow[r]&K\arrow[r]\arrow[d]&\pi_1(\Sg\setminus\{x_1,\ldots,x_n\},x_n)\arrow[r]\arrow[d]&\pi_1(\Xg\setminus\{x_1,\ldots,x_n\},x_n)\arrow[r]\arrow[d]&1\\
        1\arrow[r]&\ker(\zeta)\arrow[r]\arrow[d]&\MCG(\Xgn)\arrow[r,"\zeta"]\arrow[d,"\xi_1"]&\hMCG(\Xgn)\arrow[r]\arrow[d,"\xi_2"]&1\\
        1\arrow[r]&\Tw(\X_{g,n-1})\arrow[r]\arrow[d]&\MCG(\X_{g,n-1})\arrow[r]\arrow[d]&\hMCG(\X_{g,n-1})\arrow[r]\arrow[d]&1\\
        &1&1&1&
    \end{tikzcd}$$

    We wish to show that $\ker(\zeta)=\Tw(\Xgn).$ Since Dehn twists around disks in $\Xgn$ act trivially up to homotopy, we have $\Tw(\Xgn)\subseteq\ker(\zeta).$

    Since any disk in $\X_{g,n-1}$ can be lifted to a disk in $\Xgn,$ we have $$\xi_1(\Tw(\Xgn))=\Tw(\X_{g,n-1}).$$ It is therefore sufficient (by the correspondence theorem for groups) to show that $K\subseteq\Tw(\Xgn).$



    By Lemma \ref{lem:KernelOfAlphaGeneratedByMeridians}, $K\subseteq\pi_1(\Sg\setminus\{x_1,\ldots,x_{n-1}\},x_n)$ is generated by simple loops that bound an embedded disk. The isomorphism $\pi_1(\Sg\setminus\{x_1,\ldots,x_{n-1}\},x_n)\cong\ker(\xi_1)$ identifies such a loop $\gamma$ with the product of Dehn twists $\tw_{\delta}\cdot\tw_{\delta'},$ where $\delta$ and $\delta'$ are the two disks in $\Xgn$ whose boundaries are obtained by perturbing $\gamma$ away from $x_n$ in the two possible directions, and $\tw_{\delta},\tw_{\delta'}$ denote the corresponding Dehn twists (see \cite[Fact 4.7]{FarbMargalit2011}, \cite[Lem. 3.3]{Hensel2020}). (If $\gamma$ is just a loop around a labeled point $x_i$, then one of these Dehn twists is trivial --- this does not cause any problems with the argument.) Thus $K\subseteq\Tw(\Xgn)$ as desired.
\end{proof}



\begin{rem}
    Since $\Xgn$ is $n$-pointed-homotopy equivalent to the $n$-thorned rose $R_{g,n}$, we have $\hMCG(\Xgn)\cong A_{g,n}.$
\end{rem}


\section{Complex handlebodies and the Teichm\"uller space of a handlebody}\label{sec:T(Vgn)}
\begin{Def}
    An $n$-pointed genus-$g$ \emph{complex handlebody} is a triple $(Y,C,\iota),$ where $Y$ is an $n$-pointed genus-$g$ handlebody, $C$ is an $n$-pointed genus-$g$ Riemann surface, and $\iota:C\to Y$ is an $n$-pointed homeomorphism of $C$ onto the boundary of $Y$. An isomorphism of complex handlebodies $(Y_1,C_1,\iota_1)$ and $(Y_2,C_2,\iota_2)$ is an $n$-pointed homeomorphism $\mu:Y_1\to Y_2$ such that $\iota_2^{-1}\circ\mu\circ\iota_1:C_1\to C_2$ is an isomorphism of $n$-pointed Riemann surfaces. 
    % a commutative diagram $$
    %     \begin{tikzcd}
    %         C_1\arrow[r,"\beta"]\arrow[d,"\iota_1"]&C_2\arrow[d,"\iota_2"]\\
    %         Y_1\arrow[r,"\mu"]&Y_2
    %     \end{tikzcd}
    % $$ where $\mu$ is a homeomorphism and $\beta=\mu_{C_1}:C_1\to C_2$ is an isomorphism of Riemann surfaces.
    %(A 2-isomorphism is an isotopy between maps $\mu$ that is constant on the boundary?)
\end{Def}
Let $\Xgn$ be an $n$-pointed genus-$g$ handlebody, and let $ \iota_{g,n}\colon\Sgn=\partial\Xgn\hookrightarrow \Xgn$  be the inclusion.  
\begin{Def}
    A \emph{complex structure} on $\Xgn$ is an $n$-pointed homeomorphism from $\Xgn$ to a complex handlebody. In other words, a complex structure on $\Xgn$ is a tuple $(Y,C,\iota,\sigma)$, where $(Y,C,\iota)$ is an $n$-pointed genus-$g$ complex handlebody, and $\sigma:\Xgn\to Y$ is an $n$-pointed homeomorphism.
\end{Def}

\begin{Def}\label{def:TX}
    The Teichm\"uller space $\T(\Xgn)$ is the set of complex structures on $\Xgn$ up to $n$-pointed homeomorphism $n$-pointed-isotopic to the identity. Explicitly, two complex structures $(Y_1,C_1,\iota_1,\sigma_1)$ and $(Y_2,C_2,\iota_2,\sigma_2)$ are considered equivalent if 
    there exists an $n$-pointed isomorphism $\mu:Y_1\to Y_2$ of complex handlebodies and an $n$-pointed homeomorphism $\tilde\alpha:\Xgn\to \Xgn$ that is $n$-pointed-isotopic to the identity, such that the diagram commutes:
    \begin{align}\label{eq:TeichmullerEquivalenceHandlebody}
        \begin{tikzcd}[ampersand replacement=\&]
            \Xgn\arrow[r,"\sigma_1"]\arrow[d,"\tilde\alpha"]\&Y_1\arrow[d,"\mu"]\\
            \Xgn\arrow[r,"\sigma_2"]\&Y_2
        \end{tikzcd}
    \end{align}

    % there exists a commutative diagram 
    % % \begin{align}\label{eq:TeichmullerEquivalenceHandlebody}
    % %     \begin{tikzcd}[ampersand replacement=\&]
    % %         S\arrow[r]\arrow[d]\&C_1\arrow[r,"\beta"]\arrow[d,"\iota_1"]\&C_2\arrow[d,"\iota_2"]\\
    % %         \X\arrow[r,"\sigma_1"]\&Y_1\arrow[r,"\mu"]\&Y_2
    % %     \end{tikzcd}
    % % \end{align}

    % \begin{align}\label{eq:TeichmullerEquivalenceHandlebody}
    %     \begin{tikzcd}[ampersand replacement=\&]
    %         S\arrow[ddd]\arrow[rrr]\arrow[dr,"\hat\iota"]\&\&\&C_1\arrow[ddd]\arrow[dr,"\iota_1"]\&\\
    %         \&\X\arrow[rrr,"\sigma_1" xshift=-4ex]\arrow[ddd,"\tilde\alpha" yshift=4ex]\&\&\&Y_1\arrow[ddd,"\mu"]\\
    %         \&\&\&\&\\
    %         S\arrow[rrr]\arrow[dr,"\hat\iota"]\&\&\&C_2\arrow[dr,"\iota_2"]\&\\
    %         \&\X\arrow[rrr,"\sigma_2"]\&\&\&Y_2\\
    %     \end{tikzcd}
    % \end{align}
    % where the rightmost quadrilateral is an isomorphism of complex handlebodies, and $\tilde\alpha:\X\to \X$ is a homeomorphism isotopic to the identity.
\end{Def}
There is a well-defined map $\T(\Xgn)\to\T(\Sgn)$ sending $(Y,C,\iota,\sigma)\mapsto(C,\iota^{-1}\circ\sigma\circ\iota_{g,n})$. Note that $\sigma\circ\iota_{g,n}$ lands in $\partial Y$, where $\iota^{-1}$ is well-defined. The fact that the map is well-defined is immediate from the above notion of equivalence, and the fact that an isotopy from $\tilde\alpha:\Xgn\to\Xgn$ to the identity restricts to an isotopy from $\tilde\alpha|_{\Sgn}:\Sgn\to\Sgn$ to the identity. 
\begin{prop}\label{prop:TeichmullerBijection}
    The natural map $\T(\Xgn)\to\T(\Sgn)$ is a bijection. 
\end{prop}
\begin{proof}
    Surjectivity is clear --- given a complex structure $\phi:\Sgn\to C$, the tuple $(\X,C,\iota_{g,n}\circ\phi^{-1},\id_\X)\in\T(\Xgn)$ is a complex structure on $\Xgn$ that maps to $(C,\phi)\in\T(S).$

    For injectivity, suppose we have two complex structures $(Y_1,C_1,\iota_1,\sigma_1)$ and $(Y_2,C_2,\iota_2,\sigma_2)$ on $\Xgn$ that restrict to the same complex structure on $\Sgn$. Then there is an isomorphism $\beta:C_1\to C_2$ and homeomorphism $\alpha:\Sgn\to\Sgn$ isotopic to the identity such that $\sigma_2|_{\Sgn}\circ\alpha=\beta\circ\sigma_1|_{\Sgn}$.

    We show that $\alpha$ extends to a homeomorphism $\tilde\alpha:\Xgn\to \Xgn$ that is isotopic to the identity. Let $U\supset\Sgn$ be a tubular neighborhood in $\Xgn$ homeomorphic to $\Sgn\times[0,1]$, with $\Sgn$ identified with $\Sgn\times\{0\}$. Since $\alpha$ is isotopic to the identity, we may extend $\alpha$ to a map $U\to U$ that restricts to the identity on $\Sgn\times\{1\}$. Extending by the identity on $\Xgn\setminus U$ gives a homeomorphism $\tilde\alpha:\Xgn\to \Xgn$ with a clear isotopy to the identity.

    Let $\mu=\sigma_2\circ\tilde\alpha\circ\sigma_1^{-1}.$ The restriction of $\mu$ to $C_1$ is $\beta$, which is an isomorphism of Riemann surfaces, and the diagram \eqref{eq:TeichmullerEquivalenceHandlebody} commutes by construction, showing that \begin{align*}
        (Y_1,C_1,\iota_1,\sigma_1)&=(Y_2,C_2,\iota_2,\sigma_2)\in\T(\Xgn).\qedhere
    \end{align*}
\end{proof}

From now on, we identify $\T(\Xgn)$ with $\T(\Sgn)$ via this map.

\section{Stable complex handlebodies and the augmented Teichm\"uller space of a handlebody}\label{sec:Tbar(Vgn)}
\begin{Def}\label{Def:StableComplexHandlebody}
    An \emph{stable $n$-pointed genus-$g$ complex handlebody} is a triple $(Y,C,\iota),$ where $Y$ is a finite disjoint union of handlebodies, glued together at finitely many points, together with $n$ points on the boundary of $Y$ disjoint from the locus of glued points, $C$ is an $n$-pointed genus-$g$ stable curve, and $\iota:C\to \partial Y\subset Y$ is an $n$-pointed homeomorphism of $C$ to the boundary of $Y$. An isomorphism of stable complex handlebodies is an $n$-pointed homeomorphism $\mu:Y_1\to Y_2$ such that the restriction $\iota_2^{-1}\circ\mu\circ\iota_1:C_1\to C_2$ is an isomorphism of $n$-pointed stable curves. 

    Note that an $n$-pointed genus-$g$ stable complex handlebody $(Y,C,\iota)$ has a (stable $n$-pointed genus-$g$) weighted dual graph $\tau_Y$ constructed in the same way as the dual graph of a stable curve --- in fact, the dual graph of $(Y,C,\iota)$ coincides with the dual graph of $C$. As before, there is a canonical continuous map   $\dgm_Y$, unique up to homotopy, from $Y$ to the topological  realization of $\tau_Y$. 

    % commutative diagram
    % $$
    %     \begin{tikzcd}
    %         C_1\arrow[r,"\beta"]\arrow[d,"\iota_1"]&C_2\arrow[d,"\iota_2"]\\
    %         Y_1\arrow[r,"\mu"]&Y_2
    %     \end{tikzcd}
    % $$
    % where $\beta$ is an isomorphism of stable curves and $\mu$ is a homeomorphism.
\end{Def}

As before, let $\Xgn$ be an $n$-pointed genus-$g$ handlebody,     $\Sgn=\partial\Xgn$ and   $\iota_{g,n}\colon\Sgn\hookrightarrow \Xgn$ the inclusion.  
\begin{Def}
    The \emph{augmented Teichm\"uller space} $\Tbar(\Xgn)$ is the set of tuples $\{(Y,C,\iota,\sigma)\}/\sim$, where $(Y,C,\iota)$ is a stable $n$-pointed genus-$g$ complex handlebody, and $\sigma:\Xgn\to Y$ is a surjective $n$-pointed map that is a homeomorphism away from some multidisk $\Delta$ in $\Xgn$, and contracts each connected component of $\Delta$ to a node of $C$. The equivalence relation is the same as for $\T(\Xgn).$
\end{Def}
% \begin{Def}
%     We define the \emph{augmented Teichmuller space} $\Tbar(\X)\subseteq\Tbar(S)$ to be the set of pairs $(C,\phi)\in\Tbar(S)$ such that the multicurve $\gamma$ where $\phi$ fails to be a homeomorphism is a multimeridian.
% \end{Def}
\begin{prop}\label{prop:AugmentedTeichmullerInjection}
    The natural map $\Tbar(\Xgn)\to\Tbar(\Sgn)$ sending $(Y,C,\iota,\sigma)\mapsto(C,\sigma|_{\Sgn})$ is injective. 
\end{prop}
\begin{proof}
    The proof is identical to the proof of Proposition \ref{prop:TeichmullerBijection}.
\end{proof}
\begin{prop}\label{prop:AugmentedTeichmullerLocus}
    The image of $\Tbar(\Xgn)\to\Tbar(\Sgn)$ is the locus consisting of pairs $(C,\phi)\in\Tbar(\Sgn)$ such that the multicurve $\Delta$ at which $\phi$ fails to be a homeomorphism is a multimeridian.
\end{prop}
\begin{proof}
    Let $(C,\phi)\in\Tbar(\Sgn)$ be such that the multicurve $\Gamma\subset S$ at which $\phi$ fails to be a homeomorphism is a multimeridian, bounding some multidisk $\Delta$. Note that $\phi:\Sgn\to C$ induces a homeomorphism $\underline{\phi}:\Sgn/\Gamma\to C,$ where $\Sgn/\Gamma$ is obtained from $\Sgn$ by contracting each component of $\Gamma$ to a point.

    Let $q_\Delta:\Xgn\to \Xgn/\Delta$ denote the quotient map that contracts each component of $\Delta$ to a point. By the universal property of the quotient topology, $q_\Delta\circ\iota_{g,n}$ descends to a map $F:\Sgn/\Gamma\to \Xgn/\Delta$, since $q_\Delta\circ\iota_{g,n}:\Sgn\to \Xgn/\Delta$ is constant on each component of $\Gamma$. It is immediate that  $(\Xgn/\Delta,C,F\circ\underline{\phi}^{-1},q_\Delta)\in\Tbar(\Xgn)$ maps to $(C,\phi).$ 

    On the other hand, for any $(Y,C,\iota,\sigma)\in\Tbar(\Xgn),$ we know $\sigma$ fails to be a homeomorphism on a multidisk, by definition. Thus $\sigma|_{\Sgn}$ fails to be a homeomorphism on a multimeridian.
\end{proof}
\begin{rem}
    From now on, we identify $\Tbar(\Xgn)$ with its image in $\Tbar(\Sgn)$, via the injection of Proposition \ref{prop:AugmentedTeichmullerInjection}. Under this identification, $\Tbar(\Xgn)$ is a dense $\MCG(\Xgn)$-invariant open set of $\Tbar(\Sgn)$ that contains $\T(\Xgn)=\T(\Sgn)$. 
\end{rem}

\begin{ex}\label{ex:V112}
    In Example \ref{ex:V111}, we saw that $\Tbar(S_{1,1})$ is homeomorphic to $\mathbb{H}\cup\Q\cup\{\infty\}$, where $\mathbb{H}$ is the (open) upper half-plane in $\C$. By Proposition \ref{prop:AugmentedTeichmullerLocus}, under this identification, $\Tbar(V_{1,1})$ is identified with $\mathbb{H}\cup\{\infty\}$, since $V_{1,1}$ contains a unique essential disk up to isotopy. As expected, $\mathbb{H}\cup\{\infty\}$ is invariant under the subgroup $$\MCG(\X_{1,1})\cong\left\{\pm\begin{pmatrix}
        1&0\\
        a&1
    \end{pmatrix}:a\in\Z\right\}\subset\SL_2(\Z)$$ from Example \ref{ex:V110}; in fact, as noted in Example \ref{ex:V111}, this subgroup is precisely the stabilizer of $\infty$.
\end{ex}


By definition, $\Tbar(\Xgn)$ is naturally partitioned into subsets indexed by multidisks in $\Xgn$.
\begin{Def}[Boundary strata of $\Tbar(\Xgn)$]
Let $\Delta\subset \Xgn$ be a multidisk. We denote by $\T_\Delta(\Xgn)$ the set of tuples $(Y,C,\iota,\sigma)$ such that the multidisk where $\sigma$ fails to be a homeomorphism is ($n$-pointed-)isotopic to $\Delta$. We denote by $\Tbar_\Delta(\Xgn)$ the set of tuples $(Y,C,\iota,\sigma)$ such that the multidisk where $\sigma$ fails to be a homeomorphism is isotopic to a multidisk containing $\Delta$.
\end{Def}

\begin{rem}[Intersection of Boundary Strata]
    Let $\Delta_1$ and $\Delta_2$ be two multidisks in $\Xgn$. Then $$\Tbar_{\Delta_1}(\Xgn)\cap\Tbar_{\Delta_2}(\Xgn)=\begin{cases}
        \Tbar_{\Delta_1\cup\Delta_2}(\Xgn)&\Delta_1\cup\Delta_2\text{ is a multidisk}\\
        \emptyset&\text{else}.
    \end{cases}$$
\end{rem}

The following is immediate from Proposition \ref{prop:AugmentedTeichmullerLocus}:
\begin{prop}
    The boundary complex of $\Tbar(\Xgn)$, in the sense of Definition \ref{Def:BoundaryComplex}, is canonically isomorphic to the disk complex $\mathcal{D}(\Xgn)$.
\end{prop}
The recursive descriptions \eqref{eq:TSBoundaryRecursion} and \eqref{eq:TbarSBoundaryRecursion} of the boundary strata of $\Tbar(\Sgn)$ restrict to recursive descriptions of the boundary strata of $\Tbar(\Xgn)$, as follows
\begin{prop}
    There are natural isomorphisms
    $$\T_\Delta(\Xgn)\cong\prod_{\text{$v$ a vertex of $\tau_\Delta$}}\T(\Xgn\langle v\rangle) $$ and 
    $$\Tbar_\Delta(\Xgn)\cong\prod_{\text{$v$ a vertex of $\tau_\Delta$}}\Tbar(\Xgn\langle v\rangle),$$ where for each connected component $v$ of $\Xgn\setminus\Delta,$ $\Xgn\langle v\rangle$ denotes the pointed handlebody obtained by contracting each boundary disk in (the closure in $\Xgn$ of) $v$ to a point, and marking that point.
\end{prop}
In particular, $\T_\Delta(\X)$ is naturally a complex manifold whose codimension is the number of disks in $\Delta$.

\section{The moduli space of complex handlebodies}\label{sec:Mghbar}
\begin{Def}
    The \emph{moduli space of stable $n$-pointed genus-$g$ complex handlebodies} $$\Mbargnh=\{(Y,C,\iota)\}/\cong$$ is the set of stable $n$-pointed genus-$g$ complex handlebodies up to isomorphism. We define the subset $$\Mgnh=\{(Y,C,\iota)\in\Mbargnh:\text{$C$ is smooth}\}.$$
\end{Def}

For an element $(Y,C,\iota,\sigma)\in\Tbar(\Xgn)$, we may forget $\sigma$ to get a stable complex handlebody $(Y,C,\iota)\in\Mbargnh,$ giving a natural map $J_1:\Tbar(\Xgn)\to\Mbargnh$.

\begin{prop}\label{prop:UnmarkedBijection}
    The natural map $J_1:\Tbar(\Xgn)\to\Mbargnh$ descends to a bijection $$\bar{J}_1:\Tbar(\Xgn)/\MCG(\Xgn)\xrightarrow{\cong}{}\Mbargnh.$$
\end{prop}
\begin{proof}
    \noindent\textbf{The map $\bar{J}_1$ is well-defined.} Let $(Y,C,\iota,\sigma)\in\Tbar(\Xgn)$, and let $h\in\MCG(\Xgn).$ By definition of the $\MCG(\Xgn)$-action on $\Tbar(\Xgn)$, we have $$J_1((Y,C,\iota,\sigma)\cdot h)=J_1((Y,C,\iota,\sigma\circ h))=(Y,C,\iota)=J_1((Y,C,\iota,\sigma)),$$ so $J_1$ descends to a map $\bar{J}_1:\Tbar(\Xgn)/\MCG(\Xgn)\to\Mbargnh.$

    \medskip

    \noindent\textbf{Surjectivity of $\bar{J}_1$} Let $(Y,C,\iota)\in\Mbargnh,$ and let $y_1,\ldots,y_k$ be the nodes of the stable curve $C$. For each node $y_i$, delete a small open neighborhood of $\iota(y_i)\in Y.$ The result is a disjoint union of handlebodies with $2k$ boundary disks altogether. We glue pairs of boundary disks that came from the same node to get an $n$-pointed genus-$g$ handlebody $\tilde Y$, together with a multidisk $\Delta\subset\tilde Y,$ such that $\tilde Y\setminus\Delta$ is canonically (up to homotopy) homeomorphic to $Y\setminus\{\iota(y_1),\ldots,\iota(y_k)\}.$ Choose an arbitrary ($n$-pointed) homeomorphism $\sigma:\Xgn\xrightarrow{\cong}{}\tilde Y$. Then $(Y,C,\iota,\sigma)\in\bar{J}_1^{-1}(Y,C,\iota),$ i.e. $\bar{J}_1$ is surjective.

    \medskip

    \noindent\textbf{Injectivity of $\bar{J}_1$} Let $(Y_1,C_1,\iota_1,\sigma_1)$ and $(Y_2,C_2,\iota_2,\sigma_2)$ be two elements of $\Tbar(\Xgn)$ such that $$\bar{J}_1(Y_1,C_1,\iota_1,\sigma_1)=\bar{J}_1(Y_2,C_2,\iota_2,\sigma_2).$$ Then by definition of isomorphism of stable complex handlebodies, there exists a homeomorphism $\mu:Y_1\to Y_2$ such that $\iota_2^{-1}\circ\mu\circ\iota_1:C_1\to C_2$ is an isomorphism of stable curves. Consider the homeomorphism $$\alpha=\sigma_2^{-1}\circ\mu\circ\sigma_1:\Xgn\to \Xgn$$ as an element of $\MCG(\Xgn).$ Then $\alpha\cdot(Y_2,C_2,\iota_2,\sigma_2)=(Y_2,C_2,\iota_2,\sigma_2\circ\alpha)=(Y_2,C_2,\iota_2,\mu\circ\sigma_1)$. By definition of the equivalence relation on $\Tbar(\Xgn),$ we have $(Y_2,C_2,\iota_2,\mu\circ\sigma_1)=(Y_1,C_1,\iota_1,\sigma_1)$, taking $\tilde\alpha$ to be the identity in \eqref{eq:TeichmullerEquivalenceHandlebody}. Thus $(Y_1,C_1,\iota_1,\sigma_1)$ and $(Y_2,C_2,\iota_2,\sigma_2)$ are in the same $\MCG(\Xgn)$-orbit in $\Tbar(\Xgn)$. This shows $\bar{J}_1$ is injective.
\end{proof}

\begin{ex}\label{ex:V113}
    Recall from Example \ref{ex:V112} that $\Tbar(V_{1,1})\cong\mathbb{H}\cup\{\infty\}$ and $\MCG(V_{1,1})\cong\Stab_{\SL_2(\Z)}(\infty)\cong\Z\times\Z/2\Z,$ where $\Z/2\Z$ acts trivially on $\mathbb{H}\cup\{\infty\}$. Note that the quotient $$\T(V_{1,1})/\MCG(V_{1,1})\cong\mathbb{H}/\Stab_{\SL_2(\Z)}(\infty)$$ is homeomorphic to a cylinder, since $\Stab_{\SL_2(\Z)}(\infty)$ acts on $\mathbb{H}$ by integer horizontal translations. Note that as an \emph{orbifold}, the quotient $\T(V_{1,1})/\MCG(V_{1,1})$ ``remembers'' the fact that every point of $\T(V_{1,1})$ has nontrivial stabilizer isomorphic to $\Z/2\Z,$ coming from the fact that $\MCG(V_{1,1})$ does not act freely. To be precise, we should say that the \emph{underlying topological space} of the orbifold $\T(V_{1,1})/\MCG(V_{1,1})$ is homeomorphic to a cylinder.

    The quotient $\Tbar(V_{1,1})/\MCG(V_{1,1})\cong\mathbb{H}\cup\{\infty\}/\Stab_{\SL_2(\Z)}(\infty)$ is homeomorphic to a disk, with the image of $\infty$ at the center. (The above comment about orbifolds does not apply, as $\MCG(V_{1,1})$ acts on $\Tbar(V_{1,1})$ with infinite stabilizers, so a priori there is no orbifold structure on the quotient, only the structure of a topological space. In Section \ref{sec:ComplexStructures}, we will endow the quotient with the structure of a complex orbifold.)


\end{ex}

We note the following, which is immediate from the proof:
\begin{obs}\label{obs:BijectionRestrictsToInterior}
    The bijection in Proposition \ref{prop:UnmarkedBijection} restricts to a bijection $\Mgnh\cong\T(\Xgn)/\MCG(\Xgn).$
\end{obs}

\begin{rem}\label{rem:TopologyOfMgh}
    The bijection in Proposition \ref{prop:UnmarkedBijection} naturally endows $\Mbargnh$ with a topology. Applying Remarks \ref{rem:InheritedStratification} and \ref{rem:InheritedBoundaryComplex} to the pair $(U,G)=(\Tbar(\Xgn),\MCG(\Xgn))$, we also have the following structures:
    \begin{itemize}
        \item A boundary stratification of $\Mbargnh$ by connected, locally closed strata, each with the natural structure of a complex orbifold, with strata indexed by $\MCG(\Xgn)$-orbits of boundary strata of $\Tbar(\Xgn),$ and
        \item A boundary complex of $\Mgnh\subseteq\Mbargnh$, canonically isomorphic to $\mathcal{D}(\Xgn)/\MCG(\Xgn).$
    \end{itemize}
\end{rem}
Combining this with the canonical isomorphism $\D(\Xgn)/\MCG(\Xgn)\cong\Link\M_{g,n}^{\trop}$ in \cite{Grasse1989,McCullough1991}, we have the following:
\begin{cor}\label{cor:BoundaryMghLinkMgTrop}
    The boundary complex of $\Mgnh\subseteq\Mbargnh$ is canonically isomorphic to $\Link\M_{g,n}^{\trop}$. That is, the boundary strata of $\Mbargnh$ are indexed by stable $n$-pointed genus-$g$ weighted graphs, and the stratum corresponding to a graph $\tau$ is the locus in $\Mbargnh$ consisting of stable complex handlebodies with dual graph $\tau$. (See Definition \ref{Def:StableComplexHandlebody}.)
\end{cor}




\section{Homotopy-marked complex handlebodies and their moduli}\label{sec:Mgmhbar}
\begin{Def}
    A \emph{stable $n$-pointed genus-$g$ homotopy-marked complex handlebody} is a tuple $(Y,C,\iota,\eta)$, where $(Y,C,\iota)$ is a stable $n$-pointed genus-$g$ complex handlebody and $\eta:\Xgn\to Y$ is an $n$-pointed homotopy equivalence. Two stable homotopy-marked handlebodies $(Y_1,C_1,\iota_1,\eta_1)$ and $(Y_2,C_2,\iota_2,\eta_2)$ are isomorphic if there is a commutative diagram
    $$
        \begin{tikzcd}
            C_1\arrow[r,"\beta"]\arrow[d,"\iota_1"]&C_2\arrow[d,"\iota_2"]\\
            Y_1\arrow[r,"\mu"]&Y_2\\
            \Xgn\arrow[u,"\eta_1"]\arrow[ur,"\eta_2"']&
        \end{tikzcd}
    $$ where $\beta$ is an isomorphism of $n$-pointed Riemann surfaces and $\mu$ is an $n$-pointed homeomorphism, such that $\eta_2$ is $n$-pointed-homotopic to $\mu\circ\eta_1$.
\end{Def}
\begin{Def}
    The moduli space of stable $n$-pointed genus-$g$ homotopy-marked complex handlebodies is the set $$\Mbargnmh=\{(Y,C,\iota,\eta)\}/\cong$$ of stable $n$-pointed genus-$g$ homotopy-marked complex handlebodies up to isomorphism. We define the subset $$\Mgnmh=\{(Y,C,\iota,\eta)\in\Mbargnmh:\text{$C$ is smooth}\}.$$
\end{Def}

For $(Y,C,\iota,\sigma)\in\Tbar(\Xgn),$ note that the map $\sigma:\Xgn\to Y$ is a homeomorphism away from some multidisk, which it contracts. In particular, it is a homotopy equivalence. We therefore have a natural map $J_2:\Tbar(\Xgn)\to\Mbargnmh$ that sends $(Y,C,\iota,\sigma)\mapsto(Y,C,\iota,\sigma).$
\begin{prop}\label{prop:MarkedBijection}
The map $J_2:\Tbar(\Xgn)\to\Mbargnmh$ descends to a bijection $$\bar{J}_2:\Tbar(\Xgn)/\Tw(\Xgn)\xrightarrow{\cong}{}\Mbargnmh.$$    
\end{prop}
\begin{proof}
    \noindent\textbf{The map $\bar{J}_2$ is well-defined.} Let $(Y,C,\iota,\sigma)\in\Tbar(\Xgn)$, and let $h\in\Tw(\Xgn)$. By Proposition \ref{prop:Luft}, $h$ is in the kernel of the map $\MCG(\Xgn)\to\hMCG(\Xgn),$ so $h$ is $n$-pointed-homotopic (though not necessarily isotopic) to the identity. Thus $\sigma\circ h$ is $n$-pointed-homotopic to $\sigma.$ Hence $$J_2((Y,C,\iota,\sigma)\cdot h)=J_2(Y,C,\iota,\sigma\circ h)=J_2(Y,C,\iota,\sigma),$$ so $\bar{J}_2$ is well-defined.

    \medskip

    \noindent\textbf{Surjectivity of $\bar{J}_2$.} Let $(Y,C,\iota,\eta)\in\Mbargnmh$. As in the proof of surjectivity of $\bar{J}_1,$ there exists a map $\sigma:\Xgn\to Y$ that is an $n$-pointed homeomorphism away from some multidisk $\Delta$, each component of which is contracted to a node of $Y$. This map $\sigma$ is invertible up to homotopy; let $\underline{\sigma}:Y\to \X$ be an $n$-pointed homotopy inverse of $\sigma$. The composition $\underline{\sigma}\circ\eta:\Xgn\to\Xgn$ is an $n$-pointed homotopy equivalence. By Theorem \ref{thm:LuftMarkedPoints}, there exists an $n$-pointed homeomorphism $h:\Xgn\to \Xgn$ that is $n$-pointed homotopic to $\underline{\sigma}\circ\eta$. Thus $\sigma\circ h$ is homotopic to $\eta$. Because $h$ is a homeomorphism and $\sigma$ is a homeomorphism away from a multidisk, $\sigma\circ h$ is a homeomorphism away from a multidisk. Thus $J_2(Y,C,\iota,\sigma\circ h)=(Y,C,\iota,\eta)$. This shows that $J_2$, and hence $\bar{J}_2$, is surjective.

    \medskip

    \noindent\textbf{Injectivity of $\bar{J}_2$.} Let $(Y_1,C_1,\iota_1,\sigma_1)$ and $(Y_2,C_2,\iota_2,\sigma_2)$ be two elements of $\Tbar(\Xgn)$ such that $$J_2(Y_1,C_1,\iota_1,\sigma_1)=J_2(Y_2,C_2,\iota_2,\sigma_2).$$ By definition of isomorphism of stable homotopy-marked complex handlebodies, there exists an $n$-pointed homeomorphism $\mu:Y_1\to Y_2$ such that $\iota_2^{-1}\circ\mu\circ\iota_1:C_1\to C_2$ is an isomorphism of $n$-pointed stable curves and the two maps $\mu\circ\sigma_1:\Xgn\to Y_2$ and $\sigma_2:\Xgn\to Y_2$ are homotopic. Since $\sigma_2:\Xgn\to Y_2$ is a homeomorphism away from a contracted multidisk, it is in particular a homotopy equivalence. Therefore $\sigma_2$ has a homotopy inverse $\underline{\sigma_2}:Y_2\to\Xgn$. Now by construction, $\underline{\sigma_2}\circ\mu\circ\sigma_1:\Xgn\to\Xgn$ is a homotopy equivalence homotopic to the identity. By Theorem \ref{thm:LuftMarkedPoints}, it lifts to an element $h\in\MCG(\Xgn)$ homotopic to the identity, which implies (again by Theorem \ref{thm:LuftMarkedPoints}) that actually $h\in\Tw(\Xgn).$ Then $$(Y_1,C_1,\iota_1,\sigma_1)=(Y_2,C_2,\iota_2,\sigma_2\circ h)=(Y_2,C_2,\iota_2,\sigma_2)\cdot h,$$ i.e. $(Y_1,C_1,\iota_1,\sigma_1)$ and $(Y_2,C_2,\iota_2,\sigma_2)$ are in the same $\Tw(\Xgn)$-orbit. We conclude that $\bar{J}_2$ is injective.  
\end{proof}
In analogy to Observation \ref{obs:BijectionRestrictsToInterior}, we note:
\begin{obs}
    The bijection in Proposition \ref{prop:MarkedBijection} restricts to a bijection $\Mgnmh\cong\T(\Xgn)/\Tw(\Xgn).$
\end{obs}
\begin{ex}\label{ex:V114}
    Note that $\Tw(V_{1,1})\subset\MCG(V_{1,1})$ is identified with the subgroup $$\left\{\begin{pmatrix}
        1&0\\
        a&1
    \end{pmatrix}:a\in\Z\right\}\subset\left\{\pm\begin{pmatrix}
        1&0\\
        a&1
    \end{pmatrix}:a\in\Z\right\}\cong\MCG(\X_{1,1}).$$
    By the same reasoning as in Example \ref{ex:V113}, $$h\mathcal{T}(\X_{1,1})\cong\T(\X_{1,1})/\Tw(\X_{1,1})$$ is homeomorphic to a cylinder, and $$\bar{h\mathcal{T}}(\X_{1,1})\cong\Tbar(\X_{1,1})/\Tw(\X_{1,1})$$ is homeomorphic to a disk. Unlike in Example \ref{ex:V113}, orbifold subtleties do not apply, as $\Tw(\X_{1,1})$ acts freely on $\T(\X_{1,1})$.
\end{ex}

In analogy to Remark \ref{rem:TopologyOfMgh}, we have
\begin{rem}\label{rem:TopologyOfMgmh}
    The bijection in Proposition \ref{prop:MarkedBijection} naturally endows $\Mbargnmh$ with a topology. Applying Remarks \ref{rem:InheritedStratification} and \ref{rem:InheritedBoundaryComplex} to the pair $(U,G)=(\Tbar(\Xgn),\Tw(\Xgn))$, we also have the following structures:
    \begin{itemize}
        \item A boundary stratification of $\Mbargnmh$ by connected, locally closed strata, each with the natural structure of a complex orbifold\footnote{We will show in Section \ref{sec:ComplexStructures} that the strata, as well as $\Mbargnmh$ itself, are complex \emph{manifolds}.}, with strata indexed by $\Tw(\Xgn)$-orbits of boundary strata of $\Tbar(\Xgn),$ and
        \item A boundary complex of $\Mgnmh\subseteq\Mbargnmh$, canonically isomorphic to $\mathcal{D}(\Xgn)/\Tw(\Xgn).$
    \end{itemize}
\end{rem}

\subsection{The \texorpdfstring{$\hMCG(\Xgn)$}{hMCG(Vgn)}-action on \texorpdfstring{$\Mbargnmh$}{hT(Vgn)}}. 

\begin{prop}
The $\MCG(\Xgn)$-action on $\Tbar(\Xgn)$ descends to a properly discontinuous action of $$\MCG(\Xgn)/\Tw(\Xgn)\cong\hMCG(\Xgn)\cong A_{g,n}$$ on $\Mbargnmh$. The quotient $\Mbargnmh/\hMCG(\Xgn)$ is canonically identified with $\Mbargnh$, and under this identification, the quotient map $\Mbargnmh\to\Mbargnh$ coincides with the map that forgets the marking.
\end{prop}

\begin{ex}\label{ex:V115}
    The map $h\mathcal{T}(\X_{1,1})\to\mathcal{MH}_{1,1}$ is the quotient map by the \emph{trivial} action of $$\MCG(\X_{1,1})/\Tw(\X_{1,1})=\hMCG(\X_{1,1})\cong\Z/2\Z.$$ It is therefore a degree-2 covering map of orbifolds, though it is a homeomorphism of underlying topological spaces.
\end{ex}
\begin{rem}
    The cases $A_{0,n}\cong\{1\}$ (Remark \ref{rem:GenusZero}) and $A_{1,1}\cong\Z/2\Z$ (Example \ref{ex:V115}) are the only choices of $(g,n)$ for which $A_{g,n}\cong\hMCG(\Xgn)$ is finite. That is, in all other cases, the map $\Mbargnmh\to\Mbargnh$ is infinite-to-one.
\end{rem}


\section{The boundary complex of \texorpdfstring{$\Mbargnmh$}{hT(Vgn)}}\label{sec:MgmhbarBoundary}
In Proposition \ref{prop:MarkedBijection}, and specifically Remark \ref{rem:TopologyOfMgmh}, we noted that the boundary complex of $\Mbargnmh$ is canonically isomorphic to $\D(\Xgn)/\Tw(\Xgn)$. In this section, we will show (Theorem \ref{thm:QuotientOfDiskComplex}) that $\D(\Xgn)/\Tw(\Xgn)$ is isomorphic to $\CV_{g,n}^*,$ the simplicial completion of Culler-Vogtmann  space. (See Section \ref{sec:OuterSpaceBackground}.) The isomorphism will be canonical after choosing a $n$-pointed homotopy equivalence $R_{g,n}\to\Xgn$.

For the remainder of this section, we fix an $n$-pointed homotopy equivalence $$\rho:R_{g,n}\to\Xgn.$$ Let $\underline{\rho}:\Xgn\to R_{g,n}$ be an $n$-pointed homotopy inverse. 

We define a map $J_3:\D(\Xgn)\to\CV_{g,n}^*$ as follows. A point in $\D(V_{g,n})$ is a pair $\Delta=(\{\delta_i\},\{\ell_i\})$, where $\{\delta_i\}$ is a multidisk, with barycentric coordinates $\{\ell_i\}$ that sum to 1. Choose arbitrarily a pure multidisk $\Delta'\supseteq\Delta.$ We define \begin{align}\label{eq:J3Def}
    J_3(\Delta)=(\tau_{\Delta'},\dgm_{\Xgn,\Delta'}\circ\rho)\in\CV_{g,n}^*,
\end{align}
where the edge of $\tau_{\Delta'}$ corresponding to a disk $\delta_i\in\Delta$ is assigned length $\ell_i$, and all other edges (corresponding to disks in $\Delta'\setminus\Delta$) are assigned length $0$. Note that because $\Delta'$ is a pure multidisk, the dual graph is $\tau_{\Delta'}$ is not weighted (i.e. all vertex weights are zero), as required for an element of $\CV_{g,n}^*$.

\begin{prop}\label{prop:J3WellDefined}
    $J_3$ is well-defined, i.e. the point $(\tau_{\Delta'},\dgm_{\Xgn,\Delta'}\circ\rho)\in\CV_{g,n}^*$ is independent of choice of $\Delta'\supseteq\Delta$.
\end{prop}
\begin{proof}
    Let $\Delta',\Delta''$ be two pure multidisks containing $\Delta,$ with barycentric coordinates extending those of $\Delta$. We cut $\X$ along $\Delta$, and contract each ``boundary patch'' obtained this way to a single point, which we treat as a labeled point -- the result is a disjoint union of pointed handlebodies $\{\X^v\},$ indexed by vertices $v$ of $\tau_\Delta$. The multidisk $\Delta'$ defines a pure multidisk $\Delta'_v$ in each $\X^v,$ and similarly $\Delta''$ defines a pure multidisk $\Delta''_v$ in each $\X^v$.

    For each vertex $v$ of $\tau_\Delta$, $\Delta'_v$ and $\Delta''_v$ correspond to (open) simplices of $\D^{\pure}(\X^v)$. By Proposition \ref{prop:SimpleDisksContractible}, $\D^{\pure}(\X^v)$ is contractible, hence in particular it is connected. Thus there is a finite sequence of pure multidisks $\Delta'_v=\Delta_{v,1},\ldots,\Delta_{v,m}=\Delta''_v$, where $\Delta_{v,j}$ is obtained from $\Delta_{v,j-1}$ by either adding or deleting disks --- we may assume without loss of generality that $\Delta_{v,j}$ is obtained from $\Delta_{v,j-1}$ by adding or deleting a \emph{single} disk. Combining these sequences over all vertices $v$ of $\tau_\Delta$ gives a finite sequence $\Delta'=\Delta_1,\Delta_2,\ldots,\Delta_M=\Delta''$ of pure multidisks containing $\Delta$, where $\Delta_j$ is obtained from $\Delta_{j-1}$ by either adding or deleting a disk (not in $\Delta$).

    The marked dual graphs of $\Delta_j$ and of $\Delta_{j-1}$ are therefore related by the contraction, in the sense of Section \ref{sec:OuterSpaceBackground}, of a length-zero non-loop edge. These two marked graphs are therefore in the same equivalence class in the definition of $\CV_{g,n}^*$ (Section \ref{sec:OuterSpaceBackground}), i.e. they define the same point in $\CV_{g,n}^*.$ Applying this argument to each step in the sequence $\Delta'=\Delta_1,\Delta_2,\ldots,\Delta_M=\Delta''$, we conclude that the marked dual graphs of $\Delta'$ and of $\Delta''$ define the same point in $\CV_{g,n}^*.$ Thus $J_3$ is well-defined.
\end{proof}

The following properties are immediate:
\begin{itemize}
    \item $J_3$ is a \textbf{simplicial} map. 
    \item $J_3$ sends each simplex of $\D(\Xgn)$ isomorphically to a simplex of $\CV_{g,n}^*.$
    \item $J_3$ is compatible with the maps $\kappa_1:\D(\Xgn)\to\Link\M_{g,n}^{\trop}$ and $\kappa_2:\CV_{g,n}^{*}\to\Link\M_{g,n}^{\trop}$ described in Section \ref{sec:ModuliOfGraphs}, i.e. the following diagram commutes:
    \begin{align*}
        \begin{tikzcd}[ampersand replacement = \&]
            \D(\Xgn)\arrow[r,"J_3"]\arrow[dr,"\kappa_1"]\&\CV_{g,n}^{*}\arrow[d,"\kappa_2"]\\
            \&\Link\M_{g,n}^{\trop}
        \end{tikzcd}
    \end{align*}
    %\item \textbf{$J_3$ is compatible with the quotient maps $\D(\Xgn)\to\Link\M_{g,n}^{\trop}$ and $\CV_{g,n}^{*}\to\Link\M_{g,n}^{\trop}$:} Denote by $\kappa_1$ the map from $\D(\Xgn)$ to $\Link\M_{g,n}^{\trop}$, and denote by $\kappa_2$ the map from $\CV_{g,n}^{*}$ to $\Link\M_{g,n}^{\trop}$, as described in Section \ref{sec:ModuliOfGraphs}. Then it is clear from the definition of $J_3$ that $\kappa_1=\kappa_2\circ J_3$. 
    \item $J_3$ restricts to a map $\D^{\pure}(\Xgn)\to\CV_{g,n}$.
\end{itemize}





 \begin{thm}\label{thm:QuotientOfDiskComplex}
    $J_3$ is $\Tw(\Xgn)$-invariant, and descends to an isomorphism $$\bar{J}_3:\D(\Xgn)/\Tw(\Xgn)\to\CV_{g,n}^*.$$ 
\end{thm}

For the purposes of the proof, we first introduce a convenient alternate interpretation of $\CV_{g,n}^*.$ Observe that having fixed the above homotopy equivalence $\rho:R_{g,n}\to\Xgn,$ any marked graph $(\tau,r)$ (i.e. a graph together with a homotopy equivalence from $R_{g,n}$) can be converted into an ``$\Xgn$-marked graph'' $(\tau,r\circ\underline{\rho})$ (i.e. a graph together with a homotopy equivalence from $\Xgn$), and similarly any $\Xgn$-marked graph may be converted into a marked graph. Therefore, we may identify $\CV_{g,n}^*$ with the space of equivalence classes of $\Xgn$-marked stable genus-$g$ $n$-leafed metric graphs, where the equivalence relation is identical to that in Section \ref{sec:OuterSpaceBackground}. Under this identification, the definition \eqref{eq:J3Def} of $J_3$ becomes simply: $$J_3(\Delta)=(\tau_{\Delta'},\dgm_{\Xgn,\Delta'})\in\CV_{g,n}^*,$$ where $\Delta'$ is chosen as above.

Under the original interpretation, $\CV_{g,n}^*$ had a natural right action by $A_{g,n}$ by precomposing the marking with a homotopy equivalence $R_{g,n}\to R_{g,n}$, as described in Section \ref{sec:OuterSpaceBackground}. Under the new interpretation, we acquire a natural right $\hMCG(\Xgn)$-action on $\CV_{g,n}^*$ by precomposing the $\Xgn$-marking by a homotopy equivalence $\Xgn\to\Xgn.$ The two interpretations, together with their respective natural actions, are compatible via the isomorphism $A_{g,n}\xrightarrow{\cong}\hMCG(\Xgn)$ that is conjugation (up to homotopy) by $\rho$.
\begin{proof}[Proof of Theorem \ref{thm:QuotientOfDiskComplex}]








    \medskip\noindent\textbf{$J_3$ is equivariant.} We have two natural right actions: of $\MCG(\Xgn)$ on $\D(\Xgn)$ and of $\hMCG(\Xgn)$ on $\CV_{g,n}^*$. As in Section \ref{sec:MappingClassGroups}, there is a natural map $\MCG(\Xgn)\to\hMCG(\Xgn)$. In what follows, for $h\in\MCG(\Xgn),$ we denote by $\bar{h}$ the image in $\hMCG$. We claim that the following diagram is equivariant:
   \begin{align*}
       \begin{tikzcd}[ampersand replacement = \&,column sep=0pt,row sep=25pt]
           \D(\Xgn)\arrow[d,"J_3"]\&\circlearrowleft\&\MCG(\Xgn)\arrow[d]\\
            \CV_{g,n}^*\&\circlearrowleft\&\hMCG(\Xgn)
       \end{tikzcd}
   \end{align*}
   In other words, we claim that given $\Delta\in\D(\Xgn)$ and $h\in\MCG(\Xgn)$, we have $$J_3(\Delta\cdot h)=J_3(\Delta)\cdot \overline{h}.$$ By continuity, and by the density of $\D^{\pure}(\Xgn)$ it suffices to prove the claim for $\Delta\in\D^{\pure}(\Xgn)$, so in what follows, we assume that $\Delta\in\D^{\pure}(\Xgn)$ and that $h\in\MCG(\Xgn)$. Then
    \begin{align*}
        J_3(\Delta\cdot h)&=(\tau_{\Delta\cdot h}, \dgm_{\Xgn,\Delta\cdot h})\\
        &=(\tau_{h^{-1}(\Delta)}, \dgm_{\Xgn,h^{-1}(\Delta)}),
    \end{align*}
    where the second equality is by definition of the $\MCG(\Xgn)$-action on $\D(\Xgn)$, see Section \ref{sec:DiskComplex}.

On the other hand 
    \begin{align*}
        J_3(\Delta)\cdot \overline{h}&=(\tau_{\Delta}, \dgm_{\Xgn,\Delta})\cdot\overline{h}\\
        &=(\tau_{\Delta}, \dgm_{\Xgn,\Delta}\circ\overline{h})\\
        &=(\tau_{\Delta}, \dgm_{\Xgn,\Delta}\circ h).
    \end{align*}

Now, observe that $h$ induces an $n$-pointed, edge-length-preserving graph isomorphism $$h_\tau:\tau_{\Xgn, h^{-1}(\Delta)}\to \tau_{\Xgn, \Delta}$$ such that the following square commutes (up to $n$-pointed homotopy):
\begin{align*}
    \begin{tikzcd}[ampersand replacement = \&]
        \Xgn\arrow[r,"h"]\arrow[d,"\dgm_{\Xgn,h^{-1}(\Delta)}",swap]\&\Xgn\arrow[d,"\dgm_{\Xgn,\Delta}"]\\
        \tau_{h^{-1}(\Delta)}\arrow[r,"h_\tau"]\&\tau_\Delta
    \end{tikzcd}
\end{align*}
(In fact, it is easy to choose representatives of the homotopy classes $\dgm_{\Xgn,h^{-1}(\Delta)}$, $h_\tau$, and $\dgm_{\Xgn,\Delta}$ so that the diagram actually commutes, not just up to homotopy.) By definition, $(\tau_{h^{-1}(\Delta)}, \dgm_{\Xgn,h^{-1}(\Delta)})$ and $(\tau_{\Delta}, \dgm_{\Xgn,\Delta}\circ h)$ represent the same point in $\CV_{g,n}$, proving the claim. 






    \medskip\noindent\textbf{$J_3$ descends to $\D(\Xgn)/\Tw(\Xgn)$.} Since $J_3$ is equivariant as above, and $\Tw(\Xgn)$ is the kernel of the map $\MCG(\Xgn)\to\hMCG(\Xgn)$ by Theorem \ref{thm:LuftMarkedPoints}, we have that $J_3$ descends to a map $$\bar{J}_3:\D(\Xgn)/\Tw(\Xgn)\to\CV_{g,n}^*.$$
    Note also that $\D^{\pure}(\Xgn)\subseteq\D(\Xgn)$ is $\Tw(\Xgn)$-invariant, and $J_3$ descends to a map $\D^{\pure}(\Xgn)/\Tw(\Xgn)\to\CV_{g,n}.$


     \medskip\noindent\textbf{$\bar{J}_3$ is surjective.} The surjectivity of $J_3$ follows by combining the equivariance established above with the following:
 \begin{itemize}
     \item the quotient maps $\kappa_1:\D(\Xgn)\to\Link(\M_{g,n}^{\trop})$ and $\kappa_2\to\Link(\M_{g,n}^{\trop})$ are surjective, 
     \item $\kappa_1=\kappa_2\circ J_3$, and
     \item the homomorphism $\MCG(\Xgn)\to\hMCG(\Xgn)$ is surjective.
 \end{itemize}

In more detail: suppose we have $y\in\CV_{g,n}$. Since $\kappa_1$ is surjective, there exists $x\in\D(\Xgn)$ such that $\kappa_1(x)=\kappa_2(y)\in\Link\M_{g,n}^{\trop}$. Then $\kappa_2(J_3(x))=\kappa_1(x)=\kappa_2(y)$. Since $\kappa_2$ is the quotient map by $\hMCG(\Xgn)$, there exists $f\in\hMCG(\Xgn)$ such that $y=J_3(x)\cdot f$. Since the homomorphism $\MCG(\X_{g,n})\to\hMCG(\Xgn)$ is surjective, we can lift $f$ to $\hat{f}\in \MCG(\Xgn)$. By equivariance of $J_3$, $J_3(x\cdot \hat{f})=J_3(x)\cdot f=y$. We conclude that the image of $J_3$ contains $\CV_{g,n}\subseteq\CV_{g,n}^*$, so by density $J_3$ is surjective. Therefore $\bar{J}_3$ is surjective.



    \medskip

    To prove injectivity of $\bar{J}_3$, we first prove the following lemma:
    \begin{lem}\label{lem:StabilizerSurjectivity}
        Let $\Delta\in\D^{\pure}(\X)$. Then the natural homomorphism $$\Stab_{\MCG(\Xgn)}(\Delta)\to\Stab_{\hMCG(\Xgn)}(J_3(\Delta)),$$ which exists by equivariance of $J_3$, is surjective.
    \end{lem}
    \begin{proof}[Proof of Lemma \ref{lem:StabilizerSurjectivity}]
        Let $f\in\Stab_{\hMCG(\Xgn)}(J_3(\Delta))$. By definition, this means there exists an edge-length-preserving automorphism $\beta:\tau_\Delta\to\tau_\Delta$ such that the diagram commutes up to homotopy:
        \begin{equation}
            \begin{tikzcd}[column sep=40pt]
                \Xgn\arrow[d,"f"]\arrow[r,"\dgm_{\Xgn,\Delta}"]&\tau_{\Delta}\arrow[d,"\beta"]\\
                \Xgn\arrow[r,"\dgm_{\Xgn,\Delta}"]&\tau_\Delta
            \end{tikzcd}
        \end{equation}
        By \cite{CullerVogtmann1986,Hatcher1995}, there is an isomorphism $\Stab_{\hMCG(\Xgn)}(J_3(\Delta))\to\Aut(\tau_\Delta),$ where $\Aut(\tau_\Delta)$ is the group of edge-length-preserving automorphisms of $\tau_\Delta$, that sends $f\mapsto\beta.$ (In particular, $f$ is uniquely determined by $\beta$.)

        We use $\beta$ to construct a homeomorphism $\widehat{f}:\Xgn\to\Xgn$ as follows. Cutting $\Xgn$ along $\Delta$ yields a disjoint union of handlebodies $\X^v$, where $v$ runs over vertices of $\tau_\Delta$, with pairs of boundary ``patches'' corresponding to the edges of $\tau_\Delta.$ The automorphism $\beta:\tau_\Delta\to\tau_\Delta$ sends vertices to vertices and half-edges to half-edges. For each vertex $v$ of $\tau$, choose a homeomorphism $\X^v\to\X^{\beta(v)}$ that sends each boundary patch on $\X^v$ (corresponding to a half-edge $\nu$ incident to $v$) to the boundary patch on $\X^{\beta(v)}$ corresponding to $\beta(\nu).$ After possibly adjusting these homeomorphisms near each boundary patch to ensure they agree on paired patches, we may glue them to obtain a homeomorphism $\widehat{f}:\Xgn\to\Xgn$ that fixes $\Delta$ as a multidisk (with its barycentric coordinates), though it may permute the disks in $\Delta$. That is, $\widehat{f}\in\Stab_{\MCG(\Xgn)}(\Delta).$

        By construction, $\widehat{f}$ induces the graph automorphism $\beta:\tau_\Delta\to\tau_\Delta,$ hence maps to $f$ under the map $\MCG(\Xgn)\to\hMCG(\Xgn)$ since $f\in\Stab_{\hMCG(\Xgn)}(J_3(\Delta))$ is the unique element that induces $\beta$, as above. This proves the lemma.
    \end{proof}


\noindent\textbf{$\bar{J}_3$ is injective on the pure locus.}
    Let $\Delta_1,\Delta_2\in\D^{\pure}(\Xgn)$, such that $J_3(\Delta_1)=J_3(\Delta_2).$ Then in particular, $\kappa_1(\Delta_1)=\kappa_1(\Delta_2)$, and so there exists $h\in\MCG(\Xgn)$ such that $\Delta_2=\Delta_1\cdot h$. Let $\bar h\in\hMCG(\Xgn)$ denote the image of $h$ under the natural map $\MCG(\Xgn)\to\hMCG(\Xgn)$. Since $J_3$ is equivariant and $J_3(\Delta_1)=J_3(\Delta_2),$ we have $J_3(\Delta_1)= J_3(\Delta_2)=J_3(\Delta_1)\cdot \bar{h}$, in other words, $\bar{h}\in\Stab_{\hMCG(\Xgn)}(J_3(\Delta_1))$. By Lemma \ref{lem:StabilizerSurjectivity}, we may lift $\bar h$ to an element $h' \in\Stab_{\MCG(\Xgn)}(\Delta_1)$. Since $h$ and $h'$ have the same image in $\hMCG(\Xgn)$, $(h')^{-1}\cdot h$ is in the kernel of the homomorphism $\MCG(\Xgn)\to\hMCG(\Xgn)$, i.e. $(h')^{-1}\cdot h\in\Tw(\Xgn)$. Now, observe that
    $$\Delta_1\cdot ((h')^{-1}\cdot h)=(\Delta_1\cdot (h')^{-1})\cdot h=\Delta_1\cdot h=\Delta_2.$$

    Given two elements of $\D^{\pure}(\Xgn)$ with the same image under $J_3$, we have produced an element of $\Tw(\Xgn)$ that takes one to the other. This shows that the restriction $$\left.\bar{J_3}\right|_{\D^{\pure}(\Xgn)/\Tw(\Xgn)}:\D^{\pure}(\Xgn)/\Tw(\Xgn)\to\CV_{g,n}$$ is injective.

In order to show that $\bar{J}_3$ is injective on all of $\D(\Xgn)/\Tw(\Xgn)$, we require the following lemma:

\begin{lem}\label{lem:StrongSurjectivity}
    Let $\Sigma$ be an open simplex in $\D(\Xgn),$ and let $\Lambda$ be an open simplex of $\CV_{g,n}$ whose closure in $\CV_{g,n}^*$ contains $J_3(\Sigma).$ Then there exists an open simplex $\widehat\Lambda$ in $\D^{\pure}(\Xgn)$ such that $J_3(\widehat\Lambda)=\Lambda$ and such that $\Sigma$ is contained in the closure of $\widehat\Lambda.$
\end{lem}
\begin{proof}
Let $\Sigma$ be an open simplex in $\D(\Xgn),$ with corresponding multidisk $\Delta$ in $\Xgn.$ Let $\Lambda$ be an open simplex of $\CV_{g,n}$ whose closure in $\CV_{g,n}^*$ contains $J_3(\Sigma),$ and let $(\tau,r)$ be the $\Xgn$-marked graph corresponding to $\Lambda,$ where $r:\Xgn\to\tau$ is a homotopy equivalence. Since $J_3(\Sigma)$ is a face of $\Lambda,$ and the barycentric coordinates on $\Lambda$ are in canonical bijection with the edges of $\tau$, we may decompose the edges of $\tau$ as $$E(\tau)=E_\Delta\sqcup E',$$ where $E_\Delta$ is the set of edges whose barycentric coordinates along $J_3(\Sigma)$ are nonzero, and $E'$ is the set of edges whose barycentric coordinates along $J_3(\Sigma)$ are zero.

Cutting $\Xgn$ along $\Delta$ and contracting boundary patches, as in the proof of Proposition \ref{prop:J3WellDefined}, yields pointed handlebodies $\{\X^v\}$ indexed by the vertices of $\tau_\Delta$. For each disk $\delta\in\Delta$, we have two corresponding paired labeled points $x_\delta,x_\delta^*$, each in one of the $\X^v$s. Let $g_v$ be the genus of $\X^v$, and let $n_v$ be the number of labeled points on $\X^v$.

Similarly, let $\tau^v$ be the graphs obtained by cutting $\tau$ along $E_\Delta$. For each edge in $e\in E_\Delta,$ we have two corresponding paired labeled leaves $p_e,p_e^*,$ each in one of the $\tau^v$s.

Let $c:\tau\to\underline{\tau}$ be the map that contracts all of the edges in $E'$. (This need \emph{not} be a homotopy equivalence.) The edges of $\underline{\tau}$ are in canonical bijection with $E_\Delta.$ It follows from the definition of $J_3$ and the equivalence relation on $\CV_{g,n}^*$ that there is an isomorphism $\Phi:\underline{\tau}\to\tau_\Delta$ such that the maps $\Phi\circ c\circ r:\Xgn\to\tau_\Delta$ and $\dgm_{\Xgn,\Delta}:\Xgn\to\tau_\Delta$ are homotopic. Thus after a homotopy, we may assume that the marking $r:\Xgn\to\tau$ restricts to maps $r^v:\X^v\to\tau^v$ sending each ``cut point'' $x_\delta\in\X^v$ to the corresponding ``cut leaf'' of $p_e\in\tau^v$, where $e\in E_\Delta$ is the edge that $\Phi$ identifies with edge of $\tau_\Delta$ corresponding to the disk $\delta$.

By surjectivity of $J_3$ (as applied to the map $\D(\X^v)\to\CV_{g_v,n_v}^*$), there exists a (necessarily pure) multidisk $\Delta_v$ in $\X^v$ such that $(\tau_{\Delta_v},\dgm_{\X^v,\Delta_v})=(\tau^v,r^v)$ as elements of $\CV_{g_v,n_v}^*$. Let $$\Delta'=\Delta\cup\bigcup_{\substack{v\text{ a vertex}\\\text{of $\tau_\Delta$}}}\Delta_v,$$ where we identify $\Delta_v$ with a multidisk in $\Xgn$ in the obvious way. Then $\Delta'$ is a pure multidisk containing $\Delta.$ Thus $\Sigma$ is in the closure of the open simplex $\widehat\Sigma$ of $\D(\Xgn)$ corresponding to $\Delta'$. The marked dual graph $(\tau_{\Delta'},\dgm_{\Xgn,\Delta'})$ is obtained by gluing together all of the marked graphs $(\tau_{\Delta_v},\dgm_{\X^v,\Delta_v})$ via the pairs of labeled leaves corresponding to disks $\delta\in\Delta.$ By construction, the resulting marked graph is the same as the marked graph obtained by gluing together the marked graphs $(\tau^v,r^v)$ along the pairs of labeled leaves $p_e,p_e^*$ corresponding to edges in $E_\Delta,$ which we showed above is equivalent to $(\tau,r)$ in $\CV_{g,n}.$

It follows that if $\widehat\Sigma$ is the open simplex in $\D(\Xgn)$ corresponding to $\Delta'$, then $\Sigma$ is contained in the closure of $\widehat\Sigma$, and $J_3(\widehat\Sigma)=\Lambda$, as desired.
\end{proof}

\noindent\textbf{$\bar{J}_3$ is injective.}
    Finally, suppose $\Delta_1,\Delta_2\in\D(\Xgn)$ such that $J_3(\Delta_1)=J_3(\Delta_2).$ Pick any open simplex $\Lambda$ of $\CV_{g,n}$ whose closure contains $J_3(\Delta_1)=J_3(\Delta_2)$. By Lemma \ref{lem:StrongSurjectivity}, there exist open simplices $\widehat\Lambda_1$ and $\widehat\Lambda_2$ of $\D^{\pure}(\Xgn)$ such that $J_3(\widehat\Lambda_1)=J_3(\widehat\Lambda_2)=\Lambda$, $\Delta_1$ is in the closure of $\widehat\Lambda_1$, and $\Delta_2$ is in the closure of $\widehat\Lambda_2$. Since the restriction $$\left.\bar{J_3}\right|_{\D^{\pure}(\Xgn)/\Tw(\Xgn)}:\D^{\pure}(\Xgn)/\Tw(\Xgn)\to\CV_{g,n}$$ is injective, there exists an element $h\in\Tw(\Xgn)$ such that $\widehat\Lambda_1\cdot h=\widehat\Lambda_2.$ We then have the commutative triangle of isomorphisms of closed simplices:
    \begin{equation}
        \begin{tikzcd}
            \bar{\widehat\Lambda_1}\arrow[r,"h"]\arrow[dr,"J_3"]&\bar{\widehat\Lambda_2}\arrow[d,"J_3"]\\
            &\bar{\Lambda}
        \end{tikzcd}
    \end{equation}
    where bar denotes closure. Since $J_3(\Delta_1)=J_3(\Delta_2),$ we must have $\Delta_1\cdot h=\Delta_2$. This proves that $\bar{J_3}$ is injective.
\end{proof}
Theorem \ref{thm:QuotientOfDiskComplex} and Remark \ref{rem:TopologyOfMgmh} imply:
\begin{cor}\label{cor:MgmhBoundaryComplexCV}
    After choosing a homotopy equivalence $\rho:R_{g,n}\to\Xgn$, the boundary complex of $\Mgnmh\subseteq\Mbargnmh$ is canonically isomorphic to $\CV_{g,n}^*.$ 
\end{cor}

\begin{rem}
    This isomorphism in Corollary \ref{cor:MgmhBoundaryComplexCV}, which is given as a composition $$(\text{boundary complex of $\Mbargnmh$})\cong\D(\Xgn)/\Tw(\Xgn)\cong\CV_{g,n}^*,$$  has a simple description. Let $(Y,C,\iota,\eta)$ be a stable genus-$g$ homotopy-marked complex handlebody. The \emph{marked dual graph} of $(Y,C,\iota,\eta)$ is the marked graph $(\tau_Y,\dgm_Y\circ\eta\circ\rho)$, where $\tau_Y$ is the weighted dual graph of $(Y,C,\iota),$ and $\dgm_Y:Y\to\tau$ is as in Definition \ref{Def:StableComplexHandlebody}. Then the isomorphism in Corollary \ref{cor:MgmhBoundaryComplexCV} sends a stable $n$-pointed genus-$g$ homotopy-marked complex handlebody to its marked dual graph.
\end{rem}


\section{Tropicalization maps \`a la Chan-Galatius-Payne}\label{sec:CGP}
In \cite{ChanGalatiusPayne2019}, the authors define a canonical (up to homotopy) continuous surjection $\lambda_{g,n}:\M_{g,n}\to\M_{g,n}^{\trop}$, as follows. By the Uniformization Theorem, there is a bijection between complex structures and hyperbolic metrics on a given surface, so given $(C,p_1,\ldots,p_n)\in\M_{g,n},$ we may endow it with a unique hyperbolic metric. If $\epsilon>0$ is the Margulis constant for the hyperbolic plane, then simple closed curves of length less than epsilon are all disjoint, so form a multicurve $\Gamma$ (see e.g.  \cite[Cor. 13.7]{FarbMargalit2011}).  If $\len(\gamma_e)$ is the length of the simple closed curve $\gamma\in\Gamma,$ the graph $\lambda_{g,n}(C,p_1,\ldots,p_n)$ is defined to be the dual graph of $\Gamma$, where the length of the edge $e$ corresponding to $\gamma$ is $-\log(\len(\gamma_e)/\epsilon)$.

\begin{rem}
    As noted in \cite[Sec. 3.4]{ramadas2024thurston}, this construction naturally defines an $\MCG(\Sgn)$-equivariant surjection $\tilde\lambda_{g,n}:\T(\Sgn)\to\Cone(\mathcal{C}(\Sgn)),$ where $\Cone(\mathcal{C}(\Sgn))$ denotes the cone over $\mathcal{C}(\Sgn)$, from which the map of \cite{ChanGalatiusPayne2019} is descended.
\end{rem}

We now construct analogous maps $\lambda_{g,n}^{\mathcal{MH}}:\Mgnh\to\M_{g,n}^{\trop}$ and $\lambda_{g,n}^{h\mathcal{T}}:\Mgnmh\to\Cone(\CV_{g,n}^*)$.

\begin{Def}
    Let $\epsilon>0$ be smaller than the Margulis constant. Given $(Y,C,\iota,\sigma)\in\T(\X)$, consider the hyperbolic metric on $C\setminus\{p_1,\ldots,p_n\}$ corresponding to the complex structure. The set of disks in $Y$ whose boundaries have hyperbolic length at most $\epsilon$ is a multidisk $\Delta$, by the Margulis Lemma. We define $\tilde\lambda_{\Xgn}(Y,C,\iota,\sigma)\in\Cone(\D(\Xgn))$ to be the weighted multidisk $\Delta$, with the weight of a disk $\delta\in\Delta$ equal $-\log(\len(\partial\delta)/\epsilon)$, where $\len(\partial\delta)$ is the hyperbolic length of the boundary of $\delta$.
\end{Def}
The proof of the following proposition is similar to the proof of \cite[Prop. 4.1]{HainautPetersen2025}:
\begin{prop}\label{prop:CGPAnalogy}
    The map $\tilde\lambda_{\Xgn}:\T(\Xgn)\to\Cone(\D(\Xgn))$ is continuous, surjective, and $\MCG(\Xgn)$-equivariant. In particular, by Propositions \ref{prop:UnmarkedBijection} and \ref{prop:MarkedBijection}, $\tilde\lambda_{\Xgn}$ descends to continuous, surjective maps $$\lambda_{g,n}^{h\mathcal{T}}:\Mgnmh\to\Cone(\CV_{g,n}^*)$$ and $$\lambda_{g,n}^{\mathcal{MH}}:\Mgnh\to\M_{g,n}^{\trop}.$$
\end{prop}

\section{Complex structures on certain quotients of Teichm\"uller space}
In this section, we construct complex structures on quotients of certain open subsets of $\Tbar(\Sgn)$ by subgroups of $\MCG(\Sgn)$. There is an existing well-known example of such a construction, namely the complex structure on $\Mbar_{g,n}$ via ``plumbing coordinates'' \cite{Marden1987,Masur1976,Wolpert1990}. In order to generalize this construction, we recall the basic setup.

Let $\Gamma$ be a multicurve in $\Sgn$, and let $$U_\Gamma=\bigsqcup_{\Gamma'\subseteq\Gamma}\T_{\Gamma'}(\Sgn)\subseteq\Tbar(\Sgn),$$ where $\T_{\Gamma'}(\Sgn)$ is as in Section \ref{sec:AugmentedTeichmullerSpace}.
Then $U_\Gamma$ is an open subset of $\Tbar(\Sgn)$ containing $\T_\Gamma(\Sgn)$ (but not $\Tbar_\Gamma(\Sgn)$). $\MCG(\Sgn)$ induces maps between open sets $U_\Gamma$ --- specifically, if $h\in\MCG(\Sgn),$ then $h$ induces a homeomorphism $h:U_\Gamma\to U_{\Gamma\cdot h}$ for any $\Gamma.$ 

Let $$\Tw(\Gamma)\subseteq\MCG(\Sgn)$$ denote the subgroup generated by Dehn twists around the simple closed curves in $\Gamma.$ Then $U_\Gamma$ is invariant under the action of $\Tw(\Gamma)$. Let $$Q_\Gamma=U_\Gamma/\Tw(\Gamma)$$ denote the topological quotient space, with quotient map $t_\Gamma:U_\Gamma\to Q_\Gamma$. The action of $\MCG(\Sgn)$ descends to $Q_\Gamma$, since for any $h\in\MCG(\Sgn),$ the above homeomorphism $h:U_\Gamma\to U_{\Gamma\cdot h}$ is equivariant with respect to the $\Tw(\Gamma)$-action on $U_\Gamma$ and the $\Tw(\Gamma\cdot h)$-action on $U_{\Gamma\cdot h}$, hence induces a homeomorphism $$h:Q_\Gamma\to Q_{\Gamma\cdot h}.$$ Observe that if $\Gamma'\subseteq\Gamma$ are two multicurves, then we have an induced map $t_{\Gamma',\Gamma}:Q_{\Gamma'}\to Q_{\Gamma}$ since the composition $$U_{\Gamma'}\into U_{\Gamma}\xrightarrow{t_\Gamma}{}Q_\Gamma$$ is $\Tw(\Gamma')$-invariant. (Note $t_\Gamma=t_{\emptyset,\Gamma}.$) Furthermore, for any $\Gamma,$ the inclusion $\Tw(\Gamma)\into\MCG(\Sgn)$ induces a map $$q_{\Gamma}:Q_\Gamma\to\Mbar_{g,n},$$ which commutes with system of maps $Q_{\Gamma'}\to Q_{\Gamma}$. We have the following, due to Hubbard and Koch:
\begin{thm}[{\cite[Thms. 10.1, 13.1]{HubbardKoch2014}}]\label{thm:HubbardKoch}
For every multicurve $\Gamma$ on $\Sgn$, $Q_\Gamma$ has the natural structure of a complex manifold. With respect to this structure,
\begin{enumerate}
    \item The maps $t_{\Gamma',\Gamma}:Q_{\Gamma'}\to Q_{\Gamma}$ and $q_\Gamma:Q_\Gamma\to\Mbar_{g,n}$ are \'etale maps of complex orbifolds,\label{it:tGammaGammaEtale}
    \item For any multicurve $\Gamma'\subseteq\Gamma,$ the stratum $\T_{\Gamma'}(\Sgn)/\Tw(\Gamma)\subseteq Q_\Gamma$ is a locally closed complex submanifold, and the map $\T_{\Gamma'}(\Sgn)\to\T_{\Gamma'}(\Sgn)/\Tw(\Gamma)$ is a holomorphic covering map, \label{it:QGammaStratumSubmanifold}
    \item As $\Gamma'$ runs over multicurves contained in $\Gamma,$ the submanifolds $\T_{\Gamma'}(\Sgn)/\Tw(\Gamma)\subseteq Q_\Gamma$ meet at simple normal crossings, and\label{it:QGammaStrataSNC}
    \item For any $h\in\MCG(\Sgn),$ the induced maps $h:Q_\Gamma\to Q_{\Gamma\cdot h}$ are biholomorphisms.\label{it:QGammaInducedActionBiholomorphic}
\end{enumerate}
%As $\Gamma$ varies over multicurves on $S$, the images of the maps $q_\Gamma$ give an open cover of $\Mbar_{g,n}.$
\end{thm}
\begin{rem}
    Hubbard and Koch used Theorem \ref{thm:HubbardKoch} to give a natural functorial identification of $\Tbar(\Sgn)/\MCG(\Sgn)$ with the moduli space $\Mbar_{g,n}$ of stable curves.
\end{rem}
We now adapt the construction of the complex structure on $\Mbar_{g,n}$ to a more general setting, as follows. For a point $x\in\Tbar(\Sgn),$ let $\Gamma(x)$ denote the associated contracted multicurve in $\Sgn$.
\begin{lem}\label{lem:ComplexOrbifold}
    Let $G\subseteq\MCG(\Sgn)$ be a subgroup, and define $$U_1(G)=\{x\in\Tbar(\Sgn):\Tw(\Gamma(x))\subseteq G\}\subseteq\Tbar(\Sgn).$$ Then
    \begin{enumerate}
        \item $U_1(G)$ is a $G$-invariant open subset of $\Tbar(\Sgn)$.\label{it:InvariantOpens}
        \item The quotient $U_1(G)/G$ admits the natural structure of a complex orbifold, with respect to which the natural map $U_1(G)/G\to\Mbar_{g,n}$ induced by the inclusion $G\subseteq\MCG(\Sgn)$ is an \'etale morphism of complex orbifolds.\label{it:U1G}
        \item \label{it:IsotropyU1} For $x\in U_1(G)$ with image $\bar{x}\in U_1(G)/G,$ the isotropy group at $\bar{x}$ is canonically isomorphic to $\Stab_G(x)/\Tw(\Gamma(x)).$
        \item \label{it:StratumSuborbifold} If $\Gamma$ is a multicurve with $\Tw(\Gamma)\subseteq G,$ then the image $\T_\Gamma(\Sgn)/G\subseteq U_1(G)/G$ is a locally closed complex suborbifold, and the map $\T_\Gamma(\Sgn)\to\T_\Gamma(\Sgn)/G$ is a holomorphic covering map.
    \end{enumerate}  
\end{lem}
\begin{proof}
    If $x\in\Tbar(\X)$ and $h\in G,$ then $\Tw(\Gamma(x\cdot h))=\Tw(\Gamma(x)\cdot h)=h^{-1}\Tw(\Gamma(x))h,$ which shows that $U_1(G)$ is $G$-invariant. Furthermore we have $$U_1(G)=\bigsqcup_{\Gamma:\Tw(\Gamma)\subseteq G}\T_\Gamma(\Sgn)=\bigcup_{\Gamma:\Tw(\Gamma)\subseteq G}U_\Gamma,$$ so $U_1(G)$ is open. This proves \eqref{it:InvariantOpens}

    We now construct the structure of a complex orbifold on $U_1(G)/G.$ Let $$\pi_G:U_1(G)\to U_1(G)/G$$ denote the quotient map, and for $\Gamma$ such that $\Tw(\Gamma)\subseteq G$, let $\pi_{\Gamma,G}:=\pi_G|_{U_\Gamma}$ denote its restriction to $U_\Gamma$. Let $\beta_G:U_1(G)/G\to\Mbar_{g,n}$ denote the map induced by the inclusion $G\into\MCG(\Sgn)$. Let $P\in U_1(G)/G$ and let $\underline{P}=\beta_G(P).$ Fix a lift $\widetilde{P}\in U_1(G)$ with $\pi_G(\widetilde{P})=P.$ Then $$\widetilde{P}\in U_{\Gamma(\widetilde{P})}\subseteq U_1(G).$$ Let $\widehat P=t_{\Gamma(\widetilde{P})}(\widetilde{P}).$ That is, we have the diagram:
    $$\begin{tikzcd}[column sep=50pt]
        \widetilde{P}\arrow[r,|->]\arrow[d,phantom,sloped,"\in"]&\widehat{P}\arrow[r,|->]\arrow[d,phantom,sloped,"\in"]&P\arrow[r,|->]\arrow[d,phantom,sloped,"\in"]&\underline{P}\arrow[d,phantom,sloped,"\in"]\\
        U_{\Gamma(\widetilde{P})}\arrow[r,"t_{\Gamma(\widetilde{P})}"]\arrow[rr,bend right,"\pi_{\Gamma(\widetilde{P}),G}",swap]&Q_{\Gamma(\widetilde{P})}\arrow[r,"q_{\Gamma(\widetilde{P}),G}"]\arrow[rr,bend right,swap,"q_{\Gamma(\widetilde{P})}",crossing over]&U_1(G)/G\arrow[r,"\beta_G"]&\Mbar_{g,n}
    \end{tikzcd}$$

    Let $\Isot(\underline{P})$ denote the (finite) automorphism group of the stable curve $\underline{P}.$ (This is precisely the isotropy group of the point $\underline{P}\in\Mbar_{g,n}$.) By Lemma \ref{lem:StabilizerOfPointInTbarExactSequence}, we have $$\Isot(\underline{P})\cong\frac{\Stab_{\MCG(\Sgn)}(\widetilde{P})}{\Tw(\Gamma(\widetilde{P}))}.$$

    By Theorem \ref{thm:HubbardKoch}(1), the map $q_{\Gamma(\widetilde{P})}:Q_{\Gamma(\widetilde{P})}\to\Mbar_{g,n}$ is an \'etale morphism from a complex manifold to a complex orbifold. Thus there exists a neighborhood $W(P,\widetilde{P})\subseteq Q_{\Gamma(\widetilde{P})}$ of $\widehat P$, together with an $\Isot(\underline{P})$-action on $W(P,\widetilde{P})$ by biholomorphisms fixing $\widehat P$, such that the restriction $$q_{\Gamma(\widetilde{P})}|_{W(P,\widetilde{P})}:W(P,\widetilde{P})\to\Mbar_{g,n}$$ is the quotient map by $\Isot(\underline{P})$, followed by the inclusion of an open set. 

    Since the factorization $$q_{\Gamma(\widetilde{P})}=\beta_G\circ q_{\Gamma(\widetilde{P}),G}$$ is induced by the inclusions of groups $$\Tw(\Gamma(\widetilde{P}))\subseteq G\subseteq\MCG(\Sgn),$$ the restriction $$q_{\Gamma(\widetilde{P}),G}|_{W(P,\widetilde{P})}:Q_{\Gamma(\widetilde{P})}\to U_1(G)/G$$ is simply the quotient map by the subgroup
    \begin{align}\label{eq:IsotropyGroupAtP}
        \Isot(P):=\frac{\Stab_G(\widetilde{P})}{\Tw(\Gamma(\widetilde{P}))}\subseteq\frac{\Stab_{\MCG(\Sgn)}(\widetilde{P})}{\Tw(\Gamma(\widetilde{P}))},
    \end{align} again followed by the inclusion of an open set. ($\Isot(P)$ is finite by Lemma \ref{lem:StabilizerOfPointInTbarExactSequence} and the fact that $\Stab_G(x)\subseteq\Stab_{\MCG(\Sgn)}(x)$.) This defines the structure of a complex orbifold on a neighborhood $W(P,\widetilde{P})/\Isot(P)$ of $P\in U_1(G)/G$. This construction works for any $P\in U_1(G)/G$, giving an open cover by complex orbifolds. 

    It still remains to check that the complex structures on the above open cover are locally compatible, but we observe now that once this is completed, part \eqref{it:IsotropyU1} of the Theorem will be immediate from Equation \eqref{eq:IsotropyGroupAtP}, and part \eqref{it:StratumSuborbifold} will be immediate from Theorem \ref{thm:HubbardKoch}\eqref{it:QGammaStratumSubmanifold}.

    We now check that the complex structures on the open cover are locally compatible. Let $$W(P_1,\widetilde{P}_1)/\Isot(P_1)\hspace{1in}\text{and}\hspace{1in}W(P_2,\widetilde{P}_2)/\Isot(P_2)$$ be two open sets of the above form, with $W(P_1,\widetilde{P}_1)\subseteq Q_{\Gamma(\widetilde{P}_1)}$ and $W(P_2,\widetilde{P}_2)\subseteq Q_{\Gamma(\widetilde{P}_2)}$. 
    % Recall that an orbifold transition function $W(P_1,\widetilde{P}_1)/\Isot(P_1)\to W(P_2,\widetilde{P}_2)/\Isot(P_2)$ is, by definition, the data of a finite group $H$ with homomorphisms $H\to\Isot(P_1)$ and $H\to\Isot(P_2)$, together with a diagram of equivariant morphisms
    % $$\begin{tikzcd}
    %     H\arrow[r,phantom, "\circlearrowright"]&[-15pt]\widetilde W(P_1,\widetilde{P}_1)\arrow[r,"\cong"]\arrow[d]&[20pt]\widetilde W(P_2,\widetilde{P}_2)\arrow[d]&[-15pt]H\arrow[l,phantom, "\circlearrowleft"]\\
    %     \Isot(P_1)\arrow[r,phantom, "\circlearrowright"]&W(P_1,\widetilde{P}_1)&W(P_2,\widetilde{P}_2)&\Isot(P_2)\arrow[l,phantom, "\circlearrowleft"]
    % \end{tikzcd}$$
    % where $H$ acts freely by biholomorphisms on $\widetilde W(P_1,\widetilde{P}_1)$ and $\widetilde W(P_2,\widetilde{P}_2)$.

    Let $$P^0\in W(P_1,\widetilde{P}_1)/\Isot(P_1)\cap W(P_2,\widetilde{P}_2)/\Isot(P_2).$$ Choose lifts 
    $$\begin{tikzcd}[row sep=10pt]
        \widetilde{P}^0_1\arrow[r,|->]\arrow[d,phantom,sloped,"\in"]&\widehat{P}^0_1\arrow[r,|->]\arrow[d,phantom,sloped,"\in"]&P^0\arrow[d,phantom,sloped,"\in"]\\
        U_{\Gamma(\widetilde{P}_1)}\arrow[r]&Q_{\Gamma(\widetilde{P}_1)}\arrow[r]&U_1(G)/G
    \end{tikzcd}$$
    and 
    $$\begin{tikzcd}[row sep=10pt]
        \widetilde{P}^0_2\arrow[r,|->]\arrow[d,phantom,sloped,"\in"]&\widehat{P}^0_2\arrow[r,|->]\arrow[d,phantom,sloped,"\in"]&P^0\arrow[d,phantom,sloped,"\in"]\\
        U_{\Gamma(\widetilde{P}_2)}\arrow[r]&Q_{\Gamma(\widetilde{P}_2)}\arrow[r]&U_1(G)/G
    \end{tikzcd}$$
    with $\widehat{P}^0_1\in W(P_1,\widetilde{P}_1)$ and $\widehat{P}^0_2\in W(P_2,\widetilde{P}_2)$. In order to show that the complex structures $$W(P_1,\widetilde{P}_1)/\Isot(P_1)\into U_1(G)/G\hspace{.5in}\text{and}\hspace{.5in}W(P_2,\widetilde{P}_2)/\Isot(P_2)\into U_1(G)/G$$ are locally compatible at $P^0,$ we must construct a biholomorphism from a neighborhood of $\widehat{P}^0_1\in W(P_1,\widetilde{P}_1)$ to a neighborhood of $\widehat{P}^0_2\in W(P_2,\widetilde{P}_2)$ that is equivariant with respect to the action of $\Stab_{\Isot(P_1)}(\widehat{P}^0_1)\cong\Isot(P^0)$ on $W(P_1,\widetilde{P}_1)$ and the action of $\Stab_{\Isot(P_2)}(\widehat{P}^0_2)\cong\Isot(P^0)$ on $W(P_2,\widetilde{P}_2)$.


    Since $\widetilde{P}^0_1$ and $\widetilde{P}^0_2$ both map to $P^0\in U_1(G)/G$, there exists an element $h\in G$ such that $\widetilde{P}^0_1\cdot h=\widetilde{P}^0_2$. By Theorem \ref{thm:HubbardKoch}(4), $h$ induces a biholomorphism $h_Q:Q_{\Gamma(\widetilde{P}^0_1)}\to Q_{\Gamma(\widetilde{P}^0_2)}.$ We therefore have a diagram $$\begin{tikzcd}
        U_{\Gamma(\widetilde{P}_1)}\arrow[ddd]&&&&U_{\Gamma(\widetilde{P}_2)}\arrow[ddd]\\
        &U_{\Gamma(\widetilde{P}^0_1)}\arrow[ul,hook']\arrow[rr,"\text{action of }h","\cong"']\arrow[d,"t_{\Gamma(\widetilde{P}^0_1)}"']&&U_{\Gamma(\widetilde{P}^0_2)}\arrow[ur,hook]\arrow[d,"t_{\Gamma(\widetilde{P}^0_2)}"]&\\
        &Q_{\Gamma(\widetilde{P}^0_1)}\arrow[rr,"h_Q","\cong"']\arrow[dl,"\text{\'et}"',"t_{\Gamma(\widetilde{P}^0_1),\Gamma(\widetilde{P}_1)}"]&&Q_{\Gamma(\widetilde{P}^0_2)}\arrow[dr,"\text{\'et}","t_{\Gamma(\widetilde{P}^0_2),\Gamma(\widetilde{P}_2)}"']&\\
        Q_{\Gamma(\widetilde{P}_1)}&&&&Q_{\Gamma(\widetilde{P}_2)}\\
        W(P_1,\widetilde{P}_1)\arrow[u,hook]\arrow[d]&&&&W(P_2,\widetilde{P}_2)\arrow[u,hook]\arrow[d]\\
        W(P_1,\widetilde{P}_1)/\Isot(P_1)\arrow[rr,hook]&&U_1(G)/G&&W(P_2,\widetilde{P}_2)/\Isot(P_2)\arrow[ll,hook']
    \end{tikzcd}$$
    By Theorem \ref{thm:HubbardKoch}\eqref{it:tGammaGammaEtale} (applied with $\Gamma'=\emptyset$ and $\Gamma=\Gamma(\widetilde{P}^0_1)$), $t_{\Gamma(\widetilde{P}^0_1)}$ is \'etale, so there exists an open set $\widetilde W^0_1\subseteq Q_{\Gamma(\widetilde{P}^0_1)}$ containing $t_{\Gamma(\widetilde{P}^0_1)}(\widetilde{P}^0_1)$ such that the restriction $t_{\Gamma(\widetilde{P}^0_1),\Gamma(\widetilde{P}_1)}|_{\widetilde W^0_1}$ is a biholomorphism onto a $\Stab_{\Isot(P_1)}(\widehat{P}^0_1)$-invariant neighborhood $W^0_1$ of $\widehat{P}^0_1$ in $W(P_1,\widetilde{P}_1)$. Similarly, there is an open set $\widetilde W^0_2\subseteq Q_{\Gamma(\widetilde{P}^0_2)}$ containing $t_{\Gamma(\widetilde{P}^0_2)}$ such that the restriction $t_{\Gamma(\widetilde{P}^0_2),\Gamma(\widetilde{P}_2)}|_{\widetilde W^0_2}$ is a biholomorphism onto a $\Stab_{\Isot(P_2)}(\widehat{P}^0_2)$-invariant neighborhood $W^0_2$ of $\widehat{P}^0_2$ in $W(P_2,\widetilde{P}_2)$. The orbifold transition function is the composition (after possibly shrinking $W^0_1$ and $W^0_2$ further so that $h$ lands in $\widetilde W^0_2$ and is surjective): $$W^0_1\xrightarrow{(t_{\Gamma(\widetilde{P}^0_1),\Gamma(\widetilde{P}_1)}|_{\widetilde W^0_1})^{-1}}{} \widetilde W^0_1\xrightarrow[\cong]{\quad h_Q\quad} \widetilde W^0_2\xrightarrow{t_{\Gamma(\widetilde{P}^0_1),\Gamma(\widetilde{P}_1)}|_{\widetilde W^0_2}}{} W^0_2,$$ which is a biholomorphism by construction.

    It remains to show that this biholomorphism is equivariant with respect to the action of $\Stab_{\Isot(P_1)}(\widehat{P}^0_1)\cong\Isot(P^0)$ on $W^0_1$ and the action of $\Stab_{\Isot(P_2)}(\widehat{P}^0_2)\cong\Isot(P^0)$ on $W^0_2.$ The identifications $$\Isot(P_1)\cong\frac{\Stab_G(\widetilde{P}_1)}{\Tw(\Gamma(\widetilde{P}_1))}\hspace{.5in}\text{and}\hspace{.5in}\Isot(P^0)\cong\frac{\Stab_G(\widetilde{P}^0_1)}{\Tw(\Gamma(\widetilde{P}^0_1))}$$ show that the action of $\Stab_{\Isot(P_1)}(\widehat{P}^0_1)$ on $W^0_1$ descends from the natural action of $\frac{\Stab_G(\widetilde{P}^0_1)}{\Tw(\Gamma(\widetilde{P}^0_1))}$ on $Q_{\Gamma(\widetilde{P}^0_1)}$, and similarly the action of $\Stab_{\Isot(P_2)}(\widehat{P}^0_2)$ on $W^0_2$ descends from the natural action of $\frac{\Stab_G(\widetilde{P}^0_2)}{\Tw(\Gamma(\widetilde{P}^0_2))}$ on $Q_{\Gamma(\widetilde{P}^0_2)}$. Equivariance of the orbifold transition function therefore follows from the equalities $$\Tw(\Gamma(\widetilde{P}^0_2))=\Tw(\Gamma(\widetilde{P}^0_1)\cdot h)=h^{-1}\Tw(\Gamma(\widetilde{P}^0_1))h$$
    and $$\Stab_G(\widetilde{P}^0_2)=\Stab(\widetilde{P}^0_1\cdot h)=h^{-1}\Stab(\widetilde{P}^0_1)h.$$

    We have shown that the local complex orbifold structures $W(P,\widetilde{P})/\Isot(P)\into U_1(G)/G$ are locally compatible, so they patch together, giving a global complex orbifold structure on $U_1(G)/G.$ The map $U_1(G)/G\to\Mbar_{g,n}$ is an \'etale morphism of complex orbifolds by construction. This proves \eqref{it:U1G}.
    % In the above argument, in endowing $U_1(G)/G$ with the structure of a complex orbifold, the isotropy group associated to a point $P\in U_1(G)/G$ is the finite group $\frac{\Stab_G(\widetilde{P})}{\Tw(\Gamma(\widetilde{P}))}$. If $P\in U_2(G)/G\subseteq U_1(G)/G,$ then this group is trivial by definition (for any lift $\widetilde{P}\in U_2(G)$). Thus $U_2(G)/G$ is a complex manifold. This proves \eqref{it:U2G}.
\end{proof}

\section{Complex structures on \texorpdfstring{$\Mbargnh$}{MHgn} and \texorpdfstring{$\Mbargnmh$}{hT(Vgn)}}\label{sec:ComplexStructures}
In Sections \ref{sec:Mghbar} and \ref{sec:Mgmhbar}, we endowed $\Mbargnh$ and $\Mbargnmh$ with topologies, inherited from the topology of $\Tbar(\Sgn)$. In this section, we apply Lemma \ref{lem:ComplexOrbifold} to endow them with complex structures.

\begin{thm}\label{thm:MarkedHandlebodiesComplexManifold}
    $\Mbargnmh$ has the natural structure of a complex manifold. With respect to this structure,
    \begin{enumerate}
    \item Each boundary stratum $\Mbargnmh_{(\tau,r)}\subseteq\Mbargnmh$ is a complex submanifold, and the restriction of the map $\Tbar(\Xgn)\to\Mbargnmh$ to any locally closed stratum is a holomorphic covering map over a stratum of $\Mbargnmh$,\label{it:MgmhStrataSuborbifolds}
    \item The submanifolds $\Mbargnmh_{(\tau,r)}$ meet at simple normal crossings,\label{it:SNCStrata}
    \item The natural map $\Mbargnmh\to\Mbar_{g,n}$ is an \'etale morphism of complex orbifolds.\label{it:MgmhMgEtale}
    \item The $\MCG(\Xgn)$-action on $\Tbar(\Xgn)$ induces an $\hMCG(\Xgn)$-action on $\Mbargnmh$ by biholomorphisms, with finite stabilizer groups.\label{it:OutFgActionBiholomorphisms}
    \end{enumerate}
\end{thm}


We have an analogous theorem for $\Mbargnh$, with a few key differences.


\begin{thm}\label{thm:UnmarkedHandlebodiesComplexOrbifold}
    $\Mbargnh$ has the natural structure of a complex orbifold. With respect to this structure,
    \begin{enumerate}
    \item Each stratum $\overline{\mathcal{MH}}_\tau$ is a complex suborbifold, and the strata meet at normal crossings,
    \item The natural map $\Mbargnmh\to\Mbargnh$ is a holomorphic orbifold covering map, and \label{it:MgmhMghCovering}
    \item The natural map $\Mbargnh\to\Mbar_{g,n}$ is an \'etale morphism of complex orbifolds. \label{it:MghMgEtale}
    \end{enumerate}
\end{thm}

We first prove the following, in order to show that Lemma \ref{lem:ComplexOrbifold} applies to our situation.
\begin{lem}\label{lem:StabilizerIsTwistSubgroup}
    Let $x\in\Tbar(\Xgn)\subseteq\Tbar(\Sgn),$ with contracted multidisk $\Delta$. Then $\Tw(\Delta)=
    \Tw(\Xgn)\cap\Stab_{\MCG(\Sgn)}(x)$.
\end{lem}
\begin{proof}
    Clearly $\Tw(\Delta)\subseteq\Tw(\Xgn)\cap\Stab_{\MCG(\Sgn)}(x).$ Let $h\in\Tw(\Xgn)\cap\Stab_{\MCG(\Sgn)}(x)$.
    Then $h$ induces an automorphism of the $n$-leafed dual graph $\tau_\Gamma\cong\tau_\Delta,$ where $\Gamma=\partial\Delta$.
    %By Lemma \ref{lem:StabilizerOfPointInTbarExactSequence}, $h$ induces a nontrivial automorphism $\bar{h}$ of the stable curve $C$.

    First, we show this automorphism is trivial. Note that $h\in\Stab_{\MCG(\Xgn)}(x)$, and that the map $\Stab_{\MCG(\Xgn)}(x)\to\Aut(\tau_\Delta)$ factors through $\hMCG(\Xgn)$. Since $h\in\Tw(\Xgn),$ it maps to the identity in $\Aut(\tau_\Gamma).$

    Since $h$ acts trivially on $\tau_\Gamma$, $h$ fixes each simple closed curve of $\Gamma$, and each connected component of $\Sgn\setminus\Gamma,$ up to isotopy. Therefore $h$ determines mapping classes $h^1,\ldots,h^k$ on the components $S^1,\ldots,S^k$ of $\Sgn\setminus\Gamma,$ with boundary components each contracted to a labeled point. By definition, we have $h^i\in\Stab_{\MCG(S^i)}(x^i),$ where $x^i$ is the complex structure on $S^i$ induced by $x$. Since the $\MCG(S^i)$-action on $\T(S^i)$ has finite stabilizers, the mapping classes $h^i$ all have finite order.

    Each $h^i$ has a lift $\tilde h^i$ in $\MCG(\Sgn)$ that acts by the identity on $\Sgn\setminus S^i$ and fixes $\Gamma$ pointwise. By construction, $\tilde h^i$ has finite order in $\MCG(\Sgn).$ 

    Note that the mapping classes $\tilde h^i$ all commute with each other so their product $\tilde h^1\cdots\tilde h^k$ has finite order. Also, they satisfy $h^{-1}\cdot(\tilde h^1\cdots\tilde h^k)\in\Tw(\Gamma)$, since this product is, up to isotopy, the identity away from a small neighborhood of $\Gamma$. Since $h^{-1}\cdot(\tilde h^1\cdots \tilde h^k)\in\Tw(\Gamma)\subseteq\Tw(\Xgn)$ and $h\in\Tw(\Xgn),$ we have $\tilde h^1\cdots\tilde h^k\in\Tw(\Xgn)$. But by Proposition \ref{prop:TwistSubgroupTorsionFree}, $\Tw(\Xgn)$ is torsion-free, so we must have $\tilde h^1\cdots \tilde h^k=1.$ It follows that $h\in\Tw(\Gamma)=\Tw(\Delta),$ as desired.
\end{proof}
\begin{proof}[Proof of Theorem \ref{thm:MarkedHandlebodiesComplexManifold}]
We apply Lemma \ref{lem:ComplexOrbifold} with $G=\Tw(\Xgn)$. Then $\Tbar(\Xgn)=\U_1(G)$ by \cite[Thm. 5.6]{Hensel2020}\footnote{Actually we only need $\Tbar(\Xgn)\subseteq\U_1(G)$, which is obvious from the definition of $U_1(G)$}, so Lemma \ref{lem:ComplexOrbifold} endows $\Mbargnmh=\Tbar(\Xgn)/\Tw(\Xgn)$ with the structure of a complex orbifold, satisfying properties \eqref{it:MgmhStrataSuborbifolds} and \eqref{it:MgmhMgEtale}. By Lemma \ref{lem:StabilizerIsTwistSubgroup}, the isotropy groups of this orbifold are all trivial, i.e. $\Mbargnmh$ is actually a complex manifold. Property \eqref{it:SNCStrata} follows from Theorem \ref{thm:HubbardKoch}\eqref{it:QGammaStrataSNC} and the fact that $\CV_{g,n}^*$ is a simplicial complex. Property \eqref{it:OutFgActionBiholomorphisms} follows from Theorem \ref{thm:HubbardKoch}\eqref{it:QGammaInducedActionBiholomorphic}.
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm:UnmarkedHandlebodiesComplexOrbifold}]
This follows from Theorem \ref{thm:MarkedHandlebodiesComplexManifold}, and the fact that the map $\Mbargnmh\to\Mbargnh$ is canonically identified with the quotient map by the properly discontinuous action of $\hMCG(\Xgn)$ on $\Mbargnmh$.
\end{proof}





















\appendix




\section{Characterizations of the simplicial completion of Outer space}\label{app:SimplicialCompletion}
The space $\CV_{g,n}^*$ has at least three different characterizations:
\begin{itemize}
    \item A simplicial complex whose simplices correspond to marked graphs,
    \item A moduli space of marked \emph{metric} graphs, and
    \item The sphere complex of a doubled handlebody.
\end{itemize}
For convenience, in this appendix, we compare show the three characterizations and show their equivalence. 



 \subsection{Closing the open  simplices of \texorpdfstring{$\CV_{g,n}$}{CVgn}} 
In \cite{CullerVogtmann1986} the simplicial completion $\CV_g^*$ of $\CV_g$ is defined as follows.
Let $$\widetilde{\CV}_g^*=\bigsqcup_{k=1}^{3g-3}\bigsqcup_{(\tau,r)}\Pi_{(\tau,r)},$$ where $(\tau,r)$ runs over all marked stable genus-$g$  graphs with $k$ edges, and $\Pi_{(\tau,r)}$ is a $(k-1)$-simplex, whose vertices are in canonical bijection with the edges of $(\tau,r)$. Consider the equivalence relation $\sim$ on $\widetilde{\CV}_g^*$ defined as follows. For each graph $(\tau,r)$, and subgraph $\Phi$ that is a forest (say with $k'$ edges), let $(\tau',r')$ be the marked graph obtained by contracting each edge of $\Phi$ to a point. Then $\sim$ identifies the $(k'-1)$-simplex $\Pi_{(\tau',r')}$ in $\widetilde{\CV}_g^*$ with the $(k'-1)$-dimensional face of $\Pi_{(\tau,r)}$ corresponding to the edges of $\Phi$. The simplicial closure $\CV_g^*$ is then defined to be the quotient $\widetilde{\CV}_g^*/{\sim}$, which has the natural structure of a $\Delta$-complex. It follows from \cite[Lem. 1.3]{SmillieVogtmann1987} that in this $\Delta$-complex, no two faces of a simplex are identified, i.e. $\CV_g^*$ is actually a simplicial complex. Using this definition, the Culler-Vogtmann space $\CV_g\subseteq\CV_g^*$ is precisely the subset $$\Int(\widetilde{\CV}_g^*)/{\sim},$$ where $\Int(\widetilde{\CV}_g^*)$ is the union of the interiors of the simplices $\Pi_{(\tau,r)}$.

The above construction applies without modification to $\CV_{g,n}$, i.e.
  $$\widetilde{\CV}_{g,n}^*=\bigsqcup_{k=1}^{3g-3+n}\bigsqcup_{(\tau,r)}\Pi_{(\tau,r)},$$ where $(\tau,r)$ runs over all marked stable genus-$g$  graphs with $k$ edges and $n$ labeled leaves, and $\Pi_{(\tau,r)}$ is the corresponding $(k-1)$-simplex. 

\subsection{Edge lengths allowed to be zero} The following is implicit in the definition of $\CV_{g,n}^*$ in Section \ref{sec:OuterSpaceBackground}:
\begin{prop}\label{prop:PointsOfSimplicialCompletion}
    The points of the simplicial complex $\CV_{g,n}^*$ are in natural bijection with the set of isomorphism classes of marked stable genus-$g$ $n$-leafed   metric graphs whose edge lengths sum to 1, with lengths allowed to be zero, modulo the equivalence relation generated by setting $(\tau_1,r_1)\sim(\tau_2,r_2)$ if $(\tau_1,r_1)$ is obtained from $(\tau_2,r_2)$ by contracting a length-zero non-loop edge in $\tau_2$. 
\end{prop}
\begin{proof}
Let $\widetilde{\mathscr{R}}$ denote the set of isomorphism classes of marked stable genus-$g$ $n$-leafed   metric graphs whose edge lengths sum to 1, with lengths allowed to be zero. There is a clear bijection $\widetilde{\mathscr{R}}\to\widetilde{\CV}_{g,n}^*$. It remains to show that under this identification, the equivalence relation on $\widetilde{\mathscr{R}}$ is identified with the face-gluing relation on $\widetilde{\CV}_{g,n}^*$. Indeed, if $(\tau_1,r_1)$ is obtained from $(\tau_2,r_2)$ by contracting a length-zero non-loop edge $e$, then the face in $\Pi_{(\tau_2,r_2)}$ corresponding to contracting $e$ consists of metrics on $\tau_2$ where $e$ has length zero. The equivalence relation generated by identifications of this form is clearly the equivalence relation on $\widetilde{\CV}_{g,n}^*$ corresponding to forest contractions.
\end{proof}

\subsection{Spheres in a doubled handlebody}
The first definition of $\CV_{g,n}^*$ for $n>0$ was given by Hatcher, who used a correspondence between sphere systems in a doubled handlebody and their dual graphs, which we now explain.  

Let $\Xgn$ be a genus-$g$ $n$-pointed handlebody, and let $W_{g,n}$ denote the ``double'' of $\Xgn$, i.e. the compact oriented 3-manifold obtained by gluing together two copies of $\X$, with opposite orientations, along their common boundary via the identity map. Since the $n$ labeled points of $\Xgn$ are along the boundary, $W_{g,n}$ is an $n$-pointed 3-manifold. In analogy with Sections \ref{sec:SurfacesBackground} and \ref{sec:HandlebodiesBackground}, we have the following definitions.

A \emph{sphere} in $W_{g,n}$ is an embedded copy of $S^2$ that does not contain any labeled points. A sphere $\omega$ necessarily divides $W_{g,n}$ into two connected components. We call $\omega$ \emph{essential} if each of these components either contains $\ge2$ labeled points, or is not simply connected. A \emph{multisphere} in $W_{g,n}$ is a finite union of disjoint, pairwise non-homotopic, essential spheres in $W_{g,n}$. A multisphere $\Omega$ is called \emph{pure} if every connected component of its complement is simply connected. The \emph{dual graph} $\tau_\Omega$ of a multisphere $\Omega$ is defined similarly to the dual graph of a multidisk, as is the dual graph map $\dgm_{W_{g,n},\Omega}:W_{g,n}\setminus\{x_1,\ldots,x_n\}\to\tau_\Omega.$

The \emph{sphere complex} $\Sph(W_{g,n})$ is the infinite simplicial complex whose vertices are spheres in $W_{g,n}$, and whose $k$-simplices are multispheres with $k+1$ elements.

Fix an $n$-pointed homotopy equivalence $\rho\colon R_{g,n}\to V_{g,n}$.  This induces a map $f_\rho\colon\Sph(W_{g,n})\to\CV_{g,n}^*$ as follows. Given a multisphere $\Omega\subseteq W_{g,n}$, let $\Omega'\supseteq\Omega$ be a pure multisphere. The map takes the simplex corresponding to $\Omega$ to the simplex corresponding to the dual graph $\tau_{\Omega'},$ marked by the composition 
  $$R_{g,n}\xrightarrow{\rho} V_{g,n}\subset W_{g,n}\xrightarrow{\dgm_{W_{g,n},\Omega}} \tau_\Omega.$$  All of these maps are isomorphisms on $\pi_1$, so the composition is a homotopy equivalence (any map on graphs which induces an isomorphism on $\pi_1$ is a homotopy equivalence). 

%\begin{prop}\label{prop:SphereComplexIsomorphism} The map $f_\rho\colon\Sph(W_{g,n})\to\CV_{g,n}^*$  is an isomorphism.
%\end{prop}
%\begin{proof} See ~\cite{Hatcher1995}.
%\end{proof} 

There is also a ``doubling" map from the disc complex $\mathcal D(V_{g,n})$ to the sphere complex $\Sph(W_{g,n})$, that sends a multidisk to its double, which is a multisphere.  We have the following results from 3-manifold theory.

\begin{lem}\label{lem:DoublingSurjective}
    The doubling map $\D(\Xgn)\to\Sph(W_{g,n})$ is surjective.
\end{lem}
\begin{proof} 
By \cite[Thm. 1.3]{Scharlemann2024}, any embedded $2$-sphere in a punctured doubled handlebody is isotopic to one that intersects the handlebody surface in a single simple closed curve. Since there is only one isotopy class of disks in a handlebody with a given boundary curve \cite[Lem. 2.3]{Hensel2020}, the sphere is the double of this disk.
\end{proof}
\begin{rem}
    Scharlemann's theorem is much more general, applying to any compact 3-manifold with a fixed Heegard splitting.
\end{rem}

\begin{lem}\label{lem:DoublingTwistInvariant}
    Let $\omega$ and $\omega'$ be essential spheres in $W_{g,n}$. Then applying the Dehn twist around $\omega$ to $\omega'$ results in a sphere isotopic to $\omega'$.
\end{lem}
  \begin{proof}     This follows from Laudenbach's theorem that homotopic spheres in a doubled handlebody are isotopic.  See \cite{Hatcher1995}  for a detailed explanation of exactly how it follows.  The relevant papers of Laudenbach are \cite{Laudenbach1973} for a single sphere and \cite{Laudenbach1974} for a multisphere.
  %``Sur les 2-sspheres d'une variete de dimension 3", Annals 97 (1973) 57-81 (for a single sphere, this uses the light bulb trick)  and ``Topologie de la dimension trois:  homotopie et isotopie," Asterisque 12 (1974) 1-152. (for a multisphere, also called a sphere system) 
\end{proof}

\begin{prop}\label{prop:DiskComplexSphereComplex}
The doubling map induces an isomorphism $\mathcal D(V_{g,n})/\Tw(V_{g,n}) \to \Sph(W_{g,n}).$
\end{prop}





\begin{proof} 
    In Proposition \ref{prop:MarkedBijection}, we defined a map $\D(\Xgn)\to\CV_{g,n}^*$, which is an isomorphism after quotienting by $\Tw(\Xgn)$. This map clearly factors through the doubling map $\D(\Xgn)\to\Sph(W_{g,n})$, identifying the map $\Sph(W_{g,n})\to \CV_{g,n}^*$ with the map $f_\rho$ defined above. The doubling map is twist-invariant by Lemma \ref{lem:DoublingTwistInvariant}, so we have a diagram of simplicial complexes:
    $$\begin{tikzcd}
        \D(\Xgn)/\Tw(\Xgn)\arrow[r]\arrow[rr,bend right, "\cong"]&\Sph(W_{g,n})\arrow[r, "f_\rho"]&\CV_{g,n}^*.
    \end{tikzcd}$$
    The doubling map is surjective by Lemma \ref{lem:DoublingSurjective}, which implies that all maps above are isomorphisms. Thus $\mathcal D(V)/\Tw(V)\cong\Sph(W_{g,n})\cong\CV_{g,n}^*$.
\end{proof}
\begin{rem}
    The isomorphism $\Sph(W_{g,n})\xrightarrow{\cong}{}\CV_{g,n}^*$ is implicit in \cite{Hatcher1995}, where Hatcher takes $\Sph(W_{g,n})$ as the definition of the simplicial completion of $\CV_{g,n},$ and identifies $\CV_{g,n}$ with $\Sph^{\pure}(W_{g,n})$.
\end{rem}



