\morphism(0,0)|b|/@{<-}@<-3pt>/<750,0>[{\bf Bool}`{\bf KZFrm}; \Ba] 
\morphism(0,-500)|a|/@{->}@<3pt>/<750,0>[{\bf dBool}`{\bf KZdFrm};\idl]
\morphism(0,-500)|b|/@{<-}@<-3pt>/<750,0>[{\bf dBool}`{\bf KZdFrm}; \dB]
