\begin{defn} 
Let $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$ be a d-lattice.  A map $f\colon L\lra \bbB$ is a prime d-ideal of $\mathcal{L}$  if  it is at the same time a d-ideal and a d-filter of $\mathcal{L}$. 
\end{defn}

A prime d-ideal of a d-lattice $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$ is just a d-lattice homomorphism $f\colon\mathcal{L}\lra \bbB$; in particular, $f(\dbt)=\dbt$ and $f(\dbf)=\dbf$.

\begin{prop} Let $(L;\dbt,\dbf;{\bf con},{\bf tot})$ be a d-lattice. If $f\colon L\lra \bbB$ is a d-filter  and $g\colon L\lra \bbB$ is a d-ideal such that  $f\leq g$, then there is a prime d-ideal $h\colon L\lra \bbB$ for which $f\leq h\leq g$. \end{prop}

\begin{proof} First of all, notice that $f\leq g$ implies $f(\dbt)=\dbt=g(\dbt)$ and $f(\dbf)=\dbf=g(\dbf)$. Then, the ideal  $G_+=\{a\in L_+:g(a)=0\}$ is disjoint with the filter $ 
F_+=\{a\in L_+:f(a\vee\dbf)=1\}$; the ideal  $G_-=\{b\in L_-:g(b)=0\}$ is disjoint with the filter $F_-=\{b\in L_-:f(\dbt\vee b)=1\}.$ 

Pick an ideal $I_+$ of $L_+$ that contains $G_+$ and is maximal with respect to being disjoint with $F_+$; pick an ideal $I_-$ of  $L_-$ that contains $G_-$ and is maximal with respect to being disjoint with $F_-$. Maximality of $I_+$ implies that $I_+$ is a prime ideal of $L_+$, hence $K_+\coloneqq L_+\setminus I_+$ is a filter of $L_+$. Likewise, $K_-\coloneqq L_-\setminus I_-$ is a filter of $L_-$. 

Since $G_+\subseteq I_+$ and $G_-\subseteq I_-$, it follows that for all $(a,b)\in{\bf con}$, either $a\in I_+$ or $b\in I_-$. Since $F_+\subseteq K_+$ and $F_-\subseteq K_-$, it follows that for all $(a,b)\in{\bf tot}$, either $a\in K_+$ or $b\in K_-$. Therefore, the pair $(I_+,I_-)$ of ideals determines a d-ideal, say $h$; the pair $(K_+,K_-)$ of filters determines a d-filter, say $k$. It is readily seen that $h=k$, so $h$ is a prime d-ideal. That $f\leq h\leq g$ is clear by the construction of $h$.
\end{proof}

\begin{prop}\label{proper d-filter} Let $(L;\dbt,\dbf;{\bf con},{\bf tot})$ be a d-lattice. \begin{enumerate}[label=\rm(\roman*)] \setlength{\itemsep}{0pt}\item If $f\colon L\lra \bbB$ is a d-filter that preserves $\dbt$ and $\dbf$, i.e.,   $f(\dbt)=\dbt$ and $f(\dbf)=\dbf$, then  $f(a\vee b)=f(a)\vee f(b)$ for all $a\in L_{+}$ and $b\in L_{-}$.  \item If $g\colon L\lra \bbB$ is a d-ideal that preserves $\dbt$ and $\dbf$, i.e.,   $g(\dbt)=\dbt$ and $g(\dbf)=\dbf$, then  $g(a\vee b)=g(a\vee\dbf)\wedge g(\dbt\vee b)$ for all $a\in L_{+}$ and $b\in L_{-}$. \end{enumerate} \end{prop}

\begin{proof} (i) Since $f$ preserves $\dbt$ and $\dbf$, then $F_+=\{a\in L_+:f(a\vee\dbf)=1\}$ is a proper filter of $L_+$, and $F_-=\{b\in L_-:f(\dbt\vee b)=1\}$ is a proper filter of $L_-$. Since $f$ is determined by $F_+$ and $F_-$ as in Proposition \ref{structure of d-filter}, it is readily seen that $f$ possesses that property.

(ii) Similar. \end{proof}

Now we determine the structure of d-ideals and prime d-ideals of d-Boolean algebras. Let $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$ be a d-Boolean algebra. Then $${\bf con}=\{(a,b)\in L_+\times L_-:a\leq b^\dag\} \quad\text{and}\quad  {\bf tot}=\{(a,b)\in L_+\times L_-:a^\dag\leq b\},$$ hence for all $(a,b)\in L_+\times L_-$, $(a,b)\in{\bf tot}$ if and only if $(b^\dag,a^\dag)\in{\bf con}$. Therefore, for each ideal $I_+$ of $L_+$ and each ideal $I_-$ of $L_-$, the following are equivalent: 
\begin{itemize} \setlength{\itemsep}{0pt} \item the pair $(I_+,I_-)$ determines a  d-ideal of $\mathcal{L}$  (as in Proposition \ref{structure of d-ideal}); \item    $L_+=I_+\cup I_-^\dag$, where $I_-^\dag= \{x^\dag: x\in I_-\}$; \item   $L_-=I_+^\dag\cup I_-$, where $I_+^\dag= \{x^\dag: x\in I_+\}$. \end{itemize} Likewise, for each filter $F_+$ of $L_+$ and each filter $F_-$ of $L_-$, the following are equivalent: 
\begin{itemize} \setlength{\itemsep}{0pt} \item the pair $(F_+,F_-)$ determines a  d-filter (as in Proposition \ref{structure of d-filter}); \item  $L_+=F_+\cup F_-^\dag$, where $F_-^\dag= \{x^\dag: x\in F_-\}$; \item $L_-=F_+^\dag\cup F_-$, where  $F_+^\dag= \{x^\dag: x\in F_+\}$. \end{itemize}

The following proposition implies in particular that prime d-ideals of a d-Boolean algebra are pairwise incomparable.

\begin{prop}\label{dBool-IF} Let $(L;\dbt,\dbf;{\bf con},{\bf tot})$ be a d-Boolean algebra.  If $f\colon L\lra \bbB$ is a  d-filter and $g\colon L\lra \bbB$ is a  d-ideal such that $f\leq g$, then $f=g$. \end{prop}

\begin{proof} Let $$G_+=\{a\in L_+:g(a)=0\}, \quad G_-=\{b\in L_-:g(b)=0\};$$  let  $$F_+=\{a\in L_+:f(a\vee\dbf)=1\},\quad F_-=\{b\in L_-:f(\dbt\vee b)=1\}.$$ The inequality $f\leq g$ ensures that both $G_+$ and $G_-$ are proper ideals, both $F_+$ and $F_-$ are proper filters, and that $F_+\cap G_+=\emptyset$, $F_-\cap G_-=\emptyset$. 
Since, by the above-mentioned facts, $L_+\setminus F_+\subseteq F_-^\dag$ and $L_-\setminus G_-\subseteq G_+^\dag$, then $G_+\subseteq L_+\setminus F_+\subseteq F_-^\dag$ and $F_-\subseteq L_-\setminus G_-\subseteq G_+^\dag$, hence $F_-= G_+^\dag$ and consequently, $F_-= L_-\setminus G_-$, $F_+= L_+\setminus G_+$. 
Then,  from Proposition \ref{structure of d-ideal} and Proposition \ref{structure of d-filter} one infers that $g=f$.
\end{proof}

\begin{prop}\label{prime d-ideal}
Let $g\colon L\lra \bbB$ be  a d-ideal of a d-Boolean algebra $(L;\dbt,\dbf;{\bf con},{\bf tot})$. Then $g$ is prime if and only if it satisfies: \begin{enumerate}[label=\rm(\alph*)] \setlength{\itemsep}{0pt} \item For all $a\in L_+$, $g(a)=0\iff g(a^\dag)=\dbf$. \item  For all $b\in L_-$, $g(b)=0\iff  g(b^\dag)=\dbt$. 
\end{enumerate}
\end{prop}

\begin{proof} 
For necessity,  we check the equivalence in (a), leaving the equivalence in (b) to the reader. Suppose $a\in L_+$.  Since $g$ is a prime d-ideal,   $g$ preserves both {\bf con} and {\bf tot}, then $g({\bf con}\cap{\bf tot})\subseteq\{\dbt,\dbf\}$, particularly $g(a\vee a^\dag)\in \{\dbt,\dbf\}$. Since $g(a)\in\{0,\dbt\}$, $g(a^\dag)\in\{0,\dbf\}$ and $g(a\vee a^\dag)= g(a)\vee g(a^\dag)$, it follows that $g(a)=0\iff g(a^\dag)=\dbf$.  

For sufficiency, we show that $g$ is a d-filter. We do this in four steps.

{\bf Step 1}.   $g(\dbt)= \dbt$ and $g(\dbf)= \dbf$. If $g(\dbt)=0$, then $g(0)=\dbf$, which contradicts $g(0)\leq\dbt$. This shows that $g(\dbt)= \dbt$. Likewise,    $g(\dbf)= \dbf$.  

{\bf Step 2}. Let $$G_+=\{a\in L_+:g(a)=0\},\quad G_-=\{b\in L_-:g(b)=0\}; $$ and let $$F_+=\{a\in L_+:g(a\vee\dbf)=1\},\quad F_-=\{b\in L_-:g(\dbt\vee b)=1\}.  $$ The equivalence in (a) implies that for all $a\in L_+$, $$a\in F_+  \iff a^\dag\in G_-,$$ which  together with the fact that $(-)^\dag\colon L_+\lra L_-$ is an order-reversing isomorphism  imply that $F_+$ is a proper filter of $L_+$. Likewise, $F_-$ is a proper filter of $L_-$.

{\bf Step 3}. The pair $(F_+,F_-)$ of filters satisfies that for all $(a,b)\in{\bf tot}$, either $a\in F_+$ or $b\in F_-$. Suppose on the contrary that neither $a\in F_+$ nor $b\in F_-$. Then $g(a)=0$ and $g(b)=0$, hence $g(a^\dag)=\dbf$ and $g(b^\dag)=\dbt$, and consequently $g(b^\dag\vee a^\dag)=1$, which contradicts that $(b^\dag,a^\dag)\in{\bf con}$ and $g$ preserves {\bf con}. 

{\bf Step 4}. By Proposition \ref{structure of d-filter} the pair $(F_+,F_-)$ determines a d-filter, say $f$.  With help of Proposition \ref{proper d-filter}\thinspace(ii) one sees that $g=f$, then $g$ is a d-filter, as desired.  \end{proof}


\begin{prop}Let $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$ be a d-Boolean algebra. \begin{enumerate}[label=\rm(\roman*)] \setlength{\itemsep}{0pt}\item If $g$ is a prime d-ideal  of $\mathcal{L}$, then   $G_+=\{a\in L_+:g(a)=0\}$ is a prime ideal of $L_+$,   $G_-=\{b\in L_-:g(b)=0\}$ is a prime ideal of $L_-$,  and $G_+, G_-$ determine each other via $G_+^\dag=L_-\setminus G_-$. \item  If $I_+$ is a prime ideal of the lattice $L_+$, then there is a unique prime d-ideal $g$ of  $\mathcal{L}$ such that $I_+=  \{a\in L_+: g(a)=0\}$. \end{enumerate} Therefore, the prime d-ideals of $\mathcal{L}$ correspond bijectively to the prime ideals of  the lattice $L_+$. \end{prop}

\begin{proof}(i)  A direct consequence of Proposition \ref{prime d-ideal}.

(ii) Since $I_+$ is a prime ideal of $L_+$, then $L_+\setminus I_+$ is a prime filter of $L_+$, hence  $I_-\coloneqq \{a^\dag: a\in L_+\setminus I_+\}$ is a prime ideal of $L_-$. The d-ideal determined by the ideals $I_+$ and $I_-$ (as in Proposition \ref{structure of d-ideal}) is the unique prime d-ideal satisfying the requirement. \end{proof} 

\begin{exmp}Maximal d-filters of a d-Boolen algebra  need not be prime. Consider the d-Boolean algebra $([0,1]\times[0,1]; (1,0),(0,1);{\bf con},{\bf tot})$, where ${\bf con}=\{(a,b):a\leq 1-b\}$ and ${\bf tot}=\{(a,b):a\geq 1-b\}$. Let $F_+=(0,1]=F_-$. Then the d-filter determined by $F_+$ and $F_-$ is maximal, but not prime. 
\end{exmp} 

For each d-lattice $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$, let $$\dSpec\mathcal{L} $$ be the set of all prime d-ideals of $\mathcal{L}$. We make $\dSpec\mathcal{L} $ into a bitopological space by considering as  $\tau_+$ the topology generated by the collection of $$\phi_+(a)=\{g\in\dSpec\mathcal{L}:g(a)=\dbt\}, \quad a\in L_+; $$ and as  $\tau_-$ the topology generated by the collection of $$\phi_-(b)=\{g\in\dSpec\mathcal{L}:g(b)=\dbf\}, \quad b\in L_-. $$
The bitopological space $$(\dSpec\mathcal{L},\tau_+,\tau_-)$$ is called the \emph{spectrum} of the d-lattice $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$. It is not hard to check that each open set  of $\tau_+$ is of the form $$\phi_+(I_+)\coloneqq  
\{g\in\dSpec\mathcal{L}: \exists a\in I_+,\thinspace g(a)=\dbt\}$$ for some ideal $I_+$ of the lattice $L_+$; likewise for $\tau_-$. 

Sending each d-lattice to its spectrum defines a functor $$\dSpec\colon{\bf dLat}^{\rm op}\lra{\bf BiTop}.$$

\begin{exmp}  The spectrum $\dSpec\bbB$ of the d-lattice $\bbB$ (Example \ref{B as d-lattice}) is the bitopological space of a single point. \end{exmp}

We shall show that the spectrum of a d-Boolean algebra is a Stone bitopological space and that every Stone bitopological space arises in this way.

Let $\mathcal{L}=(L;\dbt,\dbf; \mathbf{con}, \mathbf{tot})$ be  a d-frame.  A \emph{d-point} \cite[Definition 3.4]{JM2008}) of  $\mathcal{L}$  is a d-frame homomorphism $p\colon\mathcal{L}\lra\bbB$. The set $\dpt \mathcal{L}$ of d-points of  $\mathcal{L}$ becomes a bitopological space by considering  as the topology $\tau_+$ the collection of $$\Phi_+(a) =\{p :p(a)= \dbt\},\quad a\in L_+;$$   and as the topology $\tau_-$ the collection of $$\Phi_-(b) =\{p:p(b)= \dbf\},\quad b\in L_-.$$    
The construction for objects is extended to a  functor 
$$\dpt\colon \dFrm^{\rm op}\lra \bf{BiTop}$$ in the usual way \cite{JM2006,JM2008}.

\begin{thm}{\rm(\cite[Theorem 3.5]{JM2008})} The functor 
$\dpt \colon \dFrm^{\rm op}\lra \bf{BiTop}$ is right adjoint to  $\dO\colon\bf{BiTop}\lra \dFrm^{\rm op}$. 
\end{thm}

The adjunction $\dO\dashv\dpt$ is an extension of the adjunction $\CO\dashv\pt$ between the categories of topological spaces and frames:
$$\bfig
\morphism(0,0)|a|/@{->}@<3pt>/<750,0>[{\bf Top}`{\bf Frm}^{\rm op};\CO]
\morphism(0,0)|b|/@{<-}@<-3pt>/<750,0>[{\bf Top}`{\bf Frm}^{\rm op};\pt] 
\morphism(0,-500)|a|/@{->}@<3pt>/<750,0>[{\bf BiTop}`{\bf dFrm}^{\rm op};\dO]
\morphism(0,-500)|b|/@{<-}@<-3pt>/<750,0>[{\bf BiTop}`{\bf dFrm}^{\rm op};\dpt]
\morphism(0,0)<0,-500>[{\bf Top}`{\bf BiTop}; \omega]
\morphism(750,0)|r|<0,-500>[{\bf Frm}^{\rm op} `{\bf dFrm}^{\rm op}; \omega]
\efig$$

For each bitopological space $(X,\tau_+,\tau_-)$ and each $x\in X$, the map $$[x]\colon\tau_+\times\tau_-\lra\bbB$$ is a d-point of the d-frame $\dO(X,\tau_+,\tau_-)$, where $$ [x](U,V) \geq\dbt \iff x\in U, \quad   [x](U,V) \geq\dbf \iff x\in V.$$  

A bitopological space $(X,\tau_+,\tau_-)$ is  \emph{d-sober} if each d-point $p$ of  the d-frame $\dO(X,\tau_+,\tau_-) $  is generated by a unique point $x$ of $X$ in the sense that $p=[x]$. As in the situation for topological spaces, a bitopological space $X$ is d-sober if and only if the component of the unit of the adjunction $\dO\dashv\dpt$ at $X$ is a bijection, hence a homeomorphism. It is known that every order-separated bitopological space is d-sober and  every d-sober bitopological space is $T_0$.
A d-frame $\mathcal{L}$ is  \emph{spatial}  if it is the d-frame of open sets of some bitopological space; or equivalently, it is isomorphic to the d-frame $\dO(\dpt \mathcal{L})$.  The adjunction $\dO\dashv\dpt$ between $\bf{BiTop}$ and $\bf{dFrm}$ cuts down to a duality between  d-sober bitopological spaces and  spatial d-frames. See Jung and Moshier \cite{JM2006, JM2008} for details.

\begin{prop}\label{spectrum as composite} The spectrum of a d-lattice $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$ is precisely the bitopological space of d-points of the d-frame of ideals of  $\mathcal{L}$; that is,  $\dSpec\mathcal{L} = \dpt\circ\idl\mathcal{L}$. \end{prop}

\begin{proof}By Proposition \ref{idl left adjoint to forgetful}, the functor $\idl\colon\dLat \longrightarrow \dFrm$ is left adjoint to the forgetful functor $\dFrm\longrightarrow\dLat$, it follows that a d-point of the d-frame $\idl\mathcal{L}$ is exactly a d-lattice homomorphism $\mathcal{L}\lra\bbB$, hence a prime d-ideal of $\mathcal{L}$.  It is routine to check that the bitopological structure of $\dSpec\mathcal{L}$ coincides with that of $\dpt\circ\idl\mathcal{L}$, and therefore $\dSpec\mathcal{L} =\dpt\circ\idl\mathcal{L}$. \end{proof}

We do not know whether the d-frame $\idl\mathcal{L}$  is spatial for every d-lattice $\mathcal{L}$. For d-Boolean algebras the answer is yes.

\begin{prop}\label{compact and zero-dimensional d-frame is spatial} 
For each d-Boolean algebra $\mathcal{L}$, $\idl\mathcal{L} = \dO\circ\dSpec\mathcal{L}$. In particular, the d-frame $\idl\mathcal{L}$ is spatial. 
\end{prop}

\begin{proof}  
Write $(\dSpec\mathcal{L},\tau_+,\tau_-)$ for the spectrum of $\mathcal{L}$. Since each open set of $\tau_+$ is of the form $\phi_+(I_+)$ for some ideal $I_+$ of the lattice $L_+$, each open set of $\tau_-$ is of the form $\phi_-(I_-)$ for some ideal $I_-$ of $L_-$, it suffices to prove: \begin{enumerate}[label=\rm(\roman*)] \setlength{\itemsep}{0pt}\item For different elements $(I_+, I_-)$ and $(J_+,J_-)$  of $\idl L$, there is some prime d-ideal $g$ of $\mathcal{L}$ that distinguishes $(I_+, I_-)$ and $(J_+,J_-)$ in the sense that either $g$ belongs to exactly one of $\phi_+(I_+)$ and $\phi_+(J_+)$, or $g$ belongs to exactly one of $\phi_-(I_-)$ and $\phi_-(J_-)$. \item 
$(I_+,I_-)\in{\bf con}_{\idl}\iff \phi_+(I_+)\cap\phi_-(I_-)=\emptyset$.  \item 
$(I_+,I_-)\in{\bf tot}_{\idl}\iff \phi_+(I_+)\cup\phi_-(I_-)=\dSpec\mathcal{L}$. \end{enumerate} 

{\bf Proof of (i)}.  Without loss of generality we assume that $I_+\not\subseteq J_+$. Pick a prime ideal $K_+$ of $L_+$ that contains $J_+$ but not $I_+$. Let $K_-=\{x^\dag : x\in L_+\setminus K_+\}$. Then, $K_-$ is a prime ideal of $L_-$,   the prime d-ideal of $\mathcal{L}$ determined by the pair $(K_+,K_-)$ distinguishes $(I_+, I_-)$ and $(J_+,J_-)$.

{\bf Proof of (ii)}. 
If $(I_+,I_-)\in{\bf con}_{\idl}$, then $b\leq a^\dag$ for all $a\in I_+$ and $b\in I_-$, so for each prime d-ideal $g$ of $\mathcal{L}$, we have \begin{align*} g\in \phi_+(I_+)&
\implies \exists a\in I_+, g(a)=\dbt \\ &\implies \exists a\in I_+,  g(a^\dag)=0 &(\text{Proposition \ref{prime d-ideal}})\\ &\implies \forall b\in I_-, g(b)=0 &(b\leq a^\dag)\\ &\implies g\notin \phi_-(I_-).\end{align*} Therefore $\phi_+(I_+)\cap\phi_-(I_-)=\emptyset$.  

If $(I_+,I_-)\notin{\bf con}_{\idl}$, then $a\not\leq b^\dag$ for some $a\in I_+$ and $b\in I_-$. Pick a prime ideal $K_+$ of $L_+$ containing $b^\dag$ but not $a$. Then $b$ does not belong to the prime ideal $K_-\coloneqq\{x^\dag:x\in L_+\setminus K_+\}$. Let $g$ be the prime d-ideal of $\mathcal{L}$ determined by the pair $(K_+,K_-)$, then $g\in \phi_+(I_+)\cap\phi_-(I_-)$. 

{\bf Proof of (iii)}.  
If $(I_+, I_-)\in{\bf tot}_{\idl}$, then there exist  $a\in I_+$ and $b\in I_-$ such that $(a,b)\in{\bf tot}$. Let $g$ be a prime d-ideal of $\mathcal{L}$. Since $g(a\vee b)\in\{1,\dbt,\dbf\}$, then $g(a)\vee g(b)\in\{1,\dbt,\dbf\}$ (because $g$ preserves finite joins), which implies that either $g(a)=\dbt$ or $g(b)=\dbf$, hence either $g\in\phi_+(I_+)$ or $g\in\phi_-(I_-)$. Therefore $\phi_+(I_+)\cup\phi_-(I_-) =\dSpec\mathcal{L}$.

If $(I_+,I_-)\notin{\bf tot}_{\idl}$, then $a\not\geq b^{\dag}$ for all $a\in I_+$ and all $b\in I_-$. Let $F_{+}=\{b^\dag:b\in I_-\}$. Then $F_+$ is a filter of $L_+$ which is disjoint with the ideal $I_+$, so there is a prime ideal $K_+$ of $L_+$ containing $I_+$ and  disjoint with $F_+$. It is readily seen that the ideal $I_-$ is contained in the prime ideal $K_-\coloneqq\{x^\dag:x\in L_+\setminus K_+\}$ of $L_-$. Let $g$ be the prime d-ideal of $\mathcal{L}$ determined by the pair $(K_+, K_-)$. Then $g\notin\phi_+(I_+)\cup\phi_-(I_-)$.
\end{proof} 

Since a zero-dimensional d-frame is regular in the sense of \cite[Definition 6.1]{JM2008}, and the d-frame of ideals of a d-Boolean algebra is compact and zero-dimensional, so the conclusion that the d-frame of ideals of a d-Boolean algebra is spatial also follows from a general result of Jung and Moshier  \cite[Theorem 6.11]{JM2006} which says that every compact and regular d-frame is spatial.   

\begin{cor} \label{duality between zk dframes and zk spaces}
The duality between spatial d-frames and d-sober bitopological spaces cuts down to a duality between compact and zero-dimensional d-frames and Stone bitopological spaces.
\end{cor}

\begin{proof} On the one hand, every Stone bitopological space is order-separated, hence d-sober by \cite[Theorem 3.9]{JM2008}. On the other hand, Proposition \ref{other side of the duality} shows that every compact and zero-dimensional d-frame is the d-frame $\idl\mathcal{L}$ of ideals of some d-Boolean algebra $\mathcal{L}$, hence  spatial by  Proposition \ref{compact and zero-dimensional d-frame is spatial}.  Thus, the conclusion follows from the fact that a bitopological space $(X,\tau_+,\tau_-)$ is compact and zero-dimensional if and only if so is the d-frame  $\dO(X, \tau_+, \tau_-)$ \cite[Section 2.3]{Jakl}. \end{proof}

\begin{thm} \label{duality of Stone bitop}
The category of d-Boolean algebras is dually equivalent to the category of Stone bitopological spaces.
\end{thm}

\begin{proof} Theorem \ref{dbool vs dfrm} shows that there is an equivalence $$\bfig
\morphism(0,0)|a|/@{->}@<3pt>/<750,0>[{\bf dBool}`{\bf KZdFrm};\idl ]
\morphism(0,0)|b|/@{<-}@<-3pt>/<750,0>[{\bf dBool}`{\bf KZdFrm}; \dB] \efig$$ between the category of d-Boolean algebras and the category of compact and zero-dimensional d-frames. Corollary  \ref{duality between zk dframes and zk spaces} says that there is a dual equivalence   $$\bfig
\morphism(0,0)|a|/@{->}@<3pt>/<750,0>[{\bf KZdFrm}^{\rm op}`{\bf BiStone};\dpt ]
\morphism(0,0)|b|/@{<-}@<-3pt>/<750,0>[{\bf KZdFrm}^{\rm op}`{\bf BiStone}; \dO] \efig$$ between the category of compact and zero-dimensional d-frames and the category of Stone bitopological spaces. The composite of these equivalences gives the desired duality  $$\bfig
\morphism(0,0)|a|/@{->}@<3pt>/<750,0>[{\bf dBool}^{\rm op}`{\bf BiStone};\dSpec ]
\morphism(0,0)|b|/@{<-}@<-3pt>/<750,0>[{\bf dBool}^{\rm op}`{\bf BiStone}; \dClop] \efig$$ between d-Boolean algebras and Stone bitopological spaces. \end{proof}

Since prime d-ideals  of a d-Boolean algebra $\mathcal{L}=(L;\dbt,\dbf;{\bf con},{\bf tot})$ are homomorphisms from $\mathcal{L}$ to $\bbB$ (viewed as a d-Boolean algebra),  elements of the d-Boolean algebra of d-clopen sets of a bitopological space $(X,\tau_+,\tau_-)$ are continuous maps from $(X,\tau_+,\tau_-)$ to $\bbB$ (viewed as a bitopological space as in Remark \ref{Stone-type}),  so the Boolean algebra $\bbB$ is a `schizophrenic object' \cite[Chapter VI]{Johnstone} (or, a `dualizing object' \cite[page 14]{JM2006})  for the duality in Theorem \ref{duality of Stone bitop}.

The following diagram is commutative, so the duality in Theorem \ref{duality of Stone bitop} is an extension of that between Boolean algebras and Stone  spaces to the context of bitopological spaces.
$$\bfig
\morphism(0,0)|a|/@{->}@<3pt>/<750,0>[{\bf Bool}^{\rm op}`{\bf Stone};\Spec ]
\morphism(0,0)|b|/@{<-}@<-3pt>/<750,0>[{\bf Bool}^{\rm op}`{\bf Stone}; \Clop]
\morphism(0,-500)|a|/@{->}@<3pt>/<750,0>[{\bf dBool}^{\rm op}`{\bf BiStone};\dSpec ]
\morphism(0,-500)|b|/@{<-}@<-3pt>/<750,0>[{\bf dBool}^{\rm op}`{\bf BiStone}; \dClop]
\morphism(750,0)|r|<0,-500>[{\bf Stone}`{\bf BiStone}; \omega]
\morphism(0,0)|l|<0,-500>[{\bf Bool}^{\rm op}`{\bf dBool}^{\rm op}; \omega]
\efig$$

In \cite[Theorem 5.3]{BBGK} it is proved that the category of distributive lattices is dually equivalent to the category of Stone bitopological spaces. A combination of this result with Theorem \ref{duality of Stone bitop} yields that the category of d-Boolean algebras is equivalent to the category of distributive lattices. We present below a direct proof of this equivalence. 

Let $M$ be a distributive lattice. Applying Proposition  \ref{dbool via order reversing} to the order-reversing isomorphism $M\lra M^{\rm op},~x\mapsto x$ we obtain that  $\lambda(M)\coloneqq (L;\dbt,\dbf;{\bf con},{\bf tot})$ is a d-Boolean algebra, where  \begin{itemize} \setlength{\itemsep}{0pt}
\item   $L_+=M$, $L_-=M^{\rm op}$; \item $\dbt=(1,1)$, $\dbf=(0,0)$; \item ${\bf con}=\{(a,b)\in M\times M: a\leq b\}$;   \item ${\bf tot}=\{(a,b)\in M\times M: a\geq b\}$. \end{itemize} 
In this way we obtain a functor  $\lambda\colon{\bf DisLat}\lra\dBoo$  from the category of distributive lattices and lattice homomorphisms to the category of d-Boolean algebras.

\begin{prop}\label{DLat and DBL} The functor $\lambda\colon{\bf DisLat}\lra\dBoo$ is an equivalence of categories. 
\end{prop}

We prove a lemma first. Define a category {\bf DBL}   as follows: \begin{itemize} \item objects: an object is a triple $(L_+,L_-, ^\dag)$, where $L_+,L_-$ are distributive lattices and $ ^\dag\colon L_+\lra L_-$ is an order-reversing isomorphism. \item morphisms: a morphism from $(L_+,L_-, ^\dag)$ to $(M_+,M_-, ^\dag)$ is a pair $(f,g)$, where $f\colon L_+\lra M_+$ and $g\colon L_-\lra M_-$ are two lattice homomorphisms such that $g(a^\dag)=f(a)^\dag$ for all $a\in L_+$. $$\bfig\square[L_+` L_-`M_+` M_-; ^\dag`f`g` ^\dag] \efig $$\end{itemize}

\begin{lem}\label{d-Bool as DBL} The category $\dBoo$ of d-Boolean algebras is isomorphic to the category {\bf DBL}. \end{lem}

\begin{proof} For each d-Boolean algebra $(L;\dbt,\dbf;{\bf con},{\bf tot})$, the triple $(L_+,L_-, ^\dag)$ is an object of {\bf DBL}, where $ ^\dag\colon L_+\lra L_-$ takes each $a\in L_+$ to its d-complement, which is an element of $L_-$. Suppose $h\colon (L;\dbt,\dbf;{\bf con},{\bf tot})\lra (M;\dbt,\dbf;{\bf con},{\bf tot})$ is a morphism (i.e. a d-lattice homomorphism) between d-Boolean algebras. Since $h$ maps $L_+$ to $M_+$ and maps $L_-$ to $M_-$, both the restriction $f$ of $h$ to $L_+$ and $M_+$ and the restriction $g$ of $h$ to $L_-$ and $M_-$  are lattice homomorphisms. Since $h$ preserves {\bf con} and {\bf tot}, it follows that for each $a\in L_+$, $h(a^\dag)$ is the d-complement of $h(a)$; that is, $g(a^\dag)=f(a)^\dag$. So we obtain a functor  $F\colon\dBoo\lra {\bf DBL}.$  

For each object $(L_+,L_-, ^\dag)$ of {\bf DBL}, by Proposition \ref{dbool via order reversing} we have  a d-Boolean algebra  $(L_+\times L_-;\dbt,\dbf;{\bf con},{\bf tot})$, where \begin{itemize}
\item   $\dbt=(1,0)$, $\dbf=(0,1)$, \item ${\bf con}=\{(a,b)\in L_+\times L_-: a\leq b^\dag\}$, \item ${\bf tot}=\{(a,b)\in L_+\times L_-: a^\dag\leq b\}$.\end{itemize} For each morphism $(f,g)\colon (L_+,L_-, ^\dag)\lra (M_+,M_-, ^\dag)$ in the category {\bf DBL},  the product $f\times g$  is a morphism $(L_+\times L_-;\dbt,\dbf;{\bf con},{\bf tot})\lra (M_+\times M_-;\dbt,\dbf;{\bf con},{\bf tot})$ between  d-Boolean algebras. So we obtain a functor  $G\colon {\bf DBL}\lra\dBoo.$   

The functors $F$ and $G$ are readily verified to be inverse to each other, so the categories $\dBoo$ and {\bf DBL} are isomorphic to each other. \end{proof}

\begin{proof}[Proof of Proposition \ref{DLat and DBL}]
For each distributive lattice $M$, the consistency and totality predicates of the d-Boolean algebra $\lambda(M)$ are  determined by the order relation, so the functor $\lambda\colon{\bf DisLat}\lra\dBoo$ is full and faithful. It remains to check that it is essentially surjective on objects.  For this we show that each d-Boolean algebra $(L;\dbt,\dbf;{\bf con},{\bf tot})$ is isomorphic to $\lambda(M)$  with $M=L_+$. 

Since the square  $$ \bfig \square[L_+`L_-`L_+`L_+^{\rm op}; ^\dag`{\rm id}`^\dag`{\rm id}] \efig$$ is commutative,  where $ ^\dag$ is the map sending each element to its d-complement,   {\rm id} is the identity map on the set $L_+$, it follows that $(L_+,L_-,\dag)$ is isomorphic to $(L_+,L_+^{\rm op},{\rm id})$ in the category {\bf DBL}, then the conclusion follows from Lemma \ref{d-Bool as DBL}. \end{proof}

We end this section with a duality between complete d-Boolean algebras and extremally disconnected Stone bitopological spaces. 

A d-Boolean algebra $(L;\dbt,\dbf;{\bf con}, {\bf tot})$ is \emph{complete} if the distributive lattice $L$ is   complete. It is clear that a d-Boolean algebra $(L;\dbt,\dbf;{\bf con}, {\bf tot})$ is complete if and only if both $L_+$ and $L_-$ are complete lattices.  

A bitopological space $(X,\tau_+,\tau_-)$ is \emph{extremally disconnected} \cite{Sarma} provided that the $\tau_-$-closure of each $\tau_+$-open set is   $\tau_+$-open, and the $\tau_+$-closure of each $\tau_-$-open set is $\tau_-$-open. 


A bitopological space $(X,\tau_+,\tau_-)$ is \emph{pairwise regular} \cite{Kelly} provide that (i)  for each  $\tau_+$-open set $U$ and each $x\in U$, there is some $\tau_+$-open set $V$ such that $x\in V$ and that the $\tau_-$-closure of $V$ is contained in $U$; and (ii) for each  $\tau_-$-open set $V$ and each $x\in V$, there is some $\tau_-$-open set $U$ such that $x\in U$ and that the $\tau_+$-closure of $U$ is contained in $V$.  

It is readily seen that every zero-dimensional bitopological space is pairwise regular;   every extremally disconnected and pairwise regular bitopological space  is zero-dimensional.

\begin{prop}\label{complete d-Boolean algebra}
A zero-dimensional bitopological space is extremally disconnected if and only if its d-Boolean algebra of  d-clopen sets is complete.
\end{prop}

\begin{proof}  
First,  we prove that if a bitopological space $(X,\tau_+,\tau_-)$ is extremally disconnected, then the d-Boolean algebra $\dClop(X,\tau_+,\tau_-)$  is complete. Given a collection $\{U_i\}_{i\in I}$  of $\tau_+$-open and $\tau_-$-closed sets, let $U$ be the $\tau_-$-closure of the $\tau_+$-open set $\bigcup_{i\in I} U_i$. Then $U$ is $\tau_+$-open since $(X,\tau_+,\tau_-)$ is extremally disconnected, hence a $\tau_+$-open and $\tau_-$-closed set containing each $U_i$. If $W$ is a $\tau_+$-open and $\tau_-$-closed set  containing each $U_i$, then $W$ contains  $U$. This shows that $U$ is the join of $\{U_i\}_{i\in I}$ in the d-Boolean algebra $\dClop(X,\tau_+,\tau_-)$.
Likewise,  each collection of $\tau_-$-open and $\tau_+$-closed sets has a join in $\dClop(X,\tau_+,\tau_-)$. Therefore, the d-Boolean algebra $\dClop(X,\tau_+,\tau_-)$ is complete.

Next, we prove that if a bitopological space $(X,\tau_+,\tau_-)$ is zero-dimensional and its d-Boolean algebra of d-clopen sets is complete, then  it is extremally disconnected. Given   a $\tau_+$-open set $U$, by zero-dimensionality of $(X,\tau_+,\tau_-)$  we may pick for each $x\in U$   a $\tau_+$-open and $\tau_-$-closed set $U_x$  such that $x\in U_{x}\subseteq U$. Let $\tilde{U}$ be the join of $\{U_{x}\}_{x\in U}$  in $\dClop(X,\tau_+,\tau_-)$. Then $\tilde{U}$ is $\tau_+$-open and $\tau_-$-closed. We assert that $\tilde{U}$ is the $\tau_-$-closure of $U$, so the $\tau_-$-closure of $U$ is $\tau_+$-open.  For this it suffices to show that $\tilde{U}$ is contained in the $\tau_-$-closure of $U$. Suppose on the contrary that there is some $y$ of $ \tilde{U}$ that is not in  the $\tau_-$-closure of $U$. Since $(X,\tau_+,\tau_-)$ is zero-dimensional, there is a $\tau_-$-open and $\tau_+$-closed set $V$ that contains $y$ and is disjoint with $U$. Then $X\setminus V$ is a $\tau_+$-open and $\tau_-$-closed set that contains $U$. Let $W=(X\setminus V)\cap \tilde{U}$. Then $W$ is a $\tau_+$-open and $\tau_-$-closed set that contains  $U$, so it is an upper bound of  $\{U_{x}\}_{x\in U}$  in $\dClop(X,\tau_+,\tau_-)$.  This contradicts that  $\tilde{U}$ is the join of $\{U_{x}\}_{x\in U}$ since it is not contained in $W$. Likewise,  the $\tau_+$-closure of each $\tau_-$-open set is $\tau_-$-open. Therefore, $(X,\tau_+,\tau_-)$ is extremally disconnected.
\end{proof} 

\begin{thm}
The category of complete d-Boolean algebras and d-lattice homomorphisms is dually equivalent to the category of extremally disconnected Stone bitopological spaces and continuous maps.
\end{thm}

\begin{proof}This follows immediately from Theorem \ref{duality of Stone bitop} and Proposition \ref{complete d-Boolean algebra}.\end{proof}


