\section{Tropical Lagrangians in \texorpdfstring{$(\bC^*)^2$}{(C*)²}}

\subsection{Tropical Structure of Riemann Surfaces}

We start from a Laurent polynomial on $(\bC^*)^2$ of the form
$f = \sum_{\alpha \in A} c_\alpha z^\alpha$,
where $A$ is a finite subset of $\bZ^2$, and $z^\alpha = z_1^{\alpha_1}z_2^{\alpha_2}$ for $\alpha = (\alpha_1 , \alpha_2 ) \in \bZ^2.$

\begin{definition}\label{def:trop-poly-of-f}
    The \textit{tropical polynomial} of $f$ is given by
    $$ \phi(f)(x_1, x_2) = \bigoplus_{\alpha \in A} \log|c_\alpha| \odot x^{\odot \alpha}. $$
\end{definition}

If $\alpha = (\alpha_1 , \alpha_2 )$, then
$$x^{\odot \alpha} = x_1^{\odot \alpha_1} \odot x_1^{\odot \alpha_2} = \alpha_1 x_1 + \alpha_2 x_2,$$
so the tropical polynomial can also be written by 
$$ \phi(f)(x_1, x_2) = \max_{\alpha \in A}\, \left( \log\abs{c_\alpha}+ (\alpha_1 x_1 + \alpha_2 x_2) \right). $$

The term inside the $\max$ function is the log norm of the monomial $c_\alpha z^\alpha$ with $x_1 = \log \abs{z_1}$ and $x_2 = \log \abs{z_2}$. This means that the value of the tropical polynomial tells which monomial in $f$ is maximal. 

$\phi(f)$ is a piecewise linear function, and its set of singularity is a $1$-dimensional skeleton inside $\bR^2$, called the $\textit{tropical skeleton}$ $V(f)$ of $f$. Each connected component of its complement is where one of the monomial $c_\alpha z^\alpha$ has a strictly bigger norm than other terms, and we call this component $C_\alpha$. 

Each unbounded component $C_\alpha$ comes from the most ``extreme" terms of $f$. Specifically, if we consider the convex hull of $A$ in $\bR^2$, each unbounded component $C_\alpha$ comes from the boundary of the hull, as stated by the following proposition.

\begin{proposition}\label{prop:c-alpha-hull}
    Let $\hull(A)$ be the convex hull of $A$.
    \begin{enumerate}
        \item For each vertex $\alpha$ of the polygon $\hull(A)$, $C_\alpha$ is unbounded.
        \item If $C_\alpha$ is unbounded for $\alpha \in A$, then $\alpha$ lies in the boundary of $\hull(A)$.
    \end{enumerate}
\end{proposition}

\begin{proof}
    If $\alpha$ is a vertex of $\hull(A)$, then there is a linear function $l:\bR^2 \to \bR$ such that $\alpha$ is the strict maximum of $l$ on $\hull(A)$. If $l(x_1, x_2) = k_1 x_1 + k_2 x_2$ is one such function, then by the maximality, the term $c_\alpha z^\alpha$ is strictly bigger than the other terms in $f$ when $z_1 = R^{k_1}$ and $z_2 = R^{k_2}$ for sufficiently large $R$. Thus the ray $\{(k_1 x, k_2 x ) \,|\, x\ge 0 \}$ should lie in $C_\alpha$ outside of a compact region.

    Next, we show that if $\alpha$ lies in the interior of $\hull(A)$, then $C_\alpha$ is bounded (or empty). After dividing all the terms by $z^\alpha$, we may assume that $\alpha = (0,0)$. In this case, any ray in $\bR^2$ starting from the origin intersects with one of the boundary edges (or its endpoint) of $\hull(A)$. If the endpoints of the boundary edge are $\beta_1, \beta_2 \in A$, then the intersection point $\beta$ is equal to $t\beta_1 + (1-t)\beta_2$ for some $0 \le t \le 1$, and the distance between $O$ and $\beta$ is exactly the log norm of $z^{\beta}$. Also, we have that 
    $$\log\abs*{z^\beta } = t \log\abs*{z^{\beta_1}} + (1-t)\log\abs*{z^{\beta_2}} \le \max\left( \log\abs*{z^{\beta_1}}, \log\abs*{z^{\beta_2}} \right). $$
    Hence, if we let $d$ be the distance between $\alpha$ and the boundary of $\hull(A)$, and set 
    $$M = \max_{\beta_1, \beta_2 \in A} \log\abs*{{c_{\beta_1}}c_{\beta_2}^{-1} }, $$
    then $C_\alpha$ is contained in the bounded set $\frac{M}{d} \hull(A)$.
\end{proof}

Consider the divisor $D_f \subseteq (\bC^*)^2$. We use the tropical skeleton of $f$ because it tells us about the approximate behavior of $D_f$ at infinity. Indeed, when the log norm of $z$ is in one of $C_\alpha$ and is large enough, then $f(z)$ cannot be zero because the term $c_\alpha z^\alpha$ in $f$ would be bigger than the sum of the others. Hence, $D_f$ gets close to the ray in the tropical skeleton. To simplify the description, we only consider Laurent polynomials $f = \sum_{\alpha \in A} c_\alpha z^\alpha$ satisfying the following.

\begin{assumption}{\label{ass:trop-ftn}}
    The convex hull of $A$ has no non-vertex lattice points on its boundary.
\end{assumption}

This assumption implies that for each ray $l_{\alpha\beta}$ between $C_\alpha$ and $C_\beta$, the terms $c_\alpha z^\alpha$ and $c_\beta z^\beta$ get significantly bigger than the others. Therefore, at infinity, $D_f$ approaches to the complex submanifold $\{c_\alpha z^\alpha = c_\beta z^\beta \}$.

Also, the non-existence of the boundary lattice points implies that $\alpha - \beta$ is a pair of coprime integers, and in this case, the complex curve $\{c_\alpha z^\alpha = c_\beta z^\beta \}$ is topologically isomorphic to a cylinder. Indeed, if we set $\log z_j = p_j + i \theta_j$ for $j=1,2$, then the defining equation is equivalent to

\begin{equation*}
    \begin{cases}
        (\alpha_1 - \beta_1)p_1 + (\alpha_2 - \beta_2)p_2 = \log\abs*{c_\beta} - \log\abs*{c_\alpha},\\
        (\alpha_1 - \beta_1)\theta_1 + (\alpha_2 - \beta_2)\theta_2 = \arg{c_\beta} - \arg{c_\alpha}.
    \end{cases}
\end{equation*}

Thus, when $\alpha_1 - \beta_1$ and $\alpha_2 - \beta_2$ are coprime to each other, this set is a product of a line in the $(p_1, p_2)$-plane and an $S^1$ in the $(\theta_1, \theta_2)$-torus.

Also, we consider the following coordinate system to describe the points near the cylinder. Let $\Xi_{\alpha,r}$ be the cylinder $\{ z^\alpha = r \} \subseteq (\bC^*)^2$, where $\alpha = (\alpha_1, \alpha_2)$ is a pair of coprime integers and $r$ is a nonzero complex number. If we use the same cylindrical coordinate system $(p_1, p_2, \theta_1, \theta_2)$ as above, $Z$ is a product of the line $\alpha_1 p_1 + \alpha_2 p_2 = \log |r|$ and a circle $\alpha_1 \theta_1 + \alpha_2 \theta_2 = \arg{r}.$ Then, we consider the new coordinate system given by
\begin{align*}
%    p_\alpha &= \frac{1}{\abs{\alpha}}(\alpha_1 p_1 + \alpha_2 p_2)&p_\alpha^\perp = \frac{1}{\abs{\alpha}}(\alpha_2 p_1 - \alpha_1 p_2)\\
%    \theta_\alpha &= \frac{1}{\abs{\alpha}}(\alpha_1 \theta_1 + \alpha_2 \theta_2)&\theta_\alpha^\perp = \frac{1}{\abs{\alpha}}(\alpha_2 \theta_1 - \alpha_1 \theta_2),
    p_\alpha^\perp &= \alpha_1 p_1 + \alpha_2 p_2,&p_\alpha = \frac{1}{\abs{\alpha}^2}(\alpha_2 p_1 - \alpha_1 p_2),\\
    \vartheta_\alpha^\perp &= \alpha_1 \theta_1 + \alpha_2 \theta_2,&\vartheta_\alpha = \frac{1}{\abs{\alpha}^2}(\alpha_2 \theta_1 - \alpha_1 \theta_2).
\end{align*}
(This notation is for complex curves, and we will use the coordinates $p_\alpha$ and $\theta_\alpha$ and cylinder $Z_{\alpha, r}$ for the Lagrangian case.)
The cylinder $\Xi_{\alpha, r}$ can be described as $\{p_\alpha^\perp = \log|r|,\,\, \vartheta_\alpha^\perp \equiv \arg{r} \pmod{2\pi} \}$, and the points on $Z$ can be uniquely described by $p_\alpha$ and $\vartheta_\alpha$ modulo $2\pi$. The $(\theta_1, \theta_2)$-torus cannot be expressed as a direct product of two $S^1$ formed by $\vartheta_\alpha$ and $\vartheta_\alpha^\perp$ unless $\alpha$ is $(\pm 1, 0)$ or $(0, \pm 1)$. However, every point on the complement of $\{\vartheta_\alpha^\perp \equiv \arg{r} + \pi \pmod{2\pi} \}$ can be uniquely expressed by $p_\alpha$, $p_\alpha^\perp$, $\vartheta_\alpha$ modulo $2\pi$ and $\vartheta_\alpha^\perp \in (\arg r - \pi, \arg r + \pi).$

%\vspace{0.3em}
%\begin{figure}[ht]
%    \includegraphics[width=0.6\textwidth]{figtest2.jpg}
%    \caption{}
    %\label{homotopy-method}
%\end{figure}
%\vspace{0.3em}

Since we will only need half of this cylinder, we orient the cylinder as follows. (Topologically, this is not an orientation of a cylinder, but rather an orientation of the line in the $(p_1, p_2)$-plane.)

\begin{definition}
    Consider the cylinder $\Xi_{\alpha, r} = \{ z^\alpha = r \}$, and suppose that the coordinate system $(p_\alpha, p_\alpha^\perp, \vartheta_\alpha, \vartheta_\alpha^\perp)$ is defined as above.
    \begin{itemize}
        \item The \textit{positive half} of $\Xi_{\alpha, r}$ is defined by 
        $$\Xi_{\alpha, r}^+ := \{ p_\alpha^\perp = \log|r|,\,\, \vartheta_\alpha^\perp \equiv \arg{r} \pmod{2\pi},\,\, p_\alpha > 0 \}.$$
        \item The vector $(\alpha_1, \alpha_2)$ is called the \textit{normal direction} of the cylinder $\Xi_{\alpha, r}^+$.
    \end{itemize}
\end{definition}

The half-infinite cylinder $\Xi_{\alpha, r}^+$ is the product of a ray in the $(p_1, p_2)$-plane and a circle in the $(\theta_1, \theta_2)$-plane, and the normal direction of the cylinder is orthogonal to the ray in the $(p_1, p_2)$-plane.

Now, we describe the behavior of the divisor $D_f = \{f = 0 \}$ using this definition.

\begin{definition}\label{defn:trop-ends-C}
    Let $f$ be a Laurent polynomial satisfying Assumption~\ref{ass:trop-ftn}, and denote the unbounded components of the complement of $V(f)$ by $C_{\beta_1}, C_{\beta_2}, \cdots, C_{\beta_k}$ in a counterclockwise order. Then, the \textit{holomorphic tropical cylindrical ends} of $f$ are the collection $\{\Xi_{\alpha_1, r_1}^+,\Xi_{\alpha_2, r_2}^+, \cdots, \Xi_{\alpha_m, r_m}^+\}$ of half-infinite cylinders in $(\bC^*)^2$, where $\alpha_j = \beta_{j+1} - \beta_j$ and $r_j = c_{\beta_j} c_{\beta_{j+1}}^{-1}.$ (Here, $\beta_{k+1} = \beta_1$)
\end{definition}

Note that $\beta_1, \beta_2, \cdots, \beta_k$ is ordered so that $Z_j$ are in the outward direction. In this case, we can show that $D_f$ is expressed as a union of graphs of functions on each $Z_{\alpha_m, r_m}^+$ at infinity.

\begin{proposition}\label{prop:trop-approx-C}
    Let $f = \sum_{\beta \in A}c_\beta z^\beta$ be a Laurent polynomial satisfying Assumption~\ref{ass:trop-ftn}, and set 
    $$M = \max_{\beta_1, \beta_2 \in A} \log\abs*{c_{\beta_1}c_{\beta_2}^{-1}}.$$ 
    Suppose that the tropical cylindrical ends of $f$ are $\{\Xi_{\alpha_1, r_1}^+, \Xi_{\alpha_2, r_2}^+, \cdots, \Xi_{\alpha_m, r_m}^+\}$. Then, there exist constants $b_1, b_2, b_3 > 0$ depending only on $A$ that satisfy the following.

    \begin{enumerate}
        \item The curve $D_f$ lies inside the union
        $$ \{|\log|z_1||, |\log|z_2|| \le b_1 M \} \quad \cup \quad  \bigsqcup_{j=1}^k \,\{ p_{\alpha_j} > b_2 M, \,\,\abs{p_{\alpha_j}^\perp - \log\abs{r_j}} < 1 \}.$$
        \item For $j=1,2,\cdots,k$, there exists a holomorphic function $\rho_j:\{\Rea z > b_2 M \} \to \bC$ such that the set $D_f \cap \{ p_{\alpha_j} > b_2 M, \,\,\abs{p_{\alpha_j}^\perp  - \log\abs{r_j}} < 1 \}$ is equal to the graph
        $$\{(p_{\alpha_j}, p_{\alpha_j}^\perp, \vartheta_{\alpha_j}, \vartheta_{\alpha_j}^\perp) \,|\, p_{\alpha_j}^\perp + i\vartheta_{\alpha_j}^\perp = \log{r_j} + \rho_j(p_{\alpha_j} + i\vartheta_{\alpha_j}) \}.  $$
        \item The function $\rho_j$ has the upper bound
        $$ \abs*{\rho_j(p_{\alpha_j} + i\vartheta_{\alpha_j})} \le M\exp(-b_3 p_{\alpha_j}). $$
    \end{enumerate}

\end{proposition}
