\begin{proposition}\label{prop:PoP-module-structure}
    The following holds for the generators on the diagonal cylindrical end $Z_{\alpha, r}^+$ of $L_\PoP$.
    \begin{enumerate}
        \item There are two generators of the type $x_\alpha^j x_\alpha^e$ for any nonnegative integer $j$, which are $x_\alpha^{k, j+k} x_\alpha^e$ for any positive even number or any positive odd number, respectively.
        \item\label{prop-sub:PoP-module-structure-functions} For a fiber torus $F_\rho$ lying on the cylindrical end $Z_{\alpha, r}^+$ with nonzero $HF^\bullet(F_\rho, L_f)$, the pole parts of the module structure (\ref{eqn:module-structure-fib-torus}) for generators of the type $x_\alpha^j x_\alpha^e$ and the type $e$ coming from holomorphic triangles are zero except for the relation
        \begin{equation}\label{eqn:fiber-torus-x*e-is-f(p)e-alpha}
            x_\alpha^{j_0, j_1} x_\alpha^e \cdot e_{j_1} = g^{j_0, j_1}(\rho) e_{j_0}
        \end{equation}
        (modulo the terms with $T^{-2\pi w p_\alpha}$, $w \le 0$) after a suitable rescaling of the generators. Here, the coefficient $g^{j_0, j_1}(\rho)$ is the following monomial on $\rho = (z_1, z_2)$:
        \vspace{0.1in}

        \begin{tabularx}{0.8\textwidth} { >{\centering\arraybackslash}X | >{\centering\arraybackslash}X >{\centering\arraybackslash}X }
             & $g^{\text{even},\,\, \text{even}+k} (\rho)$ & $g^{\text{odd},\,\, \text{odd}+k} (\rho)$ \\
            \hline\hline
            $k = 2l$ & $z_1^l z_2^l$ & $ z_1^l z_2^l$ \\
            $k = 2l+1$ & $z_1^{l+1} z_2^l$ & $- z_1^l z_2^{l+1}$
        \end{tabularx}
        \vspace{0.1in}

        \item\label{prop-sub:PoP-module-structure-generators} Under the same rescaling, $e_1 + e_2$ is the generator of $HF^0(F_\rho, L_\PoP)$.
    \end{enumerate}
\end{proposition}

Similar to the proof of Theorem~\ref{thm:HMS-for-Lq}, one can exclude the existence of holomorphic disks with positive width except for ones lying inside the cylindrical region. For each point $X = x_\alpha^{j_0, j_1} x_\alpha^e$ of type $x_\alpha^j x_\alpha^e$ with $j = j_1 - j_0$, there is exactly one such triangle that has $X$ as an input vertex. After action rescaling (Notation~\ref{not:action-rescale}), the weight of the triangle is equal to $T^{-2j\pi p_\alpha} \xi_\alpha^{j_0, j_1}$, where  $\xi_\alpha^{j_0, j_1}$ is the holonomy of the local system on the fiber torus along the path from $e_{j_0}$ to $e_{j_1}$, fixing $\theta_\alpha^\perp$ and increasing $\theta_\alpha$ by $2j\pi$.

