    % & \leftarrow  \text{order 3}
    \\
    & + 2\mathrm{Re}\Big\{(-i)^3 V_\mathrm{DA^2}V_\mathrm{A^2A^1}V_\mathrm{A^1D} \int_0^t dt_1\int_0^{t_1} dt_2 \int_0^{t_2} dt_3 \, \Braket{\hat{\Pi}_\mathrm{DA^2A^1D}}_\beta\Big\} 
    & \Leftarrow \raisebox{-0.5\totalheight}{\includegraphics[]{fig/propagator-2b.pdf}}
    % & \leftarrow  \text{order 3}
    \\
