\section{An alternative model with draws} \label{sec:alternative}
David's assertion that the probability of draws should be accounted for in estimating player strength parameters suggests a natural-looking modification of Davidson's assumption of Property~\ref{Luce_Condition}, and consequently (\ref{bt_davidson}), while accepting Davidson's assumption~(\ref{DavidsonDraw}).

We introduce strength parameters, $\sigma_i$, for $i=1,\ldots,t$, to satisfy
\begin{property}\label{alt_strength_ratio}
\begin{equation}\frac{\sigma_i}{\sigma_j}=\frac{p_{ij}+\frac 12 d_{ij}}{p_{ji}+\frac 12 d_{ij}}\,.\label{strength_ratio}\end{equation}
\end{property}
Property~\ref{alt_strength_ratio} implies that
\begin{equation}\left(\frac{p_{ij}+\frac 12 d_{ij}}{p_{ji}+\frac 12 d_{ij}}\right)\left(\frac{p_{jk}+\frac 12 d_{jk}}{p_{kj}+\frac 12 d_{jk}}\right)=\frac{p_{ik}+\frac 12 d_{ik}}{p_{ki}+\frac 12 d_{ik}}\,.\label{bt_edwards}\end{equation}

This has the advantage over Davidson's model of ensuring that strength parameter ratios depend on expected score ratios, not just the probability of wins (exclusive of draws). On the other hand it has the disadvantage (perhaps surprisingly) that ratings can in some situations not follow the ranking given by scores in balanced designs with three or more players. We demonstrate this fact in Section~\ref{sec:consistency}.

We remark here that whether Davidson's or the Alternative model is more correct could in principle be checked by comparing data to the assumptions (\ref{bt_davidson}) and (\ref{bt_edwards}).

Given~(\ref{strength_ratio}), we calculate:
$$p_{ij}+\frac 12d_{ij}=\frac{\sigma_i}{\sigma_j}\left(p_{ji}+\frac 12 d_{ij}\right)$$
so that
$$\frac 12d_{ij}\left(\frac{\sigma_i}{\sigma_j}-1\right)=p_{ij}-\frac{\sigma_i}{\sigma_j}p_{ji}$$
and
\begin{equation}d_{ij}=\frac{2\left(\sigma_jp_{ij}-\sigma_ip_{ji}\right)}{\sigma_i-\sigma_j}\,,\label{draw_prob}\end{equation}
as long as $\sigma_i\ne\sigma_j$. 
Then, from~(\ref{DavidsonDraw}) and (\ref{draw_prob}),
\begin{equation}\nu \sqrt{p_{ij}p_{ji}}=\frac{2\left(\sigma_jp_{ij}-\sigma_ip_{ji}\right)}{\sigma_i-\sigma_j}\label{draw_base}\end{equation}
$$\frac{\nu}{2}(\sigma_i-\sigma_j)\sqrt{p_{ij}p_{ji}}=\left(\sigma_jp_{ij}-\sigma_ip_{ji}\right)$$
or
$$\frac{\nu}{2}\left(1-\frac{\sigma_j}{\sigma_i}\right)\sqrt{\frac{p_{ji}}{p_{ij}}}=\left(\frac{\sigma_j}{\sigma_i}-\frac{p_{ji}}{p_{ij}}\right)\,.$$
Thus,
$$\frac{p_{ji}}{p_{ij}}+\frac{\nu}{2}\left(1-\frac{\sigma_j}{\sigma_i}\right)\sqrt{\frac{p_{ji}}{p_{ij}}}-\frac{\sigma_j}{\sigma_i}=0$$
from which,
\begin{equation}\sqrt{\frac{p_{ji}}{p_{ij}}}= \frac{\nu}{4}\left(\frac{\sigma_j}{\sigma_i}-1\right)+\sqrt{\frac{\nu^2}{16}\left(1-\frac{\sigma_j}{\sigma_i}\right)^2+\frac{\sigma_j}{\sigma_i}}=\frac{2}{\nu}\phi\left(\frac{\sigma_j}{\sigma_i}\right)\label{pratio}\end{equation}
where we pick the positive root (the other is negative and therefore not relevant), and where, for later use,
\begin{equation}
\phi(x)\equiv \frac{\nu^2}{8}(x-1)+\frac{\nu}{2}\sqrt{\frac{\nu^2}{16}(x-1)^2+x}\,. \label{phi}
\end{equation}
Although $\phi$ depends on parameter $\nu$, writing $\phi(x;\nu)$ everywhere is cumbersome, so we write $\phi(x)$ and just remember the dependence on $\nu$. Note that $\phi(0)=0$, $\phi(1)=\frac{\nu}{2}$, $\phi(\infty)=\infty$, and $\phi(x)>0$ for all $x>0$. Also, if $\nu=0$, then $\phi(x)\equiv 0$, and if $\nu=2$, then $\phi(x)\equiv x$.

Now, using~(\ref{draw_prob}) in~(\ref{ppd}) gives
$$p_{ij}+p_{ji}+\frac{2(\sigma_jp_{ij}-\sigma_ip_{ji})}{\sigma_i-\sigma_j}=1$$
so
$$(\sigma_i-\sigma_j)(p_{ij}+p_{ji})+2(\sigma_jp_{ij}-\sigma_ip_{ji})=\sigma_i-\sigma_j$$
$$(\sigma_i+\sigma_j)p_{ij}-(\sigma_i+\sigma_j)p_{ji}=\sigma_i-\sigma_j$$
and
\begin{equation}
p_{ji}=p_{ij}+\frac{\sigma_j-\sigma_i}{\sigma_j+\sigma_i}=p_{ij}+\frac{\left(\frac{\sigma_j}{\sigma_i}-1\right)}{\left(\frac{\sigma_j}{\sigma_i}+1\right)}\,.\label{psigma}
\end{equation}
Squaring~(\ref{pratio}) gives
\begin{eqnarray*}
p_{ji} &=& p_{ij}\left(\frac{2}{\nu}\phi\left( \frac{\sigma_j}{\sigma_i} \right)\right)^2=p_{ij}\left(\frac{\nu}{4}\left(\frac{\sigma_j}{\sigma_i}-1\right)+\sqrt{\frac{\nu^2}{16}\left(1-\frac{\sigma_j}{\sigma_i}\right)^2+\frac{\sigma_j}{\sigma_i}}\right)^2 \\
&=& p_{ij}\left(\frac{\nu^2}{8}\left(\frac{\sigma_j}{\sigma_i}-1\right)^2 +\frac{\sigma_j}{\sigma_i}+\frac{\nu}{2}\left(\frac{\sigma_j}{\sigma_i}-1\right)\sqrt{\frac{\nu^2}{16}\left(1-\frac{\sigma_j}{\sigma_i}\right)^2+\frac{\sigma_j}{\sigma_i}} \right) \\
&=& p_{ij}\left[\left(\frac{\sigma_j}{\sigma_i}-1\right)\left(\frac{\nu^2}{8}\left(\frac{\sigma_j}{\sigma_i}-1\right) +\frac{\nu}{2}\sqrt{\frac{\nu^2}{16}\left(1-\frac{\sigma_j}{\sigma_i}\right)^2+\frac{\sigma_j}{\sigma_i}} \right)+\frac{\sigma_j}{\sigma_i}\right] \\
&=& p_{ij}\left[\left(\frac{\sigma_j}{\sigma_i}-1\right)\phi\left(\frac{\sigma_j}{\sigma_i}\right)+\frac{\sigma_j}{\sigma_i}\right]
\label{pratio_squared}
\end{eqnarray*}
and combining with~(\ref{psigma}) gives
$$ p_{ij}\left[\left(\frac{\sigma_j}{\sigma_i}-1\right)\phi\left(\frac{\sigma_j}{\sigma_i}\right)+\frac{\sigma_j}{\sigma_i}-1 \right]= \frac{\left(\frac{\sigma_j}{\sigma_i}-1\right)}{\left(\frac{\sigma_j}{\sigma_i}+1\right)}$$
or
\begin{equation*}
\frac{1}{p_{ij}} =  \left(\frac{\sigma_j}{\sigma_i}+1\right)\left[1+\phi\left(\frac{\sigma_j}{\sigma_i}\right)\right] 
\end{equation*}
or
\begin{equation}
p_{ij}=\left(\frac{\sigma_i}{\sigma_i+\sigma_j}\right)\left(\frac{1}{1+\phi\left(\frac{\sigma_j}{\sigma_i}\right)}\right)
=\left(\frac{\sigma_i}{\sigma_i+\sigma_j}\right)\left(\frac{\sigma_i}{\sigma_i+\sigma_i\phi\left(\frac{\sigma_j}{\sigma_i}\right)}\right)
\,,\label{p_by_sigmaratio}
\end{equation}
which expresses $p_{ij}$ solely in terms of strength parameters $\sigma_i$ and $\sigma_j$ (as well as parameter $\nu$).

If $\sigma_i=\sigma_j$, then $p_{ij}=p_{ji}$ and $d_{ij}=1-2p_{ij}$, so $\nu p_{ij}=1-2p_{ij}$ and $p_{ij}=\frac{1}{2+\nu}$, which agrees with Equation~\eqref{p_by_sigmaratio}.

