\subsection{Special cases of the Alternative model: $\nu=0$ and $\nu=2$}
Note that when $\nu=0$, the Alternative model reduces to the Bradley-Terry model. 

Another special case is important. When
$\nu=2$, Equation~\eqref{SigmaRatio2} becomes
\begin{equation}\frac{\sigma_i}{\sigma_j}=\sqrt{\frac{p_{ij}}{p_{ji}}}\,.\label{SigmaRatioSimple}\end{equation}
Thus, the ratio of strength parameters is the square root of the ratio for the Davidson model, {\em i.e.}, 
\begin{equation}\frac{\sigma_i}{\sigma_j}=\sqrt{\frac{\pi_i}{\pi_j}}\,. \label{sigma_pi}
\end{equation}
Also, since $\phi(x)=x$, Equation~\eqref{p_by_sigmaratio} becomes
\begin{equation}p_{ij} = \left( \frac{\sigma_i}{\sigma_i+\sigma_j} \right)^2\,.\label{pijEdwardsSimple}\end{equation}
Thus, the probability of a win looks like the probability of two wins in the Bradley-Terry model without draws. In effect, this model with $\nu=2$ is what one would obtain from the Bradley-Terry model without draws if each game were considered to be {\em two} comparisons instead of one, with a draw corresponding to a result of 10 or 01, and a win (loss) corresponding to a result of 11 (or 00). This is a natural way of capturing the fact that a draw is considered equivalent (in scoring) to half a win, {\em i.e.}, two draws are equivalent to a win and a loss. This also implies that variances are halved in relation to the Bradley-Terry model, reflecting the finer information available when draws are possible.

%From this point of view, the Alternative model with $\nu=2$ is a natural choice for estimating strength parameters from results data, but of course, this does not help if one wishes to estimate an unknown number of draws on information from won games (or pools). In that case one needs to use a value of $\nu$ that reflects the frequency of draws in practice.

In fact, the Davidson model with $\nu=2$ also gives
\begin{equation} p_{ij}=\frac{\pi_i}{\pi_i+\pi_j+2\sqrt{\pi_i\pi_j}} = \left(\frac{\sqrt{\pi}_i}{\sqrt{\pi_i}+\sqrt{\pi_j}}\right)^2\label{pijDavidsonSimple}\end{equation}
which is equivalent to the above if $\sigma_i=\sqrt{\pi_i}$ and $\sigma_j=\sqrt{\pi_j}$, and is consistent with the observation in Equation~\eqref{sigma_pi} above, since
$$p_{ij}=\left(\frac{1}{1+\frac{\sigma_j}{\sigma_i}}\right)^2=\left(\frac{1}{1+\sqrt{\frac{\pi_j}{\pi_i}}}\right)^2\,.$$

\section{Maximum likelihood estimation}\label{sec:max_likelihood}

\subsection{Davidson model}
The likelihood of a data set in the Davidson model is
\begin{eqnarray*}
L &=& \prod_{i,j} p_{ij}^{w_{ij}} \prod_{i<j}d_{ij}^{t_{ij}} = \prod_{i,j} \left( \frac{\pi_i}{\pi_i+\pi_j+\nu\sqrt{\pi_i \pi_j}} \right)^{w_{ij}} \times \prod_{i<j} \left( \frac{\nu\sqrt{\pi_i \pi_j} }{\pi_i+\pi_j+\nu\sqrt{\pi_i \pi_j}} \right)^{t_{ij}} \\
&=& \frac{\nu^T \prod_{i<j}\pi_i^{w_{ij}+\frac{1}{2} t_{ij}} \prod_{i>j} \pi_i^{w_{ij}+\frac{1}{2}t_{ij}}}{ \prod_{i<j} (\pi_i+\pi_j+\nu\sqrt{\pi_i \pi_j})^{ n_{ij} } } = \frac{\nu^T\prod_{i,j}\pi_i^{s_{ij} }} { \prod_{i<j} (\pi_i+\pi_j+\nu\sqrt{\pi_i \pi_j})^{n_{ij}} } =  \frac{\nu^T\prod_{i}\pi_i^{s_{i} }} { \prod_{i<j}(\pi_i+\pi_j+\nu\sqrt{\pi_i \pi_j})^{n_{ij}} }
\end{eqnarray*}
and the log likelihood is
$$ \log(L) = T\log(\nu) + \sum_i s_i\log(\pi_i) - \sum_{i<j} n_{ij} \log(\pi_i+\pi_j+\nu\sqrt{\pi_i \pi_j})\,. $$

To find the maximum of the log-likelihood function, we differentiate with respect to each parameter and set these to $0$.
\begin{eqnarray*}
 \frac{\partial}{\partial \pi_k}\log(L) &=& \frac{s_k}{\pi_k} - \sum_{i<k} \frac{n_{ik}\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_i}{\pi_k}}\right)}{\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}} + \sum_{j>k} \frac{n_{kj}\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_j}{\pi_k}}\right)}{\pi_k+\pi_j+\nu\sqrt{\pi_k\pi_j}}  \\
 &=&  \frac{s_k}{\pi_k} - \sum_{i} \frac{n_{ik}\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_i}{\pi_k}}\right)}{\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}} =\frac{s_k}{\pi_k} - G_k(\bm{\pi},\nu) =0
 \end{eqnarray*}
letting $\bm{\pi}=(\pi_1,\ldots,\pi_t)^\top$, and where we use the fact that $n_{kj}=n_{jk}$ (and of course $n_{kk}=0$). And,
\begin{eqnarray*}
  \frac{\partial}{\partial \nu}\log(L)&=& \frac{T}{\nu} - \sum_{i<j}\frac{n_{ij}\sqrt{\pi_i\pi_j}}{\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}} \\
  &=&  \frac{T}{\nu} - \frac 12 \sum_{i,j}\frac{n_{ij}\sqrt{\pi_i\pi_j}}{\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}} =\frac{T}{\nu}-H(\bm{\pi},\nu) = 0\,.
  \end{eqnarray*}
The maximum likelihood solution is found by iteratively solving the system
\begin{subequations}
\label{iteration_Davidson}
\begin{align}
  \pi_k &\leftarrow \frac{s_k}{G_k(\bm{\pi},\nu)}\,,\quad k=1,\ldots,t, \\
  \nu &\leftarrow \frac{T}{H(\bm{\pi},\nu)  } \,,
\end{align}
\end{subequations}
along with a normalization criterion, like $\sum_k \pi_k = 1$. 
In the above system of $t+1$ equations, the number of parameters is $t+1$, since there are $t$ strength parameters $\pi_k, k=1,\ldots, t$, as well as $\nu$, but since the strength parameter vector, $\bm{\pi}=(\pi_1,\ldots,\pi_t)^\top$, can be scaled arbitrarily without changing scores or numbers of draws, we must lose one degree of freedom by such a normalization. Then the number of independent parameters is $t$. Indeed, one could rewrite the system in terms of parameter ratios, since $s_k=\frac{\pi_k}{\pi_t}G_k\left(\frac{\bm{\pi}}{\pi_t},\nu\right)$, which makes it clear that there are only $t$ independent parameters, the $t-1$ ratios, $\frac{\pi_k}{\pi_t}$ for $k=1,\ldots,t-1$ (but not $\frac{\pi_t}{\pi_t}$, which of course is fixed at $1$). Now it seems there are $t+1$ equations in $t$ unknowns, but one of the first $t$ equations is dependent on the others. It is clear that if all data ($s_k$, $n_{ik}$, and $T$), are scaled uniformly by a factor $\lambda>0$, the equations are the same, so the parameters estimated must be the same. In effect, only the score ratios are needed, not the scores themselves. So the first $t-1$ equations could be written
  $$ \frac{s_k}{s_t}=\frac{\pi_k}{\pi_t}\frac{G_t\left(\frac{\bm{\pi}}{\pi_t},\nu\right)}{G_k\left(\frac{\bm{\pi}}{\pi_t},\nu\right)}\,,\quad k=1,\ldots, t-1\,. $$
In effect, there are $t$ independent equations (for the $s$-ratios and $T$) in $t$ independent unknowns (the $\pi$-ratios and $\nu$).

  Also, note that in a balanced tournament, where all $n_{ij}\equiv n$, the number of data points in the set of equations for the maximum log-likelihood is $t+2$, since they are the components of the vector $s=(s_1,\ldots,s_t)$ as well as $n$ and $T$. But $n$ is not independent of $s$, since $\sum_k s_k = \frac{n}{2}t(t-1)$, and an arbitrary scaling of all $s_{ij}=w_{ij}+\frac 12 t_{ij}$ scales $s$ and $T$ (and $n$) by the same factor, $\lambda$, and does not change the equations, so we lose another degree of freedom by fixing this scaling, and the number of independent data points is $t$. A convenient normalization here is to make $n=1$, so that each $s_{ij}+s_{ji}=1$, and $\sum_k s_k = \frac 12 t(t-1)$. This implies that the reverse problem, to find the data values given the parameters, is also determined ($t$ independent equations in $t$ unknowns) for balanced tournaments. This is not the case, of course, for unbalanced tournaments, since then there are many more independent data values, $n_{ik}$, so many sets of data values will be consistent with the same set of parameters.

  The Consistency property, the fact that in a balanced tournament (where $n_{ij}=n$, for all $i\ne j$), strength parameters respect the order of scores, is shown by Davidson~\cite{Davidson1970} as follows.
  \begin{prop} The Davidson model is consistent.\end{prop}
  {\bf Proof:}
  \begin{eqnarray*}
  s_j-s_k &=& \pi_jG_j(\bm{\pi},\nu)-\pi_kG_k(\bm{\pi},\nu) = \pi_j n \sum_{i\ne j} \frac{\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_i}{\pi_j}}\right)}{\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}} - \pi_k n \sum_{i\ne k} \frac{\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_i}{\pi_k}}\right)}{\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}} \\
  &=& n \sum_{i\ne j} \frac{\left(\pi_j+\frac{\nu}{2}\sqrt{\pi_i\pi_j}\right)}{\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}} - n\sum_{i\ne k} \frac{\left(\pi_k+\frac{\nu}{2}\sqrt{\pi_i \pi_k}\right)}{\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}} \\
  &=& n \sum_{i} \frac{\left(\pi_j+\frac{\nu}{2}\sqrt{\pi_i\pi_j}\right)}{\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}} - n\sum_{i} \frac{\left(\pi_k+\frac{\nu}{2}\sqrt{\pi_i \pi_k}\right)}{\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}}- n\frac{\pi_j+\frac{\nu}{2}\sqrt{\pi_j\pi_j}}{\pi_j+\pi_j+\nu\sqrt{\pi_j\pi_j}}+ n\frac{\pi_k+\frac{\nu}{2}\sqrt{\pi_k\pi_k}}{\pi_k+\pi_k+\nu\sqrt{\pi_k\pi_k}} \\
  &=& n \sum_{i} \frac{\left(\pi_j+\frac{\nu}{2}\sqrt{\pi_i\pi_j}\right)\left(\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}\right) - \left(\pi_k+\frac{\nu}{2}\sqrt{\pi_i \pi_k}\right)\left(\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}\right)}{\left(\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}\right)\left(\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}\right) } -\frac{n}{2} +\frac{n}{2}\\
  &=& n \sum_{i} \frac{\left(\pi_i(\pi_j-\pi_k)+\frac{\nu}{2}\pi_j\sqrt{\pi_i \pi_k}-\frac{\nu}{2}\pi_k\sqrt{\pi_i \pi_j}+\frac{\nu}{2}\pi_i\sqrt{\pi_i \pi_j}-\frac{\nu}{2}\pi_i\sqrt{\pi_i \pi_k}\right)}{\left(\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}\right)\left(\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}\right) } \\
 &=& n \sum_{i} \frac{\left(\pi_i(\sqrt{\pi_j}-\sqrt{\pi_k})(\sqrt{\pi_j}+\sqrt{\pi_k})+(\sqrt{\pi_j}-\sqrt{\pi_k})\frac{\nu}{2}\sqrt{\pi_i \pi_j \pi_k}+(\sqrt{\pi_j}-\sqrt{\pi_k})\frac{\nu}{2}\pi_i^{3/2}\right)}{\left(\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}\right)\left(\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}\right) } \\
  &=& n(\sqrt{\pi_j}-\sqrt{\pi_k}) \sum_{i} \frac{\left(\pi_i(\sqrt{\pi_j}+\sqrt{\pi_k})+\frac{\nu}{2}\sqrt{\pi_i \pi_j \pi_k}+\frac{\nu}{2}\pi_i^{3/2}\right)}{\left(\pi_i+\pi_j+\nu\sqrt{\pi_i\pi_j}\right)\left(\pi_i+\pi_k+\nu\sqrt{\pi_i\pi_k}\right) } \\
 \end{eqnarray*}
 and since the sum in the last expression is positive, $(s_j-s_k)$ and $(\sqrt{\pi_j}-\sqrt{\pi_k})$ have the same sign, and so, therefore, too, does $(\pi_j-\pi_k)$. \qed

 Note that the same proof works (more simply) for the Bradley-Terry model (without draws), by setting $\nu=0$.

 Note also that in a 2-player tournament, where $t=2$, we have $n_{12}=n_{21}=n$ and
 $$ s_1=\pi_1 G_1(\pi,\nu)=\frac{n\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_2}{\pi_1}}\right)}{\pi_1+\pi_2+\nu\sqrt{\pi_1\pi_2}} $$
and similarly for $s_2$, so
$$ \frac{s_1}{s_2}=\frac{\pi_1 G_1(\pi,\nu)}{\pi_2 G_2(\pi,\nu)}=\frac{\pi_1+\frac{\nu}{2}\sqrt{\pi_1\pi_2}}{\pi_2+\frac{\nu}{2}\sqrt{\pi_1\pi_2}} =\frac{p_{12}+\frac 12 d_{12}}{p_{21}+\frac 12 d_{21}} \, ,$$
and, of course, by definition, 
$$ \frac{s_1}{s_2}=\frac{w_{12}+\frac 12 t_{12}}{w_{21}+\frac 12 t_{21}}\,.$$

\subsection{Alternative model} \label{sec:alternative_likelihood}

To find the maximum likelihood estimate for the Alternative model, we need $p_{ij}$ expressed in terms of $\sigma_i$, $\sigma_j$ and $\nu$, which is given by Equation~\eqref{p_by_sigmaratio}.

We have 
$$L= \prod_{i,j} p_{ij}^{w_{ij}} \prod_{i<j}d_{ij}^{t_{ij}} = \left(\prod_{i,j}p_{ij}^{w_{ij}}\right)\nu^T\left(\prod_{i<j}\sqrt{p_{ij}}^{t_{ij}}\right)\left(\prod_{i<j}\sqrt{p_{ji}}^{t_{ji}}\right) = \nu^T\prod_{i,j}p_{ij}^{s_{ij}}$$
so
\begin{eqnarray*}
 \log(L) &=& T\log(\nu)+\sum_{i,j}s_{ij}\log(p_{ij}) \\
 &=& T\log(\nu)+\sum_{i,j}s_{ij} \left[ \log(\sigma_i)-\log(\sigma_i+\sigma_j)-\log\left(1+\phi\left(\frac{\sigma_j}{\sigma_i}\right)\right) \right]  \\
 &=& T\log(\nu)+\sum_{i}s_{i} \log(\sigma_i) -\sum_{i,j}s_{ij} \log(\sigma_i+\sigma_j)-\sum_{i,j}s_{ij}\log\left(1+\phi\left(\frac{\sigma_j}{\sigma_i}\right)\right)    \,.
 \end{eqnarray*}

 Then the maximum likelihood is obtained from 
\begin{subequations}
\label{max_likelihood_alternative}
\begin{align}
0 = \frac{\partial}{\partial \sigma_k}\log(L) &= \frac{s_k}{\sigma_k} - \sum_j \frac{s_{kj}}{\sigma_k+\sigma_j} - \sum_i \frac{s_{ik}}{\sigma_i+\sigma_k} 
- \sum_j \frac{s_{kj}\left(-\frac{\sigma_j}{\sigma_k^2}\phi'\left(\frac{\sigma_j}{\sigma_k}\right)\right)}{1+\phi\left(\frac{\sigma_j}{\sigma_k}\right)} - \sum_i \frac{s_{ik}\frac{1}{\sigma_i}\phi'\left(\frac{\sigma_k}{\sigma_i}\right)}{1+\phi\left(\frac{\sigma_k}{\sigma_i}\right)} \notag \\
&=  \frac{s_k}{\sigma_k} - \sum_i \frac{n_{ik}}{\sigma_i+\sigma_k} + \sum_i \frac{s_{ki}\left(\frac{\sigma_i}{\sigma_k^2}\phi'\left(\frac{\sigma_i}{\sigma_k}\right)\right)}{1+\phi\left(\frac{\sigma_i}{\sigma_k}\right)} - \sum_i \frac{s_{ik}\frac{1}{\sigma_i}\phi'\left(\frac{\sigma_k}{\sigma_i}\right)}{1+\phi\left(\frac{\sigma_k}{\sigma_i}\right)} =\frac{s_k}{\sigma_k}-G_k(\bm{\sigma},\nu) \label{sG}\\
0 = \frac{\partial}{\partial\nu}\log(L) &= \frac{T}{\nu} - \sum_{i,j} \frac{s_{ij}\phi_{\nu}\left(\frac{\sigma_j}{\sigma_i}\right)}{1+\phi\left(\frac{\sigma_j}{\sigma_i}\right)} =\frac{T}{\nu}-H(\bm{\sigma},\nu) \,, \label{TH}
\end{align}
\end{subequations}
where
\begin{eqnarray*} G_k(\bm{\sigma},\nu) &=& \sum_i \frac{n_{ik}}{\sigma_i+\sigma_k} - \sum_i \frac{s_{ki}\left(\frac{\sigma_i}{\sigma_k^2}\phi'\left(\frac{\sigma_i}{\sigma_k}\right)\right)}{1+\phi\left(\frac{\sigma_i}{\sigma_k}\right)} + \sum_i \frac{s_{ik}\frac{1}{\sigma_i}\phi'\left(\frac{\sigma_k}{\sigma_i}\right)}{1+\phi\left(\frac{\sigma_k}{\sigma_i}\right)}  \\
H(\bm{\sigma},\nu) &=& \sum_{i,j} \frac{s_{ij}\phi_{\nu}\left(\frac{\sigma_j}{\sigma_i}\right)}{1+\phi\left(\frac{\sigma_j}{\sigma_i}\right)}
\end{eqnarray*}
which suggests the iteration
\begin{subequations}
\label{iteration_alternative}
\begin{align}
    \sigma_k &\leftarrow \frac{s_k}{G_k(\bm{\sigma},\nu)}\,,\quad k=1,\ldots,t, \\
    \nu &\leftarrow \frac{T}{H(\bm{\sigma},\nu)}\,.
    \end{align}
\end{subequations}

