\subsection{Balanced tournaments with three players} \label{sec:3player}

Consider the case $t=3$. As discussed previously, we take $n=1$ and then $s_1=s_{12}+s_{13}$, $s_2=(1-s_{12})+s_{23}$, $s_3=(1-s_{13})+(1-s_{23})$, and $s_1+s_2+s_3=3$. Thinking of the reverse problem, the system of maximum likelihood equations can be written
\begin{eqnarray*}
 s_1 = s_{12}+s_{13} &=& \sigma_1 G_1(s_{12},s_{13}) \\
 s_2 = 1-s_{12}+s_{23} &=& \sigma_2 G_2(s_{12},s_{23}) \\
 s_3 = 2-s_{13}-s_{23} &=& \sigma_3 G_3(s_{13},s_{23}) \\
 T &=& \nu H(s_{12},s_{13},s_{23})
\end{eqnarray*}
which is a linear system of $4$ equations in a vector of $4$ unknowns, $x=(s_{12}, s_{13}, s_{23}, T)$, but with a dependency among the first three equations ($s_1+s_2+s_3=3$), so that, written as $Ax=b$, the rank of $A$ is only $3$.

The equations are
\begin{eqnarray*} 
s_{12}+s_{13} &=& \frac{\sigma_1}{\sigma_1+\sigma_2}+\frac{\sigma_1}{\sigma_1+\sigma_3}
-s_{12}f\left(\frac{\sigma_2}{\sigma_1}\right)
-s_{13}f\left(\frac{\sigma_3}{\sigma_1}\right)
+(1-s_{12})f\left(\frac{\sigma_1}{\sigma_2}\right)
+(1-s_{13})f\left(\frac{\sigma_1}{\sigma_3}\right) \\
1-s_{12}+s_{23} &=& \frac{\sigma_2}{\sigma_2+\sigma_1}+\frac{\sigma_2}{\sigma_2+\sigma_3}
-(1-s_{12})f\left(\frac{\sigma_1}{\sigma_2}\right)
-s_{23}f\left(\frac{\sigma_3}{\sigma_2}\right)
+s_{12}f\left(\frac{\sigma_2}{\sigma_1}\right)
+(1-s_{23})f\left(\frac{\sigma_2}{\sigma_3}\right) \\
2-s_{13}-s_{23} &=& \frac{\sigma_3}{\sigma_3+\sigma_1}+\frac{\sigma_3}{\sigma_3+\sigma_2}
-(1-s_{13})f\left(\frac{\sigma_1}{\sigma_3}\right)
-(1-s_{23})f\left(\frac{\sigma_2}{\sigma_3}\right)
+s_{13}f\left(\frac{\sigma_3}{\sigma_1}\right)
+s_{23}f\left(\frac{\sigma_3}{\sigma_2}\right) \\
T &=& \nu\left[s_{12}g\left(\frac{\sigma_2}{\sigma_1}\right)+s_{13}g\left(\frac{\sigma_3}{\sigma_1}\right)+s_{23}g\left(\frac{\sigma_3}{\sigma_2}\right) \right.\\
&& \left. + (1-s_{12})g\left(\frac{\sigma_1}{\sigma_2}\right) + (1-s_{13})g\left(\frac{\sigma_1}{\sigma_3}\right) +(1-s_{23})g\left(\frac{\sigma_2}{\sigma_3}\right)
\right]
\,, 
\end{eqnarray*}
where 
$$f(x)=\frac{x\phi'\left(x\right)}{1+\phi\left(x\right)}\,,\quad g(x)=\frac{\phi_{\nu}(x)}{1+\phi(x)}\,,$$
which can be written:
{\small
\begin{eqnarray*} 
s_{12}\left[1+f\left(\frac{\sigma_2}{\sigma_1}\right)+f\left(\frac{\sigma_1}{\sigma_2}\right) \right]
+s_{13}\left[1+f\left(\frac{\sigma_3}{\sigma_1}\right)+f\left(\frac{\sigma_1}{\sigma_3}\right)\right] 
&=& \frac{\sigma_1}{\sigma_1+\sigma_2}+\frac{\sigma_1}{\sigma_1+\sigma_3}+f\left(\frac{\sigma_1}{\sigma_2}\right)+f\left(\frac{\sigma_1}{\sigma_3}\right) \\
s_{12}\left[-1-f\left(\frac{\sigma_1}{\sigma_2}\right)-f\left(\frac{\sigma_2}{\sigma_1}\right) \right]
+s_{23}\left[1+f\left(\frac{\sigma_3}{\sigma_2}\right)+f\left(\frac{\sigma_2}{\sigma_3}\right)\right] 
&=& -1 +\frac{\sigma_2}{\sigma_2+\sigma_1}+\frac{\sigma_2}{\sigma_2+\sigma_3}-f\left(\frac{\sigma_1}{\sigma_2}\right)+f\left(\frac{\sigma_2}{\sigma_3}\right) \\
s_{13}\left[-1-f\left(\frac{\sigma_1}{\sigma_3}\right)-f\left(\frac{\sigma_3}{\sigma_1}\right) \right]
+s_{23}\left[-1-f\left(\frac{\sigma_2}{\sigma_3}\right)-f\left(\frac{\sigma_3}{\sigma_2}\right)\right] 
&=& -2 +\frac{\sigma_3}{\sigma_3+\sigma_1}+\frac{\sigma_3}{\sigma_3+\sigma_2}-f\left(\frac{\sigma_1}{\sigma_3}\right)-f\left(\frac{\sigma_2}{\sigma_3}\right) \\
s_{12}\nu \left[-g\left(\frac{\sigma_2}{\sigma_1}\right)+g\left(\frac{\sigma_1}{\sigma_2}\right)\right]+s_{13}\nu\left[-g\left(\frac{\sigma_3}{\sigma_1}\right)+g\left(\frac{\sigma_1}{\sigma_3}\right)\right] &+& s_{23}\nu\left[-g\left(\frac{\sigma_3}{\sigma_2}\right)+g\left(\frac{\sigma_2}{\sigma_3}\right)\right] +T \\
&=&  \nu g\left(\frac{\sigma_1}{\sigma_2}\right) + \nu g\left(\frac{\sigma_1}{\sigma_3}\right)+ \nu g\left(\frac{\sigma_2}{\sigma_3}\right)
\end{eqnarray*}
to put it into the form $Ax=b$.

\begin{prop} The Alternative model is not Consistent when $t=3$, {\em i.e.,} there are balanced designs for which strength parameters do not respect the order of scores.
\end{prop}
{\bf Proof:}
To construct a family of counterexamples, let us first suppose that $\frac{\sigma_1}{\sigma_2}=1$ and $\frac{\sigma_1}{\sigma_3}=5$, which imply that $\frac{\sigma_2}{\sigma_3}=5$, and suppose also that $\nu=4$. We calculate the values needed to construct the coefficients in the linear system as follows.
\begin{eqnarray*}
\frac{\sigma_1}{\sigma_1+\sigma_2}&=&\frac{1}{1+\frac{\sigma_2}{\sigma_1}}=\frac 12\,; \quad \frac{\sigma_1}{\sigma_1+\sigma_3}=\frac{1}{1+\frac{\sigma_3}{\sigma_1}}=\frac 56 \\
\frac{\sigma_2}{\sigma_2+\sigma_1}&=&\frac{1}{1+\frac{\sigma_1}{\sigma_2}}=\frac 12\,; \quad \frac{\sigma_2}{\sigma_2+\sigma_3}=\frac{1}{1+\frac{\sigma_3}{\sigma_2}}=\frac 56 \\
\frac{\sigma_3}{\sigma_3+\sigma_1}&=&\frac{1}{1+\frac{\sigma_1}{\sigma_3}}=\frac 16\,; \quad \frac{\sigma_3}{\sigma_3+\sigma_2}=\frac{1}{1+\frac{\sigma_2}{\sigma_3}}=\frac 16 \\
\end{eqnarray*}
Also, $\phi(x)=2(x-1)+2\sqrt{(x-1)^2+x}$, $\phi'(x)=2+\frac{2x-1}{\sqrt{(x-1)^2+x}}$, and $\phi_{\nu}(x)=(x-1) + \frac{(x-1)^2+\frac{x}{2}  }{\sqrt{(x-1)^2+x}}$, so
\begin{eqnarray*}
\phi\left(\frac 15 \right) &=& -\frac 85 +\frac{2\sqrt{21}}{5} \,,\quad \quad \phi'\left(\frac 15 \right) = 2-\frac{\sqrt{21}}{7} \,,\qquad \phi_{\nu}\left(\frac{1}{5}\right)= -\frac 45 + \frac{37\sqrt{21}}{210} \\
\phi(1) &=&  2 \,,\qquad\qquad\quad \phi'(1)=3\,,\qquad \phi_{\nu}(1)= \frac{1}{2} \\
\phi(5) &=&  8+2\sqrt{21} \,,\qquad \phi'(5)=2+\frac{3\sqrt{21}}{7}\,,\qquad \phi_{\nu}(5)= 4+\frac{37\sqrt{21}}{42}
\end{eqnarray*}
\begin{eqnarray*}
f\left(\frac{\sigma_1}{\sigma_2}\right) = \frac{\frac{\sigma_1}{\sigma_2}\phi'\left(\frac{\sigma_1}{\sigma_2}\right) }{1+\phi\left(\frac{\sigma_1}{\sigma_2}\right)} &=&  1 \,,\qquad f\left(\frac{\sigma_2}{\sigma_1}\right) =\frac{\frac{\sigma_2}{\sigma_1}\phi'\left(\frac{\sigma_2}{\sigma_1}\right)}{1+\phi\left(\frac{\sigma_2}{\sigma_1}\right)}=1 \\
f\left(\frac{\sigma_1}{\sigma_3}\right) = \frac{\frac{\sigma_1}{\sigma_3}\phi'\left(\frac{\sigma_1}{\sigma_3}\right) }{1+\phi\left(\frac{\sigma_1}{\sigma_3}\right)} &=& \frac{5\sqrt{21}}{21} \,,\qquad f\left(\frac{\sigma_3}{\sigma_1}\right) = \frac{\frac{\sigma_3}{\sigma_1}\phi'\left(\frac{\sigma_3}{\sigma_1}\right)}{1+\phi\left(\frac{\sigma_3}{\sigma_1}\right)}=\frac{\sqrt{21}}{21} \\
f\left(\frac{\sigma_2}{\sigma_3}\right) = \frac{\frac{\sigma_2}{\sigma_3}\phi'\left(\frac{\sigma_2}{\sigma_3}\right) }{1+\phi\left(\frac{\sigma_2}{\sigma_3}\right)} &=&  \frac{5\sqrt{21}}{21} \,,\qquad f\left(\frac{\sigma_3}{\sigma_2}\right) =  \frac{\frac{\sigma_3}{\sigma_2}\phi'\left(\frac{\sigma_3}{\sigma_2}\right)}{1+\phi\left(\frac{\sigma_3}{\sigma_2}\right)}=\frac{\sqrt{21}}{21}  \\
\end{eqnarray*}
\begin{eqnarray*}
g\left(\frac{\sigma_1}{\sigma_2}\right) = \frac{\phi_{\nu}\left(\frac{\sigma_1}{\sigma_2}\right) }{1+\phi\left(\frac{\sigma_1}{\sigma_2}\right)} &=&  \frac 16 \,,\qquad g\left(\frac{\sigma_2}{\sigma_1}\right) =\frac{\phi_{\nu}\left(\frac{\sigma_2}{\sigma_1}\right)}{1+\phi\left(\frac{\sigma_2}{\sigma_1}\right)}=\frac 16 \\
g\left(\frac{\sigma_1}{\sigma_3}\right) = \frac{\phi_{\nu}\left(\frac{\sigma_1}{\sigma_3}\right) }{1+\phi\left(\frac{\sigma_1}{\sigma_3}\right)} &=& \frac{1}{3}+\frac{\sqrt{21}}{42} \,,\qquad g\left(\frac{\sigma_3}{\sigma_1}\right) = \frac{\phi_{\nu}\left(\frac{\sigma_3}{\sigma_1}\right)}{1+\phi\left(\frac{\sigma_3}{\sigma_1}\right)}= \frac 13  -\frac{\sqrt{21}}{14}\\
g\left(\frac{\sigma_2}{\sigma_3}\right) = \frac{\phi_{\nu}\left(\frac{\sigma_2}{\sigma_3}\right) }{1+\phi\left(\frac{\sigma_2}{\sigma_3}\right)} &=&  \frac{1}{3}+\frac{\sqrt{21}}{42} \,,\qquad 
g\left(\frac{\sigma_3}{\sigma_2}\right) =  \frac{\phi_{\nu}\left(\frac{\sigma_3}{\sigma_2}\right)}{1+\phi\left(\frac{\sigma_3}{\sigma_2}\right)}=\frac 13  -\frac{\sqrt{21}}{14} \\
\end{eqnarray*}
Finally, the linear system is 
\begin{eqnarray*}
    \left(1+1+1\right)s_{12}+\left(1+\frac{\sqrt{21}}{21}+\frac{5\sqrt{21}}{21} \right)s_{13} &=& 
    \frac 12 +\frac 56 + 1 +  \frac{5\sqrt{21}}{21} \\
    \left(-1-1-1\right)s_{12}+\left(1+\frac{\sqrt{21}}{21}+\frac{5\sqrt{21}}{21} \right)s_{23} &=& -1 +
    \frac 12 +\frac 56 - 1 +  \frac{5\sqrt{21}}{21} \\
    \left(-1-\frac{5\sqrt{21}}{21} -\frac{\sqrt{21}}{21} \right)s_{13}+\left(-1-\frac{5\sqrt{21}}{21} -\frac{\sqrt{21}}{21} \right)s_{23} &=& -2 +
    \frac 16 +\frac 16 - \frac{5\sqrt{21}}{21} -\frac{5\sqrt{21}}{21}  \\
    4\left(\frac 16 - \frac 16 \right)s_{12} + 4\left(\frac 13+\frac{\sqrt{21}}{42} -\frac 13 + \frac{\sqrt{21}}{14}\right)s_{13} + 4\left(\frac 13+\frac{\sqrt{21}}{42} -\frac 13 + \frac{\sqrt{21}}{14}\right)s_{23} &+& \\
    T &=& 4\left(\frac 16 + \frac 13 +\frac{\sqrt{21}}{42} + \frac 13 +\frac{\sqrt{21}}{42}\right)
\end{eqnarray*}
which reduces to $Ax=b$ with
$$ A=\left[\begin{array}{cccc}
3 & \left(1+\frac{2\sqrt{21}}{7}\right)  & 0 & 0 \\
-3 & 0 & \left(1+\frac{2\sqrt{21}}{7}\right) & 0 \\
0 & \left(-1-\frac{2\sqrt{21}}{7}\right) & \left(-1-\frac{2\sqrt{21}}{7}\right) & 0 \\
0 & \left(\frac{8\sqrt{21}}{21}\right) &  \left( \frac{8\sqrt{21}}{21}\right) & 1
\end{array}\right]\,,\quad x=\left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right]\,, \quad b=\left[\begin{array}{c} \left(\frac{7}{3}+\frac{5\sqrt{21}}{21}\right) \\ \left(-\frac 23 +\frac{5\sqrt{21}}{21}\right) \\ \left(-\frac{5}{3} -\frac{10\sqrt{21}}{21}\right) \\ \left(\frac{10}{3} + \frac{4\sqrt{21}}{21}\right) \end{array}\right]  $$
As anticipated, the third equation is dependent on the first two, so we can write the system as
$$ \left[\begin{array}{cccc}
3 & \left(1+\frac{2\sqrt{21}}{7}\right)  & 0 & 0 \\
-3 & 0 & \left(1+\frac{2\sqrt{21}}{7}\right) & 0 \\
0 & \left(\frac{8\sqrt{21}}{21}\right) &  \left( \frac{8\sqrt{21}}{21}\right) & 1
\end{array}\right] \left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right] = \left[\begin{array}{c} \left(\frac{7}{3}+\frac{5\sqrt{21}}{21}\right) \\ \left(-\frac 23 +\frac{5\sqrt{21}}{21}\right) \\ \left(\frac{10}{3} + \frac{4\sqrt{21}}{21}\right) \end{array}\right]  $$
and its solution is
$$ x = \left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right] = \left[\begin{array}{c} \left(\frac{2}{9}-\frac{5\sqrt{21}}{63}\right)\\ \left(\frac 53\right) \\ 0 \\ \left(\frac{10}{3} -\frac{28\sqrt{21}}{63}\right) \end{array}\right] +u\left[\begin{array}{c}\left( \frac 13 +\frac{2\sqrt{21}}{21}\right) \\ -1 \\ 1 \\ 0 \end{array}\right] $$
for arbitrary parameter $u\in [\frac 23,1]$ (to keep each $s_{ij}\in [0,1]$). When $u=\frac 23$, we have solution 
$$ \left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right] = \left[\begin{array}{c} \left(\frac{4}{9}-\frac{\sqrt{21}}{63}\right)\\ 1  \\ \frac 23 \\ \left(\frac{10}{3} -\frac{28\sqrt{21}}{63}\right) \end{array}\right] $$
and when $u=1$, we have solution
$$ \left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right] = \left[\begin{array}{c} \left(\frac{5}{9}+\frac{\sqrt{21}}{63}\right)\\ \frac 23  \\ 1 \\ \left(\frac{10}{3} -\frac{28\sqrt{21}}{63}\right) \end{array}\right]\,. $$
Note that 
$$ s_1=s_{12}+s_{13}=\left(\frac{17}{9} - \frac{5\sqrt{21}}{63}\right)+ \left(-\frac 23 +\frac{2\sqrt{21}}{21}\right)u$$ 
and 
$$ s_2=1-s_{12}+s_{23}=\left(\frac{7}{9}+\frac{5\sqrt{21}}{63}\right)+\left(\frac 23 -\frac{2\sqrt{21}}{21}\right)u\,. $$
% When $u=\frac 23$ we have 
% $$ s_1 = \frac{13}{9}-\frac{\sqrt{21}}{63}\,,\quad s_2 = \frac{11}{9}+\frac{\sqrt{21}}{63}\,,$$
% and when $u=1$ we have
% $$ s_1 = \frac{11}{9}+\frac{\sqrt{21}}{63}\,,\quad s_2 = \frac{13}{9}-\frac{\sqrt{21}}{63}\,. $$
% In fact,
Thus,
$$ s_1-s_2 = \left(\frac {10}{9} -\frac{10\sqrt{21}}{63}\right)+\left(-\frac 43 +\frac{4\sqrt{21}}{21}\right)u\,,
$$
which for $u\in[\frac 23,1]$ means
$$ s_1-s_2 \in \left[-\frac 29 +\frac{2\sqrt{21}}{63},\quad \frac 29 - \frac{2\sqrt{21}}{63}\right]\approx [-0.0767,0.0767]\,.$$
Alternatively, 
$$ \frac{s_1}{s_2} \in \left[\frac{251+6\sqrt{21}}{295}, \frac{251-6\sqrt{21}}{211}\right]\approx [0.9441,1.0593]\,.$$
This means that even though $\sigma_1=\sigma_2$, there can be a positive or negative difference between $s_1$ and $s_2$.
If we perturb $\frac{\sigma_1}{\sigma_2}$ slightly from $1$, we can get a choice of scores in the opposite order to the strength parameters.

For example, if we let $\frac{\sigma_1}{\sigma_2}=\frac{24}{25}=0.96$, we can follow the same computations as above to find 
$$ x = \left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right] \approx \left[\begin{array}{c} -23.7321 \\ 32.2866 \\ -30.7852 \\ 0 \end{array}\right] +u\left[\begin{array}{c} 18.8289 \\ -24.4503 \\ 24.5831 \\ 1 \end{array}\right] $$
where we must have $u\in [1.2796, 1.2930]$. 
At $u=1.2796$, we have solution 
\begin{equation} \left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right] = \left[\begin{array}{c} 0.3614  \\ 1  \\ 0.6714 \\ 1.2796 \end{array}\right] \label{eq:solution}
\end{equation}
and at $u=1.2930$, we have solution 
$$ \left[\begin{array}{c} s_{12} \\ s_{13} \\ s_{23} \\T \end{array}\right] = \left[\begin{array}{c} 0.6132  \\ 0.6731  \\ 1 \\ 1.2930 \end{array}\right]\,. $$
Now, 
$$ \frac{s_1}{s_2}=\frac{s_{12}+s_{13}}{1-s_{12}+s_{23}} \in [0.9275,1.03935]\,,$$
and, in particular, if we take $u=1.2796$, we have $\frac{s_1}{s_2}=1.03935$, whereas we took $\frac{\sigma_1}{\sigma_2}=0.96$. So it is possible for scores ordered such that $s_1>s_2$ to nevertheless produce strength estimates such that $\sigma_1<\sigma_2$.

To concretize this last example, we can approximate the scores by actual numbers of wins and draws between players, and calculate the maximum likelihood estimates for the parameters in the usual forwards way. We use $n=100$ now, rather then $n=1$ to allow for integer numbers of wins and draws.

Let 
\begin{equation} (w_{ij}) = \left[\begin{array}{ccc}
0 & 4 & 100 \\
32 & 0 & 35 \\
0 & 1 & 0
\end{array}\right]\,,\quad (t_{ij})=\left[\begin{array}{ccc}
0 & 64 & 0 \\
64 & 0 & 64 \\
0 & 64 & 0
\end{array}\right]\,,\quad (s_{ij})=(w_{ij})+\frac 12 (t_{ij})=\left[\begin{array}{ccc}
0 & 36 & 100 \\
64 & 0 & 67 \\
0 & 33 & 0
\end{array}\right]\,,
\label{counterexample}
\end{equation}
corresponding to~\eqref{eq:solution},
and the total scores for each player are
$$ (s_1,s_2,s_3)=(136, 131, 33)\,.$$
Then, running the iteration~\eqref{iteration_alternative_practical} gives (normalized so that $\sum_i\sigma_i=1$):
$$ \sigma_1 = 0.4456, \quad \sigma_2 = 0.4648, \quad \sigma_3 = 0.0896, \quad \nu=3.9769$$
so that 
$$ \frac{\sigma_1}{\sigma_2}= 0.9586, \quad \frac{\sigma_1}{\sigma_3}=4.9725, \quad \frac{\sigma_2}{\sigma_3}=5.1871\,.$$
Thus, $s_1>s_2$, but $\sigma_1 < \sigma_2$. \qed


\subsection{Balanced tournaments with four or more players}
When $t=4$, there are $t=4$ in independent parameters, and $\frac 12 t(t-1)+1=7$ independent data values in the system of maximum-likelihood equations. Thus, there is now a $3$-dimensional family of data values, all of which predict the same set of parameters, $(\bm{\sigma},\nu)$. This gives even more room to find sets of data values such that scores are not ordered with strength parameters. Following a procedure similar to that of Section~\ref{sec:3player}, we find the following example, again with $n=100$.

Let 
$$ (w_{ij}) = \left[\begin{array}{cccc}
0 & 16 & 6 & 35 \\
1 & 0 & 36 & 53 \\
1 & 1 & 0 & 2 \\
1 & 1 & 1 & 0
\end{array}\right]\,,\quad (t_{ij})=\left[\begin{array}{cccc}
0 & 83 & 93 & 64 \\
83 & 0 & 63 & 46 \\
93 & 63 & 0 & 97 \\
64 & 46 & 97 & 0
\end{array}\right]\,,\quad (s_{ij})=(w_{ij})+\frac 12 (t_{ij})=\left[\begin{array}{cccc}
0 & 57.5 & 52.5 & 67 \\
42.5 & 0 & 67.5 & 76 \\
47.5 & 32.5 & 0 & 50.5 \\
33 & 24 & 49.5 & 0
\end{array}\right]$$
and the total scores for each player are
$$ (s_1,s_2,s_3,s_4)=(177, 186, 130.5,106.5)\,.$$
Then, running the iteration~\eqref{iteration_alternative_practical} gives (normalized so that $\sum_i\sigma_i=1$):
$$ \sigma_1 = 0.3370, \quad \sigma_2 = 0.3188, \quad \sigma_3 = .1873, \quad \sigma_4 = .1570, \quad \nu=16.1409\,.$$
%so that 
%$$ \frac{\sigma_1}{\sigma_2}= 1.0571\,.$$
Thus, $s_1<s_2$, but $\sigma_1 > \sigma_2$.

For tournaments with more players, there are even more extra degrees of freedom in the scores, as a result of the fact that the maximum likelihood equations depend on the individual $s_{ij}$, not just the total player scores, $s_i$. One might consider trying a model with more parameters, such as a draw-propensity parameter, $\nu_i$ for each player, and letting $d_{ij}=\sqrt{\nu_i \nu_j}\sqrt{p_{ij}p_{ji}}$, but this only doubles the number of parameters, whereas the number of data values grows quadratically. In order to have enough parameters to match this growth, one might consider a model with a different draw propensity for each pair of players $\nu_{ij}=\nu_{ji}$. However, then the maximum likelihood equations involve the individual $t_{ij}$ as well as $s_{ij}$, so there are still not enough parameters.

\section{Reassessment}\label{sec:reassessment}
It is important to note that when $\nu=2$, the Alternative model is equivalent to the Davidson model by a scaling, as shown in Equations~\eqref{SigmaRatioSimple} and \eqref{pijEdwardsSimple}. Thus, in this case, the Alternative model has no problem with inconsistency of ordering of strength parameters by scores in balanced tournaments. Property~\ref{consistency_property} holds for the Alternative model when $\nu=2$.

In fact, we argue that $\nu=2$ is the correct value to use in estimating player strengths. Davidson's model promises to estimate both strength parameters and draw propensity at the same time from the same set of data. In the Alternative model, we corrected for Davidson's first flawed assumption, by assuming strength ratios depended on score ratios, Property~\ref{alt_strength_ratio}, not just win ratios, Property~\ref{Luce_Condition}, but we still tried to estimate the draw-propensity parameter at the same time as the strength parameters. The unrealistic implication is that strength parameters do not depend only on scores, but also on draw propensity (and thus, numbers of draws that make up the scores). It can reasonably be argued that two draws are equivalent to a win and a loss between a pair of players in assessing relative strength, so that a score of $+2-1=2$ should give the same assessment as $+3-2=0$, even though the draw propensity is clearly different. When $\nu=2$, a pair of draws is treated exactly the same as a win and a loss (one could even say that a draw was treated as half a win). This is essentially what Glickman assumed in his 1999 paper~\cite{Glickman1999}, but now we have a justification for this in the context of a model with a draw-propensity parameter, via Equation~\eqref{pijEdwardsSimple}. Glickman argued that a draw should count as a half-win followed by a half-loss, and so that if $p$ is the probability of a win by the first player, a single draw should contribute a term $\sqrt{p(1-p)}$ to the likelihood function. In fact, it should contribute $2\sqrt{p(1-p}$ to indclude the possibilities of a win followed by a loss (10) and a loss followed by a win (01). In our model, when $\nu=2$, we have $d_{ij}=\frac{2\sigma_i\sigma_j}{(\sigma_i+\sigma_j)^2}=2\sqrt{p_{ij}p_{ji}}$, which is twice the probability of a win and a loss in the Bradley-Terry model.
%Although not spelled out there, this $p$ must then mean the probability of a won game plus half the probability of a drawn game, as in our model.
%But fixing $\nu=2$ in the Davidson model or the Alternative model, does not allow estimation of draw propensity.

\subsection{Constrained Alternative (and Constrained Davidson) model}
Fixing $\nu=2$ for the estimation of strength parameters does not in itself allow for estimation of draw propensity, which we still require. But draw propensity should be estimated using meaningful strength parameters.

We argue, therefore, that a more correct procedure is to constrain the Alternative model to $\nu=2$ for the estimation of strength parameters, and thus iterate via
\begin{eqnarray*}
    \sigma_k &\leftarrow& \frac{s_k}{G_k(\bm{\sigma},2)}\,,\quad k=1,\ldots,t, \\
    \nu &\leftarrow& \frac{T}{H(\bm{\sigma}, \nu)}\,.
\end{eqnarray*} 
This procedure effectively estimates strength parameters with $\nu$ fixed at $2$, as it should, and then keeping the resulting strength parameters now fixed, estimates the value of $\nu$ that maximizes the likelihood for this (correct) set of strength parameters.
Note that the two stages of the estimation here use different likelihood functions. The first uses $L(\bm{\sigma},2)$, the likelihood of the observed results when $\nu=2$, to get an estimate $\bm{\sigma}=\bm{\hat{\sigma}}$, and the second stage uses $L(\bm{\hat{\sigma}},\nu)$ to estimate $\nu$. The first stage is exactly the Bradley-Terry model considering each comparison to be two comparisons, such that draws are $10$ (win+loss), while wins are $11$, and losses are $00$. The unconstrained likelihood function $L(\bm{\sigma},\nu)$ allows for too much freedom and sets of parameters that are not sensible. Finally, it is clear that the issue of convergence of the iteration, which we avoided in Section~\ref{sec:alternative_likelihood}, is not a problem when $\nu=2$, since the Bradley-Terry and Davidson methods are known to be convergent.

Of course, the same procedure could be applied to the Davidson model: use $\nu=2$ to estimate strength parameters, $\bm{\pi}$, and then use the resulting strength parameters to estimate $\nu$. Thus, we have four models to evaluate: the unconstrained Davidson model, the Constrained Davidson model (with $\nu=2$ fixed for the strength parameter calculation), the unconstrained Alternative model, and the Constrained Alternative model.

\section{Test cases for the four models} \label{sec:tests}

\subsection{Test 1}
The following test case is instructive.
$$(w_{ij})=\left[\begin{array}{cc} 0 & 1+\epsilon \\ \epsilon & 0\end{array}\right] \,,\quad (t_{ij})=\left[\begin{array}{cc} 0 & 4-2\epsilon \\ 4-2\epsilon & 0\end{array}\right]\quad \implies \quad (s_{ij})=\left[\begin{array}{cc} 0 & 3 \\ 2 & 0\end{array}\right] $$ 
with $\epsilon$ going from $2$ down to $0$.

For the {\bf Davidson model}, the maximum log-likelihood equations are
\begin{eqnarray*}
\frac{\partial}{\partial \pi_1}\log(L) &=& \frac{3}{\pi_1}-\frac{5\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_2}{\pi_1}}\right)}{\pi_1+\pi_2+\nu\sqrt{\pi_1\pi_2}} = 0 \\
\frac{\partial}{\partial \pi_2}\log(L) &=& \frac{2}{\pi_2}-\frac{5\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_1}{\pi_2}}\right)}{\pi_1+\pi_2+\nu\sqrt{\pi_1\pi_2}} = 0 \\
\frac{\partial}{\partial \nu}\log(L) &=& \frac{4-2\epsilon}{\nu}-\frac{5\left(\sqrt{\pi_1\pi_2}\right)}{\pi_1+\pi_2+\nu\sqrt{\pi_1\pi_2}} = 0 \\
\end{eqnarray*}
but the first two are necessarily equivalent.
% The first and third give:
% $$ 1+\frac{\pi_2}{\pi_1}+\nu\sqrt{\frac{\pi_2}{\pi_1}}=\frac{5}{3}\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_2}{\pi_1}}\right) = \frac{5}{4-2\epsilon}\nu\sqrt{\frac{\pi_2}{\pi_1}}$$
% So
% $$\frac 13 =\left(\frac{1}{4-2\epsilon}-\frac{1}{6}\right)\nu\sqrt{\frac{\pi_2}{\pi_1}}$$
% or
% $$\frac{4-2\epsilon}{1+\epsilon}=\nu\sqrt{\frac{\pi_2}{\pi_1}}$$
The second and third give:
$$ \frac{\pi_1}{\pi_2}+1+\nu\sqrt{\frac{\pi_1}{\pi_2}}=\frac{5}{2}\left(1+\frac{\nu}{2}\sqrt{\frac{\pi_1}{\pi_2}}\right) = \frac{5}{4-2\epsilon}\nu\sqrt{\frac{\pi_1}{\pi_2}}$$
So
$$\frac 12 =\left(\frac{1}{4-2\epsilon}-\frac{1}{4}\right)\nu\sqrt{\frac{\pi_1}{\pi_2}}$$
or
$$\frac{4-2\epsilon}{\epsilon}=\nu\sqrt{\frac{\pi_1}{\pi_2}}$$
and
$$\frac{\pi_1}{\pi_2}+1+\frac{4-2\epsilon}{\epsilon}=\frac{5}{\epsilon}$$
or
$$ \frac{\pi_1}{\pi_2}=\frac{1+\epsilon}{\epsilon}$$
which $\to \infty$ as $\epsilon\to 0$. Also, then
$$\nu=\frac{4-2\epsilon}{\epsilon}\sqrt{\frac{\epsilon}{1+\epsilon}}=\frac{4-2\epsilon}{\sqrt{\epsilon}\sqrt{1+\epsilon}}$$
which also $\to\infty$ as $\epsilon\to 0$. Finally,
\begin{eqnarray*} 
p_{12} &=& \frac{\frac{\pi_1}{\pi_2}}{\frac{\pi_1}{\pi_2}+1+\nu\sqrt{\frac{\pi_1}{\pi_2}}} = \frac{\frac{1+\epsilon}{\epsilon}}{\frac{1+\epsilon}{\epsilon}+1+\frac{4-2\epsilon}{\epsilon}} = \frac{1+\epsilon}{1+\epsilon+\epsilon+4-2\epsilon}=\frac{1+\epsilon}{5} \\
p_{21} &=& \frac{1}{\frac{\pi_1}{\pi_2}+1+\nu\sqrt{\frac{\pi_1}{\pi_2}}} = \frac{1}{\frac{1+\epsilon}{\epsilon}+1+\frac{4-2\epsilon}{\epsilon}} = \frac{\epsilon}{1+\epsilon+\epsilon+4-2\epsilon}=\frac{\epsilon}{5} \\
d_{12} &=& \frac{\nu\sqrt{\frac{\pi_1}{\pi_2}}}{\frac{\pi_1}{\pi_2}+1+\nu\sqrt{\frac{\pi_1}{\pi_2}}} = \frac{\frac{4-2\epsilon}{\epsilon}}{\frac{1+\epsilon}{\epsilon}+1+\frac{4-2\epsilon}{\epsilon}} = \frac{4-2\epsilon}{1+\epsilon+\epsilon+4-2\epsilon}=\frac{4-2\epsilon}{5}\,. \\
\end{eqnarray*}
Thus, as $\epsilon\to 0$, the probabilities approach $p_{12}=\frac 15$, $p_{21}=0$, and $d_{12}=\frac 45$, corresponding to the scores, $w_{12}=1$, $w_{21}=0$, and $t_{12}=4$ as expected, but at the cost of an infinite separation in player strengths, which does not correspond to the fact that the players' scores were $s_1=3$ and $s_2=2$ (regardless of the value of $\epsilon$ here).

For the {\bf Constrained Davidson model} ($\nu=2$ to estimate strength parameters), the maximum log-likelihood equations are
\begin{eqnarray*}
\frac{\partial}{\partial \pi_1}\log(L) &=& \frac{3}{\pi_1}-\frac{5\left(1+\sqrt{\frac{\pi_2}{\pi_1}}\right)}{\pi_1+\pi_2+2\sqrt{\pi_1\pi_2}} = 0 \\
\frac{\partial}{\partial \pi_2}\log(L) &=& \frac{2}{\pi_2}-\frac{5\left(1+\sqrt{\frac{\pi_1}{\pi_2}}\right)}{\pi_1+\pi_2+2\sqrt{\pi_1\pi_2}} = 0 \\
\frac{\partial}{\partial \nu}\log(L) &=& \frac{4-2\epsilon}{\nu}-\frac{5\left(\sqrt{\pi_1\pi_2}\right)}{\pi_1+\pi_2+\nu\sqrt{\pi_1\pi_2}} = 0 \\
\end{eqnarray*}
but, again, the first two are necessarily equivalent. The first gives
$$ \frac{\pi_1}{\pi_2}+1+2\sqrt{\frac{\pi_1}{\pi_2}}=\frac{5}{3}\left(\frac{\pi_1}{\pi_2}+\sqrt{\frac{\pi_1}{\pi_2}}\right) $$
So
$$\frac 23 \frac{\pi_1}{\pi_2}-\frac 13 \sqrt{\frac{\pi_1}{\pi_2}} = 1 = 0$$
and
$$ \sqrt{\frac{\pi_1}{\pi_2}} = \frac 12\left(\frac 12 \pm \sqrt{\frac 14 + 6}\right) =\frac 32$$
(we must pick the plus sign here) so that 
$$ \frac{\pi_1}{\pi_2}=\frac 94 \,. $$
The third equation gives
$$ \frac{\pi_1}{\pi_2}+1+\nu\sqrt{\frac{\pi_1}{\pi_2}}=\frac{5}{4-2\epsilon}\nu\sqrt{\frac{\pi_1}{\pi_2}} $$
which at $\frac{\pi_1}{\pi_2}=\frac 94$ is
$$ \frac 32\left(\frac{1+2\epsilon}{4-2\epsilon}\right)\nu=\frac 94+1 $$
so
$$ \nu = \frac{13}{6}\left(\frac{4-2\epsilon}{1+2\epsilon}\right) $$
which converges, as $\epsilon\to 0$, to $\frac{26}{3}$.  Here, 
\begin{eqnarray*} 
p_{12} &=& \frac{\frac{9}{4}}{\frac{9}{4}+1+\frac{13}{6}\left(\frac{4-2\epsilon}{1+2\epsilon}\right)\frac 32}=\frac{9}{13\left(1+\frac{4-2\epsilon}{1+2\epsilon}\right)}=\frac{9(1+2\epsilon)}{65} \\
p_{21} &=& \frac{1}{\frac{9}{4}+1+\frac{13}{6}\left(\frac{4-2\epsilon}{1+2\epsilon}\right)\frac 32}=\frac{4}{13\left(1+\frac{4-2\epsilon}{1+2\epsilon}\right)}=\frac{4(1+2\epsilon)}{65} \\
d_{12} &=& \frac{\frac{13}{6}\left(\frac{4-2\epsilon}{1+2\epsilon}\right)\frac 32}{\frac{9}{4}+1+\frac{13}{6}\left(\frac{4-2\epsilon}{1+2\epsilon}\right)\frac 32}=\frac{13\left(\frac{4-2\epsilon}{1+2\epsilon}\right)}{13\left(1+\frac{4-2\epsilon}{1+2\epsilon}\right)}=\frac{13(4-2\epsilon)}{65} 
\end{eqnarray*}
which converge as $\epsilon\to 0$ to $\frac{9}{65}$, $\frac{4}{65}$ and $\frac{52}{65}$, respectively.

For the {\bf Alternative model}, we already know by Proposition~\ref{prop:2player}, that $\frac{\sigma_1}{\sigma_2}=\frac{s_1}{s_2}$, which here is $\frac 32$. Note that this is true for any value of $\nu$.
The third maximum log-likelihood equation is now
\begin{eqnarray*}
\frac{\partial}{\partial \nu}\log(L) &=& \frac{4-2\epsilon}{\nu}-\frac{3\phi_{\nu}\left(\frac{\sigma_2}{\sigma_1}\right)}{1+\phi\left(\frac{\sigma_2}{\sigma_1}\right)} - \frac{2\phi_{\nu}\left(\frac{\sigma_1}{\sigma_2}\right)}{1+\phi\left(\frac{\sigma_1}{\sigma_2}\right)} 
=\frac{4-2\epsilon}{\nu}-\frac{3\phi_{\nu}\left(\frac 23 \right)}{1+\phi\left(\frac 23\right)} - \frac{2\phi_{\nu}\left(\frac 32 \right)}{1+\phi\left(\frac 32 \right)}=0 \\
\end{eqnarray*}
or
$$ (4-2\epsilon) -\nu H(\nu) = (4-2\epsilon) -\nu\left(\frac{3\phi_{\nu}\left(\frac 23 \right)}{1+\phi\left(\frac 23\right)} + \frac{2\phi_{\nu}\left(\frac 32 \right)}{1+\phi\left(\frac 32 \right)}\right)=0$$
The left-hand side function here is a strictly positive function of $\nu$ when $\epsilon=0$, so there is no maximum, but has a zero when $0<\epsilon\le 2$. The proof of this requires only the algebra to show that 
\begin{equation}
\nu H(\nu) = \nu\left(\frac{3\phi_{\nu}\left(\frac 23 \right)}{1+\phi\left(\frac 23\right)} + \frac{2\phi_{\nu}\left(\frac 32 \right)}{1+\phi\left(\frac 32 \right)}\right)= \frac{\frac{5}{4}\nu^2+\frac{\nu}{4}\sqrt{\nu^2+96}}{1+\frac{13}{48}\nu^2+\frac{5}{48}\nu\sqrt{\nu^2+96}}\,, \label{nuHnu}
\end{equation}
which is $0$ at $\nu=0$ with $\lim_{\nu\to\infty}\nu H(\nu) = 4 $,
and to show that 
$$ \frac{\partial}{\partial\nu} (\nu H(\nu)) = \frac{\partial}{\partial\nu} \left(\frac{\frac{5}{4}\nu^2+\frac{\nu}{4}\sqrt{\nu^2+96}}{1+\frac{13}{48}\nu^2+\frac{5}{48}\nu\sqrt{\nu^2+96}}\right)=\frac{24+\frac{13}{2}\nu^2+\frac{5}{2}\nu\sqrt{\nu^2+96}}{\left[1+\frac{13}{48}\nu^2+\frac{5}{48}\nu\sqrt{\nu^2+96}\right]^2 \sqrt{\nu^2+96}}>0\,.  $$
Thus, our estimate of $\nu\to\infty$ as $\epsilon\to 0$. In fact, the maximum likelihood estimate is 
\begin{equation}
    \nu = \frac{4-2\epsilon}{\sqrt{\epsilon(\epsilon+1)}}\,, \label{nu_Alternative}
\end{equation}
which can be verified by inserting~\eqref{nu_Alternative} into Equation~\eqref{nuHnu} to get $\nu H(\nu)=4-2\epsilon$.

Now, with this value of $\nu$,
\begin{eqnarray*}
p_{12} &=& \left(\frac{1}{1+\frac{\sigma_2}{\sigma_1}}\right)\left(\frac{1}{1+\phi\left(\frac{\sigma_2}{\sigma_1}\right)}\right)=\left(\frac{1}{1+\frac 23}\right)\left(\frac{1}{1+\phi\left(\frac 23\right)}\right)=\left(\frac 35\right)\left(\frac{1}{1+\frac{\nu}{24}\left(-\nu+\sqrt{\nu^2+96}\right)}\right)=\frac{\epsilon+1}{5} \\
p_{21} &=& \left(\frac{1}{1+\frac{\sigma_1}{\sigma_2}}\right)\left(\frac{1}{1+\phi\left(\frac{\sigma_1}{\sigma_2}\right)}\right)=\left(\frac{1}{1+\frac 32}\right)\left(\frac{1}{1+\phi\left(\frac 32\right)}\right)=\left(\frac 25\right)\left(\frac{1}{1+\frac{\nu}{16}\left(\nu+\sqrt{\nu^2+96}\right)}\right)=\frac{\epsilon}{5} \\
d_{12} &=& 1-p_{12}-p_{21} = \frac{4-2\epsilon}{5}\,. \\
\end{eqnarray*}

For the {\bf Constrained Alternative Model},  we still have $\frac{\sigma_1}{\sigma_2}=\frac{s_1}{s_2}=\frac 32$, since this is true for any $\nu$, including $\nu=2$. Thus, we again estimate $\nu$, $p_{12}$, $p_{21}$, and $d_{12}$ as for the unconstrained Alternative Model.

