\section{Incidence and adjacency matrices}
\label{app:matrices}

Assigning orientations to all quantities, signed incidence matrices $\mathsf{A}$, $\mathsf{B}$ and $\mathsf{C}$ with components $C_{hi}=\{\mathsf{C}\}_{hi}$, $B_{ij}=\{\mathsf{B}\}_{ij}$ and $A_{jk}=\{\mathsf{A}\}_{jk}$ define topological arrangements.  Specifically, an edge orientation is defined by a tangent with magnitude equal to the edge length; a face orientation is defined by a normal with magnitude equal to the face area; $C_{hi}=1$ ($-1$) if the normal to face $i$ points into (out of) cell $h$; $B_{ij}=1$ ($-1$) if edge $j$ bounds face $i$ and is congruent (or anticongruent) to its orientation in a right-handed sense; $A_{jk}=1$ ($-1$) if edge $j$ points into (out of) vertex $k$.  The components of $\mathsf{A}$, $\mathsf{B}$ and $\mathsf{C}$ are zero otherwise. 

$\mathsf{A}$ includes a sub-block $\mathsf{A}^{++}$ connecting $N_e^+$ apical edges to $N_v^+$ apical vertices; $\mathsf{B}$ has sub-blocks $\mathsf{B}^{++}$ connecting $N_f^+$ apical faces to $N_e^+$ apical edges and $\mathsf{B}^{l+}$ connecting $N_f^l$ lateral faces to $N_e^+$ apical edges; and $\mathsf{C}$ has a blocks $\mathsf{C}^+$ and $\mathsf{C}^l$ connecting  to $N_c$ cells to $N_f^+$ apical and $N_f^l$ lateral faces, respectively.  Thus
\begin{subequations}
\begin{align}
    \mathsf{A}&=\left(\begin{matrix}\mathsf{A}^{++} & \mathsf{0} \\ \mathsf{A}^{l+} & \mathsf{A}^{l-} \\ \mathsf{0} & \mathsf{A}^{--}\end{matrix}\right),\\
    \mathsf{B}&=\left(\begin{matrix}\mathsf{B}^{++} & \mathsf{0} & \mathsf{0} \\ \mathsf{B}^{l+} & \mathsf{B}^{ll} & \mathsf{B}^{l-} \\ \mathsf{0} & \mathsf{0} & \mathsf{B}^{--}\end{matrix}\right), \\
    \mathsf{C}&=\left(\begin{matrix}\mathsf{C}^{+} & \mathsf{C}^{l} & \mathsf{C}^{-} \end{matrix}\right).
\end{align}
\end{subequations}
 The requirements that $\mathsf{C}\mathsf{B}=\mathsf{0}$ and $\mathsf{B}\mathsf{A}=\mathsf{0}$, arising because the 3D network is bounded by closed faces, imply
\begin{subequations}
    \begin{align}
    \left(\begin{matrix}
    \mathsf{C}^+\mathsf{B}^{++}+\mathsf{C}^l\mathsf{B}^{l+} &
    \mathsf{C}^l\mathsf{B}^l &
    \mathsf{C}^-\mathsf{B}^{--}+\mathsf{C}^l\mathsf{B}^{l-} 
    \end{matrix}\right)&=\mathsf{0}, \\
    \left(\begin{matrix}
    \mathsf{B}^{++}\mathsf{A}^{++} & \mathsf{0} \\
    \mathsf{B}^{l+}\mathsf{A}^{++} +\mathsf{B}^{ll}\mathsf{A}^{l+} &
    \mathsf{B}^{l-}\mathsf{A}^{--} +\mathsf{B}^{ll}\mathsf{A}^{l-} \\
    \mathsf{0} & \mathsf{B}^{--}\mathsf{A}^{--} 
    \end{matrix}\right)&=\mathsf{0}. 
\end{align}
\end{subequations}
The apical matrices $\mathsf{C}^+\mathsf{B}^{++}$ and $\mathsf{A}^{++}$
are the 3D analogues of the  face-edge and edge-vertex incidence matrices used in prior 2D studies \cite{jensen2020, jensen2023, cowley2024}; they satisfy the requirement that $(\mathsf{C}^+\mathsf{B}^{++})\mathsf{A}^{++}=\mathsf{0}$.  A 2D topological cell Laplacian is then
\begin{equation}
\mathcal{L}\equiv -\mathsf{C}^+\mathsf{B}^{++}\mathsf{E} \mathsf{B}^{++\top} \mathsf{C}^{+\top}.   
\label{eq:lap}
\end{equation}
This is regularised, as in \cite{jensen2023}, by taking $\mathsf{E}$ to be a diagonal $N_e\times N_e$ matrix for which $E_{jj}=1$ unless $j$ labels a peripheral apical edge of a peripheral cell in an isolated monolayer, in which case $E_{jj}=0$.  This regularisation ensures that $\mathcal{L}\mathsf{1}_c=0$, where $\mathsf{1}_c=(1,1,\dots)$ is the chain identifying all cells in a monolayer.

The adjacency matrices connecting vertices, edges, faces and cells are 
\begin{subequations}
\label{eq:adj}
\begin{align}
D^{\mathrm{cv}}_{hk}&\equiv\tfrac{1}{6}{\textstyle{\sum_{i,j}}}\vert C_{hi}\vert \vert B_{ij} \vert \vert A_{jk}\vert, &D^{\mathrm{ev}}_{jk}&\equiv\vert A_{jk}\vert
\\
D^{\mathrm{ce}}_{hj}&\equiv\tfrac{1}{2}{\textstyle{\sum_{i}}}\vert C_{hi}\vert \vert B_{ij} \vert, & D^{\mathrm{fe}}_{ij}&\equiv\vert B_{ij} \vert, \\
D^{\mathrm{fv}}_{ik}&\equiv\tfrac{1}{2}{\textstyle{\sum_{j}}} \vert B_{ij} \vert \vert A_{jk}\vert, & D^{\mathrm{cf}}_{hi}&\equiv\vert C_{hi}\vert.
\end{align}
\end{subequations}
The factor $\tfrac{1}{6}$ in $\mathsf{D}^{\mathrm{cv}}$ accounts for the fact that each vertex $k$ of cell $h$ neighbours three edges of the cell and each edge bounds two faces of the cell.  For the prismatic cells illustrated Fig.~\ref{fig:schematic}, distinguishing apical ($+$), lateral $(l)$ and basal $(-)$ objects, the adjacency matrices inherit the structure of the incidence matrices via
\begin{subequations}
\begin{align}
    \mathsf{D}^{\mathrm{fv}}&=\left(\begin{matrix}\mathsf{D}^{\mathrm{fv}++} & \mathsf{0} \\ \mathsf{D}^{\mathrm{fv},l+} & \mathsf{D}^{\mathrm{fv},l-} \\ \mathsf{0} & \mathsf{D}^{\mathrm{fv}--}\end{matrix}\right), \\
    \mathsf{D}^{\mathrm{ce}}&=\left(\begin{matrix}\mathsf{D}^{\mathrm{ce}+} & \mathsf{D}^{\mathrm{ce},l} & \mathsf{D}^{\mathrm{ce}-}\end{matrix}\right), \\
        \mathsf{D}^{\mathrm{cv}}&=\left(\begin{matrix} \mathsf{D}^{\mathrm{cv}+} & \mathsf{D}^{\mathrm{cv}-}\end{matrix}\right).
\end{align}
\end{subequations}

\section{Geometric identities}
\label{app:geom}

Given vertex locations $\mathbf{r}_k^\pm$, we construct apical cell edge tangents and centroids using 
\begin{equation}
    \mathbf{t}^+_j={\textstyle \sum_j} A_{jk}^{++}\mathbf{r}_k^+, \quad
    \mathbf{c}^+_j=\tfrac{1}{2}{\textstyle \sum_j} \vert A_{jk}^{++}\vert \mathbf{r}_k^+
    \label{eq:edges}
\end{equation}
respectively.  The apical perimeter and apical area of cell $h$ are then, respectively, for $h=1,\dots, N_c$
\begin{subequations}
    \label{eq:la}    
\begin{align}
    L_h^+&=\textstyle{\sum_{i,j}} \vert C_{hi}^l \vert \vert B_{ij}^{l+} \vert \vert\mathbf{t}^+_j\vert, \\
    A_h^+&=\tfrac{1}{2}{\textstyle{\sum_{i,j}}} \vert C_{hi}^+\vert B_{ij}^{++} \mathbf{c}_j^+\cdot(\mathbf{t}_j^+\times \hat{\mathbf{n}}^+_{hi}),
\end{align}
\end{subequations}
where $\hat{\mathbf{n}}^+_{hi} \equiv \hat{\mathbf{z}}$; $\hat{\mathbf{n}}_{hi}$ is the unit outward normal to face $i$ of cell $h$.  The area (\ref{eq:la}b) mirrors results in \cite{jensen2020, cowley2024}.  To capture the manner in which the apical perimeter changes as a result of displacing an apical vertex we use the relations 
\begin{subequations}
    \label{eq:ids}
\begin{align}
    \frac{\partial t_i^+}{\partial \mathbf{r}_k^+}&={\textstyle{\sum_j}} \vert B_{ij}^{l+}\vert A_{jk}^{++} \hat{\mathbf{t}}_j^+, \\
    \frac{\partial L_h^+}{\partial \mathbf{r}_k^+}&={\textstyle{\sum_{i,j}}}\vert C_{hi}^l\vert \vert B_{ij}^{l+} \vert A_{jk}^{++}\hat{\mathbf{t}}_j^+ =
    {\textstyle{\sum_{i}}}\vert C_{hi}^l\vert  \frac{\partial t_i^+}{\partial \mathbf{r}_k^+},
\end{align}
\end{subequations}
where the hat denotes a unit vector.


\section{2D Model}\label{2D Appendix}

The classical 2D model is recovered from the present formulation by imposing $H=1$ in (\ref{eq:energy_AL}) (disregarding the vertical force balance), setting $\Gamma_a=0$ and defining $\Gamma^{2D}=2\Gamma_L$ and $L_0^{2D}=L_0-\Gamma_A/(4\Gamma_L)$.  This gives 
\begin{equation}
    U_h=\tfrac{1}{2}(A_h-1)^2+\tfrac{1}{2}\Gamma^{2D}(L_h-L_0^{2D})^2+\mathrm{constant}.
\end{equation}
The associated pressure and tensions are 
\begin{equation}
P_h^{2D}\equiv \frac{\partial U_h}{\partial A_h}=A_h-1, \quad T_h^{2D}\equiv \frac{\partial U_h}{\partial L_h}=\Gamma^{2D}(L_h-L_0^{2D}).
\end{equation}
Rigid hexagons satisfy (\ref{eq:hxf}a,b); floppy solutions satisfy $A_h=1$, $L_h=L_0^{2D}$, as illustrated in Fig.~\ref{fig:2D_fig}(b,c) (replicating \cite{farhadifar2007}, for example), which can be compared to figures~\ref{fig:Vary_L0}.  The parameter space map in Fig.~\ref{fig:2D_fig}(a) can be compared to Fig.~\ref{fig:rigidity transition}(c).  The rigid-floppy transition lies at $L_0^{2D}=s_6\approx 3.72$.  Rigid solutions collapse to zero area along $L_0^{2D}=0$ for $\Gamma^{2D}>\Gamma^*\equiv \sqrt{3}/12$.  Rigid solution branches terminate via a saddle-node bifurcation at $L_0^{2D}=-({8 \sqrt{2}}/(3 \Gamma ))\left(\Gamma^*-\Gamma^{2D} \right)^{\tfrac{3}{2}}$, with $0<\Gamma^{2D}\leq\Gamma^*$.

