\section{Height variation across a constrained monolayer}
\label{sec:height}

In the main presentation of the model, we impose the requirement that $\mathsfbf{r}^\pm$ and $H$ evolve independently.  Alternatively, this constraint can be enforced by redefining the total energy to accommodate small variations in height between adjacent cells.  We write $\mathsf{H}=(H_1,\dots,H_{N_c})^\top$ and redefine $U$ as
\begin{equation}
\label{eq:moden}
    U={\textstyle\sum_h}\mathcal{U}(A_h,L_h, H_h)+\tfrac{1}{2} \Lambda \mathsf{H}^\top \mathcal{L}\mathsf{H}, 
\end{equation}
(see (\ref{eq:energy_AL})).  The Laplacian term (see (\ref{eq:lap})) mimics an external constraint that penalises height differences between neighbouring cells, when the constant $\Lambda$ is positive.  Then, noting that $\mathcal{L}=\mathcal{L}^\top$, the vertical force balance on individual cells $\partial U/\partial H_h=0$ becomes 
\begin{equation}
\mathsf{0}=\frac{\partial \mathcal{U}}{\partial{H}}(A_h,L_h,H_h)+\Lambda \left\{\mathcal{L}\mathsf{H} \right\}_h.
\end{equation}
Assuming $\Lambda\gg 1$ and writing $\mathsf{H}=\mathsf{H}^{(0)}+\mathsf{H}^{(1)}/\Lambda+\dots$, at leading order it follows that $\mathcal{L}\mathsf{H}^{(0)}=\mathsf{0}$.  This has a solution for which $\mathsf{H}^{(0)}$ is uniform across the monolayer, with $H^{(0)}_h=H^*$, say, for $h=1,2,\dots,N_c$.  At the following order, 
\begin{equation}
    \left\{\mathcal{L}\mathsf{H}^{(1)}\right\}_h=-\frac{\partial \mathcal{U}}{\partial {H}}(A_h,L_h,H^*).
\label{eq:heightcorr}
\end{equation}
As $\mathcal{L}\mathsf{1}=0$, so that $\mathsf{1}^\top \mathcal{L}=\mathsf{0}^\top$, it follows that a solvability condition for (\ref{eq:heightcorr}) is that $\sum_h (\partial \mathcal{U}/\partial H)(A_h,L_h,H^*)=0$, which is equivalent to the global force balance (\ref{eq:Ha0}).  We can then evaluate small corrections to cell height by inverting (\ref{eq:heightcorr}).  

\section{Asymptotic limits}
\label{app:limits}

Here we identify solutions of (\ref{eq:H}a,b), (\ref{eq:hxf}) describing configurations of rigid hexagonal cells, and floppy cells, in specific asymptotic limits.  

\textbf{Constrained total surface area.}  For $\Gamma_a\gg 1$, which constrains the total cell surface area to take the target value of unity, we reformulate the problem for rigid hexagons as (\ref{eq:hxf}a, b) with
\begin{subequations}
\label{eq:larga}
\begin{align}
0&=2A+LH-1, \\ P^{2D}&=H(AH-1)+2T, \\
0&=A(AH-1)+(T+\tfrac{1}{2}\Gamma_A)L, \\
T^{2D}&=TH+\tfrac{1}{2}\Gamma_A H +2\Gamma_L(L-L_0).
\end{align}
\end{subequations}
Here the tension $T$ is introduced as a Lagrange multiplier and (\ref{eq:larga}d) derives from (\ref{eq:H}c) using $T$ from (\ref{eq:PTs})$_2$.  The total area constraint (\ref{eq:larga}a) can be used to eliminate $H$; the vertical force balance (\ref{eq:larga}c) specifies $T$; and $P^{2D}$ and $T^{2D}$ are then combined in (\ref{eq:hxf}a, b) to find $l$.   Within this limit, columnar cells satisfy 
\begin{subequations}
\label{eq:elonga}
\begin{gather}
    L\approx \frac{1}{H}, ~~ A\approx \frac{\sqrt{3}}{24 H^2},~~ T\approx -\tfrac{1}{2}\Gamma_A+\frac{\sqrt{3}}{24H}, \\
    P^{2D}\approx -H, ~~ T^{2D}\approx \frac{\sqrt{3}}{12},\quad L_0\approx -\frac{\sqrt{3}}{48\Gamma_L},
 \end{gather}
 \end{subequations}
with $H\gg 1$.  Here the tension $T$ balances adhesive forces.  Floppy states under large $\Gamma_a$ are obtained by solving (\ref{eq:larga}) with $P^{2D}=0$, $T^{2D}=0$ for $A$, $H$, $L$ and $T$.  This limit is shown on Fig.~\ref{fig:Vary_Gamma_a}(a,c).  Imposing (\ref{eq:s6}) in addition yields, for $\Gamma_a\gg 1$ the limits shown in Fig.~\ref{fig:rigidity transition}(b,d,e).

\textbf{Constrained apical perimeter.} For $\Gamma_L\gg 1$, the apical perimeter is constrained to satisfy $L=L_0$ and we express the problem as
\begin{subequations}
\label{eq:largl}
\begin{align}
A&=(\sqrt{3}/24)L_0^2, \\ P^{2D}&=H(AH-1)+2\Gamma_a(2A+L_0 H-1), \\
0&=A(AH-1)+(\Gamma_a(2A+L_0H-1)+\tfrac{1}{2}\Gamma_A)L_0, \\ 
T^{2D}&=\Gamma_a(2A+ L_0H-1) H+\tfrac{1}{2}\Gamma_A H +T^c.
\end{align}
\end{subequations}
In this case, the hexagonal constraint (\ref{eq:largl}a) determines $A$, the vertical force balance (\ref{eq:largl}c) specifies $H$ and the Lagrange multiplier $T^c$ takes whatever value is needed to satisfy the force balance (\ref{eq:hxf}a, b).  This leads to asymptotes shown in Fig.~\ref{fig:Vary_Gamma_L}.  Floppy solutions satisfying (\ref{eq:flo}) in this limit are recovered by solving (\ref{eq:largl}b,c,d) with $P^{2D}=0$, $T^{2D}=0$ for $A$, $H$ and $T^c$ (and $L=L_0$).  Imposing (\ref{eq:s6}) in addition leads to limits plotted in Fig.~\ref{fig:rigidity transition}(c,d,f).  Setting $H=0$ in (\ref{eq:largl}a,c) leads to 
\begin{equation}
\label{eq:sqlim}
    \Gamma_A=\frac{\sqrt{3}}{12}L_0+\Gamma_a\left(2-\frac{\sqrt{3}}{6}L_0^2\right),
\end{equation}
while (\ref{eq:largl}a,c) in the limit $H\rightarrow \infty$ requires
\begin{equation}
\label{eq:colim}
    \Gamma_a=-L_0^3/192.
\end{equation}

\textbf{Strong adhesion.}
The vertical force balance (\ref{eq:hxf}c) can be written as $0=A(AH-1)+(\Gamma_a(2A+LH-1)+\tfrac{1}{2}\Gamma_A)L$, and is then combined with (\ref{eq:H}b) to become $0=HA(AH-1)+L(T^{2D}-2\Gamma_L(L-L_0))$. Then, in the limit $\Gamma_A \rightarrow -\infty$, 
\begin{subequations}
   \label{eq:gaf}
\begin{align}
H&\approx \frac{2\Gamma_a^2-\Gamma_L}{2 \Gamma_a (\Gamma_a-\Gamma_L L_0)}\Gamma_A, \quad L \approx \frac{\Gamma_a-\Gamma_L L_0}{2\Gamma_a^2-\Gamma_L}, \\
A&\approx \frac{2 \Gamma_a \Gamma_L (2 \Gamma_a L_0-1) (\Gamma_a-\Gamma_L L_0)}{\Gamma_A\left(2 \Gamma_a^2-\Gamma_L \right)^2}.
\end{align}
\end{subequations}
This represents the dominant balance $0\approx H(AH-1)+2\Gamma_a LH$ in (\ref{eq:H}a), $0\approx \Gamma_a LH^2+\tfrac{1}{2}\Gamma_A H$ in (\ref{eq:H}b) and $AH(AH-1)-2\Gamma_L(L-L_0)=0$ in the vertical direction.  The tension balance is similar to the rigid limit (\ref{eq:gar}) but the deviation from the target volume is balanced in the pressure condition by tension associated with the area of lateral faces, and in the vertical force balance by peripheral apical tension.  At a rigidity transition, cells become hexagonal and the geometric constraint (\ref{eq:s6}) cannot be met unless 
\begin{equation}
L_0\approx \Gamma_a/\Gamma_L \quad (-\Gamma_A\rightarrow \infty).
\label{eq:floplimlargeGa}
\end{equation}
This limit is shown in Fig.~\ref{fig:rigidity transition}(a,e,f).  

Additionally, for $\Gamma_A\rightarrow -\infty$, analysis of (\ref{eq:H}a,b), (\ref{eq:hxf}) reveals the limit 
\begin{equation}
A\approx \frac{96\Gamma_a^2}{\sqrt{3} \Gamma_A^2}, \quad L\approx \frac{48\Gamma_a}{\sqrt{3}(-\Gamma_A)}, \quad H\approx \frac{\sqrt{3}\Gamma_A^2}{96\Gamma_a^2},
\label{eq:gar}
\end{equation}
satisfying the dominant balance $AH-1\approx 0$ in (\ref{eq:H}a), $\Gamma_aLH^2+\tfrac{1}{2}\Gamma_A H\approx 0$ in (\ref{eq:H}b) and (\ref{eq:hxf}c), with area and perimeter satisfying the isoperimetric constraint (\ref{eq:hxf}b); each cell is close to its target volume and an inward tension associated with total surface area, which is dominated by lateral faces, balances the outward tension due to adhesion.  

\section{Dynamics}
\label{app:dynamics}

We consider dynamic evolution of a monolayer under the forces identified in (\ref{eq:p2t2}).  Following \cite{cowley2024}, we define $\mathsf{s}(\mathsf{r})=(A_1,\dots,A_{N_c},L_1,\dots,L_{N_c})^\top$ and collect energy derivatives as $U_{\mathsf{s}}\equiv (P_1^{2D},\dots,P_{N_c}^{2D}, T_1^{2D},\dots,T_{N_c}^{2D})^\top$. Imposing a drag on vertices, time evolution of  the system follows
\begin{equation}
\left(    \begin{matrix}
        1 & 0 \\ 0 & \mu 
    \end{matrix} \right) \frac{\mathrm{d}}{\mathrm{d}t} \left(    \begin{matrix}
        {\mathsfbf{r}} \\ {H} \end{matrix}\right) =-\left(\begin{matrix} {U}_\mathsf{s} {\mathsf{s}}_\mathsfbf{r}, \\ {U}_H \end{matrix}\right).
        \label{eq:fulldyn}
\end{equation}
Here the parameter $\mu$ models frictional resistance to height changes, relative to drag forces that resist in-plane vertex motion, and subscripts on $U$ denote derivatives. The energy can be expanded as 
\begin{multline}
U\approx \bar{U}+
(\bar{U}_\mathsf{s} \bar{\mathsf{s}}_\mathsfbf{r}, \bar{U}_H)
\left(\begin{matrix}\cdot \hat{\mathsfbf{r}}\\ \hat{H}\end{matrix}\right)\\+\tfrac{1}{2}
(\hat{\mathsfbf{r}}\cdot,\hat{H})\left( 
    \begin{matrix}
        \bar{\mathsf{s}}_{\mathsfbf{r}}^\top \bar{U}_{\mathsf{s}\mathsf{s}} \bar{\mathsf{s}}_\mathsfbf{r}+\bar{U}_{\mathsf{s}}^\top \bar{\mathsf{s}}_{\mathsfbf{r}\mathsfbf{r}} & \bar{\mathsf{s}}_{\mathsfbf{r}}^\top \bar{U}_{\mathsf{s}H}\\
        \bar{U}_{\mathsf{s}H}^\top \bar{\mathsf{s}}_{\mathsfbf{r}}  & \bar{U}_{HH}
    \end{matrix}
    \right)
    \left(\begin{matrix}\cdot \hat{\mathsfbf{r}} \\ \hat{H}\end{matrix}\right)+\dots
\end{multline}
A bar denotes evaluation at an equilibrium point (so that $\bar{U}_\mathsf{s}=\mathsf{0}$, $\bar{U}_H=0$) and hats denote small perturbations.  Provided $\bar{U}_{HH}\neq 0$, rapid relaxation of the depth (linearising (\ref{eq:fulldyn}) about the equilibrium and taking $\mu\rightarrow 0$) leads to the eigenvalue problem 
\begin{equation}
\lambda\hat{\mathsfbf{r}}=
\left[\bar{\mathsf{s}}_{\mathsfbf{r}}^\top (\bar{U}_{\mathsf{s}\mathsf{s}} -\bar{U}_{\mathsf{s}H} \bar{U}_{HH}^{-1}
        \bar{U}_{\mathsf{s}H}^\top)\bar{\mathsf{s}}_\mathsfbf{r}+\bar{U}_{\mathsf{s}}^\top \bar{\mathsf{s}}_{\mathsfbf{r}\mathsfbf{r}} 
    \right]
    \cdot \hat{\mathsfbf{r}},
    \label{eq:hess}
\end{equation}
where the solutions $\lambda$ are the decay rates of small perturbation.  The matrix operator in (\ref{eq:hess}) is the Hessian $\mathcal{H}$.  

\begin{figure*}    
    \centering
    \includegraphics[width=0.8\linewidth]{Horizontal_eigenmodes.pdf}
    \caption{Eigenmodes (a) and eigenvalues of the Hessian $\mathcal{H}$ as (b) $L_0$, (c) $\Gamma_a$ and (d) $-\Gamma_A$ are varied, for a hexagon at baseline parameter values (Table~\ref{tab:base_case_quatities}). Eigenvalues correspond to the mode(s) of the same colour in (b--d); modes of the same colour in (a) share an eigenvalue.  The dilation mode is shown in cyan.  Translation and rotation modes (with zero eigenvalue) are not shown.}
    \label{fig:evals}
    \end{figure*}

Figure \ref{fig:evals} shows the values of the non-zero eigenvalues of $\mathcal{H}$ for an isolated hexagonal cell, for varying $L_0, \Gamma_a$ and $\Gamma_A$, as discussed in Sec.~\ref{sec:results}.  In all cases, all symmetry-breaking modes simultaneously become unstable when $T^{2D}=0$. The cell height vanishes at $\Gamma_A\approx 1.42$ when $\Gamma_A$ is varied.  All other unstable points correspond to a loss of in-plane rigidity. Eigenvalues of the symmetry-breaking modes diverge to $\pm \infty$ when the equilibrium cell area and perimeter go to zero.  

For some parameter values, multiple equilibrium solutions for rigid hexagonal cells can coexist; the Hessian in (\ref{eq:hess}) was used to confirm the stability of solutions plotted in Fig.~\ref{fig:rigidity transition}.

The component of the Hessian $\bar{U}_{\bar{\mathsf{s}}}^\top \mathsf{s}_{\mathsfbf{r}\mathsfbf{r}}$ in (\ref{eq:hess}) contains contributions from pre-stress through the vector $\bar{U}_{\mathsf{s}}$ of equilibrium pressures $\bar{\mathsf{P}}^{2D}$ and tensions $\bar{\mathsf{T}}^{2D}$.  $\bar{\mathsf{s}}_{\mathsfbf{r}\mathsfbf{r}}$ contains derivatives of (\ref{eq:ids}).  Focusing on components relating to $\bar{\mathsf{T}}^{2D}$, we define an indicator function satisfying 
\begin{equation}
\mathcal{I}_j^{\varepsilon}=\begin{cases}1 & \vert \sum_{h}D^{\mathrm{ce}}_{hj} \bar{T}_h^{2D}\vert >\varepsilon, \\ 0 &\mathrm{otherwise}, 
\end{cases} \quad (h=1,\dots,N_c),
\end{equation}
which identifies edges carrying tension above a threshold. Evaluation of the derivative $\partial^2 L_h^+/\partial \mathbf{r}_k^+ \partial \mathbf{r}_{k'}^+$ (see \cite{cowley2024}) and multiplication by $\mathcal{I}_h^{\varepsilon}$ leads to consideration of the operator 
\begin{equation}
\label{eq:prulap}
\left\{\mathcal{L^\varepsilon}\right\}_{k k'}\equiv
    \sum_{j} \mathcal{I}_j^{\varepsilon}A^{++}_{jk} A^{++}_{jk'}.
\end{equation}
This modification of the full apical vertex Laplacian $\mathsf{A}^{++\top}\mathsf{A}^{++}$ retains contributions from edges of cells carrying  non-vanishing tension.

\section{Stress}
\label{app:stress}

The stress for the symmetric cells considered here can be derived directly by using the energy (\ref{eq:energy_AL}) and writing the force on vertex $k$ as  
\begin{align}
\mathbf{f}_{hk}=&\frac{\partial U}{\partial A_h}\frac{\partial A_h}{\partial \mathbf{R}_k}+ \frac{\partial U}{\partial L_h^+}\frac{\partial L_h^+}{\partial \mathbf{R}_k}+\frac{\partial U}{\partial L_h^-}\frac{\partial L_h^-}{\partial \mathbf{R}_k}+\frac{1}{Z_h}\frac{\partial U}{\partial H}{}\frac{\partial H}{\partial \mathbf{R}_k}\nonumber \\
=&\left(H\frac{\partial U}{\partial V_h}+2\frac{\partial U}{\partial a_h}\right) \frac{\partial A_h}{\partial \mathbf{R}_k}\nonumber\\
 +& \left (H \frac{\partial U}{\partial a_h}+ T_h^c+\tfrac{1}{2}\Gamma_A H\right )\frac{\partial L_h}{\partial \mathbf{R}_k}
+\frac{1}{Z_h}\frac{\partial U}{\partial H}\frac{\partial H}{\partial \mathbf{R}_k}, 
\end{align}
where ${\partial U}/{\partial H}=A_h \partial U /\partial {V_h}+L_h \partial U/\partial {a_h}+\tfrac{1}{2}\Gamma_A L_h$.  Here $Z_h$ is the number of apical vertices, across which the vertical force is distrubuted.  We then exploit 2D results \cite{nestor2018}, plus the observation that $\mathbf{R}_k\otimes (\partial H/\partial\mathbf{R}_k)=H\hat{\mathbf{z}}\otimes\hat{\mathbf{z}}$ when we enforce $\mathbf{R}_k=\mathbf{r}_k$ for vertices in the plane $z=0$, and $\mathbf{R}_k=\mathbf{r}_k+H\hat{\mathbf{z}}$ for cells in the plane $z=H$, to derive (\ref{eq:Vhsigma_3Da}).


\section{Stiffness}
\label{app:stiffness}

Consider the energy $\mathcal{U}(A,L,H)$ for a single cell (\ref{eq:energy_AL}).  In this Appendix, $h$ suffices are dropped and subscripts on $\mathcal{U}$ denote derivatives. 2D and 3D stresses (\ref{eq:Vhsigma_3Da}) can be written
\begin{equation}
V\boldsymbol{\sigma}=A\boldsymbol{\sigma}^{2D}+H \mathcal{U}_H \hat{\mathbf{z}}\otimes\hat{\mathbf{z}},\quad A\boldsymbol{\sigma}^{2D} = A\mathcal{U}_A\mathsf{I}_\perp + L\mathcal{U}_L\mathsf{Q}.
\label{eq:strs}
\end{equation}
Recall that $\mathsf{I}_\perp:\mathsf{Q}=1$, $2AP^{\mathrm{eff},2D}=2A\mathcal{U}_A+L\mathcal{U}_L$ and $3VP^{\mathrm{eff}}=2A\mathcal{U}_A+L\mathcal{U}_L+H\mathcal{U}_H$.  For a symmetric hexagonal cell, $\mathsf{Q}=\tfrac{1}{2}\mathsf{I}_\perp$.  We then impose an affine deformation $\mathsf{E}=\mathsf{E}_\perp + e \hat{\mathbf{z}}\otimes\hat{\mathbf{z}}$.  For example, isotropic expansion has $\mathsf{E}_\perp=e\mathsf{I}$ so that $\mathrm{Tr}(\mathsf{E})=3e$;  in-plane shear deformation has $e=0$ with $\mathsf{I}_\perp:\mathsf{E}_\perp=0$;  out-of-plane shear deformation has $\mathsf{E}_\perp=-\tfrac{1}{2}e\mathsf{I}_\perp$.  We now seek the stress generated by an affine displacement; this approach complements that of \cite{kim2024mean}, who evaluated the elastic modulus of a cell modelled in 3D as a truncated octahedron.

Under an arbitrary small deformation, perturbations in $A$, $L$, $H$ and $\mathsf{Q}$ are $\Delta A=A\mathsf{I}_\perp:\mathsf{E}$, $\Delta L=L\mathsf{Q}:\mathsf{E}$, $\Delta H=He$ and $\Delta\mathsf{Q}=\mathsf{B}:\mathsf{E}$ respectively, where the fourth-order tensor $\mathsf{B}$ (defined in \cite{nestor2018a}) satisfies $\mathsf{B}:\mathsf{I}_\perp=\mathsf{Q}$ and $\mathrm{Tr}(\mathsf{B}:\mathsf{E})=\mathsf{Q}:\mathsf{E}$.  Perturbing all quantities in (\ref{eq:strs}) and linearising leads to 
\begin{subequations}
\label{eq:fullstiff}
\begin{align}
V\Delta\boldsymbol{\sigma}&=\boldsymbol{\alpha}(\mathsf{I}_\perp:\mathsf{E}_\perp)+\boldsymbol{\beta}e+\boldsymbol{\gamma}\mathsf{Q}:\mathsf{E}_\perp+\delta \mathsf{B}:\mathsf{E}_\perp, \\
\boldsymbol{\alpha}=& A^2 \mathcal{U}_{AA}\mathsf{I}_\perp+(LA\mathcal{U}_{LA}-L\mathcal{U}_L)\mathsf{Q}\nonumber \\&\quad+(AH\mathcal{U}_{AH}-H\mathcal{U}_H)\hat{\mathbf{z}}\otimes\hat{\mathbf{z}},\\
\boldsymbol{\beta} =& (AH \mathcal{U}_{AH}-A\mathcal{U}_A)\mathsf{I}_\perp+(LH\mathcal{U}_{LH}-L\mathcal{U}_L)\mathsf{Q} \nonumber\\ &\quad +H^2 \mathcal{U}_{HH}\hat{\mathbf{z}}\otimes\hat{\mathbf{z}},\\
\boldsymbol{\gamma} =& AL\mathcal{U}_{AL}\mathsf{I}_\perp+(L^2 \mathcal{U}_{LL}+L\mathcal{U}_L)\mathsf{Q}+HL\mathcal{U}_{HL} \hat{\mathbf{z}}\otimes\hat{\mathbf{z}},\\
\delta =&L\mathcal{U}_L.
\end{align}
\end{subequations}

These coefficients contain second derivatives of the energy, contributing to material stiffness, plus first derivatives, contributing to geometric stiffness.  The first derivatives can be identified as prestresses in the base state in (\ref{eq:strs}).  Eq.~(\ref{eq:fullstiff}) demonstrates how the cross-coupling in $\mathcal{U}$ leading to non-zero mixed second derivatives can influence the cell stiffness.

The stress-strain relationship under isotropic expansion is then
\begin{subequations}
\label{eq:outofplane}
\begin{align}
V\Delta\boldsymbol{\sigma}&=\left[2\boldsymbol{\alpha}+\boldsymbol{\beta}+\boldsymbol{\gamma}+\delta \mathsf{Q}\right]e  \nonumber \\
&=\big\{(2A^2\mathcal{U}_{AA}+AL\mathcal{U}_{AL}+AH\mathcal{U}_{AH}-A\mathcal{U}_A)\mathsf{I}_\perp \nonumber \\
& \qquad +(2LA\mathcal{U}_{AL}+L^2\mathcal{U}_{LL}+LH\mathcal{U}_{HL}-L\mathcal{U}_L)\mathsf{Q} \nonumber \\
+(2&AH\mathcal{U}_{AH}+HL\mathcal{U}_{HL}+H^2\mathcal{U}_{HH}-2H\mathcal{U}_H)\hat{\mathbf{z}}\otimes\hat{\mathbf{z}}\big\}e.
\end{align}
\end{subequations}
For a hexagonal cell, this simplifies to 
\begin{subequations}
\label{eq:isoexp}
\begin{align}
V\Delta\boldsymbol{\sigma}&=\left[2\boldsymbol{\alpha}+\boldsymbol{\beta}+\boldsymbol{\gamma}+\delta \mathsf{Q}\right]e  \\
&=\big\{(2A^2\mathcal{U}_{AA}+2AL\mathcal{U}_{AL}+AH\mathcal{U}_{AH}-A\mathcal{U}_A \nonumber\\ &\qquad +\tfrac{1}{2}(L^2\mathcal{U}_{LL}+LH\mathcal{U}_{HL}-L\mathcal{U}_L))\mathsf{I}_\perp \nonumber \\
+(2&AH\mathcal{U}_{AH}+HL\mathcal{U}_{HL}+H^2\mathcal{U}_{HH}-2H\mathcal{U}_H)\hat{\mathbf{z}}\otimes\hat{\mathbf{z}}\big\}e.
\end{align}
\end{subequations}
The trace of (\ref{eq:isoexp}) recovers a bulk modulus, illustrated more directly in Fig.~\ref{fig:heightvariation}(c).  The anisotropic response to isotropic forcing, evident in Fig.~\ref{fig:heightvariation}, is consistent with different in-plane and out-of-plane stress responses in (\ref{eq:isoexp}).

In-plane shear deformation leads to 
\begin{align}
\label{eq:ipsd}
V\Delta\boldsymbol{\sigma}&=\big[AL\mathcal{U}_{AL}\mathsf{I}_\perp+(L^2 \mathcal{U}_{LL}+L\mathcal{U}_L)\mathsf{Q}\nonumber \\ & \quad +HL\mathcal{U}_{HL} \hat{\mathbf{z}}\otimes\hat{\mathbf{z}}\big]
\mathsf{Q}:\mathsf{E}_\perp+L\mathcal{U}_L \mathsf{B}:\mathsf{E}_\perp.
\end{align}
Two terms proportional to $L\mathcal{U}_L$ rely on cortical tension to generate stiffness.  In contrast, for the classical 2D model with $\mathcal{U}=\tfrac{1}{2}(A-1)^2+\tfrac{1}{2}\Gamma(L-L_0)^2$ and $T\equiv \mathcal{U}_L$, (\ref{eq:ipsd}) simplifies to 
\begin{equation}
V\Delta\boldsymbol{\sigma}=\Gamma L^2 \mathsf{Q}(\mathsf{Q}:\mathsf{E}_\perp) +L T \left[\mathsf{Q}(\mathsf{Q}:\mathsf{E}_\perp)+ \mathsf{B}:\mathsf{E}_\perp\right].
\end{equation}
The first term provides material stiffness (via $\mathcal{U}_{LL}=\Gamma$), the second geometric stiffness (via $U_L=T$).  In (\ref{eq:ipsd}), additional material stiffness arises from $U_{AL}$ and $U_{HL}$.

Finally, out-of-plane shear deformation leads to
\begin{align}
V\Delta\boldsymbol{\sigma}&=\left[-\boldsymbol{\alpha}+\boldsymbol{\beta}-\tfrac{1}{2}\boldsymbol{\gamma}-\tfrac{1}{2}\delta \mathsf{Q}\right]e \nonumber \\
&=\big\{(-A^2\mathcal{U}_{AA}-\tfrac{1}{2}AL\mathcal{U}_{AL}+AH\mathcal{U}_{AH}-A\mathcal{U}_A)\mathsf{I}_\perp \nonumber \\
& \qquad +(-LA\mathcal{U}_{AL}-\tfrac{1}{2}L^2\mathcal{U}_{LL}+LH\mathcal{U}_{HL}-L\mathcal{U}_L)\mathsf{Q} \nonumber \\
 +(-&AH\mathcal{U}_{AH}-\tfrac{1}{2}HL\mathcal{U}_{HL}+H^2\mathcal{U}_{HH}+H\mathcal{U}_H)\hat{\mathbf{z}}\otimes\hat{\mathbf{z}}\big\}e.
\end{align}
For a hexagonal cell, this simplifies to
\begin{align}
V\Delta\boldsymbol{\sigma}&=\left[-\boldsymbol{\alpha}+\boldsymbol{\beta}-\tfrac{1}{2}\boldsymbol{\gamma}-\tfrac{1}{2}\delta \mathsf{Q}\right]e \nonumber \\
&=\big\{(-A^2\mathcal{U}_{AA}-AL\mathcal{U}_{AL}+AH\mathcal{U}_{AH}-A\mathcal{U}_A \nonumber\\&\qquad-\tfrac{1}{4}L^2\mathcal{U}_{LL}+\tfrac{1}{2}LH\mathcal{U}_{HL}-\tfrac{1}{2}L\mathcal{U}_L)\mathsf{I}_\perp \nonumber \\
 +(-&AH\mathcal{U}_{AH}-\tfrac{1}{2}HL\mathcal{U}_{HL}+H^2\mathcal{U}_{HH}+H\mathcal{U}_H)\hat{\mathbf{z}}\otimes\hat{\mathbf{z}}\big\}e,
\end{align}
showing how all second derivatives of $U$ contribute to the material stiffness.

