\section{Analytical overview}
In this section, we provide a review of some geometric and analytic tools that we frequently use.

\subsection{Differential forms}
We will give some definitions and results without proofs, some of which are from \cite[Chapter 5]{Lafontaine}, \cite[Chapter 1]{GunterSchwartz} and \cite[Chapter 1, Section 13]{taylor}.

\begin{notation}
For a differential form $\alpha \in \Omega^p(M)$, we denote by $\phi^* \alpha$ its pullback by a diffeomorphism $\phi$, and by $X \lrcorner \alpha$ its interior product by a vector field $X$.
\end{notation}


\subsubsection{Differential forms on manifolds}\label{sec:rappelGeometrie}
Let $M$ be a smooth compact manifold of dimension $n\geq2$ with smooth boundary. A differential form of degree $p$ on $M$ is a smooth section of the bundle $\Lambda^pT^*M$ and the set of $p$-differential forms on $M$ is denoted $\Omega^p(M)$. \\ 
We denote by $\iota : \partial M \longrightarrow M$ the inclusion map. Thus, for any $\w \in \partial M$, $\iota^*\w$ is the tangential component of $\w_{|\partial M}$, and $\nu \lrcorner \w$ is its normal component.\\ Let $M$ be an oriented Riemannian manifold. Recall that the Hodge operator is a linear map denoted by $"\star"$, defined as $\star : \Lambda^pM^* \longrightarrow \Lambda^{n-p}M^*$ such that if $(\epsilon_i)_{i=1}^n$ is a positively oriented orthonormal basis of $T^*M$, then 
    \[\star(\epsilon_{i_1} \wedge \dots \wedge \epsilon_{i_p}) = \epsilon_{j_1} \wedge \dots \wedge \epsilon_{j_{n-p}}\]
    where, $(j_1, \dots, j_{n-p})$ is chosen such that $(\epsilon_{i_1}, \dots, \epsilon_{i_p}, \epsilon_{j_1}, \dots, \epsilon_{j_{n-p}})$ is a positively oriented orthonormal basis. As a consequence we have $\star 1 = \epsilon_1 \wedge \dots \wedge \epsilon_n$, $\star(\epsilon_1 \wedge \dots \wedge \epsilon_n) = 1$ and for a $p$-form $\w$ we get $\star \star \w = (-1)^{p(n-p)} \w.$\\
    For differential forms, we denote by $\langle.,.\rangle$ the natural inner product induced by the Riemannian metric, and we define $(\w,\w'):=\int_M\langle\w,\w'\rangle d\mu_g.$
    The codifferential operator, denoted $\delta$, is a map $\delta : \Omega^p(M) \longrightarrow \Omega^{p-1}(M)$. It is the formal adjoint of the exterior derivative $d$, i.e., for all $\alpha\in \Omega^p(M)$ and $\beta\in \Omega^{p+1}(M)$ with support in $M\setminus \partial M$, we have  $(d\alpha, \beta) = (\alpha, \delta\beta).$ It turns out that, for every $p$-form $\w,$ 
    \[\delta \w = (-1)^{n(p+1)+1} \star d \star \w.\]
We denote by $\nabla$ the Levi-Civita connection. For a vector field $X$, we write $X^\flat$ for the differential $1$-form such that for all vector field $Y$ we have $X^\flat=g(X,Y).$\\
Given a local orthonormal basis  $(e_i)_{i=1}^n$, we have the local expressions of $d\w=\sum_i e_i^\flat\wedge\nabla_{e_i}\w$ and $\delta\w=-\sum_ie_i\lrcorner\nabla_{e_i}\w$, see for instance \cite[Proposition 2.61]{GallotHulinLafontaine}. The Hodge-de-Rham Laplacian is the operator denoted $\Delta$ from  $\Omega^p(M)$ to itself, defined for all $\w\in \Omega^p(M)$ by
    \[\Delta \w = d\delta\w + \delta d\w.\]  A $p$-differential form $\w$ is said to be harmonic if $\Delta \w = 0.$\\
    We have the following properties \begin{enumerate}
 \item The Hodge-de-Rham Laplacian is formally self-adjoint, i.e., for all $\alpha, \ \beta\in \Omega^p(M)$ with support in $M\setminus \partial M$, we have  $(\Delta\alpha, \beta) = (\alpha, \Delta\beta).$
        \item    $\Delta \star = \star \Delta.$
    \end{enumerate}

We will frequently use the following integration by parts formulas
\begin{prop}\label{prop:IPP}
    For $\w \in \Omega^p(M)$ and $\w' \in \Omega^{p+1}(M)$, we have 
    \begin{equation}\label{eq:ippPourLaPreuve}
        \int_M \langle d\w, \w' \rangle d\mu_g = \int_M \langle \w, \delta\w' \rangle d\mu_g -\int_{\partial M} \langle \iota^* \w, \nu \lrcorner \w' \rangle d\mu_g.
    \end{equation}

    Moreover, for any $\w, \w' \in \Omega^p(M)$, we have 
    \begin{equation}\label{eq:IPP1}
    \begin{split}
        & \int_M \Big( \langle \Delta \w , \w' \rangle -  \langle \w , \Delta \w' \rangle \Big) d\mu_g \\
        = & \int_{\partial M} \Big( \langle \nu \lrcorner d \w, \iota^* \w' \rangle - \langle \iota^* \w, \nu \lrcorner d \w' \rangle + \langle \nu \lrcorner \w, \iota^* \delta \w' \rangle - \langle \iota^* \delta \w, \nu \lrcorner \w' \rangle \Big) d\mu_g.
    \end{split}
    \end{equation}

Eventually, for all $\w,\w'\in \Omega^p(M)$ we have the following identity
    \begin{equation}\label{eq:IPP3'}
    \begin{aligned}
    \int_M \langle \Delta \w, \w' \rangle \, d\mu_g &= \int_M \langle d\w, d\w' \rangle \, d\mu_g + \int_M \langle \delta \w, \delta \w' \rangle \, d\mu_g \\
    &\quad + \int_{\partial M} \langle \nu \lrcorner d\w, \iota^* \w' \rangle \, d\mu_g - \int_{\partial M} \langle \iota^* \delta \w, \nu \lrcorner \w' \rangle \, d\mu_g.
    \end{aligned}
    \end{equation}

\end{prop}
\begin{proof}
    Equations \eqref{eq:ippPourLaPreuve} and \eqref{eq:IPP1} are shown in \cite[p.182]{taylor}. Equation \eqref{eq:IPP3'} is shown in \cite[Equation $30$]{BesselFidaGeorgeNicolas} and \cite[p.421]{taylor}. \end{proof}
Replacing $\w$ with $\Delta \w$ in \eqref{eq:IPP1}, we obtain:
    \begin{equation}\label{eq:IPP2}
    \begin{split}
        & \int_M \langle \Delta^2 \w , \w' \rangle d\mu_g = \int_M \langle \Delta \w , \Delta \w' \rangle d\mu_g \\
        & + \int_{\partial M} \Big( \langle \nu \lrcorner d \Delta \w, \iota^* \w' \rangle - \langle \iota^* \Delta \w, \nu \lrcorner d \w' \rangle + \langle \nu \lrcorner \Delta \w, \iota^* \delta \w' \rangle - \langle \iota^* \delta \Delta \w, \nu \lrcorner \w' \rangle \Big) d\mu_g.
    \end{split}
    \end{equation}
        In addition, for $\w = \w'$ in \eqref{eq:IPP3'} we obtain the following formula:
    \begin{equation}\label{eq:IPP3}
    \begin{aligned}
       \int_M \langle \Delta \w, \w \rangle \, d\mu_g &= \int_M \left( \lvert d\w \rvert^2 + \lvert \delta\w \rvert^2 \right) d\mu_g + \int_{\partial M} \langle \nu \lrcorner d\w, \iota^* \w \rangle \, d\mu_g \\
       &\quad - \int_{\partial M} \langle \iota^* \delta \w , \nu \lrcorner \w \rangle \, d\mu_g.
    \end{aligned}
    \end{equation}
 Moreover, applying \eqref{eq:IPP2} to $\int_M \langle \Delta^2 \omega, \omega' \rangle \, d\mu_g - \int_M \langle \omega, \Delta^2 \omega' \rangle \, d\mu_g $ gives us the following formula:
    \begin{equation}\label{eq:IPP4}
    \begin{aligned}
&\int_M \langle \Delta^2 \omega, \omega' \rangle \, d\mu_g - \int_M \langle \omega, \Delta^2 \omega' \rangle \, d\mu_g \\
&= \int_{\partial M} \langle \nu \lrcorner d \Delta \omega, \iota^* \omega' \rangle \, d\mu_g - \int_{\partial M} \langle \iota^* \omega, \nu \lrcorner d \Delta \omega' \rangle \, d\mu_g \\
&\quad - \int_{\partial M} \langle \iota^* \delta \Delta \omega, \nu \lrcorner \omega' \rangle \, d\mu_g + \int_{\partial M} \langle \nu \lrcorner \omega, \iota^* \delta \Delta \omega' \rangle \, d\mu_g \\
&\quad + \int_{\partial M} \langle \nu \lrcorner \Delta \omega, \iota^* \delta \omega' \rangle \, d\mu_g - \int_{\partial M} \langle \iota^* \delta \omega, \nu \lrcorner \Delta \omega' \rangle \, d\mu_g \\
&\quad - \int_{\partial M} \langle \iota^* \Delta \omega, \nu \lrcorner d \omega' \rangle \, d\mu_g + \int_{\partial M} \langle \nu \lrcorner d \omega, \iota^* \Delta \omega' \rangle \, d\mu_g.
\end{aligned}
 \end{equation}
Note that in \cite{taylor}, the identities involve $ \w $ on the boundary rather than  $\iota^*\w$, as in the above proposition. This is equivalent since for all $\alpha\in\Omega^p(M),\ \beta\in\Omega^{p+1}(M)$ we have $\langle\alpha,\nu\lrcorner\beta\rangle=\langle\iota^*\alpha,\nu\lrcorner\beta\rangle$ on $\partial M$.


\subsection{Elliptic operators and existence of solutions}\label{sec:EllipticiteConvFaible}
\subsubsection{Sobolev spaces}\label{sec:sobolev}
We still denote by $\nabla$ the Levi-Civita connection on the tangent bundle. Let $E\longrightarrow M$ be a smooth vector bundle equipped with a bundle norm. We write $\Gamma(E)$ for smooth sections of $E.$
For $ 1\leq p < \infty$ and $ m \in \mathbb{N} $. We will use the following Sobolev spaces : 

\begin{itemize}
    \item $ L^k(M;E) = \left\{ \w\in\Gamma(E) \ \middle| \ \int_M \lvert \w \rvert^k \, d\mu_g < +\infty \right\} / \left\{ \w\in\Gamma(E) \ \middle| \  \w=0\ \text{a.e} \right\} $,


    \item $ W^{m,k}(M;E) = \left\{ \w \in L^k(M) \ \middle| \ \forall \ 1\leq j\leq m, \nabla^j\w \in L^k(M;E^{(j)}) \right\} $,$\text{where $E^{(j)}=(TM)^{\otimes j}\otimes E$}$,

    \item $ H^m(M;E) = W^{m,2}(M)$,


    \item $ H^1_0(M;E) = \left\{ \w \in H^1(M) \ \middle| \ \ \w_{|\partial M} = 0 \right\} $,


    \item $ H^2_0(M;E) = \left\{ \w \in H^2(M) \ \middle| \ \w_{|\partial M} = 0 \ \text{and} \ (\nabla \w)_{|\partial M} = 0 \right\} $.
\end{itemize}
In the sequel, the vector bundle $E$ will be one of the $\Lambda^pT^*M$ and we will omit it in the notations by writing $L^p(M)=L^p(M;E)$ and similarly for other spaces.


\subsubsection{Elliptic operators}


\begin{definition}\cite[Chapter 2, Section 10, p.183]{taylor}\label{def:ellipticiteClassic}
 Let $E=\Lambda^pT^*M$ and $A:\Gamma(E)\longrightarrow \Gamma(E)$ a linear differential operator of order $k\geq 1$.\\
 Its \emph{principal symbol} $\sigma_A(\xi):E_x\longrightarrow E_x$ is given by $\sigma_A(\xi)=\frac{1}{k!}\underbrace{[\cdots[[A,f],f]\cdots f]}_{k\ \text{commutators}}$, where for all $x\in M$ and $\xi\in T^*_xM$, $f$ is a smooth map such that $d_xf=\xi.$ \\
 The operator $A$ is \emph{elliptic} if and only if for all $x\in M$ and $\xi\in T_x^*M\setminus\{0\}$, its principal symbol is invertible, i.e., $\det(\sigma_A(\xi))\neq 0$. \end{definition}

 It follows from \cite[p.177]{taylor} that if $A$ and $B$ are differential operators then for all $\xi\in T^*M,$ $\sigma_{A\circ B}(\xi)=\sigma_A(\xi)\circ\sigma_B(\xi).$
\begin{example}
    The Hodge-de-Rham Laplacian and bi-Laplacian  are elliptic, and their principal symbols are given by: 
    \[\sigma_\Delta(\xi) = -|\xi|^2 \qquad \text{and} \qquad \sigma_{\Delta^2}(\xi) =|\xi|^4,\]
    where $\xi \in T_x^*M$. 
\end{example}
For the proof, see \cite[p.182]{taylor}.

\subsubsection{ Elliptic boundary problems in the sense of Shapiro-Lopatinskij }\label{sec:shapiro}
The aim of this paragraph is to give the definition of the ellipticity of a differential boundary problem, in the sense of Shapiro-Lopatinskij, as presented in \cite[Paragraph 1.6]{GunterSchwartz}. Let us consider the following boundary problem:
\begin{equation}\label{eq:PbPourLaDefDeShapiro}
\begin{cases}
    A \w = 0 & \text{in } M, \\
    B_1\w = 0 & \text{on } \partial M, \\
    B_2\w = 0 & \text{on } \partial M, \\
    \vdots & \vdots \\
    B_p\w = 0 & \text{on } \partial M,
\end{cases}
\end{equation}
where $A:\Gamma(E)\longrightarrow\Gamma(E)$ is a linear differential operator of order $k$, and for all $1\leq j\leq p$ $B_j:\Gamma(E)\longrightarrow\Gamma(E_j)$ is a linear differential operator. Here $E\longrightarrow M$ and $(E_j\longrightarrow \partial M)_{1\leq j\leq p}$ are vector bundles.

The principal symbol \begin{eqnarray*}
 \sigma_A:T^*_xM &\longrightarrow & \Endo (E_x)\\
 \xi& \longmapsto &  \sigma_A(\xi)  \notag 
    \end{eqnarray*} has locally a polynomial homogeneous expression of order $k$ in the coordinates of $\xi.$ Therefore, it extends to generalized covectors with values in the algebra of differential operators on $C^\infty(\mathbb{R},E_x\otimes\mathbb{C})$, i.e., $\tilde{\xi}\in T^*_xM\otimes(\mathbb{C}\oplus\mathbb{C}\cdot \partial_t),$ where the multiplication in $\mathbb{C}\oplus\mathbb{C}\cdot \partial_t$ is given by $(a_1+b_1\partial_t)(a_2+b_2\partial_t)=a_1a_2+(a_1b_2+a_2b_1)\partial_t+b_1b_2\partial_t^2.$
\begin{definition}\cite[Definition 20.1.1]{Hormander}\cite[Definition 1.6.1]{GunterSchwartz}\label{def:ellipticiteShapiro}
The problem \eqref{eq:PbPourLaDefDeShapiro} is said to be \emph{elliptic} in the sense of Shapiro-Lopatinskij if and only if:
\begin{itemize}
    \item[$\bullet$] $A$ is elliptic in the sense of \defref{def:ellipticiteClassic}, i.e., $\sigma_{A}(\xi)$ is invertible for all $\xi \in T^*M \backslash \{0\}$. 
    \item[$\bullet$] For all $v \in T_x^*\partial M \backslash \{0\}$, the map $\Phi$
    \begin{align*}
    \Phi : \mathcal{M}^+_{A,v} &\longrightarrow \bigoplus_{j=1}^{k} E_j \\
    y &\longmapsto \left( \sigma_{B_1}(-iv+\partial_t\nu^\flat)y, \sigma_{B_2}(-iv+\partial_t\nu^\flat)y,\dots, \sigma_{B_k}(-iv+\partial_t\nu^\flat)y \right)(0)
    \end{align*}
    is an isomorphism,
    where $-iv + \partial_t\nu^\flat\in T^*_xM\otimes(\mathbb{C}\oplus\mathbb{C}\cdot \partial_t)$ for $x\in\partial M$ and
    \begin{equation}\label{eq:Mv+}
    \mathcal{M}^+_{A,v} := \{\text{bounded solutions } y=y(t) \text{ on } \mathbb{R}_+ \text{ of the ODE } \sigma_{A}(-iv+\partial_t\nu^\flat)y=0\}.
    \end{equation}

\end{itemize}
\end{definition}

\begin{lemma}
In the case of the bi-Laplacian, the space $\mathcal{M}^+_{\Delta^2,v}$ is given by:
\[
\mathcal{M}^+_{\Delta^2,v} = \spann\left( e^{-|v| t}(at+b) \cdot \w_0 \mid a,b \in \mathbb{R},\ \w_0 \in \Lambda^p T^*_x M_{|\partial M} \right)
\]
and its dimension is $2 \binom{n}{p}$.
\end{lemma}

\begin{proof}
Let $\xi \in T^*M$, $v \in T^*\partial M$, and $\nu \in TM_{|\partial M}$.
For $A=\Delta^2$ in \eqref{eq:Mv+} we have  
\[
\mathcal{M}^+_{\Delta^2,v} := \{\text{bounded solutions on } \mathbb{R}_+ \text{ of the ODE } \sigma_{\Delta^2}(-iv+\partial_t\nu^\flat)y = 0\},
\]
where $\sigma_{\Delta^2}(\xi) = |\xi|^4$. Thus,
\begin{align}
    \sigma_{\Delta^2}(-iv+\partial_t\nu^\flat) &= |-iv + \partial_t \nu|^4 \notag \\
    &= (|-iv + \partial_t \nu|^2)^2 \notag \\
    &= (\langle -iv + \partial_t \nu, -iv + \partial_t \nu \rangle)^2 \notag \\
    &= ((-i)^2\langle v,v \rangle + \langle \partial_t \nu, \partial_t \nu \rangle - 2\underbrace{\langle \underbrace{iv}_{\in T^*\partial M}, \underbrace{\partial_t \nu}_{\perp T^*\partial M} \rangle}_{0})^2. \notag
\end{align}
Therefore,
\[
\sigma_{\Delta^2}(-iv+\partial_t\nu^\flat) = (-|v|^2 + (\partial_t)^2 \cdot \underbrace{|\nu|^2}_{1})^2 = ((\partial_t)^2 - |v|^2)^2 = \partial_t^4 - 2|v|^2 \partial_t^2 + |v|^4.
\]
Now solving the equation $y = y(t): \mathbb{R}_+ \longrightarrow \Lambda^pT^*M$,
\[
(\sigma_{\Delta^2}(-iv+\partial_t\nu^\flat)y)(t) = 0
\]
is equivalent to solving 
\[
(\partial_t^4 - 2|v|^2 \partial_t^2 + |v|^4) y = 0.
\]
Thus, the equation becomes $y^{(4)}(t) - 2|v|^2 y''(t) + |v|^4 y(t) = 0$, which is a linear ODE with constant coefficients. The general solution is given by: 
\[
y(t) = (a_1 t + b_1) e^{|v| t}\w_0 + (a_2 t + b_2) e^{-|v| t}\w'_0, \quad a_1, b_1, a_2, b_2 \in \mathbb{R}\ \text{and}\ \w_0,\w'_0 \in \Lambda^p T^*_x M_{|\partial M}.
\]
Since we are looking for a bounded solution, we require that $|y(t)| \leq M$ for all $t \geq 0$, which implies $a_1 = b_1= 0 $, hence
\[
y(t) = (a t + b) e^{-|v| t}\w_0, \quad a, b \in \mathbb{R}\ \text{and}\ \w_0 \in \Lambda^p T^*_x M_{|\partial M}.
\]
Consequently,
\[
\mathcal{M}_{\Delta^2,v}^+ = \spann\left(e^{-|v| t}(at + b) \cdot \w_0 \mid a,b \in \mathbb{R}, \w_0 \in \Lambda^p T^*_x M_{|\partial M}\right).
\]
To complete the proof of the lemma, $\mathcal{M}_{\Delta^2,v}^+$ depends on two parameters $a$ and $b$. Moreover, $\w_0 \in \Lambda^p T^*_x M$, which is a space of dimension $\binom{n}{p}$. Thus, we have
\[
\dim(\mathcal{M}_{\Delta^2,v}^+) = 2 \binom{n}{p}.
\]

\end{proof}


\subsubsection{Existence of solutions of boundary problems} \label{sec:lionsMagenes}
In this section, we present some results from \cite[Chapter 2]{LionsMagenes}, which will be useful for our work.\\
We denote by $\rho(x)$ a smooth function in $M$, that is positive in $M\setminus\partial M$, vanishes on the boundary $\partial M$, and whose normal derivative is non-zero on the boundary.

As in \cite[Chapter 2 - Definition 6.1]{LionsMagenes}, the Hilbert space $\Xi^s(M)$ is defined for \emph{$s\in\mathbb{N}\cup \{0\}$}, as:
    \[
    \Xi^s(M) := \{u \mid \rho^{j} \nabla^ju \in L^2(M), \ \forall\ 0\leq j\leq s\},
    \]
    equipped with the norm:
    \[
    \lVert u \rVert_{\Xi^s(M)} = \sum_{j\leq s} \lVert \rho^{j} \nabla^j u \rVert_{L^2(M)}.
    \] The space $\Xi^s(M)$ does not depend on the choice of $\rho.$
    We note that $\Xi^0(M) = L^2(M)$ and $H^s(M) \subset \Xi^s(M) \subset L^2(M)$. In addition $(\Xi^s(M))' = \Xi^{-s}(M)$ represents the dual of $\Xi^s(M)$.

    As in \cite[Chapter 2 - Definition 6.2]{LionsMagenes}, we define the Hilbert space $\Xi^s(M)$ for \emph{$s\in\mathbb{R}_+^*$}, $s=k+\theta$ with $k\in \mathbb{Z}_+$ and $0<\theta<1$, by $\Xi^s(M)=[\Xi^{k+1}(M),\Xi^k(M)]_{1-\theta}.$
    For the definition of $[X,Y]_\theta$ where $X,Y$ are two Hilbert spaces and $0\leq\theta\leq 1$, see \cite[Chapter 1 - Definition 2.1]{LionsMagenes}.

The following is an interpretation of \cite[Chapter 2 - Theorem 2.1]{LionsMagenes} in our context.
On $\Gamma(E),$ we say that the problems \[
\begin{array}{c@{\hspace{1cm}}c}
\begin{cases}
    \begin{aligned}
    &Au & = 0 && \text{on } M \\
    &B_1u &= 0 && \text{on } \partial M \\
    &\vdots&  \vdots &&\\
    &B_ku &= 0 && \text{on } \partial M \\
    \end{aligned}
\end{cases}
& \text{and} \qquad \quad
\begin{cases}
    \begin{aligned}
    &A^*u & = 0 && \text{on } M \\
    &C_1u &= 0 && \text{on } \partial M \\
    &\vdots&  \vdots &&\\
    &C_ku &= 0 && \text{on } \partial M \\
    \end{aligned}
\end{cases}
\end{array}
\] are \emph{dual}, if 
\begin{enumerate}
    \item $A$ is a linear elliptic differential operator of order $m$ and $A^*$ is the \emph{formal adjoint} of $A,$ i.e., for all $u,v\in \Gamma(E)$ with compact support in $M\setminus \partial M$, $\int_M\langle Au,v\rangle d\mu_g=\int_M\langle u,A^*v\rangle d\mu_g.$
    \item  There exist operators $(T_1,\cdots,T_k)$, $(S_1,\cdots,S_k)$ such that $\forall i \in \{1,\cdots,k\}$, $\deg(T_i)=m-1-\deg(B_i)$ and $\deg(S_i)=m-1-\deg(C_i)$.
    \item For all $u,v\in\Gamma(E),$ we have  \begin{equation} \label{eq:greenLionsMagenes}
    \int_{M} \langle Au,{v}\rangle \, d\mu_g - \int_{M} \langle u,{A^*v}\rangle \, d\mu_g  = \sum_{i=1}^{k} \int_{\partial M} \langle S_i u, {C_i v}\rangle \, d\mu_g - \sum_{i=1}^{k} \int_{\partial M} \langle B_i u, {T_i v} \rangle \, d\mu_g.
    \end{equation}
\end{enumerate}
  In this paper, we take $A=\Delta$ or $A=\Delta^2$, both are formally self adjoint: $A=A^*$. According to $A$ and the boundary conditions which we consider, the operators $B_j,\ C_j,\ S_j,$ and $T_j$ vary in each situation due to the integration by parts formulas presented in \propref{prop:IPP}. For example in the proof of  \propref{prop:l'minimum} we have $C_1\w=-\nu\lrcorner d\w,\ C_2\w=-\nu\lrcorner\w,\ B_1\w=\nu\lrcorner\w,\ B_2\w=\nu\lrcorner d\w,\ T_1\w=-\iota^*\delta\w,\ T_2\w=-\iota^*\w,\ S_1\w=\iota^*\w$ and $S_2\w=\iota^*\delta\w.$ 

 Assuming that the problems are dual, let $\mathcal{N}$ and $\mathcal{N}^*$ be the spaces defined by:  $\mathcal{N} := \{u \in \Gamma(E) \mid Au = 0, B_1u = 0, \dots, B_{k}u = 0\}$ and $\mathcal{N}^* := \{u \in \Gamma(E) \mid A^*u = 0, C_1u = 0, \dots, C_{k}u = 0\}$.
\begin{thm}\cite[Chapter 2 - Theorems 5.3 and 5.4]{LionsMagenes}\label{theo:thm5.4}
   Under the following assumptions:
    \begin{enumerate}[label=\roman*.]
        \item $M$ is a compact manifold with smooth boundary $\partial M$.
        \item  $A : \Gamma(E) \to \Gamma(E)$ is a differential operator of order $m$.
        \item The problem \eqref{eq:PbPourLaDefDeShapiro} is elliptic in the sense of Shapiro-Lopatinskij,

    \end{enumerate}
  Then for any $\boldsymbol{s \geq m}$, the following map
    \begin{align*}
    \mathcal{P}:H^s(M)/\mathcal{N} &\longrightarrow \{ H^{s-m}(M) \times \prod_{j=1}^{k} H^{s-m_j-\frac{1}{2}}(\partial M)\} \\
    \left[\w\right] &\longmapsto \left( A\w, B_1\w, \dots, B_{k}\w \right)
\end{align*}
  is a topological and algebraic isomorphism onto the space \[
\begin{aligned}
    \im(\mathcal{P}) &= \left\{ (f; g_1, \dots, g_k) \in H^{s-m}(M) \times \prod_{j=1}^{k} H^{s-m_j-\frac{1}{2}}(\partial M) \mid \right. \\
    & \quad \left. \int_M \langle f, v\rangle \, d\mu_g + \sum_{j=1}^{k} \int_{\partial M} \langle g_j, T_j v \rangle \, d\mu_g = 0 \ \text{for all } v \in \mathcal{N}^* \right\}.
\end{aligned}
\]
  In particular, solutions of $(A\w,B_1\w,B_2\w,\cdots,B_k\w)=(0,0,\cdots,0)$ are in all $H^s(M)$ with $s\geq m$, i.e, are smooth.
\end{thm}

Following \cite[Equations 6.24 and 7.21]{LionsMagenes}, for all $\boldsymbol{s<m}$, we define the following space \[D_A^s(M)=\{u\ |\ u\in H^s(M)\ | \ Au\in \Xi^{-m+s}(M)\}.\]
\begin{thm}\cite[Chapter 2 - Theorem 6.6]{LionsMagenes}\label{theo:thm6.6}
    Under the same hypotheses as in  \thref{theo:thm5.4}, for all $\boldsymbol{s \in ]-\infty,0] }$ such that $\boldsymbol{s-\frac{1}{2} \notin \mathbb{Z}}$, the following map:
  \begin{align*}
   \mathcal{P}: D_A^s(M)/\mathcal{N} &\longrightarrow \Xi^{s-m}(M) \times \prod_{j=1}^{k} H^{s-m_j-\frac{1}{2}}(\partial M) \\
    \left[\w\right] &\longmapsto (A\w, B_1\w, \dots, B_{k}\w)
\end{align*}
is an algebraic and a topological isomorphism onto the space $\im(\mathcal{P})$ that is given by \begin{equation}\label{eq:imgPourTheorem6.6et7.4}
\begin{aligned}
    \im(\mathcal{P}) &= \left\{ (f; g_1, \dots, g_k) \in \Xi^{s-m}(M) \times \prod_{j=1}^{k} H^{s-m_j-\frac{1}{2}}(\partial M) \mid \right. \\
    & \quad \left. \int_M \langle f, v\rangle \, d\mu_g + \sum_{j=1}^{k} \int_{\partial M} \langle g_j, T_j v \rangle \, d\mu_g = 0 \ \text{for all } v \in \mathcal{N}^* \right\}.
\end{aligned}
\end{equation}
\end{thm}

\begin{thm}\cite[Chapter 2 - Theorem 7.4]{LionsMagenes}\label{theo:thm7.4}
    Under the same hypotheses as in  \thref{theo:thm5.4}, for all $\mathbf{0 < s < m}$, the following map: 
    \begin{align*}
   \mathcal{P}: D_A^s(M)/\mathcal{N} &\longrightarrow \Xi^{s-m}(M) \times \prod_{j=1}^{k} H^{s-m_j-\frac{1}{2}}(\partial M) \\
    \left[\w\right] &\longmapsto (A\w, B_1\w, \dots, B_{k}\w)
\end{align*}
is an algebraic and topological isomorphism onto the space $\im(\mathcal{P})$ \eqref{eq:imgPourTheorem6.6et7.4}.

\end{thm}

\subsection{Variational characterizations of classical eigenvalue problems}\label{sec:DNSformes}
In this section, we will recall the classical problems on differential forms and their variational characterization, as we will use them later to establish the Kuttler-Sigillito inequalities.
\subsubsection{Classical eigenvalue problems on differential forms}
\begin{definition}
Let $(M^n,g)$ be a compact connected Riemannian manifold with boundary $\partial M$. The Dirichlet problem for differential forms is defined as follows:
\begin{equation}\label{eq:dirichletFormes}
 \begin{cases}
    \Delta \w = \lambda \w & \text{on } M \\
    \w = 0 & \text{on } \partial M,
\end{cases}
\end{equation}
where $\lambda \in \mathbb{R}$. The Neumann problem for differential forms (with absolute boundary conditions) is defined by
\begin{equation}\label{eq:neumannFormesAbsolue}
 \begin{cases}
    \Delta \w = \mu \w & \text{on } M \\
    \nu \lrcorner \w = 0 & \text{on } \partial M \\
    \nu \lrcorner d\w = 0 & \text{on } \partial M,
\end{cases} 
\end{equation}
where $\mu\in \mathbb{R}$. \end{definition} 
For $p\in\{0,\cdots,n\}$, the kernel of the Dirichlet problem is trivial and the kernel of the Neumann problem is $H_A^p(M)$ defined in \eqref{eq:Hap}. The spectrum of the Laplacian for the Dirichlet and Neumann problems on forms are discrete, consisting respectively of eigenvalues 
\[0<\lambda_{1,p} \leq \lambda_{2,p} \leq \cdots\quad \text{and}\quad 0\leq\mu_{1,p} \leq \mu_{2,p} \leq \cdots .\]

Now, let $p \in \{0, \dots, n\}$. For every $p$-form $\w$ on the boundary, according to \cite{RaulotSavo} (see also  \lemref{lem:SteklovFormeGénéral} below) there exists a unique $p$-form $\hat{\w}$ on $M$ solving the following problem:
\begin{equation}\label{eq:steklovFormes}
 \begin{cases}
    \Delta \hat{\w} = 0 & \text{on } M \\
    \iota^* \hat{\w} = \w & \text{on } \partial M \\
    \nu \lrcorner \hat{\w} = 0 & \text{on } \partial M.
\end{cases}
\end{equation}
The differential form $\hat{\w}$ is called the tangential harmonic extension of $\w$. 
\begin{definition}
The Steklov operator $T^{[p]}: \Lambda^p(\partial M) \to \Lambda^p(\partial M)$ is defined by $T^{[p]}(\w) = -\nu \lrcorner d\hat{\w}$.\end{definition}
It is proved in \cite[Section 2]{RaulotSavo}, that the operator $T^{[p]}$ is an elliptic, self-adjoint and pseudodifferential operator with a discrete spectrum consisting of eigenvalues
\[
0 \leq \sigma_{1,p} \leq \sigma_{2,p} \leq \cdots .
\]
Its kernel is also $H_A^p(M)$.

\subsubsection{Variational characterizations}
In this section, we provide some of the variational characterizations of the eigenvalues of the previous problems on differential forms, derived from the min-max principle (see \cite[Chapter 1]{Chavel}), that we will use later on. Several of these expressions can also be found in \cite{BesselFidaGeorgeNicolas,GueriniThese, Karpukhin, RaulotSavo}. The proofs primarily follow the same lines as those used for the scalar case and we omit them here.

Recall that $H^s(M)$ and $H_0^2(M)$ have been defined in \secref{sec:sobolev}. Let us set \[H_N^1(M):=\{\w\in H^1(M)\ | \ \nu\lrcorner\w=0\}\] and \[H_{N,1}^2(M):=\{\w\in H^2(M)\ | \ \nu\lrcorner\w=0\ \text{and} \ \nu\lrcorner d\w=0\}.\]

\begin{prop}
  The first eigenvalue $\lambda_{1,p}$ of the problem \eqref{eq:dirichletFormes} is given by:
   \begin{equation}\label{eq:vp1DirichletForme}
\lambda_{1,p}= \inf\left\{\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2( M)}}\ \Big|\ \w\in H^1_0(M)\right\}.
\end{equation}
\end{prop}

\begin{prop}\label{prop:vpDirichletFormes2}
The $k\textsuperscript{th}$ eigenvalue $\lambda_{k,p}$ of the problem \eqref{eq:dirichletFormes} is given by
   \begin{align}
\lambda_{k,p}&=\underset{\substack{V\subset{H}^1_0(M)\\ \dim(V)=k}}{\inf}\ \underset{\substack{0\neq \w \in V }}{\sup} \frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2( M)}}\label{eq:vpKDirichletForme} \\ 
&=\underset{\substack{V\subset{H}^2(M)\cap H_0^1(M)\\ \dim(V)=k}}{\inf}\ \underset{\substack{0\neq \nabla\w \in V }}{\sup} \frac{\lVert \Delta\w \rVert^2_{L^2( M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}.\label{eq:vpKAlternativeDirichletForme}
\end{align}

\end{prop}


\begin{prop} 
 The first non-zero eigenvalue $\mu_{1,p}$ of the problem \eqref{eq:neumannFormesAbsolue} is given by
\begin{align}\label{eq:vpNeumannAbsolueForme}
\mu_{1,p} &= \inf\left\{\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2( M)}}\ \Big|\ \w\in H_N^1(M)\ \text{and}\ \w\perp_{L^2(M)}H_A^p(M)\right\}.
\end{align}

\end{prop}


\begin{prop}
    An alternative non-zero variational characterization of $\mu_{1,p}$ for the problem \eqref{eq:neumannFormesAbsolue} is given by 
    \begin{equation}\label{eq:vp1NeumannAbsolueFormeAlternative}
        \mu_{1,p} = \inf\left\{\frac{\lVert \Delta\w \rVert^2_{L^2( M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}\ \Big|\ \w\in H^2_{N,1}(M)\setminus H_A^p(M)\right\}.
    \end{equation}
\end{prop}


\begin{prop}\label{prop:CaracterisationsNeumannAbsolueFormes}
   The $k\textsuperscript{th}$  non-zero eigenvalue $\mu_{k,p}$ of the problem \eqref{eq:neumannFormesAbsolue} is given by 
   \begin{align}
      \mu_{k,p}&= \underset{\substack{ V\subset H_N^1(M)\\ \dim(V)=k+\dim H_A^p(M)}}{\inf}\ \underset{\substack{0\neq \w \in V }}{\sup} \frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2( M)}}\label{eq:vp1AlternativeNeumannAbsolueForme1} \\ 
      &= \underset{\substack{V\subset H_{N,1}^2(M)/ H_A^p(M)\\ \dim(V)=k}}{\inf} \ \  \underset{\substack{0\neq \w \in V/ H_A^p(M)}}{\sup} \ \frac{\lVert \Delta\w \rVert^2_{L^2( M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}. \label{eq:vp1AlternativeNeumannAbsolueForme}
   \end{align}

\end{prop}

\begin{prop}\cite[Theorem 11]{RaulotSavo}
  The first non-zero eigenvalue of the Steklov problem on differential forms is given by
   \begin{align}\label{eq:sigma1formesSteklov}
\sigma_{1,p} &=\inf\left\{\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2( \partial M)}}\ \Big|\ {\w}\in H_N^1(M)\ \text{and}\ \w\perp_{L^2(\partial M)}H_A^p(M)\right\}. 
\end{align}
\end{prop}

\begin{prop}\label{prop:sigma1Alternatif}
  An alternative variational characterization of the first non-zero eigenvalue of the Steklov problem on differential forms is given by
    \begin{align}
\sigma_{1,p} &=\inf\left\{\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}\ |\ {\w}\in\Omega^{p}(M),\ \Delta\w=0 \ \text{on} \ M,\ \nu\lrcorner{\w}=0\ \text{on}\ \partial M, \ \w\perp_{L^2(M)}H_A^p(M)\right\}\label{eq:sigma1formeOrthHAP}\\
&=\inf\left\{\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}\ |\ {\w}\in\Omega^{p}(M)\backslash H_A^p(M),\ \Delta\w=0 \ \text{on} \ M,\ \nu\lrcorner{\w}=0 \ \text{on}\ \partial M\right\}\label{eq:sigma1formeNotInHAP}
\end{align}
\end{prop}
\begin{prop}
         The $k$\textsuperscript{th} non-zero eigenvalue $\sigma_{k,p}$ of the problem \eqref{eq:steklovFormes} is given by
   \begin{align}
\sigma_{k,p}&=\underset{\substack{ V\subset\check{H}_N^1(M)\\\dim(V)=k}}{\inf}\ \underset{\substack{0\neq \w \in V }}{\sup} \frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}}\label{eq:sigmakformesSteklov}\\  
&=\underset{\substack{V\subset\mathcal{A}\\ \dim(V)=k}}{\inf}\ \  \underset{\substack{0\neq \w \in V }} {\sup} \frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}},
\end{align}
where $\check{H}_N^1(M):=\{\w\in H^1_N(M)\ | \ \w\perp_{L^2(\partial M)}H_A^p(M)\}$ and $\mathcal{A}:=\{\w\in H^2(M)\ | \ \nu\lrcorner\w=0,\ \Delta\w=0\}$.
\end{prop}

\section{Spectral properties of BSN1}

We first consider the problem BSN1 \eqref{eq:BSNF1}, which is the analogue of \eqref{eq:BSDF1} given in \cite{BSFidaGeorgeOlaNicolas} by adapting its boundary conditions to the Neumann ones. 
\subsection{Ellipticity of BSN1}\label{sec:elliticiteBSNF1preuve}
We begin with showing the ellipticity of the problem BSN1 \eqref{eq:BSNF1}.\begin{prop}
    Let $(M^n,g)$ be a compact Riemannian manifold with a smooth boundary $\partial M$. The BSN1 \eqref{eq:BSNF1} is elliptic in the sense of Shapiro-Lopatinskij.
\end{prop}

\begin{proof}
Let $B_1,B_2,B_3$ et $B_4$ be the following maps
\begin{align*}
B_1: \Omega^p(M) &\longrightarrow \Gamma(E_1=\Lambda^{p-1}T^*\partial M) \quad ; & B_2: \Omega^p(M) &\longrightarrow \Gamma(E_2=\Lambda^{p}T^*\partial M) \\
\w &\longmapsto \nu\lrcorner\w & \w &\longmapsto \nu\lrcorner d\w \\ \\
B_3: \Omega^p(M) &\longrightarrow \Gamma(E_3=\Lambda^{p}T^*\partial M) \qquad ; & B_4: \Omega^p(M) &\longrightarrow \Gamma(E_4=\Lambda^{p-1}T^*\partial M) \\
\w &\longmapsto \nu\lrcorner\Delta d\w +\ell\iota^*\w & \w &\longmapsto \nu\lrcorner\Delta\w+\ell\iota^*\delta\w
\end{align*}

where $\ell$ is a fixed real number. We note that $E_1$ and $E_4$ have rank $\binom{n-1}{p-1}$ and that $E_2$ and $E_3$ have rank $\binom{n-1}{p}$. Therefore, the rank of $\bigoplus_{j=1}^4 E_j$ is $2\big(\binom{n-1}{p} + \binom{n-1}{p-1}\big) = 2\binom{n}{p} = \dim \mathcal{M}_{\Delta^2,v}^+$. We have to compute the principal symbols of the $B_j$ for $1 \leq j \leq 4$.

Let us fix $\xi\in T^*M$ and let $f:M\longrightarrow\mathbb{R}$ be such that $d_xf=\xi$. The operator $B_1$ is of order 0, so its principal symbol is $B_1$ itself: $\sigma_{B_1}(\xi)\w = \nu \lrcorner \w$.

The operator $B_2$ is of order 1, recall that $\xi$ has both a normal and a tangential component, i.e., $\xi=\xi_\nu\nu^{\flat}+\iota^*\xi$ for all point in $\partial M$. By definition,
 \begin{align*}
    \sigma_{B_2}(\xi)\w &= [B_2,f]\w\\
    &= B_2(f\w) - fB_2(\w) \\
    &= \nu\lrcorner d(f\w) - f\nu\lrcorner d\w \\
    &= \nu\lrcorner f d\w + \nu\lrcorner (df\wedge \w) - f\nu\lrcorner d\w \\
    &= \nu\lrcorner(df\wedge\w) \\
    &= (\nu\lrcorner df)\w - df\wedge(\nu\lrcorner\w) \\
    &= (\nu\lrcorner\xi)\w - \xi\wedge(\nu\lrcorner\w) \\
    &= \xi_\nu\w - \xi_\nu\nu\wedge(\nu\lrcorner\w) - \iota^*\xi\wedge(\nu\lrcorner\w) \\
    &= \xi_\nu(\w - \nu\wedge(\nu\lrcorner\w)) - \iota^*\xi\wedge(\nu\lrcorner\w) \\
    &= \xi_\nu\iota^*\w - \iota^*\xi\wedge(\nu\lrcorner\w).
\end{align*}

The operator $B_3$ is of order $3$ and $\sigma_{B_3}(\xi)\w=\big(\sigma_{\nu\lrcorner}\circ\sigma_\Delta\circ\sigma_d\big)(\xi)\w$. We have $ \sigma_d(\xi)\w= \xi\wedge\w$, see \cite[p.181]{taylor}.

Therefore $\sigma_{\Delta \circ d} = -|\xi|^2 \xi \wedge \w$. Since $\nu \lrcorner$ is of order 0, we get
$\sigma_{B_3}(\xi)\w=-\lvert\xi\rvert^2\nu\lrcorner(\xi\wedge\w).$

 Finally, $B_4$ is of order 2 and
 $\sigma_{B_4}(\xi)\w=\sigma_{\nu\lrcorner}\circ\sigma_\Delta(\xi)\w=-\nu\lrcorner\lvert\xi\rvert^2\w=-\lvert\xi\rvert^2\nu\lrcorner\w.$ 

 We now need to evaluate all of the principal symbols for $\xi=(-iv+\partial_t\nu^\flat)$ with $v\in T^*M\setminus\{0\}$ and apply it to $y(t)=e^{-\lvert v\rvert t}(at+b)\w_0$. For $\sigma_{B_1}$ we get
\begin{align*}
    \sigma_{B_1}(-iv+\partial_t\nu^\flat)(y) &= \nu\lrcorner y \\
    &= \nu\lrcorner(at+b)e^{-\lvert v \rvert t}\w_0 \\
    &= (at+b)e^{-\lvert v \rvert t}\nu\lrcorner\w_0,
\end{align*}
then $ \sigma_{B_1}(-iv+\partial_t\nu^\flat)(y)(0)=b\nu\lrcorner\w_0.$

Similarly for $\sigma_{B_2}$,
\begin{align*}
    \sigma_{B_2}(-iv+\partial_t\nu^\flat)(y) &= \partial_t\iota^*y - \iota^*(-iv+\partial_t)\wedge(\nu\lrcorner y) \\
    &= \partial_t\iota^*(at+b)e^{-\lvert v \rvert t}\w_0 + \iota^*(iv)\wedge(\nu\lrcorner(at+b)e^{-\lvert v \rvert t}\w_0) \\
    &= \iota^*ae^{-\lvert v \rvert t}\w_0 - \iota^*(at+b)\lvert v \rvert e^{-\lvert v \rvert t}\w_0 \\
    &\quad + i(at+b)e^{-\lvert v \rvert t}\iota^*v\wedge(\nu\lrcorner\w_0).
\end{align*}
Thus 
\begin{align*}
    \sigma_{B_2}(-iv+\partial_t\nu^\flat)(y)(0) &= a\iota^*\w_0 - b\lvert v\rvert \iota^*\w_0 + ib\iota^*v\wedge(\nu\lrcorner\w_0) \\
    &= \iota^*\w_0(a - b\lvert v\rvert) + ib\iota^*v\wedge(\nu\lrcorner\w_0).
\end{align*}
Next for $\sigma_{B_3}$ we have \begin{align*}
    \sigma_{B_3}(-iv+\partial_t\nu^\flat)(y)&= -\lvert-iv+\partial_t\rvert^2\nu\lrcorner\big((-iv+\partial_t)\wedge y\big) \\
    &= -\lvert-iv+\partial_t\nu\rvert^2\nu\lrcorner\big((-iv+\partial_t)\wedge(at+b)e^{-\lvert v \rvert t}.\w_0\big) \\
    &= -\langle-iv+\partial_t\nu,-iv+\partial_t\nu\rangle.\\
    &\qquad \big[\nu\lrcorner\big(-i(at+b)e^{-\lvert v \rvert t}v\wedge\w_0+\partial_t(at+b)e^{-\lvert v \rvert t}\nu\wedge\w_0\big)\big] \\
    &= (\lvert v \rvert^2-\partial_t^2)\big[-i(at+b)e^{-\lvert v \rvert t}\big(\underbrace{(\nu\lrcorner v)}_{0}.\w_0-(v\wedge\nu)\lrcorner\w_0\big) \\
    &\quad +(be^{-\lvert v \rvert t}-\lvert v \rvert (at+b)e^{-\lvert v \rvert t})\nu\lrcorner(\nu\wedge\w_0)\big] \\
    &= (\lvert v \rvert^2-\partial_t^2)e^{-\lvert v \rvert t}\big[i(at+b)v\wedge(\nu\lrcorner\w_0)+b-\lvert v \rvert (at+b)\nu\lrcorner(\nu\wedge\w_0)\big] \\
    &=\lvert v \rvert^2e^{-\lvert v\rvert t}\big[i(at+b)v\wedge(\nu\lrcorner\w_0)+b-\lvert v \rvert (at+b)\nu\lrcorner(\nu\wedge\w_0)\big]\\ 
    &\quad -\lvert v \rvert^2e^{-\lvert v\rvert t}\big[i(at+b)v\wedge(\nu\lrcorner\w_0)+b-\lvert v \rvert (at+b)\nu\lrcorner(\nu\wedge\w_0)\big] \\
    &\quad +2\lvert v \rvert e^{-\lvert v\rvert t}\big((iav\wedge(\nu\lrcorner\w_0)-\lvert v\rvert a\nu\lrcorner(\nu\wedge \w_0)\big)\\
    &=2\lvert v \rvert e^{-\lvert v\rvert t}\big((iav\wedge(\nu\lrcorner\w_0)-\lvert v\rvert a\nu\lrcorner(\nu\wedge \w_0)\big).
\end{align*}
Noting that $\nu \lrcorner (\nu \wedge \w_0) = (\nu \lrcorner \nu) \w_0 - \nu \wedge (\nu \lrcorner \w_0) = \w_0 - \nu \wedge (\nu \lrcorner \w_0) = \iota^* \w_0$, we obtain that
\[
\sigma_{B_3}(-iv+\partial_t\nu^\flat)(y) = 2 |v| e^{-|v|t} a \left( iv \wedge (\nu \lrcorner \w_0) - |v| \iota^* \w_0 \right),
\]
and thus
\[
\sigma_{B_3}(-iv+\partial_t\nu^\flat)(y)(0) = 2 |v| a \left( iv \wedge (\nu \lrcorner \w_0) - |v| \iota^* \w_0 \right).
\]


 Finally for $\sigma_{B_4},$ \begin{align*}
    \sigma_{B_4}(-iv+\partial_t\nu^\flat)(y) &= -\nu\lrcorner\lvert\xi\rvert^2y \\
    &= -\nu\lrcorner\lvert -iv+\partial_t\nu\rvert^2(at+b)e^{-\lvert v\rvert t}\w_0 \\
    &= -\nu\lrcorner(\partial_t^2-\lvert v\rvert^2)(at+b)e^{-\lvert v\rvert t}\w_0 \\
    &= \lvert v\rvert^2(at+b)e^{-\lvert v\rvert t}\nu\lrcorner\w_0 -\nu\lrcorner(-2a\lvert v \rvert e^{-\lvert v\rvert t}+ (at+b)\lvert v\rvert^2 e^{-\lvert v\rvert t})\w_0 \\
    &= 2a\lvert v \rvert e^{-\lvert v\rvert t}\nu\lrcorner\w_0,
\end{align*} we conclude $\sigma_{B_4}(-iv+\partial_t\nu^\flat)(y)(0)=2a\lvert v \rvert\nu\lrcorner\w_0.$
Based on the calculations above, we obtain the following map:
\begin{align*}
\Phi : \mathcal{M}^+_{\Delta^2,v} &\longrightarrow \bigoplus_{j=1}^4 E_j \\
y &\longmapsto \Phi(y)
\end{align*}
such that  \[\Phi(y)=\big( b\nu\lrcorner\w_0,(a-b\lvert v \rvert)\iota^*\w_0+ib\iota^*v\wedge(\nu\lrcorner\w_0),2\lvert v\rvert \big(iav\wedge(\nu\lrcorner\w_0)-\lvert v\rvert a\iota^*\w_0\big),2a\lvert v \rvert \nu\lrcorner\w_0\big).\]

To end the proof, we must show that $\Phi$ is an isomorphism. Since both source and target spaces have the same finite dimension, it is enough to show that $\Phi$ is injective. Suppose that $\Phi(y)=0,$ then
\begin{align*}
&\begin{cases}
  b\nu\lrcorner\w_0 &= 0 \qquad (1) \\
  (a-b|v|)\iota^*\w_0 + ib\iota^*v\wedge(\nu\lrcorner\w_0) &= 0  \qquad (2)\\
 2\lvert v\rvert \big(iav\wedge(\nu\lrcorner\w_0)-\lvert v\rvert a\iota^*\w_0\big) &= 0  \qquad (3)\\
 2a\lvert v \rvert \nu\lrcorner\w_0 &= 0  \qquad (4)
\end{cases}
\end{align*}
If $a$ and $b$ are zero, then $y$ is zero. If $a$ or $b$ are non-zero, then from (1) and (4), we deduce that $\nu\lrcorner\w_0 = 0$. Substituting this result into (2) and (3), we find that $\iota^*\w_0 = 0$. Consequently, $\w_0 = 0$, which implies that $y = 0$. Hence, $\Phi$ is injective and the problem \eqref{eq:BSNF1} is elliptic.

\end{proof}


\subsection{Discrete spectrum of BSN1}The aim of this paragraph is to establish the following theorem. The approach of the proof is mainly inspired by the work in \cite{BSFidaGeorgeOlaNicolas,FerreroGazzolaWeth}.


\begin{thm}\label{thm:TheoremeGeneralBSNF1PourLaPreuve}
Let $(M^n, g)$ be a compact Riemannian manifold with a smooth boundary $\partial M$ and let $\nu$ be the unit inward normal vector to the boundary. Then the BSN1 \eqref{eq:BSNF1} for differential p-forms, has a discrete spectrum consisting of an unbounded non-decreasing sequence of non-negative real eigenvalues with finite multiplicities $(\ell_i)_{i \geq 0}$ in the form
\[
0 < \ell_1 \leq \ell_2 \leq \ell_3 \leq \cdots.
\]
Its kernel is given by $H_A^p(M)$ \eqref{eq:Hap}. Moreover, all its eigenforms are smooth.
\end{thm}

\begin{lemma}\label{lem:Bilap1}
     For $f\in \Omega^p(M)$, $\w_1 \in \Gamma(\Lambda^{p-1}T^*\partial M)$, $\w_2 \in \Gamma(\Lambda^{p}T^*\partial M)$, $\w_3 \in \Omega^p(\partial M)$, and $\w_4 \in \Omega^{p-1}(\partial M)$ the boundary problem
    \begin{eqnarray}\label{eq:Bilap1}
   (biLap_1) \begin{cases}
    \Delta^2\w &= f \ \qquad \text{on } M \\
    \nu \lrcorner \w &= \w_1 \qquad \text{on } \partial M\\
    \nu \lrcorner d\w &= \w_2 \qquad \text{on } \partial M\\
    \iota^*\w &= \w_3 \qquad \text{on } \partial M\\
    \iota^*\delta\w &= \w_4 \qquad \text{on } \partial M.
    \end{cases}
     \end{eqnarray} has a unique solution. Moreover, if $f,\w_1,\cdots,\w_n$ are smooth, then $\w$ is also smooth.
\end{lemma}
\begin{proof} Let us first show that the problem $(biLap_1)$ is elliptic in the sense of Shapiro-Lopatinskij. As in section \secref{sec:shapiro}, we denote by $B_1, B_2, B_3,$ and $B_4$ the following maps:

\begin{align*}
    B_1: \Omega^p(M) &\longrightarrow \Gamma(E_1=\Lambda^{p-1}T^*\partial M) \quad ; & 
    B_2: \Omega^p(M) &\longrightarrow \Gamma(E_2=\Lambda^{p}T^*\partial M) \\
    \w &\longmapsto \nu \lrcorner \w & 
    \w &\longmapsto \nu \lrcorner d\w \\ \\
    B_3: \Omega^p(M) &\longrightarrow \Gamma(E_3=\Lambda^{p}T^*\partial M) \qquad ; & 
    B_4: \Omega^p(M) &\longrightarrow \Gamma(E_4=\Lambda^{p-1}T^*\partial M) \\
    \w &\longmapsto \iota^*\w & 
    \w &\longmapsto \iota^*\delta\w
\end{align*}
    Note that $\dim \mathcal{M}^+_{\Delta^2,v} = \dim\bigoplus_{j=1}^4 E_j = 2\binom{n}{p}$. Similarly to  \secref{sec:elliticiteBSNF1preuve}, we compute the principal symbols of the $B_i$ applied to $y=e^{-\lvert v\rvert t}(at+b)\w_0$ for some $\w_0\in\Lambda^p T^*M_{|\partial M}$.  We find \begin{align*}
\sigma_{B_1}(-iv + \partial_t \nu^\flat)(y)(0) &= b \, \nu \lrcorner \omega_0, \\
\sigma_{B_2}(-iv + \partial_t \nu^\flat)(y)(0) &= \iota^* \omega_0 (a - b |v|) + i b \, \iota^* v \wedge (\nu \lrcorner \omega_0), \\
\sigma_{B_3}(-iv + \partial_t \nu^\flat)(y)(0) &= b \, \iota^* \omega_0, \\
\sigma_{B_4}(-iv + \partial_t \nu^\flat)(y)(0) &= -a \, \nu \lrcorner \omega_0 + |v| b \, \nu \lrcorner \omega_0 + i v b \lrcorner \iota^* \omega_0.
\end{align*}
 Therefore, for all $y=e^{-|v| t}(at + b)\in \mathcal{M}_{\Delta^2,v}^+$, the map $\Phi$ of  \defref{def:ellipticiteShapiro} is given by
    \[
    \Phi(y) = \big( b\nu\lrcorner\w_0, (a-b|v|)\iota^*\w_0 + ib\iota^*v\wedge(\nu\lrcorner\w_0), b\iota^*\w_0, (b|v| - a)\nu\lrcorner\w_0 + bv\lrcorner\iota^*\w_0 \big).
    \] Let us show that $\Phi$ is injective. Suppose $\Phi(y) = 0$, then

    \begin{align*}
    &\begin{cases}
    b\nu\lrcorner\w_0 &= 0 \\
    (a-b|v|)\iota^*\w_0 + ib\iota^*v\wedge(\nu\lrcorner\w_0) &= 0 \\
    b\iota^*\w_0 &= 0 \\
    (b|v| - a)\nu\lrcorner\w_0 + bv\lrcorner\iota^*\w_0 &= 0
    \end{cases} 
    \Longrightarrow
    \begin{cases}
    b\nu\lrcorner\w_0 &= 0 \\
    (a-b\lvert v\rvert)\iota^*\w_0 &= 0 \\
    b\iota^*\w_0 &= 0 \\
    -(a-b\lvert v\rvert)\nu\lrcorner\w_0 &= 0.
    \end{cases}
    \end{align*}

    Hence, $(a-b\lvert v\rvert)\w_0 = 0$ and $b\w_0 = 0$, so $y = 0$. Thus, $\Phi$ is injective and consequently it is an isomorphism. Therefore $(biLap_1)$ is elliptic.


Performing an integration by parts \eqref{eq:IPP4} we get \[
\begin{aligned}
(\Delta^2 \w, \w')_{L^2(M)} &- (\w, \Delta^2 \w')_{L^2(M)} \\
&= (\nu \lrcorner d \Delta \w, \iota^* \w')_{L^2(\partial M)} - (\iota^* \w, \nu \lrcorner d \Delta \w')_{L^2(\partial M)} \\
&\quad - (\iota^* \delta \Delta \w, \nu \lrcorner \w')_{L^2(\partial M)} + (\nu \lrcorner \w, \iota^* \delta \Delta \w')_{L^2(\partial M)} \\
&\quad + (\nu \lrcorner \Delta \w, \iota^* \delta \w')_{L^2(\partial M)} - (\iota^* \delta \w, \nu \lrcorner \Delta \w')_{L^2(\partial M)} \\
&\quad - (\iota^* \Delta \w, \nu \lrcorner d \w')_{L^2(\partial M)} + (\nu \lrcorner d \w, \iota^* \Delta \w')_{L^2(\partial M)}.
\end{aligned}
\] Using the notations given in \secref{sec:lionsMagenes} $ T_1 \w = -\iota^* \Delta \w $, $ T_2 \w = -\iota^* \delta \Delta \w $, $ T_3 \w = \nu \lrcorner \Delta \w $, and $ T_4 \w = \nu \lrcorner d \Delta \w $. Similarly,  
$ C_1 \w = \iota^* \w $, $ C_2 \w = -\nu \lrcorner \w $, $ C_3 \w = \iota^* \delta \w $, and $ C_4 \w = -\nu \lrcorner d \w $. 

This implies that $ \mathcal{N}^* = 0 $ using an integration by parts \eqref{eq:IPP1} and that every harmonic differential form that vanishes on the boundary also vanishes identically on $M$ (see \cite{ColetteAnne}). The kernel $\mathcal{N}$ of problem \eqref{eq:Bilap1} is also trivial.

So by  \thref{theo:thm5.4} the map \begin{eqnarray*}
\mathcal{P}_{biLap_1}:{H^s}(M)&\longrightarrow & H^{s-4}(M) \oplus H^{s-\frac{1}{2}}(\partial M)\oplus H^{s-\frac{3}{2}}(\partial M)\oplus H^{s-\frac{1}{2}}(\partial M)\oplus H^{s-\frac{3}{2}}(\partial M)\\
  \left[\w\right]& \longmapsto & (\Delta^2\w,\nu\lrcorner\w,\nu\lrcorner d\w,\iota^*\w,\iota^*\delta\w)  \notag 
\end{eqnarray*} is an isomorphism on its image that is given for all $s\geq 4$ by
\[ \im(\mathcal{P}_{biLap_1}) =  H^{s-4}(M) \times H^{s-\frac{3}{2}}(\partial M)\times H^{s-\frac{1}{2}}(\partial M)\times H^{s-\frac{3}{2}}(\partial M)\times H^{s-\frac{1}{2}}(\partial M).\] Which concludes the proof of the lemma.  \\ %Replacing $\w'$ by an eigenform $\w$ of the problem \eqref{eq:Bilap1} with a zero r.h.s in \eqref{eq:IPP2}, we obtain $\Delta \w = 0$, and since $\w_{|\partial M} = 0$, it follows that $\w = 0$ by \cite{ColetteAnne}. Therefore, this problem has only the trivial solution $\w=0$. \\ 
\end{proof}







By analogy to  \defref{def:DeltaBSNfct}, we define the BSN1 operator denoted by $BSN1^{form}$ as:  
    \begin{eqnarray*}
   BSN1^{form}: H^{\frac{7}{2}}(\partial M) \times H^{\frac{5}{2}}(\partial M) & \longrightarrow & H^{\frac{3}{2}}(\partial M) \times H^{\frac{1}{2}}(\partial M) \\
    (\w_1, \w_2) & \longmapsto & (-\nu \lrcorner \Delta \hat{\w}, -\nu \lrcorner \Delta d\hat{\w})  \notag 
    \end{eqnarray*} 
    where $\hat{\w}\in H^4(M)$ is the solution of
    \begin{equation}\label{eq:bilapO1surj}
    (biLap_1) \begin{cases}
        \Delta^2 \hat{\w} = 0 & \text{on } M \\
        \nu \lrcorner \hat{\w} = 0 & \text{on } \partial M \\
        \nu \lrcorner d\hat{\w} = 0 & \text{on } \partial M \\
        \iota^* \hat{\w} = \w_3 & \text{on } \partial M\\
         \iota^* \delta \hat{\w} = \w_4 & \text{on } \partial M,
    \end{cases}
    \end{equation} which is a particular case of the problem \eqref{eq:Bilap1}.
    In the particular case of \eqref{eq:Bilap1} where $f=0,\ \w_1=0$ and $\w_2=0$ we have $\Delta^2\hat{\w}= 0$ on $M$, $\nu \lrcorner\hat{\w} = 0$ and $\nu \lrcorner d\hat{\w} = 0$ on $\partial M$, $\iota^*\hat{\w} = \w_3$, and $\iota^*\delta\hat{\w} = \w_4$. \\ Note that the eigenforms of this problem are the same as those of the BSN1 \eqref{eq:BSNF1}.


\begin{proof}[Proof of  \thref{thm:TheoremeGeneralBSNF1PourLaPreuve}] We define the following spaces:
    \[
    H^2_{N,1}(M) := \{ \w \in H^2(M) \ |\ \nu \lrcorner d\w =0\ \text{and}\ \nu \lrcorner \w = 0 \ \text{on} \ \partial M \},
    \]  
\[
\check{H}_{N,1}^2(M) := \left\{ \w \in H^2_{N,1}(M) \ | \ \w\perp_{L^2(\partial M)}H_A^p(M)\right\},
\]   \[Z_1 := \left\{ \w \in \Omega^p(M)\cap {H}_{N,1}^2(M) \mid \Delta^2 \w = 0 \ \text{on} \ M, \right\}\subset H_{N,1}^2(M)\] 
and \[\check{Z}_1 := \{ \w \in Z_1 \mid \w\perp_{L^2(\partial M)}H_A^p(M)\}=Z_1\cap\check{H}_{N,1}^2(M).\]

For any $\ell$-eigenform of BSN1 $ \w $ and $ \w' \in Z_1 $, we have from equation \eqref{eq:IPP2} the following identity:
    \begin{equation}\label{eq:utiliserDansLemme3.3}
        \int_M \langle \Delta \w, \Delta \w' \rangle \, d\mu_g = \ell \int_{\partial M} \left( \langle \iota^* \w, \iota^* \w' \rangle + \langle \iota^* \delta \w, \iota^* \delta \w' \rangle \right) \, d\mu_g.
   \end{equation}

Let us define for all $ \w, \w' \in \Omega^p(M) $ the following bilinear forms:
  \begin{equation*}
(\w, \w' )_{W_1} := \int_{\partial M} \langle \iota^* \w, \iota^* \w' \rangle \, d\mu_g + \int_{\partial M} \langle \iota^* \delta \w, \iota^* \delta \w' \rangle \, d\mu_g
\end{equation*} and
\begin{equation*}
    ( \w, \w' )_{V} := \int_M \langle \Delta \w, \Delta \w' \rangle \, d\mu_g.
\end{equation*}



\begin{lemma}\label{lem:ps}
    The forms $ ( \cdot, \cdot )_{W_1} $ and $( \cdot, \cdot)_{V} $ are scalar products on $ Z_1 $ and $ \check{H}^2_{N,1}(M) $, respectively.
\end{lemma}

\begin{proof}
  It is easy to verify that the forms defined above are bilinear, symmetric, and non-negative. Let us show that they are positive definite. For $ \w \in Z_1 $, if $ ( \w, \w )_{W_1} = 0 $, then 
$\int_{\partial M} \left( | \iota^* \w |^2 + | \iota^* \delta \w |^2 \right) d\mu_g = 0,$
which implies that $ \iota^* \w $ and $ \iota^* \delta \w $ are zero on $ \partial M $. Substituting into \eqref{eq:IPP2} with $ \w \in Z_1 $, we obtain $ \Delta \w = 0 $ on $ M $. Since $ \w_{|\partial M} = 0 $ we conclude that $ \w = 0 $ on $ M $ according to \cite{ColetteAnne}.

Similarly, for $ \w \in \check{H}^2_{N,1}(M) $, if $ ( \w, \w )_{V} = 0 $ then $ \Delta \w = 0 $ on $ M $. Thus, \eqref{eq:IPP3} gives that $ d\w $ and $ \delta \w $ are zero, and since $ \nu \lrcorner \w = 0 $ it follows that $ \w \in H_A^p(M) $. Moreover, since $ \w \in \check{Z}_1 $ this implies that $\int_{\partial M} \langle \iota^* \w, \iota^* \w \rangle d\mu_g = 0$ by the definition of elements of $ \check{Z}_1 $. Therefore, $\int_{\partial M} | \iota^* \w |^2 d\mu_g = 0,$
which means that $ \iota^* \w = 0 $. As a result, $ \w_{|\partial M} = 0 $, and because $\w$ is harmonic, we can conclude again that $ \w = 0 $ on $ M $ according to \cite{ColetteAnne}.
\end{proof}
We denote by $ W_1 $ the completion of $ Z_1 $ with respect to $ ( \cdot, \cdot )_{W_1} $, and by $ V_1 $ the completion of $ \check{Z}_1 $ with respect to $ (\cdot, \cdot)_{V} $.

From \eqref{eq:IPP1} and \eqref{eq:IPP2} by taking $ \w \in Z_1 $ and $ \w' = \w $, we get 
  \begin{equation}\label{eq:integrationPourWdansZ1}
      \int_M \lvert \Delta\w  \rvert^2d\mu_g+\int_{\partial M} \Big( \langle \nu \lrcorner d \Delta\w, \iota^* \w\rangle + \langle \nu \lrcorner \Delta\w, \iota^*\delta \w\rangle   \Big)d\mu_g =0.\end{equation}


\begin{lemma}  \label{lem:lpositive}
  The kernel of BSN1 coincides with $H_A^p(M)$. Moreover, if $\w$ is a solution of $BSN1$ with $\ell\neq 0,$ then $\w\perp_{L^2(\partial M)}H_A^p(M)$ and $\ell >0.$
  \end{lemma}
  \begin{proof}
Let $\w$ be a solution of BSN1 with $\ell=0$. By integrating by parts using equation \eqref{eq:IPP2}, where we take $\w=\w'$ we obtain: 
    \begin{equation*}
\begin{split}
    & \int_M\langle \underbrace{\Delta^2 \w}_{0} , \w\rangle  d\mu_g  =  \int_M\langle \Delta\w , \Delta \w\rangle  d\mu_g \\
    & + \int_{\partial M} \Big( \langle \underbrace{\nu \lrcorner d \Delta\w}_{0}, \iota^* \w\rangle-\langle \iota^* \Delta\w, \underbrace{\nu \lrcorner d \w}_{0}\rangle  + \langle \underbrace{\nu \lrcorner \Delta\w}_{0}, \iota^*\delta \w\rangle-\langle \iota^* \delta \Delta\w, \underbrace{\nu \lrcorner \w}_{0}\rangle    \Big)d\mu_g,
\end{split}
\end{equation*} 
    thus $\Delta\w=0$. Substituting this into \eqref{eq:IPP3}, we have 
    \begin{equation*}
\begin{aligned}
   \int_M \langle \underbrace{\Delta \w}_{0}, \w \rangle \, d\mu_g &= \int_M \left( \lvert d\w \rvert^2 + \lvert \delta\w \rvert^2 \right) d\mu_g+ \int_{\partial M} \langle \underbrace{\nu \lrcorner d\w}_{0}, \iota^* \w \rangle \, d\mu_g \\
   &\quad - \int_{\partial M} \langle \iota^* \delta \w ,\underbrace{\nu \lrcorner \w}_{0} \rangle \, d\mu_g.
\end{aligned}
\end{equation*} 
    This implies that $d\w=0$ and $\delta\w=0$, so $\w$ lies in $H_A^p(M)$.

    Conversely, for $\w\in H_A^p(M)$, it is a solution of BSN1 for $\ell=0$ by definition of $H_A^p(M)$ \eqref{eq:Hap}.
  Now if $\w$ is a solution of the $BSN1$, $\ell\neq 0$ and $\w\in Z_1$, we have by \eqref{eq:utiliserDansLemme3.3} for all $\alpha\in H_A^p(M)$ that \[0=\int_M\langle\Delta\w,\Delta\alpha\rangle d\mu_g=\ell\int_{\partial M} \langle\iota^*\w,\iota^*\alpha\rangle d\mu_g.\] Since $\ell\neq 0$ we get $\w\perp_{L^2(\partial M)}H_A^p(M)$, therefore $\w\in\check{Z}_1\subset V_1$. Moreover, still by \eqref{eq:utiliserDansLemme3.3} we get $\int_M\lvert\Delta\w\rvert^2 d\mu_g=\ell\int_{\partial M}(\lvert\iota^*\w\rvert^2+\lvert\iota^*\delta\w\rvert^2) d\mu_g.$ Therefore $\ell >0,$ which concludes the proof.
\end{proof}

\begin{lemma}\label{lem:equivalence}
    The norms $ \lVert \cdot \rVert_{V} $ and $ \lVert \cdot \rVert_{H^2(M)} $ are equivalent on $ \check{H}^2_{N,1}(M) $. In particular they are equivalent in $\check{Z}_1$ and $V_1\subset \check{H}^2_{N,1}(M).$
\end{lemma}

\begin{proof}
    As $ \Delta $ is a second-order differential operator, there exists $ c > 0 $ such that for all $ \w \in \check{Z}_1 $, $ \lVert \w \rVert_{V} \leq c \lVert \w \rVert_{H^2(M)} $. It remains to show that for all $ \w \in \check{Z}_1 $, $ \lVert \w \rVert_{H^2(M)} \leq c \lVert \w \rVert_{V} $. To do this, let us first show that the space $ H^2_{N,1}(M) $ is closed in $ H^2(M) $. Indeed, it is since $ H^2_{N,1}(M) $ is the kernel of the map \begin{align*}
        J\colon H^2(M) &\longrightarrow L^2(\partial M) \oplus L^2(\partial M) \\
        \w &\longmapsto (\nu \lrcorner d\w, \nu \lrcorner \w),
    \end{align*} which is continuous by the trace theorem.

 By definition, we have 
\[
H^2_{N,1}(M) = \check{H}_{N,1}^2(M) \oplus H_A^p(M).
\]
We define the space \[
\check{L}^2(M) := \left\{ \w \in L^2(M) \ | \ \forall \alpha \in H_A^p(M), \ \int_{M} \langle \alpha, \w \rangle \, d\mu_g = 0 \right\},
\] and we prove the following lemma.
 \begin{lemma}
     The following map 
$
\Delta_{|\check{H}_{N,1}^2(M)} : \check{H}_{N,1}^2(M) \longrightarrow \check{L}^2(M),
$ is an isomorphism.
 \end{lemma}
\begin{proof}
    This map is well-defined. Indeed, doing an integration by parts \eqref{eq:IPP3'} we get $ \Delta \w \in \check{L}^2(M) $ for all $ \w \in \check{H}_{N,1}^2(M) $. Now let $\w \in \check{H}_{N,1}^2(M)$ such that $\Delta\w = 0$, performing an integration by parts \eqref{eq:IPP3'} we obtain that $d\w$ and $\delta\w$ are zero. Additionally, since $\nu \lrcorner \w = 0$, we conclude that $\w \in H_A^p(M)$. Thus, $\iota^*\w = 0$ as $\w\in H_A^p(M)$ and $\w\perp_{L^2(\partial M)} H_A^p(M)$. Therefore, $\w=0$ by \cite{ColetteAnne}, so $\ker \Delta_{|{\check{H}_{N,1}^2(M)}} = \{0\}$. Hence, the operator $\Delta_{|\check{H}_{N,1}^2(M)} : \check{H}_{N,1}^2(M) \longrightarrow \check{L}^2(M)$ is injective. 

In fact, it is an isomorphism, as follows from  \thref{theo:thm5.4}, which states that for $\mathcal{N}=H_A^p(M):$
\begin{eqnarray*}
\mathcal{P}_{\Delta_{Neu}}:{H}_{N,1}^2(M)/H_A^p(M)&\longrightarrow & \check{L}^2(M)\oplus H^\frac{3}{2}(\partial M)\oplus H^\frac{1}{2}(\partial M)\\
  \left[\w\right]& \longmapsto & (\Delta\w,\nu\lrcorner\w,\nu\lrcorner d\w)  \notag 
\end{eqnarray*}
is a topological isomorphism onto its image, which is given by
\begin{align*}
\im(\mathcal{P}_{\Delta_{Neu}}) = \Big\{ (\hat{\w},\w_1,\w_2) \in L^{2}(M) \times H^{-\frac{1}{2}}(\partial M) 
&\times H^{-\frac{3}{2}}(\partial M) \ \Big| \ \forall \w' \in \mathcal{N}^*, \\
(\hat{\w},\w') &+ \sum_{j=1}^2 (\w_j, T_j\w') = 0 \Big\},
\end{align*}where $(\cdot,\cdot)$ is the duality product and $T_j$ is the operator defined in  \secref{sec:lionsMagenes}.

 Note that $\check{L}^2(M)\oplus \{0\}\oplus \{0\}\subset \im{\mathcal{P}}$. We have in this case \begin{equation}\label{eq:N*}
     \mathcal{N}^*=\{\w\in \Omega^p(M)\ |\ \Delta\w=0,\  C_1\w=0\ \text{and}\ C_2\w=0\}=H_A^p(M),
 \end{equation} since $C_1\w=\nu\lrcorner d\w$ and $C_2\w=\nu\lrcorner\w$ by  \secref{sec:lionsMagenes}. In fact, $(\hat{\w},\w_1,\w_2)$ belongs to $\im(\mathcal{P})$ if and only if for all $\alpha\in H_A^p(M)$ we have
$
(\hat{\w},\alpha)-(\w_1,\underbrace{\iota^*\delta\alpha}_{0})-(\w_2,\iota^*\alpha)=0,
$ i.e., $(\Delta\w,\alpha)=(\w_2,\alpha).$
Thus, $(\hat{\w},0,0)\in\im(\mathcal{P})$ if and only if for all $\alpha\in H_A^p(M)$, $(\hat{\w},\alpha)_{L^2(M)}=0$. Therefore, $\hat{\w}\in {H_A^p(M)}^{\perp_{(\cdot,\cdot)_{L^2(M)}}}$. We deduce that the set $\check{L}^2(M)\times \{0\}\times \{0\}$ is included in $\im(\mathcal{P})$. 
\end{proof}

Now let
\begin{eqnarray*}
\mathcal{L}:=({\mathcal{P}_{\Delta_{Neu}}})_{|\check{L}^2(M)\oplus \{0\}\oplus \{0\}}^{-1}:\check{L}^2(M)\oplus \{0\}\oplus \{0\}&\longrightarrow &{H}_{N,1}^2(M)/H_A^p(M)\\
(\hat{\w},0,0) & \longmapsto &  \left[\w\right]  \notag 
\end{eqnarray*}
be the continuous map such that $\Delta\w=\hat{\w}$ on $M$, $\nu\lrcorner\w=0$ and $\nu\lrcorner d\w=0$ on $\partial M$. By continuity of $ \mathcal{L}$, for all $\hat{\w}\in \check{L}^2(M)$, there exists $c>0$ such that
\[
\lVert \mathcal{L}(\hat{\w}) \rVert _{{H}^2(M)}\leq c \lVert \hat{\w} \rVert _{L^2(M)},
\]
therefore, for all $\w\in \check{H}_{N,1}^2(M)$, there exists $c'>0$ such that
\[
\lVert \w \rVert _{H^2(M)}\leq c' \lVert \Delta\w \rVert _{L^2(M)}.
\]
Since $Z_1\subset H_{N,1}^2(M)$, we have $\check{Z}_1 \subset \check{H}_{N,1}^2(M)$, so there exists $c'>0$ such that for all $\w\in \check{Z}_1$,
\[
\lVert \w \rVert _{H^2(M)}\leq c'\lVert \Delta\w \rVert _{L^2(M)}=c' \lVert \w \rVert_{V}.
\]
Thus, the norms $\lVert\cdot\rVert_{V}$ and $\lVert\cdot\rVert_{H^2(M)}$ are equivalent on $\check{H}_{N,1}^2(M)$ and therefore on $\check{Z}_1$ and $V_1$ by density, which completes the proof.

\end{proof}

\begin{lemma}\label{lem:W<V}
    There exists $c>0$ such that $\lVert\cdot\rVert_{W_1} \leq c\lVert\cdot\rVert_{V}$ on $\check{Z}_1.$ 
\end{lemma}

\begin{proof}
   Recall that $\lVert\w\rVert^2_{H^1(\partial M)}=\lVert\w\rVert^2_{L^2(\partial M)}+\lVert\nabla\w\rVert^2_{L^2(\partial M)}$. For all $\w\in\check{Z}_1$, we have by definition $\lVert\w\rVert^2_{W_1}=\lVert\iota^*\w\rVert^2_{L^2(\partial M)}+\lVert\iota^*\delta\w\rVert^2_{L^2(\partial M)}.$ 

   Moreover, \[\lVert\iota^*\w\rVert^2_{L^2(\partial M)}=\lVert\w\rVert^2_{L^2(\partial M)}\leq \lVert\w\rVert^2_{H^1(\partial M)}\] and \[\lVert\iota^*\delta\w\rVert^2_{L^2(\partial M)}\leq c\lVert\nabla\w\rVert^2_{L^2(\partial M)}\leq c\lVert\w\rVert^2_{H^1(\partial M)}.\] 

Furthermore, by continuity of the trace operator $T:H^2(M)\longrightarrow H^1(\partial M)$, there exists $c>0$ such that $\lVert \w \rVert^2_{W_1}\leq c \lVert \w \rVert^2_{H^1(\partial M)}\leq c \lVert \w \rVert^2_{H^2(M)}.$

 Finally, using the equivalence of the norms $\lVert \cdot \rVert_{V}$ and $\lVert \cdot \rVert_{H^2(M)}$, we obtain $\lVert \w \rVert^2_{W_1}\leq c \lVert \w \rVert_{V}^2$ for some constant $c.$
\end{proof}
From  \lemref{lem:W<V}, and since by definition $\check{Z}_1$ is dense in both $V_1$ and $W_1$, the inclusion map $i_{W_1}:\check{Z}_1\longrightarrow W_1$, which is linear and continuous, extends to another continuous "inclusion" map $I_1$ denoted as  
\begin{eqnarray}\label{eq:applicationI}
  I_1:V_1&\longrightarrow &W_1\\
  \w& \longmapsto &\w  \notag 
\end{eqnarray} 
such that $i_{W_1}=I_1\circ i_{V_1}$, where $i_{V_1}: \check{Z}_1\longrightarrow V_1.$

\begin{lemma}\label{lem:Icompact}
    The map $I_1$ is compact.
\end{lemma}

\begin{proof}
Let $J_1$ be the following map:
\begin{eqnarray*}
J_1: Z_1 & \longrightarrow & L^2(\partial M) \oplus L^2(\partial M) \nonumber \\
\w & \longmapsto & \left( \iota^* \w , \iota^* \delta \w \right)
\end{eqnarray*}

Its extension to $W_1$ exists and is an isometry by definition of $\lVert\cdot\rVert_{W_1}$. We prove the compactness of $I_1$ via the compactness of the map $J_1\circ I_1$:
\[
\begin{array}{cccccccc}
J_1\circ I_1:V_1 & \overset{I_1}{\longrightarrow} & W_1 & \overset{J_1}{\longrightarrow} &  L^2(\partial M)\oplus L^2(\partial M) \\
\w & \longmapsto &  \w & \longmapsto & (\iota^*\w,\iota^*\delta\w)
\end{array}
\]
First, note that $V_1$ is included in $H^2(M)$ by the equivalence of norms. According to  \lemref{lem:equivalence}, and since $H^2(M)\subset H^1(M)$, the map $C:V_1{\longrightarrow} H^1(M)\oplus  H^1(M),\ \w\mapsto (\w,\delta\w)$ is continuous. Moreover, we have that $H^1(M)\subset H^\frac{1}{2}(\partial M)$ due to the trace theorem, and the inclusion map $H^\frac{1}{2}(\partial M)\subset L^2(\partial M)$ is compact by the Rellich-Kondrachov theorem. Hence, $J_1\circ I_1$ can be represented as follows:

{\small
\[
\begin{array}{ccccccc}
V_1 & {\longrightarrow} & H^1(M)\oplus H^1(M) & {\longrightarrow} &  H^\frac{1}{2}(\partial M)\oplus H^\frac{1}{2} (\partial M) & {\longrightarrow} &  L^2(\partial M)\oplus L^2(\partial M) \\
\w & \longmapsto & (\w,\delta\w) & \longmapsto & (\iota^*\w,\iota^*\delta\w)& \longmapsto & (\iota^*\w,\iota^*\delta\w)
\end{array}
\]
}

Thus, $J_1\circ I_1$ is compact as it is composed of continuous maps, one of which is compact. To deduce that $I_1$ is compact, we require the following general lemma.

\begin{lemma}\label{lem:I3=I2oI1compacte}
    Let $E, E'$ and $E''$ be three Banach spaces. Let $F:E\longrightarrow E''$ be a compact map, $G:E'\longrightarrow E''$ an isometry and $H:E\longrightarrow E'$ a map such that $F=G\circ H$. Then $H$ is compact.
\end{lemma}

\begin{proof}
     Let $(v_n)_n$ be a bounded sequence in $E$. By the compactness of $F$, there exists a subsequence $(v_{k_n})_n$ such that $F(v_{k_n}) = G(H(v_{k_n}))$ converges in $E''$. Since $G: E' \rightarrow E''$ is an isometry then $G(E')$ is a complete set in $E''$, consequently, $G(E')$ is closed in $E''$. Thus, the sequence $G(H(v_{k_n}))$ converges to $G(x)$ for some $x \in E'$. Due to the isometry property of $G$, we have $H(v_{k_n}) \rightarrow x$ in $E'$. Therefore, we can deduce that the map $H$ is compact.
\end{proof}
Consequently, $I_1$ is compact according to  \lemref{lem:I3=I2oI1compacte}.
\end{proof}
We provide the definition of a weak solution adapted to our situation.
\begin{definition}\label{def:SolFaibleBSN1}
  For $f\in L^2(M)$, a weak solution $\w$ of $\Delta^2\w=f$ on $M$ is a form $\w\in H_{N,1}^2(M)$ such that 
  \begin{equation}\label{eq:solfaible}
    (\Delta\w,\Delta\w')_{L^2(M)}=(f,\w')_{L^2(M)}, \ \forall \w'\in H_0^2(M).
\end{equation}
\end{definition}
A general definition of the weak solution in an open subset of $\mathbb{R}^n$ is given in \cite[Sections 6.1.1 and 6.1.2]{Evans}.
\begin{lemma}\label{lem:solfaible} 
We have the following equality 
\[ V_1=\{\w\in \check{H}^2_{N,1}(M)\ |\ \Delta^2 \w=0\ \text{weakly in}\ M\}.\]
\end{lemma}

\begin{proof}
We know by  \lemref{lem:equivalence} that $\check{Z}_1\subset\check{H}_{N,1}^2(M)\subset H_{N,1}^2(M).$ Let us fix $\w\in V_1$. There exists a sequence $(\w_m)_m$ in $\check{Z}_1$ such that $\lVert \w_m-\w\rVert_{V}\underset{{m \to \infty}} {{\longrightarrow}}0$. By the equivalence of the norms $\lVert \cdot \rVert_{V}$ and $\lVert \cdot \rVert_{H^2(M)}$, on $V_1$ the sequence $(\w_m)_m$ converges in $H^2(M)$ to $\w$. Hence, $(\Delta \w_m)_m$ converges in $L^2(M)$ to $\Delta \w$. For $\w'\in H_0^2(M)$, $\w_m\in \check{Z}_1$ and replacing $\w$ by $\w_m$ in \eqref{eq:IPP2}, we obtain $(\Delta \w_m, \Delta \w')_{L^2(M)}=0$. Since $(\Delta \w_m)_m$ converges in $L^2(M)$ to $\Delta \w$, it follows that 
$(\Delta \w, \Delta \w')_{L^2(M)}=0$ for all $\w'\in H_0^2(M)$. Thus, $\w\in H_{N,1}^2(M)$ and $\Delta^2\w=0$ weakly in $M$, proving the first inclusion.

Conversely, let $\w\in \check{H}^2_{N,1}(M)$ such that $\Delta^2\w=0$ weakly in $M$. Since the norms $\lVert \cdot \rVert_{V}$ and $\lVert \cdot \rVert_{H^2(M)}$ are equivalent on $\check{H}^2_{N,1}(M)$, we get that $\Delta^2\w=0$ sur $M.$ Hence the equality.
\end{proof}

\begin{lemma}\label{lem:i3injective}
    The map $I_1$ is injective.
\end{lemma}

\begin{proof}
   The injectivity of $J_1\circ I_1$ implies the injectivity of $I_1$. Let $\w\in V_1$ be such that $J_1\circ I_1(\w)=0$ i.e., $\iota^*\w=0$ and $\iota^*\delta\w=0$ on $\partial M$. Since, $\w_{|\partial M}=0$ and $\nu\lrcorner d\w=0$ ($\w\in Z_1$), its differential $d\w=\nu^\flat\wedge(\nu\lrcorner d\w)+\iota^*d\w$ is zero on the boundary. Furthermore, $\delta\w=0$ is zero on the boundary as $\iota^*\delta\w=0$ and $\nu\lrcorner\delta\w=-\delta(\nu\lrcorner\w)=0$. Consequently, $d\w=\nu^\flat\wedge\nabla_\nu\w=0$ and $\delta\w=-\nu\lrcorner\nabla_\nu\w=0$ along the boundary. From the above, we have $\nu \lrcorner\underbrace{(\nu^\flat\wedge\nabla_\nu\w)}_{0}=\underbrace{\nu^\flat(\nu)}_{1}\nabla_\nu\w-\nu^\flat\wedge\underbrace{(\nu\lrcorner\nabla_\nu\w)}_{0}=0$, so $\nabla_\nu\w=0$, implying ${\nabla\w}_{|\partial M}=0$. Therefore, $\w\in H_0^2(M)$, and we can replace $\w$ by $\w'$ in \eqref{eq:solfaible} to obtain $\Delta\w=0$. Given that $\w_{|\partial M}=0$, we have $\w=0$ by \cite{ColetteAnne}. We conclude that $J_1\circ I_1$ is injective and consequently $I_1$ is also.
\end{proof}

To complete the proof of  \thref{thm:TheoremeGeneralBSNF1PourLaPreuve}, we introduce the operator $K_1:V_1\longrightarrow V_1$ defined as follows:
\begin{equation}\label{eq:operateurK}
K_1:=D_{V_1}^{-1}\circ ~^tI_1\circ D_{W_1}\circ I_1
\end{equation}
where $D_{V_1}:V_1\longrightarrow V'_1$ and $D_{W_1}:W_1\longrightarrow W'_1$ are natural dual isomorphisms defined as follows: $D_{V_1}(\w):=(.,\w)_{V}$ and $D_{W_1}(\w):=(.,\w)_{W_1}$ for all $\w$ in $V_1$ and $W_1$ respectively, and $~^tI_1(\theta)=\theta\circ I_1$ for all $\theta$ in $W'_1.$ Note that, $K_1$ is characterized for all $\w$ and $\w'$ in $V_1$ by:
\begin{equation}\label{eq:CharacterizationK1}
    (K_1\w,\w')_{V}=(~^tI_1\circ D_{W_1}\circ I_1(\w))(\w')=(D_{W_1}\circ I_1(\w))(I_1(\w'))=(I_1(\w),I_1(\w'))_{W_1}=(\w,\w')_{W_1},
\end{equation} since $V_1\subset W_1.$
We observe that the operator $K_1$ is self-adjoint and non-negative. Moreover, since $I_1$ is injective, $\ker I_1=\{0\}$, thus $\ker K_1=\{0\}$, so $K_1$ is positive definite. The compactness of $K_1$ follows from the fact that it is the composition of continuous mappings with $I_1$, which is compact. Finally, since $K_1$ is compact, self-adjoint, and positive definite on $V_1$, which is a Hilbert space, there exists a sequence of real, positive, and non-increasing eigenvalues $(\chi_{i,1})_{i\geq 1}$ that tend to zero, with finite-dimensional eigenspaces, as per \cite[p.431]{LaurentSchwartz}. The eigenspaces form a dense space in $V_1$, and the $(\w_i)_i$ form a Hilbert basis. To conclude the proof of  \thref{thm:TheoremeGeneralBSNF1PourLaPreuve} let us show the following lemma.
\begin{lemma}\label{lem:k1w=xw}
    A form $\w$ solves \eqref{eq:BSNF1} for $\ell\in \mathbb{R}^*$ if and only if, \begin{equation}\label{eq:K1w=Xw}
     K_1\w=\frac{1}{\ell}\w.\end{equation}
\end{lemma}
\begin{proof}
Let us fix $\ell\in \mathbb{R}^*$ and a smooth solution $\w$  of the BSN1 \eqref{eq:BSNF1}. Using \eqref{eq:IPP2} $\w'\in\check{Z}_1$, we get 
\[(\Delta\w,\Delta\w')_{L^2(M)}=\ell\big((\iota^*\w,\iota^*\w')_{L^2(\partial M)}+(\iota^*\delta\w,\iota^*\delta\w')_{L^2(\partial M)}\big).\]
By density of $\check{Z}_1$ in $W_1$, we get for all $\w'$ in $V_1$, $(\w,\w')_{V}=\ell(\w,\w')_{W_1}$. Note that $\ell>0$ by  \lemref{lem:lpositive}. Thus, by the definition of $K_1$, $(\w,\w')_{V}=\ell(K_1\w,\w')_{V}$ for all $\w'\in V_1$, so $K_1\w=\frac{1}{\ell}\w$. Therefore, $\w$ is an eigenform of $K_1$ associated with the eigenvalue $\chi=\frac{1}{\ell}.$ 

Conversely, let $\w_i\in V_1$ be a $\chi_{i,1}$-eigenform for $K_1$. Since $\w_i\in V_1$, we have by  \lemref{lem:solfaible} that $\Delta^2 \w_i=0$ weakly on $M$ with $\nu\lrcorner \w_i=0$ and $\nu \lrcorner d\w_i=0$. Let us show that $\nu\lrcorner\Delta d\w_i=-\ell\iota^*\w_i$ and $\nu\lrcorner\Delta \w_i=-\ell\iota^*\delta\w_i$ on $\partial M$ with $\ell=\frac{1}{\chi_{i,1}}$. For any $\w\in \check{Z}_1$, we have by definition:
\begin{align}\label{eq:relationChi}
\chi_{i,1}(\Delta\w_i,\Delta \w)_{L^2(M)}\notag &= \chi_{i,1}(\w_i,\w)_{V} \\ \notag
&= (K\w_i,\w)_{V} \\ \notag
&= (I_1(\w_i),I_1(\w))_{W_1} \\ \notag
&= (\w_i,\w)_{W_1} \\
&= (\iota^*\w_i,\iota^* \w)_{L^2(\partial M)} + (\iota^*\delta\w_i,\iota^*\delta\w)_{L^2(\partial M)}. 
\end{align}

\begin{lemma}\label{lem:dansLaPreuveDeL'operateur}
    For all $\w\in V_1,\ \w' \in H^2_{N,1}(M)$, we have
    \[
    \int_M\langle \Delta\w , \Delta \w'\rangle  d\mu_g  + \int_{\partial M}  \langle \nu \lrcorner d \Delta\w, \iota^* \w'\rangle d\mu_g + \int_{\partial M}  \langle \nu \lrcorner \Delta\w, \iota^*\delta \w'\rangle  d\mu_g=0.
    \]
\end{lemma}
\begin{proof}
    Let $\w'\in H^2_{N,1}(M)$ and $(\w_m)_m\in H^2_{N,1}(M)$ be a sequence that converges to $\w$ in $V_1$. Using \eqref{eq:IPP2}, we obtain:
    \begin{equation}\label{eq:justepourlapreuve}  
    \int_M\langle \Delta\w_m, \Delta \w'\rangle  d\mu_g  + \int_{\partial M}  \langle \nu \lrcorner d \Delta\w_m, \iota^* \w'\rangle d\mu_g + \int_{\partial M}  \langle \nu \lrcorner \Delta\w_m, \iota^*\delta \w'\rangle  d\mu_g=0.
    \end{equation}
    Now, $V_1\subset H^2(M)$, and by the equivalence of the norms $\lVert \cdot \rVert_{V}$ and $\lVert \cdot \rVert_{H^2(M)}$, the sequence $(\w_m)_m$ converges in $H^2(M)$ to $\w$. Hence, $(\Delta \w_m)_m$ converges in $L^2(M)$ to $\Delta \w$, $(\nu\lrcorner d \Delta \w_m)_m$ converges in $H^{-\frac{3}{2}}(\partial M)$ to $\nu\lrcorner d \Delta\w$, and $(\nu\lrcorner  \Delta \w_m)_m$ converges in $H^{-\frac{1}{2}}(\partial M)$ to $\nu\lrcorner  \Delta\w$. Furthermore, the bilinear forms in \eqref{eq:justepourlapreuve} are well-defined and continuous because 
    \[
    \langle \underbrace{\nu \lrcorner d \Delta\w_m}_{\in H^{-\frac{3}{2}}(\partial M)}, \underbrace{\iota^* \w'}_{\in H^{\frac{3}{2}}(\partial M)}\rangle
    \quad \text{and} \quad 
    \langle \underbrace{\nu \lrcorner \Delta\w_m}_{\in H^{-\frac{1}{2}}(\partial M)}, \underbrace{\iota^*\delta \w'}_{\in H^{\frac{1}{2}}(\partial M)}\rangle,
    \]
    see \cite[Definition 1.7.3]{ChristianBaer}. Thus, the result follows.
\end{proof}

Thus, for all $\w\in{Z}_1$, we have 
\[
(\Delta\w_i,\Delta \w)_{L^2(M)}+(\nu\lrcorner d\Delta\w_i,\iota^*\w)_{L^2(\partial M)}+(\nu\lrcorner\Delta\w_i,\iota^*d\w)_{L^2(\partial M)}=0.
\]
Using \eqref{eq:relationChi}, we obtain:
\begin{equation} 
    \left(\frac{1}{\chi_i}\iota^*\w_i + \nu \lrcorner d \Delta\w_i, \iota^* \w\right)_{L^2(\partial M)} + \left(\frac{1}{\chi_i}\iota^*\delta\w_i + \nu \lrcorner \Delta\w_i, \iota^*\delta \w\right)_{L^2(\partial M)} = 0.
\end{equation}

Consider the following map:
\begin{align*}
O_1:{Z}_1 &\longrightarrow \Omega^p(\partial M)\oplus \Omega^{p-1}(\partial M)\\
\w&\longmapsto (\iota^*\w,\iota^*\delta\w).
\end{align*}
It is continuous with respect to the norms $\lVert\cdot\rVert_{V}$ and $\lVert\cdot\rVert_{L^2(\partial M)}$ and is injective since it is the restriction of $J_1\circ I_1$ on ${Z}_1$, which is continuous and injective by  \lemref{lem:i3injective}.

\begin{lemma}\label{lem:Osurjective}
    The map $O_1$ is surjective.
\end{lemma}

\begin{proof}
    This follows from \lemref{lem:Bilap1}.
\end{proof}

We know by \eqref{eq:justepourlapreuve} that for all $\w\in Z_1$, \[(\nu\lrcorner\Delta\w_i + \ell\iota^*\delta\w_i,\iota^*\delta\w)_{L^2(\partial M)}+(\nu\lrcorner d\Delta\w_i + \ell\iota^*\w_i,\iota^*\w)_{L^2(\partial M)}=0.\] Now using  \lemref{lem:Osurjective}, we have that $O_1$ is surjective. Consequently, for all $\alpha,\beta\in \Omega^p(\partial M),$ we get \[(\nu\lrcorner\Delta\w_i + \ell\iota^*\delta\w_i,\alpha)_{L^2(\partial M)}+(\nu\lrcorner d\Delta\w_i + \ell\iota^*\w_i,\beta)_{L^2(\partial M)}=0.\] 

By duality it follows that \begin{equation*}
\begin{aligned}
(\nu\lrcorner\Delta\w_i + \ell\iota^*\delta\w_i,\nu\lrcorner d\Delta\w_i + \ell\iota^*\w_i )= (0,0)
\end{aligned}
\end{equation*} holds in $H^{-\frac{1}{2}}(\partial M)\times H^{-\frac{3}{2}}(\partial M)$. Now by \thref{theo:thm5.4}, $\w_i$ is hence smooth and is an eigenform of the problem \eqref{eq:BSNF1} associated with the eigenvalue $\ell_i = \frac{1}{\chi_i}$.\end{proof}
 This completes the proof of \thref{thm:TheoremeGeneralBSNF1PourLaPreuve}. \end{proof}

\subsection{Variational characterization of eigenvalues}
In this section, we will provide variational characterizations of the eigenvalues of the BSN1 problem.

\begin{thm}\label{theo:BSN1VP1}
A variational characterization of the first strictly positive eigenvalue of BSN1 is given by 
\begin{equation}\label{eq:BSN1VP1}
\ell_{1,p} = \min\left\{\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)} + \lVert \iota^*\delta \w\rVert^2_{L^2(\partial M)}} \ | \ \w \in \check{H}_{N,1}^2(M), \ \iota^*\w \neq 0 \ \text{or} \ \iota^*\delta\w \neq 0 \ \text{on} \ \partial M\right\}.
\end{equation} This infimum is attained if and only if $\w$ is an $\ell_{1,p}$-eigenform for BSN1.
\end{thm}

\begin{proof}
    By applying \eqref{eq:integrationPourWdansZ1} to $\w_{1,p}$, a $\ell_{1,p}$-eigenform, we obtain
    \[
    \int_M \lvert \Delta \w_{1,p} \rvert^2 d\mu_g = \ell_{1,p} \int_{\partial M} \Big( \langle \iota^* \w_{1,p}, \iota^* \w_{1,p} \rangle + \langle \iota^* \delta \w_{1,p}, \iota^* \delta \w_{1,p} \rangle \Big) d\mu_g.
    \]
    Therefore,
    \[
    \ell_{1,p} = \frac{\lVert \Delta \w_{1,p} \rVert^2_{L^2(M)}}{\lVert \iota^* \w_{1,p} \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w_{1,p} \rVert^2_{L^2(\partial M)}}.
    \]
   Let $\w\in V_1$. By the proof of  \thref{thm:TheoremeGeneralBSNF1PourLaPreuve}, $ \w = \sum_i (\w, \w_i)_{V} \w_i $, where $ (\w_i)_i $ is a Hilbertian orthonormal basis of $ V_1 $ consisted of eigenforms for the operator $K_1$, whose eigenvalues $(\chi_i)_{i\geq 1}$ satisfy $\chi_i=\frac{1}{\ell_{i,p}}$. We have hence
    \[
    \lVert \Delta \w \rVert^2_{L^2(M)} = \lVert \w \rVert^2_{V} = \sum_i (\w, \w_i)_{V}^2.
    \]
    Using \eqref{eq:K1w=Xw}, we compute:
    \begin{alignat*}{2}
    &\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)} &&= \lVert \w \rVert^2_{W_1}\\
    &&&= (K_1 \w, \w)_{V} \\
    &&&= \bigg( K_1 \sum_i (\w_i, \w)_{V} \w_i, \sum_j (\w_j, \w)_{V} \w_j \bigg)_{V} \\
    &&&= \sum_i \chi_i (\w_i, \w)_{V}^2 \\
    &&&\leq \chi_1\sum_i (\w_i,\w)^2_V\\
    &&&=\frac{1}{\ell_{1,p}} \lVert \w\rVert^2_V\\
    &&&= \frac{1}{\ell_{1,p}} \lVert \Delta \w \rVert^2_{L^2(M)}.
    \end{alignat*}

    Thus,
    \[
\ell_{1,p} \leq  \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)}},
    \]
and the inequality is strict unless $\w$ is a  $\chi_1$-eigenform of $K_1$, i.e., $\w$ is an $\ell_{1,p}$-eigenform of BSN1 \eqref{eq:BSNF1}.
 We have shown that,
    \[
    \ell_{1,p} = \inf \left\{\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)}} \ \big| \ \w \in V_1 \setminus \{0\} \right\}.
    \]

    Let us now show that the same characterization holds for all $ \w \in \check{H}_{N,1}^2(M) $ that are non-zero on the boundary. For this, we require the following lemma:


\begin{lemma}\label{lem:Hn=V+H0}
    On $\check{H}_{N,1}^2(M)$, we have the following orthogonal decomposition with respect to $(\cdot,\cdot)_{V}$:
    \[
    \check{H}_{N,1}^2(M) = V_1 \oplus H_0^2(M).
    \]
\end{lemma}

\begin{proof}
   Let $\w' \in \check{H}_{N,1}^2(M)$ and $\w \in \check{Z}_1$. From \eqref{eq:IPP2}, we have:
    \begin{equation*}
    \begin{split}
         \int_M \langle \Delta \w , \Delta \w' \rangle d\mu_g = -\int_{\partial M} \Big( \langle \nu \lrcorner d \Delta \w, \iota^* \w' \rangle + \langle \nu \lrcorner \Delta \w, \iota^*\delta \w' \rangle \Big) d\mu_g.
    \end{split}
    \end{equation*}
    Hence, for $\w' \in H_0^2(M)$, we have $(\w,\w')_{V}=0$, which implies $H_0^2(M) \subset \check{Z}_1^\perp.$ By density of $\check{Z}_1$ in $V_1$, we have $\check{Z}_1^{\perp}=V_1^\perp.$

Conversely, let $\w' \in V_1^\perp \subset \check{H}_{N,1}^2(M)$, then $(\w_i, \w')_{V} = 0$ for all $i$. Then, by equation \eqref{eq:integrationPourWdansZ1}, we have:
\[
(\nu \lrcorner d \Delta\w_i, \iota^* \w')_{L^2(\partial M)} + (\nu \lrcorner \Delta\w_i, \iota^*\delta \w')_{L^2(\partial M)} = 0
\]
for all $i$. Hence,
\begin{equation}\label{eq:iw+ideltaw=0}(\iota^* \w_i, \iota^* \w')_{L^2(\partial M)} + (\iota^*\delta \w_i, \iota^*\delta \w')_{L^2(\partial M)} = 0.
\end{equation}

The goal now is to show that $\w'\in H_0^2(M)$. Since $\w'\in \check{H}_{N,1}^2(M),$ we will see that it is enough to show that $\iota^*\w' = 0$ and $\iota^*\delta\w' = 0.$ \\ Recall that the map $O_1$ is surjective according to  \lemref{lem:Osurjective}, bounded with respect to $\lVert \cdot \rVert_{V}$ and $\lVert \cdot \rVert_{L^2(\partial M)}$, and that the $\w_i$'s generate a dense space in $V_1$. Consequently, for any $\epsilon > 0$, there exists $\w_1 \in \Omega^p(\partial M)$ and $\w_2 \in \Omega^{p-1}(\partial M)$ such that $\lVert \iota^* \w' - \w_1 \rVert_{L^2(\partial M)} < \epsilon$ and $\lVert \iota^* \delta \w' - \w_2 \rVert_{L^2(\partial M)} < \epsilon$. Thus, there exists a unique $\w_\epsilon \in \Omega^p(M)$ such that $\Delta^2 \w_\epsilon = 0$, $\nu \lrcorner \w_\epsilon = 0$, $\nu \lrcorner d \w_\epsilon = 0$, $\iota^* \w_\epsilon = \w_1$, and $\iota^* \delta \w_\epsilon = \w_2$. Therefore, for every $\epsilon > 0$, there exists $\w_\epsilon \in \Omega^p(M)$ such that $\Delta^2 \w_\epsilon = 0$, $\nu \lrcorner \w_\epsilon = 0$, $\nu \lrcorner d \w_\epsilon = 0$, $\lVert \iota^* \w_\epsilon - \iota^* \w' \rVert_{L^2(\partial M)} < \epsilon$, and $\lVert \iota^* \delta \w_\epsilon - \iota^* \delta \w' \rVert_{L^2(\partial M)} < \epsilon$. We can then decompose $\w_\epsilon \in Z_1$ as follows: $\w_\epsilon = \check{\w}_\epsilon + \alpha_\epsilon$, where $\check{\w}_\epsilon \in \check{Z}_1$ and $\alpha_\epsilon \in H_A^p(M)$, the decomposition is w.r.t $(\cdot,\cdot)_{W_1}$. Since we have \eqref{eq:iw+ideltaw=0} and the map $O_1$ is continuous, we obtain the following:
\begin{align*}
\sum_i (\check{\w}_\epsilon, \w_i)_{V} \Big[ & (\iota^* \w_i, \iota^* \w')_{L^2(\partial M)} + (\iota^* \delta \w_i, \iota^* \delta \w')_{L^2(\partial M)} \Big] \\
&= \left( \sum_i (\check{\w}_\epsilon, \w_i)_{V} \iota^* \w_i, \iota^* \w' \right)_{L^2(\partial M)} + \left( \sum_i (\check{\w}_\epsilon, \w_i)_{V} \iota^* \delta \w_i, \iota^* \delta \w' \right)_{L^2(\partial M)} = 0.
\end{align*} Again by the continuity of the map $O_1$, we have $(\iota^* \check{\w}_\epsilon, \iota^* \w')_{L^2(\partial M)} + (\iota^* \delta \check{\w}_\epsilon, \iota^* \delta \w')_{L^2(\partial M)} = 0$. Given that for $\alpha_\epsilon \in H_A^p(M)$ and $\w' \in \check{H}_{N,1}^2(M)$, we have:
\[
(\iota^* \alpha_\epsilon, \iota^* \w')_{L^2(\partial M)} + (\iota^* \delta \alpha_\epsilon, \iota^* \delta \w')_{L^2(\partial M)} = 0,
\]
therefore:
\[
(\iota^* \w_\epsilon, \iota^* \w')_{L^2(\partial M)} + (\iota^* \delta \w_\epsilon, \iota^* \delta \w')_{L^2(\partial M)} = 0.
\]
By taking $\epsilon$ to $0$, we obtain $\lVert \iota^*\w'\rVert^2_{L^2(\partial M)} + \lVert \iota^*\delta\w'\rVert^2_{L^2(\partial M)} = 0,$ which implies that $\iota^*\w' = 0$ and $\iota^*\delta\w' = 0$. We then have: $\w'_{|\partial M} = 0$, $d\w'_{|\partial M} = \nu^\flat \wedge \nabla_\nu \w' = 0$ and $\delta\w'_{|\partial M} = -\nu \lrcorner \nabla_\nu \w' = 0.$ Thus, by the proof of  \lemref{lem:i3injective}, we have $\nabla_\nu \w' = 0$ and $\nabla_X \w' = 0$ for all $X \in T\partial M$. Therefore, $\nabla_X \w' = 0$ for all $X \in TM_{|\partial M}$, so $(\nabla \w)_{|\partial M} = 0$, and hence $\w' \in H_0^2(M) = V^\perp.$\end{proof}
We can then perform the following decomposition for $\w \in \Omega^p(M)$ such that $\nu \lrcorner d\w = 0$ and $\nu \lrcorner \w = 0$, $\w = \w_{V_1} + \hat{\w}$, with $\w_{V_1} \in V_1$ and $\hat{\w} \in H_0^2(M)$. We write\begin{equation}\label{eq:w=wv+^w}
    \lVert \Delta \w\rVert^2_{L^2(M)}=\lVert \w\rVert^2_{V}=\lVert \w_{V_1}\rVert^2_{V}+\lVert \hat{\w}\rVert^2_{V}\end{equation} and \begin{equation}\label{eq:iw=iwv}
\lVert \iota^*\delta\w\rVert^2_{L^2(\partial M)}+\lVert \iota^*\w\rVert^2_{L^2(\partial M)}=\lVert \iota^*\delta\w_{V_1}\rVert^2_{L^2(\partial M)}+\lVert \iota^*\w_{V_1}\rVert^2_{L^2(\partial M)}\end{equation}
since $\iota^* \delta \hat{\w} =0$ and $\iota^* \hat{\w} = 0$. Thus, using \eqref{eq:w=wv+^w} and \eqref{eq:iw=iwv}, we get
\begin{align}\label{eq:egalite}
\lVert \Delta \w\rVert^2_{L^2(M)} &= \lVert \Delta \w_{V_1}\rVert^2_{L^2(M)}+\lVert \Delta \hat{\w}\rVert^2_{L^2(M)} \\ \nonumber
&\geq \lVert \Delta \w_{V_1}\rVert^2_{L^2(M)} \\ \nonumber
&\geq \ell_{1,p}\big(\lVert \iota^*\delta\w_{V_1}\rVert^2_{L^2(\partial M)}+\lVert \iota^*\w_{V_1}\rVert^2_{L^2(\partial M)}\big) \\ \nonumber
&= \ell_{1,p}\big(\lVert \iota^*\delta\w\rVert^2_{L^2(\partial M)}+\lVert \iota^*\w\rVert^2_{L^2(\partial M)}\big).
\end{align}
We conclude finally that
\[
\ell_{1,p} = \inf \left\{ \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)}} \ |\ \w \in \check{H}_{N,1}^2(M), \ \iota^* \w \neq 0 \ \text{or} \ \iota^* \delta \w \neq 0 \ \text{on} \ \partial M \right\}  
\]and the infimum is only reached for $\ell_{1,p}$-eigenforms of BSN1.

\end{proof}

We provide below an alternative variational characterization of the first eigenvalue of the BSN1.

\begin{thm}\label{theo:l1p}
  Let us define 
    \begin{equation}  \label{eq:ell1}
    \ell'_{1,p} := \inf \left\{ \frac{ \lVert \nu \lrcorner \w \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\w \rVert^2_{L^2(\partial M)} }{ \lVert \w \rVert^2_{L^2(M)} } \ |\  \w\in H^2(M),\ \w \perp_{L^2(M)} H_A^p(M) \ \text{and}\ \Delta \w = 0 \ \text{on}\ M\right\}.
     \end{equation} Then we have $\ell_{1,p}= \ell'_{1,p}.$
\end{thm}
\begin{prop}\label{prop:l'minimum}
    The infimum $\ell'_{1,p}$ defined in  \thref{theo:l1p}, is a positive minimum.
\end{prop}

\begin{proof}
We prove first the following lemma. 
\begin{lemma}\label{lm:SteklovFormeGénéraleCorrigée}
    The boundary problem \begin{equation}\label{eq:SteklovFormeGénéraleCorrigée}
(\Delta_{Neu}) \begin{cases}
    \Delta \w = \w_0 & \text{on } M \\
    \nu \lrcorner \w = \w_1 & \text{on } \partial M \\
    \nu \lrcorner d\w = \w_2 & \text{on } \partial M.
\end{cases} 
\end{equation}
 has a unique solution $\w$ if and only if $\w_0,\ \w_1$ and $\w_2$ lie in $\im(\mathcal{P}_{\Delta_{Neu}})$. In this case the set of solutions is $\{\w+H_A^p(M)\}.$
This is equivalent to say that the map  \begin{eqnarray*}
\mathcal{P}_{\Delta_{Neu}}: H^s(M)/\mathcal{N}&{\longrightarrow} &H^{s-2}(M)\times H^{s-\frac{1}{2}}(\partial M)\times H^{s-\frac{3}{2}}(\partial M)\\
  \left[\w\right] & \longmapsto & (\Delta\w,\nu\lrcorner\w,\nu\lrcorner d\w) 
    \end{eqnarray*} is a topological isomorphism onto its image which is \[
\im(\mathcal{P}_{\Delta_{Neu}}) = \{ ({\w_0}, \w_1, \w_2) \in H^{s-2}(M)\times H^{s-\frac{1}{2}}(\partial M)\times H^{s-\frac{3}{2}}(\partial M) \ | \ \forall \w' \in \mathcal{N}^*, ({\w_0}, \w') + (\w_1,\underbrace{\iota^*\delta\w'}_{0})+(\w_2,\iota^*\w')=0 \}, 
\] here $\mathcal{N}$ and $\mathcal{N}^*$ are equal to $H_A^p(M).$
\end{lemma}
\begin{proof}
\underline{\textbf{Step 1 :}} We start by showing the ellipticity of the problem \eqref{eq:SteklovFormeGénéraleCorrigée} in the sense of Shapiro-Lopatinskij.

    In the same way as in  \secref{sec:elliticiteBSNF1preuve}, let us show that the map
    \begin{align*}
    & \Phi : \mathcal{M}^+_{\Delta,v} \longrightarrow  E_1 \oplus E_2 \\
    & \hspace{1.25cm} y \longmapsto \left( \sigma_{B_1}(-iv+\partial_t\nu^\flat)(y), \sigma_{B_2}(-iv+\partial_t\nu^\flat)(y) \right)(0)
    \end{align*}
    is an isomorphism where in this case \begin{align*}
\mathcal{M}^+_{\Delta,v} 
= &\spann\big(ae^{-|v| t}.\w_0 \,|\, a\in \mathbb{R}, \w_0\in \Lambda^pT^*_xM_{|\partial M} \big)
\end{align*} and has dimension $\binom{n}{p}$. Let $B_1$ and $B_2$ be the following maps:
    \begin{align*}
    B_1: \Omega^p(M) &\longrightarrow \Gamma(E_1 = \Lambda^{p-1} T^*\partial M) \qquad \quad ; \  & B_2: \Omega^p(M) &\longrightarrow \Gamma(E_2 = \Lambda^{p} T^*\partial M) \\
    \hat{\w} &\longmapsto \nu \lrcorner \hat{\w} & \hat{\w} &\longmapsto \nu \lrcorner d\hat{\w}.
    \end{align*}
    We calculate the principal symbols of $B_1$ and $B_2$ for $\xi=(-iv+\partial_t\nu^\flat)$ and applied to $y$. Let $y\in \mathcal{M}^+_{\Delta,v}$, we obtain $
    \sigma_{B_1}(-iv+\partial_t\nu^\flat)(y)(0) = a \nu \lrcorner \w_0$
    and $\sigma_{B_2}(-iv+\partial_t\nu^\flat)(y)(0) = -a |v| \iota^*\w_0 + ia \iota^*v \wedge (\nu \lrcorner \w_0).$
    Thus, the map $\Phi$ is
    \begin{align*}
    & \Phi : \mathcal{M}^+_{\Delta,v} \longrightarrow  E_1 \oplus E_2 \\
    & \hspace{1.25cm} y \longmapsto \left( a \nu \lrcorner \w_0, -a |v| \iota^*\w_0 + ia \iota^*v \wedge (\nu \lrcorner \w_0) \right).
    \end{align*}
    Suppose that $\Phi(y) = 0$, then either $a=0$, or 
    \begin{align*}
    &\begin{cases}
    a \nu \lrcorner \w_0 &= 0 \\
    -a |v| \iota^*\w_0 + ia \iota^* v \wedge (\nu \lrcorner \w_0) &= 0
    \end{cases} 
    \Longrightarrow
    \begin{cases}
    \nu \lrcorner \w_0 &= 0 \\
    \iota^*\w_0 &= 0  
    \end{cases}
    \end{align*}
    Therefore, in both cases $\w_0 = 0$, so $y = 0$, and thus $\Phi$ is injective.


   \underline{\textbf{Step 2 :}} By \thref{theo:thm5.4} we have hence that $\mathcal{P}_{\Delta_{Neu}}$ is a topological isomorphism on its image so it is invertible and its inverse is continuous. In this case  $\mathcal{N}=\mathcal{N}^*=H_A^p(M)$ (see \secref{sec:lionsMagenes} for their definitions). Indeed, it is clear by the reformulation of the formula \eqref{eq:IPP1} as it is presented in \eqref{eq:greenLionsMagenes}, for $\w$ and $\w'$ solutions of \eqref{eq:SteklovFormeGénéraleCorrigée} we have :
    \begin{equation*}
\begin{split}
    & \int_M\Big( \langle \Delta \w , \w'\rangle -  \langle \w , \Delta \w'\rangle \Big) d\mu_g \\
   =  & \int_{\partial M} \Big( \langle \underbrace{\nu \lrcorner \w}_{B_1\w}, \underbrace{\iota^*\delta \w'}_{-T_1\w'}\rangle +\langle \underbrace{\nu \lrcorner d \w}_{B_2\w}, \underbrace{\iota^* \w'}_{-T_2\w'}\rangle-\langle \underbrace{\iota^* \w}_{S_1\w}, \underbrace{\nu \lrcorner d \w'}_{-C_1\w'}\rangle  -\langle \underbrace{\iota^* \delta \w}_{S_2\w}, \underbrace{\nu \lrcorner \w'}_{-C_2\w'}\rangle  \Big)d\mu_g.
\end{split}
\end{equation*}
 Then $({\w_0}, \w_1, \w_2) \in \im(\mathcal{P}_{\Delta_{Neu}})$ if and only if for every $\alpha \in H_A^p(M)$, we have 
\[
({\w_0}, \alpha)- (\w_1, \underbrace{\iota^* \delta \alpha}_{0} )- (\w_2, \iota^* \alpha)= 0
\]
which implies
\[
(\Delta \w, \alpha ) = (\w_2, \iota^* \alpha).
\]
Thus, $(0, \w_1, \w_2) \in \im(\mathcal{P}_{\Delta_{Neu}})$ if and only if for every $\alpha \in H_A^p(M)$, $\int_{\partial M}\langle \w_2, \iota^* \alpha \rangle d\mu_g = 0.$ Therefore, we must choose $\w_2 \in {{H}_A^p}^{\perp_{L^2(\partial M)}}(M):= \{\theta \in H^{-\frac{3}{2}}(\partial M) \ | \ \forall \alpha\in H_A^p(M),\ ( \theta, \iota^* \alpha )= 0\}$ to get the result. Consequently, we have the inclusion 
\[
\{0\} \times H^{-\frac{1}{2}}(\partial M) \times {{H}_A^p}^{\perp_{L^2(\partial M)}}(M) \subset \im(\mathcal{P}_{\Delta_{Neu}}).
\] 
\end{proof}



\begin{lemma}\label{lem:SteklovFormeGénéral}
    For all $(\w_1,\w_2)\in L^2(\partial M)\times L^2(\partial M) $ there exists a unique $\w\in H^2(M)$ such that in the weak sense we have \begin{equation}\label{eq:SteklovFormeGénéral}
 \begin{cases}
    \Delta \w = 0 & \text{on } M \\
    \nu \lrcorner \w = \w_1 & \text{on } \partial M \\
    \nu \lrcorner d\w = \w_2 & \text{on } \partial M\\
    \w\perp_{L^2(M)}H_A^p(M).
\end{cases} 
\end{equation}
Moreover, \begin{eqnarray*}
 E: L^2(\partial M) \oplus L^2(\partial M) &\longrightarrow & \check{L}^2(M)\\
  (\w_1,\w_2)& \longmapsto & \w  \notag 
    \end{eqnarray*} is compact.
\end{lemma}
\begin{proof}
   We rely on an argument of \cite[p.318]{FerreroGazzolaWeth}. The map $E$ is well defined by \lemref{lm:SteklovFormeGénéraleCorrigée}. The goal for now is to show that it is continuous. To prove this, we express the composition of the map $E$ as follows:
\[
\begin{array}{cccccccc}
 L^2(\partial M) \oplus L^2(\partial M) & \overset{\mathcal{Q}}{\longrightarrow} & H^{-\frac{1}{2}}(\partial M)\oplus H^{-\frac{3}{2}}(\partial M) & \overset{(\mathcal{P}_{\Delta_{Neu}})^{-1}}{\longrightarrow} & D_\Delta^0(M)/\mathcal{N}&  \overset{\pi}{\longrightarrow}&\check{L}^2(M) \\
(\w_1,\w_2) & \longmapsto & (\w_1,\w_2)  & \longmapsto & [\w] &\longmapsto &\w
\end{array}
\]
Here $\mathcal{Q}$ is the inclusion map and $\mathcal{P}_{\Delta_{Neu}}$ is given by \lemref{lm:SteklovFormeGénéraleCorrigée}.
By the Rellich-Kondrachov theorem, the map $H^{\frac{1}{2}}(\partial M)\longrightarrow L^2(\partial M)$ is compact. Thus, by duality, we obtain that $L^2(\partial M) {\longrightarrow} H^{-\frac{1}{2}}(\partial M)$ is a compact inclusion. In addition, since $H^{\frac{3}{2}}(M)\subset H^{\frac{1}{2}}(M)$ is a continuous inclusion, we have that $L^2(\partial M) {\longrightarrow} H^{-\frac{3}{2}}(\partial M)$ is compact. Therefore, the application $\mathcal{Q}$ is compact. Since by \lemref{lm:SteklovFormeGénéraleCorrigée}, $\mathcal{N}=H_A^p(M)$, the map $\pi$ is continuous which shows the continuity and compactness of $E.$\end{proof} 


 Let us come back to the proof of \propref{prop:l'minimum}. Let $ (\w_1, \w_2) \in L^2(\partial M)\times L^2(\partial M)$ and let $ {\w_0} = E(\w_1,\w_2) $ be the harmonic extension given by \lemref{lem:SteklovFormeGénéral}. Since $E$ is continuous, there exists a constant $ c > 0 $ such that
\begin{align*}
\lVert\w_0\rVert^2_{L^2(M)}=\lVert E(\w)\rVert^2_{L^2(M)} 
&\leq c \left(\lVert \w_1 \rVert^2_{L^2(\partial M)} + \lVert \w_2 \rVert^2_{L^2(\partial M)}\right) \\
&= c \left(\lVert \nu \lrcorner {\w_0} \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d \hat{\w} \rVert^2_{L^2(\partial M)}\right).
\end{align*}
Therefore, $\ell'_{1,p}\geq \frac{1}{c}$ is positive.


Now let $ \mathbb{S} $ be the unit sphere, \[\mathbb{S} = \{ (\w_1,\w_2) \in L^2(\partial M) \oplus {H_A^p(M)}^{\perp_{L^2(\partial M)}} \ | \ \lVert \w_1 \rVert^2_{L^2(\partial M)} + \lVert \w_2 \rVert^2_{L^2(\partial M)} = 1 \}.\] Since $ E $ is compact, $ E(\mathbb{S}) $ is relatively compact in $\check{L}^2(M)$, and thus there exists $ \Tilde{\w} \in \overline{E(\mathbb{S})}\subset \check{L}^2(M) $ such that $ \lVert \Tilde{\w} \rVert_{L^2(M)} = \sup\{ \lVert E\w \rVert_{L^2(M)} \ | \ \w \in \mathbb{S} \} $. Therefore, there exists a subsequence $ (\w_m)_m \in \mathbb{S} $ such that $ E\w_m \xrightarrow[\substack{m \to \infty}]{L^2(M)}\Tilde{\w} $. Then, $ \Delta(E\w_m)\xrightarrow[\substack{m \to \infty}]{H^{-2}(M)} \Delta\Tilde{\w} $. Moreover, since $E(\w_m)\in H^2(M)$ and $\Delta(E\w_m) =0\in L^2(M)$ we get $ \Delta(E\w_m)\xrightarrow[\substack{m \to \infty}]{L^2(M)} 0=\Delta\Tilde{\w} $. Using the inequality 
\[
\lVert \w \rVert_{H^2(M)} \leq c \left( \lVert \Delta\w \rVert_{L^2(M)} + \lVert \w \rVert_{L^2(M)} \right)
\]
given in \cite[Theorem $1.6.12$]{ChristianBaer}, we obtain for some positive constant $c$: 
\[
\lVert E\w_m - \Tilde{\w} \rVert_{H^2(M)} \leq c \left( \lVert \Delta(E\w_m - \Tilde{\w}) \rVert_{L^2(M)} + \lVert E\w_m - \Tilde{\w} \rVert_{L^2(M)} \right),
\]
so in the limit, $ E\w_m \xrightarrow[\substack{m \to \infty}]{H^2(M)}\Tilde{\w} $. This implies that $ \nu \lrcorner E(\w_m) \xrightarrow[\substack{m \to \infty}]{H^{\frac{3}{2}}(\partial M)}\nu \lrcorner \Tilde{\w} $, and $ \nu \lrcorner dE(\w_m) \xrightarrow[\substack{m \to \infty}]{H^{\frac{1}{2}}(\partial M)}\nu \lrcorner d\Tilde{\w} $. Since $ \lVert \nu \lrcorner E(\w_m) \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d E(\w_m) \rVert^2_{L^2(\partial M)} = 1 $, we conclude that in the limit, $\lVert \nu \lrcorner \Tilde{\w} \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d \Tilde{\w} \rVert^2_{L^2(\partial M)} = 1.$
Thus, $ \Tilde{\w} \in E(\mathbb{S}) $, and since $ \lVert \Tilde{\w} \rVert_{L^2(M)} = \max\{ \lVert E\w \rVert_{L^2(M)} \ | \ \w \in \mathbb{S} \} $, we have $ \lVert \Tilde{\w} \rVert_{L^2(M)} = \frac{1}{\ell'_{1,p}} $. Therefore, $ \ell'_{1,p} $ is a minimum, which completes the proof.
\end{proof}

\begin{proof}[Proof of \thref{theo:l1p}]
   Let $\w$ be a $\ell_{1,p}$-eigenform of BSN1. Without loss of generality, we can assume that 
\[
\lVert \iota^*\w \rVert_{L^2(\partial M)} + \lVert \iota^*\delta\w \rVert_{L^2(\partial M)} = 1.
\]
Consider the following problem
\begin{equation}\label{eq:systeme}
\begin{cases}
    \begin{aligned}
    &\Delta \hat{\w} &&= 0 && \text{on } M \\
    &\nu \lrcorner \hat{\w} &&= \ell_{1,p} \iota^*\delta\w && \text{on } \partial M \\
    &\nu \lrcorner d\hat{\w} &&= \ell_{1,p} \iota^*\w && \text{on } \partial M,
    \end{aligned}
\end{cases}
\end{equation} which is a particular case of \eqref{eq:SteklovFormeGénéraleCorrigée}. Since $\iota^*\w\perp_{L^2(\partial M)} H_A^p(M)$ by \lemref{lem:SteklovFormeGénéral} and there exists a unique solution $\hat{\w}\perp_{L^2(M)}H_A^p(M)$. Given that $\mathcal{N}^*=H_A^p(M)$, we have by \thref{theo:thm5.4} the map \begin{eqnarray*}
\mathcal{P}_{\Delta_{Neu}}: H^2(M)/H_A^p(M)&{\longrightarrow} &L^{2}(M)\times H^{\frac{3}{2}}(\partial M)\times H^{\frac{1}{2}}(\partial M)\\
  \left[\w\right] & \longmapsto & (\Delta\w,\nu\lrcorner\w,\nu\lrcorner d\w) 
    \end{eqnarray*} is an isomorphism on \begin{align*}
\im(\mathcal{P}_{\Delta_{Neu}}) &= \{ (\w_0, \w_1, \w_2) \ | \ \forall \w' \in H_A^p(M), (\w_0, \w') + (\w_1, \iota^*\delta\w')+ (\w_2, \iota^*\w') = 0 \}\\
&\supset \{(\w_0, \w_1, \w_2) \ | \ \forall \w' \in H_A^p(M), (0, \w') + \ell_{1,p}(\underbrace{\iota^*\delta\w}_{0}, \iota^*\delta\w')+ \ell_{1,p}\underbrace{(\iota^*\w, \iota^*\w')}_{0} = 0\},\end{align*} where $(\cdot,\cdot)$ is the duality product. Therefore $(0,\ell_{1,p}\iota^*\delta\w,\ell_{1,p}\iota^*\w)$ belongs to $\im(\mathcal{P}_{\Delta_{Neu}})$. Let $\hat{\w} \in \Omega^p(M)$ be a solution of \eqref{eq:systeme} and $\hat{\w}_1 := \proj_{\perp_{L^2(M)}}(\hat{\w}) \in H_A^p(M)$. Then $\hat{\w}_2 := \hat{\w} - \hat{\w}_1$ which will be a solution of \eqref{eq:systeme} such that $\hat{\w}_2$ is $L^2(M)$-orthogonal to $H_A^p(M)$.


Next, using \eqref{eq:IPP3'} for $\w \in Z_1$, we obtain 
\begin{equation*}
\begin{split}
    \int_M \langle \hat{\w}_2 , \Delta \w \rangle d\mu_g + \ell_{1,p} \int_{\partial M} \Big( \langle \iota^* \w, \iota^* \w \rangle + \langle \iota^*\delta \w, \iota^*\delta \w \rangle \Big) d\mu_g = 0,
\end{split}
\end{equation*}
hence
\begin{equation*}
\begin{split}
    \int_M \langle \hat{\w}_2 , \Delta \w \rangle d\mu_g + \ell_{1,p} \underbrace{\int_{\partial M} \big( \lvert \iota^* \w \rvert^2 + \lvert \iota^*\delta \w \rvert^2 \big) d\mu_g}_{=1} = \int_M \langle \hat{\w}_2 , \Delta \w \rangle d\mu_g + \ell_{1,p} = 0.
\end{split}
\end{equation*}
Using the Cauchy-Schwarz inequality, we get
\begin{equation}\label{eq:cauchyInTheProof}
\ell_{1,p} \leq \lVert \Delta\w \rVert_{L^2(M)} \lVert \hat{\w}_2 \rVert_{L^2(M)}.
  \end{equation}
Since $\w$ is an eigenform of $K_1$ with eigenvalue $\frac{1}{\ell_{1,p}}$, we have \[\lVert\w\rVert^2_{W_1}=(K_1\w,\w)_V=\frac{1}{\ell_{1,p}}\lVert\w\rVert^2_{V}=\frac{1}{\ell_{1,p}}\lVert\Delta\w\rVert^2_{L^2(M)}\] which implies $\lVert\Delta\w\rVert^2_{L^2(M)}=\ell_{1,p}$ hence $\lVert\Delta\w\rVert_{L^2(M)}=\ell_{1,p}^{\frac{1}{2}}$, consequently by \eqref{eq:cauchyInTheProof} we get $\ell_{1,p}\leq \lVert\hat{\w}_2\rVert^2_{L^2(M)}.$  Thus
\begin{alignat*}{2}
    & \frac{ \lVert \nu \lrcorner \hat{\w}_2 \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\hat{\w}_2 \rVert^2_{L^2(\partial M)} }{ \lVert \hat{\w}_2 \rVert^2_{L^2(M)} } &&= \frac{\ell_{1,p}^2 \lVert \iota^*\w \rVert^2_{L^2(\partial M)} + \ell_{1,p}^2 \lVert \iota^*\delta \w \rVert^2_{L^2(\partial M)}}{ \lVert \hat{\w}_2 \rVert^2_{L^2(M)}} \\
    && \leq & \frac{\ell_{1,p}^2 \left( \lVert \iota^*\w \rVert^2_{L^2(\partial M)} + \lVert \iota^*\delta \w \rVert^2_{L^2(\partial M)} \right)}{ \ell_{1,p}} = \ell_{1,p}.
\end{alignat*}
Finally \[\underset{\substack{ \w \perp_{L^2(M)} H_A^p(M)\\ \Delta \w = 0}}{\inf}\  \frac{ \lVert \nu \lrcorner \hat{\w}_2 \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\hat{\w}_2 \rVert^2_{L^2(\partial M)} }{ \lVert \hat{\w}_2 \rVert^2_{L^2(M)} }\leq \ell_{1,p}.\]
Conversely, let $\w \in \Omega^p(M) \setminus \{0\}$ be a minimizer of $\ell'_{1,p}$ as given in  \propref{prop:l'minimum}, i.e., $\w$ is $L^2(M)$-orthogonal to $H_A^p(M)$, $\Delta \w = 0$ on $M$, and
\[
\lVert \nu \lrcorner \w \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\w \rVert^2_{L^2(\partial M)} = \ell'_{1,p} \lVert \w \rVert^2_{L^2(M)}.
\]
Again, using  \lemref{lem:SteklovFormeGénéral}, for $\w_0=\w,\ \w_1=0$ and $\w_2=0$, the following problem which is a particular case of \eqref{eq:SteklovFormeGénéraleCorrigée} has a solution since $\w\perp_{L^2(M)}H_A^p(M):$
\begin{equation}\label{eq:SteklovFormeGénéraleCorrigéeW1W2=0}
\begin{cases}
    \begin{aligned}
    & \Delta \hat{\w} && = \w && \text{on } M \\
    & \nu \lrcorner \hat{\w} && = 0 && \text{on } \partial M \\
    & \nu \lrcorner d\hat{\w} && = 0 && \text{on } \partial M. 
    \end{aligned}
\end{cases}
\end{equation} Indeed, using integration by parts \eqref{eq:IPP1} we get \begin{align*}
    \int_M \langle \w, \alpha \rangle d\mu_g &= \int_M \langle \Delta \hat{\w}, \alpha \rangle d\mu_g \\
    &= \int_M \langle \hat{\w}, \underbrace{\Delta \alpha}_{0} \rangle d\mu_g + \int_{\partial M} \Big( \langle \underbrace{\nu \lrcorner d \hat{\w}}_{0}, \iota^* \alpha \rangle 
    - \langle \iota^* \hat{\w}, \underbrace{\nu \lrcorner d \alpha}_{0} \rangle \\
    &\quad + \langle \underbrace{\nu \lrcorner \hat{\w}}_{0}, \iota^* \delta \alpha \rangle 
    - \langle \iota^* \delta \hat{\w}, \underbrace{\nu \lrcorner \alpha}_{0} \rangle \Big) d\mu_g,
\end{align*} then $\int_M\langle\w,\alpha\rangle d\mu_g=0$ hence, $\w\perp_{L^2(M)}H_A^p(M)$. Therefore, there exists a such solution $\hat{\w}$.\\ We have the following decomposition: $\hat{\w}=\hat{\w}_1+\hat{\w}_2,$ where $\hat{\w}_1\in H_A^p(M)$ and $\hat{\w}_2\in H_A^p(M)^{\perp_{L^2(\partial M)}}.$ 
Using the integration by parts \eqref{eq:IPP1}, we get 
\begin{align}\label{eq:***}
    \lVert \w \rVert^2_{L^2(M)} &= (\Delta \hat{\w}_2, \w)_{L^2(M)} \nonumber\\
    &= - (\iota^* \hat{\w}_2, \nu \lrcorner d\w)_{L^2(\partial M)} - (\iota^* \delta \hat{\w}_2, \nu \lrcorner \w)_{L^2(\partial M)}.
\end{align}
Note that
\begin{equation}\label{eq:****}
\ell_{1,p} \left( \lVert \iota^* \hat{\w}_2 \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \hat{\w}_2 \rVert^2_{L^2(\partial M)} \right) \leq \lVert \w \rVert^2_{L^2(M)}.
\end{equation}
Using Cauchy-Schwarz inequality in \eqref{eq:***}, we obtain
\begin{align*}
    \lVert \w \rVert^2_{L^2(M)} &\leq \left( \lVert \iota^* \hat{\w}_2 \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \hat{\w}_2 \rVert^2_{L^2(\partial M)} \right)^{\frac{1}{2}} \left( \lVert \nu \lrcorner \w \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\w \rVert^2_{L^2(\partial M)} \right)^{\frac{1}{2}} \\
    &\leq \frac{\lVert \w \rVert_{L^2(M)} \left( \lVert \nu \lrcorner \w \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\w \rVert^2_{L^2(\partial M)} \right)^{\frac{1}{2}}}{\ell_{1,p}^{\frac{1}{2}}}.
\end{align*}
Thus,
\[
\ell_{1,p}^{\frac{1}{2}} \leq \frac{\left( \lVert \nu \lrcorner \w \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\w \rVert^2_{L^2(\partial M)} \right)^{\frac{1}{2}}}{\lVert \w \rVert_{L^2(M)}}.
\]
Hence, the desired characterization follows.

\end{proof}

\begin{cor}
    Let $\w$ be any harmonic $p$-form which is $L^2(M)$-orthogonal to $H_A^p(M)$. Then the equality
    \[
    \ell_{1,p} = \frac{ \lVert \nu \lrcorner \w \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\w \rVert^2_{L^2(\partial M)} }{ \lVert \w \rVert^2_{L^2(M)}}
    \]
    holds if and only if there exists a $\ell_{1,p}$-eigenform $\hat{\w}$ for BSN1 such that $\Delta \hat{\w} = \w$.
\end{cor}

\begin{proof}
    Inequality \eqref{eq:****} is strict when $\hat{\w}_2$ is an eigenform for $K_1$ with eigenvalue $\frac{1}{\ell_{1,p}}$, i.e., a solution of BSN1 associated with $\ell_{1,p}.$
\end{proof}




\begin{thm}\label{thm:ell_k_2}
For every $ k \in \mathbb{N} $, we have the following characterization for the $ k^{\text{th}} $ positive eigenvalue of BSN1:
\[
\ell_{k,p} = \inf_{\substack{\mathcal{V}_k \subset V_1 \\ \dim \mathcal{V}_k = k}} \sup_{0 \neq \w \in \mathcal{V}_k} \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)}}.
\]
\end{thm}
We will rely on the following immediate Lemma:
\begin{lemma}\label{lem: v}
Let $H $ be a Hilbert space, and let $V$ and $ E_{k-1} $ be subspaces of $ H $ of dimension $ k $ and $ k-1 $ respectively, where $k\geq 1$. Then $ V \cap E_{k-1}^{\perp} \neq \{0\} $.
\end{lemma}

\begin{proof}[Proof of  \thref{thm:ell_k_2}]
Let $ (\w_i)_{i \geq 1} $ be a Hilbert basis of $ (V_1, (\cdot, \cdot)_{V}) $, with $ \w_i $ being $\ell_{i,p}$-eigenforms. According to  \lemref{lem: v}, for $ \mathcal{V}_k \subset V_1 $ such that $ \dim \mathcal{V}_k = k $, there exists a non-zero $ \w \in \mathcal{V}_k $ such that $ (\w, \w_i)_{V} = 0 $ for all $ i = 1, \cdots, k-1 $. Thus, $ \w = \underset{i \geq k}{\sum}(\w, \w_i)_{V} \w_i $ and we have:
\[
\lVert \w \rVert_{V}^2 = \sum_{i \geq k} (\w, \w_i)_{V}^2,
\]
and
\[
\lVert \w \rVert_{W_1}^2 = (K \w, \w)_{V} = \sum_{i \geq k} \frac{1}{\ell_{i,p}} (\w, \w_i)_{V}^2 \leq \frac{1}{\ell_{k,p}} \sum_{i \geq 1} (\w, \w_i)_{V}^2.
\]
Thus, we conclude that $\ell_{k,p} \leq \frac{\lVert \w \rVert_{V}^2}{\lVert \w \rVert_{W_1}^2}.$ Therefore, $\ell_{k,p} \leq \underset{0 \neq \w \in \mathcal{V}_k}{\sup} 
  \frac{\lVert \w \rVert_{V}^2}{\lVert \w \rVert_{W_1}^2}.$ This implies that
\[
\ell_{k,p} \leq \inf_{\substack{\mathcal{V}_k \subset V_1 \\ \dim \mathcal{V}_k = k}} \sup_{0 \neq \w \in \mathcal{V}_k} \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)}}.
\]

To show the second inequality, we define $ \overline{V}_k = \spann(\w_1, \cdots, \w_k) \subset V_1 $. For $ \w \in \overline{V}_k $, we have 
\[
\lVert \w \rVert_{V}^2 = \sum_{i=1}^k (\w, \w_i)_{V}^2,
\]
and
\[
\lVert \w \rVert_{W_1}^2 = (K \w, \w)_{V} = \sum_{i=1}^k \frac{1}{\ell_{i,p}} (\w, \w_i)_{V}^2 \geq \frac{1}{\ell_{k,p}} \sum_{i=1}^k (\w, \w_i)_{V}^2.
\]
Thus, $\frac{\lVert \w \rVert_{V}^2}{\lVert \w \rVert_{W_1}^2} \leq \ell_{k,p},$
therefore, $\underset{0 \neq \w \in \mathcal{V}_k}{\sup} \frac{\lVert \w \rVert_{V}^2}{\lVert \w \rVert_{W_1}^2} \leq \ell_{k,p}.$
This concludes the proof.
\end{proof}

\begin{thm}\label{theo:ell_k_3}
 For all $k\in\mathbb{N}$, we have the following characterization of the $k^{\text{th}}$ positive eigenvalue of BSN1:
    \[
    \ell_{k,p}=\inf_{\substack{\mathcal{V}_k\subset \check{H}_{N,1}^2(M) \\ \dim (\mathcal{V}_k/H_0^2(M)\cap \mathcal{V}_k)=k}} \ \underset{\w\in \mathcal{V}_k\backslash H_0^2(M)}{\sup}\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}+\lVert \iota^*\delta \w\rVert^2_{L^2(\partial M)}}.
    \]
\end{thm}

\begin{proof}
    Recall that by  \lemref{lem:Hn=V+H0} we have the following orthogonal decomposition $ \check{H}_{N,1}^2(M)=V\oplus H_0^2(M)$ with respect to the inner product $(\cdot,\cdot)_{V}$. Let $\mathcal{V}_k\subset \check{H}_{N,1}^2(M)$ such that $\dim (\mathcal{V}_k/H_0^2(M)\cap \mathcal{V}_k)=k$, and let $p_{V_1}:\check{H}_{N,1}^2(M)\longrightarrow V_1$ be the orthogonal projection with respect to the inner product $(\cdot,\cdot)_{V}$. We define $\mathcal{U}:=p_{V_1}(\mathcal{V}_k)$ hence $\mathcal{U}\subset V_1$ and $\dim\mathcal{U}=k$. Then, by  \thref{thm:ell_k_2}, we have $\ell_{k,p}\leq \underset{0\neq u\in \mathcal{U}}{\sup}\frac{\lVert u\rVert_{V}^2}{\lVert u \rVert_{W_1}^2}$. Now, let $\w\in \mathcal{V}_k\backslash H_0^2(M)$, we decompose $\w$ as follows: $\w=p_{V_1}(\w)+\w-p_{V_1}(\w)$ where $p_{V_1}(\w)\in \mathcal{U}\subset V_1$ and $\w-p_{V_1}(\w)\in V_1^{\perp_{(\cdot,\cdot)_{V}}}\subset \mathcal{U}^{\perp_{(\cdot,\cdot)_{V}}}$. Thus, we have $ \lVert \w \rVert_{V}^2=\lVert p_{V_1}(\w)\rVert_{V}^2+\lVert\w-p_{V_1}(\w)\rVert_{V}^2$ and since $\w-p_{V_1}(\w)\in H_0^2(M)$, we get $\lVert\w-p_{V_1}(\w)\rVert_{W_1}^2=0$ so $\lVert\w\rVert_{W_1}^2=\lVert p_{V_1}(\w)\rVert_{W_1}^2+\lVert\w-p_{V_1}(\w)\rVert_{W_1}^2$.

    We now have:
    \[
    \frac{ \lVert \w \rVert_{V}^2}{\lVert\w\rVert_{W_1}^2} = \frac{\lVert p_{V_1}(\w)\rVert_{V}^2 + \lVert\w-p_{V_1}(\w)\rVert_{V}^2}{\lVert p_{V_1}(\w)\rVert_{W_1}^2} \geq \frac{\lVert p_{V_1}(\w)\rVert_{V}^2}{\lVert p_{V_1}(\w)\rVert_{W_1}^2}.
    \]
    Therefore,
    \[
    \underset{0\neq \w\in \mathcal{V}_k\backslash H_0^2(M)}{\sup}\frac{\lVert \w\rVert_{V}^2}{\lVert \w \rVert_{W_1}^2} \geq \underset{0\neq \w\in \mathcal{V}_k\backslash H_0^2(M)}{\sup}\frac{\lVert p_{V_1}(\w)\rVert_{V}^2}{\lVert p_{V_1}(\w)\rVert_{W_1}^2} = \underset{ u\in p_{V_1}(\mathcal{V}_k)}{\sup}\frac{\lVert u\rVert_{V}^2}{\lVert u \rVert_{W_1}^2} \geq \ell_{k,p}.
    \]

    This implies that for all $k\in\mathbb{N}$, we have
    \[
    \ell_{k,p}\leq\inf_{\substack{\mathcal{V}_k\subset \check{H}_{N,1}^2(M) \\ \dim (\mathcal{V}_k/H_0^2(M)\cap \mathcal{V}_k)=k}}\ \underset{u\in \mathcal{V}_k\backslash H_0^2(M)}{\sup}\frac{\lVert u\rVert_{V}^2}{\lVert u \rVert_{W_1}^2}.
    \]
    Finally, let $\overline{V}_k=\spann(\w_1,\cdots,\w_k)\subset V_1$. Since $\overline{V}_k$ is a subspace of $V_1$ orthogonal to $H_0^2(M)$, we have $\overline{V}_k\cap H_0^2(M)=\{0\}$. Therefore,
    \[
    \inf_{\substack{\mathcal{V}_k\subset \check{H}_{N,1}^2(M) \\ \dim (\mathcal{V}_k/H_0^2(M)\cap \mathcal{V}_k)=k}}\ \underset{\w\in \mathcal{V}_k\backslash H_0^2(M)}{\sup}\frac{\lVert \w\rVert_{V}^2}{\lVert \w\rVert_{W_1}^2} \leq \underset{u\in \mathcal{V}_k\backslash H_0^2(M)}{\sup}\frac{\lVert u\rVert_{V}^2}{\lVert u\rVert_{W_1}^2} = \ell_{k,p}.
    \]
    This concludes the proof.

\end{proof}
\begin{remark}
For every $ k \in \mathbb{N} $, the following characterization holds for the $ k^{\text{th}} $ positive eigenvalue of BSN1:
\[
\ell_{k,p} = \inf_{\substack{\w \in V_1 \\ \w \perp_{W_1} \spann(\w_1, \cdots, \w_{k-1})}} \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)}}.
\]
\end{remark}



\subsection{No Kuttler-Sigillito inequalities using BSN1}
Let us describe the problem to establish the Kuttler-Sigillito inequality $\mu_1\sigma_1 \leq \ell_1$ based on this BSN1. Regardless of the conditions imposed in the characterizations, for any $\w\in\Omega^p(M),$ we have
\begin{align}\label{eq:4stars}
&\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}
\times
\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}}
= 
\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)}} \notag \\
&\phantom{=}\qquad \qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\geq 
\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)} + \lVert \iota^* \delta \w \rVert^2_{L^2(\partial M)}}.
\end{align}

Thus, using the characterizations \eqref{eq:vp1NeumannAbsolueFormeAlternative}, \eqref{eq:sigma1formesSteklov} and \eqref{eq:BSN1VP1} does not yield Kuttler-Sigillito inequalities. We can also try using the characterizations 
\eqref{eq:vpNeumannAbsolueForme}, \eqref{eq:sigma1formeNotInHAP}, and \eqref{eq:ell1}. So we get
\begin{align*}
\mu_1 \sigma_1 &= \inf_{\substack{\w \perp_{L^2(M)} H_A^p(M) \\ \nu \lrcorner \w = 0 }}
\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(M)}} 
\times 
\inf_{\substack{\w \notin H_A^p(M) \\ \nu \lrcorner \w = 0 \\ \Delta\w = 0}}
\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}} \\
&\leq \inf_{\substack{\w \perp_{L^2(M)} H_A^p(M) \\ \nu \lrcorner \w = 0 \\ \Delta\w = 0}}
\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert \w \rVert^2_{L^2(M)}}.
\end{align*}

Because of the boundary condition $\nu\lrcorner\w=0$ the infimum above is a priori greater than 
\[
\ell_1 = \inf_{\substack{\w \perp_{L^2(M)} H_A^p(M) \\ \Delta \w = 0 }}
\frac{\lVert \nu \lrcorner \w \rVert^2_{L^2(\partial M)} + \lVert \nu \lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert \w \rVert^2_{L^2(M)}},
\]
which also prevents us from concluding.

In a forthcoming paper, we will see that on some examples the inequality $\mu_1\sigma_1\ell_1$ can indeed fail.

\section{Spectral properties of BSN2}
\subsection{Formulation of the boundary problem}\label{sec:FormulationBSN2}
To establish the inequalities \eqref{eq:3èmePBmuksigma1<lk}, and \eqref{eq:3èmePBmu1sigmak<lk}, it follows from \eqref{eq:BSN1VP1} and \eqref{eq:4stars} that it is enough to have a BSN on differential forms, whose first non-zero eigenvalue satisfies
\begin{align*}
\mathbf{l}_{1,p} &= \inf\left\{\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}} \,\Big|\ \w \in \check{H}^2_{N,1}(M),\ \iota^*\delta\w=0\ \text{and}\ \iota^*\w \neq 0\ \text{on}\ \partial M\right\}.
\end{align*}
We start by defining the following spaces: 
\[{H}_{N,2}^2(M) := \{\w \in H^2(M)\ |\ \nu\lrcorner d\w = 0,\ \nu\lrcorner \w =0,\ \iota^*\delta\w = 0\ \text{on} \ \partial M\},\]\begin{equation}\label{eq:H2Ncheck}
    \check{H}_{N,2}^2(M) := \{\w \in H^2(M)\ |\ \nu\lrcorner d\w = 0,\ \nu\lrcorner \w =0,\ \iota^*\delta\w = 0\ \text{on} \ \partial M \ \text{and}\ \w \perp_{L^2(\partial M)} H_A^p(M)\}\subset \check{H}_{N,1}^2(M).
\end{equation}
\[ Z_2 := \{\w \in \Omega^p(M)\cap {H}_{N,2}^2(M)  \ | \ \Delta^2\w = 0 \ \text{on}\ M \}\subset Z_1\subset H^2_{N,1}(M), \]  
and  
\[ \check{Z}_2 := \{\w \in Z_2 \ | \ \w \perp_{L^2(\partial M)} H_A^p(M)\}=Z_2\cap\check{H}_{N,1}^2(M)=Z_2\cap \check{Z}_1. \]  We compute the critical points of the following functional: $ Q(\w) := \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}} $ on $ \check{H}^2_{N,2}(M)$, which will be the eigenforms of the new BSN2 problem that we will determine. The critical points of the functional $ Q(\w) $ are those $\w$ such that $ d_{\w} Q$ is zero, i.e, $\w\in\check{H}^2_{N,2}(M)$ is a critical point of $Q(\w)$ if and only if for all $ \w' \in \check{Z}_2\subset \check{H}^2_{N,2}(M)$, we have
\begin{equation}\label{eq:pointsCritiquesBSN2}
    (\Delta\w,\Delta\w')_{L^2(M)}\lVert\iota^*\w\rVert^2_{L^2(\partial M)} = (\iota^*\w,\iota^*\w')_{L^2(\partial M)}\lVert\Delta\w\rVert^2_{L^2(M)}.
\end{equation}
Using an integration by parts \eqref{eq:IPP2} in \eqref{eq:pointsCritiquesBSN2}, we get
\[
(\Delta^2\w,\w')_{L^2(M)} - (\nu\lrcorner d\Delta\w,\iota^*\w')_{L^2(\partial M)} = \frac{\lVert \Delta\w\rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}(\iota^*\w,\iota^*\w')_{L^2(\partial M)}.
\]
Denoting $\mathbf{l}=\frac{\lVert \Delta\w\rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}$, it follows that
\begin{equation}\label{eq:preuveFonctionnelle}
(\Delta^2\w,\w')_{L^2(M)} = \left(\nu\lrcorner d\Delta\w+\mathbf{l}\iota^*\w,\iota^*\w'\right)_{L^2(\partial M)}.
\end{equation}
Let us now show that $\Delta^2\w=0$ on $M$. We define the sets $D_\epsilon:=\{x\in M\ | \ d(x,\partial M)\geq \epsilon\}$ and  $D_{2\epsilon}:=\{x\in M\ | \ d(x,\partial M)\geq 2\epsilon\}$. There exists $\chi_\epsilon \in C^\infty(M, [0, 1])$ such that ${\chi_\epsilon}_{|D_{2\epsilon}} = 1$ and ${\chi_\epsilon}_{|(M \backslash D_\epsilon)} = 0$. Let $\w_\epsilon := \chi_\epsilon \Delta^2 \w \in \Omega^p(M)$ then ${\w_\epsilon}_{|(M \backslash D_\epsilon)} = 0$ thus, $\nu \lrcorner \w_\epsilon,\ \nu \lrcorner d\w_\epsilon$, $\iota^* \delta \w_\epsilon$ and $\iota^* \w_\epsilon $ vanish on $\partial M$ since $\w_\epsilon$ vanishes on a neighbourhood of $\partial M$. Then $ \int_M \langle \Delta^2 \w, \chi_\epsilon \Delta^2 \w \rangle d\mu_g = 0 = \int_M \chi_\epsilon \lvert \Delta^2 \w \rvert^2 d\mu_g,$ hence $\chi_\epsilon \Delta^2 \w = 0.$ Thus, $\chi \Delta^2 \w = 0$, so $\Delta^2 \w = 0$ on $D_\epsilon$, and letting $\epsilon$ tend to $0$, we conclude that $\Delta^2 \w = 0$ on $M$.  

