We show now that \eqref{eq:preuveFonctionnelle} is valid for all $\w\in \check{H}^2_{N,2}(M),\ \w'\in H_A^p(M)$. Then, using \eqref{eq:IPP2} for such $\w$ and $\w'$, we get
\begin{align*}
\int_M \langle \Delta^2 \w , \w' \rangle \, d\mu_g 
&= \int_{\partial M} \langle \nu \lrcorner d \Delta\w, \iota^* \w' \rangle \, d\mu_g \\
&= \int_{\partial M} \left\langle \nu \lrcorner d\Delta\w + \mathbf{l} \iota^*\w, \iota^*\w' \right\rangle d\mu_g \\
&\quad - \int_{\partial M} \left\langle\mathbf{l}\iota^*\w, \iota^*\w' \right\rangle d\mu_g
\end{align*}
noting that here $(\iota^*\w,\iota^*\w')_{L^2(\partial M)}=0$. 
From the above, we deduce that \eqref{eq:preuveFonctionnelle} is true for all $\w' \in {H}^2_{N,2}(M)$. By \lemref{lem:Bilap1}, there exists a unique $\w'\in \Omega^p(M)$ such that 
\begin{equation*}
\begin{cases}
\Delta^2\w'=0 & \text{on} M,\\
  \nu \lrcorner \w' = 0 & \text{on } \partial M, \\
  \nu \lrcorner d \w' = 0 & \text{on } \partial M, \\
  \iota^* \delta \w' = 0 & \text{on } \partial M, \\
  \iota^* \w' = \nu \lrcorner d \Delta \w + \mathbf{l} \iota^* \w & \text{on } \partial M.
\end{cases}
\end{equation*}
Since $\w'\in {H}^2_{N,2}(M)$, then by \eqref{eq:preuveFonctionnelle} we get $(\nu\lrcorner d\Delta\w+\mathbf{l}\iota^*\w,\iota^*\w')_{L^2(\partial M)}=0,$ hence $\nu\lrcorner d\Delta\w+\mathbf{l}\iota^*\w=0.$

Therefore, $\w$ is a smooth critical point of $\mathcal{Q}$ if and only if $\w$ satisfies:
\begin{equation*}
\begin{cases}
\Delta^2 \w = 0 & \text{on } M \\
\nu \lrcorner \w = 0 & \text{on } \partial M \\
\nu \lrcorner d \w = 0 & \text{on } \partial M \\
\iota^* \delta \w = 0 & \text{on } \partial M \\
\nu \lrcorner d \Delta \w + \mathbf{l} \iota^* \w = 0 & \text{on } \partial M,
\end{cases}
\end{equation*} for $\mathbf{l}=\frac{\lVert \Delta\w\rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}.$ This problem will be called BSN2 from now on.










\subsection{Ellipticity of BSN2}\label{sec:EllipticityBSN2}
\begin{thm}
 The BSN2 problem \eqref{eq:BSNF2} is elliptic in the sense of Shapiro-Lopatinskij.
\end{thm}

\begin{proof}
We follow the method used in  \secref{sec:elliticiteBSNF1preuve} to show that BSN1 is elliptic. Let us compute the principal symbols of $B_1,\ B_2,\ B_3$ and $B_4$ respectively, applied to $y=e^{-|v| t}(at + b) \cdot \w_0\in \mathcal{M}^+_{\Delta^2,v}$ where $ B_1\w = \nu \lrcorner \w, B_2\w = \nu \lrcorner d\w, B_3\w = \nu \lrcorner d\Delta\w $, and $ B_4\w = \iota^* \delta \w $, we get 
    \begin{align*}
        \sigma_{B_1}(-iv+\partial_t\nu^\flat)(y)(0) &= b \nu \lrcorner \w_0, \\
        \sigma_{B_2}(-iv+\partial_t\nu^\flat)(y)(0) &= \iota^* \w_0 (a - b \lvert v \rvert) + i b \iota^* v \wedge (\nu \lrcorner \w_0), \\
        \sigma_{B_3}(-iv+\partial_t\nu^\flat)(y)(0) &= 2 \lvert v \rvert a (iv \wedge (\nu \lrcorner \w_0) - \lvert v \rvert \iota^* \w_0), \\
        \sigma_{B_4}(-iv+\partial_t\nu^\flat)(y)(0) &= -a \nu \lrcorner \w_0 + \lvert v \rvert b \nu \lrcorner \w_0 + iv b \lrcorner \iota^* \w_0.
    \end{align*} 
    Let us show that the corresponding map
    \begin{align*}
        \Phi : \mathcal{M}^+_{\Delta^2,v} &\longrightarrow \bigoplus_{j=1}^4 E_j
    \end{align*}
    is injective. Assume that $\Phi(y) = 0$. Then:
    \begin{align*}
        &\begin{cases}
            b \nu \lrcorner \w_0 &= 0 \qquad (1)\\
            \iota^* \w_0 (a - b \lvert v \rvert) + i b \iota^* v \wedge (\nu \lrcorner \w_0) &= 0 \qquad (2)\\
            2 \lvert v \rvert a (iv \wedge (\nu \lrcorner \w_0) - \lvert v \rvert \iota^* \w_0) &= 0 \qquad (3) \\
            -a \nu \lrcorner \w_0 + \lvert v \rvert b \nu \lrcorner \w_0 + iv b \lrcorner \iota^* \w_0 &= 0 \qquad (4)
        \end{cases}
    \end{align*}

If $a$ and $b$ are zero then $y=0$. If $a=0$ and $b$ non-zero, we get from $(1)$ that $\nu\lrcorner\w_0=0$. Replacing in $(2)$ and $(4)$, we get $\iota^*\w_0=0$. If $a$ non-zero and $b=0$, from $(2)$ and $(4)$ we get that $\iota^*\w_0=0$ and $\nu\lrcorner\w_0=0$ respectively.  In both cases we conclude that $\w_0=0$, hence $y = 0$, which implies that $\Phi$ is injective. Therefore, the problem \eqref{eq:BSNF2} is elliptic.
\end{proof}

\subsection{Discrete spectrum of BSN2}
Let us show that BSN2 has a discrete spectrum of eigenvalues.

\begin{thm}\label{thm:TheoremeGeneralBSNF2PourLaPreuve}
Let $(M^n, g)$ be a compact Riemannian manifold with a smooth boundary $\partial M$. The BSN2 problem \eqref{eq:BSNF2} for differential $p$-forms has a discrete spectrum consisting of an unbounded non-decreasing sequence of positive real eigenvalues with finite multiplicities $(\mathbf{l}_i)_{i \geq 1}$ and possibly $\mathbf{l}_0=0$. Its kernel is given by $H_A^p(M)$ (see \eqref{eq:Hap}).
\end{thm}
The proof of this theorem is similar to that of  \thref{thm:TheoremeGeneralBSNF1PourLaPreuve}.
\begin{proof} 

The bilinear forms \begin{equation*}
  ( \w, \w' )_{V} := \int_M \langle \Delta \w, \Delta \w' \rangle d\mu_g
\end{equation*} and
\begin{equation*}
    ( \w, \w' )_{W_2} := \int_{\partial M} \langle \iota^* \w, \iota^* \w' \rangle d\mu_g.
\end{equation*}  are inner products on $\check{Z}_1$ and $Z_2$ respectively since $( \w, \w' )_{W_1}$ and $( \w, \w' )_{V}$ are inner products on $Z_1$ and $\check{Z}_1$ (see  \lemref{lem:ps}). Note that for all $\w,\w'\in Z_2$ we have $(\w,\w')_{W_2}=(\w,\w')_{W_1}.$ \\
We denote by $W_2$ the completion of $Z_2$ with respect to $( \w, \w')_{W_2}$, and by $V_2$ the completion of $\check{Z}_2$ with respect to $( \w, \w' )_{V}$. \\ 
The norms $\lVert \cdot \rVert_{V}$ and $\lVert \cdot \rVert_{H^2(M)}$ are equivalent on $\check{Z}_2$ since they are on $\check{Z}_1$ and $\check{Z}_2\subset \check{Z}_1$ (see  \lemref{lem:equivalence}). Furthermore, for the same reason, there exists a positive constant $c$ such that $\lVert \cdot \rVert_{W_2}\leq c\lVert \cdot \rVert_{V}$ on $\check{Z}_2$ (see  \lemref{lem:W<V}). We can then say that $\check{Z}_2$ is dense in $V_2$ and $W_2$. \\
The inclusion map $i_{W_2}:\check{Z}_2\longrightarrow W_2$ can be extended to another continuous map 
\begin{eqnarray*}
I_2 = {I_1}_{|V_2} : V_2 & \longrightarrow & W_2 \\
\w & \longmapsto & \w
\end{eqnarray*}  The map $I_2$ is compact since $I_1$ is compact and $W_2$ is closed (see \lemref{lem:Icompact}). The map $I_2$ is injective since $I_1$ is injective (see \lemref{lem:i3injective}).

Let the operator $K_2:V_2\longrightarrow V_2$ such that \[K_2:=D_{V_2}^{-1}\circ ~^tI_2\circ D_{W_2}\circ I_2,\] where \[
\begin{array}{ccc@{\quad}c@{\quad}ccc}
D_{V_2} : V_2 & \longrightarrow & V'_2 &\text{and} & D_{W_2} : W_2 & \longrightarrow & W'_2 \\
\w & \longmapsto & (\cdot, \w)_V &  & \w & \longmapsto & (\cdot, \w)_{W_2}
\end{array}
\]
In addition, as in \eqref{eq:CharacterizationK1}, $K_2$ is characterized by \[ (K_2 \w, \w')_{V} = (\w, \w')_{W_2}. \]
The operator $ K_2 $ is compact, self-adjoint, and positive definite in $ V_2 $. Therefore, there exists a sequence of eigenvalues $(\chi_{i,2})_{i \geq 1}$, which are real, positive, and decreasing, going to $ 0 $ with finite-dimensional eigenspaces, according to \cite[p.431]{LaurentSchwartz}. The eigenforms $\w_i$ form a Hilbert basis of $ V_2 $. To conclude the proof, we show the following Lemma. 
\begin{lemma}
    A form $\w$ is a solution of BSN2 for $\mathbf{l}\in \mathbb{R}^*$ if and only if $K_2\w=\frac{1}{\mathbf{l}}\w.$ 
\end{lemma}
\begin{proof}
    Let $ \mathbf{l} \in \mathbb{R}^* $ such that $ \w $ is a solution of $BSN2$, integrating by parts \eqref{eq:IPP2} for $ \w' \in \check{Z}_2 $, we have:  \[
(\Delta \w, \Delta \w')_{L^2(M)} = \mathbf{l} (\iota^* \w, \iota^* \w')_{L^2(\partial M)} .
\]  Since $\check{Z}_2$ is dense in $W_2$, we have for all $\w'\in V_2$, $(\w, \w')_{V} = \mathbf{l} ( \w, \w')_{W_2}$. Then by definition of $K_2$ we get $(\w, \w')_{V} = \mathbf{l} (K_2 \w, \w')_{V}$ for all $\w'\in V_2.$ Hence $K_2\w=\frac{1}{\mathbf{l}}\w$, consequently $\w$ is an eigenform for $K_2$ associated to $\frac{1}{\mathbf{l}}=\chi$.

Conversely, let $\w_i$ be a $\chi$-eigenform in $V_2$ for $K_2$. Since $V_2\subset V_1,$ we have by \lemref{lem:solfaible} that $\Delta^2\w_i=0$ weakly on $M$, $\nu\lrcorner\w_i=0,\ \nu\lrcorner d\w_i=0$ and $\iota^*\delta\w_i=0$ on $\partial M$. It remains to show that $\nu\lrcorner\Delta d\w_i=-\mathbf{l}\iota^*\w_i$. For all $\w\in\check{Z}_2,$ we have by definition \begin{align}\label{eq:preuve}
\chi(\Delta\w_i,\Delta \w)_{L^2(M)}\notag &= \chi(\w_i,\w)_{V}\\ \notag
&= (K_2\w_i,\w)_{V} \\ \notag
&=(I_2(\w_i),I_2(\w))_{W_2} \\ \notag
&= (\w_i,\w)_{W_2} \\
&= (\iota^*\w_i,\iota^* \w)_{L^2(\partial M)}.
\end{align}
Then by integrating by parts \eqref{eq:IPP2}, for all $ \w_i\in V_2,\ \w \in {Z}_2 $, as in \lemref{lem:k1w=xw}, we get:  

\[
(\Delta \w_i, \Delta \w)_{L^2(M)} + ( \underbrace{\nu \lrcorner d \Delta \w_i}_{\in H^{-\frac{3}{2}}(\partial M)}, \underbrace{\iota^* \w}_{\in H^{\frac{3}{2}}(\partial M)})_{L^2(\partial M)} = 0.
\]
Using \eqref{eq:preuve}, we get
\[
\frac{1}{\chi} (\iota^* \w_i, \iota^* \w)_{L^2(\partial M)} + (\nu \lrcorner d \Delta \w_i, \iota^* \w)_{L^2(\partial M)} = 0.
\]
Finally we get
\[
\left( \frac{1}{\chi} \iota^* \w_i + \nu \lrcorner d \Delta \w_i, \iota^* \w \right)_{L^2(\partial M)} = 0.
\]
Moreover, it follows from \lemref{lem:Bilap1} that the map \begin{align*}
O_2:{Z}_2 &\longrightarrow \Omega^p(\partial M)\\
\w&\longmapsto \iota^*\w
\end{align*} is surjective since $O_1$ is surjective (see \lemref{lem:Osurjective}).
This implies that $  \nu \lrcorner d \Delta \w_i+\mathbf{l} \iota^* \w_i=0$ in $H^{-\frac{3}{2}}(\partial M).$ By the definition of $Z_2$, the restriction ${O_2}_{|\check{Z}_2}:\check{Z}_2\longrightarrow \Omega^p(M)\cap H_A^p(M)^{\perp_{L^2(\partial M)}}$ is also surjective. Hence, by \thref{theo:thm5.4}, $\w_i\in \Omega^p(M)$, therefore $\w_i$ is a solution of BSN2.

\end{proof}
Which concludes the proof of \thref{thm:TheoremeGeneralBSNF2PourLaPreuve}.
\end{proof}

\subsection{Variational characterization of eigenvalues}
To establish Kuttler-Sigillito inequalities, we will present in this section the variational characterizations associated with the eigenvalues of problem BSN2. The proofs of these characterizations are done in the same way as those of problem BSN1.


\begin{thm}\label{theo:BSN2VP1}
A variational characterization of the first strictly positive eigenvalue of problem \eqref{eq:BSNF2} is given by
\begin{equation}\label{eq:l1BSN2}
\mathbf{l}_{1,p} = \inf\left\{\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}\ \big|\ \w \in \check{H}_{N,2}^2(M), \ \iota^*\w \neq 0 \ \text{on}\ \partial M\right\}.
\end{equation}

\end{thm}

\begin{proof}
The proof is identical to that of  \thref{theo:BSN1VP1}.
\end{proof}

\begin{thm}\label{theo:BSN2VPk}
For any $k \in \mathbb{N}$, the following characterization of the $k^{\text{th}}$ strictly positive eigenvalue holds:
\begin{equation*}
\mathbf{l}_{k,p} = \inf_{\substack{\mathcal{V}_k \subset \check{H}_{N,2}^2(M)  \\ \dim (\mathcal{V}_k/(H_0^2(M) \cap \mathcal{V}_k) = k}}\ \sup_{\w \in \mathcal{V}_k \backslash H_0^2(M)}\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}}.
\end{equation*}
\end{thm}

\begin{proof}
The proof is identical to that of  \thref{theo:ell_k_3}.
\end{proof}



\section{Spectral properties of BSN3}
As we will see in \secref{sec:kuttler-sigillito}, BSN2 is enough to show Kuttler-Sigillito inequalities \eqref{eq:3èmePBmuksigma1<lk} and \eqref{eq:3èmePBmu1sigmak<lk} but not to show the rest of the inequalities of \thref{thm:3èmePBkuttlersigilitto1}. A new BSN3 is introduced with the aim of improving what was done using BSN2 and establishing the inequalities that remain.
\subsection{Formulation of the boundary problem}
In this section, we mainly use the same working method as in  \secref{sec:FormulationBSN2}. The goal is to obtain the following variational characterization:
\[
\textit{l}_{1,p} = \inf\left\{\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}\ |\ \w\in\check{H}^2_{N,1}(M) \right\},
\]
 i.e., removing the boundary condition $\iota^*\delta\w=0.$

To do this, we compute again the critical points of the following functional: $Q(\w) := \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}$ on $\check{H}^2_{N,1}(M)$. For all $\w, \w'$ satisfying the above conditions, we have $(\Delta\w, \Delta\w')_{L^2(M)} = \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}} (\iota^*\w, \iota^*\w')_{L^2(\partial M)}.$ Denoting $\textit{l} = \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}}$ and using integration by parts \eqref{eq:IPP2}, we obtain
\[
(\Delta^2\w, \w')_{L^2(M)} - (\nu\lrcorner d\Delta\w, \iota^*\w)_{L^2(\partial M)} - (\nu\lrcorner \Delta\w, \iota^*\delta\w)_{L^2(\partial M)} = \textit{l} (\iota^*\w, \iota^*\w')_{L^2(\partial M)}.
\]
It implies that
\[
(\Delta^2\w, \w')_{L^2(M)} = (\nu\lrcorner d\Delta\w + \textit{l}\ \iota^*\w, \iota^*\w')_{L^2(\partial M)} + (\nu\lrcorner \Delta\w, \iota^*\delta\w')_{L^2(\partial M)},
\]
for all $\w'$ such that $\nu\lrcorner \w'$ and $\nu\lrcorner d\w'$ vanish. By following the same steps as in  \secref{sec:FormulationBSN2}, we show that $\Delta^2\w = 0$ on $M$. Again by \lemref{lem:Bilap1} there exists $\w' \in {H}^2_{N,1}(M)$ such that 

\[\begin{cases}
\Delta^2 \w' = 0 & \text{on}\ M \\
  \nu\lrcorner \w' = 0 & \text{on } \partial M \\
 \nu\lrcorner d\w' = 0 & \text{on } \partial M \\
   \iota^*\delta\w'=\nu\lrcorner\Delta\w &  \text{on } \partial M \\
    \iota^*\w= \nu\lrcorner d\Delta\w + \textit{l}\ \iota^*\w  &  \text{on } \partial M.
\end{cases}\]

We conclude in the same way we did for BSN2. The critical points of $\mathcal{Q}$ are the eigenforms $\w$ for the following BSN3 problem:
\[
\begin{cases}
\Delta^2 \w = 0 & \text{on}\ M \\
  \nu\lrcorner \w = 0 & \text{on } \partial M \\
 \nu\lrcorner d\w = 0 & \text{on } \partial M \\
   \nu\lrcorner\Delta\w = 0 &  \text{on } \partial M \\
    \nu\lrcorner d\Delta\w + \textit{l}\ \iota^*\w = 0  &  \text{on } \partial M.
\end{cases}
\]

\subsection{Ellipticity of BSN3}\label{sec:BSN3elliptic}

\begin{thm}
    The BSN3 problem \eqref{eq:BSNF3} is elliptic in the sense of Shapiro-Lopatinskij.
\end{thm}

\begin{proof}
    Since its principal symbols are identical to those of the BSN1 \eqref{eq:BSNF1}, the problem BSN3 \eqref{eq:BSNF3} is also elliptic in the sense of Shapiro-Lopatinskij. 
\end{proof}
\subsection{Discrete spectrum of BSN3}

 \begin{thm}\label{thm:TheoremeGeneralBSNF3PourLaPreuve}\noindent Let $(M^n,g)$ be a compact Riemannian manifold with a smooth $\partial M$ and let $\nu$ be the unit inward normal vector to the boundary. Then the BSN3 \eqref{eq:BSNF3} for differential $p$-forms, has a discrete spectrum consisting of an unbounded non-decreasing sequence of positive real eigenvalues with finite multiplicities $(\textit{l}_i)_{i\geq0}$. Its kernel is given by $H_A^p(M)$ \eqref{eq:Hap}.
\end{thm}

\begin{lemma}\label{lem:Bilap2} The problem  
\begin{equation*}
(biLap_2) \begin{cases}\label{eq:bilap2}
    \Delta^2 \w &= f\ \ \qquad \text{on } M\\
    \nu \lrcorner \w &= \w_1 \qquad \text{on } \partial M \\
    \nu \lrcorner d \w &= \w_2\qquad  \text{on } \partial M \\
    \iota^*\w&= \w_3 \qquad \text{on } \partial M \\
    \nu \lrcorner \Delta \w &= \w_4 \qquad \text{on } \partial M.
\end{cases}
\end{equation*}
 admits a unique solution $\w$ for all $(f,\w_1,\w_2,\w_3,\w_4)\in H^{s-4}(M) \times H^{s-\frac{1}{2}}(\partial M)\times H^{s-\frac{3}{2}}(\partial M)\times H^{s-\frac{1}{2}}(\partial M)\times H^{s-\frac{3}{2}}(\partial M)$ where $s\geq 4$, in particular for $f=0,\ \w_1=0,\ \w_2=0,\ \iota^*\w = \w_3\perp_{L^2(\partial M)}H_A^p(M) $ and $ \nu \lrcorner \Delta \w = \w_4 $.\end{lemma} \begin{proof}
     Indeed, by \thref{theo:thm5.4}, the problem above admits a unique solution. It is elliptic since by doing the same calculations of principal symbols as in  \secref{sec:elliticiteBSNF1preuve}, we obtain that the corresponding map  
\[
\begin{aligned}
\Phi : \mathcal{M}^+_{\Delta^2,v} &\longrightarrow \bigoplus_{j=1}^4 E_j \\
y &\longmapsto \left( 
b \nu \lrcorner \omega_0,\,
(a - b \lvert v \rvert)\, \iota^* \omega_0 + i b\, \iota^* v \wedge (\nu \lrcorner \omega_0),\,
b\, \iota^* \omega_0,\,
2a \lvert v \rvert\, \nu \lrcorner \omega_0
\right)
\end{aligned}
\]


is an isomorphism.\\ The operator of this problem is injective since its kernel $\mathcal{N}$ is trivial, and this is shown by doing an integration by parts:
\begin{equation*}
\begin{split}
    & \int_M \langle \underbrace{\Delta^2 \w}_{0}, \w \rangle d\mu_g = \int_M \langle \Delta \w, \Delta \w \rangle d\mu_g \\
    & + \int_{\partial M} \Big( \langle \nu \lrcorner d \Delta \w, \underbrace{\iota^* \w}_{0} \rangle - \langle \iota^* \Delta \w, \underbrace{\nu \lrcorner d \w}_{0} \rangle + \langle \underbrace{\nu \lrcorner \Delta \w}_{0}, \iota^* \delta \w \rangle - \langle \iota^* \delta \Delta \w, \underbrace{\nu \lrcorner \w}_{0} \rangle \Big) d\mu_g.
\end{split}
\end{equation*} Thus, $\Delta \w = 0$ and since $\w_{|\partial M} = 0$ we get by \cite{ColetteAnne} that $\w = 0$. \\ To evaluate $\mathcal{N}^*$, we use  \thref{theo:thm5.4}, and we denote by $B_0\w=\nu\lrcorner d\w,B_1\w=\nu\lrcorner\w, B_2\w=\nu\lrcorner\Delta\w$ and $B_3\w=\iota^*\w$ and integrate by parts we get \begin{align*}
(\Delta^2 \w, \w')_{L^2(M)} &- (\w, \Delta^2 \w')_{L^2(M)} \\
&= (\nu \lrcorner d\Delta \w, \iota^* \w')_{L^2(\partial M)} - (\iota^* \w, \nu \lrcorner d\Delta \w')_{L^2(\partial M)} \\
&\quad - (\iota^* \delta \Delta \w, \nu \lrcorner \w')_{L^2(\partial M)} + (\nu \lrcorner \w, \iota^* \delta \Delta \w')_{L^2(\partial M)} \\
&\quad + (\nu \lrcorner \Delta \w, \iota^* \delta \w')_{L^2(\partial M)} - (\iota^* \delta \w, \nu \lrcorner \Delta \w')_{L^2(\partial M)} \\
&\quad - (\iota^* \Delta \w, \nu \lrcorner d \w')_{L^2(\partial M)} + (\nu \lrcorner d \w, \iota^* \Delta \w')_{L^2(\partial M)}. 
\end{align*}We note, based on the above, that $T_0\w=-\iota^*\Delta\w,T_1\w=-\iota^*\delta\Delta\w,T_2\w=-\iota^*\delta\w $ and $T_3\w=\nu\lrcorner d\Delta\w$ as well as $C_0\w=\iota^*\w, C_1\w=-\nu\lrcorner\w, C_2\w=-\nu\lrcorner\Delta\w$ and $C_3\w=-\nu\lrcorner d\w,$ which implies that $\mathcal{N}^*=0$.
 So by  \thref{theo:thm5.4} the map \begin{eqnarray*}
\mathcal{P}_{biLap_2}:{H^s}(M)&\longrightarrow & H^{s-4}(M) \oplus H^{s-\frac{1}{2}}(\partial M)\oplus H^{s-\frac{1}{2}}(\partial M)\oplus H^{s-\frac{3}{2}}(\partial M)\oplus H^{s-\frac{3}{2}}(\partial M)\\
  \left[\w\right]& \longmapsto & (\Delta^2\w,\nu\lrcorner\w,\nu\lrcorner d\w,\iota^*\w,\nu\lrcorner\Delta\w)  \notag 
\end{eqnarray*} is an isomorphism on its image that is given for all $s\geq 4$ by:
\[ \im(\mathcal{P}_{biLap_2}) =  H^{s-4}(M) \times H^{s-\frac{1}{2}}(\partial M)\times H^{s-\frac{3}{2}}(\partial M)\times H^{s-\frac{1}{2}}(\partial M)\times H^{s-\frac{3}{2}}(\partial M).\] In particular, by \thref{theo:thm5.4} $(biLap_2)$ admits a unique solution. \end{proof}


The proof of \thref{thm:TheoremeGeneralBSNF3PourLaPreuve} is done in a very similar way to that of both \thref{thm:TheoremeGeneralBSNF1PourLaPreuve} and \thref{thm:TheoremeGeneralBSNF2PourLaPreuve}.
\begin{proof}[Proof of  \thref{thm:TheoremeGeneralBSNF3PourLaPreuve}]
 We begin by defining the following spaces: 
\[
Z_3 := \{\w \in \Omega^p(M)\cap {H}_{N,3}^2(M) \ |\ \Delta^2\w = 0 \ \text{on}\ M\}\subset Z_1,
\]\[
\check{Z}_3 := \{\w \in Z_3\ |\ \w \perp_{L^2(\partial M)} H_A^p(M)\}\subset \check{Z}_1,
\] 
 \[
{H}_{N,3}^2(M) := \{\w \in H^2(M) \ | \ \nu\lrcorner\w = 0, \ \nu\lrcorner d\w = 0, \ \text{and} \ \nu\lrcorner\Delta\w = 0 \ \text{on} \ \partial M\}
\] and 
\[
\check{H}_{N,3}^2(M):=\{\w\in H^2(M)\ |\ \nu\lrcorner d\w=0,\ \nu\lrcorner \w=0,\ \nu\lrcorner\Delta\w=0\ \text{on} \ \partial M\ \text{and}\ \w\perp_{L^2(\partial M)}H_A^p(M)\}.
\]
The bilinear forms \begin{equation*}
  ( \w, \w' )_{V} := \int_M \langle \Delta \w, \Delta \w' \rangle d\mu_g
\end{equation*} and
\begin{equation*}
    ( \w, \w' )_{W_3} := \int_{\partial M} \langle \iota^* \w, \iota^* \w' \rangle d\mu_g.
\end{equation*}  are inner products on $\check{Z}_3$ and $Z_3$ respectively since $( \w, \w' )_{W_1}$ and $( \w, \w' )_{V}$ are inner products on $Z_1$ and $\check{Z}_1$ (see  \lemref{lem:ps}). 

We denote by $W_3$ the completion of $Z_3$ with respect to $( \w, \w')_{W_3}$, and by $V_3$ the completion of $\check{Z}_3$ with respect to $( \w, \w' )_{V}$.  

The norms $\lVert \cdot \rVert_{V}$ and $\lVert \cdot \rVert_{H^2(M)}$ are equivalent on $\check{Z}_3$ since they are on $\check{Z}_1$ and $\check{Z}_3\subset \check{Z}_1$ (see  \lemref{lem:equivalence}). Furthermore, for the same reason, there exists a positive constant $c$ such that $\lVert \cdot \rVert_{W_3}\leq c\lVert \cdot \rVert_{V}$ on $\check{Z}_3$ (see  \lemref{lem:W<V}). We can then say that $\check{Z}_3$ is dense in $V_3$ and $W_3$. \\
The inclusion map $i_{W_3}:\check{Z}_3\longrightarrow W_3$ can be extended to another continuous map 
\begin{eqnarray*}
I_3 = {I_1}_{|V_3} : V_3 & \longrightarrow & W_3 \\
\w & \longmapsto & \w
\end{eqnarray*}  The map $I_3$ is compact since $I_1$ is compact and $W_3$ is closed (see \lemref{lem:Icompact}). The map $I_3$ is injective since $I_1$ is injective (see \lemref{lem:i3injective}).

Let the operator $K_3:V_3\longrightarrow V_3$ such that \[K_3:=D_{V_3}^{-1}\circ ~^tI_3\circ D_{W_3}\circ I_3,\] where \[
\begin{array}{ccc@{\quad}c@{\quad}ccc}
D_{V_3} : V_3 & \longrightarrow & V'_3 &\text{and} & D_{W_3} : W_3 & \longrightarrow & W'_3 \\
\w & \longmapsto & (\cdot, \w)_V &  & \w & \longmapsto & (\cdot, \w)_{W_3}
\end{array}
\]
In addition, as in \eqref{eq:CharacterizationK1}, $K_3$ is characterized by \[ (K_3 \w, \w')_{V} = (\w, \w')_{W_3}. \]
The operator $ K_3 $ is compact, self-adjoint, and positive definite in $ V_3 $. Therefore, there exists a sequence of eigenvalues $(\chi_{i,3})_{i \geq 1}$, which are real, positive, and decreasing, going to $ 0 $ with finite-dimensional eigenspaces, according to \cite[p.431]{LaurentSchwartz}. The eigenforms $\w_i$ form a Hilbert basis of $ V_3 $. To conclude the proof, we show the following Lemma. 
\begin{lemma}
    A form $\w$ is a solution of BSN3 for $\textit{l}\in \mathbb{R}^*$ if and only if $K_3\w=\frac{1}{\textit{l}}\w.$ 
\end{lemma}
\begin{proof}
    Let $ \textit{l} \in \mathbb{R}^* $ such that $ \w $ is a solution of $BSN3$, integrating by parts \eqref{eq:IPP2} for $ \w' \in \check{Z}_3 $, we have:  \[
(\Delta \w, \Delta \w')_{L^2(M)} = \textit{l} (\iota^* \w, \iota^* \w')_{L^2(\partial M)} .
\]  Since $\check{Z}_3$ is dense in $W_3$, we have for all $\w'\in V_3$, $(\w, \w')_{V} = \textit{l} ( \w, \w')_{W_3}$. Then by definition of $K_3$ we get $(\w, \w')_{V} = \textit{l} (K_3 \w, \w')_{V}$ for all $\w'\in V_3.$ Hence $K_3\w=\frac{1}{\textit{l}}\w$, consequently $\w$ is an eigenform for $K_3$ associated to $\frac{1}{\textit{l}}=\chi$.

Conversely, let $\w_i$ be a $\chi$-eigenform in $V_3$ for $K_3$. Since $V_3\subset V_1,$ we have by \lemref{lem:solfaible} that $\Delta^2\w_i=0$ weakly on $M$, $\nu\lrcorner\w_i=0,\ \nu\lrcorner d\w_i=0$ and $\nu\lrcorner \Delta\w_i=0$ on $\partial M$. It remains to show that $\nu\lrcorner\Delta d\w_i=-\textit{l}\iota^*\w_i$. For all $\w\in\check{Z}_3,$ we have by definition \begin{align}\label{eq:preuve1}
\chi(\Delta\w_i,\Delta \w)_{L^2(M)}\notag &= \chi(\w_i,\w)_{V}\\ \notag
&= (K_3\w_i,\w)_{V} \\ \notag
&=(I_3(\w_i),I_3(\w))_{W_3} \\ \notag
&= (\w_i,\w)_{W_3} \\
&= (\iota^*\w_i,\iota^* \w)_{L^2(\partial M)}.
\end{align}
Then by integrating by parts \eqref{eq:IPP2}, for all $ \w_i\in V_3,\ \w \in {Z}_3 $, as in \lemref{lem:k1w=xw}, we get:  

\[
(\Delta \w_i, \Delta \w)_{L^2(M)} + ( \underbrace{\nu \lrcorner d \Delta \w_i}_{\in H^{-\frac{3}{2}}(\partial M)}, \underbrace{\iota^* \w}_{\in H^{\frac{3}{2}}(\partial M)})_{L^2(\partial M)} = 0.
\]
Using \eqref{eq:preuve1}, we get
\[
\frac{1}{\chi} (\iota^* \w_i, \iota^* \w)_{L^2(\partial M)} + (\nu \lrcorner d \Delta \w_i, \iota^* \w)_{L^2(\partial M)} = 0.
\]
Finally we get
\[
\left( \frac{1}{\chi} \iota^* \w_i + \nu \lrcorner d \Delta \w_i, \iota^* \w \right)_{L^2(\partial M)} = 0.
\]

Moreover, by \lemref{lem:Bilap2}, for all $\w_0\in H^{\frac{3}{2}}(\partial M),$ there exists $\w\in H^2(M)$ such that \begin{equation*}
\begin{cases}
    \Delta^2 \omega = 0 & \text{on } M, \\
    \nu \lrcorner \omega = 0 & \text{on } \partial M, \\
    \nu \lrcorner d\omega = 0 & \text{on } \partial M, \\
    \iota^* \omega = \omega_0 & \text{on } \partial M, \\
    \nu \lrcorner \Delta \omega = 0 & \text{on } \partial M.
\end{cases}
\end{equation*}

Therefore, the map \begin{align*}
O_3:{Z}_3 &\longrightarrow \Omega^p(\partial M)\\
\w&\longmapsto \iota^*\w
\end{align*} is surjective since $O_1$ is surjective (see \lemref{lem:Osurjective}). The map \begin{align*}
{O_3}_{|\check{Z}_3}:\check{Z}_3 &\longrightarrow \Omega^p(\partial M)\cap H_A^p(M)^{\perp_{L^2(\partial M)}}
\end{align*} is also surjective.
This implies that $  \nu \lrcorner d \Delta \w_i+\mathbf{l} \iota^* \w_i=0$ in $H^{-\frac{3}{2}}(\partial M).$ Hence, by \thref{theo:thm5.4}, $\w_i\in \Omega^p(M)$, therefore $\w_i$ is a solution of BSN3.

\end{proof}
Which concludes the proof of \thref{thm:TheoremeGeneralBSNF2PourLaPreuve}.
\end{proof}



\subsection{Variational characterization of eigenvalues}
In this section, we will provide the variational characterizations associated with the eigenvalues of BSN3, which will be used to establish the Kuttler-Sigillito inequalities of  \secref{sec:IntroKuttlerSigillito}.


\begin{thm}
A variational characterization of the first strictly positive eigenvalue of problem \eqref{eq:BSNF3} is given by
\begin{align}
\label{eq:l1BSN3}
\textit{l}_{1,p} &= \inf\left\{ \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}} \ |\ \w \in \check{H}_{N,3}^2(M) \ \text{and}\ \iota^*\w \neq 0 \ \text{on}\ \partial M \right\}.
\end{align}
It is a minimum, attained only by eigenforms of BSN3.
\end{thm}

\begin{proof}
    The proof of this theorem is done in the same way as the one of  \thref{theo:BSN1VP1}.
\end{proof}
Actually the condition $\nu\lrcorner\Delta\w$ can be dropped in \eqref{eq:l1BSN3}: we have the following stronger theorem.
\begin{thm}
A variational characterization of the first strictly positive eigenvalue of problem \eqref{eq:BSNF3} is given by
\begin{align}
\label{eq:l1BSN3WithoutNulrcornerDeltaw}
\textit{l}_{1,p}&= \inf\left\{ \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}} \ |\  \w\in \check{H}^2_{N,1}(M)\ \text{and}\  \iota^*\w \neq 0 \ \text{on}\ \partial M \right\}.
\end{align}

\end{thm}


\begin{proof}
    We recall that the operator $K_3:V_3\longrightarrow V_3$ is self-adjoint, compact with a discrete spectrum consisting of the eigenvalues $\frac{1}{\textit{l}_{i,p}}.$ Thus, 
\[
\frac{1}{\textit{l}_{1,p}}=\underset{\w\in V_3\backslash \{0\}}{\sup}\frac{(K_3\w,\w)_{V}}{\lVert \w\rVert^2_{V}}=\underset{\w\in V_3\backslash \{0\}}{\sup}\frac{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}{\lVert \Delta\w\rVert^2_{L^2(M)}}
\]
so that
\begin{align*}
\textit{l}_{1,p} &= \inf\left\{\frac{\lVert\Delta\w\rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}},\ \w\in V_3\right\} \\
&= \inf\left\{\frac{\lVert\Delta\w\rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}} \ |\  \w\in\Omega^p(M),\
\nu\lrcorner\w=0,\ \nu\lrcorner d\w=0,\ \nu\lrcorner\Delta\w=0\ \text{on}\ \partial M\ \text{and}\ \w\perp_{L^2(\partial M)}H_A^p(M)\right\}. 
\end{align*}
We want to remove the condition $\nu\lrcorner\Delta\w=0.$ To do so, we establish the following decomposition:
\[
\check{H}^2_{N,3}(M)=V_3\oplus_{\perp_{(\cdot,\cdot)_{V}}}H_0^1(M)\cap\check{H}^2_{N,3}(M).
\]
Note that the inner product $(\cdot,\cdot)_{V}$ is well-defined on $\check{H}_{N,3}^2(M)\subset\check{H}^2_{N,1}(M).$ Let $\w\in\check{Z}_3, \w'\in \check{H}_{N,3}^2(M)$, then by performing an integration by parts \eqref{eq:IPP2}, we obtain
\[
\int_M\langle \Delta\w , \Delta \w'\rangle  d\mu_g=- \int_{\partial M}  \langle \nu \lrcorner d \Delta\w, {\iota^* \w'}\rangle d\mu_g,
\]
so that for $\w'\in H_0^1(M)\cap\check{H}^2_{N,3}(M)$, we have $( \w,\w')_{V}=0$, thus $H_0^1(M)\cap\check{H}^2_{N,3}(M)\subset\check{Z}_3^\perp=V_3^\perp.$

Conversely, let $\w'\in V_3^\perp\subset\check{H}_{N,3}^2(M)$, then $(\w_i,\w')_{V}=0$ so that $(\nu\lrcorner d\Delta\w_i,\iota^*\w')_{L^2(\partial M)}=0$, thus $-\textit{l}_i(\iota^*\w_i,\iota^*\w')_{L^2(\partial M)}=0$, and consequently, $(\iota^*\w_i,\iota^*\w')_{L^2(\partial M)}=0.$ \\ The goal now is to show that if $\w'\in V_3^\perp\subset\check{H}^2_{N,3}(M)$ and satisfies
\begin{equation*}
\begin{cases}
    \nu\lrcorner d \w' = 0 & \text{on } \partial M \\
 \nu\lrcorner\w' = 0 & \text{on } \partial M\\
 \nu\lrcorner \Delta \w' = 0 & \text{on } \partial M ,
\end{cases}
\end{equation*}
then $\iota^*\w'=0.$

Now, the operator $\Delta^2$ with the boundary conditions of the problem \eqref{eq:pb} is an invertible operator and thus has a trivial kernel (see \lemref{lem:Bilap2}). Therefore, the problem
\begin{equation}\label{eq:pb}
\begin{cases}
    \Delta^2 \w = 0 & \text{on}\ M \\
    \nu\lrcorner d \w = 0 & \text{on } \partial M \\
 \nu\lrcorner\w = 0 & \text{on } \partial M\\
 \nu\lrcorner \Delta \w = 0 & \text{on } \partial M \\
  \iota^*\w = 0 &  \text{on } \partial M,
\end{cases}
\end{equation}
which is a particular case of $(biLap_2)$ \eqref{eq:bilap2} admits $\w=0$ as unique solution. We have shown in  \secref{sec:BSN3elliptic} that the operator $O_3:Z_3\longrightarrow \Omega^p(M)$ is surjective, so for every strictly positive $\epsilon$, there exists $\w\in \Omega^p(\partial M)$ such that $\lVert \iota^*\w'-\iota^*\w\rVert_{L^2(\partial M)}<\epsilon$. Therefore, there exists $\w_\epsilon\in\Omega^p(M)$ such that
\begin{equation*}
\begin{cases}
    \Delta^2 \w_\epsilon = 0 & \text{on}\ M \\

    \nu\lrcorner d \w_\epsilon = 0 & \text{on } \partial M \\
 \nu\lrcorner\w_\epsilon = 0 & \text{on } \partial M\\
 \nu\lrcorner \Delta \w_\epsilon = 0 & \text{on } \partial M\\
 \iota^*\w_\epsilon = \iota^*\w &  \text{on } \partial M,
\end{cases}
\end{equation*}
which implies that 
\begin{equation*}
\begin{cases}
    \Delta^2 \w_\epsilon = 0 & \text{on}\ M \\

    \nu\lrcorner d \w_\epsilon = 0 & \text{on } \partial M \\
 \nu\lrcorner\w_\epsilon = 0 & \text{on } \partial M\\
 \nu\lrcorner \Delta \w_\epsilon = 0 & \text{on } \partial M\\
 \lVert\iota^*\w_\epsilon-\iota^*\w'\rVert_{L^2(\partial M)} < \epsilon.
\end{cases}
\end{equation*}
We then decompose the $\w_\epsilon\in Z_3$ as follows: $\w_\epsilon=\check{\w}_\epsilon+\alpha_\epsilon$ such that $\check{\w}_\epsilon\in\check{Z}_3$ and $\alpha_\epsilon\in H_A^p(M)$.  
By the continuity of the trace map and having $\lVert\cdot\rVert_{V}\sim\lVert\cdot\rVert_{H^2(M)}$ (see the proof of  \thref{thm:TheoremeGeneralBSNF3PourLaPreuve}) we get the continuity of the following maps:
\[
\begin{array}{ccccc}
V_3 & \overset{}{\longrightarrow} & H^{\frac{3}{2}}(\partial M) & \overset{}{\longrightarrow} & L^2(\partial M) \\
\w & \longmapsto & \iota^*\w & \longmapsto & \iota^*\w 
\end{array}
\] Now given that $(\iota^*\w_i,\iota^*\w')_{L^2(\partial M)}=0$, we have by the continuity of the map above 
\[
(\iota^*\check{\w}_\epsilon,\iota^*\w')_{L^2(\partial M)}=\sum_i(\check{\w}_\epsilon,\w_i)_{V} (\iota^*\w_i,\iota^*\w')_{L^2(\partial M)}=0
.\] Moreover, since for $\alpha_\epsilon\in H_A^p(M)$ and $\w'\in \check{H}^2_{N,3}(M)$ we have $(\iota^*\alpha_\epsilon,\iota^*\w')_{L^2(\partial M)}=0,$
this implies that $(\iota^*{\w}_\epsilon,\iota^*\w')_{L^2(\partial M)}=0$.
Letting $\epsilon$ tend to $0$, we obtain $\lVert\iota^*\w'\rVert^2_{L^2(\partial M)}=0$, hence $\iota^*\w'=0$. Since we already have $\nu\lrcorner\w'=0$, it follows that $\w'_{|\partial M}=0$, so $\w'\in H_0^1(M)$. Finally, we conclude that  
\[
\check{H}^2_{N,3}(M)=V_3\oplus_{\perp_{(\cdot,\cdot)_{V}}}H_0^1(M)\cap \check{H}^2_{N,3}(M).
\]
Let us now show that the infimum in \eqref{eq:l1BSN3WithoutNulrcornerDeltaw} exists and is a minimum. We know that  
\[
\begin{aligned}
\check{H}^2_{N,1}(M) = \Big\{ \omega \in H^2(M) \ |\, 
& \nu \lrcorner \omega = 0, \nu \lrcorner d\omega = 0 \text{ on } \partial M, \omega \perp_{L^2(\partial M)} H_A^2(M) \Big\}\\
&= \check{H}_{N,3}^2(M) \oplus \left( \check{H}_{N,3}^2(M) \right)^{\perp_{V}}.
\end{aligned}
\]

Since $\lVert \cdot \rVert_{V} \sim \lVert \cdot \rVert_{H^2(M)}$ on $\check{H}^2_{N,1}(M)$ and we have $\lVert \cdot \rVert_{W_3} \leq \lVert \cdot \rVert_{W_1} \leq c \lVert \cdot \rVert_{H^\frac{3}{2}(M)}$ on $Z_1$ and so on $Z_3$, and the embedding $H^2(M) \hookrightarrow H^\frac{3}{2}(M)$ is compact, thus, the map  
\begin{eqnarray*}
\check{H}^2_{N,1}(M)\setminus\{0\}& \longrightarrow & \mathbb{R} \\
  \w & \longmapsto & \frac{\lVert\w\rVert^2_{W_3}}{\lVert\w\rVert^2_{V}}  \notag 
\end{eqnarray*}
admits a maximum on $\overline{\mathcal{B}}_1^{\check{H}^2_{N,1}(M)}(0)$. That is, there exists $\hat{\w}\in \mathcal{B}_1\subset \check{H}^2_{N,1}(M)$ such that 
$\frac{\lVert\hat{\w}\rVert^2_{W_3}}{\lVert{\w}\rVert^2_{V}} = \sup \left\{ \frac{\lVert\hat{\w}\rVert^2_{W_3}}{\lVert{\w}\rVert^2_{V}} \ \text{on } \mathcal{B}_1 \right\}.$


To conclude, consider the following functional: $Q(\w) := \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}}$ and let $\w \in \check{H}^2_{N,3}(M)$ such that $\w = u + v$ where $u \in V_3$ and $v \in H_0^1(M)$. Given that $\iota^*v\in H_0^1(M)$, we have then:  
\[
Q(\w) = \frac{\lVert \Delta u + \Delta v \rVert^2_{L^2(M)}}{\lVert \iota^* u \rVert^2_{L^2(\partial M)}} = \frac{\lVert u + v \rVert^2_{V}}{\lVert \iota^* u \rVert^2_{L^2(\partial M)}} = \frac{\lVert u \rVert^2_{V} + \lVert v \rVert^2_{V}}{\lVert \iota^* u \rVert^2_{L^2(\partial M)}} \geq \frac{\lVert u \rVert^2_{V}}{\lVert \iota^* u \rVert^2_{L^2(\partial M)}}.
\] So we can conclude that
\[
\inf \{Q(\w) \mid \w \in V_3\} = \textit{l}_{1,p} = \inf \{Q(\w) \mid \w \in \check{H}^2_{N,3}(M)\}
\]
is attained. \\
Next, let $\w\in\check{H}^2_{N,1}(M)$ be such that $\w = u' + v'$ where $u' \in \check{H}^2_{N,3}(M)$ and $v' \in (\check{H}^2_{N,3}(M))^{\perp_{V}}$. Then,  
\[
Q(\w) = \frac{\lVert \Delta u' + \Delta v' \rVert^2_{L^2(M)}}{\lVert \iota^* u' + \iota^* v' \rVert^2_{L^2(\partial M)}} = \frac{\lVert \Delta u' \rVert^2_{L^2(M)} + \lVert \Delta v' \rVert^2_{L^2(M)}}{\lVert \iota^* u' \rVert^2_{L^2(\partial M)} + \lVert \iota^* v' \rVert^2_{L^2(\partial M)}},
\] because of:  
\[
\lVert \iota^* u' + \iota^* v' \rVert^2_{L^2(\partial M)} = \lVert \iota^* u' \rVert^2_{L^2(\partial M)} + \lVert \iota^* v' \rVert^2_{L^2(\partial M)} + 2 \int_{\partial M} \langle \iota^* u', \iota^* v' \rangle d\mu_g.
\]
It is enough to show that  
\[
\int_{\partial M} \langle \iota^* u', \iota^* v' \rangle d\mu_g = 0 \quad \text{for} \quad u' \in V_3,
\]
because it is obvious for $u' \in H_0^1(M)$. We decompose $u' \in V_3$ as an orthogonal sum over the eigenforms of $u' = \sum_{i \in I} \alpha_i \textit{l}_i \w_i$, where $\w_i$ is an $\textit{l}_i$-eigenform. Doing an integration by parts and using the fact that $\iota^*$ is continuous on $V_3$, we get  
\[
\int_{\partial M} \langle \iota^* u', \iota^* v' \rangle d\mu_g = \sum_{i \in I} \alpha_i \int_{\partial M} \langle \ell_1 \iota^* \w_i, \iota^* v' \rangle d\mu_g.
\]For a fixed $i\in I$, we have \begin{align*}
\int_{\partial M} \langle \textit{l}_{i,p} \iota^*\w_i,\iota^*v' \rangle d\mu_g
&= -\int_{\partial M} \langle \nu \lrcorner d\Delta \w_i,\iota^*v' \rangle d\mu_g \\
&= \int_M \underbrace{\langle \Delta \w_i, \Delta v' \rangle}_{0} d\mu_g+ \int_M \langle \underbrace{\Delta^2 \w_i}_{0}, v' \rangle d\mu_g \\
&\quad + \int_{\partial M} \langle \underbrace{\nu \lrcorner \Delta \w_i}_{0}, \iota^* \delta v' \rangle d\mu_g - \int_{\partial M} \langle \iota^* \delta \w_i, \underbrace{\nu \lrcorner v'}_{0} \rangle d\mu_g=0.
\end{align*} Thus $\int_{\partial M} \langle \iota^* u', \iota^* v' \rangle d\mu_g = 0$. Let us next show that the closure of $\iota^*V_3$ is equal to $\check{L}^2(\partial M)=L^2(\partial M)\cap {H_A^p}^\perp(M).$
Hence, by \lemref{lem:Bilap2}, $(\check{H}_{N,3}^2(M))^{\perp_{\check{H}^2_{N,1}(M)}} \subset \{\w \in \check{H}^2_{N,1}(M),\ \iota^* \w = 0\}$ and thus $Q(\w) \geq Q(u')$. Finally,  
\[
\inf \{ Q(\w), \ \w \in \check{H}^2_{N,1}(M) \} = \inf \{ Q(\w), \ \w \in V_3 \}.
\]
This completes the proof.
\end{proof}

\begin{thm}\label{theo:lk}
For all $ k \in \mathbb{N} $, we have the following characterization of the $ k^{\text{th}} $ positive eigenvalue:
    \begin{equation}\label{eq:lkBSN3}
  \textit{l}_{k,p} = \inf_{\substack{\mathcal{V}_k \subset \check{H}_{N,1}^2(M)  \\ \dim (\mathcal{V}_k / (H_0^1(M) \cap \mathcal{V}_k)) = k}} \underset{\w \in \mathcal{V}_k \backslash H_0^1(M)}{\sup} \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}}.  
    \end{equation}

\end{thm} 

\begin{proof}
    The proof is done in the same way of the one of  \thref{theo:ell_k_3}.
\end{proof}

\begin{thm}\label{thm:l'minimumtheorem}
Let us define
\begin{align*}
\textit{l}^{\ '}_{1,p} &:= \inf\left\{ \frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert \w \rVert^2_{L^2( M)}} \ |\  \w\in\Omega^p(M),\ \Delta \w = 0\ \text{on}\ M, \ \nu \lrcorner \w = 0\ \text{on}\ \partial M \ \text{and} \ \w \perp_{L^2(M)} H_A^p(M) \right\}
\end{align*}and \begin{equation}\label{eq:lTilde<l}
    \tilde{\textit{l}}_{1,p}:=\inf\left\{ \frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert \w\rVert^2_{L^2( M)}} \ |\ \w\in\Omega^p(M),\  \Delta\w=0\ \text{on}\ M, \ \nu\lrcorner\w=0\ \text{on}\ \partial M\ \text{and} \ \w\perp_{L^2(\partial M)}H_A^p(M) \right\}.
\end{equation} We have then $\textit{l}^{\ '}_{1,p}=\textit{l}_{1,p}=\tilde{\textit{l}}_{1,p}$.
\end{thm}
 \begin{lemma}
       The characterizations $\textit{l}^{\ '}_{1,p}$ and $\tilde{\textit{l}}_{1,p}$ given in  \thref{thm:l'minimumtheorem} are positive minima. 

 \end{lemma}
\begin{proof}
    The proof is an adaptation of \propref{prop:l'minimum}, using the BSN3 adapted boundary conditions.
\end{proof}
\begin{proof}[Proof of  \thref{thm:l'minimumtheorem}]
     We need to show that $\textit{l}^{\ '}_{1,p}=\textit{l}_{1,p}$. Let $\w$ be an $\textit{l}_1$-eigenform in $\check{Z}_3$. By taking $\lVert\iota^*\w\rVert_{L^2(\partial M)}=1$ in \eqref{eq:l1BSN3}, we obtain $\lVert \Delta\w\rVert_{L^2(M)}^2=\textit{l}_1.$ Let $\Delta\w=\hat{\w}$, then we have the following elliptic problem which is a particular case of \eqref{eq:SteklovFormeGénéraleCorrigée}
\begin{equation}\label{eq:pbpreuve}
\begin{cases}
    \Delta \hat{\w} = 0 & \text{on } M \\
    \nu\lrcorner d \hat{\w} = -\textit{l}_1\iota^*\w & \text{on } \partial M \\
 \nu\lrcorner\hat{\w} = 0 & \text{on } \partial M.
\end{cases}
\end{equation} 
By \lemref{lm:SteklovFormeGénéraleCorrigée} there exists a solution $\hat{\w}\in \Omega^p(M)$, we denote $\hat{\w}'=\proj_{\perp_{L^2(\partial M)}}^{H_A^p(M)}(\hat{\w})$.
%Let $\hat{\w}\in \Omega^p(M)$ be a solution of problem \eqref{eq:pbpreuve} and $\w\in Z_3$.
%Since the operator $\Delta$ with these boundary conditions
%\begin{equation*}
%\begin{cases}
  %  \Delta {\bar{\w}} = \w_1 & \text{on } M \\
 %   \nu\lrcorner {\bar{\w}} = \w_2 & \text{on } \partial M \\
  %  \iota^* {\bar{\w}}=\w_3 & \text{on } \partial M \\
 %\nu\lrcorner d {\bar{\w}} = \w_4 & \text{on } \partial M.
%\end{cases}
%\end{equation*} 
 %is injective, there exists $\hat{\w}_1\in H_A^p(M)$ such that $\iota^*\hat{\w}_1:=\proj_{\perp_{L^2(\partial M)}}^{H_A^p(M)}(\hat{\w})\in H_A^p(M),$ and satisfying the following conditions: $\Delta\hat{\w}_1=0$, $\nu\lrcorner\hat{\w}_1=0$, $\nu\lrcorner d\hat{\w}_1=0$ and $\iota^*\hat{\w}_1=\proj_{\perp_{L^2(\partial M)}}^{H_A^p(M)}(\hat{\w}).$ We also define $\hat{\w}_2:=\hat{\w}-\hat{\w}_1$. It is a solution of \eqref{eq:pbpreuve} such that $\hat{\w}_2\perp_{L^2(\partial M)} H_A^p(M).$ 
 Using integration by parts \eqref{eq:IPP1} since $\w$ is an $\textit{l}_1$-eigenform $(\w\in\check{Z}_3)$, we obtain 
\[
\int_M\langle\hat{\w}',\Delta\w\rangle d\mu_g+\int_{\partial M}\langle\nu\lrcorner d\hat{\w}',\iota^*\w\rangle d\mu_g=0.
\]

Thus,
\[
\int_M \langle \hat{\w}', \Delta \w \rangle \, d\mu_g - \textit{l}_1 \underbrace{\int_{\partial M} \langle \iota^* \w, \iota^* \w \rangle \, d\mu_g}_{1} = 0.
\]
By Cauchy-Shwarz inequality, we have
\[
\lVert\hat{\w}'\rVert_{L^2(M)}\cdot \underbrace{\lVert \Delta\w\rVert_{L^2(M)}}_{{\textit{l}_1}^{\frac{1}{2}}}\geq \int_M\langle\hat{\w}',\Delta\w\rangle=\textit{l}_1,
\]
so $\textit{l}_1\leq \lVert\hat{\w}'\rVert_{L^2(M)}^2.$ 

Therefore,
\[
\frac{{\lVert\nu\lrcorner d\hat{\w}'\rVert}_{L^2(M)}^2}{{\lVert\hat{\w}'\rVert}_{L^2(M)}^2}=\textit{l}_1^2\frac{\lVert\iota^*\w\rVert^2_{L^2(\partial M)}}{\lVert\hat{\w}'\rVert^2_{L^2(M)}}\leq \textit{l}_1^2\frac{\lVert\iota^*\w\rVert^2_{L^2(\partial M)}}{\textit{l}_1}=\textit{l}_1.
\] Since \[\frac{\lVert \nu\lrcorner d\hat{\w} \rVert^2_{L^2(\partial M)}}{\lVert  {\hat{\w}}\rVert^2_{L^2( M)}}\leq \frac{\lVert \nu\lrcorner d\hat{\w}' \rVert^2_{L^2(\partial M)}}{\lVert  {\hat{\w}'}\rVert^2_{L^2( M)}}\leq \textit{l}_1\] we have then
\begin{equation*}
    \tilde{\textit{l}_1}\leq \textit{l}_1
\end{equation*}
and 
\[
\inf\left\{ \frac{\lVert \nu\lrcorner d {\hat{\w}} \rVert^2_{L^2(\partial M)}}{\lVert  {\hat{\w}}\rVert^2_{L^2( M)}} \ |\  \Delta\w=0\ \text{on}\ M, \ \nu\lrcorner\w=0,\ \text{on}\ \partial M\ \text{and} \ \w\perp_{L^2( M)}H_A^p(M) \right\}\leq \textit{l}_1.
\] Before concluding the proof, we establish the following lemma:

\begin{lemma}
    Let $\hat{\w}=\Delta\w$ where $\w$ is an $\textit{l}_1$-eigenform for BSN3, then $\hat{\w}\perp_{L^2(M)}H_A^p(M).$
\end{lemma}

\begin{proof}
Let $\hat{\w}=\Delta\w$ where $\w$ is an $\textit{l}_1$-eigenform for BSN3 and $\alpha\in H_A^p(M)$. From \eqref{eq:IPP2}, we obtain 
\[
\int_M\langle \hat{\w},\alpha\rangle d\mu_g=\int_M \langle \Delta\w,\alpha\rangle d\mu_g=-\textit{l}_1\int_{\partial M}\langle\iota^*\w,\iota^*\alpha\rangle d\mu_g=0.
\] 
\end{proof}

Returning to the proof, conversely, let $\w\in\Omega^p(M)\backslash\{0\}$ such that $\w\perp_{L^2(M)}H_A^p(M),$ $\Delta\w=0$ on $M$, $\nu\lrcorner\w=0$ on $\partial M$ and $\lVert\nu\lrcorner d\w\rVert^2_{L^2(M)}=\textit{l}^{\ '}_1\lVert\w\rVert^2_{L^2(M)}$ where $\textit{l}^{\ '}_1$ is a positive minimum. Let $\hat{\w}$ be a solution of the problem
\begin{equation*}
\begin{cases}
    \Delta \hat{\w} = \w & \text{on } M \\
    \nu\lrcorner d \hat{\w} = 0 & \text{on } \partial M \\
 \nu\lrcorner\hat{\w} = 0 & \text{on } \partial M,
\end{cases}
\end{equation*} given by \lemref{lm:SteklovFormeGénéraleCorrigée}.


 Again from an integration by parts \eqref{eq:IPP1}, we have 
\[
\lVert\w\rVert^2_{L^2(M)} = \int_M\langle\Delta\hat{\w},\w\rangle d\mu_g = -\int_{\partial M}\langle\iota^*\hat{\w},\nu\lrcorner d\w\rangle d\mu_g,
\]
and using the Cauchy-Schwarz inequality, we obtain
\[
\lVert\w\rVert^2_{L^2(M)} \leq \lVert\iota^*\hat{\w}\rVert_{L^2(\partial M)}(\textit{l}^{\ '}_1)^{\frac{1}{2}}\lVert\w\rVert_{L^2(M)}.
\]
Thus,
\[
\lVert\w\rVert_{L^2(M)} \leq \lVert\iota^*\hat{\w}\rVert_{L^2(\partial M)}(\textit{l}^{\ '}_1)^{\frac{1}{2}},
\]
so
\[
\textit{l}_1 \leq \frac{\lVert\Delta\hat{\w}\rVert^2_{L^2(M)}}{\lVert\iota^*\hat{\w}\rVert^2_{L^2(\partial M)}} \leq \textit{l}^{\ '}_1,
\]
which implies that $\textit{l}_1 \leq \textit{l}^{\ '}_1$, thus we obtain the equality.

\end{proof}




\section{Spectral inequalities for BSN2 and BSN3}\label{sec:kuttler-sigillito}
After having stated the three BSN problems and given the characterization of their eigenvalues, we will now present a generalization of the Kuttler-Sigillito inequalities \cite{hassannezhadETsiffert,Kuttler&Sigillito} on differential forms.

\begin{lemma}\label{lem:l<l<l}
   Using the notations defined previously, we have the following inequalities:
    \[
    \ell_{k,p} \leq \textit{l}_{k,p} \leq \mathbf{l}_{k,p}.
    \]
\end{lemma}

\begin{proof}
    For all $k\geq 1$, it follows immediately from  \thref{theo:ell_k_3}, \thref{theo:BSN2VPk} and \thref{theo:lk}.
\end{proof}
\begin{thm}\label{thm:3èmePBkuttlersigilitto1PourLaPreuve}
    Let $(M^n,g)$ be a compact Riemannian manifold with smooth boundary $\partial M$. The following inequality holds between the first non-zero eigenvalues of the Steklov, Neumann, BSN2 and BSN3 problems on differential forms:
    \begin{equation*}
    \mu_1\sigma_1<\textit{l}_1\leq\mathbf{l}_1.
    \end{equation*}
\end{thm}
\begin{proof}
    Using the following variational characterizations \eqref{eq:vp1NeumannAbsolueFormeAlternative}, \eqref{eq:sigma1formesSteklov}, and \eqref{eq:l1BSN3}, we obtain:
    \begin{align*}
    \mu_1 \sigma_1 &=\inf_{\substack{\w \notin H_A^p(M) \\ \nu \lrcorner \w = 0 \\ \nu \lrcorner d\w = 0}}
    \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)} }
    \times \inf_{\substack{ \nu \lrcorner \w = 0 \\ \w \perp_{L^2(\partial M)} H_A^p(M) }}
    \frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}} \\
    &\leq \inf_{\substack{ \nu \lrcorner \w = 0 \\ \nu \lrcorner d\w = 0\\ \w \perp_{L^2(\partial M)}H_A^p(M)}}
    \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)} }
    \times\inf_{\substack{ \nu \lrcorner \w = 0 \\ \nu \lrcorner d\w = 0\\ \w \perp_{L^2(\partial M)}H_A^p(M) }}
    \frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}}
    \\
    &\leq \inf_{\substack{\nu \lrcorner \w = 0 \\ \nu \lrcorner d\w = 0\\ \w \perp_{L^2(\partial M)}H_A^p(M)}}
    \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}} =\textit{l}_1\leq \mathbf{l}_1.
    \end{align*} We then have the inequality in the broad sense. To show that it is strict, we prove the following lemma:
    \begin{lemma}\label{lem:mu1sigma1<l1stricte}
  If $\mu_1\sigma_1=\textit{l}_1$, then there exists $\w$ an $\textit{l}_1$-eigenform for problem \eqref{eq:BSNF3} such that $\w$ is also a $\sigma_1$-eigenform for Steklov problem \eqref{eq:steklovFormes} and $\w - \projection_{L^2(M)}^{H_A^p(M)}(\w)$ is a $\mu_1$-eigenform for Neumann problem \eqref{eq:neumannFormesAbsolue}.
\end{lemma}
\begin{proof}
   Let $\w\in \check{H}_{N,3}^2(M)$ be an $\textit{l}_1$-eigenform for BSN3 $\eqref{eq:BSNF3}$. We know that  

\[
\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}}\geq \sigma_1
\]

and the quotient  

\[
\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)} }
\]

is invariant by translation by an element of $H_A^p(M)$. Therefore, for $\Tilde{\w}=\w-\projection_{L^2(M)}^{H_A^p(M)}(\w)$, we have  

\[
\frac{\lVert \Delta \Tilde{\w}\rVert^2_{L^2(M)}}{\lVert d\Tilde{\w} \rVert^2_{L^2(M)} + \lVert \delta \Tilde{\w} \rVert^2_{L^2(M)} }=\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)} }\geq\mu_1
\]

which implies that  

\[
\mu_1\sigma_1\leq \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)} }\times \frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}}=\textit{l}_1=\mu_1\sigma_1.
\]

Thus,  

\[
\mu_1=\frac{\lVert \Delta \Tilde{\w}\rVert^2_{L^2(M)}}{\lVert d\Tilde{\w} \rVert^2_{L^2(M)} + \lVert \delta \Tilde{\w} \rVert^2_{L^2(M)} }=\frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)} }
\]

and  

\[
\sigma_1=\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}}.
\]

Hence, $\Tilde{\w}$ and $\w$ are solutions of the following problems:  
\begin{equation*}
\begin{aligned}
\begin{cases}
    \Delta \Tilde{\w} =\mu_1 \Tilde{\w} & \text{on } M \\
    \nu\lrcorner\Tilde{\w} = 0 & \text{on } \partial M\\
    \nu\lrcorner d\Tilde{\w} = 0 & \text{on } \partial M
\end{cases}
\quad & ; \quad
\begin{cases}
    \Delta^2\w=0 & \text{on } M\\
    \nu\lrcorner\w = 0 & \text{on } \partial M\\
    \nu\lrcorner d \w= 0 & \text{on } \partial M \\
    \nu\lrcorner\Delta\w= 0 & \text{on } \partial M\\
    \nu\lrcorner d\Delta\w+\textit{l}_1\iota^*\w=0  & \text{on } \partial M
\end{cases}
\quad & ; \quad
\begin{cases}
    \Delta {\w} = 0 & \text{on } M \\
    -\nu\lrcorner d\w=\sigma_1\iota^* {\w} & \text{on } \partial M\\
    \nu\lrcorner{\w}=0 & \text{on } \partial M.
\end{cases}
\end{aligned}
\end{equation*}

\end{proof}

Back to the proof of  \thref{thm:3èmePBkuttlersigilitto1PourLaPreuve}. Since $\nu\lrcorner d\w=0$, it follows that $\iota^*\w$ is zero due to the conditions of the Steklov problem. Moreover, as $\nu\lrcorner\w=0$, we get that $\w_{|\partial M}=0$, which implies together with $\Delta\w=0$ that $\w=0$ by \cite{ColetteAnne}. This is a contradiction, because $\w$ is an eigenform and cannot be zero. Consequently, the inequality is strict. Now using  \lemref{lem:l<l<l} we get $\mu_1\sigma_1<\textit{l}_1\leq\mathbf{l}_1.$ 

\end{proof}
The following theorem is a generalization of  \thref{thm:3èmePBkuttlersigilitto1PourLaPreuve} that is given in \cite[Theorem 1.1]{hassannezhadETsiffert} and \cite[Inequality I]{Kuttler&Sigillito}.
\begin{thm}
    Let $(M^n,g)$ be a compact Riemannian manifold with a smooth boundary $\partial M.$ The following inequalities hold for $k\geq 2$, between the eigenvalues of the Steklov, Neumann, BSN2 and BSN3 problems for differential forms:
    \begin{equation}\label{eq:3èmePBmuksigma1<lkPourLaPreuve}
    \mu_k \sigma_1 \leq \textit{l}_k\leq \mathbf{l}_k,
    \end{equation}
    and
    \begin{equation}\label{eq:3èmePBmu1sigmak<lkPourLaPreuve}
    \mu_1 \sigma_k \leq \textit{l}_k\leq \mathbf{l}_k.
    \end{equation}
\end{thm}

\begin{proof}
    We begin by proving \eqref{eq:3èmePBmuksigma1<lkPourLaPreuve}. Let $\mathcal{V}=\spann(\w_1,\cdots,\w_k)$, where the $\w_i$ are $\textit{l}_i$-eigenforms, note that $\mathcal{V}$ has dimension $k$. Let $\Tilde{\mathcal{V}}=H_A^p(M)\oplus \mathcal{V}$ such that $\dim\Tilde{\mathcal{V}}=k+\dim H_A^p(M)$. For all $\w\in \mathcal{V}$, we have $\w\perp_{L^2(M)} H_A^p(M)$. Since $\w$ satisfies the boundary conditions of the Neumann problem, we can use the characterization \eqref{eq:vp1AlternativeNeumannAbsolueForme1}, and deduce that
\begin{align*}
\mu_k & \leq \sup_{\substack{\w \in \Tilde{\mathcal{V}}}} \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}} \\
& = \sup_{\substack{\w \in \mathcal{V}}} \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}} \times \frac{\lVert \w \rVert^2_{L^2(\partial M)}}{\lVert \w \rVert^2_{L^2(\partial M)}} \\
& \leq \textit{l}_k \sup_{\substack{\w \in \mathcal{V}}} \frac{\lVert \w \rVert^2_{L^2(\partial M)}}{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}} \\
& = \textit{l}_k\left(\inf_{\substack{\w \in \mathcal{V}}} \frac{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}}\right)^{-1} \\
& \leq \frac{\textit{l}_k}{\sigma_1},
\end{align*}
from which we deduce using  \lemref{lem:l<l<l} that $\mu_k\sigma_1\leq \textit{l}_k\leq\mathbf{l}_k.$\\
Let us next show \eqref{eq:3èmePBmu1sigmak<lkPourLaPreuve}. Using the same definitions above of $\mathcal{V}$ and $\Tilde{\mathcal{V}}$, we have \begin{align*}
\sigma_k & \leq \sup_{\substack{\w \in \mathcal{V}}} \frac{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \w \rVert^2_{L^2(\partial M)}} \\
& = \sup_{\substack{{\Tilde{\w}} \in \Tilde{\mathcal{V}} \\ \Tilde{\w}_{|\partial M} \neq 0}} \frac{\lVert d \Tilde{\w} \rVert^2_{L^2(M)} + \lVert \delta \Tilde{\w} \rVert^2_{L^2(M)}}{\lVert \iota^* \tilde{\w} \rVert^2_{L^2(\partial M)}} \\
& \leq \sup_{\substack{\w \in \mathcal{V} \\ \w_{|\partial M} \neq 0}} \frac{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \iota^* \w \rVert^2_{L^2(\partial M)}} \times \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \Delta \w \rVert^2_{L^2(M)}} \\
& \leq \textit{l}_k \sup_{\substack{\w \in \mathcal{V}}} \frac{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}{\lVert \Delta \w \rVert^2_{L^2(M)}} \\
& = \textit{l}_k \left(\inf_{\substack{\w \in \mathcal{V}}} \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert d \w \rVert^2_{L^2(M)} + \lVert \delta \w \rVert^2_{L^2(M)}}\right)^{-1} \\
& \leq \frac{\textit{l}_k}{\mu_1},
\end{align*}
we conclude that $\mu_1\sigma_k\leq \textit{l}_k\leq\mathbf{l}_k$ using  \lemref{lem:l<l<l}.
\end{proof}

\begin{remark}
    Unlike the case where $ k=1 $, the generalized inequalities may not be strict because having
    \[
    \textit{l}_{k,p}=\underset{\w\in \mathcal{V}_k/ \mathcal{V}_k\cap H_0^2(M)}{\sup}\ \frac{\lVert \Delta \w \rVert^2_{L^2(M)}}{\lVert \iota^*\w\rVert^2_{L^2(\partial M)}}
    \]
    for $\mathcal{V}_k \subset \check{H}_{N,3}^2(M)$ and $\dim(\mathcal{V}_k/\mathcal{V}_k \cap H_0^2)=k$, does not imply that $\mathcal{V}=\spann\{\w_1,\cdots,\w_k\}$.
\end{remark}


The following theorem is a generalization of \cite[Inequality II]{Kuttler&Sigillito}.
\begin{thm}\label{thm:proofQSigma<l}
    Let $(M^n, g)$ be a compact Riemannian manifold with smooth boundary $\partial M$. The following inequality holds between the eigenvalues of the Steklov, BSD, BSN2 and BSN3 problems for differential forms:
    \begin{equation}\label{eq:q1sigma1<l1PourLaPreuve}
    q_1 \sigma_1^2 <\textit{l}_1\leq\mathbf{l}_1.
    \end{equation}
\end{thm}

\begin{proof}
 Using the characterizations \eqref{eq:sigma1formesSteklov} and \eqref{eq:sigma1formeOrthHAP} of the classical Steklov problem, we have:

\[
\sigma^2_1 \leq \inf_{\substack{\nu \lrcorner \w = 0 \\  \w\perp_{L^2(\partial M)}H_A^p(M)}}
\frac{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta\w \rVert^2_{L^2(M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}} \times \inf_{\substack{\nu \lrcorner \w = 0 \\ \Delta\w = 0}}
\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert d\w \rVert^2_{L^2(M)} + \lVert \delta\w \rVert^2_{L^2(M)}} 
\]

\[
\leq \inf_{\substack{\nu \lrcorner \w = 0 \\ \Delta\w = 0 \\ \w\perp_{L^2(\partial M)} H_A^p(M)}}
\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}}.
\]

Multiplying by $ q_1 $ and using $\Tilde{l}_1$ given in \eqref{eq:lTilde<l}, we obtain:

\[
q_1\sigma_1^2 \leq \inf_{\substack{\Delta\w = 0 }}
\frac{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}}{\lVert \w \rVert^2_{L^2(M)}} 
\times \inf_{\substack{\nu \lrcorner \w = 0 \\ \Delta\w = 0 \\ \w\perp_{L^2(\partial M)} H_A^p(M)}}
\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert \iota^*\w \rVert^2_{L^2(\partial M)}} 
\]

\[
\leq \inf_{\substack{\nu \lrcorner \w = 0 \\ \Delta\w = 0 \\ \w\perp_{L^2(\partial M)} H_A^p(M)}}
\frac{\lVert \nu\lrcorner d\w \rVert^2_{L^2(\partial M)}}{\lVert \w \rVert^2_{L^2(M)}} \leq \tilde{\textit{l}_1}=\textit{l}_1.
\]
Let us next show that the inequality is strict. We first show the following lemma: 
   \begin{lemma}
    If $ q_1\sigma_1^2 = \textit{l}_1 $, then there exists $ \w \in \Omega^p(M) $ eigenform associated to  both $ \textit{l}_1 $ and $ \sigma_1 $.
\end{lemma}

\begin{proof}
 Let $\w$ be an $\textit{l}_1$-eigenform for BSN3, in the same way as in the proof of  \lemref{lem:mu1sigma1<l1stricte}, we show that $ \w $ is also a $\sigma_1$-eigenform so it satisfies the following problems:
\[
\begin{cases}
\Delta^2 \w = 0 & \text{on } M \\
\nu \lrcorner \w = 0 & \text{on  } \partial M \\
\nu \lrcorner d \w = 0 & \text{on  } \partial M \\
\nu \lrcorner \Delta \w = 0 & \text{on  } \partial M \\
\nu \lrcorner d\Delta \w + \textit{l}\, \iota^* \w = 0 & \text{on  } \partial M
\end{cases}
\quad; \quad
\begin{cases}
\Delta \w = 0 & \text{on  } M \\
\nu \lrcorner d \w = -\sigma_1 \iota^* \w & \text{on  } \partial M \\
\nu \lrcorner \w = 0 & \text{on  } \partial M.
\end{cases}
\]
    \end{proof}
Let us finish the proof of  \thref{thm:proofQSigma<l}. In this case, $ \nu\lrcorner \w = 0 $ and $ \iota^*\w = 0 $, so $ \w_{|\partial M} = 0 $. Moreover, since $ \Delta\w = 0 $, we have $ \w = 0 $ on $ M $ according to \cite{ColetteAnne}. This leads to a contradiction, and the inequality is strict. Now, using  \lemref{lem:l<l<l}, we get $ q_1 \sigma_1^2 < \textit{l}_1 \leq \mathbf{l}_1 $.

\end{proof}
The following is a generalization of \cite[Inequality III]{Kuttler&Sigillito}.
\begin{thm}
    Let $(M^n, g)$ be a compact Riemannian manifold with smooth boundary $\partial M$. The following inequality holds between the eigenvalues of the Dirichlet, Neumann, BSD and BSN3 problems for differential forms:
    \begin{equation}\label{eq:mu1<lamba1+(q1l1)PourLaPreuve}
    \mu_1^{-1} < \lambda_1^{-1} + (q_1 \textit{l}_1)^{-\frac{1}{2}}.
    \end{equation}
\end{thm}
\begin{proof}
   Let $ \w_1 \in \Omega^p(M) $ such that $ \nu\lrcorner d\w_1 = 0 $, $ \nu\lrcorner \w_1 = 0 $, and $ \w_1 \perp_{L^2(\partial M)} H_A^p(M) $. Let $v\in \Omega^p(M)$ satisfy the following conditions:
\begin{equation*}
\begin{cases}
    \Delta v = \Delta\w_1 & \text{on}\ M \\
    v_{|\partial M} = 0,
\end{cases}
\end{equation*}and which has a solution due to  \thref{theo:thm5.4}. Let $u\in \Omega^p(M)$ such that $u=\w_1-v$, so we have $\Delta u=\Delta\w_1-\Delta v=0$. So we decompose $ \w_1 = u + v $ such that $ \Delta u = 0 $ and $ v_{|\partial M} = 0 $.
On the one hand, we have
\begin{equation*}
    \lVert u \rVert_{L^2( M)} \leq (q_1^{-1})^{\frac{1}{2}} \lVert u \rVert_{L^2(\partial M)}.
\end{equation*} Since $v_{|\partial M}=0,$ we get \begin{equation}\label{eq:q1u<q1w}
    \lVert u \rVert_{L^2( M)} \leq (q_1^{-1})^{\frac{1}{2}} \lVert \w_1 \rVert_{L^2(\partial M)}.
\end{equation}
On the other hand, by multiplying \eqref{eq:vpKDirichletForme} and \eqref{eq:vpKAlternativeDirichletForme} we get $\lVert v \rVert_{L^2(M)}\leq {\lambda_1^{-2}}\lVert \Delta v \rVert_{L^2(M)}.$ Now $\Delta v=\Delta\w_1$ as $\Delta u=0,$ so that \begin{equation}\label{eq:v<lambdaDeltaw}
    \lVert v \rVert_{L^2(M)}\leq {\lambda_1^{-1}}\lVert \Delta \w_1 \rVert_{L^2(M)}.
\end{equation}
Thus, using \eqref{eq:q1u<q1w} and \eqref{eq:v<lambdaDeltaw} we get
\begin{align}
    \lVert \w_1 \rVert_{L^2(M)} \nonumber &\leq \lVert u \rVert_{L^2(M)} + \lVert v \rVert_{L^2(M)} \\ \nonumber
    &\leq (q_1^{-1})^{\frac{1}{2}} \lVert \w_1 \rVert_{L^2(\partial M)} + (\lambda_1^{-1}) \lVert \Delta \w_1 \rVert_{L^2(M)} \\ \nonumber
    &\leq (q_1^{-1})^{\frac{1}{2}} (\textit{l}_1^{-1})^{\frac{1}{2}} \lVert \Delta \w_1 \rVert_{L^2(M)} + \lambda_1^{-1} \lVert \Delta \w_1 \rVert_{L^2(M)} \\
    &\label{eq:preuveIneg} \leq (\lambda_1^{-1} + q_1^{-\frac{1}{2}} \textit{l}_1^{-\frac{1}{2}})\lVert \Delta \w_1 \rVert_{L^2(M)}. 
\end{align}
Now let $ \w $ be a $\mu_1$-eigenform for the Neumann problem \eqref{eq:neumannFormesAbsolue}, so we have $\lVert \Delta\w\rVert_{L^2(M)}=\mu_1\lVert \w\rVert_{L^2(M)}$. We decompose $\w$ as follows, $\w=\w_0+\w_1$ such that $\w_0\in H_A^p(M)$ and $\w_1\perp_{L^2(\partial M)}\w_0$, then $\Delta\w=\Delta\w_1$. We perform an integration by parts \eqref{eq:IPP3'}, we obtain $(\Delta\w_1,\w_0)_{L^2(M)}=0.$ As we said before, $\Delta\w=\Delta\w_1,$ then $\Delta\w_1=\mu_1(\w_1+\w_0),$ so \[0=(\Delta\w_1,\w_0)_{L^2(M)}=\mu_1(\w_1,\w_0)_{L^2(M)}+\mu_1\lVert\w_0\rVert^2_{L^2(M)}.\] Hence we get $(\w_1,\w_0)_{L^2(M)}=-\lVert\w_0\rVert^2_{L^2(M)}.$ Using the calculations above, we have \begin{align}
    \lVert \w \rVert_{L^2(M)} \nonumber &= \lVert \w_0 \rVert_{L^2(M)} + \lVert \w_1 \rVert_{L^2(M)} + 2(\w_0, \w_1)_{L^2(M)} \\ \nonumber
    &= \lVert \w_0 \rVert_{L^2(M)} + \lVert \w_1 \rVert_{L^2(M)} - 2 \lVert \w_0 \rVert_{L^2(M)} \\ \nonumber
    &= \lVert \w_1 \rVert_{L^2(M)} - \lVert \w_0 \rVert_{L^2(M)}\\ 
    &\label{eq:preuveIneg2} \leq \lVert\w_1\rVert_{L^2(M)}.
\end{align}
Going back to \eqref{eq:preuveIneg} and using \eqref{eq:preuveIneg2} and that $\Delta\w=\Delta\w_1$, we get \[\lVert \w \rVert_{L^2(M)}\leq \lVert \w_1 \rVert_{L^2(M)}\leq \lVert \Delta \w_1 \rVert_{L^2(M)}[(q_1 \textit{l}_1)^{-\frac{1}{2}} + \lambda_1^{-1}] =\lVert \Delta \w \rVert_{L^2(M)}[(q_1 \textit{l}_1)^{-\frac{1}{2}} + \lambda_1^{-1}] .\]
Which implies finally that \[
\mu_1^{-1} \leq \lambda_1^{-1} + (q_1 \textit{l}_1)^{-\frac{1}{2}}
\] since $\lVert\Delta\w\rVert_{L^2(M)}=\mu_1\lVert\w\rVert_{L^2(M)}$. Let us now show that the inequality is strict. 
Then
\[
\lVert \w \rVert^2_{L^2(M)} = \left(\lVert u \rVert_{L^2(M)} + \lVert v \rVert_{L^2(M)} \right)^2,
\]
so
\[
\lVert u \rVert^2_{L^2(M)} + \lVert v \rVert^2_{L^2(M)} + 2(u, v)_{L^2(M)} = \lVert u \rVert^2_{L^2(M)} + \lVert v \rVert^2_{L^2(M)} + 2 \lVert u \rVert_{L^2(M)} \lVert v \rVert_{L^2(M)},
\]
thus $ u $ and $ v $ are collinear, either $ v = ku $ or $u=kv$, where $ k \in \mathbb{R} $. However, $ \w $ is an $ \mu_1 $-eigenform, so it satisfies the following conditions:
\begin{equation*}
 \begin{cases}
    \Delta \w = \mu_1 \w & \text{on } M \\
   \nu\lrcorner \w = 0 & \text{on } \partial M \\
     \nu\lrcorner d\w = 0 & \text{on } \partial M,
\end{cases} 
\end{equation*}
thus $ k \Delta v = \Delta u = 0 $, contradiction. When $u=kv$ there are two cases: the first case is if $ k = 0 $, then $ u = 0 $, so $ \w_{|\partial M} = 0 $ and $ \w $ is then associated to $ \lambda_1 $, which implies $ \mu_1 = \lambda_1 $, hence $ (\underbrace{\textit{l}_1 q_1}_{>0})^{-1} = 0 $, a contradiction. The second case is if $ k \neq 0 $, then $ \Delta v = 0 $, so $ \Delta \w = 0 $, and hence $ \w = 0 $, a contradiction. Therefore, the inequality \eqref{eq:mu1<lamba1+(q1l1)PourLaPreuve} is strict. 
\end{proof}






The following is a generalization of \cite[Inequality IV]{Kuttler&Sigillito}.
\begin{thm}\label{thm:dernierInegaliteIntroPourLaPreuve}
    Let $(M^n, g)$ be a compact Riemannian manifold with smooth boundary $\partial M$. The following inequality holds between the eigenvalues of the Dirichlet, Neumann, Steklov, and BSD problems for differential forms:
    \begin{equation}\label{eq:mu1<lamba1+(q1sigma1)PourLaPreuve}
    \mu_1^{-1} < \lambda_1^{-1} + (q_1 \sigma_1)^{-1}.
    \end{equation}
\end{thm}

\begin{proof}
   Using the inequality \eqref{eq:q1sigma1<l1PourLaPreuve}, we have 
\[
\sigma_1 \leq \textit{l}_1^{\frac{1}{2}} q_1^{-\frac{1}{2}}
\]
and by multiplying then by $ q_1 $, we obtain 
\[
q_1 \sigma_1 \leq \textit{l}_1^{\frac{1}{2}} q_1^{\frac{1}{2}}.
\]
Finally, by inserting the previous inequality into \eqref{eq:mu1<lamba1+(q1l1)PourLaPreuve}, we get
\[
\mu_1^{-1} \leq \lambda_1^{-1} + (q_1 \sigma_1)^{-1}.
\] Since the two inequalities \eqref{eq:q1sigma1<l1PourLaPreuve} and \eqref{eq:mu1<lamba1+(q1l1)PourLaPreuve} are strict, the inequality \eqref{eq:mu1<lamba1+(q1sigma1)PourLaPreuve} is also strict.

\end{proof}

\appendix 

\section{List of all spaces}

In this Appendix we will list all the functional spaces we use throughout the paper.

\begin{itemize}
    \item  $H_A^p(M) = \left\{ \w \in \Omega^p(M) \mid d\w = 0 \text{ on } M, \ \delta\w = 0 \text{ on } M, \ \nu \lrcorner \w = 0 \text{ on } \partial M \right\}.$
     \item $ L^k(M) = \left\{ \w\in\Gamma(E) \ \middle| \ \int_M \lvert \w \rvert^k \, d\mu_g < +\infty \right\} / \left\{ \w\in\Gamma(E) \ \middle| \  \w=0\ \text{a.e} \right\} $.
    \item $\check{L}^2(M) := \left\{ \w \in L^2(M) \ | \ \forall \alpha \in H_A^p(M), \ \int_{M} \langle \alpha, \w \rangle \, d\mu_g = 0 \right\}.$
    \item $ W^{m,k}(M) = \left\{ \w \in L^k(M) \ \middle| \ \forall \ 1\leq j\leq m, \nabla^j\w \in L^k(M;E^{(j)}) \right\} $,$\text{where $E^{(j)}=(TM)^{\otimes j}\otimes E$}$.

    \item $ H^m(M) = W^{m,2}(M)$.


    \item $ H^1_0(M) = \left\{ \w \in H^1(M) \ \middle| \ \ \w_{|\partial M} = 0 \right\} $.


    \item $ H^2_0(M) = \left\{ \w \in H^2(M) \ \middle| \ \w_{|\partial M} = 0 \ \text{and} \ (\nabla \w)_{|\partial M} = 0 \right\} $.

    \item  $\mathcal{M}^+_{A,v} := \{\text{bounded solutions } y=y(t) \text{ on } \mathbb{R}_+ \text{ of the ODE } \sigma_{A}(-iv+\partial_t\nu^\flat)y=0\}.$

    \item $ \Xi^s(M) := \{u \mid \rho^{j} \nabla^ju \in L^2(M), \ \forall\ 0\leq j\leq s\},$ for $ s=0,1,\cdots$

    \item $\mathcal{N} := \{u \in \Gamma(E) \mid Au = 0, B_1u = 0, \dots, B_{k}u = 0\}$.
    \item $\mathcal{N}^* := \{u \in \Gamma(E) \mid A^*u = 0, C_1u = 0, \dots, C_{k}u = 0\}$.


    \item $\mathcal{A}:=\{\w\in H^2(M)\ | \ \nu\lrcorner\w=0,\ \Delta\w=0\}$.

 \item $H_N^1(M):=\{\w\in H^1(M)\ | \ \nu\lrcorner\w=0\}$.
    \item $\check{H}_N^1(M):=\{\w\in H^1(M)\ | \ \nu\lrcorner \w=0,\ \w\perp_{L^2(\partial M)}H_A^p(M)\}$.
    \item $   H^2_{N,1}(M) := \{ \w \in H^2(M) \ |\ \nu \lrcorner d\w =0\ \text{and}\ \nu \lrcorner \w = 0 \ \text{on} \ \partial M \}.$
\item $\check{H}_{N,1}^2(M) := \left\{ \w \in H^2_{N,1}(M) \ | \ \w\perp_{L^2(\partial M)}H_A^p(M)\right\}.$
\item ${H}_{N,2}^2(M) := \{\w \in H^2(M)\ |\ \nu\lrcorner d\w = 0,\ \nu\lrcorner \w =0\ \text{and}\ \iota^*\delta\w = 0\ \text{on} \ \partial M \}.$
\item $ \check{H}_{N,2}^2(M) := \{\w \in H^2(M)\ |\ \nu\lrcorner d\w = 0,\ \nu\lrcorner \w =0,\ \iota^*\delta\w = 0\ \text{on} \ \partial M \ \text{and}\ \w \perp_{L^2(\partial M)} H_A^p(M)\}.$

\item ${H}_{N,3}^2(M) := \{\w \in H^2(M) \ | \ \nu\lrcorner\w = 0, \ \nu\lrcorner d\w = 0, \ \text{and} \ \nu\lrcorner\Delta\w = 0 \ \text{on} \ \partial M\}.$
    \item $\check{H}_{N,3}^2(M):=\{\w\in H^2(M)\ |\ \nu\lrcorner d\w=0,\ \nu\lrcorner \w=0,\ \nu\lrcorner\Delta\w=0\ \text{on} \ \partial M\ \text{and}\ \w\perp_{L^2(\partial M)}H_A^p(M)\}.$


\item $Z_1 := \left\{ \w \in \Omega^p(M)\cap H_{N,1}^2(M) \mid \Delta^2 \w = 0 \ \text{on} \ M \right\}\subset H_{N,1}^2(M).$
\item $\check{Z}_1 := \{ \w \in Z_1 \mid \w\perp_{L^2(\partial M)}H_A^p(M)\}=Z_1\cap\check{H}_{N,1}^2(M).$
\item $Z_2 := \{\w \in \Omega^p(M)\cap H_{N,2}^2(M) \ | \ \Delta^2\w = 0 \ \text{on}\  M \}\subset Z_1\subset H^2_{N,1}(M).$
\item $\check{Z}_2 := \{\w \in Z_2 \ | \ \w \perp_{L^2(\partial M)} H_A^p(M)\}=Z_2\cap\check{H}_{N,1}^2(M)=Z_2\cap \check{Z}_1.$
\item $Z_3 := \{\w \in \Omega^p(M)\cap H_{N,3}^2(M) |\ \Delta^2\w = 0 \ \text{on}\ M\}.$
\item $\check{Z}_3 := \{\w \in Z_3\ |\ \w \perp_{L^2(\partial M)} H_A^p(M)\}.$
    \item $ V_1=\{\w\in \check{H}^2_{N,1}(M)\ |\ \Delta^2 \w=0\ \text{weakly in}\ M\}.$
\item $\mathcal{H} := \{ \w \in \Omega^p(M) \ |\ \nu \lrcorner \w = 0, \nu \lrcorner d\w = 0, \iota^* \w = 0 \text{ and } \iota^* \delta \w = 0 \text{ on } \partial M \}.$
\item $\mathbb{S} = \{ (\w_1,\w_2) \in L^2(\partial M) \oplus {H_A^p(M)}^{\perp_{L^2(\partial M)}} \ | \ \lVert \w_1 \rVert^2_{L^2(\partial M)} + \lVert \w_2 \rVert^2_{L^2(\partial M)} = 1 \}.$



\end{itemize}

