% $H_{new} = \mathcal{C}^S(H_n,\varepsilon^S_n,H_{n-1},\varepsilon^S_{n-1},\ldots,P)$ and 
% $h_{new} = \mathcal{C}^F(h_{n,m},\varepsilon^F_{n,m},h_{n,m-1},\varepsilon^F_{n,m-1},\ldots,p)$,
